window.MAPDATA={"name":"overland","width":8192,"height":8192,"images":["https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-Overland-v1-0256.jpg","https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-Overland-v1-0512.jpg","https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-Overland-v1-1024.jpg","https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-Overland-v1-2048.jpg","https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-Overland-v1-4096.jpg","https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-Overland-v1-8192.jpg"],"layers":[{"label":"Locations","group":"Locations","icon":null},{"label":"Sites of Grace","group":"Locations","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"label":"Locations","group":"Locations","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit-turtle.png?h=40"},{"label":"Summoning Pools","group":"Locations","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"label":"Waygates","group":"Locations","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"label":"Spiritsprings","group":"Locations","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"label":"Maps","group":"Locations","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"label":"Equipment","group":"Equipment","icon":null},{"label":"Weapons","group":"Equipment","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"label":"Armor","group":"Equipment","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"label":"Shields","group":"Equipment","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"label":"Ashes of War","group":"Equipment","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"label":"Spells","group":"Equipment","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"label":"Talismans","group":"Equipment","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"label":"Spirit Ashes","group":"Equipment","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"label":"Items","group":"Items","icon":null},{"label":"Flask Upgrades","group":"Items","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"label":"Upgrade Materials","group":"Items","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"label":"Crafting Materials","group":"Items","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"label":"Consumables","group":"Items","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"label":"Key Items","group":"Items","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"label":"Remembrances","group":"Items","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"label":"Characters","group":"Characters","icon":null},{"label":"Bosses","group":"Characters","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"label":"NPCs","group":"Characters","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"label":"NPC Invaders","group":"Characters","icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"}],"markers":[{"id":"5351","x":0.574263376,"y":0.135389804,"cat":"Spirit Ashes","group":"Equipment","title":"Haligtree Soldier Ashes","desc":"Spirit Ashes. Found under a large decorative chalice in the northern edge of the main city proper.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"5407","x":0.584375191,"y":0.136000213,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [9] - Elphael, Brace of the Haligtree","desc":"Spirit Ash Upgrade Material. Found on a grave in the western section of the graveyard in the northwest of the building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5406","x":0.583398937,"y":0.136396974,"cat":"Key Items","group":"Items","title":"Ghost-Glovewort Picker's Bell Bearing [3]","desc":"Key Item. Found on a corpse in the western section of the graveyard in the northeast of the city.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"5405","x":0.582148245,"y":0.136799842,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [7] - Elphael, Brace of the Haligtree","desc":"Spirit Ash Upgrade Material. Found on a grave in the western section of the graveyard northeast of the city.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5402","x":0.585900731,"y":0.136824258,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [7] - Elphael, Brace of the Haligtree","desc":"Spirit Ash Upgrade Material. Found in a cluster of graves far to the northeast.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5308","x":0.57546539,"y":0.137605576,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - Elphael, Brace of the Haligtree","desc":"Upgrade Material. Found on a corpse in between two ballistae in the north of the city.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5352","x":0.573725634,"y":0.137629993,"cat":"Armor","group":"Equipment","title":"Haligtree Knight Helm","desc":"Helmet. Found on a corpse in an upper level room next to the Elphael Inner Wall site of grace. There is a ladder adjacent to the grace which leads to the room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"4829","x":0.579322404,"y":0.137947403,"cat":"Consumables","group":"Items","title":"Spiritflame Arrow - 15x Elphael, Brace of the Haligtree","desc":"Ammunition. 15x found on a corpse sitting on a chair inside a building in the northeast. This building can be reached by following the eastern walkway all the way to the northeast and walking along a concrete beam connecting to the building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5354","x":0.571468044,"y":0.137965717,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] - Elphael, Brace of the Haligtree","desc":"Upgrade Material. Found on a corpse by the wall directly north of the Elphael Inner Wall site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4827","x":0.581727111,"y":0.138142733,"cat":"Consumables","group":"Items","title":"Warming Stone - Elphael, Brace of the Haligtree","desc":"Consumable. 2 are found on a corpse sitting by a desk inside a building in the northeast. This building can be reached by following the eastern walkway all the way to the northeast and walking along a concrete beam connecting to the building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5403","x":0.583795679,"y":0.138295332,"cat":"Consumables","group":"Items","title":"Numen's Rune - Elphael, Brace of the Haligtree","desc":"Rune Consumable. Found on a corpse in the southwest end of the graveyard in the northwest of the city.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5404","x":0.584161772,"y":0.139619913,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [8] - Elphael, Brace of the Haligtree","desc":"Spirit Ash Upgrade Material. Found on a grave in the southwest end of the graveyard in the northeast of the city.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"3360","x":0.572352936,"y":0.14021811,"cat":"Sites of Grace","group":"Locations","title":"Elphael Inner Wall","desc":"Site of Grace found within <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Elphael,+Brace+of+the+Haligtree'>Elphael, Brace of the Haligtree</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5306","x":0.578120882,"y":0.14066981,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - Elphael, Brace of the Haligtree","desc":"Upgrade Material. Found on a corpse under a tree at the bottom level in the north of the city.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5355","x":0.575105144,"y":0.140767475,"cat":"Weapons","group":"Equipment","title":"Rotten Crystal Sword","desc":"<a href='https://eldenring.wiki.fextralife.com/Straight+Swords' target=\"_blank\">Straight Sword</a>. Found in a chest guarded by 3 <a href='https://eldenring.wiki.fextralife.com/Crystalians' target=\"_blank\">Crystalians</a>. From the Elphael Inner Wall site of grace, head down the steps and jump over the rubble on the left. You can engage the Crystalians one by one by luring them to the hallway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"8231","x":0.57343083,"y":0.141260682,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Elphael, Brace of the Haligtree (Inner Wall)","desc":"Summoning Pool Effigy found next to the Elphael Inner Wall site of grace in Elphael, Brace of the Haligtree. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3363","x":0.588489426,"y":0.141927264,"cat":"Talismans","group":"Equipment","title":"Dragoncrest Greatshield Talisman","desc":"Talisman. Found in a chest on an elevated platform inside the large building in the northeast, guarded by several Pests. This platform can be reached by heading through the eastern exit from the Drainage Channel site of grace and then navigating across the branches and concrete beams to reach the roof of the building. While there are many branches and beams to traverse, the path is fairly linear. Once on the roof, drop through one of the holes onto the wooden beams below and then carefully make your way onto the platform after killing the Pests from range.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"8299","x":0.580669441,"y":0.142415568,"cat":"Upgrade Materials","group":"Items","title":"Somber Ancient Dragon Smithing Stone - 1x Elphael, Brace of the Haligtree","desc":"<p>Located in<a class=\"wiki_link\" title=\"Elden Ring Elphael, Brace of the Haligtree\" href='https://eldenring.wiki.fextralife.com/Elphael,+Brace+of+the+Haligtree'> Elphael, Brace of the Haligtree</a>. Found in a chest hidden between columns near a roof with a corpse carrying an item, after the Prayer Room site of Grace in the Haligtree.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8846","x":0.57977389,"y":0.142901451,"cat":"Key Items","group":"Items","title":"Seedbed Curse - Elphael, Brace of the Haligtree A","desc":"<p>Key Item. Found on a body sitting in a chair looking down the ballistae and the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Putrid+Avatar' target=\"\">Putrid Avatar</a>&nbsp;within <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Elphael,+Brace+of+the+Haligtree' target=\"\">Elphael, Brace of the Haligtree</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4822","x":0.583429582,"y":0.143141952,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] - Elphael, Brace of the Haligtree","desc":"Upgrade Material. Found on a corpse in a large room with many braziers and two Cleanrot Knights.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5304","x":0.581842364,"y":0.143239613,"cat":"Consumables","group":"Items","title":"Pickled Turtle Neck - Elphael, Brace of the Haligtree","desc":"Consumable. Found on a corpse in a dark building in the northeast, guarded by 3 Crystalians. This room is in the bottom level of the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5365","x":0.583673646,"y":0.144497052,"cat":"Armor","group":"Equipment","title":"Traveler's Set","desc":"Armor Set comprised of <a href='https://eldenring.wiki.fextralife.com/Traveler's+Clothes' target=\"_blank\">Traveler's Clothes</a>, <a href='https://eldenring.wiki.fextralife.com/Traveler's+Manchettes' target=\"_blank\">Traveler's Manchettes</a> and <a href='https://eldenring.wiki.fextralife.com/Traveler's+Boots' target=\"_blank\">Traveler's Boots</a>. All three pieces are found deep underground in a side room with a large orange flower, adjacent to the Haligtree Roots site of grace. This area can be reached by taking the lift from the large building in the northeast.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"4823","x":0.584893966,"y":0.144710691,"cat":"Consumables","group":"Items","title":"Golden Rune [10] - Elphael, Brace of the Haligtree","desc":"Rune Consumable. Found on a corpse leaning over the balcony of the room with many braziers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5302","x":0.581085767,"y":0.144747316,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9] - Elphael, Brace of the Haligtree","desc":"Upgrade Material. Found on a corpse in a dark building in the northeast guarded by 3 Crystalians. This building is in the bottom level of the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4951","x":0.586712241,"y":0.14478394,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9] - Elphael, Brace of the Haligtree","desc":"Upgrade Material. Found on a corpse inside a room at the northern end of the ring walkway in the east. Guarded by a <a href='https://eldenring.wiki.fextralife.com/Crystalians' target=\"_blank\">Crystalian</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4457","x":0.5831329,"y":0.145675131,"cat":"Sites of Grace","group":"Locations","title":"Haligtree Roots","desc":"Found underground after taking the lift from the large building in the northeast.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8233","x":0.581897511,"y":0.146114623,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Elphael, Brace of the Haligtree (Haligtree Roots)","desc":"Summoning Pool Effigy found just before Malenia's Boss Arena in Elphael, Brace of the Haligtree. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5958","x":0.57937698,"y":0.146139039,"cat":"Spirit Ashes","group":"Equipment","title":"Cleanrot Knight Finlay Ashes","desc":"Located in a chest protected by a knight in <a href='https://eldenring.wiki.fextralife.com/Elphael,+Brace+of+the+Haligtree' target=\"_blank\">Elphael, Brace of the Haligtree</a>. From the Prayer Room site of grace, head straight down a few sets of stairs until you reach a small landing where two crossbow guards are stationed above. Jump over the railing on the landing onto the angled brace, then jump onto the platform with the gazebo. The ashes are in a chest in a room next to the gazebo.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"5356","x":0.56810728,"y":0.14647476,"cat":"Consumables","group":"Items","title":"Hero's Rune [5] - Elphael, Brace of the Haligtree","desc":"Rune Consumable. Found on a corpse behind a large decorative chalice at the end of the hallway after the Elphael Inner Wall site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4821","x":0.584832949,"y":0.14649918,"cat":"Consumables","group":"Items","title":"Immunizing White Cured Meat - Elphael, Brace of the Haligtree","desc":"Consumable. Found on a corpse at the end of the eastern walkway, on the bottom level.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6051","x":0.581495148,"y":0.147652844,"cat":"Bosses","group":"Characters","title":"Malenia, Blade of Miquella","desc":"Demigod. Found past a fog door southwest of the Haligtree Roots Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mainboss.png?h=40"},{"id":"6052","x":0.578516816,"y":0.148019087,"cat":"Key Items","group":"Items","title":"Malenia's Great Rune","desc":"Great Rune. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Malenia+Blade+of+Miquella'>Malenia, Blade of Miquella</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4825","x":0.584619394,"y":0.148067919,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - Elphael, Brace of the Haligtree","desc":"Upgrade Material. Found on a corpse on a balcony. You can reach this corpse by going into the building on the left and heading up the stairs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4459","x":0.575347501,"y":0.148244935,"cat":"Locations","group":"Locations","title":"Elphael, Brace of the Haligtree","desc":"Legacy Dungeon. Accessed through Miquella's Haligtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-location_52.png?h=40"},{"id":"4830","x":0.588285652,"y":0.148598974,"cat":"Weapons","group":"Equipment","title":"Rotten Staff","desc":"<a href='https://eldenring.wiki.fextralife.com/Colossal+Weapons' target=\"_blank\">Colossal Weapon</a>. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Erdtree+Avatar' target=\"_blank\">Erdtree Avatar</a> patrolling the ring walkway in the east.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossal_weapon.png?h=40"},{"id":"4826","x":0.586352249,"y":0.149343668,"cat":"Weapons","group":"Equipment","title":"Miquellan Knight's Sword","desc":"<a href='https://eldenring.wiki.fextralife.com/Straight+Swords' target=\"_blank\">Straight Sword</a>. Found atop a belltower. You can reach this belltower by entering the second alcove on the left of the eastern walkway, heading up the stairs and then jumping onto the tree branch on the balcony. Follow the tree branch up and across to reach the tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"5964","x":0.572417327,"y":0.149679389,"cat":"Sites of Grace","group":"Locations","title":"Malenia, Goddess of Rot","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6053","x":0.578646439,"y":0.149972383,"cat":"Remembrances","group":"Items","title":"Remembrance of the Rot Goddess","desc":"Key Item. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Malenia+Blade+of+Miquella'>Malenia, Blade of Miquella</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4817","x":0.583988896,"y":0.150009007,"cat":"Consumables","group":"Items","title":"Golden Rune [13] - Elphael, Brace of the Haligtree","desc":"Rune Consumable. Found in a small room along with Haligtree Knights sitting on chairs. This room is found along the walkway after the Prayer Room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4851","x":0.588651749,"y":0.150527854,"cat":"Consumables","group":"Items","title":"Numen's Rune - Elphael, Brace of the Haligtree","desc":"Rune Consumable. Found on a corpse at the edge of a broken section of the ring walkway in the east.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5361","x":0.582097399,"y":0.150564478,"cat":"Consumables","group":"Items","title":"Golden Rune [10] - Elphael, Brace of the Haligtree","desc":"Consumable. Found on a corpse in a small alcove along the inner wall. Note that this is found after traversing the lake of rot, after passing the Elphael Inner Wall site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3361","x":0.586501635,"y":0.150997863,"cat":"Sites of Grace","group":"Locations","title":"Drainage Channel","desc":"Site of Grace found in the drainage channels of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Elphael,+Brace+of+the+Haligtree'>Elphael, Brace of the Haligtree</a>. This area is accessed by dropping down a ladder found inside an alcove along the inner walls. This requires you to traverse the first lake of rot found after the Elphael Inner Wall site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5408","x":0.591526268,"y":0.151034488,"cat":"Consumables","group":"Items","title":"Hero's Rune [5] - Elphael, Brace of the Haligtree","desc":"Rune Consumable. Found on a corpse under a large tree in the eastern graveyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4819","x":0.584802976,"y":0.151089423,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] - Elphael, Brace of the Haligtree","desc":"Upgrade Material. Found on a corpse inside a wine cellar/storage room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8232","x":0.585868766,"y":0.152407897,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Elphael, Brace of the Haligtree (Drainage Channel)","desc":"Summoning Pool Effigy found next to the Drainage Channel site of grace in Elphael, Brace of the Haligtree. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"8708","x":0.579377996,"y":0.152578822,"cat":"Talismans","group":"Equipment","title":"Rotten Winged Sword Insignia","desc":"Earned after choosing to assist <a href='https://eldenring.wiki.fextralife.com/Millicent' target=\"_blank\">Millicent</a> and successfully defeat her sisters.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"8847","x":0.576874893,"y":0.153799621,"cat":"NPCs","group":"Characters","title":"Millicent (Final Location)","desc":"<p style=\"text-align: left;\">NPC. Millicent will be available at the Prayer Room Grace at��<a class=\"wiki_link\" title=\"Elden Ring Elphael Brace of the Haligtree\" href='https://eldenring.wiki.fextralife.com/Elphael+Brace+of+the+Haligtree'>Elphael Brace of the Haligtree</a>. She will not move from this spot until the player has defeated a��<a class=\"wiki_link\" title=\"Elden Ring Ulcerated Tree Spirit\" href='https://eldenring.wiki.fextralife.com/Ulcerated+Tree+Spirit'>Ulcerated Tree Spirit</a>��mini-boss just before the Drainage Channel Grace. Go up the slope, up the stairs, up the hill, and then across the branch to reach the boss arena.��</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"5917","x":0.588741665,"y":0.154226662,"cat":"Talismans","group":"Equipment","title":"Millicent's Prosthesis","desc":"When you are given the choice between assisting Millicent and challenging her, choose to challenge her. When you kill her, you will automatically receive this talisman.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"5001","x":0.585497678,"y":0.15448938,"cat":"Consumables","group":"Items","title":"Golden Rune [12] - Elphael, Brace of the Haligtree","desc":"Rune Consumable. Found on a corpse next to an Imp Statue seal in the lower levels.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8230","x":0.582031305,"y":0.154709126,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Elphael, Brace of the Haligtree (Prayer Room)","desc":"Summoning Pool Effigy found next to the Prayer Room site of grace in Elphael, Brace of the Haligtree. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5364","x":0.577668943,"y":0.154989913,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Elphael, Brace of the Haligtree","desc":"Flask Upgrade Material. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Ulcerated+Tree+Spirit' target=\"_blank\">Ulcerated Tree Spirit</a> lurking beneath the second lake of rot, past a second set of branches within the inner walls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"5363","x":0.575899713,"y":0.155185246,"cat":"Upgrade Materials","group":"Items","title":"Great Grave Glovewort - Elphael, Brace of the Haligtree","desc":"Spirit Ash Upgrade Material. Found in the center of the second lake of rot, past a second set of branches inside the inner walls. Beware the <a href='https://eldenring.wiki.fextralife.com/Ulcerated+Tree+Spirit' target=\"_blank\">Ulcerated Tree Spirit</a> lurking beneath.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"4820","x":0.583851126,"y":0.155215761,"cat":"Spells","group":"Equipment","title":"Triple Rings of Light","desc":"<a href='https://eldenring.wiki.fextralife.com/Incantations' target=\"_blank\">Incantation</a>. Found in a chest locked behind an Imp Statue barrier. Requires 2 <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Keys</a> to unlock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"4456","x":0.582507968,"y":0.156066667,"cat":"Sites of Grace","group":"Locations","title":"Prayer Room","desc":"Can be easily found at the entrance of the church a few metters away after go just enter Elphael, <a href='https://eldenring.wiki.fextralife.com/Brace+of+the+Haligtree'>Brace of the Haligtree<a/>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4901","x":0.586022761,"y":0.156314494,"cat":"Upgrade Materials","group":"Items","title":"Somber Ancient Dragon Smithing Stone - Elphael, Brace of the Haligtree","desc":"Upgrade Material. Found on a corpse in the southern end of the ring walkway in the east.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3364","x":0.584277361,"y":0.156686839,"cat":"Talismans","group":"Equipment","title":"Marika's Soreseal","desc":"<a href='https://eldenring.wiki.fextralife.com/Talismans' target=\"_blank\">Talisman</a>. Found on an altar in a room requiring 2 <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stonesword+Key'>Stonesword Keys</a> to unlock. This room is in the southeast, on the lower levels.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4812","x":0.585998885,"y":0.15852416,"cat":"Consumables","group":"Items","title":"Holy Grease - 3x Elphael, Brace of the Haligtree","desc":"Consumable. 3 are found on a corpse on the bridge towards the Prayer Room at the base of Elphael.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4661","x":0.589354981,"y":0.162131652,"cat":"Upgrade Materials","group":"Items","title":"Ancient Dragon Smithing Stone","desc":"Found in a chest, at the top of a tower, no traps or tricks.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4612","x":0.576447189,"y":0.16554992,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8]","desc":"Upgrade Material. Found on a corpse draped over the balcony of a building in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4610","x":0.577972914,"y":0.167381135,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8]","desc":"Upgrade Material. Found on a corpse inside a building in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a>. Be careful of the Misbegotten just around the corner.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4618","x":0.57540967,"y":0.167808419,"cat":"Upgrade Materials","group":"Items","title":"Ancient Dragon Smithing Stone","desc":"Upgrade Material. Found on a corpse in front of a statue in in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a>. Guarded by an axe-wielding Misbegotten.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"9842","x":0.576202825,"y":0.168846108,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Haligtree Town Plaza","desc":"Summoning Pool Effigy next to the Haligtree Town Plaza Site of Grace. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4455","x":0.590120116,"y":0.16915131,"cat":"Sites of Grace","group":"Locations","title":"Haligtree Promenade","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4454","x":0.577148988,"y":0.169273391,"cat":"Sites of Grace","group":"Locations","title":"Haligtree Town Plaza","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5724","x":0.579345909,"y":0.169273391,"cat":"Talismans","group":"Equipment","title":"Viridian Amber Medallion +2","desc":"The closest site of grace is the Haligtree Town Plaza. Run to the roof with the Summoning Snail, jump to the building on the right (it's lower), immediately turn around and jump inside the building. There will be a chest with the medallion and some mushroom people","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4616","x":0.574341688,"y":0.170280558,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9]","desc":"Upgrade Material. Found on a corpse inside a small building in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"6882","x":0.580810863,"y":0.171074084,"cat":"Talismans","group":"Equipment","title":"Pearldrake Talisman +2","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Talismans'>Talisman</a>. Down the steps and up the ladder from the Haligtree Town Site of Grace, there is a Rot Grease. The platform behind that has the Pearldrake Talisman.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4453","x":0.581971299,"y":0.172142295,"cat":"Sites of Grace","group":"Locations","title":"Haligtree Town","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6529","x":0.586737519,"y":0.172175403,"cat":"Spirit Ashes","group":"Equipment","title":"Oracle Envoy Ashes","desc":"Miquella's Haligtree near Haligtree Town site of grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"4619","x":0.575348664,"y":0.172325416,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6]","desc":"Upgrade Material. Found on a corpse on the roof of a small building in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4630","x":0.591185668,"y":0.174034551,"cat":"Weapons","group":"Equipment","title":"Loretta's War Sickle","desc":"Halberd. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Loretta,+Knight+of+the+Haligtree'>Loretta, Knight of the Haligtree</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-halberd.png?h=40"},{"id":"8229","x":0.581606499,"y":0.174034551,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Miquella's Haligtree (Haligtree Town)","desc":"Summoning Pool Effigy found next to the Haligtree Town site of grace in Miquella's Haligtree. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4622","x":0.576416681,"y":0.174126109,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6]","desc":"Upgrade Material. Found on a corpse on a platform in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a> filled with scarlet rot zombies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4624","x":0.589507073,"y":0.175102758,"cat":"Bosses","group":"Characters","title":"Loretta, Knight of the Haligtree","desc":"Great Enemy. Found in the large courtyard of a temple in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"4629","x":0.591033626,"y":0.176079406,"cat":"Spells","group":"Equipment","title":"Loretta's Mastery","desc":"Sorcery. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Loretta,+Knight+of+the+Haligtree'>Loretta, Knight of the Haligtree</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"4609","x":0.580780679,"y":0.17662877,"cat":"Ashes of War","group":"Equipment","title":"Lost Ashes of War - Miquella's Haligtree","desc":"Ash of War Upgrade. Found on a corpse slumped over in front of a statue in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a> canopy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"4628","x":0.586364556,"y":0.177117094,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - 4x Consecrated Snowfield","desc":"Upgrade Material. Found on a corpse laying inside a gazebo connecting 3 bridges in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a>. This area is guarded by two sorcerers. -Another one can be found on the river, south to the Minor Erdtree. On a statue. Need to be broken by an enemy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4626","x":0.584808104,"y":0.177147616,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7]","desc":"Upgrade Material. Found on a corpse in front of a gazebo connecting 3 bridges in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a>. This area is guarded by two sorcerers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4451","x":0.580475982,"y":0.188836871,"cat":"Locations","group":"Locations","title":"Miquella's Haligtree","desc":"Legacy Dungeon. North from the Consecrated Snowfield. Miquella's Haligtree is accessed by doing the Evergaol puzzle located at <a href='https://eldenring.wiki.fextralife.com/Ordina+Liturgical+Town' target=\"_blank\">Ordina, Liturgical Town</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-location_44.png?h=40"},{"id":"4608","x":0.582758839,"y":0.189801304,"cat":"Key Items","group":"Items","title":"Stonesword Key - Miquella's Haligtree (B)","desc":"Key Item. Found on a corpse lying at the tip of a branch in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a> canopy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4458","x":0.574189423,"y":0.192682423,"cat":"Sites of Grace","group":"Locations","title":"Haligtree Canopy","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6663","x":0.579723856,"y":0.192774611,"cat":"Key Items","group":"Items","title":"Prattling Pate (My Beloved)","desc":"Pratting Pate \"<em>My beloved</em>\" can be found on <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/miquella's+haligtree'>Miquella's Haligtree</a>, shortly after taking the way gate from Ordina, Liturgical Town. It is two branches down from where you are transported to.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"12358","x":0.57368583,"y":0.19375129,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud - 3x Haligtree Canopy","desc":"Material. Found near the Haligtree Canopy Site of Grace, guarded by an <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Oracle+Envoy' target=\"\">Oracle Envoy</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"4607","x":0.572270175,"y":0.194263374,"cat":"Key Items","group":"Items","title":"Stonesword Key - Miquella's Haligtree (A)","desc":"Key Item. Found on a corpse lying at the tip of a branch in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree'>Miquella's Haligtree</a> canopy right behind you when you enter the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"12359","x":0.578202526,"y":0.194804238,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - Miquella's Haligtree","desc":"<p>Upgrade Material. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree' target=\"blank\">Miquella's Haligtree</a>, looted from a corpse after two patrolling <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Oracle+Envoy' target=\"blank\">Oracle Envoy</a> enemies.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"12360","x":0.580220763,"y":0.194944895,"cat":"Consumables","group":"Items","title":"Dappled Cured Meat - Miquella's Haligtree","desc":"<p>Consumable. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Miquella's+Haligtree' target=\"blank\">Miquella's Haligtree</a>, looted from a corpse after two patrolling <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Oracle+Envoy' target=\"blank\">Oracle Envoy</a> enemies.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6067","x":0.582032249,"y":0.197107862,"cat":"Armor","group":"Equipment","title":"Envoy Crown","desc":"Helmet. Looted from the very edge of the branches.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"7802","x":0.531074168,"y":0.224301406,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9]","desc":"<a href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"_blank\">Consecrated Snowfield</a>: Found on a corpse sitting on a chair overlooking the edge east of the <a href='https://eldenring.wiki.fextralife.com/Apostate+Derelict' target=\"_blank\">Apostate Derelict</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3826","x":0.620817695,"y":0.224667649,"cat":"Key Items","group":"Items","title":"Haligtree Secret Medallion (Left)","desc":"Key Item. Found in the castle's northeast tower after defeating <a href='https://eldenring.wiki.fextralife.com/Commander+Niall' target=\"_blank\">Commander Niall</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2992","x":0.517432273,"y":0.225644297,"cat":"Shields","group":"Equipment","title":"Silver Mirrorshield","desc":"Shield found in the Apostate Derelict church.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"4648","x":0.530830007,"y":0.226315742,"cat":"Consumables","group":"Items","title":"Golden Rune [12]","desc":"Found on a body at the edge of the cliffs in the Consecrated Snowfield. There is a jumping path up from here to the Apostate Derelict in the West.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2991","x":0.523379857,"y":0.227719674,"cat":"Sites of Grace","group":"Locations","title":"Apostate Derelict","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2990","x":0.521522352,"y":0.228330079,"cat":"Locations","group":"Locations","title":"Apostate Derelict","desc":"A ruined church lying in the frozen north-west of the Consecrated Grounds","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"3820","x":0.622952115,"y":0.228726844,"cat":"Weapons","group":"Equipment","title":"Veteran's Prosthesis","desc":"Fist Weapon. Dropped by <a href='https://eldenring.wiki.fextralife.com/Commander+Niall' target=\"_blank\">Commander Niall</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fist.png?h=40"},{"id":"6619","x":0.615535968,"y":0.230130776,"cat":"Key Items","group":"Items","title":"Stonesword Key - Castle Sol","desc":"<strong>Stonesword Key</strong> held by a corpse located on the rooftop in the northern section.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3807","x":0.621000163,"y":0.230252857,"cat":"Bosses","group":"Characters","title":"Commander Niall","desc":"Great Enemy. Found in the northeast of the castle, accessible by using the eastern exit of the church and going through the building there.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3824","x":0.619236292,"y":0.230313897,"cat":"Sites of Grace","group":"Locations","title":"Castle Sol Rooftop","desc":"Site of Grace found in <a href='https://eldenring.wiki.fextralife.com/Commander+Niall' target=\"_blank\">Commander Niall</a>'s arena after defeating him.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3758","x":0.614804087,"y":0.23327436,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly - Castle Sol","desc":"Crafting Material. Found on a corpse in a room filled with skeletal slimes in the northwest section of the castle, by a ladder.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6363","x":0.521583119,"y":0.234189968,"cat":"Locations","group":"Locations","title":"Walking Mausoleum (Consecrated Snowfield)","desc":"A <a href='https://eldenring.wiki.fextralife.com/Walking+Mausoleum' target=\"_blank\">Walking Mausoleum</a> found near the <a href='https://eldenring.wiki.fextralife.com/Apostate+Derelict' target=\"_blank\">Apostate Derelict</a>. This one fires magical artillery into the air, raining havoc down in the surrounding areas. Subdue it to stop the bombardment.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-walking-mausoleum.png?h=40"},{"id":"3761","x":0.619808761,"y":0.234464652,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy I","desc":"Multiplayer Item. Found under a wooden walkway in the eastern section of the castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"6210","x":0.532746002,"y":0.235136098,"cat":"Bosses","group":"Characters","title":"Death Rite Bird (Consecrated Snowfield)","desc":"Found at the head of the frozen river, just southeast of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/apostate+derelict'>Apostate Derelict</a> at night","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3759","x":0.616451424,"y":0.2354413,"cat":"Consumables","group":"Items","title":"Fan Daggers - 5x Castle Sol","desc":"Offensive Consumable Item. 5x can be found on a corpse at the eastern edge of the roof of the northwest building with a ladder.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8554","x":0.619076266,"y":0.235899102,"cat":"Consumables","group":"Items","title":"Golden Rune [10] C - Castle Sol","desc":"Rune Consumable. Found on a corpse on top of a building north of the church. Beware the spectral Exiles that appear as you approach.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3811","x":0.621090579,"y":0.236478989,"cat":"Consumables","group":"Items","title":"Golden Rune [9] - 1x Castle Sol","desc":"Rune Consumable. Found on a corpse in the middle level of the eastern section of the castle. Accessible via ladder outside the church's main entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3821","x":0.614833764,"y":0.23687575,"cat":"Key Items","group":"Items","title":"Sorcerer Painting","desc":"Key Info Item. Found inside the central building of the courtyard. This can be accessed through the roof by walking along the top of the northwest walls and finding a walkway connecting to the building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"15451","x":0.616115109,"y":0.237024544,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] - Church of the Eclipse Castle Sol","desc":"<p>Upgrade Material. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Castle+Sol' target=\"blank\">Castle Sol</a> next to the Church of the Eclipse Grace. Going outside the church (to the south) around the church and up the wall till you reach the church roof. You will have to platform onto the broken wall and hug the wall of the church to reach it. It will be on a corpse hanging off the edge. Killing the crossbowmen makes this easier to do.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3760","x":0.612544872,"y":0.237119912,"cat":"Consumables","group":"Items","title":"Golden Rune [10] B - Castle Sol","desc":"Rune Consumable. Found on a corpse sitting by the northwest corner of the wall, in the upper level. Access via ladder in a building nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8005","x":0.61687967,"y":0.237180953,"cat":"Weapons","group":"Equipment","title":"Stormhawk Axe","desc":"Found on an awning at the center of the Castle, that can be accessed by dropping from above.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-axe.png?h=40"},{"id":"8552","x":0.619320295,"y":0.237303034,"cat":"Consumables","group":"Items","title":"Thawfrost Boluses - 1x Castle Sol","desc":"Consumable. 1x found on a corpse hanging by a wall outside the Church.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6371","x":0.532807042,"y":0.23782188,"cat":"Spells","group":"Equipment","title":"Explosive Ghostflame","desc":"Drops from a <a href='https://eldenring.wiki.fextralife.com/Death+Rite+Bird' target=\"_blank\">Death Rite Bird</a> southeast <a href='https://eldenring.wiki.fextralife.com/Apostate+Derelict' target=\"_blank\">Apostate Derelict</a> (late game area). It's a clearing in the frozen river, and you must go there at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"3767","x":0.618099498,"y":0.238157601,"cat":"Consumables","group":"Items","title":"Thawfrost Boluses - 3x Castle Sol","desc":"Consumable. 3x found on a corpse in an area between two buildings accessed via the wooden walkways in the courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3769","x":0.620083564,"y":0.238188123,"cat":"Sites of Grace","group":"Locations","title":"Church of the Eclipse","desc":"Site of Grace found in the Church in the southeast corner of the castle. The church is accessed by heading up the wooden platform in the courtyard and following the path in the middle levels.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8551","x":0.616085666,"y":0.238340723,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] A - Castle Sol","desc":"Upgrade Material. Found on a corpse on top of the central building in the courtyard, accessible by walking along the top of the outer walls from the northwest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3805","x":0.623532173,"y":0.238462803,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] B - Castle Sol","desc":"Upgrade Material. Found on a corpse in the upper level of a building east of the church.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6401","x":0.601102468,"y":0.239500492,"cat":"Crafting Materials","group":"Items","title":"Fulgurbloom","desc":"One can be found on the outskirts of the <a href='https://eldenring.wiki.fextralife.com/Castle+Sol' target=\"_blank\">Castle Sol</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3763","x":0.617947378,"y":0.239988816,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - 1x Castle Sol","desc":"Upgrade Material. One found under the wooden platform directly opposite the main gate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3765","x":0.615413747,"y":0.239988816,"cat":"Consumables","group":"Items","title":"Freezing Grease - Castle Sol","desc":"Weapon Coating. Found on a corpse hanging at the edge of a wooden walkway in the courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3770","x":0.621213495,"y":0.2402635,"cat":"Weapons","group":"Equipment","title":"Eclipse Shotel","desc":"Curved Sword. Found at the altar of the Church in the southeast section of the castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedsword.png?h=40"},{"id":"3267","x":0.644375105,"y":0.240568703,"cat":"Sites of Grace","group":"Locations","title":"Freezing Lake","desc":"Site of grace located by the Freezing Lake","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4452","x":0.550057556,"y":0.240812865,"cat":"Waygates","group":"Locations","title":"Waygate to Miquella's Haligtree","desc":"Waygate accessible only after completing the Evergaol Puzzle at <a href='https://eldenring.wiki.fextralife.com/Ordina+Liturgical+Town' target=\"_blank\">Ordina, Liturgical Town</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"3754","x":0.61835965,"y":0.24148431,"cat":"Locations","group":"Locations","title":"Castle Sol","desc":"A minor dungeon found in northeast <a href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants' target=\"_blank\">Mountaintops of the Giants</a>. Stronghole of <a href='https://eldenring.wiki.fextralife.com/Commander+Niall' target=\"_blank\">Commander Niall</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-castlesol.png?h=40"},{"id":"3803","x":0.619472896,"y":0.241667432,"cat":"Consumables","group":"Items","title":"Rune Arc - Castle Sol","desc":"Consumable. Found on a corpse by a campfire atop the building in the south of the courtyard. This area is accessed by climbing a ladder behind the church in the southeast and following the path along the outer walls. Rune Arcs are also frequently dropped by Rat enemies in the castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4596","x":0.610470969,"y":0.241728472,"cat":"Locations","group":"Locations","title":"Walking Mausoleum (Mountaintops of the Giants)","desc":"Attack the white spots on the legs to get it to come down and access the mausoleum.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-walking-mausoleum.png?h=40"},{"id":"2984","x":0.536991548,"y":0.242094715,"cat":"Weapons","group":"Equipment","title":"Rotten Greataxe","desc":"Colossal Weapon. Dropped by the duelist enemy guarding the rear of Ordina, Liturgical Town","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greataxe.png?h=40"},{"id":"5939","x":0.662897933,"y":0.242125234,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Seppuku","desc":"On the frozen lake next to the \"Freezing Lake\" site of grace, dropped by an invisible <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a>. The Scarab can be heard on the edge of the lake. Stand on his trail and wait for it to come back around and greet it with attacks.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"8553","x":0.615413747,"y":0.242125234,"cat":"Consumables","group":"Items","title":"Golden Rune [10] A - Castle Sol","desc":"Rune Consumable. Found on a grave to the south as soon as you enter the main gate. Beware as there is a sleeping <a href='https://eldenring.wiki.fextralife.com/Lion+Guardian' target=\"_blank\">Lion Guardian</a> right next to it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2983","x":0.533936279,"y":0.242186274,"cat":"Armor","group":"Equipment","title":"Rotten Duelist Greaves","desc":"Leggings dropped by the large rotten duelist enemy guarding the rear of Ordina, Liturgical Town.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-leggins.png?h=40"},{"id":"3756","x":0.61195069,"y":0.243132404,"cat":"Sites of Grace","group":"Locations","title":"Castle Sol Main Gate","desc":"Site of Grace found by the castle's western entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3804","x":0.614559668,"y":0.243407084,"cat":"Talismans","group":"Equipment","title":"Cerulean Amber Medallion +1","desc":"Upgraded Talisman. Found on a corpse hanging by a wooden ledge above the southern walls of the castle. This area is accessed by climbing a ladder behind the church in the southeast and following the walls west. Beware the very powerful dual sword knight guarding the area. He can teleport behind you and perform very long combos.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4646","x":0.548688756,"y":0.243559687,"cat":"Consumables","group":"Items","title":"Invigorating Cured Meat - 1x Ordina, Liturgical Town","desc":"Found on a body on top of the stairs in Ordina, Liturgical Town","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3801","x":0.619931174,"y":0.243620728,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] - 3x Castle Sol","desc":"Upgrade Material. 3x found on a corpse inside a building full of Rats. This room is accessed by climbing the ladder behind the church and following the path along the outer walls. The building has an opening on the roof that you can jump to.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8249","x":0.61327764,"y":0.24407853,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Castle Sol","desc":"Summoning Pool Effigy found next to the Castle Sol Main Gate site of grace in the Mountaintops of the Giants. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4644","x":0.546818405,"y":0.244383732,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly - 1x Ordina, Liturgical Town","desc":"Nascent Butterfly found under the stairs in Ordina, Liturgical Town","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2979","x":0.548957137,"y":0.244963619,"cat":"Armor","group":"Equipment","title":"Black Knife Set","desc":"Full Set found under an arch. Includes <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/black+knife+hood'>Black Knife Hood</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/black+knife+armor'>Black Knife Armor</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/black+knife+gauntlets'>Black Knife Gauntlets</a> and <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/black+knife+greaves'>Black Knife Greaves</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"8251","x":0.649530356,"y":0.245787664,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Freezing Lake","desc":"Summoning Pool Effigy found southeast of the Freezing Lake site of grace in the Mountaintops of the Giants. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"9845","x":0.616145703,"y":0.245879227,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] - Castle Sol","desc":"Upgrade Material. Found on a corpse siting on a ledge outside <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Castle+Sol' target=\"blank\">Castle Sol</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4659","x":0.542847665,"y":0.246916915,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [9] - Ordina, Liturgical Town","desc":"It is dropped by an invisible warrior found by entering first the evergaol, you can defeat him by paying attention to the footprints on the ground.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"4647","x":0.540867263,"y":0.247893563,"cat":"Consumables","group":"Items","title":"Freezing Grease - 2x Ordina, Liturgical Town","desc":"Found on a body lying in the middle of the snow on the west side of Ordina, Liturgical Town","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8601","x":0.614245453,"y":0.24796071,"cat":"Bosses","group":"Characters","title":"Tibia Mariner (Mountaintops of the Giants)","desc":"Optional Boss found up on a ridge south of <a href='https://eldenring.wiki.fextralife.com/Castle+Sol' target=\"_blank\">Castle Sol</a>. Drops a <a href='https://eldenring.wiki.fextralife.com/Deathroot' target=\"_blank\">Deathroot</a> and <a href='https://eldenring.wiki.fextralife.com/Helphen's+Steeple' target=\"_blank\">Helphen's Steeple</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6808","x":0.61208743,"y":0.248229284,"cat":"Key Items","group":"Items","title":"Deathroot - Mountaintops of the Giants","desc":"Obtained when defeating the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/tibia+mariner'>Tibia Mariner</a> on a ledge between <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/castle+sol'>Castle Sol</a> Main Gate and Snow Valley Ruins Overlook.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2978","x":0.546147318,"y":0.24874813,"cat":"Locations","group":"Locations","title":"Ordina, Liturgical Town","desc":"It's easy to find once you gain access to Consecrated Snowfield. Loot is only found by interacting with the Evergaol.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ordina.png?h=40"},{"id":"3537","x":0.646478364,"y":0.249480617,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] x3 - Freezing Lake","desc":"Upgrade Material. Found at the bottom of the western side of the freezing lake, inside a statue with a glowing crack on it. Lure one of the nearby <a href='https://eldenring.wiki.fextralife.com/Golem' target=\"_blank\">Golems</a> to destroy the statue and collect the item.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8602","x":0.613767544,"y":0.2499079,"cat":"Weapons","group":"Equipment","title":"Helphen's Steeple","desc":"Greatsword. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Tibia+Mariner' target=\"_blank\">Tibia Mariner</a> boss found up on a ridge south of <a href='https://eldenring.wiki.fextralife.com/Castle+Sol' target=\"_blank\">Castle Sol</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"4645","x":0.547734247,"y":0.250304662,"cat":"Consumables","group":"Items","title":"Golden Rune [10] - 1x Ordina, Liturgical Town","desc":"Found on a body on the floor of Ordina, Liturgical Town","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8610","x":0.49918245,"y":0.251891715,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - West Consecrated Snowfield","desc":"There's a breakable statue with <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Smithing+Stone+(7)' target=\"blank\">Smithing Stone [7] x3</a> and <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Smithing+Stone+(8)' target=\"blank\">Smithing Stone [8]</a> inside. There's a bear uphill to the east that can be used to break it","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3263","x":0.594726033,"y":0.252257958,"cat":"Bosses","group":"Characters","title":"Death Rite Bird (Central Mountaintops of the Giants)","desc":"Optional Boss. A large Skeletal Bird found north of <a href='https://eldenring.wiki.fextralife.com/Stargazer's+Ruins' target=\"_blank\">Stargazer's Ruins</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Death+Ritual+Spear' target=\"_blank\">Death Ritual Spear</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"8253","x":0.573488836,"y":0.252868363,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Minor Erdtree (Consecrated Snowfields)","desc":"Summoning Pool Effigy found northwest of the Minor Erdtree in the Consectrated Snowfield, at the same elevation. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4579","x":0.625208037,"y":0.253204087,"cat":"Sites of Grace","group":"Locations","title":"Snow Valley Ruins Overlook","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2986","x":0.543152866,"y":0.253234606,"cat":"Sites of Grace","group":"Locations","title":"Ordina, Liturgical Town","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3912","x":0.592956003,"y":0.25350929,"cat":"Weapons","group":"Equipment","title":"Death Ritual Spear","desc":"Spear. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Death+Rite+Bird' target=\"_blank\">Death Rite Bird</a> boss upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spear.png?h=40"},{"id":"8609","x":0.498572052,"y":0.25357033,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] - 3x West Consecrated Snowfield","desc":"There's a breakable statue with <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Smithing+Stone+(7)' target=\"blank\">Smithing Stone [7] x3</a> and <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Smithing+Stone+(8)' target=\"blank\">Smithing Stone [8]</a> inside. There's a bear uphill to the east that can be used to break it","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2806","x":0.643764812,"y":0.253997614,"cat":"Spells","group":"Equipment","title":"Founding Rain of Stars","desc":"Glinstone Sorcery. Found inside a chest at the top of <a href='https://eldenring.wiki.fextralife.com/Heretical+Rise' target=\"_blank\">Heretical Rise</a>. You must access the tower by crossing an invisible bridge from the other side of the ravine.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"4119","x":0.641721057,"y":0.254089173,"cat":"Consumables","group":"Items","title":"Thawfrost Boluses","desc":"Consumable. Found on a corpse at the edge of the cliffs behind and below <a href='https://eldenring.wiki.fextralife.com/Heretical+Rise' target=\"_blank\">Heretical Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2766","x":0.58812049,"y":0.254333335,"cat":"Consumables","group":"Items","title":"Thawfrost Boluses - Mountaintops of the Giants Central","desc":"Consumable. Found in a corpse hiding from a cliff behind an enemy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2985","x":0.533025315,"y":0.254791141,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed (Ordina Liturgical Town)","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"8901","x":0.577484495,"y":0.255004781,"cat":"Flask Upgrades","group":"Items","title":"Thorny Cracked Tear","desc":"Dropped by the Putrid Avatar under the Minor Erdtree in Consecrated Snowfield","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"2804","x":0.646540014,"y":0.256103509,"cat":"Locations","group":"Locations","title":"Heretical Rise","desc":"Puzzle tower that hides the <a href='https://eldenring.wiki.fextralife.com/Founding+Rain+of+Stars' target=\"blank\">Founding Rain of Stars</a> spell. Unlock the entrance by finding the invisible bridge from the other side of the ravine, and carefully follow the misty path to find the way to enter.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"4643","x":0.576874233,"y":0.256835996,"cat":"Flask Upgrades","group":"Items","title":"Ruptured Crystal Tear","desc":"Dropped by the Putrid Avatar under the Minor Erdtree in Consecrated Snowfield","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"3547","x":0.659025851,"y":0.256988599,"cat":"Consumables","group":"Items","title":"Rune Arc - Spiritcaller Cave","desc":"Consumable Item. Found inside the <a href=\"Spiritcaller's+Cave\" target=\"_blank\">Spiritcaller's Cave</a>, in a small cavern with three corpses.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2054","x":0.669978179,"y":0.257415882,"cat":"Bosses","group":"Characters","title":"Borealis the Freezing Fog","desc":"Optional Boss. Drops a <a href='https://eldenring.wiki.fextralife.com/Dragon+Heart' target=\"blank\">Dragon Heart</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"8608","x":0.564363379,"y":0.258575652,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] (A)- Consecrated Snowfield","desc":"<p>Found with a visible <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"\">Teardrop Scarab</a> atop a rock formation west of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Consecrated+Snowfield)' target=\"\">Minor Erdtree (Consecrated Snowfield)</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3548","x":0.662016803,"y":0.258667211,"cat":"Consumables","group":"Items","title":"Hero's Rune [1] - Spiritcaller Cave","desc":"Rune Consumable. Found inside the <a href='https://eldenring.wiki.fextralife.com/Spiritcaller+Cave' target=\"_blank\">Spiritcaller Cave</a>, in a small cavern with three corpses.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4640","x":0.579073978,"y":0.259430219,"cat":"Bosses","group":"Characters","title":"Putrid Avatar","desc":"A Putrid Avatar is found at the bottom of the Minor Erdtree here in the Consecrated Snowfield.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2708","x":0.674560489,"y":0.259979584,"cat":"Consumables","group":"Items","title":"Dragon Heart (Borealis the Freezing Fog)","desc":"Key Consumable. Dropped by <a href='https://eldenring.wiki.fextralife.com/Borealis,+The+Freezing+Fog target='_blank\">Borealis, The Freezing Fog</a> upon defeat. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8252","x":0.633293759,"y":0.260223746,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Minor Erdtree (Mountaintops East)","desc":"Summoning Pool Effigy found north of the Minor Erdtree (Mountaintops East), near the bridge in the Mountaintops of the Giants. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"8607","x":0.56823941,"y":0.260498426,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9] - West Minor Erdtree (Consecrated Snowfield)","desc":"<p>Upgrade Material. Found with a invisible <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"\">Teardrop Scarab</a> atop a rock formation west of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Consecrated+Snowfield)' target=\"\">Minor Erdtree (Consecrated Snowfield)</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3554","x":0.662836518,"y":0.260589989,"cat":"Armor","group":"Equipment","title":"White Reed Set","desc":"White Reed Armor Set <u>excluding the Helm</u>. Found on a corpse inside the <a href='https://eldenring.wiki.fextralife.com/Spiritcaller's+Cave' target=\"_blank\">Spiritcaller's Cave</a>, in a long cavern filled with spirit wolves.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"2802","x":0.65636405,"y":0.260742588,"cat":"Sites of Grace","group":"Locations","title":"Spiritcaller Cave","desc":"Site of Grace found within the Spiritcaller's Cave, near the entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3521","x":0.641259459,"y":0.260803628,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Mountaintops of the Giants East","desc":"Flask Upgrade Material. Found under a Phantom Tree in the lower valley northeast of the Minor Erdtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"2801","x":0.65923136,"y":0.260864669,"cat":"Locations","group":"Locations","title":"Spiritcaller Cave","desc":"Cave found on the western bank of the frozen lake. Requires two <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Keys</a> to unlock the barrier. Spirit Snails and a double boss await within.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"4657","x":0.576400843,"y":0.261261434,"cat":"Consumables","group":"Items","title":"Warming Stone - 4x","desc":"Found on a body laying over a dead tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8248","x":0.655936726,"y":0.262604325,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Spiritcaller Cave","desc":"Summoning Pool Effigy found just past the short tunnel after the Spiritcaller Cave site of grace in the Mountaintops of the Giants. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4641","x":0.581116342,"y":0.262756925,"cat":"Locations","group":"Locations","title":"Minor Erdtree (Consecrated Snowfield)","desc":"Minor Erdtree found in the Consecrated Snowfield","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tree.png?h=40"},{"id":"3651","x":0.662470281,"y":0.262787447,"cat":"Talismans","group":"Equipment","title":"Godskin Swaddling Cloth","desc":"Talisman. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle+and+Godskin+Noble' target=\"_blank\">Godskin Apostle and Godskin Noble</a> upon their defeat in the <a href='https://eldenring.wiki.fextralife.com/Spiritcaller's+Cave' target=\"_blank\">Spiritcaller's Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"8606","x":0.566408215,"y":0.263062127,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [7] - Consecrated Snowfield","desc":"<p>Found with a visible <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"\">Teardrop Scarab</a> atop a rock around <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"\">Consecrated Snowfield</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3418","x":0.633966018,"y":0.263580973,"cat":"Flask Upgrades","group":"Items","title":"Cerulean Crystal Tear B","desc":"Physick Flask material. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Erdtree+Avatar' target=\"_blank\">Erdtree Avatar</a> guarding this tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"8228","x":0.59991607,"y":0.263886176,"cat":"Armor","group":"Equipment","title":"Greathood","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Helms'>Helm</a>. Reward for finding the painter of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Sorcerer+Painting'>Sorcerer Painting</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"4002","x":0.59085181,"y":0.263916694,"cat":"Armor","group":"Equipment","title":"Traveling Maiden Set","desc":"Armor set comprised of the <a href='https://eldenring.wiki.fextralife.com/Traveling+Maiden+Hood' target=\"_blank\">Traveling Maiden Hood</a>, <a href='https://eldenring.wiki.fextralife.com/Traveling+Maiden+Robe' target=\"_blank\">Traveling Maiden Robe</a>, <a href='https://eldenring.wiki.fextralife.com/Traveling+Maiden+Gloves' target=\"_blank\">Traveling Maiden Gloves</a> and the <a href='https://eldenring.wiki.fextralife.com/Traveling+Maiden+Boots' target=\"_blank\">Traveling Maiden Boots</a>. Found inside the <a href='https://eldenring.wiki.fextralife.com/Shack+of+the+Lofty' target=\"_blank\">Shack of the Lofty</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"3565","x":0.660700126,"y":0.263977735,"cat":"Bosses","group":"Characters","title":"Godskin Apostle and Godskin Noble","desc":"Consecutive boss fight at the end of the <a href='https://eldenring.wiki.fextralife.com/Spiritcaller's+Cave' target=\"_blank\">Spiritcaller's Cave</a>, first against a <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle' target=\"_blank\">Godskin Apostle</a> and then a <a href='https://eldenring.wiki.fextralife.com/Godskin+Noble' target=\"_blank\">Godskin Noble</a>. Defeating them awards the <a href='https://eldenring.wiki.fextralife.com/Godskin+Swaddling+Cloth' target=\"_blank\">Godskin Swaddling Cloth</a> talisman.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3416","x":0.631798285,"y":0.264191379,"cat":"Bosses","group":"Characters","title":"Erdtree Avatar (Mountaintops East)","desc":"Field Boss found roaming the fields near the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Mountaintops+East)' target=\"_blank\">Minor Erdtree</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Cerulean+Crystal+Tear' target=\"_blank\">Cerulean Crystal Tear</a> and <a href='https://eldenring.wiki.fextralife.com/Crimson+Bubbletear' target=\"_blank\">Crimson Bubbletear</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"4001","x":0.593323611,"y":0.264466059,"cat":"Locations","group":"Locations","title":"Shack of the Lofty","desc":"A lone shack found at the base of some cliffs in the north of the <a href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants' target=\"_blank\">Mountaintops of the Giants</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"3652","x":0.658593437,"y":0.26458814,"cat":"Spells","group":"Equipment","title":"Black Flame Ritual","desc":"<a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle+Incantations' target=\"_blank\">Godskin Apostle Incantation</a>. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle+and+Godskin+Noble' target=\"_blank\">Godskin Apostle and Godskin Noble</a> upon their defeat in the <a href='https://eldenring.wiki.fextralife.com/Spiritcaller's+Cave' target=\"_blank\">Spiritcaller's Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"4003","x":0.595796038,"y":0.264618662,"cat":"NPC Invaders","group":"Characters","title":"Juno Hoslow, Knight of Blood","desc":"A hostile NPC that you can invade as part of the final contract for the <a href='https://eldenring.wiki.fextralife.com/Volcano+Manor' target=\"_blank\">Volcano Manor</a> questline. Drops <a href='https://eldenring.wiki.fextralife.com/Hoslow's+Petal+Whip' target=\"_blank\">Hoslow's Petal Whip</a> along with <a href='https://eldenring.wiki.fextralife.com/Hoslow's+Set' target=\"_blank\">Hoslow's Set</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"3419","x":0.635308895,"y":0.265351148,"cat":"Flask Upgrades","group":"Items","title":"Crimson Bubbletear","desc":"Physick Flask material. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Erdtree+Avatar' target=\"_blank\">Erdtree Avatar</a> guarding this tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"4004","x":0.597749157,"y":0.265961553,"cat":"Armor","group":"Equipment","title":"Hoslow's Set","desc":"Armor Set comprised of <a href='https://eldenring.wiki.fextralife.com/Hoslow's+Helm' target=\"_blank\">Hoslow's Helm</a>, <a href='https://eldenring.wiki.fextralife.com/Hoslow's+Armor' target=\"_blank\">Hoslow's Armor</a>, <a href='https://eldenring.wiki.fextralife.com/Hoslow's+Gauntlets' target=\"_blank\">Hoslow's Gauntlets</a> and <a href='https://eldenring.wiki.fextralife.com/Hoslow's+Greaves' target=\"_blank\">Hoslow's Greaves</a>. Dropped by <a href='https://eldenring.wiki.fextralife.com/Juno+Hoslow,+Knight+of+Blood' target=\"_blank\">Juno Hoslow, Knight of Blood</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"6389","x":0.584167947,"y":0.265992072,"cat":"Spells","group":"Equipment","title":"Theodorix's Magma","desc":"Unlocked after the defeat of <a href='https://eldenring.wiki.fextralife.com/Great+Wyrm+Theodorix' target=\"_blank\">Great Wyrm Theodorix</a>. This item can then be purchased after its defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"8732","x":0.552892705,"y":0.266449877,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - Consecrated Snowfields Central Area","desc":"Upgrade Material. Looted from a body behind the big tree where you get the map piece.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4005","x":0.595856922,"y":0.26696872,"cat":"Weapons","group":"Equipment","title":"Hoslow's Petal Whip","desc":"Whip. Dropped by <a href='https://eldenring.wiki.fextralife.com/Juno+Hoslow,+Knight+of+Blood' target=\"_blank\">Juno Hoslow, Knight of Blood</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-whip.png?h=40"},{"id":"3412","x":0.633478997,"y":0.267457044,"cat":"Locations","group":"Locations","title":"Minor Erdtree (Mountaintops East)","desc":"Minor Erdtree found on the eastern half of the <a href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants' target=\"_blank\">Mountaintops of the Giants</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tree.png?h=40"},{"id":"4658","x":0.586273285,"y":0.267670687,"cat":"Consumables","group":"Items","title":"Freezing Grease - 4x Cave of the Forlorn","desc":"Can be found inside <a href='https://eldenring.wiki.fextralife.com/Cave+of+the+Forlorn' target=\"_blank\">Cave of the Forlorn</a>. just pass the <a href='https://eldenring.wiki.fextralife.com/Golden+Rune+(7)' target=\"_blank\">Golden Rune (7)</a> - Another one inside the cave, on a body against a wall on a small room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3408","x":0.6114415,"y":0.267945368,"cat":"Talismans","group":"Equipment","title":"Primal Glintstone Blade","desc":"Talisman. Found in an underground area of the <a href='https://eldenring.wiki.fextralife.com/Stargazer's+Ruins' target=\"_blank\">Stargazer's Ruins</a>. The entrance is sealed by a barrier and there is a talking jellyfish atop the steps. Summon the <a href='https://eldenring.wiki.fextralife.com/Spirit+Jellyfish' target=\"_blank\">Spirit Jellyfish</a> next to her to unlock the seal.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4814","x":0.58163618,"y":0.268159011,"cat":"Weapons","group":"Equipment","title":"Golden Order Greatsword","desc":"Found inside <a href='https://eldenring.wiki.fextralife.com/Cave+of+the+Forlorn' target=\"_blank\">Cave of the Forlorn</a>. Dropped by <a href='https://eldenring.wiki.fextralife.com/Misbegotten+Crusader' target=\"_blank\"> Misbegotten Crusader</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"3407","x":0.616931289,"y":0.268220052,"cat":"Consumables","group":"Items","title":"Freezing Grease","desc":"Consumable Item. Found on a corpse in the eastern section of the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8245","x":0.583679629,"y":0.268311611,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Cave of the Forlorn","desc":"Summoning Pool Effigy found in the middle of the ice just past the frozen dragon after the Cave of the Forlorn site of grace in the Consecrated Snowfield. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3405","x":0.607694232,"y":0.268586295,"cat":"Locations","group":"Locations","title":"Stargazer's Ruins","desc":"A set of ruins found in central <a href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants' target=\"_blank\">Mountaintops of the Giants</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"7918","x":0.539190192,"y":0.268708376,"cat":"NPC Invaders","group":"Characters","title":"Anastasia Tarnished-Eater (Consecrated Snowfield)","desc":"Post patch you can find Anastasia in the <a href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"_blank\">Consecrated Snowfield</a> on the frozen river southwest of <a href='https://eldenring.wiki.fextralife.com/Ordina+Liturgical+Town' target=\"_blank\">Ordina Liturgical Town</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"4655","x":0.587585642,"y":0.269288259,"cat":"Consumables","group":"Items","title":"Golden Rune [7] - 1x Cave of Forlorn","desc":"Inside <a href='https://eldenring.wiki.fextralife.com/Cave+of+the+Forlorn' target=\"_blank\"> Cave of the Forlorn</a>. Just jump down from the site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5965","x":0.581730642,"y":0.269990227,"cat":"Sites of Grace","group":"Locations","title":"Cave of the Forlorn","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4653","x":0.514717772,"y":0.270081785,"cat":"Consumables","group":"Items","title":"Thawfrost Boluses - 2x","desc":"Found on a body atop one of the pillars in the Consecrated Snowfield.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4652","x":0.584900114,"y":0.270966875,"cat":"Locations","group":"Locations","title":"Cave of the Forlorn","desc":"Located south of the Minor Erdtree in <a href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"_blank\">Consecrated Snowfield</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"3173","x":0.552677041,"y":0.271302596,"cat":"Maps","group":"Locations","title":"Map (Consecrated Snowfield)","desc":"Map for all of Consecrated Snowfield: follow the road north past the snowstorm until you go down and cross a frozen river, then you will spot the map pillar ahead.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"7919","x":0.538334707,"y":0.271302596,"cat":"Upgrade Materials","group":"Items","title":"Somber Ancient Dragon Smithing Stone","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Anastasia+Tarnished-Eater' target=\"_blank\">Anastasia, Tarnished-Eater</a> after her third invasion, in the <a href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"_blank\">Consecrated Snowfield</a> on the frozen river southwest of <a href='https://eldenring.wiki.fextralife.com/Ordina+Liturgical+Town' target=\"_blank\">Ordina, Liturgical Town</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4824","x":0.580841126,"y":0.271546758,"cat":"Bosses","group":"Characters","title":"Misbegotten Crusader","desc":"Boss found at the end of the <a href='https://eldenring.wiki.fextralife.com/Cave+of+the+Forlorn' target=\"_blank\"> Cave of the Forlorn</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Golden+Order+Greatsword' target=\"_blank\"> Golden Order Greatsword</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6398","x":0.592072455,"y":0.27157728,"cat":"Upgrade Materials","group":"Items","title":"Ancient Dragon Smithing Stone","desc":"On the waterfall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4656","x":0.588591544,"y":0.272614968,"cat":"Bosses","group":"Characters","title":"Great Wyrm Theodorix","desc":"Optional Dragon Boss found outside of the <a href='https://eldenring.wiki.fextralife.com/Cave+of+the+Forlorn'>Cave of the Forlorn</a>. Drops <strong>3</strong> <a href='https://eldenring.wiki.fextralife.com/Dragon+Heart' target=\"_blank\">Dragon Hearts</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mainboss.png?h=40"},{"id":"10232","x":0.594905721,"y":0.272624079,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Consecrated Snowfield Waterfall","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants' target=\"blank\">Mountaintops of the Giants</a>, south of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Shack+of+the+Lofty' target=\"blank\">Shack of the Lofty</a> by the waterfall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"9836","x":0.579384604,"y":0.272905982,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - 3x Consecrated Snowfield","desc":"Upgrade Material. Looted from a statue close to the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Cave+of+the+Forlorn' target=\"blank\">Cave of the Forlorn</a>. Lure a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Giant+Crab' target=\"blank\">Giant Crab</a> or <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Giant+Land+Octopus' target=\"blank\">Giant Land Octopus</a> from the area to help you destroy the statue and loot its contents.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8054","x":0.586914742,"y":0.273805257,"cat":"Consumables","group":"Items","title":"Dragon Heart (Great Wyrm Theodorix)","desc":"Key Consumable. <strong>3 Hearts</strong> are dropped by <a href='https://eldenring.wiki.fextralife.com/Great+Wyrm+Theodorix' target=\"_blank\"> Great Wyrm Theodorix</a> upon his defeat. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4654","x":0.518136002,"y":0.27395786,"cat":"Consumables","group":"Items","title":"Crystal Dart 4x","desc":"Found on a body being devoured by Rotten Strays in the Consecrated Snowfield","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6618","x":0.532568689,"y":0.274385143,"cat":"Key Items","group":"Items","title":"Stonesword Key - West Mountaintops of the Giants","desc":"Held by a corpse sitting on a chair, near the edge of the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8605","x":0.544406406,"y":0.274385143,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: White Shadow's Lure","desc":"<p>Dropped by an invisible <a class=\"wiki_link\" title=\"Elden Ring Teardrop Scarab\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab'>Teardrop Scarab</a> in the <a class=\"wiki_link\" title=\"Elden Ring Consecrated Snowfield\" href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield'>Consecrated Snowfield</a>, northwest of the Inner Consecrated Snowfield site of grace between the grace and <a class=\"wiki_link\" title=\"Elden Ring Ordina Liturgical Town\" href='https://eldenring.wiki.fextralife.com/Ordina+Liturgical+Town'>Ordina, Liturgical Town</a>. </p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"4651","x":0.506172854,"y":0.274507224,"cat":"Consumables","group":"Items","title":"Hero's Rune [2]","desc":"Found on a body by the edge of the large pillar hanging off the edge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6136","x":0.613156665,"y":0.275605953,"cat":"NPCs","group":"Characters","title":"Brother Corhyn (Fourth Location)","desc":"NPC, found at the south of <a href='https://eldenring.wiki.fextralife.com/Stargazer's+Ruins' target=\"_blank\"> Stargazer's Ruins</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3410","x":0.61484031,"y":0.276033237,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9] A","desc":"Upgrade Material. Found on a corpse sitting in a chair on the bridge south of <a href='https://eldenring.wiki.fextralife.com/Stargazer's+Ruins' target=\"_blank\">Stargazer's Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3170","x":0.507634839,"y":0.276918322,"cat":"Waygates","group":"Locations","title":"Waygate to Mohgwyn Palace","desc":"Waygate. Teleports players to the underground area beneath Caelid, called <a href='https://eldenring.wiki.fextralife.com/Mohgwyn+Palace' target=\"_blank\">Mohgwyn Palace</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"8848","x":0.612459756,"y":0.278444335,"cat":"NPCs","group":"Characters","title":"Millicent (Fifth Location)","desc":"<p style=\"text-align: left;\">NPC. Millicent will move to the Ancient Snow Valley Ruins Site of Grace at��<a class=\"wiki_link\" title=\"Elden Ring Mountaintops of the Giants\" href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants'>Mountaintops of the Giants</a>��after her encounter at the��Windmill Heights Grace.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"9829","x":0.577606423,"y":0.278566416,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Albinauric Rise","desc":"Summoning Pool Effigy in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"blank\">Consecrated Snowfield</a>. It is located Southwest of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Cave+of+the+Forlorn' target=\"blank\">Cave of the Forlorn</a>, across the river. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2997","x":0.517401449,"y":0.278688497,"cat":"NPC Invaders","group":"Characters","title":"Sanguine Noble","desc":"Invading NPC. Drops <a href='https://eldenring.wiki.fextralife.com/Sanguine+Set' target=\"_blank\">Sanguine Set</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"3513","x":0.613522754,"y":0.278810578,"cat":"Sites of Grace","group":"Locations","title":"Ancient Snow Valley Ruins","desc":"Site of Grace found below the bridge south of <a href='https://eldenring.wiki.fextralife.com/Stargazer's+Ruins'>Stargazer's Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4802","x":0.576557236,"y":0.27905474,"cat":"Talismans","group":"Equipment","title":"Graven-Mass Talisman","desc":"Talisman found in a chest atop the <a href='https://eldenring.wiki.fextralife.com/Albinauric+Rise' target=\"_blank\">Albinauric Rise</a> tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3504","x":0.609678117,"y":0.279726185,"cat":"NPCs","group":"Characters","title":"Hermit Merchant Mountaintops East","desc":"<a href='https://eldenring.wiki.fextralife.com/Nomadic+Merchants' target=\"_blank\">Nomadic Merchant</a>. General Goods vendor found south of <a href='https://eldenring.wiki.fextralife.com/Stargazer's+Ruins' target=\"_blank\">Stargazer's Ruins</a>, beneath the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"4650","x":0.516027817,"y":0.279726185,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - Yelough Anix Ruins","desc":"Upgrade Material. Found on a corpse resting against a pillar in the northern section of <a href='https://eldenring.wiki.fextralife.com/Yelough+Anix+Ruins' target=\"_blank\">Yelough Anix Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5758","x":0.579163742,"y":0.280550234,"cat":"Locations","group":"Locations","title":"Albinauric Rise","desc":"Puzzle tower found east of the Consecrated Snowfield. Unlocking the seal requires you to summon your <a href='https://eldenring.wiki.fextralife.com/Fanged+Imp+Ashes' target=\"_blank\">Fanged Imp Ashes</a> and defeat one of the imps that spawn around the tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"2974","x":0.58699505,"y":0.280611275,"cat":"Waygates","group":"Locations","title":"Waygate (Consecrated Snowfield)","desc":"Waygate. Teleports you across the ravine to the northern side of the river.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"2998","x":0.519323966,"y":0.280855437,"cat":"Armor","group":"Equipment","title":"Sanguine Set","desc":"Full <strong>Sanguine Set</strong> dropped by <a href='https://eldenring.wiki.fextralife.com/Sanguine+Noble' target=\"_blank\">Sanguine Noble</a> NPC invasion. Includes <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sanguine+noble+hood'>Sanguine Noble Hood</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sanguine+Noble+robe'>Sanguine Noble Robe</a> and <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sanguine+noble+waistcloth'>Sanguine Noble Waistcloth</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"10233","x":0.664042727,"y":0.28154956,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Lord Contender's Evergaol","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants' target=\"blank\">Mountaintops of the Giants</a>, at the cliffside directly east of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Lord+Contender's+Evergaol' target=\"blank\">Lord Contender's Evergaol</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"5940","x":0.661585201,"y":0.281832085,"cat":"Spells","group":"Equipment","title":"Vyke's Dragonbolt","desc":"<a href='https://eldenring.wiki.fextralife.com/Dragon+Cult+Incantations' target=\"_blank\">Dragon Cult Incantation</a>. Received after defeating <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Roundtable+Knight+Vyke'>Vyke, Knight of the Roundtable</a> at <a href='https://eldenring.wiki.fextralife.com/Lord+Contender's+Evergaol' target=\"_blank\">Lord Contender's Evergaol</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"14101","x":0.655435655,"y":0.282566583,"cat":"Bosses","group":"Characters","title":"Roundtable Knight Vyke","desc":"<p><br />Optional Boss. Located in <a class=\"wiki_link\" title=\"Elden Ring Lord Contender's Evergaol\" href='https://eldenring.wiki.fextralife.com/Lord+Contender's+Evergaol' target=\"_blank\" rel=\"noopener noreferrer\">Contender's Evergaol</a>. Drops <a class=\"wiki_link\" title=\"Elden Ring Fingerprint Set\" href='https://eldenring.wiki.fextralife.com/Fingerprint+Set' target=\"_blank\" rel=\"noopener noreferrer\">Fingerprint Set</a><a class=\"wiki_link\" title=\"Elden Ring Vyke's Dragonbolt\" href='https://eldenring.wiki.fextralife.com/Vyke's+Dragonbolt' target=\"_blank\" rel=\"noopener noreferrer\">Vyke's Dragonbolt</a> upon defeat.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mainboss.png?h=40"},{"id":"3873","x":0.657674709,"y":0.282595089,"cat":"Locations","group":"Locations","title":"Lord Contender's Evergaol","desc":"Evergaol with Boss Fight: <a href='https://eldenring.wiki.fextralife.com/Roundtable+Knight+Vyke' target=\"_blank\">Roundtable Knight Vyke</a>, who drops the <a href='https://eldenring.wiki.fextralife.com/Fingerprint+Set' target=\"_blank\">Fingerprint Set</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-evergaol.png?h=40"},{"id":"10101","x":0.579156547,"y":0.283113936,"cat":"Consumables","group":"Items","title":"Rune Arc - Albinauric Rise","desc":"Consumable. In a chest located next to <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Albinauric+Rise' target=\"blank\">Albinauric Rise</a> on a cliff. You can drop down or reach this area from the tower itself.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3876","x":0.659937127,"y":0.283144454,"cat":"Armor","group":"Equipment","title":"Fingerprint Set","desc":"Armor Set comprised of the <a href='https://eldenring.wiki.fextralife.com/Fingerprint+Helm' target=\"_blank\">Fingerprint Helm</a>, <a href='https://eldenring.wiki.fextralife.com/Fingerprint+Armor' target=\"_blank\">Fingerprint Armor</a>, <a href='https://eldenring.wiki.fextralife.com/Fingerprint+Helm' target=\"_blank\"><a href='https://eldenring.wiki.fextralife.com/Fingerprint+Gauntlets' target=\"_blank\">Fingerprint Gauntlets</a>, and the <a href='https://eldenring.wiki.fextralife.com/Fingerprint+Greaves' target=\"_blank\">Fingerprint Greaves</a>. drops from <a href='https://eldenring.wiki.fextralife.com/Lord+Contender's+Evergaol' target=\"_blank\">Lord Contender's Evergaol</a> Boss Fight: <a href='https://eldenring.wiki.fextralife.com/Roundtable+Knight+Vyke' target=\"_blank\">Roundtable Knight Vyke</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"3519","x":0.620082505,"y":0.283510697,"cat":"Crafting Materials","group":"Items","title":"Formic Rock","desc":"Crafting Material. Found on a corpse at the edge of the cliffs east of the Ancient Snow Valley Ruins Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3514","x":0.611116879,"y":0.2836633,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] B","desc":"Upgrade Material. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab'>Teardrop Scarab</a> found in the lower valley.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3517","x":0.614978014,"y":0.283754859,"cat":"Consumables","group":"Items","title":"Soft Cotton","desc":"Consumable. Found on a corpse sitting on a chair south of the Ancient Snow Valley Ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5775","x":0.573915082,"y":0.284090584,"cat":"Key Items","group":"Items","title":"Glintstone Craftsman's Cookbook [8]","desc":"Can be found in the <a href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"_blank\">Consecrated Snowfield</a>, southwest of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Albinauric+Rise'>Albinauric's Rise</a>. There are 3 <a href='https://eldenring.wiki.fextralife.com/School+of+Graven+Mages' target=\"_blank\">Schools of Graven Mages</a> encircling a corpse with the Cookbook.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"2773","x":0.68358778,"y":0.286532204,"cat":"Key Items","group":"Items","title":"Somberstone Miner's Bell Bearing [3]","desc":"Bell Bearing Key Item. Found on a corpse just outside the <a href='https://eldenring.wiki.fextralife.com/First+Church+of+Marika' target=\"_blank\">First Church of Marika</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3515","x":0.603258367,"y":0.287722492,"cat":"Consumables","group":"Items","title":"Golden Rune [13]","desc":"Rune Consumable. Found on a corpse behind a <a href='https://eldenring.wiki.fextralife.com/Golem' target=\"_blank\">Golem</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2810","x":0.633701617,"y":0.288119257,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] - Guardians' Garrison","desc":"Upgrade Material. Found on a corpse in the upper ramparts of <a href='https://eldenring.wiki.fextralife.com/Guardian's+Garrison' target=\"_blank\">Guardian's Garrison</a>. A Flame Guardian is protecting it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4578","x":0.555212542,"y":0.288210816,"cat":"Sites of Grace","group":"Locations","title":"Inner Consecrated Snowfield","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2782","x":0.681088763,"y":0.288302379,"cat":"Sites of Grace","group":"Locations","title":"First Church of Marika","desc":"Site of Grace of the First Church of Marika","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2803","x":0.63874717,"y":0.288454978,"cat":"Sites of Grace","group":"Locations","title":"Whiteridge Road","desc":"Site of Grace found near the Guardians Garrison.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4806","x":0.517980167,"y":0.289034865,"cat":"Key Items","group":"Items","title":"Stonesword Key - Yelough Anix Ruins","desc":"Stonesword Key. Found inside a small open structure in the northern section of the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6209","x":0.686365228,"y":0.289126423,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] - 3x First Church of Marika","desc":"<p>Upgrade Material. <strong>Three</strong> can be obtained from a corpse sitting on a chair atop the cliffs east overlooking the <a href='https://eldenring.wiki.fextralife.com/First+Church+of+Marika' target=\"_blank\" rel=\"noopener noreferrer\">First Church of Marika</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2809","x":0.629053627,"y":0.289767351,"cat":"Crafting Materials","group":"Items","title":"Smoldering Butterfly - 6x Guardians' Garrison","desc":"Crafting Material. 6 are found on a corpse by an active fire inside Guardian's Garrison.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"9846","x":0.577156987,"y":0.289828391,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] - Consecrated Snowfield","desc":"Upgrade Material. From the top of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Albinauric+Rise' target=\"blank\">Albinauric Rise</a> jump south onto some rocks and further up until you are on top of the rocks. It is located next to a large gravestone.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2775","x":0.683615898,"y":0.290560877,"cat":"Locations","group":"Locations","title":"First Church of Marika","desc":"Destroyed Church with a Sacred Tear and Somber Miner's Bell Bearing (3). Offers a respite before a Dragon encounter.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"6620","x":0.636214016,"y":0.290682958,"cat":"Key Items","group":"Items","title":"Stonesword Key - Guardians' Garrison","desc":"Stonesword Key. Held by a corpse in front of the fort's entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6379","x":0.357662513,"y":0.290896599,"cat":"Weapons","group":"Equipment","title":"Twinned Knight Swords","desc":"In a burning corpse pile in front of <a href='https://eldenring.wiki.fextralife.com/East+Windmill+Pasture' target=\"_blank\">East Windmill Pasture</a> in <a href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"_blank\"> Altus Plateau</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-doubleedgedswords.png?h=40"},{"id":"2808","x":0.632714147,"y":0.291445963,"cat":"Locations","group":"Locations","title":"Guardians' Garrison","desc":"A garrison of Fire Priests guard the path to the Giant Forge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-forthaight.png?h=40"},{"id":"2779","x":0.686056516,"y":0.291507003,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (First Church of Marika)","desc":"A flask upgrade found within the <a href='https://eldenring.wiki.fextralife.com/First+Church+of+Marika' target=\"_blank\">First Church of Marika</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"4803","x":0.520728911,"y":0.293277178,"cat":"Locations","group":"Locations","title":"Yelough Anix Ruins","desc":"A set of ruins found west of the <a href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"_blank\">Consecrated Snowfield</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"2812","x":0.629810693,"y":0.293368741,"cat":"Consumables","group":"Items","title":"Golden Rune [10] -  Guardian's Garrison","desc":"Rune Consumable. Found on a corpse on the ledge past some barrels near the entrance to Guardian's Garrison.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2813","x":0.635340943,"y":0.293368741,"cat":"Shields","group":"Equipment","title":"One-Eyed Shield","desc":"Shield. Dropped by mini-boss NPC <a href='https://eldenring.wiki.fextralife.com/Chief+Guardian+Arghanthy' target=\"_blank\">Chief Guardian Arghanthy</a> inside <a href='https://eldenring.wiki.fextralife.com/Guardian's+Garrison' target=\"_blank\">Guardian's Garrison</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"5733","x":0.360925666,"y":0.294131745,"cat":"Locations","group":"Locations","title":"East Windmill Pasture","desc":"The East Windmill Pasture is found in the Altus Plateau, in the North-most limits of the area","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-windmill.png?h=40"},{"id":"5840","x":0.356167657,"y":0.294253826,"cat":"Armor","group":"Equipment","title":"Noble's Set","desc":"An Armor Set comprised of the <a href='https://eldenring.wiki.fextralife.com/Navy+Hood' target=\"_blank\">Navy Hood</a>, <a href='https://eldenring.wiki.fextralife.com/Noble's+Traveling+Garb' target=\"_blank\">Noble's Traveling Garb</a>, <a href='https://eldenring.wiki.fextralife.com/Noble's+Gloves' target=\"_blank\">Noble's Gloves</a> and <a href='https://eldenring.wiki.fextralife.com/Noble's+Trousers' target=\"_blank\">Noble's Trousers</a>.The entire set can be found within <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/east+windmill+pasture'>East Windmill Pasture</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/altus+plateau'>Altus Plateau</a>, in the fire in the middle of a circle of dancing women.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"7804","x":0.563019818,"y":0.29452851,"cat":"Key Items","group":"Items","title":"Larval Tear","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Runebear' target=\"_blank\">Runebear</a> disguised as a pilgrim in the <a href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"_blank\">Consecrated Snowfield</a>. The disguised pilgrim is half-buried in snow with two other pilgrims, one carrying a torch, standing around it. They are located southeast of the Inner Consecrated Snowfield site of grace, nearly on the straight-line path between the grace and the <a href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield+Catacombs' target=\"_blank\">Consecrated Snowfield Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2811","x":0.633540088,"y":0.294772672,"cat":"NPC Invaders","group":"Characters","title":"Chief Guardian Arghanthy","desc":"NPC Mini-Boss, attacks with quick Fire spells. Drops <a href='https://eldenring.wiki.fextralife.com/One-Eyed+Shield' target=\"_blank\">One-Eyed Shield</a> when defeated.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"4808","x":0.523626721,"y":0.296115563,"cat":"Spells","group":"Equipment","title":"Unendurable Frenzy","desc":"<a href='https://eldenring.wiki.fextralife.com/Incantations' target=\"_blank\">Incantation</a>. Found in a chest in an underground treasure room in the central section of the <a href='https://eldenring.wiki.fextralife.com/Yelough+Anix+Ruins' target=\"_blank\">Yelough Anix Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"4412","x":0.544624421,"y":0.296603887,"cat":"Armor","group":"Equipment","title":"Night's Cavalry Set","desc":"Full Set dropped by one of the two mini-boss <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> guarding a Consecrated Fields caravan at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"2814","x":0.631709971,"y":0.296756487,"cat":"Key Items","group":"Items","title":"Giant's Prayerbook","desc":"Key Item. Give to a Cleric to unlock Incantations: Giantsflame Take Thee and Flame, Fall Upon Them for purchase.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tome.png?h=40"},{"id":"5819","x":0.389575319,"y":0.29718377,"cat":"Weapons","group":"Equipment","title":"Godskin Peeler","desc":"Dropped by the <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle' target=\"_blank\">Godskin Apostle</a> fought at the <a href='https://eldenring.wiki.fextralife.com/Windmill+Village' target=\"_blank\">Windmill Village</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-doubleedgedswords.png?h=40"},{"id":"4409","x":0.54858779,"y":0.297305852,"cat":"Weapons","group":"Equipment","title":"Flowing Curved Sword","desc":"Curved Sword. Found within the chest of the Enemy Caravan traveling the <a href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"_blank\">Consecrated Snowfield</a> south-western area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedsword.png?h=40"},{"id":"3165","x":0.267278061,"y":0.298801346,"cat":"Sites of Grace","group":"Locations","title":"Volcano Cave","desc":"Site of Grace located by the entrance to <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Cave'>Volcano Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3246","x":0.390340919,"y":0.299045508,"cat":"Sites of Grace","group":"Locations","title":"Windmill Heights","desc":"Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2964","x":0.57107752,"y":0.299076026,"cat":"Weapons","group":"Equipment","title":"St Trina's Torch","desc":"Special Torch. Looted from the treasure chest in the caravan wagon carted in the southern portion of Consecrated Ground in the northern lands.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-torch.png?h=40"},{"id":"4411","x":0.544349744,"y":0.299198107,"cat":"Bosses","group":"Characters","title":"Night's Cavalry - 2x (Consecrated Snowfield)","desc":"Two Night's Cavalry mini-bosses guard the wagon in the Consecrated Snowfield. Spawn at night only. Drops <a href='https://eldenring.wiki.fextralife.com/Night+Cavalry's+Set' target=\"_blank\">Night Cavalry's Set</a> and <a href='https://eldenring.wiki.fextralife.com/Ancient+Dragon+Smithing+Stone' target=\"_blank\">Ancient Dragon Smithing Stone</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"7923","x":0.634730107,"y":0.299259148,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Prelate's Charge","desc":"In <a href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants' target=\"_blank\">Mountaintops of the Giants</a>. South of Whiteridge Road Grace. Inside a Fire Monk campsite, look for the scarab hanging on a tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"5786","x":0.343811942,"y":0.299442269,"cat":"Spirit Ashes","group":"Equipment","title":"Giant Rat Ashes","desc":"Can be found in a wooden shack located left of the windwill.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"5805","x":0.392629428,"y":0.299991634,"cat":"Bosses","group":"Characters","title":"Godskin Apostle (Altus Plateau)","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Windmill+Heights' target=\"_blank\">Windmill Heights</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Godskin+Peeler' target=\"_blank\">Godskin Peeler</a> and <a href='https://eldenring.wiki.fextralife.com/Scouring+Black+Flame' target=\"_blank\">Scouring Black Flame</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"8611","x":0.53437072,"y":0.300113715,"cat":"Consumables","group":"Items","title":"Golden Rune [13] - Southwest Consecrated Snowfield","desc":"<p>A Golden Rune [13] is located Southwest <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"\">Consecrated Snowfield</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4408","x":0.547367134,"y":0.30051048,"cat":"Locations","group":"Locations","title":"Enemy Caravan 2 (Consecrated Snowfield)","desc":"Enemy Caravan. Loot the chest to obtain <a href='https://eldenring.wiki.fextralife.com/Flowing+Curved+Sword' target=\"_blank\">Flowing Curved Sword</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-wagon.png?h=40"},{"id":"9840","x":0.267673037,"y":0.300540998,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Volcano Cave","desc":"Summoning Pool Effigy next to the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Volcano+Cave' target=\"blank\">Volcano Cave</a> Site of Grace. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5817","x":0.388629203,"y":0.300754642,"cat":"Spells","group":"Equipment","title":"Scouring Black Flame","desc":"Incantation, dropped by the <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle' target=\"_blank\">Godskin Apostle</a> fought at the <a href='https://eldenring.wiki.fextralife.com/Windmill+Village' target=\"_blank\">Windmill Village</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"6362","x":0.518836609,"y":0.300754642,"cat":"Consumables","group":"Items","title":"Hero's Rune [5] - Yelough Anix Tunnel","desc":"Rune Consumable. Found on a body in the center of the room where the <a href='https://eldenring.wiki.fextralife.com/Onyx+Lord' target=\"_blank\">Onyx Lord</a> is fought.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4586","x":0.583496669,"y":0.301090363,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [9] - 1x Consecrated Snowfield Catacombs","desc":"Ghost Glovewort found in a room with 2 Cleanrot Knights.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5809","x":0.391806389,"y":0.301151404,"cat":"NPCs","group":"Characters","title":"Millicent (Fourth Location)","desc":"Moves here after <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle'>Godskin Apostle</a> is defeated.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3166","x":0.26300428,"y":0.301242966,"cat":"Bosses","group":"Characters","title":"Demi-Human Queen Margot","desc":"Optional Field Boss. Found in the lowest level of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Cave'>Volcano Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"5717","x":0.265385829,"y":0.301273484,"cat":"Shields","group":"Equipment","title":"Coil Shield","desc":"Located on a body in Volcano Cave, northeast of the Ninth Mt. Gelmir Campsite in Mt. Gelmir. You will need to drop down a hole and then double back.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-smallshield.png?h=40"},{"id":"8618","x":0.557393387,"y":0.301331134,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9] - Western Consecrated Snowfield","desc":"<p>Can be looted on top of a rock formation in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"\">Consecrated Snowfield</a> North of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Hidden+Path+to+the+Haligtree' target=\"\">Hidden Path to the Haligtree</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4638","x":0.521217163,"y":0.301670249,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9] - Yelough Anix Tunnel","desc":"Upgrade Material. On the right, in a cavity where you find the <a href='https://eldenring.wiki.fextralife.com/Onyx+Lord'>Onyx Lord</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3454","x":0.585358384,"y":0.301883889,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [9] - 6x Consecrated Snowfield Catacombs","desc":"Upgrade material. 6 in total. First is found within the Consecrated Snowfield Catacombs, in a room filled with imps. Another one is found in the room before taking the stairs to the second floor of the frost trap. Third is on second floor by the trap. A fourth is guarded by two Cleanrot Knights in a room in the second floor by the trap. A fifth one can be looted on the third floor by the lever to open the boss door. Final one is in a room in the second floor, guarded by a Burial Tree Watchdog.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"3501","x":0.58182919,"y":0.302097533,"cat":"Consumables","group":"Items","title":"Golden Rune [12] - Consecrated Snowfield Catacombs","desc":"Consumable Item. Looted from a corpse on the third floor, by the lever that opens the boss door.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10501","x":0.259360613,"y":0.302529372,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf - 3x Volcano Cave","desc":"<p>Material. Can be looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Volcano+Cave' target=\"blank\">Volcano Cave</a>, in a room guarded by <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Demi-Human' target=\"blank\">Demi-Human</a> Enemies</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"4495","x":0.517675337,"y":0.302555335,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] - Yelough Anix Tunnel","desc":"Somber Smithing Stones [8] are found throughout the tunnel as little shinny white stones on the wall or at the end of some cavities.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"10399","x":0.262320471,"y":0.302810838,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Volcano Cave","desc":"<p>Looted from a body hanging from a ledge in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Volcano+Cave' target=\"blank\">Volcano Cave</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3164","x":0.268527026,"y":0.302921578,"cat":"Locations","group":"Locations","title":"Volcano Cave","desc":"A cave found at the top of a mountain.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"8244","x":0.522436444,"y":0.302921578,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Yelough Anix Tunnel","desc":"Summoning Pool Effigy found next to the Yelough Anix Tunnel site of grace in the Consecrated Snowfield. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4413","x":0.544563381,"y":0.303074181,"cat":"Upgrade Materials","group":"Items","title":"Ancient Dragon Smithing Stone (Consecrated Snowfield Boss Drop)","desc":"Dropped by one of the two mini-boss <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> guarding a Consecrated Fields caravan at night, alongside the <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry+Set' target=\"_blank\">Night's Cavalry Set</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"7751","x":0.372583765,"y":0.303501465,"cat":"Consumables","group":"Items","title":"Raw Meat Dumpling - 10x Village Windmill Pasture","desc":"Consumable. Found on a corpse in the left stables at the <a href='https://eldenring.wiki.fextralife.com/Village+Windmill+Pasture' target=\"_blank\">Village Windmill Pasture</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5841","x":0.351861918,"y":0.303562505,"cat":"Armor","group":"Equipment","title":"Battlemage Set","desc":"The entire set drops from a particular <em>Battlemage</em> enemy, located east of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/west+windmill+pasture'>West Windmill Pasture</a>, on a hill near the northern end of the collapsed bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"3176","x":0.582924626,"y":0.303623546,"cat":"Sites of Grace","group":"Locations","title":"Consecrated Snowfield Catacombs","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"10502","x":0.259384345,"y":0.303780704,"cat":"Crafting Materials","group":"Items","title":"Sliver of Meat - 6x Volcano Cave","desc":"<p>Material. Can be looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Volcano+Cave' target=\"blank\">Volcano Cave</a>, lying in the corner of a room guarded by <a class=\"wiki_link\" title=\"blank\" href='https://eldenring.wiki.fextralife.com/Demi-Human' target=\"blank\">Demi-Human</a> Enemies</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"4491","x":0.520789127,"y":0.304050829,"cat":"Locations","group":"Locations","title":"Yelough Anix Tunnel","desc":"Tunnels in Western Consecrated Snowfield, rich in very rare smithing materials.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tunnel.png?h=40"},{"id":"3175","x":0.579162988,"y":0.30417291,"cat":"Crafting Materials","group":"Items","title":"Lump of Flesh","desc":"Crafting Material. Found on a corpse on the field.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"4493","x":0.515447384,"y":0.304203429,"cat":"Spells","group":"Equipment","title":"Meteorite of Astel","desc":"Gravity Sorcery. Dropped by <a href='https://eldenring.wiki.fextralife.com/Astel,+Stars+of+Darkness' target=\"_blank\">Astel, Stars of Darkness</a>, the boss of Yelough Anix Tunnel.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-purplespell.png?h=40"},{"id":"3452","x":0.586823338,"y":0.304294991,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [8] - Consecrated Snowfield Catacombs","desc":"Upgrade material. One is found in the first room with a frost trap.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"10398","x":0.270355902,"y":0.304675962,"cat":"Consumables","group":"Items","title":"Poison Grease - 2x Volcano Cave Entrance","desc":"<p>Consumable/ Looted from a corpse outside <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Volcano+Cave' target=\"blank\">Volcano Cave</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2822","x":0.339412885,"y":0.304691753,"cat":"Locations","group":"Locations","title":"West Windmill Pasture","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-windmill.png?h=40"},{"id":"5755","x":0.581848977,"y":0.304783315,"cat":"Locations","group":"Locations","title":"Consecrated Snowfield Catacombs","desc":"Hidden by the snowstorm, Catacombs with valuable Grave Glovewort materials 8, 9 and Great Grave Glovewort.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"12357","x":0.574027839,"y":0.305085635,"cat":"Crafting Materials","group":"Items","title":"Old Fang - 2x Consecrated Snowfield","desc":"Crafting Material. Looted from a body in the middle of a bout between <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wandering+Nobles' target=\"blank\">Wandering Nobles</a> and <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wolf' target=\"blank\">Wolf</a> enemies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"4492","x":0.517461696,"y":0.305088518,"cat":"Bosses","group":"Characters","title":"Astel, Stars of Darkness","desc":"Boss of <a href='https://eldenring.wiki.fextralife.com/Yelough+Anix+Tunnel' target=\"_blank\">Yelough Anix Tunnel</a> in Consecrated Snowfield. Drops the <a href='https://eldenring.wiki.fextralife.com/Meteorite+of+Astel' target=\"_blank\">Meteorite of Astel</a> spell upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"4577","x":0.523624865,"y":0.305210599,"cat":"Sites of Grace","group":"Locations","title":"Yelough Anix Tunnel Site of Grace","desc":"Located inside <a href='https://eldenring.wiki.fextralife.com/Yelough+Anix+Tunnel' target=\"_blank\">Yelough Anix Tunnel</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3167","x":0.261937075,"y":0.305668401,"cat":"Weapons","group":"Equipment","title":"Jar Cannon","desc":"Ballista. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Demi-Human+Queen+Margot'>Demi-Human Queen Margot</a> when defeated.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ballista.png?h=40"},{"id":"4649","x":0.536933402,"y":0.305790482,"cat":"Talismans","group":"Equipment","title":"Stalwart Horn Charm +1","desc":"Found to the east of <a href='https://eldenring.wiki.fextralife.com/Yelough+Anix+Tunnel' target=\"_blank\">Yelough Anix Tunnel</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"12356","x":0.5653856,"y":0.305791138,"cat":"Consumables","group":"Items","title":"Golden Rune [11] - Consecrated Snowfield","desc":"Found north of the Consecrated Snowfield Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5848","x":0.375238199,"y":0.305912563,"cat":"Locations","group":"Locations","title":"Village Windmill Pasture","desc":"A windmill with two stables, found near <a href='https://eldenring.wiki.fextralife.com/Windmill+Village' target=\"_blank\">Dominula, Windmill Village</a>. The windmill here is still functional but the area has been taken over by <a href='https://eldenring.wiki.fextralife.com/Misbegotten' target=\"_blank\">Misbegotten</a> creatures.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-windmill.png?h=40"},{"id":"10400","x":0.260550699,"y":0.30594764,"cat":"Crafting Materials","group":"Items","title":"Lump of Flesh - 5x Volcano Cave","desc":"<p>Material. Looted from a body at the bottom of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Volcano+Cave' target=\"blank\">Volcano Cave</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6058","x":0.563510468,"y":0.306187247,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed (Consecrated Snowfield)","desc":"Flask Upgrade Material. Found by a pillar within the snowstorm, near a cookbook north from Consecrated Snowfield site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"2981","x":0.584828133,"y":0.306217765,"cat":"Armor","group":"Equipment","title":"Imp Head (Elder)","desc":"Found as a treasure inside <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/consecrated+snowfield+catacombs'>Consecrated Snowfield Catacombs</a>. Inside a room on the second floor, guarded by a <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/burial+tree+watchdog'>Burial Tree Watchdog</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"8603","x":0.520973002,"y":0.30670609,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - Yelough Anix Tunnel","desc":"Upgrade Material. Multiple found in the <a href='https://eldenring.wiki.fextralife.com/Yelough+Anix+Tunnel' target=\"_blank\">Yelough Anix Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5421","x":0.387316846,"y":0.307408057,"cat":"Weapons","group":"Equipment","title":"Celebrant's Skull","desc":"Warhammer. Found on a corpse at the cliff directly north from Windmill village site of grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-warhammer.png?h=40"},{"id":"10394","x":0.274525913,"y":0.307539248,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily - 1x Mt. Gelmir Northern Cliffs","desc":"<p>Found on the edge of a cliff in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8755","x":0.390827734,"y":0.307591179,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Godskin Apostle","desc":"Summoning Pool Effigy located by the path before the switchback, next to the stake of Marika. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"8243","x":0.579273511,"y":0.30771326,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Consecrated Snowfield Catacombs","desc":"Summoning Pool Effigy found In front of the Boss Doors of the Consecrated Snowfield Catacombs in the Consecrated Snowfield. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4496","x":0.518378342,"y":0.308140543,"cat":"Upgrade Materials","group":"Items","title":"Ancient Dragon Smithing Stone - 1x (Yelough Anix Tunnel)","desc":"Upgrade Material. In the room with the wooden walkways, there is a lower area you can drop down to in the center. Defeat the <a href='https://eldenring.wiki.fextralife.com/Alabaster+Lord' target=\"_blank\">Alabaster Lord</a> found here and you can loot the stone off of the body in the back.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3506","x":0.587067499,"y":0.309025629,"cat":"Upgrade Materials","group":"Items","title":"Great Grave Glovewort - Consecrated Snowfield Catacombs","desc":"Upgrade Material. Dropped by the boss of Consecrated Snowfield Catacombs, Putrid Grave Warden Duelist.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"4407","x":0.565641791,"y":0.309438755,"cat":"Locations","group":"Locations","title":"Enemy Caravan 1 (Consecrated Snowfield)","desc":"Enemy Caravan. Loot the chest to obtain <a href='https://eldenring.wiki.fextralife.com/St+Trina's+Torch'>St. Trina's Torch</a> Note: This caravan only spawns at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-wagon.png?h=40"},{"id":"3177","x":0.57743432,"y":0.309452912,"cat":"Consumables","group":"Items","title":"Rejuvenating Boluses","desc":"Consumable Item. Found on a corpse by jumping on a trap to access a higher area of the Consecrated Snowfield Catacombs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2982","x":0.582030359,"y":0.309727596,"cat":"Armor","group":"Equipment","title":"Rotten Gravekeeper Cloak","desc":"Dropped by the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/bosses'>Boss</a> of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/consecrated+snowfield+catacombs'>Consecrated Snowfield Catacombs</a> in Consecrated Snowfield, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/putrid+grave+warden+duelist'>Putrid Grave Warden Duelist</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"2823","x":0.352566951,"y":0.31015488,"cat":"Sites of Grace","group":"Locations","title":"Road of Iniquity Side Path","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3505","x":0.584675537,"y":0.310307479,"cat":"Bosses","group":"Characters","title":"Putrid Grave Warden Duelist","desc":"Boss of the <a href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield+Catacombs' target=\"_blank\">Consecrated Snowfield Catacombs</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Rotten+Gravekeeper+Cloak' target=\"_blank\">Rotten Gravekeeper Cloak</a> and <a href='https://eldenring.wiki.fextralife.com/Great+Grave+Glovewort' target=\"_blank\">Great Grave Glovewort</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"1194","x":0.31624753,"y":0.310551642,"cat":"Consumables","group":"Items","title":"Starlight Shards C","desc":"Consumable Item. Found in front of a crescent bowl-shaped stone sundial at the edge of the cliffs behind the castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"9804","x":0.321258356,"y":0.310551642,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily - Shaded Castle Outskirts","desc":"Material. Can be scavenged Found on the cliff behind the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Shaded+Castle' target=\"blank\">Shaded Castle</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3451","x":0.579936954,"y":0.311955573,"cat":"Consumables","group":"Items","title":"Root Resin","desc":"Consumable item. 4x Found on a corpse on the first trap room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5845","x":0.387168054,"y":0.312382856,"cat":"Locations","group":"Locations","title":"Dominula, Windmill Village","desc":"The ruins of a village of windmills in northern <a href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"_blank\">Altus Plateau</a>. Inhabitated by a <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle'>Godskin Apostle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dominula.png?h=40"},{"id":"3247","x":0.380574544,"y":0.312413379,"cat":"Sites of Grace","group":"Locations","title":"Windmill Village","desc":"Site of Grace in the Windmill Village","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2453","x":0.311430609,"y":0.31253546,"cat":"Shields","group":"Equipment","title":"Briar Greatshield","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Elemer+of+the+Briar' target=\"_blank\"> Elemer of the Briar</a> inside the <a href='https://eldenring.wiki.fextralife.com/The+Shaded+Castle' target=\"_blank\">The Shaded Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"2454","x":0.313475445,"y":0.3125965,"cat":"Weapons","group":"Equipment","title":"Marais Executioner's Sword","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Elemer+of+the+Briar' target=\"_blank\">Elemer of the Briar</a> inside the <a href='https://eldenring.wiki.fextralife.com/The+Shaded+Castle' target=\"_blank\">The Shaded Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"2940","x":0.316496617,"y":0.313145865,"cat":"Key Items","group":"Items","title":"Perfumer's Cookbook [2]","desc":"Found on a corpse sitting on a chair on the roof of the northwestern building. You can reach this area by climbing a series of ladders in the Castellan's Hall building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"2294","x":0.276126536,"y":0.313359504,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud (A)","desc":"A Sacramental Bud can be found at the edge of the cliffs, red buds on a small white tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7402","x":0.59286747,"y":0.313573148,"cat":"Key Items","group":"Items","title":"Lost Ashes of War - 1x Mountaintops of the Giants","desc":"Key Item. Found on a corpse sitting on a chair in the narrow stretch heading north in Mountaintops of the Giants.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2846","x":0.32476633,"y":0.313725748,"cat":"Crafting Materials","group":"Items","title":"Gold Firefly - 2x The Shaded Casle","desc":"2 Gold fireflies can be found on a body at the end of a room full of statues. There are 2 Page enemies within this room as well, 1 hidden behind the statues and one on top of the stairs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3563","x":0.644709361,"y":0.313725748,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [7] - Flame Peak","desc":"Upgrade Material. Drops from a <a href='https://eldenring.wiki.fextralife.com/Lesser+Spider+Hand' target=\"_blank\"> Lesser Spider Hand</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3160","x":0.319059092,"y":0.31403095,"cat":"Crafting Materials","group":"Items","title":"Hefty Beast Bone - 4x The Shaded Castle","desc":"Found on a body on the walkway up in the castle area, to the right when exiting the first room after the ladder up.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2204","x":0.298123408,"y":0.314122513,"cat":"Weapons","group":"Equipment","title":"Antspur Rapier","desc":"Thrusting Sword. Dropped by <a href='https://eldenring.wiki.fextralife.com/Maleigh+Marais,+Shaded+Castle+Castellan'>Maleigh Marais, Shaded Castle Castellan</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-thrusting_sword.png?h=40"},{"id":"3172","x":0.558292122,"y":0.314336153,"cat":"Key Items","group":"Items","title":"Nomadic Warrior's Cookbook [23]","desc":"On a corpse lying by the road soon after the first Site of Grace of the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"2845","x":0.320703436,"y":0.314671877,"cat":"Consumables","group":"Items","title":"Rot Grease - 3x The Shaded Castle","desc":"Weapon Coating. Found on a body in the middle of the raised garden-like area in the main keep.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2847","x":0.322821843,"y":0.314763436,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] E - The Shaded Castle","desc":"Upgrade Material. Found on a body being chewed up by a <a href='https://eldenring.wiki.fextralife.com/Rotten+Stray' target=\"_blank\">Rotten Stray</a> on the roof of the northeastern building. This can be accessed by crossing the northern ramparts from the northwestern building and then climbing up the stairs in the northeastern building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6365","x":0.396171734,"y":0.314885517,"cat":"Spells","group":"Equipment","title":"Fire's Deadly","desc":"Can be found at Windmill Heights southeast overlook, south of <a href='https://eldenring.wiki.fextralife.com/Windmill+Village' target=\"_blank\">Windmill Village</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"2840","x":0.312986827,"y":0.314916039,"cat":"Key Items","group":"Items","title":"Valkyrie's Prosthesis","desc":"Key Item. Found by climbing up the ladder in the central-western section of the courtyard that leads up to the top of the inner walls. Follow the walls northwest to find a room with a chest surrounded by statues and guarded by a single <a href='https://eldenring.wiki.fextralife.com/Cleanrot+Knight' target=\"_blank\">Cleanrot Knight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"5834","x":0.343713617,"y":0.315099161,"cat":"Weapons","group":"Equipment","title":"Great Stars","desc":"On a guarded wagon in Altus Plateau, traveling on the road SouthWest of the Road of Iniquity Side Path site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-warhammer.png?h=40"},{"id":"7351","x":0.296292213,"y":0.315434882,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - West from The Shaded Castle","desc":"Upgrade Material. Found on a corpse leaning against a rock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5903","x":0.27951446,"y":0.315526444,"cat":"Weapons","group":"Equipment","title":"Scavenger's Curved Sword","desc":"Found in <a href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"_blank\">Mt. Gelmir</a> , on a corpse near a Grafted Scion across a stone pillar-bridge northwest of the First Mt. Gelmir Campsite site of grace. The corpse closest to the ladder has the blade.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedsword.png?h=40"},{"id":"2452","x":0.316163051,"y":0.315709566,"cat":"Bosses","group":"Characters","title":"Elemer of the Briar","desc":"Found inside <a href='https://eldenring.wiki.fextralife.com/The+Shaded+Castle' target=\"_blank\"> The Shaded Castle</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Marais+Executioner's+Sword' target=\"_blank\"> Marais Executioner's Sword</a> and <a href='https://eldenring.wiki.fextralife.com/Briar+Greatshield' target=\"_blank\">Briar Greatshield</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3527","x":0.633783233,"y":0.315801125,"cat":"Sites of Grace","group":"Locations","title":"Giants' Gravepost","desc":"Site of grace at the edge of the hanging chain. Near a map shard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2202","x":0.299410678,"y":0.315862165,"cat":"NPC Invaders","group":"Characters","title":"Maleigh Marais, Shaded Castle Castellan","desc":"Non-Invader Hostile NPC. Found in the fields west of <a href='https://eldenring.wiki.fextralife.com/The+Shaded+Castle' target=\"_blank\">The Shaded Castle</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Antspur+Rapier' target=\"_blank\">Antspur Rapier</a>, <a href='https://eldenring.wiki.fextralife.com/Marais+Mask' target=\"_blank\">Marais Mask</a> and <a href='https://eldenring.wiki.fextralife.com/Marais+Robe' target=\"_blank\">Marais Robe</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"3039","x":0.318111421,"y":0.316014768,"cat":"Sites of Grace","group":"Locations","title":"Castellan's Hall","desc":"Site of Grace that shows up after defeating the Boss in The Shaded Castle","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1332","x":0.274447918,"y":0.316075809,"cat":"NPCs","group":"Characters","title":"Nomadic Merchant Mt. Gelmir","desc":"Nomadic Merchant. General Goods vendor found sitting by a campfire on a ledge halfway up Mt. Gelmir. Sells <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stonesword+Key'>Stonesword Key</a> and a full set of Confessor armor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"26851","x":0.384938305,"y":0.316106329,"cat":"Consumables","group":"Items","title":"Rune Arc - Dominula, Windmill Village","desc":"<p>Consumable Item. Found on a corpse inside a small shack in <a class=\"wiki_link\" title=\"Dominula, Windmill Village\" href='https://eldenring.wiki.fextralife.com/Windmill+Village'target=\"_blank \">Dominula, Windmill Village</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8844","x":0.319944484,"y":0.316228408,"cat":"NPCs","group":"Characters","title":"Patches (Fourth Location)","desc":"<p>NPC. You can then find him at the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Shaded+Castle' target=\"\">Shaded Castle</a> before the boss and he gives you <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Dancer's+Castanets' target=\"\">Dancer's Castanets</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"2205","x":0.29757405,"y":0.316258931,"cat":"Armor","group":"Equipment","title":"Marais Mask","desc":"Light Helm. Dropped by <a href='https://eldenring.wiki.fextralife.com/Maleigh+Marais,+Shaded+Castle+Castellan'>Maleigh Marais, Shaded Castle Castellan</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"3573","x":0.63826923,"y":0.316350489,"cat":"Flask Upgrades","group":"Items","title":"Crimsonwhorl Bubbletear","desc":"On a cliff ledge south of Giants' Gravepost (above the grace point, the ledge is accessed by going north-east from the Foot of the Forge grace point, Just follow the edge of the cliff until you see the path going above Giant's Gravepost).","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"10395","x":0.276579275,"y":0.316690769,"cat":"Consumables","group":"Items","title":"Great Arrow - 5x Mt. Gelmir","desc":"<p>Consumable Ammunition. Looted from a body atop one of the ladders in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8845","x":0.321350452,"y":0.316777773,"cat":"Key Items","group":"Items","title":"Dancer's Castanets","desc":"<p>Key Item. Given by <a class=\"wiki_link\" title=\"Elden Ring Patches\" href='https://eldenring.wiki.fextralife.com/Patches'>Patches</a> in <a class=\"wiki_link\" title=\"Elden Ring Shaded Castle\" href='https://eldenring.wiki.fextralife.com/Shaded+Castle'>Shaded Castle</a>, before the boss room, after killing <a class=\"wiki_link\" title=\"Elden Ring Rykard, Lord of Blasphemy\" href='https://eldenring.wiki.fextralife.com/Rykard,+Lord+of+Blasphemy'>Rykard, Lord of Blasphemy</a> and talking to him in <a class=\"wiki_link\" title=\"Elden Ring Volcano Manor\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3174","x":0.562350657,"y":0.317235579,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] - Consecrated Snowfield","desc":"Upgrade Material. Defeat a Teardrop Scarab to obtain it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"5808","x":0.353299843,"y":0.317235579,"cat":"NPCs","group":"Characters","title":"Goldmask","desc":"Found around the Forest-Spanning Greatbridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"2828","x":0.317201313,"y":0.317479741,"cat":"Sites of Grace","group":"Locations","title":"Shaded Castle Inner Gate","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"10229","x":0.257453278,"y":0.317610932,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Ninth Mt. Gelmir Campsite","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>, Immediately west of Ninth <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a> Campsite site of grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"2839","x":0.314639194,"y":0.31763234,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] C - The Shaded Castle","desc":"Upgrade Material. Found on a body in the corner behind the Large Poison Flower, in the northwest of the outer courtyard. You can access this area by getting up on the western ramparts and following it north past the rock barricade.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2206","x":0.299008484,"y":0.31769338,"cat":"Armor","group":"Equipment","title":"Marais Robe","desc":"Light Chest Armor. Dropped by <a href='https://eldenring.wiki.fextralife.com/Maleigh+Marais,+Shaded+Castle+Castellan'>Maleigh Marais, Shaded Castle Castellan</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"7678","x":0.318756672,"y":0.317876502,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - The Shaded Castle","desc":"Rune Consumable. Found on a corpse laying on the outer edges of the northwestern building. You can reach this area by climbing a ladder along the western walls of the main keep's grounds.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3270","x":0.632500928,"y":0.317907024,"cat":"Maps","group":"Locations","title":"Map (Mountaintops of The Giants, East)","desc":"Found at the altar. You can arrive by walking on the chain from the enemy encampment.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"10396","x":0.268046977,"y":0.317938711,"cat":"Crafting Materials","group":"Items","title":"Eye of Yelough -1x Mt. Gelmir","desc":"Material. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>, behind the sword monument","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"12353","x":0.547162097,"y":0.317949645,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Consecrated Snowfield South","desc":"Found in a Rune graveyard south Consecrated Snowfield","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10225","x":0.349669734,"y":0.317983961,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Road of Iniquity","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>, at the drop off south of the Road of Iniquity Side Path Site of Grace where the collapsed bridge is.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"5787","x":0.356857968,"y":0.318090146,"cat":"Spells","group":"Equipment","title":"Protection of the Erdtree","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a>. It can be found on top of the stone ruin.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"1324","x":0.259648082,"y":0.318181705,"cat":"Sites of Grace","group":"Locations","title":"Ninth Mt. Gelmir Campsite","desc":"Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1333","x":0.236640292,"y":0.318181705,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Northwest Mt. Gelmir","desc":"Flask Upgrade Material. One can be found underneath a Phantom Tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"9802","x":0.352703432,"y":0.31863951,"cat":"Consumables","group":"Items","title":"Dragonwound Grease -1x Atlus Plateau","desc":"Consumable. Found on a corpse hanging from the edge atop of the collapsed bridge in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>, near the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Goldmask' target=\"\">Goldmask</a> NPC.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"12352","x":0.546279206,"y":0.318781323,"cat":"Consumables","group":"Items","title":"Golden Rune [9] - Consecrated Snowfield Sout","desc":"Found in a Rune graveyard south Consecrated Snowfield","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2285","x":0.278021072,"y":0.31885315,"cat":"Bosses","group":"Characters","title":"Grafted Scion","desc":"A Grafted Scion can be found at the destroyed camp across the stone pillar, at the bottom of the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"10397","x":0.269643979,"y":0.318857709,"cat":"Crafting Materials","group":"Items","title":"Eye of Yelough - 3x Mt. Gelmir","desc":"<p>Material. Looted from a corpse behind a cart in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2289","x":0.279699667,"y":0.318944713,"cat":"Consumables","group":"Items","title":"Soporific Grease (B)","desc":"2 Soporific Grease can be found on one of the bodies in the destroyed camp at the bottom of the cliff here across the stone pillar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2844","x":0.325044831,"y":0.318975231,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] D - The Shaded Castle","desc":"Upgrade Material. Found on a body in the corner atop the eastern inner walls. You can access this area by climbing a ladder in the eastern side of the inner courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2837","x":0.313722348,"y":0.319127834,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [4] - The Shaded Castle","desc":"Spirit Ash Upgrade Material. Found on one of the rocks near the dead tree at the western end of the outer courtyard of <a href='https://eldenring.wiki.fextralife.com/The+Shaded+Castle' target=\"_blank\">The Shaded Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"4673","x":0.549899933,"y":0.319280434,"cat":"Weapons","group":"Equipment","title":"Rotten Battle Hammer","desc":"Warhammer. Guaranteed drop from the <a href='https://eldenring.wiki.fextralife.com/Rotten+Duelist' target=\"_blank\">Rotten Duelist</a> enemy in the area","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-warhammer.png?h=40"},{"id":"12351","x":0.547472716,"y":0.319280434,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - Consecrated Snowfield South","desc":"Found in a Rune graveyard south Consecrated Snowfield","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2300","x":0.254216482,"y":0.319310956,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly","desc":"An exceedingly rare butterfly to find, can be found west on the edge of the mountain near the Ninth Mt. Gelmir Campsite Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7677","x":0.323182065,"y":0.319524596,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] B - The Shaded Castle","desc":"Upgrade Material. Found on a body inside a wooden structure that looks like a stable, pressed against the eastern section of the inner courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"9801","x":0.366620805,"y":0.319555118,"cat":"Consumables","group":"Items","title":"Poison Grease - 1x Altus Plateau","desc":"Consumable. Looted from a body on the village near the Minor Erdtree in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10393","x":0.272922458,"y":0.319742794,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud - 4x Minor Erdtree (Mt. Gelmir)","desc":"<p>Can be gathered north of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>, <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Mt.+Gelmir)' target=\"blank\">Minor Erdtree (Mt. Gelmir)</a> surrounded by bow wielding <a class=\"wiki_link\" href='https://eldenring.wiki.fextralife.com/Marionette+Soldier'>Marionette Soldiers</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2838","x":0.313051261,"y":0.319890839,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5] - The Shaded Castle","desc":"Upgrade Material. Found on a body by the dead tree on the western end of the outer courtyard, next to the western rampart.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"12354","x":0.54608186,"y":0.319963982,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Consecrated Snowfield South","desc":"Found in a Rune graveyard south Consecrated Snowfield","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2310","x":0.275668738,"y":0.319982401,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud (B)","desc":"2 small white plants with red Sacramental Buds can be found on a cliff in Mt. Gelmir. On the edge of the cliffside down the ladder from the Nomadic Merchant Mt. Gelmir.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2829","x":0.325530443,"y":0.319982401,"cat":"Key Items","group":"Items","title":"Champion's Song Painting","desc":"Champion's Song painting found in a small wooden structure on the side of the eastern walls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"10503","x":0.242455683,"y":0.320170078,"cat":"Crafting Materials","group":"Items","title":"Smoldering Butterfly - 4x Mt. Gelmir Northwest","desc":"<p>Material. Looted from a corpse sitting near some rocks in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>, after the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Fallingstar+Beast' target=\"blank\">Fallingstar Beast</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2841","x":0.317656334,"y":0.320257082,"cat":"Consumables","group":"Items","title":"Golden Rune [6] B - The Shaded Castle","desc":"Rune Consumable. Found on a body sat in front of a series of tombstones in the inner courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1193","x":0.33419682,"y":0.320318122,"cat":"Crafting Materials","group":"Items","title":"Gravel Stone","desc":"Crafting Material. Two obtained by a grave marker overlooking the cliffs. Guarded by a <a href='https://eldenring.wiki.fextralife.com/Pumpkin+Head' target=\"_blank\">Pumpkin Head</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1334","x":0.239446874,"y":0.320348644,"cat":"Consumables","group":"Items","title":"Cuckoo Glintstone (C)","desc":"Pillage from the body near the golden tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7675","x":0.326813353,"y":0.320409685,"cat":"Consumables","group":"Items","title":"Golden Rune [6] C - The Shaded Castle","desc":"Rune Consumable. Found on a body sitting on the eastern battlements.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2306","x":0.273992444,"y":0.320440203,"cat":"Consumables","group":"Items","title":"Cuckoo Glintstone (E)","desc":"Crafting Material. Found on the body of the soldier shot to death by the surrounding Marionette Soldiers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1195","x":0.320127632,"y":0.320470725,"cat":"Locations","group":"Locations","title":"The Shaded Castle","desc":"An abandoned and Decrepit castle found in the northern region between the Mt. Gelmir and the Altus Plateau regions. The castle is half sunken into a poisonous bog, with the air tinged yellow by the fumes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shadedcastle.png?h=40"},{"id":"12355","x":0.547362896,"y":0.320517163,"cat":"Consumables","group":"Items","title":"Golden Rune [11] - Consecrated Snowfield South","desc":"Found in a Rune graveyard south Consecrated Snowfield","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5901","x":0.344662408,"y":0.320775928,"cat":"Locations","group":"Locations","title":"Enemy Caravan (Altus Plateau)","desc":"Enemy Caravan traveling the Road of Iniquity. Loot <a href='https://eldenring.wiki.fextralife.com/Great+Stars' target=_blank\">Great Stars</a> from its chest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-wagon.png?h=40"},{"id":"9817","x":0.351045272,"y":0.321225889,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly - 1x Altus Plateau","desc":"Material. Can be gathered under the broken bridge in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a><br /><br />","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3242","x":0.288485207,"y":0.321264252,"cat":"Locations","group":"Locations","title":"Corpse-Stench Shack","desc":"A small shack in northern <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Mt+Gelmir'>Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"5820","x":0.399451319,"y":0.321569455,"cat":"Weapons","group":"Equipment","title":"Greatbow","desc":"Found in a chest at the top of the <a href='https://eldenring.wiki.fextralife.com/Highway+Lookout+Tower+(Altus+Plateau)' target=\"_blank\">Highway Lookout Tower</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bow.png?h=40"},{"id":"3574","x":0.291383626,"y":0.321813617,"cat":"Weapons","group":"Equipment","title":"Butchering Knife","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Greataxes'>Greataxe</a>. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Anastasia,+Tarnished-Eater'>Anastasia, Tarnished-Eater</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greataxe.png?h=40"},{"id":"3403","x":0.286074423,"y":0.32217986,"cat":"Spells","group":"Equipment","title":"Golden Vow (Spell)","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Incantations'>Incantation</a>. Found on a corpse inside the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Corpse-Stench+Shack'>Corpse-Stench Shack</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"2966","x":0.55496314,"y":0.3222409,"cat":"Sites of Grace","group":"Locations","title":"Consecrated Snowfield","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4672","x":0.549019974,"y":0.322271418,"cat":"Armor","group":"Equipment","title":"Rotten Duelist Helm","desc":"Guaranteed Drop from the <a href='https://eldenring.wiki.fextralife.com/Rotten+Duelist' target=\"_blank\">Rotten Duelist</a> enemy in the area","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"9531","x":0.273169162,"y":0.322291389,"cat":"Consumables","group":"Items","title":"Drawstring Fire Grease - 3x Mt. Gelmir","desc":"Consumable. Can be found on a corpse at <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a> near the Minor Erdtree and the broken bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2842","x":0.321407661,"y":0.322393499,"cat":"Key Items","group":"Items","title":"Perfume Bottle - The Shaded Castle","desc":"Key Crafting Item. Found on a body hanging by the edge of the top part of the inner ramparts. You can reach this area by climbing a ladder in the eastern section of the inner courtyard and following the ramparts as it curves to the west.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3158","x":0.324554267,"y":0.322515581,"cat":"Consumables","group":"Items","title":"Poisonbone Dart - 5x The Shaded Castle","desc":"Offensive Throwable. 5x found on a body in the middle of the poisoned area by the eastern rampart.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1335","x":0.238990384,"y":0.322576621,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Through and Through","desc":"Dropped by an invisible <a class=\"wiki_link\" title=\"Elden Ring Teardrop Scarab\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"\">Teardrop Scarab</a>. You will see glowing footprints appearing in a set pattern around the area. Stand in front of its path and attack as it approaches you to reveal the creature.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"10388","x":0.292649449,"y":0.322814048,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud - 4x Mt. Gelmir","desc":"<p>Material. Can be gathered in east <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>, sprouting from small mounds of corpses</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1142","x":0.281435396,"y":0.323248067,"cat":"Key Items","group":"Items","title":"Stonesword Key - Corpse-Stench Shack","desc":"<strong>Stonesword Key</strong> found on a corpse on a broken bridge near <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/corpse-stench+shack'>Corpse-Stench Shack</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2830","x":0.318878479,"y":0.323248067,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] A - The Shaded Castle","desc":"Upgrade Material. Found on a body hanging off a ledge inside a wooden structure in the central outer courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2938","x":0.32528716,"y":0.323309107,"cat":"Key Items","group":"Items","title":"Stonesword Key - The Shaded Castle","desc":"Found on a body on a stone ledge, reached by traversing the rocks leading from the eastern wall all the way to the ledge. A set of slugs can be found underneath looking at the body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2558","x":0.266849318,"y":0.32340067,"cat":"Flask Upgrades","group":"Items","title":"Leaden Hardtear","desc":"Dropped by the <a href=\"Ulcerated+Tree+Spirit\" target=\"_blank\">Ulcerated Tree Spirit</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"3169","x":0.25982536,"y":0.32340067,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] 5x","desc":"Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Full-Grown+Fallingstar+Beast'>Full-Grown Fallingstar Beast</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"9532","x":0.278967223,"y":0.323599945,"cat":"Crafting Materials","group":"Items","title":"Beast Blood - 3x Mt. Gelmir","desc":"Crafting Material. Can be found on a corpse hanging from the upper part of the broken bridge in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3243","x":0.289887476,"y":0.32367535,"cat":"NPC Invaders","group":"Characters","title":"Anastasia, Tarnished-Eater B","desc":"NPC Invader. The second time Anastasia invades is as the player approaches the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Corpse-Stench+Shack'>Corpse-Stench Shack</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"3575","x":0.291474511,"y":0.323705872,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy","desc":"Multiplayer Item. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Anastasia,+Tarnished-Eater'>Anastasia, Tarnished-Eater</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"2836","x":0.311860199,"y":0.323736391,"cat":"Consumables","group":"Items","title":"Neutralizing Boluses - 2x The Shaded Castle","desc":"2x found on a body on the western ramparts of <a href='https://eldenring.wiki.fextralife.com/The+Shaded+Castle' target=\"_blank\">The Shaded Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10351","x":0.258325027,"y":0.323863031,"cat":"Consumables","group":"Items","title":"Poisonbone Dart - 10x Seethewater Cave","desc":"Ammunition Consumable. Looted from a corpse surrounded by 2 rats in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Seethewater+Cave' target=\"blank\">Seethewater Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1337","x":0.256230259,"y":0.324041593,"cat":"Bosses","group":"Characters","title":"Full-Grown Fallingstar Beast","desc":"Optional Field Boss found high up in Mt. Gelmir.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3404","x":0.26971819,"y":0.324102634,"cat":"Flask Upgrades","group":"Items","title":"Cerulean Hidden Tear","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Flask+of+Wondrous+Physick'>Flask of Wondrous Physick</a> Upgrade. Dropped by the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Ulcerated+Tree+Spirit'>Ulcerated Tree Spirit</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"10504","x":0.233540707,"y":0.32466905,"cat":"Consumables","group":"Items","title":"Golden Rune [3] -  Northwest Mt. Gelmir","desc":"<p>Looted from a corpse guarded by <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Fingercreeper' target=\"blank\">Fingercreeper</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3661","x":0.646486363,"y":0.324743561,"cat":"Consumables","group":"Items","title":"Golden Rune [10] B - Flame Peak","desc":"Rune Consumable. Found on a corpse below the frozen body of a giant.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2276","x":0.228734387,"y":0.324774079,"cat":"Key Items","group":"Items","title":"Stonesword Key - Northwest Mt. Gelmir","desc":"Key Item. Found under a large burnt tree near the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2832","x":0.3188185,"y":0.32483512,"cat":"Consumables","group":"Items","title":"Drawstring Fire Grease - 2x The Shaded Castle","desc":"Found on a body in the corner between some rubble and a sunken building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2363","x":0.251193279,"y":0.325109804,"cat":"Weapons","group":"Equipment","title":"Fallingstar Beast Jaw","desc":"Colossal Weapon Dropped by <a href='https://eldenring.wiki.fextralife.com/Full-Grown+Fallingstar+Beast' target=\"_blank\"> Full-Grown Fallingstar Beast</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossal_weapon.png?h=40"},{"id":"3662","x":0.622039909,"y":0.325506566,"cat":"Consumables","group":"Items","title":"Warming Stone - Flame Peak","desc":"Consumable. 2 Warming Stones found on a body in the Mountaintops of the Giants.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"9528","x":0.261133296,"y":0.325542307,"cat":"Consumables","group":"Items","title":"Fan Daggers - 5x Mt. Gelmir","desc":"Offensive Consumable. Can be found on a corpse at <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a> near the Minor Erdtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1233","x":0.268227157,"y":0.325689687,"cat":"Bosses","group":"Characters","title":"Ulcerated Tree Spirit (Mt. Gelmir)","desc":"Boss roaming Mt. Gelmir. Drops <a href='https://eldenring.wiki.fextralife.com/Leaden+Hardtear' target=\"_blank\">Leaden Hardtear</a> and <a href='https://eldenring.wiki.fextralife.com/Cerulean+Hidden+Tear' target=\"_blank\"> Cerulean Hidden Tear</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5732","x":0.398092518,"y":0.325720209,"cat":"Locations","group":"Locations","title":"Highway Lookout Tower (Altus Plateau)","desc":"A lookout tower overlooking the main road heading into the Capital Outskirts' northwest entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tower.png?h=40"},{"id":"10505","x":0.238964364,"y":0.326062852,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf - 1x Mt. Gelmir","desc":"<p>Material. Can be gathered in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"\"blank>Mt. Gelmir</a>, near the border of a cliff and a wall</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2827","x":0.323971249,"y":0.326178011,"cat":"Sites of Grace","group":"Locations","title":"Shaded Castle Ramparts","desc":"Site of Grace found on top of one part of the Castle Ramparts","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8757","x":0.248267129,"y":0.326178011,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Path of Iniquity","desc":"Summoning Pool Effigy located near the Path of Iniquity site of grace. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5813","x":0.254964115,"y":0.32641109,"cat":"Key Items","group":"Items","title":"Larval Tear - Mt. Gelmir","desc":"Dropped by Colossal Wormface disguised as charred corpse when defeated. Due East from the Road of Inequities grace, upon entering the ruined camp, and next to the first corpse fire will be the charred remains enemy","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"10392","x":0.283490078,"y":0.326426732,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Mt. Gelmir North","desc":"<p>Looted from a body sprawled atop a rock in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2833","x":0.319855825,"y":0.326635817,"cat":"Consumables","group":"Items","title":"Golden Rune [6] A - The Shaded Castle","desc":"Rune Consumable. Found on a body inside the walls, on top of a broken wooden platform jutting out from the ground.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2835","x":0.321016238,"y":0.327429343,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] B - The Shaded Castle","desc":"Upgrade Material. Found on a body between a large dead tree and the southern ramparts.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3168","x":0.253940074,"y":0.327612465,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5]","desc":"Upgrade Material. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Full-Grown+Fallingstar+Beast'>Full-Grown Fallingstar Beast</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"9529","x":0.267829364,"y":0.327655324,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Mt. Gelmir","desc":"Consumable. Can be found on a corpse at <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a> near the Minor Erdtree. <br /><br />","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"14251","x":0.258441659,"y":0.327722338,"cat":"Bosses","group":"Characters","title":"Wormface - Minor Erdtree (Mt. Gelmir)","desc":"<p> <br />Boss. Wormface Bosses are usually located within the vicinity of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Mt.+Gelmir)' target=\"blank\">Minor Erdtree (Mt. Gelmir)</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"8226","x":0.324828488,"y":0.327734546,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Shaded Castle Ramparts","desc":"Summoning Pool Effigy found next to the Shaded Castle Ramparts site of grace in the Altus Plateau. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1338","x":0.258613382,"y":0.327765064,"cat":"Consumables","group":"Items","title":"Starlight Shards D","desc":"Can be found at the edge in front of the stone statue.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3406","x":0.273654586,"y":0.327856627,"cat":"Locations","group":"Locations","title":"Minor Erdtree (Mt. Gelmir)","desc":"A withered Minor Erdtree found in northern <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Mt+Gelmir'>Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tree.png?h=40"},{"id":"6104","x":0.283907611,"y":0.327948186,"cat":"NPCs","group":"Characters","title":"Patches (Second Location)","desc":"NPC. Seen hiding behind some bushes. Following the glowing stones to the ledge will trigger a cutscene with an ambush.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"10387","x":0.301072049,"y":0.328216135,"cat":"Consumables","group":"Items","title":"Explosive Greatbolt - Mt. Gelmir","desc":"<p>Ammunition. Looted from a corpse in the middle of a battlefield in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6359","x":0.55807834,"y":0.328589113,"cat":"Key Items","group":"Items","title":"Deathroot - Hidden Path to the Haligtree","desc":"Key Item. Found in a chest at the back of the boss room after defeating the <a href='https://eldenring.wiki.fextralife.com/Mimic+Tear' target=\"_blank\">Stray Mimic Tear</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"9803","x":0.323471334,"y":0.328772234,"cat":"Consumables","group":"Items","title":"Poison Grease - 1x Shaded Castle Outskirts","desc":"Consumable. Can be scavenged from a corpse lying in the poison pool outside the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Shaded+Castle' target=\"blank\">Shaded Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"9849","x":0.284610687,"y":0.328894315,"cat":"Key Items","group":"Items","title":"Calm Down Gesture","desc":"Gesture. Obtained fromreturning to <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Patches' target=\"blank\">Patches</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Murkwater+Cave' target=\"blank\">Murkwater Cave</a> after his initial attack. Spare him to obtain the gesture.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"10386","x":0.301950293,"y":0.328945488,"cat":"Consumables","group":"Items","title":"Golden Rune [8] - Mt. Gelmir","desc":"<p>Looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>, found between two formations of rocks.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10249","x":0.261804719,"y":0.328984815,"cat":"Consumables","group":"Items","title":"Golden Rune [7] - Seethewater Cave","desc":"Consumable. Can be looted from a corpse hanging from a ledge in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Seethewater+Cave' target=\"blank\">Seethewater Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2825","x":0.318389016,"y":0.329138477,"cat":"Consumables","group":"Items","title":"Golden Rune [3] D","desc":"Found on a body laid by the wall, surrounded by 4 Poison Slugs","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5773","x":0.357599243,"y":0.329168996,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Minor Erdtree Altus Plateau","desc":"Flask Upgrade Material. Found northwest of the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Altus+Plateau)' target=\"_blank\">Minor Erdtree</a> of <a href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"_blank\">Altus Plateau</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"6358","x":0.554087778,"y":0.329352118,"cat":"Spirit Ashes","group":"Equipment","title":"Blackflame Monk Amon Ashes","desc":"Spirit Ash. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Mimic+Tear' target=\"_blank\">Stray Mimic Tear</a> boss found in the secret catacombs underneath the <a href='https://eldenring.wiki.fextralife.com/Hidden+Path+to+the+Haligtree' target=\"_blank\">Hidden Path to the Haligtree</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"5842","x":0.351992146,"y":0.329413158,"cat":"Armor","group":"Equipment","title":"Radiant Gold Mask","desc":"Part of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/goldmask's+set'>Goldmask's Set</a>. Found on a corpse on the collapsed bridge North-East of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/writheblood+ruins'>Writheblood Ruins</a>. Drop down two times heading South to find the body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"7676","x":0.320160488,"y":0.32944368,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] A - The Shaded Castle","desc":"Upgrade Material. Found on a corpse in an alcove in the southern battlements.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3886","x":0.58801754,"y":0.329474198,"cat":"Spells","group":"Equipment","title":"Briars of Punishment","desc":"Sorcery. Found at the leftmost dead tree next to three Lesser Fire Monks just before the long stone bridge with the Golem Archer at the end in the Mountaintops of the Giants region","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"10509","x":0.586530968,"y":0.329474198,"cat":"Crafting Materials","group":"Items","title":"Arteria Lea - 3x Mountaintops of the Giants","desc":"<p>Material. Looted from a corpse before the stone bridge in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants' target=\"blank\">Mountaintops of the Giants</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10250","x":0.264492754,"y":0.329486703,"cat":"Consumables","group":"Items","title":"Immunizing Cured Meat - Seethewater Cave","desc":"Consumable. Looted from a body on the room with the giant <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Miranda+Sprout' target=\"blank\">Miranda Sprouts</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Seethewater+Cave' target=\"blank\">Seethewater Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3576","x":0.611296898,"y":0.329565761,"cat":"Consumables","group":"Items","title":"Invigorating White Cured Meat - Flame Peak","desc":"Consumable. Found at the bottom of a tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3863","x":0.580811906,"y":0.329626801,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [9] - 2x Giant-Conquering Hero's Grave","desc":"Spirit Ash Upgrade Material. Spirit Ash Upgrade Material. A total of <strong>3</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Giant-Conquering+Hero's+Grave' target=\"_blank\">Giant-Conquering Hero's Grave</a>. <ol> <li>One is found behind the first <a href='https://eldenring.wiki.fextralife.com/Lesser+Burial+Watchdog' target=_blank\">Lesser Burial Watchdog</a> encountered, in a room under the circle of light.</li> <li>When you reach the lift, take it down and then step on the plate again to send it up back up but jump off immediately. Once it's fully raised, you will see an opening in the column. Pull the lever in the nearby alcove and enter the opening in the lift. It will take you further down. At the bottom, check behind the lift column for the second glovewort.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"8210","x":0.270594442,"y":0.329687842,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Seethewater Cave","desc":"Summoning Pool Effigy found under the small ledge just after the Seethwater Cave site of grace in the Mt. Gelmir. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"10389","x":0.287240694,"y":0.329791906,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud - Mt. Gelmir North","desc":"<p>Material. Can be gathered in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>, guarded by two foot soldiers</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6357","x":0.556376771,"y":0.329809923,"cat":"Bosses","group":"Characters","title":"Stray Mimic Tear","desc":"Optional Boss. Found in the secret underground catacombs underneath the <a href='https://eldenring.wiki.fextralife.com/Hidden+Path+to+The+Haligtree' target=\"_blank\">Hidden Path to the Haligtree</a> found by navigating a series of invisible walkways underneath the large staircase in the main hall. See the location page for details on how to reach the boss. Drops the <a href='https://eldenring.wiki.fextralife.com/Blackflame+Monk+Amon+Ashes' target=\"_blank\">Black Flame Monk Ashes</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6360","x":0.552102791,"y":0.329870963,"cat":"Consumables","group":"Items","title":"Hero's Rune [1] - Hidden Path to the Haligtree","desc":"Rune Consumable. Found on a corpse on a balcony before the room with the boss door's lever. This is in the secret catacombs underneath the large staircase, accessed by navigating a series of invisible walkways.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3865","x":0.57876707,"y":0.329962522,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [8] - 3x Giant-Conquering Hero's Grave","desc":"Spirit Ash Upgrade Material. A total of <strong>3</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Giant-Conquering+Hero's+Grave' target=\"_blank\">Giant-Conquering Hero's Grave</a>. <ol> <li>One found in the large hall locked behind an Imp Statue barrier. This is directly above the flamethrower pillar and there is a hole in the ground where a section of the pillar can rise through.</li> <li>Upon reaching the lift, take it to the lower level and then step on the plate again to send it back up. When it's fully raised, you can find an opening in the lift column. Pull the lever in the nearby alcove and go inside the opening in the lift column to descend further down. At the bottom level, sprint past the <a href='https://eldenring.wiki.fextralife.com/Lesser+Burial+Watchdog' target=\"_blank\">Lesser Burial Watchdog</a> and turn right to find the second glovewort behind a second <a href='https://eldenring.wiki.fextralife.com/Lesser+Burial+Watchdog' target=\"_blank\">Lesser Burial Watchdog</a>.</li> <li>Directly after picking up the second glovewort, climb the long ladder in the alcove to the right to reach an otherwise inaccessible area far west of the Troll hall. You can find the third glovewort on the north wall up here.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"3869","x":0.582213933,"y":0.330084603,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [9] - Giant-Conquering Hero's Grave","desc":"Spirit Ash Upgrade Material. <strong>One</strong> found inside the <a href='https://eldenring.wiki.fextralife.com/Giant-Conquering+Hero's+Grave' target=\"_blank\">Giant-Conquering Hero's Grave</a>. <ul> <li>To left of the locked door that leads to the boss, behind the <a href='https://eldenring.wiki.fextralife.com/Troll' target=\"_blank\">Troll</a>.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"10247","x":0.268513113,"y":0.330248543,"cat":"Crafting Materials","group":"Items","title":"Lump of Flesh - Seethewater Cave","desc":"Consumable. Found on a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Seethewater+Cave' target=\"blank\">Seethewater Cave</a>, guarded by some <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Giant+Rats' target=\"blank\">Giant Rats</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1236","x":0.247046016,"y":0.330267725,"cat":"Sites of Grace","group":"Locations","title":"Road of Iniquity","desc":"Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5152","x":0.549662392,"y":0.330450846,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [9] - Hidden Path to the Haligtree","desc":"Spirit Ash Upgrade Material. 3 can be found in the <a href='https://eldenring.wiki.fextralife.com/Hidden+Path+to+the+Haligtree'>Hidden Path to the Haligtree</a>. The first is guarded by two <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/land+octopus'>Land Octopuses</a> and a <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/vulgar+militiamen'>Vulgar Militiaman</a> near the exit to the <a href='https://eldenring.wiki.fextralife.com/Consecrated+Snowfield' target=\"_blank\">Consecrated Snowfield</a>. The next two are found in the secret catacombs below. One is in the first alcove that you can access after jumping down onto the invisible walkways under the staircase. The last one can be found in a third alcove across to the west from the second alcove guarded by two <a href='https://eldenring.wiki.fextralife.com/Vulgar+Militant' target=\"_blank\">Vulgar Militants</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"9545","x":0.276677874,"y":0.33065102,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly - 1x Mt Gelmir","desc":"Crafting Material. Found on a corpse near the edge of a cliff, outside <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Seethewater+Cave' target=\"blank\">Seethewater Cave</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10390","x":0.2865183,"y":0.330699567,"cat":"Consumables","group":"Items","title":"Fire Arrow - Mt. Gelmir","desc":"<p>Ammunition. Looted from a corpse atop of a siege tower in <a class=\"wiki_link\" title=\"blank\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"\">Mt. Gelmir</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"9530","x":0.274573068,"y":0.33090573,"cat":"Consumables","group":"Items","title":"Golden Arrow - 5x Mt. Gelmir","desc":"Bow Ammunition. Found on the back of the Minor Erdtree in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8281","x":0.590025978,"y":0.331244373,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [7] - 3x Giants' Mountaintop Catacombs","desc":"Spirit Ash Upgrade Material. A total of <strong>3</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Giants'+Mountaintop+Catacombs' target=\"_blank\">Giants' Mountaintop Catacombs</a>: <ol> <li>The first one is found by heading straight west from the Site of Grace, in the back wall of the room at the end.</li> <li>Back in the main path from the first lift, head left from the Boss Doors and descend the dungeon's second lift. Continue along the path and then turn right in the room with the statue. Proceed through the hall with the guillotine traps and then take the first left in the next corridor to a room with several <a href='https://eldenring.wiki.fextralife.com/Land+Squirt' target=\"_blank\">Land Squirts</a>. Keep moving forward until you reach a small room at the end of the path with a large <a href='https://eldenring.wiki.fextralife.com/Living+Jar' target=\"_blank\">Living Jar</a>. The second glovewort can be found pressed against the right wall here.</li> <li>From the last glovewort, backtrack into the previous hall and look for an opening in the alcove in the right. Drop down this opening and you will end up in a balcony overlooking a room with a statue that looks identical to the one you previously passed. Head west from the statue and follow the identical pathway through another set of guillotine traps, another room with <a href='https://eldenring.wiki.fextralife.com/Land+Squirt' target=\"_blank\">Land Squirts</a> and another small room at the end with a <a href='https://eldenring.wiki.fextralife.com/Living+Jar' target=\"_blank\">Living Jar</a>. The final glovewort is found behind the door frame of this room, on the right.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"1343","x":0.245180859,"y":0.331305413,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4]","desc":"Found on a corpse, or as a drop from the <a class=\"wiki_link\" title=\"Elden Ring Spider Hand\" href='https://eldenring.wiki.fextralife.com/Spider+Hand'>Spider Hand</a>������near the Road of Iniquity site of grace in������<a class=\"wiki_link\" title=\"Elden Ring Mt. Gelmir\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3567","x":0.27215096,"y":0.331335936,"cat":"Locations","group":"Locations","title":"Seethewater Cave","desc":"A cave locked behind an imp statue. Requires a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stonesword+Key'>Stonesword Key</a> to unlock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"1323","x":0.242713253,"y":0.331366454,"cat":"Maps","group":"Locations","title":"Map (Mt. Gelmir)","desc":"Map of Mt. Gelmir region","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"3862","x":0.577057295,"y":0.331396976,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [7] - 2x Giant-Conquering Hero's Grave","desc":"Spirit Ash Upgrade Material. A total of<strong>2</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Giant-Conquering+Hero's+Grave' target=\"_blank\">Giant-Conquering Hero's Grave</a>. <ol> <li>By a set of steps opposite the first <a href='https://eldenring.wiki.fextralife.com/Lesser+Burial+Watchdog' target=\"_blank\">Lesser Burial Watchdog</a> encountered.</li> <li>Upon reaching the lift, take it to the lower level and then step on the plate again to send it back up. When it's fully raised, you can find an opening in the lift column. Pull the lever in the nearby alcove and go inside the opening in the lift column to descend further down. At the bottom level, sprint past the <a href='https://eldenring.wiki.fextralife.com/Lesser+Burial+Watchdog' target=\"_blank\">Lesser Burial Watchdog</a> and turn right. Climb the long ladder to the right of a second <a href='https://eldenring.wiki.fextralife.com/Lesser+Burial+Watchdog' target=\"_blank\">Lesser Burial Watchdog</a> to reach an otherwise inaccessible area far west of the Troll hall. You can find the second glovewort on the west wall up here.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5956","x":0.588072702,"y":0.331488535,"cat":"Spirit Ashes","group":"Equipment","title":"Fire Monk Ashes","desc":"Spirit Ash. Found inside the <a href='https://eldenring.wiki.fextralife.com/Giants'+Mountaintop+Catacombs' target=\"_blank\">Giants' Mountaintop Catacombs</a>: <ul> <li>Descend the first lift you find and then step on the plate again to send it back up. When fully raised, there is a second platform on the lift that will take you to the lowest levels of the catacombs. Continue through this path past two frost breath traps. The spell is found in a chest behind the second trap.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"3568","x":0.269783671,"y":0.331549575,"cat":"Sites of Grace","group":"Locations","title":"Seethewater Cave","desc":"Site of Grace right by the entrance to <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Seethewater+Cave'>Seethewater Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5774","x":0.391378553,"y":0.331580098,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Windmill Village","desc":"One can be found at a phantom tree South East of Windmill Village site of grace (following the road).","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"9822","x":0.250542584,"y":0.331580098,"cat":"Consumables","group":"Items","title":"Fireproof Dried Liver - 3x Seethewater River","desc":"Consumable. Found on a sprawled out corpse in Seethewater River, just under a fire geyser","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8306","x":0.583679805,"y":0.331671656,"cat":"Upgrade Materials","group":"Items","title":"Great Grave Glovewort - Giant-Conquering Hero's Grave","desc":"Spirit Ash Upgrade Material. <strong>One</strong> found inside the <a href='https://eldenring.wiki.fextralife.com/Giant-Conquering+Hero's+Grave' target=\"_blank\">Giant-Conquering Hero's Grave</a>. <ul> <li>In the large hall with the Troll, drop down from either side of the platform into a room with a <a href='https://eldenring.wiki.fextralife.com/Prelate' target=\"_blank\">Prelate</a>. Defeat it and check the very back of the room for the glovewort.</li> <li>Alternatively, you can reach this room by descending the lift and sending it back up. Pull the lever in the alcove to the right and then enter the small space in the raised lift to descend further down. In the next hall, sprint past the <a href='https://eldenring.wiki.fextralife.com/Lesser+Burial+Watchdog' target=\"_blank\">Lesser Burial Watchdog</a> and turn left. Climb the ladder at the end of this path.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"2968","x":0.55826191,"y":0.331946341,"cat":"Sites of Grace","group":"Locations","title":"Hidden Path to the Haligtree","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3660","x":0.649813033,"y":0.331946341,"cat":"Consumables","group":"Items","title":"Starlight Shards - Mountaintops of the Giants East","desc":"Found in front of a crescent bowl-shaped stone statue by the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8282","x":0.592315815,"y":0.332007381,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [8] - 3x Giants' Mountaintop Catacombs","desc":"Spirit Ash Upgrade Material. A total of <strong>3</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Giants'+Mountaintop+Catacombs' target=\"_blank\">Giants' Mountaintop Catacombs</a>: <ol> <li>Descend the first lift you find and then step on the plate again to send it back up. When fully raised, there is a second platform on the lift that will take you to the lowest levels of the catacombs. From here, continue east to a room with a set of stairs on the right and a <a href='https://eldenring.wiki.fextralife.com/Lesser+Burial+Watchdog' target=\"_blank\">Lesser Burial Watchdog</a>. Check underneath the stairs for the first glovewort.</li> <li>Continue north from the first glovewort to a narrow corridor with a frost breath trap at the end. Turn left halfway through the corridor and pick up the second glovewort at the end of this path.</li> <li>Get back on the first lift and ascend back onto the main path. Head left from the Boss Doors and descend the dungeon's second lift. Turn right in the room with the statue and you will wind up in a hall with guillotine traps. Past the guillotines, turn left in the next corridor and go through the room with several <a href='https://eldenring.wiki.fextralife.com/Land+Squirt' target=\"_blank\">Land Squirts</a>. In the next hall, you will see a small room in the back with a <a href='https://eldenring.wiki.fextralife.com/Living+Jar' target=\"_blank\">Living Jar</a> guarding it. Ignore that room and instead, look for an alcove on the left that you can drop down through. You will end up on a balcony overlooking a room with a statue that looks identical to the one you have previously passed but this is an entirely different floor. Head west from the statue and you will end up in another identical hall filled with guillotine traps, except this time, you can see another statue in a room in the distance. The final glovewort is found next to this statue.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5833","x":0.288788924,"y":0.332129462,"cat":"Weapons","group":"Equipment","title":"Pulley Bow","desc":"Pulley Bow can be found on a sitting corpse (at the top of a siege tower near Mt. Gelmir campsite. The tower is located to the northeast of Gelmir Hero's Grave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bow.png?h=40"},{"id":"10384","x":0.307058819,"y":0.332211188,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf - 2x Mt. Gelmir","desc":"<p>Material. Looted from a corpse in the middle of a ruined battlefield in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5915","x":0.551798785,"y":0.332251543,"cat":"Talismans","group":"Equipment","title":"Silver Scarab","desc":"Found in a chest in <a href='https://eldenring.wiki.fextralife.com/Hidden+Path+to+the+Haligtree' target=\"_blank\">Hidden Path to the Haligtree</a>. The chest is found past an illusory wall, behind a <a href='https://eldenring.wiki.fextralife.com/Grave+Glovewort+(9)' target=\"_blank\">Grave Glovewort (9)</a> inside the first alcove that you can access by jumping down onto the invisible walkways under the staircase in the main hall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"2967","x":0.555361753,"y":0.332343102,"cat":"Locations","group":"Locations","title":"Hidden Path to the Haligtree","desc":"Catacombs leading from the Grand Lift of Rold to Consecrated Grounds. Can only be accessed by those who have found both pieces of the Haligtree Secret Medallion","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"8246","x":0.579297231,"y":0.332373624,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Giant-Conquering Hero's Grave","desc":"Summoning Pool Effigy found next to the Giant-Conquering Hero's Grave site of grace in the Mountaintops of the Giants. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"9818","x":0.275945922,"y":0.332404142,"cat":"Consumables","group":"Items","title":"Glass Shard - Mt. Gelmir","desc":"Material. Found on the farthest corpse of a trio of corpses outside <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Seethewater+Cave' target=\"blank\">Seethewater Cave</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"\">Mt. Gelmir</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10385","x":0.304654764,"y":0.332441079,"cat":"Crafting Materials","group":"Items","title":"Bloodrose - 3x Mt. Gelmir","desc":"<p>Material. Looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>, found between two formations of rocks</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8503","x":0.58666914,"y":0.332587264,"cat":"Key Items","group":"Items","title":"Ritual Pot - Giants' Mountaintop Catacombs","desc":"Crafting Pot. <strong>One</strong> found inside the <a href='https://eldenring.wiki.fextralife.com/Giants'+Mountaintop+Ctacombs' target=\"_blank\">Giants' Mountaintop Catacombs</a>: <ul> <li>Head left from the Boss Doors and descend the dungeon's second lift. Continue along the path and then turn right in the room with the statue. Proceed through the hall with the guillotine traps and then take the first left in the next corridor to a room with several <a href='https://eldenring.wiki.fextralife.com/Land+Squirt' target=\"_blank\">Land Squirts</a>. Keep moving forward until you reach a small room at the end of the path with a large <a href='https://eldenring.wiki.fextralife.com/Living+Jar' target=\"_blank\">Living Jar</a>. There is a corpse by the back wall holding the <strong>Ritual Pot</strong>.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"1331","x":0.297881899,"y":0.332617786,"cat":"Sites of Grace","group":"Locations","title":"First Mt. Gelmir Campsite","desc":"Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"9819","x":0.27747212,"y":0.332648305,"cat":"Crafting Materials","group":"Items","title":"Hefty Beast Bone - 2x Seethewater Cave","desc":"Material. Found in one corpse of a trio of corpses outside <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Seethewater+Cave' target=\"blank\">Seethewater Cave</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"\">Mt. Gelmir</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8283","x":0.593689212,"y":0.333411313,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [9] - Giants' Mountaintop Catacombs","desc":"Spirit Ash Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Giants'+Mountaintop+Catacombs' target=\"_blank\">Giants' Mountaintop Catacombs</a>: <ul> <li>From the Boss Doors, head left and descend the dungeon's second lift. Turn right in the room with the statue and you will wind up in a hall with guillotine traps. Past the guillotines, turn left in the next corridor and go through the room with several <a href='https://eldenring.wiki.fextralife.com/Land+Squirt' target=\"_blank\">Land Squirts</a>. In the next hall, you will see a small room in the back with a <a href='https://eldenring.wiki.fextralife.com/Living+Jar' target=\"_blank\">Living Jar</a> guarding it. Ignore that room and instead, look for an alcove on the left that you can drop down through. You will end up on a balcony overlooking a room with a statue that looks identical to the one you have previously passed but this is an entirely different floor. Head for the corridor the statue is facing to find a third lift. Ascend the lift and get past the hallway with <a href='https://eldenring.wiki.fextralife.com/Imp' target=\"_blank\">Imps</a> to find a small room with the glovewort, guarded by a <a href='https://eldenring.wiki.fextralife.com/Lesser+Burial+Watchdog' target=\"_blank\">Lesser Burial Watchdog</a>.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"1329","x":0.223062274,"y":0.333502872,"cat":"Locations","group":"Locations","title":"Fort Laiedd","desc":"Fort Laiedd is found on the western edge of Mt. Gelmir. A fort left broken, still occupied by those who won the battle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-forthaight.png?h=40"},{"id":"3569","x":0.268166116,"y":0.333533394,"cat":"Armor","group":"Equipment","title":"Mushroom Set (No Crown)","desc":"Entire armor set excluding <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/mushroom+crown'>Mushroom Crown</a>. Found in a room inside the <a href='https://eldenring.wiki.fextralife.com/Seethewater+Cave' target=\"_blank\">Seethewater Cave</a> filled with <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/servant+of+rot'>Servants of Rot</a> and a <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Giant+Poison+Flower'>Giant Poison Flower</a>. Includes <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/mushroom+head'>Mushroom Head</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/mushroom+body'>Mushroom Body</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/mushroom+arms'>Mushroom Arms</a> and <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/mushroom+legs'>Mushroom Legs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"9534","x":0.300372879,"y":0.333622034,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - First Mt. Gelmir Campsite","desc":"Consumable. Can be found at the cemetery near the First Mt. Gelmir Campsite site of grace in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10248","x":0.270643242,"y":0.333700725,"cat":"Consumables","group":"Items","title":"Preserving Boluses - 1x Seethewater Cave","desc":"Consumable. Found on a corpse in an enclosed space in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Seethewater+Cave' target=\"blank\">Seethewater Cave</a>, after a poison pool","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3866","x":0.576141883,"y":0.333869115,"cat":"Weapons","group":"Equipment","title":"Cranial Vessel Candlestand","desc":"Warhammer. Found inside the <a href='https://eldenring.wiki.fextralife.com/Giant-Conquering+Hero's+Grave' target=\"_blank\">Giant-Conquering Hero's Grave</a> on a corpse at the end of the large hall locked behind an Imp Statue barrier. This is directly above the room with the flamethrower pillar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-warhammer.png?h=40"},{"id":"4051","x":0.255221911,"y":0.333869115,"cat":"Talismans","group":"Equipment","title":"Taker's Cameo","desc":"<a href='https://eldenring.wiki.fextralife.com/Talismans' target=\"_blank\">Talisman</a>. Awarded by <a href='https://eldenring.wiki.fextralife.com/Tanith' target=\"_blank\">Tanith</a> after completing the third letter quest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6388","x":0.583801885,"y":0.333869115,"cat":"Weapons","group":"Equipment","title":"Giant's Seal","desc":"Sacred Seal found inside the <a href='https://eldenring.wiki.fextralife.com/Giant-Conquering+Hero's+Grave' target=\"_blank\">Giant-Conquering Hero's Grave</a>: <ul> <li>In the large hall with the Troll, drop down from either side of the platform into a room with a <a href='https://eldenring.wiki.fextralife.com/Prelate' target=\"_blank\">Prelate</a>. Defeat it and check the right side of the room for a corpse holding the seal.</li> <li>Alternatively, you can reach this room by descending the lift and sending it back up. Pull the lever in the alcove to the right and then enter the small space in the raised lift to descend further down. In the next hall, sprint past the <a href='https://eldenring.wiki.fextralife.com/Lesser+Burial+Watchdog' target=\"_blank\">Lesser Burial Watchdog</a> and turn left. Climb the ladder at the end of this path.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacredseal.png?h=40"},{"id":"9546","x":0.373315857,"y":0.333960677,"cat":"Crafting Materials","group":"Items","title":"Gravel Stone - 2x Altus Plateau","desc":"Material. Can be found in the ground at a crumbled ruin, north of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Woodfolk+Ruins' target=\"\">Woodfolk Ruins</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3859","x":0.578091136,"y":0.333991196,"cat":"Sites of Grace","group":"Locations","title":"Giant-Conquering Hero's Grave","desc":"Site of Grace found near the beginning of the dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"9820","x":0.276495355,"y":0.333991196,"cat":"Consumables","group":"Items","title":"Rejuvenating Boluses - 1x Seethwater Cave","desc":"Consumable. Found on the nearest corpse of a trio of corpses outside <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Seethewater+Cave' target=\"\">Seethewater Cave</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"\">Mt. Gelmir</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3601","x":0.581421312,"y":0.33432692,"cat":"Locations","group":"Locations","title":"Giant-Conquering Hero's Grave","desc":"A complex dungeon filled with invulnerable enemies and strange golden floor seals.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-herosgrave.png?h=40"},{"id":"6513","x":0.590453908,"y":0.334449001,"cat":"Locations","group":"Locations","title":"Giants' Mountaintop Catacombs","desc":"<p>The Giants' Mountaintop Catacombs is found in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants' target=\"\">Mountaintops of the Giants</a> region.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"4511","x":0.592038736,"y":0.33447952,"cat":"Sites of Grace","group":"Locations","title":"Giant's Mountaintop Catacombs","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3559","x":0.643151488,"y":0.33454056,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Flame Peak","desc":"Flask Upgrade Material. Found under a Phantom Tree before a frozen giant.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"9823","x":0.240476933,"y":0.334693163,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Seethewater Terminus","desc":"Consumable. Found on a body lying on the ground just before the Seethewater Terminus Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"9533","x":0.298847138,"y":0.334713134,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - Mt. Gelmir","desc":"Consumable. Can be found at the cemetery near the First Mt. Gelmir Campsite site of grace in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3572","x":0.273629178,"y":0.334723682,"cat":"Talismans","group":"Equipment","title":"Kindred of Rot's Exultation","desc":"Talisman. Dropped by the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Kindred+of+Rot'>Kindred of Rot</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3577","x":0.601805208,"y":0.334754204,"cat":"Consumables","group":"Items","title":"Drawstring Holy Grease - Flame Peak","desc":"Weapon Coating. Found on a body near a giant rock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8242","x":0.557346525,"y":0.334754204,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Hidden Path to the Haligtree","desc":"Summoning Pool Effigy found at the end of the hallway after using the Haligtree Medallion at the Grand Lift of Rold. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"9821","x":0.269474478,"y":0.334845763,"cat":"Crafting Materials","group":"Items","title":"Herba - 3x Seethewater River","desc":"Material. Found on a corpse hanging low from a rock in Seethewater River","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8625","x":0.224984462,"y":0.334906804,"cat":"Armor","group":"Equipment","title":"Fire Prelate Set","desc":"The full set is dropped by Fire Prelate enemies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"8452","x":0.595006604,"y":0.334937325,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [7] - Giants' Mountaintop Catacombs","desc":"Spirit Ash Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Giants'+Mountaintop+Catacombs' target=\"_blank\">Giants' Mountaintop Catacombs</a>: <ul> <li>Follow the main path until you reach the first lift. Descend it and then send it back up to reveal a second platform in the lift that will take you to the lowest levels of the catacombs. From here, continue past the room with the <a href='https://eldenring.wiki.fextralife.com/Lesser+Burial+Watchdog' target=\"_blank\">Lesser Burial Watchdog</a> to a corridor with a frost breath trap. Continue past this trap to a second corridor with another frost breath trap at the end. Halfway through this second corridor, hit the wall on the right to reveal an alcove where the ghost glovewort can be found.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"10383","x":0.282012716,"y":0.335070115,"cat":"Crafting Materials","group":"Items","title":"Beast Blood - 3x Gelmir Hero's Grave","desc":"<p>Material. Looted from a corpse on the edge of the second room with a chariot and a lava pool in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"blank\">Gelmir Hero's Grave</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3571","x":0.271004468,"y":0.335150965,"cat":"Bosses","group":"Characters","title":"Kindred of Rot","desc":"Optional Boss. Found by falling through holes to reach the lowest floor of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Seethewater+Cave'>Seethewater Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6361","x":0.553019582,"y":0.335212006,"cat":"Talismans","group":"Equipment","title":"Spelldrake Talisman +2","desc":"Upgraded Talisman. Found in the secret catacombs underneath the <a href='https://eldenring.wiki.fextralife.com/Hidden+Path+to+the+Haligtree' target=\"_blank\">Hidden Path to the Haligtree</a> by turning right just before the <a href='https://eldenring.wiki.fextralife.com/Mimic+Tear' target=\"_blank\">Stray Mimic Tear</a>'s boss door, following the corridor and taking the lift up. The talisman is found on a corpse in an alcove at the top.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3415","x":0.253392388,"y":0.335303568,"cat":"Spells","group":"Equipment","title":"Magma Shot","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Sorceries'>Sorcery</a>. Rewarded by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Tanith'>Tanith</a> after completing the first letter quest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"3206","x":0.374077618,"y":0.335334087,"cat":"Shields","group":"Equipment","title":"Icon Shield","desc":"Found inside a crumbling building. Beware of the enemies inside.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"3207","x":0.251226475,"y":0.335334087,"cat":"Locations","group":"Locations","title":"Volcano Manor","desc":"The manor of a lord looking to rebel against the Erdtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-volcanomanor.png?h=40"},{"id":"8304","x":0.571597826,"y":0.335334087,"cat":"Armor","group":"Equipment","title":"Ronin's Set","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Shabriri'>Shabriri</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"9535","x":0.301715494,"y":0.335392209,"cat":"Consumables","group":"Items","title":"Golden Rune [7] - Mt. Gelmir","desc":"Consumable. Can be found at the furthest grave in the cemetery near the First Mt. Gelmir Campsite site of grace in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5829","x":0.226109672,"y":0.335517208,"cat":"Weapons","group":"Equipment","title":"Prelate's Inferno Crozier","desc":"Drops from the <a href='https://eldenring.wiki.fextralife.com/Prelate' target=\"_blank\">Prelate</a> wielding it inside <a href='https://eldenring.wiki.fextralife.com/Fort+Laiedd' target=\"_blank\"> Fort Laiedd</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossal_weapon.png?h=40"},{"id":"3266","x":0.573731919,"y":0.335578249,"cat":"NPCs","group":"Characters","title":"Shabriri","desc":"Npc that looks exactly like Bloody Finger Hunter Yura. He tells you about \"a righteous path to ascension\"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3860","x":0.583924083,"y":0.335822411,"cat":"Spells","group":"Equipment","title":"Flame, Protect Me","desc":"<a href='https://eldenring.wiki.fextralife.com/Fire+Monk+Incantations' target=\"_blank\">Fire Monk Incantation</a>. Found in a room at the beginning of the <a href='https://eldenring.wiki.fextralife.com/Giant-Conquering+Hero's+Grave' target=\"_blank\">Giant-Conquering Hero's Grave</a>, just in front of the Site of Grace. Requires 2 <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Keys</a> to unlock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"3874","x":0.576977718,"y":0.335822411,"cat":"Weapons","group":"Equipment","title":"Zamor Curved Sword","desc":"Curved Greatsword. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Ancient+Hero+of+Zamor' target=\"_blank\">Ancient Hero of Zamor</a> inside the <a href='https://eldenring.wiki.fextralife.com/Giant-Conquering+Hero's+Grave' target=\"_blank\">Giant-Conquering Hero's Grave</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedgreatsword.png?h=40"},{"id":"8754","x":0.340941684,"y":0.336005532,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Writheblood Ruins","desc":"Summoning Pool Effigy located on the north edge by the stake of Marika. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1340","x":0.221958963,"y":0.336066573,"cat":"Talismans","group":"Equipment","title":"Fire Scorpion Charm","desc":"Raises fire attack, but lowers damage negation. Found next to the talking spirit on the top of the walls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3210","x":0.25494723,"y":0.336219176,"cat":"Key Items","group":"Items","title":"Drawing-Room Key","desc":"Key Item. Given by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Tanith'>Tanith</a> after pledging your allegiance to the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8247","x":0.591948734,"y":0.336280217,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Giants' Mountaintop Catacombs","desc":"Summoning Pool Effigy found in the middle of the hallway just past the Giants' Mountaintop Catacombs site of grace in the Mountaintops of the Giants. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2785","x":0.340697273,"y":0.336341257,"cat":"Locations","group":"Locations","title":"Writheblood Ruins","desc":"A set of ruins overlooking a forest where the <a href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"_blank\">Altus Plateau</a>'s <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Altus+Plateau)' target=\"_blank\">Minor Erdtree</a> can be found.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"2314","x":0.297760116,"y":0.336493856,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [6]","desc":"Found on a body sat on a chair overlooking the edge, there is a wolf sat next to them.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"10379","x":0.279194503,"y":0.336625356,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Gelmir Hero's Grave","desc":"<p>Looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"blank\">Gelmir Hero's Grave</a>, on a room guarded by two <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wandering+Nobles' target=\"blank\">Wandering Nobles</a> lying in ambush</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1235","x":0.253210575,"y":0.3367075,"cat":"NPCs","group":"Characters","title":"Tanith","desc":"Tanith, head of Volcano Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"1339","x":0.22299664,"y":0.336860099,"cat":"Key Items","group":"Items","title":"Armorer's Cookbook [7]","desc":"Can be found on the bottom floor once past the wooden door.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"6259","x":0.594237727,"y":0.336890622,"cat":"Bosses","group":"Characters","title":"Ulcerated Tree Spirit (Giants' Mountaintop Catacombs)","desc":"Found within the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Giant's+Mountaintop+Catacombs'>Giant's Mountaintop Catacombs</a> located in the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants'>Mountaintops of the Giants</a> region. Droprs <a href='https://eldenring.wiki.fextralife.com/Glovewort+Picker's+Bell+Bearing+(2)' target=\"_blank\">Glovewort Picker's Bell Bearing [2]</a>,","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"1147","x":0.411123647,"y":0.33698218,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Lightning Slash","desc":"Ash of War Upgrade. Dropped by a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab'>Teardrop Scarab</a> in the middle of an enclosed area just outside the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Capital+Outskirts'>Capital Outskirts</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"10381","x":0.282610666,"y":0.337029751,"cat":"Crafting Materials","group":"Items","title":"Root Resin - 5x Gelmir Hero's Grave","desc":"<p>Material. Looted from a corpse buried under some jars, atop a ladder in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"blank\">Gelmir Hero's Grave</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10382","x":0.281876609,"y":0.337029751,"cat":"Crafting Materials","group":"Items","title":"Beast Blood - 3x Gelmir Hero's Grave","desc":"<p>Looted from a corpse on the edge of the second room with a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Chariot' target=\"blank\">Chariot</a> and a lava pool in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"blank\">Gelmir Hero's Grave</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"4556","x":0.249395049,"y":0.337043221,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Royal Knight's Resolve","desc":"Ash of War. Found on a corpse in the hallways of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>. Accessible from the imp statue locked room in the dungeon of the manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"5781","x":0.358422931,"y":0.337104261,"cat":"Flask Upgrades","group":"Items","title":"Crimsonspill Crystal Tear","desc":"Flask Upgrade. Dropped by <a href='https://eldenring.wiki.fextralife.com/Wormface' target=\"_blank\">Wormface</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"10353","x":0.221309304,"y":0.337234292,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud - 4x Fort Laiedd","desc":"Material. Can be gathered on the cliffs behind <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Fort+Laeidd' target=\"blank\">Fort Laeidd</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a><br /><br />","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1327","x":0.235296165,"y":0.337287383,"cat":"Sites of Grace","group":"Locations","title":"Seethewater Terminus","desc":"Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3872","x":0.578259551,"y":0.337287383,"cat":"Bosses","group":"Characters","title":"Ancient Hero of Zamor (Giant-Conquering Hero's Grave)","desc":"Optional Boss. Found at the end of the <a href='https://eldenring.wiki.fextralife.com/Giant-Conquering+Hero's+Grave' target=\"_blank\">Giant-Conquering Hero's Grave</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Zamor+Curved+Sword' target=\"_blank\">Zamor Curved Sword</a> and the entire <a href='https://eldenring.wiki.fextralife.com/Zamor+Set' target=\"_blank\">Zamor Armor Set</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"8257","x":0.260105095,"y":0.337348424,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Volcano Manor (Audience Pathway)","desc":"Summoning Pool Effigy found next to the Audience Pathway site of grace in Volcano Manor in Mt. Gelmir, just before the Rykard, Lord of Blasphemy Encounter. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"9825","x":0.342376876,"y":0.337366281,"cat":"NPCs","group":"Characters","title":"Magnus the Beast Claw","desc":"The red summon sign for this <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/NPCs' target=\"blank\">NPC</a> can be found at <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Writheblood+Ruins' target=\"blank\">Writheblood Ruins</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>, after accepting <a class=\"wiki_link\" title=\"Varre's\" href='https://eldenring.wiki.fextralife.com/White+Mask+Varre'>Varre's</a> quest in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes' target=\"blank\">Liurnia of the Lakes</a>. 1x <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Festering+Bloody+Finger' target=\"blank\">Festering Bloody Finger</a> is needed for each invasion attempt, and counts towards completion of the questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"10352","x":0.231294233,"y":0.337454714,"cat":"Crafting Materials","group":"Items","title":"Mushroom - 5x Seethewater Terminus","desc":"Material. Looted from a corpse atop a rock, near Seethewater Terminus Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3830","x":0.572817288,"y":0.337470505,"cat":"Sites of Grace","group":"Locations","title":"Zamor Ruins","desc":"Site of Grace found near the path towards <a href='https://eldenring.wiki.fextralife.com/Zamor+Ruins' target=\"_blank\">Zamor Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6512","x":0.280526682,"y":0.337562067,"cat":"Bosses","group":"Characters","title":"Red Wolf of the Champion","desc":"Large wolf enemy found in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/gelmir+hero's+grave'>Gelmir Hero's Grave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3539","x":0.252203419,"y":0.33792831,"cat":"NPCs","group":"Characters","title":"Patches (Third Location)","desc":"Appears by the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor's</a> entrance after pledging your service to the manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6101","x":0.27499933,"y":0.337947699,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone (5) - 1x Mt. Gelmir","desc":"Upgrade Material. Found on a corpse on the ground.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1143","x":0.441730095,"y":0.338050391,"cat":"Flask Upgrades","group":"Items","title":"Winged Crystal Tear","desc":"Crystal Tear for the Flask of Wondrous Physick. Found on an altar surrounded by Skull enemies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"3533","x":0.255099831,"y":0.338050391,"cat":"Weapons","group":"Equipment","title":"Serpentbone Blade","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Katanas'>Katana</a>. Rewarded by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Tanith'>Tanith</a> after completing the second letter quest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-katana.png?h=40"},{"id":"3880","x":0.580112884,"y":0.338264031,"cat":"Armor","group":"Equipment","title":"Zamor Set","desc":"Armor Set comprised of <a href='https://eldenring.wiki.fextralife.com/Zamor+Mask' target=\"_blank\">Zamor Mask</a>, <a href='https://eldenring.wiki.fextralife.com/Zamor+Armor' target=\"_blank\">Zamor Armor</a>, <a href='https://eldenring.wiki.fextralife.com/Zamor+Bracelets' target=\"_blank\">Zamor Bracelets</a> and <a href='https://eldenring.wiki.fextralife.com/Zamor+Legwraps' target=\"_blank\">Zamor Legwraps</a>. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Ancient+Hero+of+Zamor' target=\"_blank\">Ancient Hero of Zamor</a> <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/bosses'>Boss</a> inside the <a href='https://eldenring.wiki.fextralife.com/Giant-Conquering+Hero's+Grave' target=\"_blank\">Giant-Conquering Hero's Grave</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"5784","x":0.283517634,"y":0.338386112,"cat":"Spirit Ashes","group":"Equipment","title":"Bloodhound Knight Floh","desc":"Dropped by the <a href='https://eldenring.wiki.fextralife.com/Red+Wolf+of+the+Champion' target=\"_blank\">Red Wolf of the Champion</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"8284","x":0.592741788,"y":0.338447153,"cat":"Key Items","group":"Items","title":"Glovewort Picker's Bell Bearing [2]","desc":"Bell Bearing. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Ulcerated+Tree+Spirit' target=\"_blank\">Ulcerated Tree Spirit</a> Boss fought inside the <a href='https://eldenring.wiki.fextralife.com/Giants'+Mountaintop+Catacombs' target=\"_blank\">Giants' Mountaintop Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4559","x":0.258916529,"y":0.338538715,"cat":"Sites of Grace","group":"Locations","title":"Audience Pathway","desc":"Site of Grace found right outside <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Rykard,+Lord+of+Blasphemy'>Rykard's</a> boss room. Accessed by completing all 3 assassination quests for the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> and talking to <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Tanith'>Tanith</a>, or completing the manor's hidden dungeon and taking the waygate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4553","x":0.253514503,"y":0.338630274,"cat":"Spirit Ashes","group":"Equipment","title":"Man-Serpent Ashes","desc":"Spirit Ash. Found on an altar protected by some enemies in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor's</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"3230","x":0.250555798,"y":0.338660796,"cat":"NPC Invaders","group":"Characters","title":"Inquisitor Ghiza","desc":"NPC Invader. Appears at the far end of the dining room when going up to the upper floor of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"5765","x":0.278268209,"y":0.338721837,"cat":"Key Items","group":"Items","title":"Deathroot - Gelmir's Hero Grave","desc":"Found inside a chest, located in the same room where you fight the <a href='https://eldenring.wiki.fextralife.com/Red+Wolf+of+the+Champion' target=\"_blank\">Red Wolf of the Champion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"10391","x":0.282368357,"y":0.338756914,"cat":"Crafting Materials","group":"Items","title":"Mushroom - 5x Mt. Gelmir","desc":"<p>Material. Looted from a corpse outside <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Gelmir's+Hero+Grave' target=\"blank\">Gelmir's Hero Grave</a>, guarded by a pack of <a class=\"wiki_link\" title=\"Wolves\" href='https://eldenring.wiki.fextralife.com/Lone+Wolf'>Wolves</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3236","x":0.249240007,"y":0.338874436,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] A - Volcano Manor","desc":"Upgrade Material. Found on a corpse in the far side of the dining hall in the upper floor of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"10354","x":0.22326424,"y":0.339041767,"cat":"Crafting Materials","group":"Items","title":"Slumbering Egg - 3x  Fort Laiedd","desc":"<p>Material. Looted from a soldier's corpse sprawled on the ground, atop <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Fort+Laeidd' target=\"blank\">Fort Laeidd</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a><br /><br /></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10355","x":0.224930687,"y":0.339116371,"cat":"Consumables","group":"Items","title":"Golden Rune [8] - Fort Laiedd","desc":"Consumable. Looted from a soldier's corpse lying near a wall atop <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Fort+Laeidd' target=\"blank\">Fort Laeidd</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a><br /><br />","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3553","x":0.254583344,"y":0.339210161,"cat":"Weapons","group":"Equipment","title":"Magma Whip Candlestick","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Whips'>Whip</a>. Rewarded by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Patches'>Patches</a> after completing his <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> quest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-whip.png?h=40"},{"id":"3540","x":0.252261479,"y":0.339423801,"cat":"Key Items","group":"Items","title":"Letter to Patches","desc":"Quest Item. A letter outlining Patches' mission. Given by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Patches'>Patches</a> after completing two quests for the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4103","x":0.259435367,"y":0.339423801,"cat":"Weapons","group":"Equipment","title":"Serpent-Hunter","desc":"<a href='https://eldenring.wiki.fextralife.com/Great+Spears' target=\"_blank\">Great Spear</a>. Held by a corpse on the left as you enter the boss chamber of <a href='https://eldenring.wiki.fextralife.com/Rykard,+Lord+of+Blasphemy' target=\"_blank\">Rykard, Lord of Blasphemy</a>. This weapon has a special interaction when fighting Rykard in both his first phase as the God-Devouring Serpent and second phase as Rykard, Lord of Blasphemy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatspear.png?h=40"},{"id":"4557","x":0.365572044,"y":0.339423801,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Golden Slam","desc":"Sacred affinity Ash of War. Obtained by defeating a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> in the northern section of the <a href='https://eldenring.wiki.fextralife.com/Woodfolk+Ruins' target=\"_blank\">Woodfolk Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"1144","x":0.449629399,"y":0.339454323,"cat":"Locations","group":"Locations","title":"Minor Erdtree (Capital Outskirts)","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tree.png?h=40"},{"id":"4558","x":0.257330639,"y":0.339454323,"cat":"Waygates","group":"Locations","title":"Volcano Manor Waygate","desc":"Waygate. Found on a balcony at the top of the stairs of a temple in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor's</a> dungeon. Teleports you to the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Rykard,+Lord+of+Blasphemy'>Rykard, Lord of Blasphemy</a> boss fight.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"6809","x":0.590819032,"y":0.339637444,"cat":"Key Items","group":"Items","title":"Deathroot - Giants' Mountaintop Catacombs","desc":"Key Item. Can be found inside a chest after defeating the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/ulcerated+tree+spirit'>Ulcerated Tree Spirit Boss</a> inside the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/giants'+mountaintop+catacombs'>Giants' Mountaintop Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"10380","x":0.278155815,"y":0.339990218,"cat":"Crafting Materials","group":"Items","title":"Smoldering Butterfly - 6x Gelmir Hero's Grave","desc":"<p>Material. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"blank\">Gelmir Hero's Grave</a> looted from a corpse near a ledge below a room with a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Chariot' target=\"blank\">Chariot</a> passing by</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2312","x":0.280640806,"y":0.340003687,"cat":"Sites of Grace","group":"Locations","title":"Gelmir Hero's Grave","desc":"Site of Grace found inside the Gelmir Hero's Grave, near the entrance after descending the lift.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3265","x":0.570529325,"y":0.340003687,"cat":"Maps","group":"Locations","title":"Map Mountaintops of the Giants, West","desc":"As you leave the Grand Lift of Rold, take the path forward until you reach a stone monument on your right, interact with it to obtain the map Fragment.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"5821","x":0.338194463,"y":0.340003687,"cat":"Weapons","group":"Equipment","title":"Bloody Helice","desc":"Can be found inside a chest, in the same room of the boss in <a href='https://eldenring.wiki.fextralife.com/Writheblood+Ruins' target=\"_blank\">Writheblood Ruins</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-heavy-thrusting-sword.png?h=40"},{"id":"5802","x":0.360991472,"y":0.340125769,"cat":"Bosses","group":"Characters","title":"Wormface","desc":"Boss located at the base of the Minor Erdtree. Drops <a href='https://eldenring.wiki.fextralife.com/Speckled+Hardtear' target=\"_blank\">Speckled Hardtear</a> and <a href='https://eldenring.wiki.fextralife.com/Crimsonspill+Crystal+Tear' target=\"_blank\">Crimsonspill Crystal Tear</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6262","x":0.435197688,"y":0.340186809,"cat":"Shields","group":"Equipment","title":"Twinbird Kite Shield","desc":"Medium Shield dropped by nighttime spawn Deathbird near Leyndell's Hermit Merchant's Shack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"3231","x":0.249697805,"y":0.340217327,"cat":"Weapons","group":"Equipment","title":"Ghiza's Wheel","desc":"Colossal Weapon. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Inquisitor+Ghiza'>Inquisitor Ghiza</a> in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossal_weapon.png?h=40"},{"id":"1952","x":0.311341185,"y":0.340369931,"cat":"Sites of Grace","group":"Locations","title":"Bridge of Iniquity","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5780","x":0.357659654,"y":0.340492012,"cat":"Flask Upgrades","group":"Items","title":"Speckled Hardtear","desc":"Flask Upgrade. Dropped by <a href='https://eldenring.wiki.fextralife.com/Wormface' target=\"_blank\">Wormface</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"8718","x":0.25110343,"y":0.34058357,"cat":"Talismans","group":"Equipment","title":"Dagger Talisman","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Talismans'>Talisman</a>. Found in a room locked by an imp statue in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> dungeon. The room is opposite the balcony where you find the Volcano Manor Waygate. Once inside, drop down two cages, then look for a red candle behind you that shows an obscure pathway to the talisman.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4597","x":0.261938001,"y":0.340614093,"cat":"Spells","group":"Equipment","title":"Aspect of the Crucible: Breath","desc":"Incantation. Dropped by Tanith's Knight. After defeating <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Rykard,+Lord+of+Blasphemy'>Rykard, Lord of Blasphemy</a>, speak with <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Tanith'>Tanith</a> then go back to Rykard's body. If you attack her here in his boss area, her knight will invade.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"8208","x":0.282815676,"y":0.340827732,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Gelmir Hero's Grave","desc":"Summoning Pool Effigy found next to the Gelmir Hero's site of grace in the Altus Plateau. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5807","x":0.340880495,"y":0.340888773,"cat":"Bosses","group":"Characters","title":"Sanguine Noble (Writheblood Ruins)","desc":"Boss found inside <a href='https://eldenring.wiki.fextralife.com/Writheblood+Ruins' target=\"_blank\">Writheblood Ruins</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5757","x":0.368228778,"y":0.340919295,"cat":"Key Items","group":"Items","title":"Nomadic Warrior's Cookbook [19]","desc":"Can be found on the ground inside of the smaller ruined building at <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Woodfolk+Ruins'>Woodfolk Ruins</a> in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau'>Altus Plateau</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"5838","x":0.277491946,"y":0.340980336,"cat":"Armor","group":"Equipment","title":"Gelmir Knight Set","desc":"You can loot the entire <strong>Gelmir Knight Set</strong> in the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/gelmir+hero's+grave'>Gelmir Hero's Grave</a> dungeon from a <em>Gelmir Knight</em> corpse. To find the corpse, head down the first Chariot hallway until you see a pit on either side of the central concrete walkway instead of lava. Drop down into the left pit onto some wooden beams and look for a small window along the walls. Head through this window and down the ladder to find a <a href='https://eldenring.wiki.fextralife.com/Bloodhound+Knight' target=\"_blank\">Bloodhound Knight</a> guarding the corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"6208","x":0.437425122,"y":0.341029168,"cat":"Bosses","group":"Characters","title":"Deathbird (Leyndell Capital Outskirts)","desc":"East of the Hermit Merchant's Shack. It drops the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/twinbird+kite+shield'>Twinbird Kite Shield</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"9550","x":0.365655343,"y":0.341163457,"cat":"Crafting Materials","group":"Items","title":"Beast Blood - Altus Plateau","desc":"Material. Scavenged from a corpse lying in a crumbled ruin in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"4105","x":0.263616596,"y":0.341316057,"cat":"Key Items","group":"Items","title":"Rykard's Great Rune","desc":"Great Rune Key Item. Dropped by <a href='https://eldenring.wiki.fextralife.com/Rykard, Lord of Blasphemy' target=\"_blank\">Rykard, Lord of Blasphemy</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"5832","x":0.284891028,"y":0.341438137,"cat":"Weapons","group":"Equipment","title":"Mantis Blade","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Cemetary+Shade' target=\"_blank\">Cemetary Shade</a> inside the <a href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"_blank\">Gelmir Hero's Grave</a>. This enemy can be found by heading down the first Chariot hall until you reach a point where there is a pit on either side of the central concrete walkway instead of lava. Drop into the left pit onto some wooden beams and then drop into the room below. The shade is in an alcove in the eastern wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedsword.png?h=40"},{"id":"1234","x":0.254460553,"y":0.3415297,"cat":"Sites of Grace","group":"Locations","title":"Volcano Manor (Site of Grace)","desc":"Site of grace located just inside the Volcano Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4599","x":0.260198362,"y":0.341682299,"cat":"Armor","group":"Equipment","title":"Consort's Set","desc":"Armor Set. Dropped by Tanith's Knight. After defeating <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Rykard,+Lord+of+Blasphemy'>Rykard, Lord of Blasphemy</a>, speak with <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Tanith'>Tanith</a> then go back to Rykard's body. If you attack her here in his boss area, her knight will invade.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"3557","x":0.633088122,"y":0.342018024,"cat":"Consumables","group":"Items","title":"Golden Rune [10] A - Flame Peak","desc":"Rune Consumable. Found inside a small cave. Beware of enemies guarding it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4517","x":0.252507816,"y":0.342018024,"cat":"Spirit Ashes","group":"Equipment","title":"Depraved Perfumer Carmaan Ashes","desc":"Spirit Ash. Found behind a hidden room in the secret passageway of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>. After heading in the secret passage, before going downstairs, turn left and go through the hallway full of snails. At the dead end where you get the cookbook, smack the left wall to reveal the hidden room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6862","x":0.249700164,"y":0.342353745,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [6] A - Volcano Manor","desc":"Upgrade Material. Found in an underground room filled with Basiliks next to the large lava lake","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4554","x":0.244176671,"y":0.342384267,"cat":"Key Items","group":"Items","title":"Seedbed Curse - Volcano Manor","desc":"Key Item. Found on a corpse at the bottom of a room locked behind an imp statue in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor's</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4104","x":0.261388639,"y":0.342506348,"cat":"Bosses","group":"Characters","title":"Rykard, Lord of Blasphemy","desc":"Demi God opponent found in <a href='https://eldenring.wiki.fextralife.com/Volcano Manor' target=\"_blank\">Volcano Manor</a>. Initially encountered in his first phase as the <a href='https://eldenring.wiki.fextralife.com/God-Devouring+Serpent' target=\"_blank\">God-Devouring Serpent</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Rykard's+Great+Rune' target=\"_blank\">Rykard's Great Rune</a> and <a href='https://eldenring.wiki.fextralife.com/Remembrance+of+the+Blasphemous' target=\"_blank\">Remembrance of the Blasphemous</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5764","x":0.25403381,"y":0.34296415,"cat":"Key Items","group":"Items","title":"Nomadic Warrior's Cookbook [21]","desc":"Can be found Inside the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>, going upstairs when you enter the hallway from the lobby, enter the first door to the right, the same one with the corpse with a Perfume Bottle. Follow the path through a room full of Snails and you'll end up with a room with two ways forward - one down a flight of steps, another through an open doorway to your left. Head left first, being wary of Snails that may ambush you and continue until you reach a dead end. The corpse at the end of this passageway has the Nomadic Warrior's Cookbook [21] on it, and to the left of it, reveal another hidden door that opens up into a room with the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Depraved+Perfumer+Carmaan+Ashes'>Depraved Perfumer Carmaan Ashes</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"2311","x":0.281740214,"y":0.343238834,"cat":"Locations","group":"Locations","title":"Gelmir Hero's Grave","desc":"Optional Dungeon. The entrance can be reached by walking along the long jagged rock extending from the north of Hermit Village across the chasm.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-herosgrave.png?h=40"},{"id":"2784","x":0.372460119,"y":0.343238834,"cat":"Locations","group":"Locations","title":"Woodfolk Ruins","desc":"East of the Minor Erdtree in Altus Plateau","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"3215","x":0.25238654,"y":0.343238834,"cat":"NPCs","group":"Characters","title":"Rya (Second Location)","desc":"The scout of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"5839","x":0.277254538,"y":0.343269353,"cat":"Armor","group":"Equipment","title":"Bloodhound Knight Set","desc":"Dropped by the <strong>Bloodhound Knight</strong> guarding the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/gelmir+knight+set'>Gelmir Knight Set</a> pickup inside the <a href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"_blank\">Gelmir Hero's Grave</a>. To find the Bloodhound Knight, head down the first Chariot hallway until you see a pit on either side of the central concrete walkway instead of lava. Drop down into the left pit onto some wooden beams and look around for a window along the walls. Head through this window and down the ladder.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"3534","x":0.251073378,"y":0.343360915,"cat":"Key Items","group":"Items","title":"Red Letter","desc":"Quest Item. A letter outlining your final mission after pledging your services to the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>. Found in a room unlocked using the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Drawing-Room+Key'>Drawing-Room Key</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6375","x":0.2850058,"y":0.343391434,"cat":"Weapons","group":"Equipment","title":"Ringed Finger","desc":"Hammer found inside the <a href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"_blank\"> Gelmir Hero's Grave</a>. From the first Chariot hallway, head all the way down and turn left at the end of the path to find a room with a chest containing the weapon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-hammer.png?h=40"},{"id":"4562","x":0.259983514,"y":0.343513515,"cat":"Armor","group":"Equipment","title":"Eye Surcoat","desc":"Chest Armor. Found on the ground after defeating <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Rykard,+Lord+of+Blasphemy'>Rykard, Lord of Blasphemy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"4106","x":0.264042663,"y":0.343635596,"cat":"Remembrances","group":"Items","title":"Remembrance of the Blasphemous","desc":"Remembrance Key Item. Dropped by <a href='https://eldenring.wiki.fextralife.com/Rykard,+Lord+of+Blasphemy' target=\"_blank\">Rykard, Lord of Blasphemy</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4518","x":0.246923423,"y":0.343757677,"cat":"Weapons","group":"Equipment","title":"Bloodhound Claws","desc":"Claw. Dropped by the Bloodhound Knight in the secret passage of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-claws.png?h=40"},{"id":"4519","x":0.248327033,"y":0.344001839,"cat":"Consumables","group":"Items","title":"Fireproof Dried Liver (A) - Volcano Manor","desc":"Consumable. Found on a corpse guarded by the Bloodhound Knight in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor's</a> secret passageway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4533","x":0.239294839,"y":0.344032361,"cat":"Shields","group":"Equipment","title":"Smoldering Shield","desc":"Small Shield. Found on a corpse on the sitting by some tombstones on the same level as the lava in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"5423","x":0.418566216,"y":0.344093401,"cat":"NPCs","group":"Characters","title":"Hermit Merchant","desc":"Merchant within the Hermit Merchant's Shack. Replaced by Bell Bearing Hunter at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"4564","x":0.26181471,"y":0.344398604,"cat":"Sites of Grace","group":"Locations","title":"Rykard, Lord of Blasphemy","desc":"Site of Grace that spawns after <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Rykard,+Lord+of+Blasphemy'>Rykard, Lord of Blasphemy's</a> defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"10369","x":0.279247681,"y":0.344410988,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Hermit Village","desc":"Can be looted from a corpse lying atop a rock pillar connecting <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Hermit+Village' target=\"blank\">Hermit Village</a> to <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"blank\">Gelmir Hero's Grave</a>, in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6861","x":0.25388121,"y":0.344581725,"cat":"Armor","group":"Equipment","title":"Commoner's Headband","desc":"Head Armor. On the head of one of the big statues facing the large lava lake.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"4531","x":0.241827575,"y":0.344642766,"cat":"Weapons","group":"Equipment","title":"Erdtree Seal","desc":"Sacred Seal. Found on a corpse in a building close to the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Omenkiller'>Omenkiller</a> in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacredseal.png?h=40"},{"id":"3226","x":0.250859734,"y":0.344673284,"cat":"Key Items","group":"Items","title":"Letter from Volcano Manor","desc":"Quest Item. A letter outlining your mission after pledging your services to the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>. Found in a room unlocked using the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Drawing-Room+Key'>Drawing-Room Key</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6868","x":0.240332519,"y":0.344703806,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] B - Volcano Manor","desc":"Upgrade Material. Found on the rooftops of Volcano Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3216","x":0.252324445,"y":0.344795365,"cat":"NPCs","group":"Characters","title":"Bernahl (Second Location)","desc":"<a href='https://eldenring.wiki.fextralife.com/Bernahl' target=\"_blank\">Bernahl</a>, Location 2. Merchant and Quest NPC. Sells <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Ashes+of+War'>Ashes of War</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"9547","x":0.373802738,"y":0.344978487,"cat":"Consumables","group":"Items","title":"Invigorating White Cured Meat - Woodfolk Ruins","desc":"Found on a corpse guarded by two wormface enemies in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Woodfolk+Ruins' target=\"\">Woodfolk Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2786","x":0.363640144,"y":0.345314212,"cat":"Locations","group":"Locations","title":"Minor Erdtree (Altus Plateau)","desc":"Minor Erdtree found in central <a href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"_blank\">Altus Plateau</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tree.png?h=40"},{"id":"7601","x":0.278536223,"y":0.345527851,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [6] - Gelmir Hero's Grave","desc":"Spirit Ash Upgrade Material. One is found in the <a href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"_blank\">Gelmir Hero's Grave</a>. From the first Chariot hallway, head down until just before the central concrete walkway ends and jump into the alcove on the left. Head into the room it connects to where you can find the glovewort just by the left wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"7603","x":0.283578674,"y":0.345588892,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [7] - Gelmir Hero's Grave","desc":"Spirit Ash Upgrade Material. One is found in the <a href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"_blank\">Gelmir Hero's Grave</a>. From the first Chariot hallway, head down until just before the central concrete walkway ends and jump into the alcove on the left. Head into the room it connects to and walk up the steps in the back to find the glovewort against the back wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"4573","x":0.419851342,"y":0.345649932,"cat":"Sites of Grace","group":"Locations","title":"Hermit Merchant's Shack","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6863","x":0.248598433,"y":0.345772013,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [7] - Volcano Manor","desc":"Upgrade Material. Found on a corpse hanging from the balcony.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3536","x":0.253607165,"y":0.345863576,"cat":"Key Items","group":"Items","title":"Letter to Bernahl","desc":"Quest Item. A letter outlining Bernahl's mission. Given by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Knight+Bernahl'>Bernahl</a> after completing two quests for the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3228","x":0.251714297,"y":0.345985657,"cat":"Key Items","group":"Items","title":"Recusant Finger","desc":"Multiplayer Item. Found in a locked room with the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Letter+from+Volcano+Manor'>Letter from Volcano Manor</a> after pledging your services to the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"6866","x":0.239111734,"y":0.346016176,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5] A - Volcano Manor","desc":"Upgrade Material. Dropped by a teardrop scarab sitting on a small rooftop.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"7401","x":0.583650621,"y":0.346016176,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [7] - 1x near Zamor Ruins","desc":"Upgrade Material. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> sitting by a tree near <a href='https://eldenring.wiki.fextralife.com/Zamor+Ruins' target=\"_blank\">Zamor Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4520","x":0.243688311,"y":0.346138256,"cat":"Sites of Grace","group":"Locations","title":"Prison Town Church","desc":"Site of Grace located in a church in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"10508","x":0.591059569,"y":0.34633843,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly - 1x Mountaintops of the Giants","desc":"<p>Found near the eastern cliffs of the starting zone in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants' target=\"blank\">Mountaintops of the Giants</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5422","x":0.417774377,"y":0.3463519,"cat":"Locations","group":"Locations","title":"Hermit Merchant's Shack","desc":"Merchant dwells here. Sells Sentry's Torch and Prophet Set among other items.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"8906","x":0.255174428,"y":0.346358003,"cat":"NPCs","group":"Characters","title":"Diallos - Volcano Manor","desc":"Diallos' second overworld location is in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> drawing room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"4537","x":0.240454608,"y":0.346504499,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] C - Volcano Manor","desc":"Upgrade Material. Found on a corpse sitting amongst some tombstone in a tiny island in the lava in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5816","x":0.384971734,"y":0.346535022,"cat":"Key Items","group":"Items","title":"Larval Tear - Ruins","desc":"Dropped from a Miniboss disguises as a noble inside the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1146","x":0.449904991,"y":0.346657103,"cat":"Flask Upgrades","group":"Items","title":"Crimson Crystal Tear","desc":"Crystal Tear for the Flask of Wondrous Physick. Found on an altar at the base of the Minor Erdtree in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Capital+Outskirts'>Capital Outskirts</a>. Guarded by enemies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"10102","x":0.430691667,"y":0.346657103,"cat":"Consumables","group":"Items","title":"Golden Rune [10] - Hermit Merchant's Shack","desc":"Due East of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Hermit+Merchant's+Shack' target=\"blank\">Hermit Merchant's Shack</a> on the cliff to the south of the path.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1145","x":0.447707554,"y":0.346779184,"cat":"Flask Upgrades","group":"Items","title":"Twiggy Cracked Tear","desc":"Crystal Tear for the Flask of Wondrous Physick. Found on an altar at the base of the Minor Erdtree in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Capital+Outskirts'>Capital Outskirts</a>. Guarded by enemies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"3203","x":0.3712082,"y":0.346840224,"cat":"Consumables","group":"Items","title":"Soft Cotton - Woodfolk Ruins","desc":"Consumable. Found against a wall, surrounded by snails.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7602","x":0.281040083,"y":0.346901265,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [7] - 7x Gelmir Hero's Grave","desc":"Spirit Ash Upgrade Material. A total of <strong>7</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Gelmir+Hero's+Grave' target=\"_blank\">Gelmir Hero's Grave</a>: <ol> <li>In the first Chariot hallway, head down until just before the central strip of concrete ends and jump into the alcove to the left to find the first glovewort</li> <li>From the first glovewort, continue through the alcove to a large room. The second glovewort can be found by the right wall.</li> <li>In the same room, head to the back and under the stairs to find the third one.</li> <li>Still in the same room, head up the stairs and go past the flamethrower pillar heading east to a second Chariot hall. The glovewort is just directly opposite of where you enter the hall from.</li> <li>Head back to the first Chariot hall and from the top, head down until the point where there is no lava on either side of the central concrete walkway. Drop down into the pit on the left and land on the crossbeams. Drop down to the area below and you can find the fifth glovewort in an alcove along the eastern wall. Beware the <a href='https://eldenring.wiki.fextralife.com/Cemetary+Shade' target=\"_blank\">Cemetary Shade</a> guarding it.</li> <li>Head back to the first Chariot hallway once more and head all the way down. Look for an alcove on the right at the end of the path, past the lava to get the sixth glovewort</li> <li>From the same alcove, drop down into the hole to find the final glovewort, just outside the boss door</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"4101","x":0.253729246,"y":0.347114905,"cat":"Spells","group":"Equipment","title":"Gelmir's Fury","desc":"<a href='https://eldenring.wiki.fextralife.com/Sorceries' target=\"_blank\">Glintstone Sorcery</a>. Given by <a href='https://eldenring.wiki.fextralife.com/Resucant+Bernahl' target=\"_blank\">Resucant Bernahl</a> after completing three contracts for <a href='https://eldenring.wiki.fextralife.com/Tanith' target=\"_blank\">Tanith</a> at <a href='https://eldenring.wiki.fextralife.com/Volcano+Manor' target=\"_blank\">Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"2554","x":0.43775391,"y":0.347145427,"cat":"Consumables","group":"Items","title":"Golden Rune [4] C","desc":"Found right next to a huge stone, on the ground.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3682","x":0.683585452,"y":0.347206467,"cat":"Sites of Grace","group":"Locations","title":"Forge of the Giants","desc":"The Site of Grace is found following the left edge of the Forge right at the end before reaching the crack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"9003","x":0.445921264,"y":0.3472553,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Minor Erdtree (Capital Outskirts)","desc":"Summoning Pool Effigy found near the Minor Erdtree right by the capital entrance. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"8254","x":0.244630841,"y":0.34751167,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Volcano Manor (Prison Town Church)","desc":"Summoning Pool Effigy found near the Prison Town Church site of grace in Volcano Manor in Mt. Gelmir, through the double doors leading outside. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6867","x":0.239539012,"y":0.347755832,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - Volcano Manor","desc":"Upgrade Material. Found on a corpse hanging from a low rooftop (you must drop down from the higher rooftops to reach it).","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3542","x":0.605923788,"y":0.348030512,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (Church of Ripose)","desc":"Flask upgrade, found inside the <a href='https://eldenring.wiki.fextralife.com/Church+of+Ripose' target=\"_blank\"> Church of Ripose</a>, below the main statue.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"3549","x":0.622220167,"y":0.348274674,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] - East of the Church of Repose","desc":"Dropped from a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\"> Teardrop Scarab</a> found at the top of a small mountain. Will vanish if it spots you or you get too close.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"8756","x":0.22547041,"y":0.348274674,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Magma Wrym","desc":"Summoning Pool Effigy located behind some rocks south of the stake of Marika, overlooking the lava lake. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4550","x":0.253179887,"y":0.348366237,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5] B - Volcano Manor","desc":"Upgrade Material. Dropped by a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab'>Teardrop Scarab</a> rolling on cooled lava in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3849","x":0.579477329,"y":0.348427277,"cat":"Consumables","group":"Items","title":"Invigorating Cured Meat - Zamor Ruins","desc":"Consumable. Found on a corpse on the eastern side of the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5424","x":0.419270617,"y":0.348579877,"cat":"Bosses","group":"Characters","title":"Bell Bearing Hunter (Hermit Merchant's Shack)","desc":"Field Boss. Spawns at the <a href='https://eldenring.wiki.fextralife.com/Hermit+Merchant's+Shack' target=\"_blank\">Hermit Merchant's Shack</a>, but only at night time. Drops the <a href='https://eldenring.wiki.fextralife.com/Medicine+Peddler's+Bell+Bearing' target=\"_blank\">Medicine Peddler's Bell Bearing</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"2819","x":0.56302074,"y":0.348701958,"cat":"Locations","group":"Locations","title":"Grand Lift of Rold","desc":"Elevator connecting Lyndell and Mountaintop of the Giants. Can also be used to access Consecrated Grounds, by those who have obtained the Haligtree Medallion pieces.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-guardians.png?h=40"},{"id":"10227","x":0.320622348,"y":0.348870457,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Clifftop Altus Plateau","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>, Clifftops. Above the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mirage+Rise' target=\"blank\">Mirage Rise</a> towards the northwest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"3545","x":0.615688905,"y":0.348885079,"cat":"Armor","group":"Equipment","title":"Okina Mask","desc":"Dropped by NPC Invader <a href='https://eldenring.wiki.fextralife.com/Bloody+Finger+Okina' target=\"_blank\"> Bloody Finger Okina</a> alongside his trusted katana, <a href='https://eldenring.wiki.fextralife.com/Rivers+of+Blood' target=\"_blank\">Rivers of Blood</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"2762","x":0.613127309,"y":0.349007161,"cat":"Weapons","group":"Equipment","title":"Rivers of Blood","desc":"Katana dropped by NPC invader <a href='https://eldenring.wiki.fextralife.com/Bloody+Finger+Okina' target=\"_blank\"> Bloody Finger Okina</a>. Spawns near the <a href='https://eldenring.wiki.fextralife.com/Church+of+Repose' target=\"_blank\">Church of Repose</a> in the later areas of the game.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-katana.png?h=40"},{"id":"2307","x":0.273290196,"y":0.349068201,"cat":"Spells","group":"Equipment","title":"Comet Azur","desc":"<a href='https://eldenring.wiki.fextralife.com/Sorceries' target=\"_blank\">Sorcery</a>. Acquired from <a href='https://eldenring.wiki.fextralife.com/Primeval+Sorcerer+Azur' target=\"_blank\">Primeval Sorcerer Azur</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"8840","x":0.251684581,"y":0.349159763,"cat":"NPCs","group":"Characters","title":"Rya (End of Questline Location)","desc":"<p> NPC.��Her finally location Volcano Manor at the end of her Questline.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"9816","x":0.356195884,"y":0.349251322,"cat":"Crafting Materials","group":"Items","title":"Hefty Beast Bone - 2x Altus Plateau","desc":"Material. Looted from a corpse near the Forest-Spanning Greatbridge site of grace, below the bridge itself.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10506","x":0.574728869,"y":0.349271996,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly - 1x Zamor Ruins","desc":"<p>Material. Found atop a crumbled wall in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Zamor+Ruins' target=\"blank\">Zamor Ruins</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3680","x":0.678242264,"y":0.349342885,"cat":"Locations","group":"Locations","title":"Forge of the Giants","desc":"It can be reached using the giant frozen chain as a birdge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-giantforge.png?h=40"},{"id":"6261","x":0.422111291,"y":0.349464966,"cat":"Key Items","group":"Items","title":"Medicine Peddler's Bell Bearing","desc":"Key Item. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Bell+Bearing+Hunter' target=\"_blank\">Bell Bearing Hunter</a> that invades the <a href='https://eldenring.wiki.fextralife.com/Hermit+Merchant's+Shack' target=\"_blank\">Hermit Merchant's Shack</a> at night time.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4555","x":0.256201359,"y":0.349526006,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [2] - Volcano Manor","desc":"Upgrade Material. Found on a corpse hanging off of a broken banister in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor's</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"1238","x":0.27600178,"y":0.349648087,"cat":"Sites of Grace","group":"Locations","title":"Primeval Sorcerer Azur","desc":"Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3531","x":0.315337235,"y":0.349709128,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy","desc":"Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Rileigh+the+Idle'>Rileigh the Idle</a> after successfully invading his world.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"4522","x":0.233375069,"y":0.349800687,"cat":"Talismans","group":"Equipment","title":"Crimson Amber Medallion +1","desc":"Talisman. Found at the top of a room locked behind an imp statue in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"10228","x":0.327872981,"y":0.349808637,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Behind Mirage Rise","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>, behind <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mirage+Rise' target=\"blank\">Mirage Rise</a> towards the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"3535","x":0.618282342,"y":0.349861728,"cat":"NPC Invaders","group":"Characters","title":"Bloody Finger Okina","desc":"NPC Invader. Deals powerful blows with his Katana. Drops <a href='https://eldenring.wiki.fextralife.com/Rivers+of+Blood' target=\"_blank\"> Rivers of Blood</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"6613","x":0.239355891,"y":0.349983808,"cat":"Key Items","group":"Items","title":"Stonesword Key - Volcano Manor (A)","desc":"Held by a corpse lying on the stairs within the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/volcano+manor'>Volcano Manor</a> area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"9548","x":0.374016805,"y":0.350105889,"cat":"Consumables","group":"Items","title":"Poisonbone Dart - 5x Woodfolk Ruins","desc":"Ammunition. Found on a body lying in the corner in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Woodfolk+Ruins' target=\"\">Woodfolk Ruins</a> on <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"\">Altus Plateau</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6612","x":0.253912523,"y":0.35016693,"cat":"Key Items","group":"Items","title":"Stonesword Key - Volcano Manor (B)","desc":"Found at the exit of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/rya'>Rya's</a> room, reachable through the window.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8051","x":0.224953208,"y":0.350258493,"cat":"Consumables","group":"Items","title":"Dragon Heart (Magma Wyrm - Mt. Gelmir Lava Pool)","desc":"Key Consumable. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Magma+Wyrm' target=\"_blank\">Magma Wyrm</a> boss found in the lava pool west of <a href='https://eldenring.wiki.fextralife.com/Mt+Gelmir' target=\"_blank\">Mt. Gelmir</a>. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1237","x":0.266820173,"y":0.350319533,"cat":"Sites of Grace","group":"Locations","title":"Subterranean Inquisition Chamber","desc":"Site of grace surrounded by magma","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3302","x":0.572298386,"y":0.350624736,"cat":"Key Items","group":"Items","title":"Smithing-Stone Miner's Bell Bearing [3]","desc":"Key Item. Found in an underground area beneath the <a href='https://eldenring.wiki.fextralife.com/Zamor+Ruins' target=\"_blank\">Zamor Ruins</a>. The entrance is in the southwest section of the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3566","x":0.269476021,"y":0.350807857,"cat":"Weapons","group":"Equipment","title":"Inquisitor's Girandole","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Spears'>Spear</a>. Dropped by the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Abductor+Virgins'>Abductor Virgins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spear.png?h=40"},{"id":"4538","x":0.249425936,"y":0.350868898,"cat":"Bosses","group":"Characters","title":"Magma Wyrm (Volcano Manor)","desc":"Optional Field Boss. Pops out of the lava in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> dungeon after taking the cage lift down.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"2304","x":0.2749961,"y":0.350960456,"cat":"NPCs","group":"Characters","title":"Primeval Sorcerer Azur","desc":"Mysterious NPC. Hands you the <a href='https://eldenring.wiki.fextralife.com/Comet+Azur' target=\"_blank\">Comet Azur</a> spell after interacting with them.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"4540","x":0.25171416,"y":0.351052019,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] - Volcano Manor","desc":"Upgrade Material. Found on a corpse in the back of the cave in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> where you fight the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Magma+Wyrm'>Magma Wyrm</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3550","x":0.631100322,"y":0.351082537,"cat":"Sites of Grace","group":"Locations","title":"Foot of the Forge","desc":"Site of grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3543","x":0.613368252,"y":0.351204618,"cat":"Sites of Grace","group":"Locations","title":"Church of Repose (Site of Grace)","desc":"Site of grace found inside the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Church+of+Repose' target=\"blank\">Church of Repose</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2063","x":0.326817877,"y":0.351418262,"cat":"Spells","group":"Equipment","title":"Unseen Form","desc":"Found at the top of Mirage Rise. Can be found alongside <a href='https://eldenring.wiki.fextralife.com/Unseen Blade' target=\":blank\">Unseen Blade</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"8250","x":0.632502896,"y":0.35144878,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Foot of the Forge","desc":"Summoning Pool Effigy found next to the Foot of the Forge site of grace of Flame Peak in the Mountaintops of the Giants. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"9815","x":0.329404482,"y":0.35144878,"cat":"Crafting Materials","group":"Items","title":"Slumbering Egg - 5x Mirage Rise","desc":"Material. Looted from the body sitting in a chair atop <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mirage+Rise' target=\"blank\">Mirage Rise</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3420","x":0.312750078,"y":0.351723465,"cat":"Consumables","group":"Items","title":"Rune Arc","desc":"Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Rileigh+the+Idle'>Rileigh the Idle</a> after successfully invading his world.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2553","x":0.431192128,"y":0.351967627,"cat":"Consumables","group":"Items","title":"Grace Mimic - Capital Outskirts","desc":"Consumable. Found on a dead body on the path to the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Capital+Outskirts)' target=\"_blank\">Minor Erdtree</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6105","x":0.226384947,"y":0.352120226,"cat":"Bosses","group":"Characters","title":"Magma Wyrm (Mt Gelmir Lava Pool)","desc":"Optional Dragon Boss in the lava pool on the western section of <a href='https://eldenring.wiki.fextralife.com/Mt+Gelmir' target=\"_blank\">Mt. Gelmir</a>. Drops a <a href='https://eldenring.wiki.fextralife.com/Dragon+Heart' target=\"_blank\">Dragon Heart</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"8290","x":0.273989592,"y":0.352303348,"cat":"Armor","group":"Equipment","title":"Azur's Glintstone Set","desc":"After completing Sorceress Sellen's Questline, return to <a href='https://eldenring.wiki.fextralife.com/Primeval+Sorecerer+Azur'>Primeval Sorecerer Azur</a>'s location.to find the complete set there.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"1227","x":0.305664815,"y":0.352516991,"cat":"Weapons","group":"Equipment","title":"Great Club","desc":"Hammer Weapon. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Stonedigger+Troll' target=\"_blank\">Stonedigger Troll</a> boss inside the <a href='https://eldenring.wiki.fextralife.com/Old+Altus+Tunnel' target=\"_blank\">Old Altus Tunnel</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-hammer.png?h=40"},{"id":"3532","x":0.3180559,"y":0.352516991,"cat":"Talismans","group":"Equipment","title":"Crepus's Vial","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Talisman'>Talisman</a>. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Rileigh+the+Idle'>Rileigh the Idle</a> after successfully invading his world.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"7501","x":0.314971068,"y":0.35254751,"cat":"NPC Invaders","group":"Characters","title":"Rileigh the Idle","desc":"One of the assassination targets for the <a href='https://eldenring.wiki.fextralife.com/Volcano+Manor' target=\"_blank\">Volcano Manor</a> questline. Drops <a href='https://eldenring.wiki.fextralife.com/Crepus's+Vial' target=\"_blank\">Crepus's Vial</a>, a <a href='https://eldenring.wiki.fextralife.com/Rune+Arc' target=\"_blank\">Rune Arc</a> and a <href='https://eldenring.wiki.fextralife.com/Furlcalling+Finger+Remedy' target=\"_blank\">Furlcalling Finger Remedy</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"6860","x":0.258700525,"y":0.352639072,"cat":"Key Items","group":"Items","title":"Missionary's Cookbook [6]","desc":"Key Item. Found by going to Temple of Eiglay Grace and up the elevator, then taking a right onto a balcony to access a tower. Go to the bottom of this tower and find the book in a cell.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"2258","x":0.279482034,"y":0.352730631,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Seethewater River","desc":"Flask Upgrade Material. Found under a Phantom Tree as you exit the narrow channel north of Seethewater River.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"7922","x":0.257451126,"y":0.352730631,"cat":"Armor","group":"Equipment","title":"Crimson Tear Scarab","desc":"Can be found after jumping off the balcony and making it to the building with the broken window/ half the floor missing, the item is to their left (hop the railing) and a silver scarab to their right (can be killed from the mini bridge).","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"3558","x":0.266147293,"y":0.352883234,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] B - Volcano Manor","desc":"Upgrade Material. Found on a corpse lying on a fallen column in the lava.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3657","x":0.571709014,"y":0.353120661,"cat":"Locations","group":"Locations","title":"Zamor Ruins","desc":"Once you reach Mountaintops of the Giants, past Shabriri.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"3845","x":0.574096914,"y":0.353127396,"cat":"Spells","group":"Equipment","title":"Zamor Ice Storm (Spell)","desc":"<a href='https://eldenring.wiki.fextralife.com/Snow+Witch+Sorceries'>Snow Witch Sorcery</a>. Found on a corpse in the southern section of the <a href='https://eldenring.wiki.fextralife.com/Zamor+Ruins' target=\"_blank\">Zamor Ruins</a>, by a stone archway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"6864","x":0.240759824,"y":0.353127396,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] D - Volcano Manor","desc":"Upgrade Material. Found on a corpse on a rooftop.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"9813","x":0.326689633,"y":0.353249477,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily - Altus Plateau","desc":"Crafting Material. Can be grabbed from a gravestone near Mirage Rise in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3538","x":0.609159189,"y":0.353371558,"cat":"Locations","group":"Locations","title":"Church of Repose","desc":"Church found high in the mountains. There is a site of grace and a Sacred Tear inside.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"4539","x":0.24826618,"y":0.353402077,"cat":"Consumables","group":"Items","title":"Dragon Heart (Magma Wyrm - Volcano Manor)","desc":"Key Consumable. Dropped by the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Magma+Wyrm'>Magma Wyrm</a>boss in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1148","x":0.412831762,"y":0.35355468,"cat":"Sites of Grace","group":"Locations","title":"Outer Wall Battleground","desc":"Site of Grace found near the northwestern gate of the outer walls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"7019","x":0.416573089,"y":0.35361572,"cat":"Consumables","group":"Items","title":"Golden Rune [7] - Outer Wall Battleground","desc":"Held by a corpse lying on the open field.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10357","x":0.226416857,"y":0.353652872,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - West Mt. Gelmir","desc":"Found on a body in the middle of the lava pool in west <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>, at a small safe spot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1226","x":0.303012341,"y":0.35370728,"cat":"Weapons","group":"Equipment","title":"Troll's Hammer","desc":"Hammer Weapon. Found in a storage shed inside the <a href=\"Old+Altus+Tunnel\" target=\"_blank\">Old Altus Tunnel</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-hammer.png?h=40"},{"id":"2821","x":0.330930371,"y":0.354012482,"cat":"Locations","group":"Locations","title":"Mirage Rise","desc":"An area with a mystic glow. Adventurers who solve the riddle and touch the <strong>Phantom Crests</strong> found across the fields will unveil the <strong>Mirage Rise</strong> and reap its rewards.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"3199","x":0.34591205,"y":0.354012482,"cat":"Sites of Grace","group":"Locations","title":"Bower of Bounty","desc":"Site of grace in the middle of the forest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4140","x":0.253179876,"y":0.354043004,"cat":"Weapons","group":"Equipment","title":"Godskin Stitcher","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Godskin+Noble' \"target=_blank\">Godskin Noble</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-heavy-thrusting-sword.png?h=40"},{"id":"8255","x":0.237860686,"y":0.354043004,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Volcano Manor (Guest Hall)","desc":"Summoning Pool Effigy found next to the Guest Hall site of grace in Volcano Manor in Mt. Gelmir. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5806","x":0.355279296,"y":0.354256644,"cat":"NPCs","group":"Characters","title":"Nomadic Merchant West Altus Plateau","desc":"Found at the Forest-Spanning Greatbridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"2313","x":0.274721942,"y":0.354287166,"cat":"Bosses","group":"Characters","title":"Demi-Human Queen Maggie","desc":"Optional Boss. Found in the northeast section of <a href='https://eldenring.wiki.fextralife.com/Hermit+Village' target=\"_blank\">Hermit Village</a>. Drops a <a href='https://eldenring.wiki.fextralife.com/Memory+Stone' target=\"_blank\">Memory Stone</a> and <a href='https://eldenring.wiki.fextralife.com/Golden+Rune+(1)' target=\"_blank\">Golden Rune (1)</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"5804","x":0.357446447,"y":0.354409247,"cat":"NPCs","group":"Characters","title":"Finger Reader (Altus Plateau)","desc":"Found at the Forest-Spanning Greatbridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"8209","x":0.308628004,"y":0.354561847,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Old Altus Tunnel","desc":"Summoning Pool Effigy found to the right of the shack shortly after the Old Altus Tunnel site of grace in the Altus Plateau. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6865","x":0.236024226,"y":0.35477549,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] A - Volcano Manor","desc":"Upgrade Material. Found on the outer parts of the building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"10507","x":0.573335368,"y":0.354925171,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly - South Zamor Ruins","desc":"<p>Material. Found at the farthest end of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Zamor+Ruins' target=\"blank\">Zamor Ruins</a>, near the cliffs</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8289","x":0.234411683,"y":0.355019652,"cat":"Armor","group":"Equipment","title":"Albinauric Mask","desc":"Found in Volcano Manor near the Guest Hall grace. Head left from the bonfire, then left again, taking the stairs to the next floor. Head outside and take the ladder to your left onto the roof. Go to the back of the roof and jump off the right side to be taken to a room with an Omenkiller, the Albinauric Staff, and Albinauric Mask.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"4141","x":0.258303764,"y":0.355141733,"cat":"Spells","group":"Equipment","title":"Noble Presence","desc":"Incantation. Dropped by <a href='https://eldenring.wiki.fextralife.com/Godskin+Noble' \"target=_blank\">Godskin Noble</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"6399","x":0.612361946,"y":0.355141733,"cat":"Upgrade Materials","group":"Items","title":"Ancient Dragon Smithing Stone - Southeast of the Church of Repose","desc":"Upgrade Material. Found in the skull of a dead giant southeast of the <a href='https://eldenring.wiki.fextralife.com/Church+of+Repose' target=\"_blank\">Church of Repose</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4136","x":0.256747249,"y":0.355172251,"cat":"Bosses","group":"Characters","title":"Godskin Noble(Volcano Manor)","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Volcano+Manor' \"target=_blank\">Volcano Manor</a>. From the Guest Hall Site of Grace, head east across the lava and up the rooftops until you reach a stone platform with a cage elevator. Take the elevator up, go up the stairs, and activate the switch to lower the drawbridge back to the Prison Town Church Site of Grace. Then head up the last set of stairs into the church to fight the Noble.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2824","x":0.313421518,"y":0.355202774,"cat":"Consumables","group":"Items","title":"Golden Rune [3] C","desc":"Found on a body lying at the top of a pillar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3556","x":0.26523201,"y":0.355294332,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] E - Volcano Manor","desc":"Upgrade Material. Found on a corpse in the lava-filled cavern of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5779","x":0.353113879,"y":0.355294332,"cat":"Key Items","group":"Items","title":"Ancient Dragon Apostle's Cookbook [2]","desc":"Can be purchased from the <a href='https://eldenring.wiki.fextralife.com/Nomadic+Merchant+West+Altus+Plateau' target=\"_blank\">Nomadic Merchant</a> sitting next to the <strong>Forest-Spanning Greatbridge</strong> site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"8305","x":0.227661769,"y":0.355355373,"cat":"Armor","group":"Equipment","title":"Jar","desc":"Given by <a href\"/Iron+Fist+Alexander\">Iron Fist Alexander</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"5759","x":0.237128708,"y":0.355385895,"cat":"Sites of Grace","group":"Locations","title":"Guest Hall","desc":"Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5417","x":0.229408919,"y":0.355416414,"cat":"NPCs","group":"Characters","title":"Iron Fist Alexander (Sixth Location)","desc":"NPC. Alexander's Fifth location on this questline. Found near the Seethewater Terminus Site of Grace at a lava lake south of Fort Laiedd in Mt. Gelmir. Alexander is sitting in the lake behind a Magma Wyrm. It is recommended to consider healing before engaging in conversation.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"2064","x":0.327332047,"y":0.355538494,"cat":"Spells","group":"Equipment","title":"Unseen Blade","desc":"Found at the top of Mirage Rise. Can be found alongside <a href='https://eldenring.wiki.fextralife.com/Unseen Form' target=\":blank\">Unseen Form</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"4526","x":0.239661108,"y":0.355630057,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [6] B - Volcano Manor","desc":"Upgrade Material. Found on a corpse slouched over a fountain in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> dungeon surrounded by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Burning+Slug'>Burning Slugs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4541","x":0.25494864,"y":0.355630057,"cat":"Sites of Grace","group":"Locations","title":"Temple of Eiglay","desc":"Site of Grace that spawns after beating the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Godskin+Noble'>Godskin Noble</a> in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"9809","x":0.296858905,"y":0.355691098,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Old Altus Tunnel","desc":"Consumable. Looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Old+Altus+Tunnel' target=\"\">Old Altus Tunnel</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10356","x":0.224204996,"y":0.355725038,"cat":"Crafting Materials","group":"Items","title":"Smoldering Butterfly - 2x Mt. Gelmir","desc":"Material. Found on a body lying near the edge of the lava pool in west <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10226","x":0.318003281,"y":0.355822289,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Bridge of Iniquity South","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>, Below the Bridge of Iniquity towards the south.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"2315","x":0.276643694,"y":0.35593526,"cat":"Key Items","group":"Items","title":"Memory Stone - Hermit Village","desc":"Memory Slot Upgrade Material. Dropped by <a href='https://eldenring.wiki.fextralife.com/Demi-Human+Queen+Maggie' target=\"_blank\">Demi-Human Queen Maggie</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"6525","x":0.640802294,"y":0.356057341,"cat":"Locations","group":"Locations","title":"Flame Peak","desc":"A hostile landscape filled with frozen giant bodies laying around.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-location_44.png?h=40"},{"id":"9814","x":0.342823229,"y":0.356057341,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5] - Altus Plateau","desc":"Upgrade Material. Dropped from a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"\">Teardrop Scarab</a> surrounded by <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wormface' target=\"\">Wormface</a> enemies in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"\">Altus Plateau</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"1224","x":0.301483586,"y":0.35620994,"cat":"Bosses","group":"Characters","title":"Stonedigger Troll (Altus Plateau)","desc":"Optional Boss encountered in the <a href='https://eldenring.wiki.fextralife.com/Old+Altus+Tunnel' target=\"_blank\">Old Altus Tunnel</a> dungeon. Drops the <a href='https://eldenring.wiki.fextralife.com/Great+Club' target=\"_blank\">Great Club</a> weapon upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6373","x":0.235450062,"y":0.356301503,"cat":"Weapons","group":"Equipment","title":"Albinauric Staff","desc":"Found in Volcano Manor near the Guest Hall grace. Head left from the bonfire, then left again, taking the stairs to the next floor. Head outside and take the ladder to your left onto the roof. Go to the back of the roof and jump off the right side to be taken to a room with an Omenkiller, the Albinauric Staff, and Albinauric Mask.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"6522","x":0.410574339,"y":0.356301503,"cat":"Bosses","group":"Characters","title":"Margit, The Fell Omen (Leyndell)","desc":"Margit can be fought again as a non-respawning miniboss in Capital Leyndell, near the end of the game.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"10358","x":0.228970021,"y":0.356369962,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - Mt. Gelmir","desc":"Looted from a corpse lying atop some crumbled stone pillars at the lava lake, in west <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"9810","x":0.296190599,"y":0.356423584,"cat":"Consumables","group":"Items","title":"Stanching Boluses - Old Altus Tunnel","desc":"Consumable. Found on a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Old+Altus+Tunnel' target=\"blank\">Old Altus Tunnel</a>, behind some boxes besides a shack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2316","x":0.273897903,"y":0.356606705,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - (Demi-Human Queen Maggie)","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Demi-Human+Queen+Maggie' target=\"_blank\">Demi-Human Queen Maggie</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1197","x":0.309295095,"y":0.356637224,"cat":"Sites of Grace","group":"Locations","title":"Old Altus Tunnel","desc":"Site of Grace found within the <a href='https://eldenring.wiki.fextralife.com/Old+Altus+Tunnel' target=\"_blank\">Old Altus Tunnel</a>. Found after descending the lift at the entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1196","x":0.307495221,"y":0.356820345,"cat":"Locations","group":"Locations","title":"Old Altus Tunnel","desc":"Optional Dungeon. An old mining site rich with crystals. The <a href='https://eldenring.wiki.fextralife.com/Stonedigger+Troll' target=\"_blank\">Stonedigger Troll</a> boss can be found at the end.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tunnel.png?h=40"},{"id":"4548","x":0.260840542,"y":0.356942426,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy","desc":"Multiplayer Item. Found on a corpse sitting at the edge of a cliff in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"4529","x":0.251592849,"y":0.357095029,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5]","desc":"Upgrade Material. Found on a corpse hanging off of a ledge in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor's</a> dungeon. After going up the cage lift, turn right to find it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"6858","x":0.257422313,"y":0.357095029,"cat":"Key Items","group":"Items","title":"Serpent's Amnion","desc":"Found on the altar after defeating the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/godskin+noble'>Godskin Noble Boss</a> in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/volcano+manor'>Volcano Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2798","x":0.286012749,"y":0.35736971,"cat":"Key Items","group":"Items","title":"Glovewort Picker's Bell Bearing [1]","desc":"Dropped by the Erdtree Burial Watchdog boss of the Wyndham Catacombs","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8256","x":0.253756297,"y":0.35736971,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Volcano Manor (Temple of  Eiglay)","desc":"Summoning Pool Effigy found near the Temple of Eiglay site of grace in Volcano Manor in Mt. Gelmir. After the Godskin Noble encounter, take the elevator to the second floor and jump from the balcony onto the cliff below. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5938","x":0.61352177,"y":0.357613872,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Troll's Roar","desc":"Can be found on the top of the big rock just southeast of the <a href='https://eldenring.wiki.fextralife.com/Church+of+Repose' target=\"_blank\">Church of Repose</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"3211","x":0.3718907,"y":0.357644394,"cat":"Spells","group":"Equipment","title":"Wrath of Gold","desc":"Found at <a href='https://eldenring.wiki.fextralife.com/Woodfolk+Ruins' target=\"_blank\"> Woodfolk Ruins</a>. Among the enemies, there is a staircase that goes down and leads to a chest that contains this <a href='https://eldenring.wiki.fextralife.com/Incantations' target=\"_blank\"> Incantation</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"4572","x":0.357021302,"y":0.357705434,"cat":"Sites of Grace","group":"Locations","title":"Forest-Spanning Greatbridge","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"7722","x":0.357021302,"y":0.357705434,"cat":"Crafting Materials","group":"Items","title":"Hefty Beast Bone - 10x Highway Lookout Tower","desc":"Crafting Material. 10x can be found on a corpse hanging off a wooden beam on the first floor of the <a href='https://eldenring.wiki.fextralife.com/Highway+Lookout+Tower+(Altus+Plateau)' target=\"_blank\">Highway Lookout Tower</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2789","x":0.288856331,"y":0.35818155,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [4] - 2x Wyndham Catacombs","desc":"Spirit Ash Upgrade Material. Two are found within the <a href='https://eldenring.wiki.fextralife.com/Wyndham+Catacombs' target=\"_blank\">Wyndham Catacombs</a>. <ol> <li>The first is found in the room with the cleaver traps, at the back.</li> <li>The second one is found in the sewer area, right where the Golden Order Knight is fought.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"2788","x":0.290651776,"y":0.35865156,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [5] - Wyndham Catacombs","desc":"Spirit Ash Upgrade Material. Two are found inside the <a href='https://eldenring.wiki.fextralife.com/Wyndham+Catacombs' target=\"_blank\">Wyndham Catacombs</a>: <ol> <li>The first one is found as you are descending the lift from the entrance. Face towards the west wall and jump onto a balcony as the lift passes it by to find the glovewort.</li> <li>The second one is found shortly after the room with the cleaver traps, in a pile of rubble in the corner.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"1225","x":0.302002424,"y":0.358712601,"cat":"Talismans","group":"Equipment","title":"Boltdrake Talisman +1","desc":"An upgraded version of the Boltdrake Talisman. Found in a storage shed inside the <a href='https://eldenring.wiki.fextralife.com/Old+Altus+Tunnel' target=\"_blank\">Old Altus Tunnel</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4525","x":0.235840512,"y":0.358712601,"cat":"Consumables","group":"Items","title":"Fireproof Dried Liver (B) - Volcano Manor","desc":"Consumable. Found on a corpse in the outskirts of a building in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2950","x":0.283723756,"y":0.358773641,"cat":"Bosses","group":"Characters","title":"Erdtree Burial Watchdog (Wyndham Catacombs)","desc":"Optional boss found at the end of the <a href='https://eldenring.wiki.fextralife.com/Wyndham+Catacombs' target=\"_blank\">Wyndham Catacombs</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Glovewort+Picker's+Bell+Bearing+(1)' target=\"_blank\">Glovewort Picker's Bell Bearing (1)</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"3262","x":0.563082436,"y":0.358804163,"cat":"Sites of Grace","group":"Locations","title":"Grand Lift of Rold (Site of Grace)","desc":"Site of grace, located at the side of the Grand Lift of Rold","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8804","x":0.355434767,"y":0.358895722,"cat":"Waygates","group":"Locations","title":"Altus Plateau Bridge Waygate","desc":"Waygate. Next to Forest-Spanning Greatbridge Site of Grace. Teleports you to the other side of the destroyed bridge","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"10237","x":0.608927937,"y":0.359017788,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Church of Repose","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mountaintops+of+the+Giants' target=\"blank\">Mountaintops of the Giants</a>, behind the <a class=\"wiki_link\" title=\"Elden Ring Church of Repose\" href='https://eldenring.wiki.fextralife.com/Church+of+Repose' target=\"blank\">Church of Repose</a> towards the south.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"3560","x":0.275517575,"y":0.359139884,"cat":"Sites of Grace","group":"Locations","title":"Abductor Virgin","desc":"Site of Grace found in the underground caverns of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>. Accessible after defeating the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Abductor+Virgins'>Abductor Virgins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"10368","x":0.278130595,"y":0.359159929,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud - 4x Hermit Village (A)","desc":"Material. Can be gathered near the cliffs behind to the right of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Hermit+Village' target=\"blank\">Hermit Village</a> at <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7453","x":0.309876559,"y":0.359414569,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [6] - 2x Old Altus Tunnel","desc":"Upgrade Material. Two are found inside the <a href='https://eldenring.wiki.fextralife.com/Old+Altus+Tunnel' target=\"_blank\">Old Altus Tunnel</a>: <ol> <li>When entering the main chamber with the wooden walkways, head to the right and climb up the ladder to a small cavern. Check to the left of the storage shed to find the stone. You may need to crouch/roll to get into the opening.</li> <li>The second stone is found in the bottom level of the main chamber, behind the southern shed.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"5800","x":0.365522865,"y":0.359445087,"cat":"Bosses","group":"Characters","title":"Crystalians (Altus Tunnel)","desc":"Duo Field Bosses found inside the <a href='https://eldenring.wiki.fextralife.com/Altus+Tunnel' target=\"_blank\">Altus Tunnel</a>. The <a href='https://eldenring.wiki.fextralife.com/Somberstone+Miner's+Bell+Bearing+(2)' target=\"_blank\"> Somberstone Miner's Bell Bearing (2)</a> is obtained upon their defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5729","x":0.27267704,"y":0.35953665,"cat":"Armor","group":"Equipment","title":"Errant Sorcerer Set (No Helm)","desc":"The <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/errant+sorcerer+robe'>Errant Sorcerer Robe</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/errant+sorcerer+manchettes'>Errant Sorcerer Manchettes</a>, and <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/errant+sorcerer+boots'>Errant Sorcerer Boots</a> can be looted together from a corpse in a house on the northeast corner of the village.<br /><a target=\"blank\" href='https://eldenring.wiki.fextralife.com/hierodas+glintstone+crown'>Hierodas Glintstone Crown</a> can be looted from a corpse behind a house on the southern end of the village.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"3552","x":0.643915284,"y":0.35981133,"cat":"Bosses","group":"Characters","title":"Fire Giant","desc":"Main Boss. Found at <a href='https://eldenring.wiki.fextralife.com/Flame+Peak' target=\"_blank\"> Flame Peak</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Remembrance+of+the+Fire+Giant' target=\"_blank\"> Remembrance of the Fire Giant</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2771","x":0.363214019,"y":0.35987237,"cat":"Consumables","group":"Items","title":"Rune Arc - Altus Tunnel","desc":"Consumable Item. Found inside the <a href='https://eldenring.wiki.fextralife.com/Altus+Tunnel' target=\"_blank\">Altus Tunnel</a>. In the first cavern past the Site of Grace, head through the door on the right to find the item in a chest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5767","x":0.367750818,"y":0.359963933,"cat":"Key Items","group":"Items","title":"Somberstone Miner's Bell Bearing [2]","desc":"Bell Bearing Key Item. Obtained by defeating the <a href='https://eldenring.wiki.fextralife.com/Crystalian' target=_blank\">Crystalian</a> Duo Bosses inside the <a href='https://eldenring.wiki.fextralife.com/Altus+Tunnel' target=\"_blank\">Altus Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"7452","x":0.304077777,"y":0.360269136,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - 6x Old Altus Tunnel","desc":"Upgrade Material. A total of 6 can be found in the <a href='https://eldenring.wiki.fextralife.com/Old+Altus+Tunnel' target=\"_blank\">Old Altus Tunnel</a>: <ol> <li>The first is found by the wall to the right of the first storage shed you encounter.</li> <li>In the main chamber with the wooden walkways, head to the right and climb the ladder into a smaller cavern with a storage shed. Check the cavity in the wall concealed by explosive barrels to find the second one.</li> <li>Back on the wooden walkways, take the path to the left of the ladder to find the third stone by the wall.</li> <li>The fourth one is in the bottom of the main chamber, by a wall in the east side.</li> <li>In the same area, check the space between the southern shed and the wall for the fifth stone.</li> <li>In the same area, go behind the northern shed and follow the tunnel to a small cavern to find the sixth stone.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"9543","x":0.286259609,"y":0.360384482,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - Wyndham Catacombs","desc":"Consumable. Found on a body in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wyndham+Catacombs' target=\"\">Wyndham Catacombs</a> in the room behind the rusted bars in the sewers. Can be reached by going under the raising floor in the room with the spike ceiling.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3564","x":0.267671772,"y":0.360726937,"cat":"Bosses","group":"Characters","title":"Abductor Virgins","desc":"Optional Boss. Found in the cave under <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a> by heading south from the Subterranean Inquisition Chamber Site of Grace and falling through the floor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"2790","x":0.291597892,"y":0.3609711,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [6] - Wyndham Catacombs","desc":"Spirit Ash Upgrade Material. Found in the sewer area amongst the Putrid Corpses.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"7454","x":0.307956569,"y":0.361184743,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5] - Old Altus Tunnel","desc":"Upgrade Material. Found at the bottom of the main chamber. Head behind the northern storage shed and follow the tunnel to a small cavern where you can find the stone.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"8212","x":0.365370265,"y":0.361337343,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Altus Tunnel","desc":"Summoning Pool Effigy found next to the Altus Tunnel site of grace in the Altus Plateau. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5835","x":0.369215776,"y":0.361428905,"cat":"Talismans","group":"Equipment","title":"Arsenal Charm +1","desc":"Upgraded Talisman found inside the <a href='https://eldenring.wiki.fextralife.com/Altus+Tunnel' target=\"_blank\">Altus Tunnel</a>. In the second cavern, head through the tunnel in the south to find a wooden balcony overlooking a pit. Drop down on the left side to an overgrown root below. Follow the root going upwards to reach an upper balcony above where you can loot the talisman from a corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"2254","x":0.285314466,"y":0.361489946,"cat":"Sites of Grace","group":"Locations","title":"Wyndham Catacombs","desc":"Site of Grace found right by the catacombs' entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5810","x":0.324582823,"y":0.361581505,"cat":"NPC Invaders","group":"Characters","title":"Eleonora, Violet Bloody Finger","desc":"After talking to <a href='https://eldenring.wiki.fextralife.com/Bloody+Finger+Hunter+Yura' target=\"_blank\">Bloody Finger Hunter Yura</a> at the <a href='https://eldenring.wiki.fextralife.com/Second+Church+of+Marika' target=\"_blank\">Second Church of Marika</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"2776","x":0.361443473,"y":0.361642545,"cat":"Consumables","group":"Items","title":"Crystal Dart - 8x Altus Tunnel","desc":"Offensive Throwable. <strong>8</strong> can be looted off a corpse in the <a href='https://eldenring.wiki.fextralife.com/Altus+Tunnel' target=\"_blank\">Altus Tunnel</a>. In the first cavern after the Site of Grace, head into the second room on the right to find the corpse sitting by some wreckage.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2797","x":0.283113358,"y":0.361703586,"cat":"Key Items","group":"Items","title":"Ancient Dragon Apostle's Cookbook [1]","desc":"Found on a body in the <a href=\"Wyndham+Catacombs\" target=\"_blank\">Wyndham Catacombs</a>, in the room behind the rusted bars in the sewers. Can be reached by going under the raising floor in the room with the spike ceiling.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"7455","x":0.305388716,"y":0.361703586,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4] - Old Altus Tunnel","desc":"Upgrade Material. Found at the bottom of the main chamber, on a corpse inside the northern storage shed.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"9544","x":0.2812557,"y":0.361788413,"cat":"Consumables","group":"Items","title":"Arrow - 10x Seethewater River","desc":"Ammunition. Found on a corpse atop some rocks near the Seethewater River Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5822","x":0.32678515,"y":0.361795148,"cat":"Weapons","group":"Equipment","title":"Eleonora's Poleblade","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Eleonora,+Violet+Bloody+Finger' target=\"_blank\">Eleonora, Violet Bloody Finger</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-doubleedgedswords.png?h=40"},{"id":"2257","x":0.279848245,"y":0.36197827,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Barrage","desc":"Ash of War. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> found in the narrow channel north of Seethewater River.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"2253","x":0.288270906,"y":0.362008788,"cat":"Locations","group":"Locations","title":"Wyndham Catacombs","desc":"Mini Dungeon. The entrance is found at the top of <a href='https://eldenring.wiki.fextralife.com/Wyndham+Ruins' target=\"_blank\">Wyndham Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"3264","x":0.556765967,"y":0.362008788,"cat":"NPCs","group":"Characters","title":"Finger Reader (Grand Lift of Rold)","desc":"Finger Reader found at the base of the Grand Lift of Rold.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"8751","x":0.470322035,"y":0.362405553,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Draconic Tree Sentinel","desc":"<p>Summoning Pool Effigy located around the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Capital+Outskirts' target=\"\">Capital Outskirts</a> along the path next to the Stake of Marika where the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Draconic+Tree+Sentinel' target=\"\">Draconic Tree Sentinel</a>������can be found nearby. Activate this effigy to send your summon sign to this summoning pool.������</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5796","x":0.322418156,"y":0.362497112,"cat":"NPCs","group":"Characters","title":"Bloody Finger Hunter Yura (Fourth Location)","desc":"Found at the Second Church of Marika.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"2770","x":0.363491524,"y":0.362710756,"cat":"Sites of Grace","group":"Locations","title":"Altus Tunnel (Site of Grace)","desc":"Site of Grace found just inside the Altus Tunnel","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2293","x":0.272738752,"y":0.362771796,"cat":"Locations","group":"Locations","title":"Hermit Village","desc":"A secluded village found southeast of the volcano.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-town.png?h=40"},{"id":"10367","x":0.270159134,"y":0.362771796,"cat":"Crafting Materials","group":"Items","title":"String - 5x Hermit Village","desc":"Material. Can be looted from a corpse lying atop the roof of one of the houses in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Hermit+Village' target=\"blank\">Hermit Village</a> at <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7701","x":0.349117181,"y":0.363290639,"cat":"Bosses","group":"Characters","title":"Ancient Hero of Zamor (Sainted Hero's Grave)","desc":"The final boss of the <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave' target=\"_blank\">Sainted Hero's Grave</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Ancient+Dragon+Knight+Kristoff+Ashes' target=\"_blank\">Ancient Dragon Knight Kristoff Ashes</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2780","x":0.368829685,"y":0.363626363,"cat":"Consumables","group":"Items","title":"Golden Rune [7]- Altus Tunnel","desc":"Rune Consumable. <strong>One</strong> is found inside the <a href='https://eldenring.wiki.fextralife.com/Altus+Tunnel' target=\"_blank\">Altus Tunnel</a>. In the second cavern, head through the tunnel in the south to find a wooden balcony overlooking a pit. The rune is found on a corpse sitting on this balcony.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5722","x":0.407035537,"y":0.363626363,"cat":"Talismans","group":"Equipment","title":"Viridian Amber Medallion +1","desc":"can be found in Altus Plauteau, south of the Outer Wall Battleground Site of Grace. You should hear Margit whisper, \"I see you, Tarnished...\" to you before appearing on the road. Defeat him again and it will drop.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"2556","x":0.470411291,"y":0.363656882,"cat":"Weapons","group":"Equipment","title":"Dragon Greatclaw","desc":"Colossal Weapon that drops from the <a href='https://eldenring.wiki.fextralife.com/Draconic+Tree+Sentinel' target=\"_blank\"> Draconic Tree Sentinel</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossal_weapon.png?h=40"},{"id":"2298","x":0.274813429,"y":0.363717922,"cat":"Armor","group":"Equipment","title":"Hierodas Glintstone Crown","desc":"Can be looted from a corpse behind a house on the southern end of the village.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"5830","x":0.351086944,"y":0.363748444,"cat":"Talismans","group":"Equipment","title":"Dragoncrest Shield Talisman +1","desc":"Can be found in a locked imp's room in <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave'>Sainted Hero's Grave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"9812","x":0.322477357,"y":0.363778963,"cat":"Crafting Materials","group":"Items","title":"Human Bone Shard - 6x Second Church of Marika","desc":"Crafting Material. Looted from a corpse lying near a grave at the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Second+Church+of+Marika' target=\"blank\">Second Church of Marika</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3555","x":0.642176074,"y":0.363809485,"cat":"Remembrances","group":"Items","title":"Remembrance of the Fire Giant","desc":"Drops from <a href='https://eldenring.wiki.fextralife.com/Fire+Giant' target=\"_blank\"> Fire Giant</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"5818","x":0.284334155,"y":0.363931566,"cat":"Talismans","group":"Equipment","title":"Lightning Scorpion Charm","desc":"Found in <a href='https://eldenring.wiki.fextralife.com/Wyndham+Catacombs'>Wyndham Catacombs</a> in a room sealed by an Imp Statue, requires a <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key'>Stonesword Key</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6544","x":0.347132842,"y":0.363962085,"cat":"Spirit Ashes","group":"Equipment","title":"Leyndell Soldier Ashes","desc":"<p>Found inside the <a class=\"wiki_link\" title=\"Elden Ring Sainted Hero's Grave\" href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave'>Sainted Hero's Grave</a>. After a floor collapsed, make your way back up and retrieve from a corpse.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"2557","x":0.468946341,"y":0.364145206,"cat":"Shields","group":"Equipment","title":"Dragonclaw Shield","desc":"<a href='https://eldenring.wiki.fextralife.com/Greatshields' target=\"_blank\"> Greatshield</a> that drops from the <a href='https://eldenring.wiki.fextralife.com/Draconic+Tree+Sentinel' target=\"_blank\">Draconic Tree Sentinel</a> guarding the path into the capital.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"5837","x":0.366113145,"y":0.364175728,"cat":"Locations","group":"Locations","title":"Altus Tunnel","desc":"Can be found directly south from the Minor Erdtree in Altus Plateau.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tunnel.png?h=40"},{"id":"9542","x":0.288395912,"y":0.364321592,"cat":"Consumables","group":"Items","title":"Dappled White Cured Meat - Wyndham Ruins","desc":"Consumable. Found on a corpse sitting on the ground in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wyndham+Ruins' target=\"blank\">Wyndham Ruins</a>, on an enclosed space.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7713","x":0.361534955,"y":0.36441989,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - Altus Tunnel","desc":"Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Altus+Tunnel' target=\"_blank\">Altus Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2787","x":0.325162096,"y":0.364511449,"cat":"Locations","group":"Locations","title":"Second Church of Marika","desc":"One of the Four Churches of Marika.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"6133","x":0.445206424,"y":0.364511449,"cat":"NPCs","group":"Characters","title":"Blackguard  (Second Location)","desc":"Merchant. He appears here if you bought <a href='https://eldenring.wiki.fextralife.com/Rya's+Necklace' target=\"_blank\">Rya's Necklace</a> and <a href='https://eldenring.wiki.fextralife.com/Boiled+Prawn' target=\"_blank\">Boiled Prawn</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"10366","x":0.267037477,"y":0.364535236,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud - 2x Hermit Village","desc":"Material. Can be looted from a demi human's corpse at the entrance of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Hermit+Village' target=\"blank\">Hermit Village</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5824","x":0.32104961,"y":0.364755611,"cat":"Weapons","group":"Equipment","title":"Nagakiba","desc":"Can be obtained by completing <a href='https://eldenring.wiki.fextralife.com/Bloody+Finger+Hunter+Yura' target=\"_blank\">Bloody Finger Hunter Yura's</a> questline at the <a href='https://eldenring.wiki.fextralife.com/Second+Church+of+Marika' target=\"_blank\">Second Church of Marika</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-katana.png?h=40"},{"id":"5811","x":0.323087322,"y":0.364786133,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (Second Church of Marika)","desc":"Found inside the <a href='https://eldenring.wiki.fextralife.com/Second+Church+of+Marika' target=\"_blank\">Second Church of Marika</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"8207","x":0.286899321,"y":0.364999773,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Wyndham Catacombs","desc":"Summoning Pool Effigy found in front of the Boss Doors of the Wyndham Catacombs in the Altus Plateau. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5778","x":0.326536075,"y":0.365121854,"cat":"Flask Upgrades","group":"Items","title":"Purifying Crystal Tear","desc":"It can be found at the <a href='https://eldenring.wiki.fextralife.com/Second+Church+of+Marika' target=\"_blank\">Second Church of Marika</a> after defeating the invader <a href='https://eldenring.wiki.fextralife.com/Eleonora,+Violet+Bloody+Finger' target=\"_blank\">Eleonora, Violet Bloody Finger</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"4565","x":0.280245978,"y":0.365213417,"cat":"Sites of Grace","group":"Locations","title":"Seethewater River","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6106","x":0.269472447,"y":0.365274457,"cat":"Key Items","group":"Items","title":"Prattling Pate (You're Beautiful)","desc":"Tool Item. Found by a door just near the Hierodas Glintstone Crown in Hermit Village.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"5828","x":0.345698405,"y":0.365304975,"cat":"Talismans","group":"Equipment","title":"Crimson Seed Talisman","desc":"Talisman. Found in a room inside the <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave'>Sainted Hero's Grave</a>, locked behind an Imp Statue seal. The room is right in front of the Site of Grace near the entrance and requires a <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a> to unlock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"7702","x":0.352612942,"y":0.365304975,"cat":"Spirit Ashes","group":"Equipment","title":"Ancient Dragon Knight Kristoff Ashes","desc":"Spirit Ash Summon. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Ancient+Hero+of+Zamor' target=\"_blank\">Ancient Hero of Zamor</a> found in the <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave' target=\"_blank\">Sainted Hero's Grave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"2796","x":0.293400449,"y":0.365335498,"cat":"Consumables","group":"Items","title":"Magic Grease - Wyndham Ruins","desc":"Found in the room behind the rusted bars in the sewers. Can be reached by going underneath the raising floor in the spiked room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10359","x":0.230694845,"y":0.365389803,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf - Mt. Gelmir West","desc":"Material. Can be gathered once, located behind a formation of rocks, on west <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5812","x":0.276370009,"y":0.365518619,"cat":"Armor","group":"Equipment","title":"Raptor's Black Feathers","desc":"Inside <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sage's+cave'>Sage's Cave</a>, in a chest behind an illusory wall. Alongside <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/skeletal+mask'>Skeletal Mask</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"10363","x":0.239177977,"y":0.365817087,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily - Hermit's Shack","desc":"<p>Material. Can be gathered in west <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>, behind a ruined building in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Hermit's+Shack' target=\"blank\">Hermit's Shack</a> area</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"9541","x":0.292484854,"y":0.365908646,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Wyndham Ruins","desc":"Consumable. Can be found on a sprawled out body in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wyndham+Ruins' target=\"\">Wyndham Ruins</a>, to the left of a huge archway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8905","x":0.478163889,"y":0.366037462,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [6] - Auriza Side Tomb","desc":"Spirit Ash Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Side+Tomb' target=\"_blank\">Auriza Side Tomb</a>: <ul> <li>Precise location to be added</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"7018","x":0.446518054,"y":0.366098502,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Capital Outskirts","desc":"Held by a corpse next to the water, south of the <em>Minor Erdtree</em>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1151","x":0.469924547,"y":0.366220583,"cat":"Bosses","group":"Characters","title":"Draconic Tree Sentinel (Capital Outskirts)","desc":"Field Boss. Defeating it is required to enter <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Leyndell,+Royal+Capital'>Leyndell, Royal Capital</a>. Found right outside the capital's entrance. Drops the <a href='https://eldenring.wiki.fextralife.com/Dragon+Greatclaw' target=\"_blank\">Dragon Greatclaw</a> and <a href='https://eldenring.wiki.fextralife.com/Dragonclaw+Shield' target=\"_blank\">Dragonclaw Shield</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"10362","x":0.23506196,"y":0.366236991,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Mt. Gelmir West","desc":"Can be looted from the open tombs in the gravesite on west <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4605","x":0.449874525,"y":0.366312146,"cat":"NPC Invaders","group":"Characters","title":"Dung Eater (Royal Capital Moat)","desc":"NPC Invader. Found after releasing Dung Eater's corporeal body from his cell in the <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a> and then reading his message at the <a href='https://eldenring.wiki.fextralife.com/Roundtable+Hold' target=\"_blank\">Roundtable Hold</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"2777","x":0.362786272,"y":0.366373186,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - 6x Altus Tunnel","desc":"Upgrade Material. A total of <strong>6</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Altus+Tunnel' target=\"_blank\">Altus Tunnel</a>: <ol> <li>In the first cavern past the Site of Grace, head through the door on the right to find the first stone in the far wall.</li> <li>Back in the main path, head east into the next cavern. The second stone can be found just past the entry point, to the right.</li> <li>In the same cavern, check under the wooden walkway for the third stone.</li> <li>Still in the same cavern, check next to the overgrown root in the southeast to find the fourth stone.</li> <li>The fifth stone is found in the cavern with the boss door, to the left just as you enter.</li> <li>The final stone is also in the cavern with the boss door, next to a root on the left, closer to the boss door.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"10361","x":0.234020804,"y":0.366427492,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Mt. Gelmir West","desc":"Can be looted from the open tombs in the gravesite on west <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2778","x":0.367933939,"y":0.366464745,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5] - Altus Tunnel","desc":"Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Altus+Tunnel' target=\"_blank\">Altus Tunnel</a>. In the second cavern, head up the wooden platform and look along the walls on the right to find the stone.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2282","x":0.240355052,"y":0.366525786,"cat":"Spells","group":"Equipment","title":"Roiling Magma","desc":"<a href='https://eldenring.wiki.fextralife.com/Sorceries' target=\"_blank\">Sorcery</a>. Found on a corpse inside the <a href='https://eldenring.wiki.fextralife.com/Hermit's+Shack' target=\"_blank\">Hermit's Shack</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"2252","x":0.289401951,"y":0.366708907,"cat":"Talismans","group":"Equipment","title":"Pearldrake Talisman +1","desc":"Upgraded Talisman. Found in an cellar near the top of the <a href='https://eldenring.wiki.fextralife.com/Wyndham+Ruins' target=\"_blank\">Wyndham Ruins</a>. The entrance requires a <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a> to unlock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"8904","x":0.476485294,"y":0.366708907,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [6] - 4x Auriza Side Tomb","desc":"Spirit Ash Upgrade Material. A total of <strong>4</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Side+Tomb' target=\"_blank\">Auriza Side Tomb</a>: <ul> <li>Precise locations to be added</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"9540","x":0.295597464,"y":0.366946334,"cat":"Consumables","group":"Items","title":"Golden Rune [7] - Wyndham Ruins","desc":"Consumable. Can be found on a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wyndham+Ruins' target=\"\">Wyndham Ruins</a>, after doing a sharp right at the arching entryway","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2251","x":0.294160453,"y":0.367136191,"cat":"Locations","group":"Locations","title":"Wyndham Ruins","desc":"A large set of ruins south west of the <a href='https://eldenring.wiki.fextralife.com/Old+Altus+Tunnel' target=\"_blank\">Old Altus Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"5814","x":0.276462323,"y":0.367136191,"cat":"Armor","group":"Equipment","title":"Skeletal Mask","desc":"Inside <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sage's+cave'>Sage's Cave</a>, in a chest behind an illusory wall. Alongside <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/raptor's+black+feathers'>Raptor's Black Feathers</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"10360","x":0.234570201,"y":0.367190496,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - 2x Mt. Gelmir West","desc":"Can be looted from the open tombs in the gravesite on west <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2280","x":0.23807471,"y":0.367258272,"cat":"Locations","group":"Locations","title":"Hermit's Shack","desc":"A small shack found south of the volcano.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"8211","x":0.346924974,"y":0.367380353,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Sainted Hero's Grave","desc":"Summoning Pool Effigy found next to the Sainted Hero's Grave site of grace in the Altus Plateau. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"7714","x":0.365350025,"y":0.367410875,"cat":"Consumables","group":"Items","title":"Glintstone Scrap - 6x Altus Tunnel","desc":"Offensive Consumable. Found inside the <a href='https://eldenring.wiki.fextralife.com/Altus+Tunnel' target=\"_blank\">Altus Tunnel</a>. In the second cavern, head through the tunnel in the south to find a wooden balcony overlooking a pit. Drop down onto the overgrown root on the left side to reach a lower balcony below where you can find the item on a corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5955","x":0.48047545,"y":0.367514646,"cat":"Spirit Ashes","group":"Equipment","title":"Soldjars of Fortune Ashes","desc":"Spirit Ashes. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Grave+Warden+Duelist' target=\"_blank\">Grave Warden Duelist</a> boss at the end of the <a href='https://eldenring.wiki.fextralife.com/Auriza+Side+Tomb' target=\"_blank\">Auriza Side Tomb</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"4606","x":0.453657379,"y":0.367532956,"cat":"Weapons","group":"Equipment","title":"Sword of Milos","desc":"<a href='https://eldenring.wiki.fextralife.com/Greatswords' target=\"_blank\">Greatsword</a>. Dropped by <a href='https://eldenring.wiki.fextralife.com/Dung+Eater' target=\"_blank\">Dung Eater</a> as an NPC invader upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"6665","x":0.344930324,"y":0.367618413,"cat":"Key Items","group":"Items","title":"Prattling Pate (Let's get to it)","desc":"Found within <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sainted+hero's+grave'>Sainted Hero's Grave</a> in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/altus+plateau'>Altus Plateau</a>. Found by the entrance of the room with the shadow enemy that, when killed, opens the final door.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"5966","x":0.651483796,"y":0.367624515,"cat":"Sites of Grace","group":"Locations","title":"Fire Giant","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4535","x":0.478379866,"y":0.36802128,"cat":"Sites of Grace","group":"Locations","title":"Auriza Side Tomb","desc":"Site of Grace found by the entrance to <a href='https://eldenring.wiki.fextralife.com/Auriza+Side+Tomb' target=\"_blank\">Auriza Side Tomb</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8903","x":0.475570382,"y":0.36823492,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [5] - 2x Auriza Side Tomb","desc":"Spirit Ash Upgrade Material. A total of <strong>2</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Side+Tomb' target=\"_blank\">Auriza Side Tomb</a>: <ul> <li>Precise locations to be added</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"10364","x":0.244313141,"y":0.368491371,"cat":"Crafting Materials","group":"Items","title":"Gravel Stone - Mt. Gelmir West","desc":"Material. Can be looted from a corpse lying at the edge of a rock, at west <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"n;aml\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"9539","x":0.296162059,"y":0.36856391,"cat":"Crafting Materials","group":"Items","title":"Stormhawk Feather - 4x Wyndham Ruins","desc":"Crafting Material. Can be found on a corpse near a crumbled ledge in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wyndham+Ruins' target=\"\">Wyndham Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7712","x":0.352185664,"y":0.368814807,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [4] - Sainted Hero's Grave","desc":"Spirit Ash Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave' target=\"_blank\">Sainted Hero's Grave</a>, in the room with the <a href='https://eldenring.wiki.fextralife.com/Grave+Warden+Duelist' target=\"_blank\">Grave Warden Duelist</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"3025","x":0.381555406,"y":0.369150527,"cat":"Sites of Grace","group":"Locations","title":"Rampartside Path","desc":"Site of grace found at the western side of Leyndell.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5831","x":0.276279203,"y":0.369150527,"cat":"Armor","group":"Equipment","title":"Black Hood","desc":"In the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sage's+cave'>Sage's Cave</a>, in a treasure chest behind an illusory wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"9501","x":0.420758595,"y":0.369218229,"cat":"Consumables","group":"Items","title":"Golden Rune [12] - Altus Plateau Drop","desc":"<p>Rune Consumable. Dropped by a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wandering+Nobles' target=\"\">Wandering Noble</a> with a treasure chest upon defeating him. This is a one-time drop.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3030","x":0.343684093,"y":0.36924209,"cat":"Bosses","group":"Characters","title":"Black Knife Assassin (Sainted Hero's Grave)","desc":"Optional boss found at the entrance of <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave' target=\"_blank\"> Sainted Hero's Grave</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Black+Knife' target=\"_blank\"> Black Knife</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5735","x":0.349299728,"y":0.369272608,"cat":"Locations","group":"Locations","title":"Sainted Hero's Grave","desc":"The Sainted Hero's Grave is found in Altus Plateau, west of Rampartside Path.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-herosgrave.png?h=40"},{"id":"10231","x":0.465294711,"y":0.369504371,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Capital Rampart Cliffisde","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Capital+Outskirts' target=\"blank\">Capital Outskirts</a>, eastern side of the Capital towards the cliffs where the Capital Rampart Site of Grace is.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"3032","x":0.346675049,"y":0.369699892,"cat":"Sites of Grace","group":"Locations","title":"Sainted Hero's Grave (Site of Grace)","desc":"Site of grace inside the <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave' target=\"_blank\">Sainted Hero's Grave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6260","x":0.481476298,"y":0.369748728,"cat":"Bosses","group":"Characters","title":"Grave Warden Duelist (Auriza Side Tomb)","desc":"Field Enemy located inside <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/auriza+side+tomb'>Auriza Side Tomb</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5826","x":0.279117554,"y":0.369760932,"cat":"Weapons","group":"Equipment","title":"Raptor Talons","desc":"Located at <a href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"_blank\">Sage's Cave</a>, in one of the chests, behind several secret walls","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-claws.png?h=40"},{"id":"9001","x":0.236468041,"y":0.369815191,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Hermit's Shack","desc":"Summoning Pool Effigy found right by Hermit's Shack in Gelmir. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2711","x":0.558566385,"y":0.369821973,"cat":"Weapons","group":"Equipment","title":"Gargoyle's Black Axe","desc":"Greataxe. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Black+Blade+Kindred' target=\"_blank\">Black Blade Kindred</a> guarding the path to the <a href='https://eldenring.wiki.fextralife.com/Grand+Lift+of+Rold' target=\"_blank\">Grand Lift of Rold</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-axe.png?h=40"},{"id":"4534","x":0.478925923,"y":0.369944054,"cat":"Locations","group":"Locations","title":"Auriza Side Tomb","desc":"A Catacomb east from Lyndell, for fallen Auriza warriors","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"3031","x":0.344542863,"y":0.370615499,"cat":"Weapons","group":"Equipment","title":"Black Knife","desc":"Dagger dropped from the <a href='https://eldenring.wiki.fextralife.com/Black+Knife+Assassin' target=\"_blank\">Black Knife Assassin</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"10104","x":0.239159909,"y":0.370615499,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] - 3x Hermit's Shack","desc":"Located in a breakable statue near the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Hermit's+Shack' target=\"blank\">Hermit's Shack</a>, <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>. There is a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Runebear' target=\"blank\">Runebear</a> in the area you can lure to this location to help you break the statue and retrieve its contents.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5768","x":0.283003084,"y":0.37071927,"cat":"Key Items","group":"Items","title":"Stonesword Key - Sage's Cave","desc":"Can be found behind an illusory wall, in the same room where you fight an Axe Skeleton, within <a href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"_blank\">Sage's Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"7706","x":0.351819423,"y":0.370768103,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [5] - Sainted Hero's Grave","desc":"Spirit Ash Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave' target=\"_blank\">Sainted Hero's Grave</a>, in the back of the room with the <a href='https://eldenring.wiki.fextralife.com/Grave+Warden+Duelist' target=\"_blank\">Grave Warden Duelist</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5651","x":0.27655313,"y":0.371134346,"cat":"Shields","group":"Equipment","title":"Candletree Wooden Shield","desc":"In the <a href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"_blank\">Sage's Cave</a>, in a chest behind an illusory wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"6378","x":0.373623918,"y":0.371134346,"cat":"Weapons","group":"Equipment","title":"Harp Bow","desc":"Acquired by solving the <a href='https://eldenring.wiki.fextralife.com/Champion's+Song' target=\"_blank\">Champion's Song</a> Painting, found in <a href=/\"The+Shaded+Castle\" target=\"_blank\"> The Shaded Castle</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-lightbow.png?h=40"},{"id":"1189","x":0.407001228,"y":0.371378508,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - 2x Capital Outskirts Northwest","desc":"Flask Upgrade Material. Two can be found under the Phantom Tree in the northwestern outer wall section.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"2006","x":0.289402767,"y":0.371439548,"cat":"Spells","group":"Equipment","title":"Tibia's Summons","desc":"Drops from the <a href='https://eldenring.wiki.fextralife.com/Tibia+Mariner' target=\"_blank\"> Tibia Mariner</a> at <a href='https://eldenring.wiki.fextralife.com/Wyndham+Ruins' target=\"_blank\">Wyndham Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"1455","x":0.555423,"y":0.371470067,"cat":"Bosses","group":"Characters","title":"Black Blade Kindred (Forbidden Lands)","desc":"Field Boss guarding the path to the <a href='https://eldenring.wiki.fextralife.com/Grand+Lift+of+Rold' target=\"_blank\">Grand Lift of Rold</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Gargoyle's+Black+Axe' target=\"_blank\">Gargoyle's Black Axe</a> and <a href='https://eldenring.wiki.fextralife.com/Gargoyle's+Black+Blades' target=\"_blank\">Gargoyle's Black Blades</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5777","x":0.481323729,"y":0.371732543,"cat":"Key Items","group":"Items","title":"Perfumer's Cookbook [3]","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Auriza+Side+Tomb'>Auriza Side Tomb</a>, open the transporter chest in the room with many benches. The room you'll be teleported to will have a corpse with Perfumer's Cookbook [3] on it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"4487","x":0.28015348,"y":0.371866832,"cat":"Weapons","group":"Equipment","title":"Family Heads","desc":"Flail. Dropped from boss of <a href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"_blank\">Sage's Cave</a>, Necromancer Garris.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-flail.png?h=40"},{"id":"2712","x":0.561191142,"y":0.372110994,"cat":"Weapons","group":"Equipment","title":"Gargoyle's Black Blades","desc":"Twinblades. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Black+Blade+Kindred' target=\"_blank\">Black Blade Kindred</a> guarding the path to the <a href='https://eldenring.wiki.fextralife.com/Grand+Lift+of+Rold' target=\"_blank\">Grand Lift of Rold</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-doubleedgedswords.png?h=40"},{"id":"9549","x":0.369927757,"y":0.372172034,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf - Altus Tunnel","desc":"Material. Found on a corpse at a dead end in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Tunnel' target=\"\">Altus Tunnel</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2292","x":0.260044918,"y":0.372233075,"cat":"Sites of Grace","group":"Locations","title":"Craftsman's Shack","desc":"Site of Grace found inside the Craftsman's Shack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"10365","x":0.258441659,"y":0.372233075,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily - Mt. Gelmir","desc":"Material. Can be gathered in west <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"blank\">Mt. Gelmir</a>, on the cliffs behind the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Craftsman's+Shack' target=\"blank\">Craftsman's Shack</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1191","x":0.461991461,"y":0.372568796,"cat":"Consumables","group":"Items","title":"Gravity Stone Fan","desc":"Offensive Consumable Item. Found on a corpse by the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7703","x":0.3462648,"y":0.372568796,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [3] - 3x Sainted Hero's Grave","desc":"Spirit Ash Upgrade Material. A total of <strong>3</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave' target=\"_blank\">Sainted Hero's Grave</a>: <ol> <li>The first one is found in the room you fall into after the floor above crumbles. Check the southeast of this room to find the glovewort.</li> <li>Continue north from the previous room to find a large hall with falling cleaver traps. The glovewort is found near the end of the second set of cleavers, next to an opening in the wall on the right.</li> <li>The last one is found after after opening the boss door by defeating the <a href='https://eldenring.wiki.fextralife.com/Grave+Warden+Duelist' target=\"_blank\">Grave Warden Duelist</a>. There is a connecting room between the door and the mist gate, you can find the glovewort by a statue on the right. </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"4489","x":0.274477668,"y":0.372660358,"cat":"Talismans","group":"Equipment","title":"Concealing Veil","desc":"Talisman dropped by the <a href='https://eldenring.wiki.fextralife.com/Black+Knife+Assassin' target=\"_blank\">Black Knife Assassin</a> boss within <a href='https://eldenring.wiki.fextralife.com/Sage's+Cave'>Sage's Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"5827","x":0.256872283,"y":0.372690877,"cat":"Weapons","group":"Equipment","title":"Pulley Crossbow","desc":"Can be found on a body at the <a href='https://eldenring.wiki.fextralife.com/Craftsman's+Shack' target=\"_blank\">Craftsman's Shack</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crossbow.png?h=40"},{"id":"7705","x":0.350751226,"y":0.372751917,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [5] - 3x Sainted Hero's Grave","desc":"Spirit Ash Upgrade Material. A total of <strong>3</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave' target=\"_blank\">Sainted Hero's Grave</a>: <ol> <li>From the Site of Grace, head into the corridor towards the east, ignoring the first turn and going all the way to the end. Check behind the stairs in the following room to find the first glovewort.</li> <li>From the room that you fall into after the floor above crumbles, head north into the hall with the falling cleaver traps. Wait for the first cleaver to fall then stand on top of it to use it as a lift and then jump into the opening in the western wall. In the next room, unlock the Imp Statue barrier to find the glovewort.</li> <li>Go back down to the cleaver trap hall and continue along north and then east. Climb the ladder in the opening in the wall to the right near the end of the second set of cleavers and you can find the last glovewort in the corner of the next room.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5760","x":0.282842352,"y":0.372873998,"cat":"Sites of Grace","group":"Locations","title":"Sage's Cave","desc":"Site of grace, located inside <a href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"_blank\"> Sage's Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6811","x":0.479902809,"y":0.372996079,"cat":"Key Items","group":"Items","title":"Cracked Pot - 2x Auriza Side Tomb","desc":"Held by a corpse next to a column, above the water level.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"9537","x":0.28993694,"y":0.373264029,"cat":"Crafting Materials","group":"Items","title":"Human Bone Shard 5x","desc":"Crafting Material. Can be found on a corpse lying at the corner of a structure in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wyndham+Ruins' target=\"\">Wyndham Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6615","x":0.368126188,"y":0.373301282,"cat":"Key Items","group":"Items","title":"Stonesword Key - Altus Plateau (B)","desc":"Held by a Noble's sitting corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"9002","x":0.258832241,"y":0.373429469,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Craftman's Shack","desc":"Summoning Pool Effigy found right by Craftman's Shack on the western edge of Mt. Gelmir. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2004","x":0.291840127,"y":0.373484403,"cat":"Bosses","group":"Characters","title":"Tibia Mariner (Wyndham Ruins)","desc":"Found in the waterlogged section of Wyndham Ruins. Drops A <a href='https://eldenring.wiki.fextralife.com/Deathroot' target=\"_blank\"> Deathroot</a> and <a href='https://eldenring.wiki.fextralife.com/Tibia's+Summons' target=\"_blank\"> Tibia's Summons</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"7704","x":0.34867587,"y":0.373484403,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [4] - 2x Sainted Hero's Grave","desc":"Spirit Ash Upgrade Material. A total of <strong>2</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave' target=\"_blank\">Sainted Hero's Grave</a>: <ol> <li>From the Site of Grace, head into the corridor in the east and take the first turn to the right. Go through the large hallway ahead and turn left into a large room with a set of stairs on the left. Check behind the stairs to find the first glovewort.</li> <li>From the room that you fall into after the floor above crumbles, head north into a large hall with falling cleaver traps. The second glovewort is found halfway through this hall, on the right side.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5766","x":0.340983461,"y":0.373624798,"cat":"Key Items","group":"Items","title":"Amber Starlight","desc":"Key item requested by <a href='https://eldenring.wiki.fextralife.com/Seluvis' target=\"_blank\">Seluvis</a> to progress his quest further.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2007","x":0.295258361,"y":0.373698047,"cat":"Key Items","group":"Items","title":"Deathroot - Wyndham Ruins","desc":"Dropped by the <a href='https://eldenring.wiki.fextralife.com/Tibia+Mariner' target=\"_blank\"> Tibia Mariner</a> Boss.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"9538","x":0.293112207,"y":0.37379179,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Wyndham Ruins","desc":"Consumable. Can be found on a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Wyndham+Ruins' target=\"blank\">Wyndham Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8206","x":0.284820547,"y":0.373850646,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Sage's Cave","desc":"Summoning Pool Effigy found next to the Sage's Cave site of grace in the Altus Plateau. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2291","x":0.259008253,"y":0.374461051,"cat":"Locations","group":"Locations","title":"Craftsman's Shack","desc":"A series of wooden huts found directly south of the volcano.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"5432","x":0.412466302,"y":0.374522092,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Golden Parry","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> found within the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Capital+Outskirts'>Capital Outskirts</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"4484","x":0.282534241,"y":0.374949375,"cat":"Locations","group":"Locations","title":"Sage's Cave","desc":"Cave in Western Altus Plateau, has Black Knife Assassin loot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"4488","x":0.279085381,"y":0.374949375,"cat":"Bosses","group":"Characters","title":"Black Knife Assassin (Sage's Cave)","desc":"Secret boss within <a href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"_blank\">Sage's Cave</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Conceiling+Veil' target=\"_blank\">Concealing Veil</a> talisman.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"5798","x":0.375299985,"y":0.375132497,"cat":"Bosses","group":"Characters","title":"Ancient Dragon Lansseax (Altus Plateau)","desc":"Southwest of Rampartside path. It will only appear if you defeat it first at its first location. Drops <a href='https://eldenring.wiki.fextralife.com/Lansseax's+Glaive' target=\"_blank\">Lansseax's Glaive</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2848","x":0.463730229,"y":0.375529262,"cat":"Sites of Grace","group":"Locations","title":"Capital Rampart","desc":"Site of grace on the eastern side of the Capital.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4486","x":0.27505748,"y":0.375681862,"cat":"Bosses","group":"Characters","title":"Necromancer Garris","desc":"One of the bosses of <a href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"_blank\">Sage's Cave</a>. Drops flail: <a href='https://eldenring.wiki.fextralife.com/Family+Heads' target=\"_blank\">Family Heads</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"8857","x":0.473647365,"y":0.375681862,"cat":"Key Items","group":"Items","title":"Stonesword Key - Auriza Hero's Grave","desc":"Stonesword Key. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>: <ul> <li>In the first Chariot Hall, drop down the openings on either side just before the second ramp. In the room below, head west and up the steps then turn right to reach a second Chariot hall where two chariots are running side by side with a short delay between them. As you exit into this hall, turn left to find the key on a corpse between two ramps.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"5731","x":0.334743831,"y":0.375926024,"cat":"Maps","group":"Locations","title":"Map (Altus Plateau)","desc":"Can be found near the round, just north of the Altus Highway Junction site of grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"5251","x":0.248564909,"y":0.376322789,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - 1x Perfumer's Ruins","desc":"Located on one of the south facing walls, where the main table with the candles is.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2800","x":0.286804343,"y":0.37644487,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - Wyndham Ruins","desc":"Found on a body in the southern section of <a href='https://eldenring.wiki.fextralife.com/Wyndham+Ruins' target=\"_blank\">","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6102","x":0.407581759,"y":0.376597469,"cat":"NPCs","group":"Characters","title":"Finger Reader (Leyndell Capital City)","desc":"Finger Reader NPC.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6387","x":0.377374619,"y":0.376627991,"cat":"Spells","group":"Equipment","title":"Lannseax's Glaive","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Ancient+Dragon+Lansseax' target=\"_blank\">Ancient Dragon Lansseaxt</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"6543","x":0.472213142,"y":0.376627991,"cat":"Spirit Ashes","group":"Equipment","title":"Vulgar Militia Ashes","desc":"Spirit Ashes found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>: <ul> <li>In the large Chariot Hall where two Chariots are running side by side with a short delay between them, head all the way down to the large pit behind some pillars. Looking down, you can find several wooden beams you can drop down onto. Navigate your way across the beams, heading north to find a hidden area on the right with a statue. Head into the corridor behind the statue and to the right to access a small room where a corpse holding the ashes can be found.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"3191","x":0.351849943,"y":0.376811113,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - 2x","desc":"Found over the sarcophagi directly to the southof <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave' target=\"_blank\">Sainted Hero's Grave</a> There are also 2 <a href='https://eldenring.wiki.fextralife.com/Golden+Rune+(4)' target=\"_blank\">Golden Rune (4)</a> nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8858","x":0.475234314,"y":0.376811113,"cat":"Consumables","group":"Items","title":"Golden Rune [7] - Auriza Hero's Grave","desc":"Rune Consumable. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>: <ul> <li>In the large Chariot Hall where two Chariots are running side by side with a short delay between them, head all the way down to the large pit behind some pillars. The rune can be found on a corpse by the edge of this pit.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5937","x":0.476910107,"y":0.377146834,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Holy Ground","desc":"Ash of War obtained inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a> by destroying three specific Chariots. Doing this involves a few steps: <ol> <li>From this first Chariot Hall, drop down the openings on either side just before the second ramp.</li> <li>In the room below, head west and up the steps and then turn right in the next corridor. Follow the path and you will end up in a large Chariot Hall where two Chariots are running almost side by side, with a short delay between them. These are the Chariots you need to destroy.</li> <li>Head down the hall all the way to the bottom where there is a large pit behind some pillars. Looking down, you will find several wooden beams you can drop down onto.</li> <li>Navigate your way down onto the lowest beam you can drop down to and then head south towards an archway with a ladder in the back. Climb up the ladder to reach another Chariot Hall with a single Chariot.</li> <li>Wait for the Chariot to head downwards and then run up the ramp and enter the chamber on the right where you will find a flamethrower pillar. Hit the pillar to raise it which will activate the circular golden seal in the middle of the large double Chariot Hall, teleporting the Chariot from the third hall and causing it to collide with the double Chariots.</li> <li>From here, you will need to return to the large hall to witness the collision event and collect your items. The easiest way to do this is by killing yourself or using the <a href='https://eldenring.wiki.fextralife.com/Memory+of+Grace' target=\"_blank\">Memory of Grace</a> tool (if you don't care about your runes) to return to the Site of Grace. Alternatively, from the flamethrower pillar room, return to the third Chariot Hall, go all the way down the ramp and turn left into a corridor. Take another left to find a lift which will take you up to a chamber where the flamethrower pillar was raised. Wait for breaks between flame spews and head through the corridor in the north. There is an alcove on the right halfway through the corridor which you can use to safely wait for another break before heading towards the end. At the end of this corridor, you can turn left to return to the large Chariot Hall. After the Chariots crash into each other, you will receive the Ash of War along with the <a href='https://eldenring.wiki.fextralife.com/Tree+Sentinel+Set' target=\"_blank\">Tree Sentinel Armor Set</a>.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"6859","x":0.24472758,"y":0.377177356,"cat":"Key Items","group":"Items","title":"Perfume Bottle - 2x Perfumer's Ruins","desc":"One <strong>Perfume Bottle</strong> is near the chest that holds <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/perfumer's+cookbook+(1)'>Perfumer's Cookbook [1]</a>. The other one is in the back section, under the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/giant+poison+flower'>Giant Poison Flower</a> in the ruin's basement cache.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"14201","x":0.4049101,"y":0.377336061,"cat":"Bosses","group":"Characters","title":"Valiant Gargoyle - Capital Outskirts","desc":"<p> Optional Boss. Located around the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Capital+Outskirts' target=\"blank\">Capital Outskirts</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5783","x":0.237982677,"y":0.377390996,"cat":"Spirit Ashes","group":"Equipment","title":"Perfumer Tricia Ashes","desc":"Dropped from <a href='https://eldenring.wiki.fextralife.com/Perfumer+Tricia' target=\"_blank\">Perfumer Tricia</a> at the <a href='https://eldenring.wiki.fextralife.com/Unsightly+Catacombs' target=\"_blank\">Unsightly Catacombs</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"10242","x":0.284630411,"y":0.377450978,"cat":"Consumables","group":"Items","title":"Rejuvenating Boluses - 5x Sage's Cave","desc":"Consumable. Found in a chest behind a illusory wall in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"blank\">Sage's Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10243","x":0.286223387,"y":0.377456595,"cat":"Consumables","group":"Items","title":"Silver-Pickled Fowl Foot - 5x Sage's Cave","desc":"Consumable. Found in a chest behind a illusory wall in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"blank\">Sage's Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3192","x":0.347516113,"y":0.377482558,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - 2x","desc":"Found over the sarcophagi directly to the southof <a href='https://eldenring.wiki.fextralife.com/Sainted+Hero's+Grave' target=\"_blank\">Sainted Hero's Grave</a> There are also 2 <a href='https://eldenring.wiki.fextralife.com/Golden+Rune+(6)' target=\"_blank\">Golden Rune (6)</a> nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2130","x":0.240416092,"y":0.377513077,"cat":"Bosses","group":"Characters","title":"Perfumer Tricia","desc":"Optional Duo Boss Fight. Perfumer Tricia is found at the end of the <a href='https://eldenring.wiki.fextralife.com/Unsightly+Catacombs' target=\"_blank\">Unsightly Catacombs</a> and is accompanied by a Misbegotten Warrior.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6254","x":0.242316507,"y":0.377696198,"cat":"Bosses","group":"Characters","title":"Misbegotten Warrior","desc":"Duo boss of Unsightly Catacombs - paired with Perfumer Tricia. Defeating them grants the <a href='https://eldenring.wiki.fextralife.com/Perfumer+Tricia+Ashes' target=\"_blank\">Perfumer Tricia Ashes</a> spirit ashes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"9536","x":0.300252317,"y":0.377999823,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Wyndham Ruins","desc":"Summoning Pool Effigy found just before the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Tibia+Mariner' target=\"blank\">Tibia Mariner</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>, after the Erdtree-Gazing Hill Site of Grace. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"7755","x":0.471229679,"y":0.378092963,"cat":"Talismans","group":"Equipment","title":"Crucible Feather Talisman","desc":"Talisman found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>. Reaching it is quite complex: <ol> <li>From the first Chariot Hall, drop down through the opening on either side just before the second ramp.</li> <li>In the room below, head west and up the steps, then turn right into the next corridor that leads to a large hall with two Chariots running almost side by side, with a short delay between them. Head all the way down towards the pit behind the pillars.</li> <li>Looking down, you will see several wooden beams that you can drop onto. Navigate your way to the lowest beam and then head south towards the archway with a ladder at the back. Climb the ladder to reach a third Chariot Hall with a single Chariot.</li> <li>Head all the way down this hall, using the alcove on the left about halfway through to avoid the Chariot (unless you've previously destroyed it). At the bottom, turn left into a corridor and head straight to find a small room guarded by an <a href='https://eldenring.wiki.fextralife.com/Omen' target=\"_blank\">Omen</a>. The talisman can be found on a corpse behind the Omen, sitting by a statue.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"10244","x":0.285572586,"y":0.378745228,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly - 1x Sage's Cave","desc":"Consumable. Found in a chest behind a illusory wall in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"blank\">Sage's Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2703","x":0.473378769,"y":0.378794927,"cat":"Bosses","group":"Characters","title":"Crucible Knight & Crucible Knight Ordovis","desc":"Duo Boss fight against <a href='https://eldenring.wiki.fextralife.com/Crucible+Knight+Ordovis' target=\"_blank\">Crucible Knight Ordovis</a> and a standard <a href='https://eldenring.wiki.fextralife.com/Crucible+Knight' target=\"_blank\">Crucible Knight</a>. Awards the entire <a href='https://eldenring.wiki.fextralife.com/Crucible+Axe+Set' target=\"_blank\">Crucible Axe Set</a> as well as <a href='https://eldenring.wiki.fextralife.com/Ordovis's+Greatsword' target=\"_blank\">Ordovis's Greatsword</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2139","x":0.235480621,"y":0.378978049,"cat":"Key Items","group":"Items","title":"Prattling Pate (Apologies)","desc":"Reusable Item. Found on a corpse in the <a href='https://eldenring.wiki.fextralife.com/Unsightly+Catacombs' target=\"_blank\">Unsightly Catacombs</a>, along the corridors in the room with the lever that opens the final door.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"2562","x":0.475204239,"y":0.379008571,"cat":"Weapons","group":"Equipment","title":"Ordovis's Greatsword","desc":"<a href='https://eldenring.wiki.fextralife.com/Greatswords' target=\"_blank\">Greatsword</a>. Obtained by defeating <a href='https://eldenring.wiki.fextralife.com/Crucible+Knight+Ordovis' target=\"_blank\">Crucible Knight Ordovis</a> and his regular <a href='https://eldenring.wiki.fextralife.com/Crucible+Knight' target=\"_blank\">Crucible Knight</a> companion in their <strong>Duo Boss Fight</strong> inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"10234","x":0.469356214,"y":0.379008571,"cat":"Crafting Materials","group":"Items","title":"Great Dragonfly Head - 3x Auriza Hero's Grave","desc":"Material. Found on a corpse at the stairs of a secluded room in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Auriza's+Hero+Grave' target=\"blank\">Auriza's Hero Grave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5803","x":0.250373763,"y":0.37910013,"cat":"Armor","group":"Equipment","title":"Omenkiller Set (No Helm)","desc":"The <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Omenkiller+Robe'>Omenkiller Robe</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Omenkiller+Long+Gloves'>Long Gloves</a> and <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Omenkiller+Boots'>Boots</a> drops from <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Omenkiller'>Omenkiller</a> after defeating in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Perfumer's+Ruins'>Perfumer's Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"10245","x":0.287953351,"y":0.379104689,"cat":"Consumables","group":"Items","title":"Golden Great Arrow - 10x Sage's Cave","desc":"Consumable Ammunition. Found in a chest in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"blank\">Sage's Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5799","x":0.334255903,"y":0.379374814,"cat":"NPCs","group":"Characters","title":"Brother Corhyn (First Location)","desc":"Found at the side of the road after he leaves <a href='https://eldenring.wiki.fextralife.com/Roundtable+Hold'>Roundtable Hold</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"5253","x":0.248299188,"y":0.379435855,"cat":"Key Items","group":"Items","title":"Perfumer's Cookbook [1]","desc":"Located at a chest west of the table with the candles on it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"1953","x":0.245399593,"y":0.379527413,"cat":"Locations","group":"Locations","title":"Perfumer's Ruins","desc":"A set of ruins found in <a href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"_blank\">Altus Plateau</a>, far to the west and below <a href='https://eldenring.wiki.fextralife.com/Mt+Gelmir' target=\"_blank\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"8310","x":0.478349908,"y":0.379722747,"cat":"Armor","group":"Equipment","title":"Tree Sentinel Set","desc":"Armor Set comprised of the <a href='https://eldenring.wiki.fextralife.com/Tree+Sentinel+Helm' target=\"_blank\">Tree Sentinel Helm</a>, <a href='https://eldenring.wiki.fextralife.com/Tree+Sentinel+Armor' target=\"_blank\">Tree Sentinel Armor</a>, <a href='https://eldenring.wiki.fextralife.com/Tree+Sentinel+Gauntlets' target=\"_blank\">Tree Sentinel Gauntlets</a> and <a href='https://eldenring.wiki.fextralife.com/Tree+Sentinel+Greaves' target=\"_blank\">Tree Sentinel Greaves</a>. Obtained inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a> by destroying three specific Chariots. Doing this involves a few steps: <ol> <li>From this first Chariot Hall, drop down the openings on either side just before the second ramp.</li> <li>In the room below, head west and up the steps and then turn right in the next corridor. Follow the path and you will end up in a large Chariot Hall where two Chariots are running almost side by side, with a short delay between them. These are the Chariots you need to destroy.</li> <li>Head down the hall all the way to the bottom where there is a large pit behind some pillars. Looking down, you will find several wooden beams you can drop down onto.</li> <li>Navigate your way down onto the lowest beam you can drop down to and then head south towards an archway with a ladder in the back. Climb up the ladder to reach another Chariot Hall with a single Chariot.</li> <li>Wait for the Chariot to head downwards and then run up the ramp and enter the chamber on the right where you will find a flamethrower pillar. Hit the pillar to raise it which will activate the circular golden seal in the middle of the large double Chariot Hall, teleporting the Chariot from the third hall and causing it to collide with the double Chariots.</li> <li>From here, you will need to return to the large hall to witness the collision event and collect your items. The easiest way to do this is by killing yourself or using the <a href='https://eldenring.wiki.fextralife.com/Memory+of+Grace' target=\"_blank\">Memory of Grace</a> tool (if you don't care about your runes) to return to the Site of Grace. Alternatively, from the flamethrower pillar room, return to the third Chariot Hall, go all the way down the ramp and turn left into a corridor. Take another left to find a lift which will take you up to a chamber where the flamethrower pillar was raised. Wait for breaks between flame spews and head through the corridor in the north. There is an alcove on the right halfway through the corridor which you can use to safely wait for another break before heading towards the end. At the end of this corridor, you can turn left to return to the large Chariot Hall. After the Chariots crash into each other, you will receive the Armor Set along with the <a href='https://eldenring.wiki.fextralife.com/Ash+of+War:+Holy+Ground' target=_blank\">Ash of War: Holy Ground</a>.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"10246","x":0.287434618,"y":0.380054206,"cat":"Consumables","group":"Items","title":"Dragonwound Grease - 4x Sage's Cave","desc":"Consumable. Found in a chest in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sage's+Cave' target=\"blank\">Sage's Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2855","x":0.471264479,"y":0.380290422,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy - Leyndell, Royal Capital","desc":"Multiplayer Item. Found on a corpse laying on an altar in a chapel-like room within the eastern capital ramparts.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"2652","x":0.476689956,"y":0.380473543,"cat":"Armor","group":"Equipment","title":"Crucible Axe Set","desc":"Armor Set comprised of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Crucible+Axe+Helm'>Crucible Axe Helm</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Crucible+Axe+Armor'>Crucible Axe Armor</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Crucible+Gauntlets'>Crucible Gauntlets</a> and the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Crucible+Greaves'>Crucible Greaves</a>. Dropped by <a href='https://eldenring.wiki.fextralife.com/Crucible+Knight+Ordovis' target=\"_blank\">Crucible Knight Ordovis</a> upon defeat inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"3026","x":0.382315566,"y":0.380961867,"cat":"Crafting Materials","group":"Items","title":"Land Octopus Ovary (B)","desc":"Crafting Material, found against the wall, on a small campsite where two Ghost Jellyfish dwell.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5969","x":0.558929052,"y":0.381043253,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Forbidden Lands","desc":"From the Forbidden Lands Site of grace, move towards the <a href='https://eldenring.wiki.fextralife.com/Grand+Lift+of+Rold' target=\"_blank\">Grand Lift of Rold</a>. You'll eventually come across the Golden Seed.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"8856","x":0.479699143,"y":0.381065638,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [5] - 2x Auriza Hero's Grave","desc":"Spirit Ash Upgrade Material. A total of <strong>2</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>: <ol> <li>In the first Chariot Hall, drop down the openings on either side just before the second ramp. In the room below, head west and up the steps and then turn right to find the first glovewort in the next corridor.</li> <li>Continue on from the previous glovewort to the large Chariot Hall with two Chariots running almost side by side, with a short delay between them. Head all the way down to the bottom where there is a large pit. Looking down, you will see several wooden beams you can jump onto. Navigate your way across the beams, heading to the north where you can find a hidden area with a statue to the right. Enter the corridor behind the statue to find a small room where the second glovewort can be looted from the back wall.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"3190","x":0.356534191,"y":0.3811328,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Lightning Ram","desc":"Dropped from a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"2131","x":0.234596596,"y":0.381144989,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [4] - Unsightly Catacombs","desc":"Spirit Ash Upgrade Material. A total of 3 are found within the <a href='https://eldenring.wiki.fextralife.com/Unsightly+Catacombs' target=\"_blank\">Unsightly Catacombs</a>. <ol> <li>The first one is found in the room with the L-shaped staircase.</li> <li>The second one is found by dropping into the pit from the L-shaped staircase and heading through the corridor in the north.</li> <li>The last one is found in the dark hall just before the boss' door.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"10235","x":0.248574119,"y":0.381195857,"cat":"Crafting Materials","group":"Items","title":"Budding Cave Moss - 4x Perfumer Ruins","desc":"Material. Found on a corpse surrounded by <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Miranda+Flowers' target=\"blank\">Miranda Flowers</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Perfumer's+Ruins' target=\"blank\">Perfumer's Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2854","x":0.46748418,"y":0.381236548,"cat":"Consumables","group":"Items","title":"Magic Grease - 3x Leyndell, Royal Capital","desc":"Weapon Coating. A <strong>set of 3</strong> can be found in the southeast corridor after ascending the lift near the <strong>Capital Rampart</strong>grace. The items are on a corpse pressed against the right wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10236","x":0.243419582,"y":0.381297588,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly - 1x Perfumer's Ruins","desc":"Material. Looted from a corpse lying in an enclosed space in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Perfumer's+Ruins' target=\"blank\">Perfumer's Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3653","x":0.477337088,"y":0.381511232,"cat":"Weapons","group":"Equipment","title":"Golden Epitaph","desc":"<a href='https://eldenring.wiki.fextralife.com/Straight+Swords' target=\"_blank\">Straight Sword</a>. Found on a corpse in a room locked behind an <strong>Imp Statue Seal</strong> just past the Site of Grace. Use a <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a> to unlock the seal and beware the <a href='https://eldenring.wiki.fextralife.com/Basilisk' target=\"_blank\">Basilisk</a> guarding the treasure.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"1188","x":0.420028112,"y":0.381907994,"cat":"Ashes of War","group":"Equipment","title":"Lost Ashes of War - Capital Outskirts","desc":"Key Item used to duplicate Ashes of War. Found by the locked gate in the northwestern Capital Outskirts.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"1955","x":0.240271257,"y":0.381999556,"cat":"Locations","group":"Locations","title":"Unsightly Catacombs","desc":"A burial grounds crawling with Misbegotten creatures found deep beneath the Perfumer's Ruins. Despite its decrepit state, the catacombs give off a trace of fragrant aromas juxtaposed by the scent of the ancient dead.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"1192","x":0.475419434,"y":0.382030074,"cat":"Sites of Grace","group":"Locations","title":"Auriza Hero's Grave","desc":"Site of Grace found inside <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>. Right by the lift.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3656","x":0.463572785,"y":0.382091115,"cat":"Consumables","group":"Items","title":"Golden Rune [7] B","desc":"Found inside <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\"> Auriza Hero's Grave</a>, at the edge of the path where the lone chariot passes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"9101","x":0.557310752,"y":0.382091115,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [7] - Forbidden Lands","desc":"Upgrade Material. <p>Found in the <a class=\"wiki_link\" title=\"Elden Ring Forbidden Lands\" href='https://eldenring.wiki.fextralife.com/Forbidden+Lands'>Forbidden Lands</a> on a corpse inside the giant skull on the hill before the encounter with Black Blade Kindred.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"1159","x":0.473919718,"y":0.382121637,"cat":"Locations","group":"Locations","title":"Auriza Hero's Grave","desc":"Found by following the main path within the outskirt walls, all the way to the east.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-herosgrave.png?h=40"},{"id":"9811","x":0.321887558,"y":0.38254892,"cat":"Crafting Materials","group":"Items","title":"Turtle Neck Meat - 1x Altus Plateau","desc":"Crafting Material. Looted from a corpse at an abandoned campsite in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"\">Altus Plateau</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3654","x":0.45939636,"y":0.382609961,"cat":"Key Items","group":"Items","title":"Stonesword Key - Auriza Hero's Grave","desc":"At <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\"> Auriza Hero's Grave</a>, one can be found while passing the third part of the giant chariots, on a small platform in the middle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"7710","x":0.483044311,"y":0.382671001,"cat":"Weapons","group":"Equipment","title":"Frenzied Flame Seal","desc":"Weapon. Reward from completing Hyetta's Questline. Hyetta can be finally found at Frenzied Flame Proscription, Leyndell, Royal Capital. Upon accepting the Three Fingers flame, return to Hyetta and talk to her once more. Exhaust her dialogue, and she will give you the Frenzied Flame Seal, completing her questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacredseal.png?h=40"},{"id":"8853","x":0.479545547,"y":0.38268321,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [6] - 4x Auriza Hero's Grave","desc":"Spirit Ash Upgrade Material. A total of <strong>4</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>: <ol> <li>In the first Chariot Hall, drop down the openings on either side just before the second ramp and then check the eastern wall in the bottom room. Beware the multiple <a href='https://eldenring.wiki.fextralife.com/Basilisk' target=\"_blank\">Basilisks</a> that emerge from the ground as you approach.</li> <li>From the first glovewort, head west and up the steps and then turn right in the next corridor. Follow the path towards a second Chariot Hall where two Chariots are running side by side with a short delay between them. The second glovewort can be found shortly after exiting into this hall, right down the middle before the second ramp.</li> <li>In the same large hall, head all the way to the bottom where there is a large pit. Look down to find some wooden beams you can drop onto. Navigate your way to the lowest beam and then head south towards an archway with a ladder in the back. Head up the ladder and you will end up in another hall with a single Chariot. Wait for it to run down the ramp and then head up and turn right into a chamber with a flamethrower pillar. The third glovewort can be found behind this pillar.</li> <li>From the flamethrower pillar, head back into the last Chariot hall and head all the way down to the bottom. Enter the corridor on the left and then take another left to find a lift which will take you up to a chamber where the flamethrower pillar is raised (if you have previously hit it). If the pillar is active, it will be spewing flames into the northern corridor. Wait for breaks in between spews and head inside. There is an alcove on the right where you can safely wait for another break before heading to the end of the corridor. Turn left at the end to find the final glovewort just before the path leads back to the large double Chariot Hall.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5792","x":0.295626887,"y":0.382732042,"cat":"NPCs","group":"Characters","title":"Millicent (Third Location)","desc":"Found at the hill.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3197","x":0.351222753,"y":0.382793082,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (Stormcaller Church)","desc":"Found inside <a href='https://eldenring.wiki.fextralife.com/Stormcaller+Church' target=\"_blank\">Stormcaller Church</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"5772","x":0.297149717,"y":0.382854123,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Lux Ruins","desc":"Found just north of <a href='https://eldenring.wiki.fextralife.com/Lux+Ruins' target=\"_blank\">Lux Ruins</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"3655","x":0.46119304,"y":0.383469411,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [6]","desc":"At <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\"> Auriza Hero's Grave</a>, can be found while passing the third part of the giant chariots, on a small platform in the middle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8852","x":0.477001551,"y":0.38364765,"cat":"Consumables","group":"Items","title":"Fan Daggers - 5x Auriza Hero's Grave","desc":"Offensive Consumable. A <strong>set of 5</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>. In the first chariot hall just before the second chariot ramp, there is a corpse hanging off an opening on the right side from which the items can be looted.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5911","x":0.326293672,"y":0.383678168,"cat":"Talismans","group":"Equipment","title":"Sacrificial Twig - Altus Plateau","desc":"Can be found inside a chest at an enemy camp.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"5968","x":0.481672769,"y":0.383769731,"cat":"Sites of Grace","group":"Locations","title":"Frenzied Flame Proscription","desc":"Reached upon defeating <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/mohg,+the+omen'>Mohg, the Omen</a>, at <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/subterranean+shunning-grounds'>Subterranean Shunning-Grounds</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8216","x":0.475356085,"y":0.383830771,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Auriza Hero's Grave","desc":"Summoning Pool Effigy found next to the Auriza Hero's Grave site of grace in the Altus Plateau. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"8302","x":0.328706105,"y":0.383861289,"cat":"Key Items","group":"Items","title":"Perfume Bottle - Altus Highway Junction","desc":"<p>Located south of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Second+Church+of+Marika' target=\"\">Second Church of Marika</a>. North Altus Highway Junction, in the small camp next to the Erdtree sappling, enemies are guarding a body with the bottle.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2132","x":0.234869645,"y":0.384105451,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [5] - 3x Unsightly Catacombs","desc":"Spirit Ash Upgrade Material. A total of 3 can be found inside the <a href='https://eldenring.wiki.fextralife.com/Unsightly+Catacombs' target=\"_blank\">Unsightly Catacombs</a>. <ol> <li>The first is found in the first big hall with multiple levels. Go through the side corridors towards the back to find the glovewort.</li> <li>The second one is found by going down one level and heading to the connecting room in the east, behind the Winged Misbegotten and Rotten Stray.</li> <li>The last one is found in a corner of a pit you drop into from an L-shaped staircase.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5815","x":0.247047094,"y":0.384135974,"cat":"Talismans","group":"Equipment","title":"Perfumer's Talisman","desc":"In a chest underground below stairs in the room with the yellow Giant Poison Flower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"7709","x":0.483623049,"y":0.384288573,"cat":"NPCs","group":"Characters","title":"Hyetta (Final Location)","desc":"NPC. Hyetta will move to this location if her questline has been followed.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"8854","x":0.479063791,"y":0.384404552,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [5] - Auriza Hero's Grave","desc":"Spirit Ash Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>: <ul> <li>In the first Chariot Hall, drop down the openings on either side just before the second ramp. In the room below, head west and up the steps. The glovewort can be found at the very end of the following corridor.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"10230","x":0.411983553,"y":0.384423159,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Capital Outskirts West","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Capital+Outskirts' target=\"blank\">Capital Outskirts</a>, northwest of the capital, below the main bridge at the moat surrounding the capital.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"8205","x":0.242223888,"y":0.384685338,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Unsightly Catacombs","desc":"Summoning Pool Effigy found at the end of the large hallway after the Unsightly Catacombs site of grace in the Altus Plateau. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4600","x":0.458687242,"y":0.384935606,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] - Subterranean Shunning-Grounds","desc":"Upgrade Material. One found in the Aqueducts section of the <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3194","x":0.348750198,"y":0.384960018,"cat":"Locations","group":"Locations","title":"Stormcaller Church","desc":"A small church located on a steppe. There is a <a href='https://eldenring.wiki.fextralife.com/Sacred+Tear' target=\"_blank\"> Sacred Tear</a> inside.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"3185","x":0.330654826,"y":0.385387302,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Altus Highway Junction","desc":"Flask Upgrade Material. Found right next to the road heading north from the <strong>Altus Highway Junction</strong> site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"5790","x":0.309265083,"y":0.385478865,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Blood Blade","desc":"Dropped by a Teardrop Scarab in Altus Plateau, northeast of Erdtree-Gazing Hill, flying above a pond with trees.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"8859","x":0.47640972,"y":0.38563757,"cat":"Consumables","group":"Items","title":"Holy Grease - 2x Auriza Hero's Grave","desc":"Weapon Coating. A <strong>set of 2</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>: <ul> <li>In the large Chariot Hall where two Chariots are running side by side with a short delay between them, head all the way down to the large pit behind some pillars. Looking down, you can find several wooden beams you can drop down to. Align yourself with the closest one and drop down, then drop down once more to a second beam below where the items can be looted off a corpse.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3198","x":0.352921654,"y":0.386125894,"cat":"Spells","group":"Equipment","title":"Dragonbolt Blessing","desc":"Found inside a chest at<a href='https://eldenring.wiki.fextralife.com/Stormcaller+Church' target=\"_blank\"> Stormcaller Church</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"8855","x":0.478246173,"y":0.386211351,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [6] - Auriza Hero's Grave","desc":"Spirit Ash Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Auriza+Hero's+Grave' target=\"_blank\">Auriza Hero's Grave</a>: <ul> <li>In the first Chariot Hall, drop down the openings on either side just before the second ramp. In the room below, head west and up the steps and then turn right into the next corridor. Follow the path to a second Chariot Hall where two Chariots are running side by side with a short delay between them. As you exit into this hall, turn left to find two ramps. In between them in the back is a small opening where the glovewort can be found.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5713","x":0.482894039,"y":0.38636395,"cat":"Shields","group":"Equipment","title":"Fingerprint Stone Shield","desc":"Subterranean shunning grounds. Past the Altar you Fight mini boss version of Mohg. After defeating him you can roll/attack the altar behind the chest and it will move down out of the way revealing a path. If you have not defeated Morgott, the Omen King a seal will be blocking further progress. Following this path will lead you to the hardest part which is jumping from coffin to coffin to make your way down to the area. NOTE it is slightly above the bottom floor so do not jump off even if you will survive. If you miss that coffin, you will have to start from the beginning of the coffin descend all over to obtain the shield.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"3027","x":0.380516855,"y":0.386608113,"cat":"Consumables","group":"Items","title":"Golden Rune [6] B","desc":"Found as you enter the cemetery, on the left side on a grave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2133","x":0.236273562,"y":0.386638634,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [5] - Unsightly Catacombs","desc":"Spirit Ash Upgrade Material. Found by the wall in the pit you drop into from the L-shaped staircase.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5795","x":0.290635188,"y":0.386942372,"cat":"Bosses","group":"Characters","title":"Demi-Human Queen Gilika","desc":"Field boss found inside the <a href='https://eldenring.wiki.fextralife.com/Lux+Ruins' target=\"_blank\"> Lux Ruins</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5789","x":0.258123354,"y":0.387065918,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Sacred Order","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\"> Teardrop Scarab</a> in Altus Plateau, just north of the Site Of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"4598","x":0.456855961,"y":0.387212415,"cat":"Key Items","group":"Items","title":"Stonesword Key - Subterranean Shunning-Grounds","desc":"<a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a>. One found in the Aqueducts section of the <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a>. From the Underground Roadside site of grace, head northeast and drop down into an opening in the ground to enter the aqueducts. From here, head northwest past the rats and look for a tunnel on the right. Follow this tunnel until you see slimes and drop into the hole in front of them. Follow the path all the way to the end to grab the key on a corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2134","x":0.239187601,"y":0.38731008,"cat":"Spirit Ashes","group":"Equipment","title":"Winged Misbegotten Ashes","desc":"Spirit Ash. Found on a corpse in a pit inside the <a href='https://eldenring.wiki.fextralife.com/Unsightly+Catacombs' target=\"_blank\">Unsightly Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"1956","x":0.242552485,"y":0.387401639,"cat":"Sites of Grace","group":"Locations","title":"Unsightly Catacombs","desc":"Site of Grace near the Unsightly Catacombs entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3029","x":0.378044741,"y":0.388042566,"cat":"Consumables","group":"Items","title":"Golden Rune [3]","desc":"Located in the cemetery to the right side.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10224","x":0.368478298,"y":0.388225688,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Perfumer's Grotto Entrace","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>, <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Perfumer's+Grotto' target=\"blank\">Perfumer's Grotto</a> Entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"6264","x":0.296052188,"y":0.388256206,"cat":"NPCs","group":"Characters","title":"Rya (Second Location A)","desc":"Rya spawns here if the player completed the interaction with her in Liurnia of the Lakes but has not obtained both portions of the Dectus Medallion. She will teleport you to the Volcano Manor if you talk to her.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"4591","x":0.37336866,"y":0.388903235,"cat":"Weapons","group":"Equipment","title":"Great Omenkiller Cleaver","desc":"Greataxe. Dropped by the boss duo of <a href='https://eldenring.wiki.fextralife.com/Perfumer's+Grotto' target=_blank\">Perfumer's Grotto</a>: <a href='https://eldenring.wiki.fextralife.com/Omenkiller' target=\"_blank\">Omenkiller</a> and <a href='https://eldenring.wiki.fextralife.com/Miranda+the+Blighted+Bloom' target=\"_blank\">Miranda the Blighted Bloom</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greataxe.png?h=40"},{"id":"6664","x":0.475148924,"y":0.389080255,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [6] - 1x Leyndel Royal Capital","desc":"Upgrade material. Found behind a statue in a ditch within Leyndell Royal Capital.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"1232","x":0.46592774,"y":0.389141295,"cat":"Sites of Grace","group":"Locations","title":"East Capital Rampart","desc":"Site of Grace at East Capital.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8220","x":0.464800148,"y":0.389232858,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: East Capital Rampart","desc":"Summoning Pool Effigy found next to the East Capital Rampart site of grace in the Leyndell, Royal Capital. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6391","x":0.480328771,"y":0.389293906,"cat":"Spells","group":"Equipment","title":"Inescapable Frenzy","desc":"After making your way past <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a> and defeating <a href='https://eldenring.wiki.fextralife.com/Mohg,+The+Omen' target=\"_blank\">Mohg, the Omen</a>, attack the altar at the front of the boss room. It should lower revealing a new area. Continue through here until you are forced to parkour downwards using stone coffins as platforms. Near the bottom you will see a corpse that has Inescapable Frenzy on it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"3028","x":0.379509699,"y":0.389354935,"cat":"Consumables","group":"Items","title":"Silver-Pickled Fowl Foot (B)","desc":"Further in the cemetery, past the Golden Rune (6),","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4567","x":0.295562636,"y":0.389477016,"cat":"Sites of Grace","group":"Locations","title":"Erdtree-Gazing Hill","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6374","x":0.477267073,"y":0.38969066,"cat":"Spells","group":"Equipment","title":"Bloodflame Talons","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Mohg,+the+Omen' target=\"_blank\">Mohg, the Omen</a> in <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a>, Subterranean Shunning-Grounds, under <a href='https://eldenring.wiki.fextralife.com/Leyndell' target=\"_blank\">Leyndell</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"3829","x":0.473793232,"y":0.389809811,"cat":"Consumables","group":"Items","title":"Soporific Grease (C)","desc":"Found lying in the middle of the ground. Beware enemies nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6256","x":0.531095689,"y":0.390148462,"cat":"Bosses","group":"Characters","title":"Night's Cavalry (Forbidden Lands)","desc":"Roams the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Forbidden+Lands'>Forbidden Lands</a> at night time, along the path to the <a href='https://eldenring.wiki.fextralife.com/Grand+Lift+of+Rold' target=\"_blank\">Grand Lift of Rold</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Ash+of+War:+Phantom+Slash' target=\"_blank\">Ash of War: Phantom Slash</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3679","x":0.461588993,"y":0.390178984,"cat":"Consumables","group":"Items","title":"Golden Rune [9] D","desc":"Found on a big chapel with statues, where there's also a knight that performs the same moveset as Crucible Knight Ordivis, on a body , near the left exit.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5823","x":0.289727318,"y":0.390266882,"cat":"Talismans","group":"Equipment","title":"Ritual Sword Talisman","desc":"Located in <a href='https://eldenring.wiki.fextralife.com/Lux+Ruins'>Lux Ruins</a>, in a chest after defeating <a href='https://eldenring.wiki.fextralife.com/Demi-Human+Queen+Gilika'>Demi-Human Queen Gilika</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6110","x":0.369560196,"y":0.390362105,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - Perfumer's Grotto","desc":"<p>Found within <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Perfumer's+Grotto' target=\"\">Perfumer's Grotto</a> in the area just outside the fog gates at the end of the tunnel.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5726","x":0.479105154,"y":0.390391893,"cat":"Sites of Grace","group":"Locations","title":"Cathedral of the Forsaken","desc":"Subterranean site of grace. In the room where you fight <a href='https://eldenring.wiki.fextralife.com/Mohg,+The+Omen' target=\"_blank\">Mohg, The Omen</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8502","x":0.451277357,"y":0.390575745,"cat":"Weapons","group":"Equipment","title":"Sword of Milos","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Dung+Eater' target=\"_blank\">Dung Eater</a> in <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"7752","x":0.372035012,"y":0.390606267,"cat":"Bosses","group":"Characters","title":"Miranda the Blighted Bloom (Perfumer's Grotto)","desc":"<strong>Miranda the Blighted Bloom</strong> is encountered in a <strong>Duo Boss Fight</strong> with an <a href='https://eldenring.wiki.fextralife.com/Omenkiller' target=\"_blank\">Omenkiller</a> inside the <a href='https://eldenring.wiki.fextralife.com/Perfumer's Grotto' target=\"_blank\">Perfumer's Grotto</a>. Defeating them both awards the <a href='https://eldenring.wiki.fextralife.com/Great+Omenkiller+Cleaver' target=\"_blank\">Great Omenkiller Cleaver</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"4593","x":0.376460097,"y":0.390697826,"cat":"Key Items","group":"Items","title":"Perfume Bottle - Perfumer's Grotto","desc":"Crafting Material. One bottle can be looted from a chest inside <a href='https://eldenring.wiki.fextralife.com/Perfumer's+Grotto' target=\"_blank\">Perfumer's Grotto</a>. In the second area after encountering the second <a href='https://eldenring.wiki.fextralife.com/Giant+Poison+Flower' target=\"_blank\">Giant Poison Flower</a>, turn back towards the corner to find two chests, one of which contains the bottle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4590","x":0.374522507,"y":0.390728348,"cat":"Bosses","group":"Characters","title":"Omenkiller (Perfumer's Grotto)","desc":"An <strong>Omenkiller</strong> encountered in a <strong>Duo Boss Fight</strong> with <a href='https://eldenring.wiki.fextralife.com/Miranda+the+Blighted+Bloom' target=\"_blank\">Miranda the Blighted Bloom</a> inside the <a href='https://eldenring.wiki.fextralife.com/Perfumer's Grotto' target=\"_blank\">Perfumer's Grotto</a>. Defeating them both awards the <a href='https://eldenring.wiki.fextralife.com/Great+Omenkiller+Cleaver' target=\"_blank\">Great Omenkiller Cleaver</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"3842","x":0.398074906,"y":0.390774739,"cat":"Weapons","group":"Equipment","title":"Gargoyle's Great Axe","desc":"Dropped by<a class=\"wiki_link\" href='https://eldenring.wiki.fextralife.com/Gargoyle' target=\"_blank\">Gargoyle</a>. From the <a class=\"wiki_link\" href='https://eldenring.wiki.fextralife.com/Outer+Wall+Phantom+Tree' target=\"_blank\">Outer Wall Phantom Tree</a>.Site of Grace go northeast the Slope/long Stairs up until it spawns.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greataxe.png?h=40"},{"id":"8501","x":0.448561082,"y":0.390880948,"cat":"Armor","group":"Equipment","title":"Omen Set","desc":"Drops from <a href='https://eldenring.wiki.fextralife.com/Dung+Eater'>Dung Eater</a> if defeated in <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds'>Subterranean Shunning-Grounds</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"3014","x":0.464978948,"y":0.390941988,"cat":"NPCs","group":"Characters","title":"Boc the Seamster (Sixth Location)","desc":"Boc appears in the East Capital Rampart site of grace. You have to rest at this Site of Grace for him to appear. He offers his sewing services as well as makes some conversation regarding the Erdtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"8623","x":0.459520159,"y":0.391094591,"cat":"Armor","group":"Equipment","title":"Leather-Draped Tabard","desc":"Chance to drop from regular Soldier enemies found in <a href='https://eldenring.wiki.fextralife.com/Leyndell+Royal+Capital+(Legacy+Dungeon)' target=\"_blank\">Leyndell, Royal Capital</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"6266","x":0.528173332,"y":0.391521875,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Phantom Slash","desc":"Ash of War. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> boss that roams the path towards the <a href='https://eldenring.wiki.fextralife.com/Grand+Lift+of+Rold' target=\"_blank\">Grand Lift of Rold</a> at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"7559","x":0.48070355,"y":0.391613434,"cat":"Armor","group":"Equipment","title":"Nomadic Merchant's Set","desc":"Full Armor Set. In the hidden tunnels behind the altar in Mohg, the Omen's boss room at the Cathedral of the Forsaken Site of Grace in the Subterranean Shunning-Grounds below Leyndell, Royal Capital. After opening the secret passage behind the altar and taking the stairs down, after crossing the narrow fallen rafter, directly to the left is a tent and in the far corner you can find the full Nomadic Merchant's set. To get access to the set, you need to destroy tent by either aggroing the enemy close by, leading it next to the tent and baiting its frenzy attack onto it or quit-outing while standing very close to tent itself.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"3677","x":0.463176027,"y":0.391857596,"cat":"Consumables","group":"Items","title":"Hero's Rune [5]","desc":"Found inside the big room with the statues and the knight that can perform the same moves as Crucible Knight Ordovis, on a body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"14154","x":0.447522652,"y":0.391888118,"cat":"Bosses","group":"Characters","title":"Ulcerated Tree Spirit","desc":"Can be found in the 2nd Lower Floor, in Leyndell Royal Capital.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"5801","x":0.335598628,"y":0.39213228,"cat":"NPCs","group":"Characters","title":"Boc the Seamster (Fifth Location)","desc":"Found at the Altus Highway Junction site of grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"4603","x":0.44990478,"y":0.392559563,"cat":"NPCs","group":"Characters","title":"Dung Eater (Subterranean Shunning-Grounds)","desc":"Quest NPC. Found in a cell in the <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a> beneath the Royal Capital. To reach his cell, head northeast from the Underground Roadside site of grace and enter a grate in the floor to access the aqueducts. Continue north past the Rats and Giant Poison Flower and climb up the ladder. You can find the cell door in the next room past the ladder. It is unlocked using the <a href='https://eldenring.wiki.fextralife.com/Sewer-Gaol+Key' target=\"_blank\">Sewer-Gaol Key</a> given by the same NPC but in his non-corporeal form at the <a href=\"Roundtable+Hold\" target=\"_blank\">Roundtable Hold</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"5727","x":0.482221104,"y":0.392895277,"cat":"Talismans","group":"Equipment","title":"Erdtree's Favor +1","desc":"Found inside a chest, in the room where you fight <a href='https://eldenring.wiki.fextralife.com/Mohg,+The+Omen' target=\"_blank\">Mohg, The Omen</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3925","x":0.444171028,"y":0.392986847,"cat":"Consumables","group":"Items","title":"Dragonwound Grease (B)","desc":"At the end of the corridor, in front of a giant door, NW of Avenue Balcony site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3839","x":0.453075005,"y":0.393383608,"cat":"Armor","group":"Equipment","title":"Guilty Hood","desc":"Held by a corpse on the right side of the sewer-like tunnel.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"4588","x":0.37410872,"y":0.393383608,"cat":"Locations","group":"Locations","title":"Perfumer's Grotto","desc":"A cave found below the <strong>Great Bridge</strong> to the <a href='https://eldenring.wiki.fextralife.com/Capital+Outskirts' target=\"_blank\">Capital Outskirts</a>. Its entrance is found below the northern side of the bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"8213","x":0.378534548,"y":0.393383608,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Perfumer's Grotto","desc":"Summoning Pool Effigy found at the end of the long tunnel past the Perfumer's Grotto site of grace in the Altus Plateau. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4571","x":0.376392984,"y":0.393444649,"cat":"Sites of Grace","group":"Locations","title":"Perfumer's Grotto","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2136","x":0.278371444,"y":0.393597252,"cat":"Bosses","group":"Characters","title":"Ancient Dragon Lansseax","desc":"A large white 4 winged dragon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"4566","x":0.294495604,"y":0.393810892,"cat":"Locations","group":"Locations","title":"Lux Ruins","desc":"Ruins located north of the <a href='https://eldenring.wiki.fextralife.com/Grand+Lift+of+Dectus' target=\"_blank\">Grand Lift of Dectus</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"3681","x":0.469190834,"y":0.393871933,"cat":"Weapons","group":"Equipment","title":"Iron Cleaver","desc":"Dropped by one of the enemies that can be found at behind the big door, on the right side.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-axe.png?h=40"},{"id":"5762","x":0.331844939,"y":0.394055054,"cat":"Sites of Grace","group":"Locations","title":"Altus Highway Junction","desc":"Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3923","x":0.443159287,"y":0.394634941,"cat":"Consumables","group":"Items","title":"Holyproof Dried Liver","desc":"On the sewers, past the <a href='https://eldenring.wiki.fextralife.com/Broken+Statue' target=\"_blank\">Broken Statue</a>, on the room below there are three items to grab, one of those is this one.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5825","x":0.310884079,"y":0.3947265,"cat":"Weapons","group":"Equipment","title":"Troll's Golden Sword","desc":"In a Chest on a Black Carriage, which can be found east of Erdtree-Gazing Hill site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossalsword.png?h=40"},{"id":"4604","x":0.449599286,"y":0.39478754,"cat":"Ashes of War","group":"Equipment","title":"Lost Ashes of War - Subterranean Shunning-Grounds","desc":"Lost Ashes of War. Found in the room before Dung Eater's cell in the <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a> beneath the Royal Capital. Beware the Giant Spider Hand that emerges as you loot the item.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"3675","x":0.455765154,"y":0.395001184,"cat":"Consumables","group":"Items","title":"Golden Rune [9] B","desc":"Found at the patio, on a body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3867","x":0.446733789,"y":0.395184305,"cat":"Consumables","group":"Items","title":"Clarifying Boluses","desc":"Found on the upper platform where there are some enemies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3828","x":0.478224976,"y":0.395245346,"cat":"Consumables","group":"Items","title":"Exalted Flesh","desc":"Found hanging over an edge, above the staircase. Near a tree and some graves.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3843","x":0.452954237,"y":0.395275864,"cat":"Weapons","group":"Equipment","title":"Black Bow","desc":"Bow that can be found on the roof on the right that overlooks the area. Need to jump from roof to roof in order to reach it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bow.png?h=40"},{"id":"3835","x":0.30531156,"y":0.395306386,"cat":"Talismans","group":"Equipment","title":"Greatshield Talisman","desc":"Found in a chest on a Wagon East of Grace \"Erdtree-Gazing Hill\" behind Ancient Dragon Lansseax.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6617","x":0.461544564,"y":0.395306386,"cat":"Key Items","group":"Items","title":"Stonesword Key - Leyndell, Royal Capital (F)","desc":"On the rooftop of one of the buildings, held by a corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4601","x":0.466538576,"y":0.395428467,"cat":"Spirit Ashes","group":"Equipment","title":"Nomad Ashes","desc":"Spirit Ashes. Found on a corpse in the <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a>beneath the capital. This is in a large, multi-level section in the east.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"3924","x":0.441724623,"y":0.395458986,"cat":"Weapons","group":"Equipment","title":"Erdsteel Dagger","desc":"Drop down a pit with a Broken Statue and it will be on a corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"4568","x":0.297331795,"y":0.395550548,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Shield Crash","desc":"Ash of war with no affinity, dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> in the <a href='https://eldenring.wiki.fextralife.com/Lux+Ruins' target=\"_blank\">Lux Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"3840","x":0.451186023,"y":0.395642107,"cat":"Consumables","group":"Items","title":"Golden Rune [8] D","desc":"Found on the left side of the sewers, where the rats are.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7921","x":0.464524064,"y":0.395703148,"cat":"Key Items","group":"Items","title":"Frenzied's Cookbook [2]","desc":"Is found nearest to the Cathedral of the Forsaken Site of Grace in the Subterranean Shunning-Grounds below Leyndell, Royal Capital. Behind the altar in Mohg, the Omen's boss room is a hidden path which can be opened by attacking the altar behind the chest after the boss fight. Following the the hidden path, there are stairs down and will lead to collapsed rafters that you can cross; you can cross the path and follow the stairs down for a safer route, or drop directly below on second set of collapsed rafters. On the second set of rafters, you will need to drop down to the lowest set of them, and you will find Frenzied's Cookbook [2] on a sitting corpse","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"8714","x":0.45820733,"y":0.396191472,"cat":"Armor","group":"Equipment","title":"Bloodsoaked Manchettes","desc":"From the Underground Roadside grace, head to the main tunnel and turn left. Go forward until you find crates, barrels and debris on the right side of the main tunnel. The item is over there.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-gauntlets.png?h=40"},{"id":"3684","x":0.473886972,"y":0.396204903,"cat":"Consumables","group":"Items","title":"Golden Rune [9] C","desc":"Found on a body that two dogs are devouring.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3259","x":0.515663255,"y":0.396283034,"cat":"Consumables","group":"Items","title":"Drawstring Fire Grease (B)","desc":"Turn back from the Forbidden Lands site of grace, head to the body to obtain x2 Drawstring Fire Grease","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3672","x":0.459422076,"y":0.396344075,"cat":"Consumables","group":"Items","title":"Lord's Rune","desc":"Drops from the <a href='https://eldenring.wiki.fextralife.com/Erdtree+Avatar' target=\"_blank\">Erdtree Avatar</a> that patrols the road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4580","x":0.453474723,"y":0.396374593,"cat":"Sites of Grace","group":"Locations","title":"Underground Roadside","desc":"Site of Grace found underground in the <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6263","x":0.455613409,"y":0.396588237,"cat":"Bosses","group":"Characters","title":"Mohg, the Omen","desc":"Located at the end of the Subterranean Shunning-Grounds.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3827","x":0.476818867,"y":0.396618755,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly (D)","desc":"Found on a body over the stairs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5857","x":0.463606988,"y":0.396862918,"cat":"Sites of Grace","group":"Locations","title":"Forsaken Depths","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3851","x":0.449724131,"y":0.397046039,"cat":"Key Items","group":"Items","title":"Cracked Pot - Leyndell, Royal Capital","desc":"Crafting Pot. Found inside a room in the northern area, where you fight the Leyndell Royal Guard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"4611","x":0.452590554,"y":0.397046039,"cat":"Locations","group":"Locations","title":"Subterranean Shunning-Grounds","desc":"A massive underground sewer network found beneath the Royal Capital. The entrance can be found in a well northeast of the Avenue Balcony.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-subterranean-shunning-grounds.png?h=40"},{"id":"2856","x":0.411029399,"y":0.397259682,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Prayerful Strike","desc":"On the lake under the short rocky tunnel, dropped by the invisible mob that leaves paw prints on its path.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"2859","x":0.468030929,"y":0.397290193,"cat":"Consumables","group":"Items","title":"Golden Rune [10]","desc":"In the platform where you fight the improved <a href='https://eldenring.wiki.fextralife.com/Trumpeteer' target=_\"blank\">Trumpeteer</a>, against the wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1134","x":0.391988943,"y":0.397290201,"cat":"Maps","group":"Locations","title":"Map (Leyndell, Royal Capital)","desc":"Map Fragment. Reveals the Leyndell region. Found on a monolith near the Outer Wall Phantom Tree Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"8219","x":0.462326987,"y":0.397320723,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Subterranean Shunning-Grounds (Forsaken Depths)","desc":"Summoning Pool Effigy found next to the door near the Forsaken Depths site of grace in the Subterranean Shunning-Grounds. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3674","x":0.458236123,"y":0.397595403,"cat":"Consumables","group":"Items","title":"Golden Rune [9]","desc":"Can be found near the wheel of a chariot, at the main road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3836","x":0.454149345,"y":0.397717485,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] I","desc":"Found on a patio, in what seems to be a cemetery district. A skeleton will drop down on you once you approach this item.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8293","x":0.465249907,"y":0.397748007,"cat":"Armor","group":"Equipment","title":"Imp Head (Corpse)","desc":"The easiest way to reach is by falling from above over the buildings with golden roofs and then down again, head to the northern dark passage between the buildings to the west and at the end of it, jump down. You will find this item on a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"1133","x":0.38890615,"y":0.397778525,"cat":"Sites of Grace","group":"Locations","title":"Outer Wall Phantom Tree","desc":"Site of Grace found next to the Phantom Tree on the outskirts of Leyndell.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1136","x":0.375910298,"y":0.398144768,"cat":"Bosses","group":"Characters","title":"Tree Sentinel (Leyndell, Royal Capital)","desc":"Field Bossfight. Two <strong>Tree Sentinels</strong> guarding the western gate to Leyndell.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"1452","x":0.522070777,"y":0.398144768,"cat":"Sites of Grace","group":"Locations","title":"Forbidden Lands","desc":"Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8291","x":0.455888066,"y":0.398205808,"cat":"Armor","group":"Equipment","title":"Bloodsoaked Mask","desc":"From the Underground Roadside grace, head to the main tunnel and turn left. Go forward until you find crates, barrels and debris on the right side of the main tunnel. The item is over there.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"4602","x":0.460835087,"y":0.398358412,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - Subterranean Shunning-Grounds","desc":"Upgrade Material. One found at a dead end tunnel that slopes downwards, inside the central Aqueduct section of the <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a> beneath the Royal Capital.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"9008","x":0.519350776,"y":0.39843166,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Forbidden Lands","desc":"Summoning Pool Effigy found near the Forbidden Lands Site of Grace area. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2137","x":0.210949634,"y":0.398541533,"cat":"Armor","group":"Equipment","title":"Snow Witch Set","desc":"Armor Set. Found in a chest on the upper floor of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Renna's+Rise'>Renna's Rise</a> after reaching the end of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Ranni+the+Witch'>Ranni's</a> questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"6693","x":0.450487221,"y":0.398663614,"cat":"Talismans","group":"Equipment","title":"Lord of Blood's Exultation","desc":"Drops from <a href='https://eldenring.wiki.fextralife.com/Esgar,+Priest+of+Blood' target=\"_blank\">Esgar, Priest of Blood</a> in <a href='https://eldenring.wiki.fextralife.com/Leyndell Catacombs' target=\"_blank\">Leyndell Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3671","x":0.457661014,"y":0.398724655,"cat":"Bosses","group":"Characters","title":"Erdtree Avatar (Leyndell)","desc":"Mini boss that patrols the main road in <a href='https://eldenring.wiki.fextralife.com/Leyndell,+Royal+Capital' target=\"_blank\">Leyndell, Royal Capital</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Lord's+Rune' target=\"_blank\">Lord's Rune</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2865","x":0.466016687,"y":0.398846736,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4]","desc":"After defeating the first enhanced Trumpeteer, drop down to the platform below, and enter the room in the back. Beware of the assassin hidden inside.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"9807","x":0.316832705,"y":0.398968817,"cat":"Consumables","group":"Items","title":"Fan Daggers - 5x Altus Plateau","desc":"Offensive Consumable. Looted from a corpse in a small encampment in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3926","x":0.443800202,"y":0.398999335,"cat":"Consumables","group":"Items","title":"Rune Arc M","desc":"Climb the \"wing\" of the dragon and once you are on top, jump to the room below. you will find one there.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3248","x":0.451739291,"y":0.399151938,"cat":"Sites of Grace","group":"Locations","title":"Avenue Balcony","desc":"Site of Grace on Avenue Balcony.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1184","x":0.390951548,"y":0.399212979,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - 2x Capital Outskirts West","desc":"Flask Upgrade Material. 2 can be found underneath the Phantom Tree at the <a href='https://eldenring.wiki.fextralife.com/Capital+Outskirts' target=\"_blank\">Capital Outskirts</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"7711","x":0.327864669,"y":0.399212979,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Earthshaker","desc":"Ash of War. Found by defeating an invisible Teardrop Scarab in the intersection of the road before Altus Highway Junction site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"3871","x":0.449480123,"y":0.399274019,"cat":"Key Items","group":"Items","title":"Stonesword Key - Leyndell, Royal Capital (C)","desc":"Found in the lower platform, open a door and find it inside the chest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"5718","x":0.372919303,"y":0.39933506,"cat":"Shields","group":"Equipment","title":"Erdtree Greatshield","desc":"Dropped by the <a href='https://eldenring.wiki.fextralife.com/Tree+Sentinel' target=\"_blank\">Tree Sentinel</a> duo","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"3673","x":0.454360096,"y":0.399487659,"cat":"Consumables","group":"Items","title":"Holy Grease","desc":"Over The main road, at the top of the wrecked chariot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3838","x":0.453203433,"y":0.399518181,"cat":"Key Items","group":"Items","title":"Stonesword Key - Leyndell, Royal Capital (D)","desc":"Found in front of a grave, there are three enemies in the vicinity","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1138","x":0.268527284,"y":0.399579222,"cat":"Sites of Grace","group":"Locations","title":"Abandoned Coffin","desc":"Site of Grace found at the foot of a hill littered with broken down stagecoaches.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1766","x":0.209605456,"y":0.399914943,"cat":"Locations","group":"Locations","title":"Renna's Rise","desc":"One of three towers found in the <a href='https://eldenring.wiki.fextralife.com/Three+Sisters' target=\"_blank\">Three Sisters</a> sub-region. Three Sisters is accessible after completing <a href='https://eldenring.wiki.fextralife.com/Caria+Manor' target=\"_blank\">Caria Manor</a> and defeating <a href='https://eldenring.wiki.fextralife.com/Royal+Knight+Loretta' target=\"_blank\">Royal Knight Loretta</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"3891","x":0.446488155,"y":0.400006505,"cat":"Armor","group":"Equipment","title":"Omensmirk Mask","desc":"Dropped an <em>Omensmirk</em> wielding double swords and wearing this mask outside of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'>Lower Capital Church Site of Grace</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"8217","x":0.456896632,"y":0.400088055,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Subterranean Shunning-Grounds (Underground Roadside)","desc":"Summoning Pool Effigy found next to the double doors across the room with the Underground Roadside site of grace in the Royal Capital. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2877","x":0.464246606,"y":0.400128586,"cat":"Weapons","group":"Equipment","title":"Red Branch Shortbow","desc":"Drops from an Assassin on the study, past the <a href='https://eldenring.wiki.fextralife.com/Trumpeteer' target=\"_blank\"> Trumpeteer</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bow.png?h=40"},{"id":"8827","x":0.450884892,"y":0.400128586,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Avenue Balcony","desc":"Summoning Pool Effigy found next to the Avenue Balcony Site of Grace in Leyndell, Royal Capital. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2138","x":0.207043086,"y":0.400220145,"cat":"Waygates","group":"Locations","title":"Renna's Rise Waygate","desc":"Waygate. Found at the top of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Renna's Rise'>Renna's Rise</a>. Teleports you to <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Ainsel+River+Main'>Ainsel River Main</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"5705","x":0.27214011,"y":0.40055587,"cat":"Armor","group":"Equipment","title":"Ruler's Set","desc":"Found on a corpse laying face-down on a carriage northeast of the<a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'> Abandoned Coffin Site of Grace</a>. You'll find it alongside the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/ruler's+mask'>Ruler's Mask</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"9808","x":0.317382505,"y":0.40070847,"cat":"Consumables","group":"Items","title":"Lightning Grease - Altus Plateau","desc":"Consumable. Looted from a corpse in the middle of a camp in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"\">Altus Plateau</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4114","x":0.442126911,"y":0.400738991,"cat":"Crafting Materials","group":"Items","title":"Gravel Stone - 6x Leyndell Royal Capital","desc":"You can find Gravel Stone at three different parts: 1) Found at the end of a dark alley, near the main road. 2) Found over the \"wing\" of the dragon once you manage to get over it. 3) Found at the ruined area, past the Fortified Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6695","x":0.449663286,"y":0.400738991,"cat":"Bosses","group":"Characters","title":"Esgar, Priest of Blood","desc":"Esgar, Priest of Blood is a Boss found in Leyndell, <a href='https://eldenring.wiki.fextralife.com/Leyndell+Royal+Capital' target=\"_blank\">Leyndell Royal Capital</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2867","x":0.467147056,"y":0.400800032,"cat":"Consumables","group":"Items","title":"Golden Rune [7]","desc":"Just in front of the <a href='https://eldenring.wiki.fextralife.com/Broken+Statue' target=\"_blank\" >Broken Statue</a>. You can kill it from behind if you take an alternate route, allowing you to grab this item without much of a hassle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2870","x":0.460646224,"y":0.400970945,"cat":"Key Items","group":"Items","title":"Perfume Bottle - Leyndell, Royal Capital (A)","desc":"Found inside a chest, within the second floor on the tower next to the East Rampart.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6694","x":0.451736088,"y":0.401074712,"cat":"Locations","group":"Locations","title":"Leyndell Catacombs","desc":"The Leyndell Catacombs is a massive underground mausoleum found beneath the Royal Capital. These catacombs are accessed via the <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"6383","x":0.509620213,"y":0.401135753,"cat":"Weapons","group":"Equipment","title":"Blade of Calling","desc":"From the <a href='https://eldenring.wiki.fextralife.com/Forbidden+Lands' target=\"_blank\"> Forbidden Lands</a> site of grace, turn back and head towards the elevator. Face southwest before activating the elevator, and then watch for an opening to jump off into. The Blade of Calling is on the table in the room at the end of this hall","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"14302","x":0.21598534,"y":0.401205341,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily - 3x Caria Manor Grounds","desc":"Crafting Material. Found within the grounds of Caria Manor","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3666","x":0.453047098,"y":0.401227315,"cat":"Crafting Materials","group":"Items","title":"Gold Firefly","desc":"Found 3 on a body laying on the middle of a road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3257","x":0.493220806,"y":0.401244407,"cat":"Consumables","group":"Items","title":"Invigorating White Cured Meat 2x","desc":"Found on a body in the middle of the bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4113","x":0.444228998,"y":0.401349396,"cat":"Crafting Materials","group":"Items","title":"Old Fang - 8x Leyndell, Royal Capital","desc":"x5 Found in what it looks like a small stable, outside of Fortified Manor, protected by two guards. x3 Found on a body that's being devoured by two dogs. Near the main road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3832","x":0.487412035,"y":0.401501996,"cat":"Talismans","group":"Equipment","title":"Flamedrake Talisman +1","desc":"Found on the ground, against a column. The path is a blocked by a magic barrier if Morgott has not been defeated. You can still reach it by going slightly","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4634","x":0.454027858,"y":0.401532518,"cat":"Talismans","group":"Equipment","title":"Crimson Amber Medallion +2","desc":"By falling down the sewers gate, on the beam below, just before fully entering the <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds'>Subterranean Shunning-Grounds</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"2873","x":0.464395817,"y":0.401556934,"cat":"Key Items","group":"Items","title":"Seedbed Curse - East Leyndell, Royal Capital","desc":"Key Item. Found after you exit the room with East Capital Rampart grace, continue south past the Oracle Envoys and into the building. Inside, head down the stairs and face west to take the elevator. After the elevator continue west into the next building. Climb up the ladder to your right and go up the stairs. On the highest floor you will find the Seedbed Curse on a corpse sitting in a chair.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"9051","x":0.465198053,"y":0.401657759,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily - Leyndell, Royal Capital","desc":"<p>Found in <a class=\"wiki_link\" title=\"Elden Ring Leyndell, Royal Capital\" href='https://eldenring.wiki.fextralife.com/Leyndell,+Royal+Capital'>Leyndell, Royal Capital</a>. 5 can be found in planters in a plaza off the main road. </p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2065","x":0.296299185,"y":0.40177668,"cat":"Weapons","group":"Equipment","title":"Magma Wyrm's Scalesword","desc":"Curved Greatsword dropped by <a href='https://eldenring.wiki.fextralife.com/Magma+Wyrm+Makar' target=\"_blank\"> Magma Wyrm Makar</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedgreatsword.png?h=40"},{"id":"5836","x":0.292239623,"y":0.401868239,"cat":"Weapons","group":"Equipment","title":"Serpent-God's Curved Sword","desc":"Can be found at Ruin-Strewn Precipice, after the first singing bat go up two ladders then another one on the left and walk across to where the Land Octopus are","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedsword.png?h=40"},{"id":"1231","x":0.447006993,"y":0.402112401,"cat":"Locations","group":"Locations","title":"Leyndell, Royal Capital","desc":"Leyndell, Royal Capital.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-leyndell.png?h=40"},{"id":"2880","x":0.458845666,"y":0.402234482,"cat":"Consumables","group":"Items","title":"Fan Daggers","desc":"Found at the end of the alley on your left, beware of the enemy hiding behind the wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1708","x":0.290163528,"y":0.402387085,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4] - Ruin-Strewn Precipice","desc":"Can be found in the caves that go through the Ruin-Strewn Precipice.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2868","x":0.462385949,"y":0.402387085,"cat":"Consumables","group":"Items","title":"Preserving Boluses","desc":"Inside the next room, after you get down the lift. Beware of the lurking enemies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5860","x":0.448045123,"y":0.402448126,"cat":"Sites of Grace","group":"Locations","title":"Lower Capital Church","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8215","x":0.449388555,"y":0.402539684,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Leyndell Catacombs","desc":"Summoning Pool Effigy found in front of the Boss Doors of the Leyndell Catacombs in the Royal Capital. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1706","x":0.293947296,"y":0.402600725,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] - 3x Ruin-Strewn Precipice","desc":"There are at least 3 Smithing Stones (3) within the caves that go through <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Ruin-Strewn+Precipice'>Ruin-Strewn Precipice</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3910","x":0.444628459,"y":0.402692288,"cat":"Armor","group":"Equipment","title":"Deathbed Dress","desc":"Found on the bed in the building with the Lower Capital Church grace alonside the <a href='https://eldenring.wiki.fextralife.com/Lionel's+Set' target=\"_blank\">Lionel's Set</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"6381","x":0.44337815,"y":0.40321113,"cat":"Weapons","group":"Equipment","title":"Gravel Stone Seal","desc":"From the West Capital Rampart site of grace in Leyndell, walk north to the next room with the single guard inside. Jump over the balcony railing to get to the area next to the Fortified Manor with the dragon foot. The knight with the spear supported by an archer drops this seal.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacredseal.png?h=40"},{"id":"5751","x":0.510912088,"y":0.403333211,"cat":"Armor","group":"Equipment","title":"Official's Attire","desc":"From the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/forbidden+lands'>Forbidden Lands</a> <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'>Site of Grace</a>, turn back and head towards the elevator. Face southwest before activating the elevator, and then watch for an opening to jump off into. The <strong>Official's Attire</strong> is on the corpse in this hidden hallway alongside <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/blade+of+calling'>Blade of Calling</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"2879","x":0.460768422,"y":0.403455292,"cat":"Consumables","group":"Items","title":"Golden Rune [10]","desc":"On the big room, before the big spartan-like enemy. You can find this on the left side.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"9527","x":0.296196673,"y":0.403472345,"cat":"Consumables","group":"Items","title":"Lightningproof Dried Liver - Altus Plateau","desc":"Consumable. Found on a wrecked carriage near the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a> Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6377","x":0.452134342,"y":0.403485814,"cat":"Spells","group":"Equipment","title":"Shadow Bait","desc":"Can be found on a corpse at <a href='https://eldenring.wiki.fextralife.com/Subterranean+Shunning-Grounds' target=\"_blank\">Subterranean Shunning-Grounds</a>, after going through the pipe room to a room with the corpse sitting at the center, next to a not very well hidden <a href='https://eldenring.wiki.fextralife.com/Ogre' target=\"_blank\">Ogre</a> ready to strike.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"5788","x":0.282413031,"y":0.403516332,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Barbaric Roar","desc":"On a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> in Ravine-Veiled Village, found by going as far northeast as possible in Lake of Liurnia (near but not accessible from Grand Lift of Dectus)","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"5859","x":0.450911049,"y":0.403516332,"cat":"Sites of Grace","group":"Locations","title":"Leyndell Catacombs","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3667","x":0.453569084,"y":0.403668936,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] G","desc":"Found inside a small chapel, to the left side of the big main road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3883","x":0.449995746,"y":0.403852057,"cat":"Consumables","group":"Items","title":"Golden Rune [8] E","desc":"The first body on the staircase in the main road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"9806","x":0.30559085,"y":0.403852057,"cat":"Crafting Materials","group":"Items","title":"String - 5x Altus Plateau","desc":"Material. Looted from the corpse of a Demi Human surrounded by other demi-humans, located in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"9824","x":0.33598404,"y":0.403852057,"cat":"Crafting Materials","group":"Items","title":"Beast Blood - 1x Altus Plateau Campsite","desc":"Material. Found on a corpse lying on the ground in a small abandoned campsite in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"blank\">Altus Plateau</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2875","x":0.464553151,"y":0.403943616,"cat":"Crafting Materials","group":"Items","title":"Miranda Powder","desc":"Once you are back inside, roll onto the blocked door, and loot this on your left. You will get x10 Miranda Powder.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5793","x":0.321197492,"y":0.404126738,"cat":"Bosses","group":"Characters","title":"Night's Cavalry (Altus Plateau)","desc":"Found patrolling the road. Only appears at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"4116","x":0.442432026,"y":0.4042183,"cat":"Key Items","group":"Items","title":"Stonesword Key - Leyndell, Royal Capital (A)","desc":"Found on a small shack past the Fortified Manor, west of the Lower Capital Chuch Site of Grace. You have to jump around in order to reach it. There is a <a href='https://eldenring.wiki.fextralife.com/Smithing+Stone+(6)' target=\"_blank\">Smithing Stone (6)</a> on that same shack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1751","x":0.296512947,"y":0.404309859,"cat":"Bosses","group":"Characters","title":"Magma Wyrm Makar","desc":"This Boss fight is accessed through Ruin-Strewn Precipice, upon reaching the Ruin-Strewn Precipice Overlook Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"9805","x":0.399283509,"y":0.404554021,"cat":"Consumables","group":"Items","title":"Holy Grease 2x D","desc":"Consumable. Found on a body lying atop the small stone platform near the Outer Wall Phantom Tree Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6352","x":0.43836982,"y":0.404859224,"cat":"Weapons","group":"Equipment","title":"Stormhawk Axe","desc":"Looted from a dead body in the courtyard with Iron Maidens near Fortified Manor, First Floor at Leyndell, Royal Capital","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-axe.png?h=40"},{"id":"8294","x":0.445511605,"y":0.404920264,"cat":"Armor","group":"Equipment","title":"Lionel's Set","desc":"Next to the Lower Capital Church site of grace, over a bed. <br />IMPORTANT: If you burn the Erdtree and progress to the Ashen Capital, you can no longer obtain Lionel's Set if you haven't picked it up earlier.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"3823","x":0.478193909,"y":0.404981305,"cat":"Key Items","group":"Items","title":"Perfume Bottle - Leyndell, Royal Capital (B)","desc":"Found guarded by a lesser Leonine Misbegotten on the east side of the eastern pond.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3885","x":0.44865433,"y":0.405042345,"cat":"Consumables","group":"Items","title":"Golden Rune [12] B","desc":"The second body on the staircase in the main road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5791","x":0.323264994,"y":0.405347548,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Shared Order","desc":"Dropped by the <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"1702","x":0.287600123,"y":0.405408589,"cat":"Crafting Materials","group":"Items","title":"Smoldering Butterfly - Ravine-Veiled Village","desc":"Within Ravine-Veiled Village, near Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3913","x":0.452010359,"y":0.405469629,"cat":"Ashes of War","group":"Equipment","title":"Lost Ashes of War - Leyndell, Royal Capital","desc":"Found at the bottom of the sewers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"3887","x":0.447006255,"y":0.405530669,"cat":"Consumables","group":"Items","title":"Lightningproof Dried Liver","desc":"Found on the third body on the staircase in the main road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2872","x":0.466717283,"y":0.405530681,"cat":"Armor","group":"Equipment","title":"Upper-Class Robe","desc":"Found at the end of tha passageway. Beware of the <a href='https://eldenring.wiki.fextralife.com/Bedouin' target=\"_blank\">Bedouin</a> on your left side.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"3669","x":0.462388293,"y":0.405866394,"cat":"Consumables","group":"Items","title":"Golden Rune [8] C","desc":"Found at the end of an alleway, there is a Broken Statue at the end. There is also a <a href='https://eldenring.wiki.fextralife.com/Golden+Rune+(11)' target=\"_blank\">Golden Rune (11)</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3541","x":0.268344363,"y":0.405957953,"cat":"NPC Invaders","group":"Characters","title":"Great Horned Tragoth","desc":"Assassination target for the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>. You can invade their world using a summoning sign after accepting the assassination request.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"1860","x":0.231610843,"y":0.406018993,"cat":"Spells","group":"Equipment","title":"Frozen Armament","desc":"<a href='https://eldenring.wiki.fextralife.com/Sorceries' target=\"_blank\">Sorcery</a>. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> in an area behind Caria Manor. This area is accessible after completing the manor and defeating <a href='https://eldenring.wiki.fextralife.com/Royal+Knight+Loretta' target=\"_blank\">Royal Knight Loretta</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"1767","x":0.211772501,"y":0.406080034,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Chilling Mist","desc":"Ash of War. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> in the ruins south of <a href='https://eldenring.wiki.fextralife.com/Renna's+Rise' target=\"_blank\">Renna's Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"6752","x":0.440327267,"y":0.406110556,"cat":"Key Items","group":"Items","title":"Flightless Bird Painting","desc":"Key Info Item. Next to the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'>Fortified Manor, First Floor Site of Grace</a> in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/leyndell,+royal+capital'>Leyndell, Royal Capital</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3659","x":0.266478605,"y":0.406171596,"cat":"Sites of Grace","group":"Locations","title":"Magma Wyrm Site of Grace","desc":"Site of Grace for Magma Wyrm","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3668","x":0.458420701,"y":0.406354718,"cat":"Consumables","group":"Items","title":"Golden Rune [8] B","desc":"Found at the end of the alleway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3952","x":0.444135412,"y":0.406354718,"cat":"Key Items","group":"Items","title":"Seedbed Curse - West Leyndell, Royal Capital","desc":"Found on a body on the library area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1453","x":0.516507167,"y":0.40681252,"cat":"Bosses","group":"Characters","title":"Fell Twins","desc":"Field Boss encounter. A couple of bulky ogre-like beasts wielding flaming armaments. Drops the <a href='https://eldenring.wiki.fextralife.com/Omenkiller+Rollo' target=\"_blank\">Omenkiller Rollo</a> spirit ashes upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3670","x":0.465837042,"y":0.40687356,"cat":"Consumables","group":"Items","title":"Golden Rune [11]","desc":"Found at the end of an alleway, there is a Broken Statue at the end. There is also a <a href='https://eldenring.wiki.fextralife.com/Golden+Rune+(8)' target=\"_blank\">Golden Rune (8)</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3921","x":0.448656392,"y":0.40687356,"cat":"Consumables","group":"Items","title":"Poisonbone Dart - 8x Leyndell Royal Capital","desc":"On a small corridor, against the fence (Sewers)","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3551","x":0.272429989,"y":0.407056682,"cat":"Armor","group":"Equipment","title":"Bull-Goat Set","desc":"Armor Set. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Great+Horned+Tragoth'>Great Horned Tragoth</a> after successfully invading his world.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"1540","x":0.222147173,"y":0.407087204,"cat":"Bosses","group":"Characters","title":"Royal Knight Loretta","desc":"Great Enemy. The guardian of <a href='https://eldenring.wiki.fextralife.com/Caria+Manor' target=\"_blank\">Caria Manor</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Loretta's+Greatbow' target=\"_blank\">Loretta's Greatbow</a> and <a href='https://eldenring.wiki.fextralife.com/Ash+of+War:+Loretta's+Slash' target=\"_blank\">Ash of War: Loretta's Slash</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6390","x":0.43751601,"y":0.407117723,"cat":"NPC Invaders","group":"Characters","title":"Vargram the Raging Wolf","desc":"Found close to the Fortified Manor, First Floor Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"8200","x":0.289002924,"y":0.407117723,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Ruin-Strewn Precipice","desc":"Summoning Pool Effigy found next to the site of grace at the beginning of the Ruin-Strewn Precipice in Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4587","x":0.453965846,"y":0.407300844,"cat":"Talismans","group":"Equipment","title":"Haligdrake Talisman +1","desc":"Upgraded Talisman. Found on a corpse next to a Lesser Spirit-Caller Snail inside the <a href='https://eldenring.wiki.fextralife.com/Leyndell+Catacombs' target=\"_blank\">Leyndell Catacombs</a>. From the Lyndell Catacombs site of grace, head up the elevator in the southeast to find a room with 3 spirit crossbowmen. Look next to the stairs for an illusory wall. Hit it to dispel the illusion, and then hit the wall on the left to dispel another illusion. The corpse and snail are found in here.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1701","x":0.284457352,"y":0.407422925,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Liurnia Northern Ravine","desc":"Found just south of where <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Poison+Pod'>Poison Pods</a> are located. Found besides a glowing tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"3544","x":0.269168261,"y":0.407483965,"cat":"Consumables","group":"Items","title":"Rune Arc","desc":"Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Great+Horned+Tragoth'>Great Horned Tragoth</a> after successfully invading his world.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3922","x":0.447371747,"y":0.407575528,"cat":"Crafting Materials","group":"Items","title":"String - 4x Leyndell Royal Capital","desc":"On the sewers, at the big room with rats, can be found on a body against a wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1652","x":0.29242154,"y":0.407636569,"cat":"Locations","group":"Locations","title":"Ruin-Strewn Precipice","desc":"A large precipice over Ravine-Veiled Village with <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/miner'>Miners'</a> caves all the way to the top.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-precipice.png?h=40"},{"id":"3930","x":0.446395857,"y":0.407636569,"cat":"Consumables","group":"Items","title":"Golden Rune [11] B","desc":"Once you are up, after you jump from the dragon \"wing\" you will find it inside a room. Beware of the ambushing enemy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4112","x":0.439227097,"y":0.407636569,"cat":"Sites of Grace","group":"Locations","title":"Fortified Manor, First Floor","desc":"Site of grace inside the Fortified Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2903","x":0.450973843,"y":0.407850208,"cat":"Consumables","group":"Items","title":"Golden Rune [8]","desc":"Found on between the bushes to the right of a big staircase.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6616","x":0.45521942,"y":0.407911249,"cat":"Key Items","group":"Items","title":"Stonesword Key - Leyndell, Royal Capital (E)","desc":"On top of a gazebo, held by a corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1705","x":0.295266008,"y":0.40809437,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] - 9x Ruin-Strewn Precipice","desc":"There are at least 9 Smithing Stones (4) within the cave that goes through <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Ruin-Strewn+Precipice'>Ruin-Strewn Precipice</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4108","x":0.443712695,"y":0.408124893,"cat":"Armor","group":"Equipment","title":"Raging Wolf Set","desc":"After obtaining the second to last letter from Volcano Manor, You will be sent to assist Bernahl with an invade in a familiar location. Upon invasion completion, you will receive the full Raging Wolf set, including: <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/raging+wolf+greaves'>Raging Wolf Greaves</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/raging+wolf+gauntlets'>Raging Wolf Gauntlets</a>, <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/raging+wolf+armor'>Raging Wolf Armor</a> and <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Raging+Wolf+Helm'>Raging Wolf Helm</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"2066","x":0.299231186,"y":0.408155411,"cat":"Consumables","group":"Items","title":"Dragon Heart (Magma Wyrm Makar)","desc":"Key Consumable. Dropped by <a href='https://eldenring.wiki.fextralife.com/Magma+Wyrm+Makar' target=\"_blank\"> Magma Wyrm Makar</a> upon defeat. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3546","x":0.270145503,"y":0.408613217,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy","desc":"Multiplayer Item. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Great+Horned+Tragoth'>Great Horned Tragoth</a> after successfully invading his world.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"3950","x":0.438678204,"y":0.408613217,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy - 1x Leyndell Royal Capital","desc":"Found on a body in the room with the fire.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"5797","x":0.37447672,"y":0.408826857,"cat":"Bosses","group":"Characters","title":"Fallingstar Beast","desc":"Optional boss. Found directly south of the large bridge. The map will display a large crater there, which is where it will spawn.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"8839","x":0.201549246,"y":0.408918419,"cat":"Locations","group":"Locations","title":"Seluvis' Secret Room","desc":"A hidden area hidden behind a few Illusionary walls. An unresponsive Soceress Sellen may be seen here.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cityruins.png?h=40"},{"id":"5942","x":0.456460168,"y":0.409071019,"cat":"Spells","group":"Equipment","title":"Barrier of Gold","desc":"<p>Can be found after heading down the stairs and taking the elevator, right after the fight with <a class=\"wiki_link\" href='https://eldenring.wiki.fextralife.com/Godfrey,+First+Elden+Lord+(Golden+Shade)' target=\"blank\">Godfrey, First Elden Lord (Golden Shade)</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"1544","x":0.221749916,"y":0.409101541,"cat":"Sites of Grace","group":"Locations","title":"Royal Moongazing Grounds","desc":"Site of Grace found after defeating <a href='https://eldenring.wiki.fextralife.com/Royal+Knight+Loretta' target=\"_blank\">Royal Knight Loretta</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3934","x":0.448748011,"y":0.4091931,"cat":"Weapons","group":"Equipment","title":"Cane Sword","desc":"West Capital Ramparts Site of Grace, Go south out of the room with the site of grace and down the flight of stairs to the floor underneath, make a complete U-turn in the room with the stairs to find a corpse with the sword","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"6351","x":0.441851581,"y":0.409223622,"cat":"Armor","group":"Equipment","title":"Alberich's Set","desc":"Alberich's Set can be found within Leyndell, Royal Capital near the Fortified Manor, first floor Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"8823","x":0.224008889,"y":0.409376221,"cat":"Spells","group":"Equipment","title":"Loretta's Greatbow","desc":"<a href='https://eldenring.wiki.fextralife.com/Sorceries' target=\"_blank\">Sorcery</a>. Dropped by <a href='https://eldenring.wiki.fextralife.com/Royal+Knight+Loretta' target=\"_blank\">Royal Knight Loretta</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"1135","x":0.428700172,"y":0.409467784,"cat":"Sites of Grace","group":"Locations","title":"Divine Bridge","desc":"Site of Grace found on the Leyndell Divine Bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6382","x":0.453569455,"y":0.409467784,"cat":"Weapons","group":"Equipment","title":"Bolt of Gransax","desc":"Can be found in <a href='https://eldenring.wiki.fextralife.com/Leyndell,+Royal+Capital' target=\"_blank\">Leyndell, Royal Capital</a> after beating Godfrey, First Elden Lord; walk outside of the west door, take the elevator down, and walk up the spear.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spear.png?h=40"},{"id":"6853","x":0.278720125,"y":0.409467784,"cat":"Ashes of War","group":"Equipment","title":"Lost Ashes of War - Ruin-Strewn Precipice","desc":"Behind two <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Chanting+Winged+Dame'>Chanting Winged Dames</a> within the higher levels of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Ruin-Strewn+Precipice'>Ruin-Strewn Precipice</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"3933","x":0.449385055,"y":0.409498302,"cat":"Sites of Grace","group":"Locations","title":"West Capital Rampart","desc":"Site of grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2863","x":0.414782686,"y":0.409528824,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - 5x Sealed Tunnel","desc":"Upgrade Material. A total of <strong>5</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel' target=\"_blank\">Sealed Tunnel</a>: <ol> <li>In the hidden chamber past the Site of Grace, drop off the ledge into the lower section and check the alcove in the back for the first stone.</li> <li>In the same chamber, head west to find a chest (<a href='https://eldenring.wiki.fextralife.com/Smithing-Stone+Miner's+Bell+Bearing+(2)' target=\"_blank\">Smithing-Stone Miner's Bell Bearing (2)</a>). Dispel the <em>illusory wall</em> behind the chest to reveal a lift but ride it. Instead, drop down the ledges on the left to find the second stone.</li> <li>At the bottom of the lift chamber, look to the south and dispel two <em>illusory walls</em> to reveal a large cavern with overgrown roots. Navigate the roots to reach the tunnel in the east and drop down an opening on the right to find the third stone in the back. Beware of the exploding <a href='https://eldenring.wiki.fextralife.com/Abnormal+Stone+Cluster' target=\"_blank\">Abnormal Stone Clusters</a>.</li> <li>In the same chamber with the exploders, look for a set of wooden stairs. The fourth stone can be found on a wall next to these stairs.</li> <li>Still in the same chamber, check the wall opposite the stairs. Beware the exploder hidden behind crates and barrels. Hit the wall to reveal a deep pit with roots strewn across. Drop down to the second root and check the ledge in the corner for the final stone.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"7956","x":0.413281725,"y":0.409589865,"cat":"Consumables","group":"Items","title":"Large Glintstone Scrap - 3x Sealed Tunnel","desc":"Offensive Consumable. A set of <strong>3</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel' target=\"_blank\">Sealed Tunnel</a>. In the chamber with the exploding <a href='https://eldenring.wiki.fextralife.com/Abnormal+Stone+Cluster' target=\"_blank\">Abnormal Stone Clusters</a>, check the northeast for a corpse behind a wheelbarrow.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4569","x":0.288848253,"y":0.409620383,"cat":"Sites of Grace","group":"Locations","title":"Ruin-Strewn Precipice","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1137","x":0.422749476,"y":0.409803505,"cat":"Talismans","group":"Equipment","title":"Blessed Dew Talisman","desc":"Talisman. Found in a chest west of the Divine Bridge Site of Grace. Guarded by a Golem.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"5761","x":0.301079587,"y":0.409803505,"cat":"Sites of Grace","group":"Locations","title":"Altus Plateau (Site of Grace)","desc":"Site of grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2912","x":0.410987056,"y":0.409895067,"cat":"Consumables","group":"Items","title":"Gold-Pickled Fowl Foot - Sealed Tunnel","desc":"Consumable. Found inside the <a href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel' target=\"_blank\">Sealed Tunnel</a>. At the bottom of the chamber with the lift, dispel two <em>illusory walls</em> to the south and walk on the overgrown root in the next chamber. Drop down onto another root below and loot the corpse hanging off of it for the item.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1703","x":0.284578651,"y":0.410139229,"cat":"Crafting Materials","group":"Items","title":"Crystal Bud","desc":"Within Ravine-Veiled Village, near Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2914","x":0.202616876,"y":0.410291829,"cat":"NPCs","group":"Characters","title":"Sorceress Sellen (Third Location)","desc":"Found standing behind two illusory walls in a room. But she doesn't respond.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3222","x":0.4644909,"y":0.41041391,"cat":"Sites of Grace","group":"Locations","title":"Queen's Bedchamber","desc":"Site of grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3949","x":0.440872579,"y":0.41041391,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone (5) - 2x Leyndell Royal Capital","desc":"At the balcony of the fortified Manor, next to the room with the swords on the table. The second can be found inside the fortified Manor, once in the lower level at the back of the armory room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6657","x":0.451460899,"y":0.410566513,"cat":"Key Items","group":"Items","title":"Stonesword Key - Leyndell, Royal Capital (B)","desc":"Found on a corpse below <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'>West Capital Rampart Site of Grace</a>. Drop down, jump on petrified dragon foot onto barn, then into 2nd story wooden building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"5769","x":0.32368114,"y":0.410658072,"cat":"Key Items","group":"Items","title":"Stonesword Key - Altus Plateau (A)","desc":"Found on a corpse located on a camp northeast from the Grand Lift of Dectus.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"7951","x":0.416186604,"y":0.410658072,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] - 3x Sealed Tunnel","desc":"Upgrade Material. A total of <strong>3</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel' target=\"_blank\">Sealed Tunnel</a>: <ul> <li>At the bottom of the lift found halfway through the dungeon, dispel two <em>illusory walls</em> to the south to reveal a large cavern with an <a href='https://eldenring.wiki.fextralife.com/Iron+Virgin' target=\"_blank\">Iron Virgin</a> roaming the very bottom level. Lure it to the east end where a statue with a glowing crack can be found. Its attacks can destroy the statue, revealing a set of 3 of the stones.</li> <ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8222","x":0.45057791,"y":0.410719112,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: West Capital Rampart","desc":"Summoning Pool Effigy found as you exit to the southeast of the the West Capital Rampart site of grace in Leyndell, Royal Capital. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2707","x":0.518839117,"y":0.410780153,"cat":"Spirit Ashes","group":"Equipment","title":"Omenkiller Rollo","desc":"Spirit Ashes. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Fell+Twins'>Fell Twins</a> bosses.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"7952","x":0.40925387,"y":0.410835091,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - Sealed Tunnel","desc":"Rune Consumable. Found inside the <a href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel' target=\"_blank\">Sealed Tunnel</a>, on a corpse at the bottom of the chamber with the <a href='https://eldenring.wiki.fextralife.com/Iron+Virgin' target=\"_blank\">Iron Virgin</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2915","x":0.452682958,"y":0.410841193,"cat":"Consumables","group":"Items","title":"Hero's Rune [2]","desc":"On a body against a wall, beware of the soldier and the lion guarding it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8822","x":0.221262278,"y":0.410902234,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Loretta's Slash","desc":"Ash of War. Dropped by <a href='https://eldenring.wiki.fextralife.com/Royal+Knight+Loretta' target=\"_blank\">Royal Knight Loretta</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"3946","x":0.438762539,"y":0.411054837,"cat":"Consumables","group":"Items","title":"Rune Arc N","desc":"Found inside the Fortified Manor, in the room with the big table in the middle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1651","x":0.286376143,"y":0.411085355,"cat":"Sites of Grace","group":"Locations","title":"Ravine-Veiled Village","desc":"Ravine-Veiled Village Site of Grace, right below the entrance to the Miners' cave that lead to <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Ruin-Strewn+Precipice'>Ruin-Strewn Precipice</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8214","x":0.413470333,"y":0.411298999,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Sealed Tunnel","desc":"Summoning Pool Effigy found next to the Sealed Tunnel site of grace in the Altus Plateau. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4137","x":0.46589331,"y":0.411596877,"cat":"Spells","group":"Equipment","title":"Blessing of the Erdtree","desc":"Found lying on a giant furniture, located in the middle of the room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"1709","x":0.275882586,"y":0.411909404,"cat":"Sites of Grace","group":"Locations","title":"Ruin-Strewn Precipice Overlook","desc":"Site of Grace located on top of Ruin-Strewn Precipice, right before <a target=\"\" href='https://eldenring.wiki.fextralife.com/Magma+Wyrm+Makar'>Magma Wyrm Makar Bossfight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3156","x":0.41719376,"y":0.411939922,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5] - Sealed Tunnel","desc":"Upgrade Material. <strong>One</strong> can be found inside the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel'>Sealed Tunnel</a>: <ul> <li>At the bottom of the chamber with the lift, dispel two illusory walls to the south to reveal a large cavern with overgrown roots and an <a href='https://eldenring.wiki.fextralife.com/Iron+Virgin' target=\"_blank\">Iron Virgin</a> roaming the lower section. Make your way to the lower section of this cavern and check the northwest wall to find the stone.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4111","x":0.444079046,"y":0.411939922,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] - 7x Leyndell, Royal Capital","desc":"There are 7 Smithing Stone (6) to be found: - Can be found on the stairs leading to the lower floor inside Fortified Manor. - Found on a body, at the little patio. - Found on the upper platform. After climbing the ladder, open the door in front of you. Climb the next set of stairs, head to one of the corners of the stairs you just climbed up to find it. - Found near the Omensmirk, on the ground. - Found on the big area, past the <a href='https://eldenring.wiki.fextralife.com/Lesser+Ulcerated+Tree+Spirit' target=\"_blank\">Lesser Ulcerated Tree Spirit</a> - Found on a small building past the Fortified Manor, you have to jump around to get there. - Found to the south of the West Capital Rampart site of grace, on an edge, near some poison flowers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1207","x":0.424824367,"y":0.411970445,"cat":"Bosses","group":"Characters","title":"Giant Golem","desc":"Dormant Golem guarding the divine bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3938","x":0.450090509,"y":0.412000963,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - 2x Leyndell Royal Capital","desc":"The first one is found by the by defeating the <a href='https://eldenring.wiki.fextralife.com/Lesser+Ulcerated+Tree+Spirit' target=\"_blank\">Lesser Ulcerated Tree Spirit</a> NW of the Avenue Balcony Site of grace. The second one is found on a balcony to the SW of West Capital Rampart site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"7023","x":0.391012307,"y":0.412031485,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Capital Outskirts (Ulcerated Tree Spirit Drop)","desc":"Flask Upgrade Material. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Lesser+Ulcerated+Tree+Spirit' target=\"_blank\">Lesser Ulcerated Tree Spirit</a> enemy in an unmarked military camp directly south of the <strong>Outer Wall Phantom Tree</strong> site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"3954","x":0.441257009,"y":0.412153566,"cat":"Key Items","group":"Items","title":"Two Fingers' Prayerbook","desc":"Located in the first floor of Fortified Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tome.png?h=40"},{"id":"7027","x":0.228198765,"y":0.412153566,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Caria Manor Staircase","desc":"Consumable Item. Held by a corpse within the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Caria+Manor'>Caria Manor</a> grounds. It is situated near a Stake of Marika.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3936","x":0.448616553,"y":0.412184084,"cat":"Weapons","group":"Equipment","title":"Gargoyle's Halberd","desc":"Dropped by the Lesser Black Blade Kindred.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-halberd.png?h=40"},{"id":"8199","x":0.274354682,"y":0.412214607,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Ruin-Strewn Precipice Overlook","desc":"Summoning Pool Effigy found at the top of the Ruin-Strewn Precipice in Liurnia of the Lakes, just before the Magma Wyrm Makar boss fight. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1870","x":0.240334,"y":0.412367206,"cat":"Sites of Grace","group":"Locations","title":"Behind Caria Manor","desc":"Site of Grace in the plateau behind <a href='https://eldenring.wiki.fextralife.com/Caria+Manor' target=\"_blank\">Caria Manor</a>. Accessible only after defeating <a href='https://eldenring.wiki.fextralife.com/Royal+Knight+Loretta' target=\"_blank\">Royal Knight Loretta</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2861","x":0.407904544,"y":0.412367206,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - 2x Sealed Tunnel","desc":"Rune Consumable. A total of <strong>2</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel' target=\"_blank\">Sealed Tunnel</a>: <ol> <li>From the Site of Grace, look at the west wall for a section that looks slightly off. Attack or roll towards it to dispel the <em>illusory wall</em> revealing a hidden path. In the next chamber, look for a set of wooden stairs leading to a platform where a corpse with the first rune can be found.</li> <li>At the bottom of the chamber with the lift, dispel an <em>illusory wall</em> in the south to find a corpse with the second rune.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1704","x":0.285585991,"y":0.412397728,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - Ravine-Veiled Village","desc":"Within Ravine-Veiled Village, near Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3678","x":0.434616661,"y":0.412397728,"cat":"Weapons","group":"Equipment","title":"Coded Sword","desc":"Found in Leyndell, Royal Capital. Look for an abandoned horse stable, then climb onto its roof and enter the building. Keep going until you find a broken round table. Look for the double door. Inside that room you will find the coded sword.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"3942","x":0.442522794,"y":0.412489287,"cat":"Key Items","group":"Items","title":"Sanctified Whetblade","desc":"Found inside the fortified manor, you have to access by jumping through the roof and entering the building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8821","x":0.226235303,"y":0.412550327,"cat":"Crafting Materials","group":"Items","title":"Rimed Crystal Bud - 5x Caria Manor Upper","desc":"Crafting Material. Five can be looted off a corpse on the final staircase leading to the boss of Caria Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"14202","x":0.448655341,"y":0.412886052,"cat":"Bosses","group":"Characters","title":"Valiant Gargoyle - Leyndell, Royal Capital","desc":"<p> Optional Boss. Located around <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Leyndell,+Royal+Capital' target=\"blank\">Leyndell, Royal Capital</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"8401","x":0.194165085,"y":0.412947093,"cat":"Armor","group":"Equipment","title":"Blaidd's Set (No helmet)","desc":"Return to <a href='https://eldenring.wiki.fextralife.com/Ranni's+Rise'>Ranni's Rise</a> after giving <a href='https://eldenring.wiki.fextralife.com/Ranni'>Ranni</a> the <a href='https://eldenring.wiki.fextralife.com/Dark+Moon+Ring'>Dark Moon Ring</a>, to find <a href='https://eldenring.wiki.fextralife.com/Blaidd'>Blaidd</a> who will become hostile. The set is dropped by defeating him, except for the helmet.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"2860","x":0.414613142,"y":0.413038651,"cat":"Sites of Grace","group":"Locations","title":"Sealed Tunnel","desc":"Site of Grace found shortly after entering the tunne.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3945","x":0.440196976,"y":0.413130214,"cat":"Consumables","group":"Items","title":"Hero's Rune [1]","desc":"Found inside Fortified Manor, at the second room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1707","x":0.294314635,"y":0.413343854,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - Ruin-Strewn Precipice","desc":"Can be found within the caves that run through the Ruin-Strewn Precipice.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6380","x":0.392322802,"y":0.413435417,"cat":"Weapons","group":"Equipment","title":"Giant-Crusher","desc":"Colossal Weapon. Can be found in a chest inside an unmarked military camp directly to the south of <strong>Outer Wall Phantom Tree</strong> site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossal_weapon.png?h=40"},{"id":"2858","x":0.413075071,"y":0.413526976,"cat":"Locations","group":"Locations","title":"Sealed Tunnel","desc":"A massive tunnel system found along the southern end of the lake near the western gate of the <a href='https://eldenring.wiki.fextralife.com/Capital+Outskirts' target=\"_blank\">Capital Outskirts</a>. A series of <em>Illusory Walls</em> conceal the path to the <a href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+West+Altus' target=\"_blank\">Divine Tower</a> far to the south.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tunnel.png?h=40"},{"id":"5850","x":0.191997711,"y":0.413526976,"cat":"Sites of Grace","group":"Locations","title":"Ranni's Chamber","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8820","x":0.234841347,"y":0.41380166,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] - Caria Manor Upper Level","desc":"Upgrade Material. One can be looted from a corpse on the higher platform near the archway leading to the large staircase. Accessible by dropping down from the higher area after defeating the Troll Knight.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"7953","x":0.407568827,"y":0.413923741,"cat":"Consumables","group":"Items","title":"Golden Rune [9] - Sealed Tunnel","desc":"Rune Consumable. Found inside the <a href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel' target=\"_blank\">Sealed Tunnel</a>, on a corpse at the bottom of the deep pit with roots strewn across, near the end of the dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8826","x":0.195568272,"y":0.413954259,"cat":"NPCs","group":"Characters","title":"Ranni the Witch","desc":"You can talk to Ranni at the very top of Ranni's Rise in the Three Sisters, northwestern Liurnia of the Lakes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3943","x":0.441545142,"y":0.414045822,"cat":"Weapons","group":"Equipment","title":"Hammer","desc":"Found inside the Fortified manor, beside the <a href='https://eldenring.wiki.fextralife.com/Sanctified+Whetblade' target=\"_blank\">Sanctified Whetblade</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-hammer.png?h=40"},{"id":"1878","x":0.256900518,"y":0.414106862,"cat":"Spells","group":"Equipment","title":"Meteorite","desc":"<a href='https://eldenring.wiki.fextralife.com/Sorceries' target=\"_blank\">Sorcery</a>. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Alabaster+Lord' target=\"_blank\">Alabaster Lord</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"2905","x":0.417492099,"y":0.414167903,"cat":"Key Items","group":"Items","title":"Stonesword Key - Sealed Tunnel","desc":"Stonesword Key. <strong>One</strong> found in the <a href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel' target=\"_blank\">Sealed Tunnel</a>. At the bottom of the chamber with the lift, dispel two <em>illusory walls</em> to the south. In the next chamber, walk on the overgrown root and jump to the right onto the wooden platform below, right in front of a tunnel. Follow the tunnel to find the key on a corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2908","x":0.231272181,"y":0.414167903,"cat":"Weapons","group":"Equipment","title":"Troll Knight's Sword","desc":"Colossal Sword. Dropped by a Troll Knight guarding the staircase leading up to the boss of Caria Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossalsword.png?h=40"},{"id":"9827","x":0.425339432,"y":0.414167903,"cat":"Waygates","group":"Locations","title":"Divine Bridge Site of Grace Waygate","desc":"Waygate. At the Divine Bridge Site of Grace. Teleports you you to <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Isolated+Divine+Tower' target=\"blank\">Isolated Divine Tower.</a> You can reach this area via the transporter trap chest atop the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Tower+of+Return' target=\"blank\">Tower of Return</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"8224","x":0.467261595,"y":0.4143144,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Queen's Bedchamber","desc":"Summoning Pool Effigy found outside of the Queen's Bedchamber site of grace in Leyndell, Royal Capital, on the path to the Morgott, the Omen King encounter. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1817","x":0.192241599,"y":0.414747786,"cat":"NPCs","group":"Characters","title":"Blaidd (Spectral)","desc":"Quest NPC. Appears in spectral form on the first floor after speaking to <a href='https://eldenring.wiki.fextralife.com/Ranni' target=\"_blank\">Ranni</a> for the first time.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"4123","x":0.458844858,"y":0.415190942,"cat":"Consumables","group":"Items","title":"Holy Grease C","desc":"Down the stairs after facing <a href='https://eldenring.wiki.fextralife.com/Godfrey,+First+Elden+Lord' target=\"_blank\">Godfrey, First Elden Lord</a>, you will find it","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2114","x":0.196696591,"y":0.41529715,"cat":"Key Items","group":"Items","title":"Carian Inverted Statue","desc":"Quest Item. Given by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Ranni+the+Witch'>Ranni</a> after giving her the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Fingerslayer+Blade'>Fingerslayer Blade</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3155","x":0.408667543,"y":0.415571834,"cat":"Consumables","group":"Items","title":"Rune Arc - Sealed Tunnel","desc":"Consumable. Found on a corpse in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel'>Sealed Tunnel</a>, at the bottom section of the chamber with the <a href='https://eldenring.wiki.fextralife.com/Iron+Virgin' target=\"_blank\">Iron Virgin</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1531","x":0.232044276,"y":0.415815996,"cat":"Consumables","group":"Items","title":"Magic Grease - 2x Caria Manor","desc":"Consumable. Two found on a corpse on a lower ledge reachable by jumping to the building on the left of the door as you enter and going up the ladder to the higher platform.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1534","x":0.220372976,"y":0.415815996,"cat":"Consumables","group":"Items","title":"Crystal Dart - 8x Caria Manor Upper Cliffs","desc":"Offensive Consumable. Found on a gravestone in the western portion of the upper manor. This area is only accessible by dropping down from a ledge near the entrance to the boss room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2862","x":0.416912447,"y":0.415907555,"cat":"Key Items","group":"Items","title":"Smithing-Stone Miner's Bell Bearing [2]","desc":"Bell Bearing. Found in a chest in the first hidden chamber of the <a href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel' target=\"_blank\">Sealed Tunnel</a>. Drop down into the lower section and look to the west to find the chest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1866","x":0.206889712,"y":0.415968596,"cat":"Bosses","group":"Characters","title":"Glintstone Dragon Adula (Three Sisters)","desc":"Great Enemy. Found roaming the sub-region of <a href='https://eldenring.wiki.fextralife.com/Three+Sisters' target=\"_blank\">Three Sisters</a>. The dragon cannot be killed here and will teleport to the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Manus+Celes' target=\"_blank\">Cathedral of Manus Celes</a> in the very south of the region after being brought to about 50% HP.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"1802","x":0.195446277,"y":0.415999118,"cat":"Locations","group":"Locations","title":"Ranni's Rise","desc":"One of three towers found in the <a href='https://eldenring.wiki.fextralife.com/Three+Sisters' target=\"_blank\">Three Sisters</a> sub-region. Three Sisters is accessible after completing <a href='https://eldenring.wiki.fextralife.com/Caria+Manor' target=\"_blank\">Caria Manor</a> and defeating <a href='https://eldenring.wiki.fextralife.com/Royal+Knight+Loretta' target=\"_blank\">Royal Knight Loretta</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"1876","x":0.255179639,"y":0.416121199,"cat":"Bosses","group":"Characters","title":"Alabaster Lord","desc":"Optional Boss imprisoned within the <a href='https://eldenring.wiki.fextralife.com/Royal+Grave+Evergaol' target=\"_blank\">Royal Grave Evergaol</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"1532","x":0.224525176,"y":0.416151717,"cat":"Key Items","group":"Items","title":"Cracked Pot - Caria Manor","desc":"Crafting Pot. Found on the cliffs overlooking the gardens below.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"1815","x":0.190196766,"y":0.416273798,"cat":"NPCs","group":"Characters","title":"Smithing Master Iji (Spectral)","desc":"Quest NPC. Appears in spectral form by the lift on the first floor after speaking to <a href='https://eldenring.wiki.fextralife.com/Ranni' target=\"_blank\">Ranni</a> for the first time.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"4124","x":0.45346922,"y":0.41630432,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5] - 3x Leyndell, Royal Capital","desc":"On a side room, you can find this on a body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"1875","x":0.258733975,"y":0.416395879,"cat":"Locations","group":"Locations","title":"Royal Grave Evergaol","desc":"Evergaol found east of Caria Manor. The <a href='https://eldenring.wiki.fextralife.com/Alabaster+Lord' target=\"_blank\">Alabaster Lord</a> is imprisoned within.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-evergaol.png?h=40"},{"id":"2843","x":0.418874097,"y":0.416548483,"cat":"Crafting Materials","group":"Items","title":"Smoldering Butterfly (B)","desc":"Found at the base of a Stonegrave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8819","x":0.237496027,"y":0.416609523,"cat":"Crafting Materials","group":"Items","title":"Rimed Crystal Bud - 3x Caria Manor Upper Gardens","desc":"Crafting Material. Three can be looted from a corpse on the gardens in upper Caria Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3159","x":0.415304688,"y":0.416762122,"cat":"Weapons","group":"Equipment","title":"Onyx Lord's Greatsword","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Curved+Greatsords'>Curved Greatsword</a>. Dropped by the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Onyx+Lord'>Onyx Lord</a> when defeated.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedgreatsword.png?h=40"},{"id":"6353","x":0.45613718,"y":0.416792645,"cat":"Key Items","group":"Items","title":"Golden Order Principia","desc":"Incantation Tome. From the Erdtree Sanctuary site in Leyndell, Royal Capital, exit the east side of the room. Once outside, climb up the root to the left that circles back into the building's 2nd floor. Once inside, exit the only door and immediately turn left to jump down to a nearby roof. Once on the roof, a broken window can be used to get back inside. After entering the broken window, climb the root crossing the room to reach the Golden Order Principia, which is located in the chair hanging from the ceiling.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tome.png?h=40"},{"id":"7151","x":0.248694864,"y":0.416853685,"cat":"Consumables","group":"Items","title":"Thawfrost Boluses - Liurnia of the Lakes","desc":"Can be found on a corpse ast the top of the massive rock","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7954","x":0.410132501,"y":0.416884203,"cat":"Consumables","group":"Items","title":"Lightning Grease - 4x Sealed Tunnel","desc":"Weapon Coating. A set of <strong>4</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel' target=\"_blank\">Sealed Tunnel</a>. In the chamber with the exploding <a href=\"Abnormal+Stone+Cluster\" target=\"_blank\">Abnormal Stone Clusters</a> near the end of the dungeon, dispel the wall opposite the wooden stairs to reveal a deep pit with roots strewn jutting across the walls. Drop down onto the second root and check the corpse on a ledge along the north wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3234","x":0.472851951,"y":0.417128365,"cat":"Key Items","group":"Items","title":"Morgott's Great Rune","desc":"Drops from <a href='https://eldenring.wiki.fextralife.com/Morgot,+The+Omen+King' target=\"_blank\">Morgot, The Omen King</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6857","x":0.469952583,"y":0.417158888,"cat":"Key Items","group":"Items","title":"Rold Medallion","desc":"Given by <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/melina'>Melina</a> at the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'>Site of Grace</a> once you defeat <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/morgott,+the+omen+king'>Morgott, The Omen King</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1807","x":0.192119713,"y":0.417433568,"cat":"Sites of Grace","group":"Locations","title":"Ranni's Rise","desc":"Site of Grace found in Ranni's Rise. Up on the first floor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"11952","x":0.245560193,"y":0.417480662,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [2] - 3x Caria Manor Outkirts","desc":"Spirit Ash Upgrade Material. 3 Can be found spread throughout the graveyard area close to the 'Behind Caria Manor' Site of Grace. They can be looted behind the gravestones.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"6367","x":0.196907966,"y":0.41767773,"cat":"Weapons","group":"Equipment","title":"Royal Greatsword","desc":"Obtainable at the end of Ranni's questline; <a href='https://eldenring.wiki.fextralife.com/Blaidd' target=\"_blank\">Blaidd</a> will spawn in front of <a href='https://eldenring.wiki.fextralife.com/Ranni's+Rise' target=\"_blank\">Ranni's Rise</a> tower. Best him in combat for a final time to obtain this weapon along with his armor set.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossalsword.png?h=40"},{"id":"7955","x":0.412153199,"y":0.417860851,"cat":"Consumables","group":"Items","title":"Grace Mimic - 5x Sealed Tunnel","desc":"Consumable. A set of <strong>5</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel' target=\"_blank\">Sealed Tunnel</a>. In the large cavern with the <a href='https://eldenring.wiki.fextralife.com/Iron+Virgin'>Iron Virgin</a> roaming the bottom, navigate the roots at the top to reach a tunnel in the east. Drop down the opening on the right and proceed east to find a corpse on the ground with the items.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3157","x":0.413835368,"y":0.418031765,"cat":"Bosses","group":"Characters","title":"Onyx Lord","desc":"Enemy. Found in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Sealed+Tunnel'>Sealed Tunnel</a> blocking the path to the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+West+Altus'>Divine Tower of West Altus</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"8006","x":0.452623871,"y":0.418318657,"cat":"Weapons","group":"Equipment","title":"Erdtree Bow","desc":"Climb the root found at the east, head up to the west, once outside again, jump on the roof to the left and enter inside the window. Loot the chest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bow.png?h=40"},{"id":"1536","x":0.228700898,"y":0.418361388,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] - Caria Manor","desc":"Upgrade Material. Found in the cliff graveyard behind the Living Jars.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3239","x":0.471418924,"y":0.418440738,"cat":"Sites of Grace","group":"Locations","title":"Elden Throne","desc":"Site of grace that appearts on the battlefield where you face <a href='https://eldenring.wiki.fextralife.com/Morgott,+the+Omen+King' target=\"_blank\"> Morgott, the Omen King</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4122","x":0.459495486,"y":0.418471257,"cat":"Key Items","group":"Items","title":"Talisman Pouch (Godfrey)","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Godfrey,+First+Elden+Lord+(Golden+Shade)' target=\"_blank\">Godfrey, First Elden Lord (Golden Shade)</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4121","x":0.456587752,"y":0.418501779,"cat":"Sites of Grace","group":"Locations","title":"Erdtree Sanctuary","desc":"Site of grace inside the Erdtree Sanctuary.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1537","x":0.222208393,"y":0.418532297,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Carian Grandeur","desc":"Ash of War. Found on a corpse on the roof of a tall stone structure. This is accessible by jumping down the cliffside graveyard from the manor's upper level.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"5912","x":0.436569269,"y":0.4186849,"cat":"Talismans","group":"Equipment","title":"Ritual Shield Talisman","desc":"From the West Capital Rampart site of grace in Leyndell, follow the marble stairway heading South-Southwest, past a Valiant Gargoyle near a Golden Seed and up the stair toward a giant Colloseum, the talisman is at the top of the hill, in front of the door of the Colloseum.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1818","x":0.194255915,"y":0.418745941,"cat":"NPCs","group":"Characters","title":"Seluvis (Spectral)","desc":"Quest NPC. Appears in spectral form by the entrance after speaking to <a href='https://eldenring.wiki.fextralife.com/Ranni' target=\"_blank\">Ranni</a> for the first time.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6667","x":0.455319347,"y":0.41889854,"cat":"Bosses","group":"Characters","title":"Godfrey, First Elden Lord (Golden Shade)","desc":"This is a spectral shade of Godfrey that is encountered in Leyndell, Royal Capital. Drops a Talisman Pouch.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"1518","x":0.225961169,"y":0.418990103,"cat":"Locations","group":"Locations","title":"Caria Manor","desc":"A major dungeon comprised of a very large estate, overlooking the lakes from the north. Its eternal warden, <a href='https://eldenring.wiki.fextralife.com/Royal+Knight+Loretta' target=\"_blank\">Royal Knight Loretta</a> fervently guards the manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cariamanor.png?h=40"},{"id":"6852","x":0.21485308,"y":0.419142702,"cat":"Key Items","group":"Items","title":"Pidia's Bell Bearing","desc":"Key Item. Dropped by <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/pidia,+carian+servant'>Pidia, Carian Servant in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/caria+manor'>Caria Manor</a> upon death.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1598","x":0.288913004,"y":0.419447905,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [3] F","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teadrop+Scarab' target=\"_blank\"> Teadrop Scarab</a> found within the woods.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"6265","x":0.305574559,"y":0.419692067,"cat":"NPCs","group":"Characters","title":"Rya (Second Location B)","desc":"Rya spawns at the top of the Grand Lift of Dectus if it is taken from the bottom, if the player completed the interaction with her in Liurnia of the Lakes. She will teleport you to the Volcano Manor if you talk to her.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3233","x":0.470349337,"y":0.419966751,"cat":"Remembrances","group":"Items","title":"Remembrance of the Omen King","desc":"Drops from <a href='https://eldenring.wiki.fextralife.com/Morgot,+The+Omen+King' target=\"_blank\">Morgot, The Omen King</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3232","x":0.473126628,"y":0.419997269,"cat":"Bosses","group":"Characters","title":"Morgott, The Omen King","desc":"Main Boss. Drops <a href='https://eldenring.wiki.fextralife.com/Remembrance+of+the+Omen+King' target=\"_blank\"> Remembrance of the Omen King</a> and <a href='https://eldenring.wiki.fextralife.com/Morgott's+Great+Rune' target=\"_blank\"> Morgott's Great Rune</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"1530","x":0.230966249,"y":0.420210913,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Caria Manor","desc":"Flask Upgrade material. Found under a Phantom Tree in the manor's upper level.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"2920","x":0.214548789,"y":0.420241431,"cat":"NPCs","group":"Characters","title":"Pidia, Carian Servant","desc":"Pidia is a Merchant. Can be found by falling down from the cliff at Three Sisters.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"6354","x":0.453565932,"y":0.420271953,"cat":"Key Items","group":"Items","title":"Celestial Dew - 1x (Leyndell Throne Room)","desc":"Key Item. Used to find absolution at the Church of Vows in Liurnia of the Lakes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"11951","x":0.247333129,"y":0.420319043,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [1] - 3x Caria Manor Outkirts","desc":"Spirit Ash Upgrade Material. 3 Can be found spread throughout the graveyard area close to the 'Behind Caria Manor' Site of Grace. They can be looted behind the gravestones.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"1525","x":0.215829552,"y":0.420394034,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] - Caria Manor","desc":"Upgrade Material. Found in the chapel with the Manor Lower Level site of grace, on a corpse hidden under the altar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"9838","x":0.453889147,"y":0.420425775,"cat":"Talismans","group":"Equipment","title":"Crucible Scale Talisman","desc":"<a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Leyndell+Catacombs' target=\"\">Leyndell Catacombs</a>, <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau' target=\"\">Altus Plateau</a>. Found in the mini-dungeon directly behind the fire pillar trap is a room with an Omen enemy guarding the item on an altar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4118","x":0.451367265,"y":0.420485593,"cat":"Consumables","group":"Items","title":"Holy Grease B","desc":"Take the giant tree branches located south of West Rampart Capital south of grace. There is one that gets neer a yellowish roof. Jump there and walk along until you find an enemy. Behind it you will find the item","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2361","x":0.302033745,"y":0.420790796,"cat":"Locations","group":"Locations","title":"Grand Lift of Dectus","desc":"A massive lift that connects the Altus Plateau to Liurnia. Requires collection of both <a href='https://eldenring.wiki.fextralife.com/Dectus+Medallion+(Left)' target=\"_blank\">Dectus Medallion (Left)</a> and <a href='https://eldenring.wiki.fextralife.com/Dectus+Medallion+(Right)' target=\"_blank\">Dectus Medallion (Right)</a> to activate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-guardians.png?h=40"},{"id":"8815","x":0.223306079,"y":0.420821318,"cat":"Crafting Materials","group":"Items","title":"Rimed Crystal Bud - 2x Caria Manor","desc":"Crafting Material. Two can be looted from a corpse in the frontal gardens before accessing the higher areas of Caria Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5734","x":0.407641025,"y":0.420943399,"cat":"Key Items","group":"Items","title":"Missionary's Cookbook [4]","desc":"Can be found on <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+Church'>Minor Erdtree Church</a>, Capital area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"8295","x":0.2336631,"y":0.421248602,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Caria Manor Upper Level","desc":"Summoning Pool Effigy found on the stairs outside of the room with the Caria Manor Upper Level site of grace in Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"8824","x":0.218148456,"y":0.421248602,"cat":"Crafting Materials","group":"Items","title":"Old Fang - 5x Caria Manor Rooftop","desc":"Crafting Material. Five can be looted from a corpse on the rooftops of the chapel of Caria Manor, above the Manor Lower Level site of grace. This area is only accessible by dropping down from the cliffs in the Three Sisters area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7101","x":0.215502482,"y":0.421401201,"cat":"Consumables","group":"Items","title":"Spellproof Dried Liver - Caria Manor","desc":"Consumable Item. Can be found on the balcony located near Pida. Only accessible after defeating <a href='https://eldenring.wiki.fextralife.com/Royal+Knight+Loretta' target=\"_blank\">Royal Knight Loretta</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1522","x":0.230753792,"y":0.422042128,"cat":"Shields","group":"Equipment","title":"Ice Crest Shield","desc":"Small Shield. Found on a corpse up on a ledge by a jagged stone pillar. This area is in the gardens, jumping up on the rocks from the Teardrop Scarab nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-smallshield.png?h=40"},{"id":"2852","x":0.411700838,"y":0.42222525,"cat":"Crafting Materials","group":"Items","title":"Golden Centipede - Minor Erdtree Church","desc":"Crafting Material. Many can be found at the base of the <strong>Minor Erdtree</strong>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1524","x":0.21750744,"y":0.42228629,"cat":"Sites of Grace","group":"Locations","title":"Manor Lower Level","desc":"Site of Grace found in a chapel building on the west side of the estate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6135","x":0.442950044,"y":0.422347331,"cat":"NPCs","group":"Characters","title":"Brother Corhyn (Third Location)","desc":"NPC, found contemplating a riddle alongside <a href='https://eldenring.wiki.fextralife.com/Goldmask' target=\"_blank\">Goldmask</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"1528","x":0.228037072,"y":0.422530452,"cat":"Weapons","group":"Equipment","title":"Sword of Night and Flame","desc":"Straight Sword. Found in a chest inside a locked room behind the gardens. This is accessible by using the walkways above. You can get onto the walkways from the Chapel building in the west.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"1529","x":0.234870934,"y":0.422622011,"cat":"Sites of Grace","group":"Locations","title":"Manor Upper Level","desc":"Site of Grace found in a room in the east. Accessible by using the garden walkways from the chapel building in the west and then taking a lift up a tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1855","x":0.296145858,"y":0.422774614,"cat":"Sites of Grace","group":"Locations","title":"Grand Lift of Dectus","desc":"Site of Grace found on the Liurnia side of the Grand Lift of Dectus.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8816","x":0.22269568,"y":0.422835655,"cat":"Crafting Materials","group":"Items","title":"Glintstone Firefly - 6x Caria Manor Gardens","desc":"Crafting Material. Six can be looted from a corpse in the garden. Beware of an ambush by many Giant Hands in this area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8805","x":0.243506463,"y":0.422866173,"cat":"Spirit Ashes","group":"Equipment","title":"Albinauric Ashes","desc":"<p>Found on a corpse in the graveyard area east of <a class=\"wiki_link\" title=\"Elden Ring Caria Manor\" href='https://eldenring.wiki.fextralife.com/Caria+Manor' target=\"\">Caria Manor</a>. This area is accessible only after completing the manor and defeating <a class=\"wiki_link\" title=\"Elden Ring Royal Knight Loretta\" href='https://eldenring.wiki.fextralife.com/Royal+Knight+Loretta' target=\"\">Royal Knight Loretta</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"1523","x":0.225787691,"y":0.422957736,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Caria Manor","desc":"Rune Consumable. Found on a corpse near the center of the garden.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1521","x":0.229927932,"y":0.423140857,"cat":"Spells","group":"Equipment","title":"Carian Piercer","desc":"<a href='https://eldenring.wiki.fextralife.com/Sorceries' target=\"_blank\">Sorcery</a>. Dropped by a <a hred=\"/Teardrop+Scarab\" target=\"_blank\">Teardrop Scarab</a> behind the gardens near the east.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"6134","x":0.444719613,"y":0.423385019,"cat":"NPCs","group":"Characters","title":"Goldmask (Second Location)","desc":"NPC found alongside <a href='https://eldenring.wiki.fextralife.com/Brother+Corhyn' target=\"_blank\">Brother Corhyn</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"1871","x":0.244823472,"y":0.423690222,"cat":"Armor","group":"Equipment","title":"Juvenile Scholar Cap","desc":"Light Helmet. Found by touching a ghost at the graveyard. This ghost also gives <a href='https://eldenring.wiki.fextralife.com/Juvenile+Scholar+Robe' target=\"_blank\">Juvenile Scholar Robe</a> and 1x <a href='https://eldenring.wiki.fextralife.com/Larval+Tear' target=\"_blank\">Larval Tear</a>. This is the location from the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Resurrection+Painting' target=\"blank\">Resurrection Painting</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"2849","x":0.408651888,"y":0.424148024,"cat":"Locations","group":"Locations","title":"Minor Erdtree Church","desc":"Found outside the west gate to Leyndell Capital City surrounding a Minor Erdtree..","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"1872","x":0.247671741,"y":0.424270105,"cat":"Armor","group":"Equipment","title":"Juvenile Scholar Robe","desc":"<p>Light Chest Armor. Found by touching a ghost at the graveyard. This ghost also gives <a href='https://eldenring.wiki.fextralife.com/Juvenile+Scholar+Cap' target=\"_blank\" rel=\"noopener noreferrer\">Juvenile Scholar Cap</a> and 1x <a href='https://eldenring.wiki.fextralife.com/Larval+Tear' target=\"_blank\" rel=\"noopener noreferrer\">Larval Tear</a>. This is the location from the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Resurrection+Painting' target=\"blank\">Resurrection Painting</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"14151","x":0.432712091,"y":0.424483748,"cat":"Locations","group":"Locations","title":"Leyndell Colosseum","desc":"The Colosseum in Leyndell can be seen immediately when you enter the city from East Capital Rampart, in Leyndell, Royal Capital.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-location_41.png?h=40"},{"id":"2851","x":0.405967098,"y":0.424544789,"cat":"Sites of Grace","group":"Locations","title":"Minor Erdtree Church","desc":"The Site of Grace is right in front of the Erdtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2128","x":0.207349689,"y":0.424636348,"cat":"Spirit Ashes","group":"Equipment","title":"Finger Maiden Therolina Puppet","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Spirit+Ashes'>Spirit Ashes</a>. Can be bought from a body in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Seluvis's+Rise'>Seluvis's Rise</a> for <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Starlight+Shards'>Starlight Shards</a> after reaching the end of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Ranni+the+Witch'>Ranni's</a> questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"1526","x":0.228534486,"y":0.424819469,"cat":"Consumables","group":"Items","title":"Rune Arc - Caria Manor","desc":"Consumable Item. Found on a corpse on the upper walkways of the garden. This is accessible from the chapel in the west.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"11953","x":0.247058123,"y":0.424850648,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf - Caria Manor Graveyard","desc":"Material. Can be gathered near one of the gravestones, in the graveyard behind <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Caria+Manor' target=\"\">Caria Manor</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1854","x":0.204966449,"y":0.425094153,"cat":"Key Items","group":"Items","title":"Memory Stone - Seluvis's Rise","desc":"Memory Slot Upgrade Material. Found on the top floor of <a href='https://eldenring.wiki.fextralife.com/Seluvis's+Rise'>Seluvis's Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"2850","x":0.41130658,"y":0.425368834,"cat":"Weapons","group":"Equipment","title":"Golden Order Seal","desc":"Found right at the base of the Minor Erdtree surrounded by the remains of the Church.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacredseal.png?h=40"},{"id":"2129","x":0.208934544,"y":0.425521437,"cat":"Spirit Ashes","group":"Equipment","title":"Jarwight Puppet","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Spirit+Ashes'>Spirit Ashes</a>. Can be bought from a body in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Seluvis's+Rise'>Seluvis's Rise</a> for <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Starlight+Shards'>Starlight Shards</a> after reaching the end of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Ranni+the+Witch'>Ranni's</a> questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"1873","x":0.246344443,"y":0.425551955,"cat":"Key Items","group":"Items","title":"Larval Tear (B)","desc":"Key Item. Found by touching a ghost at the graveyard. This ghost also gives <a href='https://eldenring.wiki.fextralife.com/Juvenile+Scholar+Cap' target=\"_blank\">Juvenile Scholar Cap</a> and <a href='https://eldenring.wiki.fextralife.com/Juvenile+Scholar+Robe' target=\"_blank\">Juvenile Scholar Robe</a>. This is the location from the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Resurrection+Painting' target=\"blank\">Resurrection Painting</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8825","x":0.218148905,"y":0.426009761,"cat":"Crafting Materials","group":"Items","title":"Slumbering Egg - 3x Caria Manor Western Walls","desc":"Crafting Material. Three can be looted from a corpse hanging on a wooden walkway on the higher western ramparts of Caria Manor. These can only be reached by dropping down from Three Sisters after defeating the main boss, and finding the path from the south-west of the chapel's rooftop.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1601","x":0.287475375,"y":0.426040279,"cat":"Consumables","group":"Items","title":"Dragonwound Grease","desc":"Found on a body at the stairs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3353","x":0.317237802,"y":0.426223401,"cat":"Bosses","group":"Characters","title":"Godefroy the Grafted","desc":"Optional Boss. Imprisoned within the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Golden+Lineage+Evergaol'>Golden Lineage Evergaol</a>. Drops the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Godfrey+Icon'>Godfrey Icon</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"5908","x":0.444079124,"y":0.426284441,"cat":"Weapons","group":"Equipment","title":"Star Fist","desc":"In the left side of a castle situated atop the mountain near the West Capital Rampart grace in <a href='https://eldenring.wiki.fextralife.com/Leyndell,+Royal+Capital' target=\"_blank\">Leyndell, Royal Capital</a> .","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fist.png?h=40"},{"id":"1801","x":0.20740855,"y":0.426467563,"cat":"Locations","group":"Locations","title":"Seluvis's Rise","desc":"One of three towers found in the <a href='https://eldenring.wiki.fextralife.com/Three+Sisters' target=\"_blank\">Three Sisters</a> sub-region. Three Sisters is accessible after completing <a href='https://eldenring.wiki.fextralife.com/Caria+Manor' target=\"_blank\">Caria Manor</a> and defeating <a href='https://eldenring.wiki.fextralife.com/Royal+Knight+Loretta' target=\"_blank\">Royal Knight Loretta</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"5863","x":0.527943591,"y":0.426559126,"cat":"Sites of Grace","group":"Locations","title":"Divine Tower of East Altus: Gate","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3352","x":0.315703418,"y":0.426620166,"cat":"Locations","group":"Locations","title":"Golden Lineage Evergaol","desc":"Evergaol located in south-western <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Altus+Plateau'>Altus Plateau</a>. <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Godefroy+the+Grafted'>Godefroy the Grafted</a> is imprisoned within.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-evergaol.png?h=40"},{"id":"8813","x":0.225779044,"y":0.426620166,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - 3x Caria Manor Entrance","desc":"Crafting Material. Three can be looted from a corpse next to a round structure on the main path heading into the manor. Beware of Giant Hand ambush.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8812","x":0.229226935,"y":0.426681207,"cat":"Crafting Materials","group":"Items","title":"Rimed Crystal Bud - 2x Caria Manor Garden","desc":"Crafting Material. Two can be looted from a corpse near two Giant Hands and several small ones in Caria Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7005","x":0.195664535,"y":0.426864328,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Liurnia's North Sarcophagi","desc":"Looted from the many sarcophagi within the area. Watch out for the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/giats+rats'>Giant Rats</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8814","x":0.222238574,"y":0.426925369,"cat":"Crafting Materials","group":"Items","title":"Rimed Crystal Bud - 5x Caria Manor Entrance","desc":"Crafting Material. Five can be looted from a corpse where a Giant Hand waits in ambush near the entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1508","x":0.197404174,"y":0.427077968,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - Liurnia's North Sarcophagi","desc":"Looted from the many sarcophagi within the area. Watch out for the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/giant+rat'>Giant Rats</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1520","x":0.233101712,"y":0.427169531,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [3] - Caria Manor","desc":"Upgrade Material. Found on a corpse at the end of a narrow path along the eastern walls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2126","x":0.204569664,"y":0.427169531,"cat":"Key Items","group":"Items","title":"Seluvis's Bell Bearing","desc":"Key Item. Found on a body in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Seluvis's+Rise'>Seluvis's Rise</a> after reaching the end of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Ranni+the+Witch'>Ranni's</a> questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1852","x":0.209085723,"y":0.42738317,"cat":"NPCs","group":"Characters","title":"Seluvis","desc":"Quest NPC. Found on the ground floor of his tower after first speaking to his spectral form at <a href='https://eldenring.wiki.fextralife.com/Ranni's+Rise' target=\"_blank\">Ranni's Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3354","x":0.317054579,"y":0.427779936,"cat":"Talismans","group":"Equipment","title":"Godfrey Icon","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Talismans'>Talisman</a>. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Godefroy+the+Grafted'>Godefroy the Grafted</a> when defeated.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6668","x":0.446490709,"y":0.428085138,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - 1x Treasure Leyndell Royal Capital","desc":"Upgrade Material. Found on a corpse sitting by the cliff looking toward the Erdtree","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"11954","x":0.253555257,"y":0.428132228,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily - 5x Liurnia Ravine","desc":"<p>Crafting Material. Can be gathered near the gravestones behind a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Lesser+Red+Wolf+of+Radagon' target=\"\">Lesser Red Wolf of Radagon</a>, in the graveyard behind <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Caria+Manor' target=\"\">Caria Manor</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6965","x":0.233326114,"y":0.42826826,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Caria Manor","desc":"Consumable Item. Located at the fortification ramparts, under the stairs. This area is accessed by dropping down from the higher walkway leading to the lift to upper Caria Manor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5409","x":0.198624967,"y":0.428298778,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - 4x Liurnia's North Sarcophagi","desc":"Multiple Golden Runes can be found within the sarcophagi under the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7004","x":0.196610655,"y":0.428420859,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - Liurnia's North Sarcophagi","desc":"Looted from the many sarcophagi within the area. Watch out for the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/giant+rat'>Giant Rats</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6964","x":0.255849812,"y":0.428603981,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Liurnia's North Creek","desc":"Near the river shore, surrounded by <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/wolf'>Wolves</a> and a <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/lesser+red+wolf+of+radagon'>Lesser Red Wolf of Radagon</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5702","x":0.210399502,"y":0.428726062,"cat":"Armor","group":"Equipment","title":"Black Wolf Mask","desc":"This mask can be found on the wall behind <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/seluvi's+rise'>Seluvis's Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"5427","x":0.52704474,"y":0.428787102,"cat":"Locations","group":"Locations","title":"Divine Tower of East Altus","desc":"Divine Tower of East Altus.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-divinetower.png?h=40"},{"id":"2127","x":0.204784613,"y":0.428970224,"cat":"Armor","group":"Equipment","title":"Preceptor's Set","desc":"Armor Set. Found on a body in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Seluvis's+Rise'>Seluvis's Rise</a> after reaching the end of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Ranni+the+Witch'>Ranni's</a> questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"1853","x":0.208628097,"y":0.429092305,"cat":"Key Items","group":"Items","title":"Seluvis's Potion","desc":"Key Quest Item. Given by <a href='https://eldenring.wiki.fextralife.com/Seluvis' target=\"_blank\">Seluvis</a> after accepting his task.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2297","x":0.207011258,"y":0.429183867,"cat":"Key Items","group":"Items","title":"Seluvis's Introduction","desc":"A scroll given by <a href='https://eldenring.wiki.fextralife.com/Seluvis' target=\"_blank\">Seluvis</a>. It is addressed to <a href='https://eldenring.wiki.fextralife.com/Sorceress+Sellen' target=\"_blank\">Sorceress Sellen</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8817","x":0.231851649,"y":0.429214386,"cat":"Crafting Materials","group":"Items","title":"Rimed Crystal Bud - 8x Caria Manor Ramparts","desc":"Crafting Material. Eight can be looted from a corpse on a wooden platform on Caria Manor's Outer Walls. Reach this area by jumping down from the overhead walkway used to access the lift toward Manor Upper Level.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7006","x":0.197587291,"y":0.429946872,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - Liurnia's North Sarcophagi","desc":"Looted from the many sarcophagi within the area. Watch out for the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/giant+rat'>Giant Rats</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6609","x":0.22165902,"y":0.430129993,"cat":"Key Items","group":"Items","title":"Stonesword Key - Caria Manor Western Walls","desc":"Crafting Material. Three can be looted from a corpse on the Western Walls of Caria Manor. It is guarded by a Giant Crab.This area can only be reached by dropping down from Three Sisters after defeating the main boss, and finding the path from the south-west of the chapel's rooftop.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"5410","x":0.22760938,"y":0.430374155,"cat":"Crafting Materials","group":"Items","title":"Rimed Crystal Bud - 3x Caria Manor","desc":"Crafting Material. Three Rimed Crystal Buds can be found within the garden of the Caria Manor","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8818","x":0.224800295,"y":0.431228722,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [3] - Caria Manor","desc":"Upgrade Material. One can be looted from a corpse on the manor outer walls, above the entrance to the grounds. This area is only reachable by dropping down from the higher level walkway, right before reaching the lift to the Manor Upper Level site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"1513","x":0.223641175,"y":0.432235893,"cat":"Sites of Grace","group":"Locations","title":"Main Caria Manor Gate","desc":"Site of Grace found by the southern gate to Caria Manor. Be careful when traversing the fields outside the manor, as a rain of energy projectiles will constantly bombard you until you reach this Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1519","x":0.231394874,"y":0.432327452,"cat":"Key Items","group":"Items","title":"Glintstone Craftsman's Cookbook [6]","desc":"Cookbook Key Item. Found on a corpse in a small room southeast of the gardens.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"6301","x":0.233225914,"y":0.433212541,"cat":"Weapons","group":"Equipment","title":"Urumi","desc":"Whip. Found on a body on the south-east ramparts, reached by jumping from the higher ramparts leading to the elevator and the Manor Upper Level site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-whip.png?h=40"},{"id":"5428","x":0.528494312,"y":0.434708277,"cat":"Sites of Grace","group":"Locations","title":"Divine Tower of East Altus","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1510","x":0.243602855,"y":0.436142485,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Hoarfrost Stomp","desc":"Ash Of War Upgrade. Dropped by an invisible <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> roaming around the shallow water. Look for its glowing footprints and attack as the prints move towards you.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"5920","x":0.213756301,"y":0.438370462,"cat":"Flask Upgrades","group":"Items","title":"Intelligence-knot Crystal Tear","desc":"From Road to the Manor Site of Grace, head southeast down the slope and turn back towards north. Loot from a small, half-bowl structure guarded by a few <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Lesser+Spider+Hand'>Lesser Spider Hand</a> and one <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Spider+Hand'>Spider Hand</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"1587","x":0.261709635,"y":0.438400984,"cat":"Consumables","group":"Items","title":"Rune Arc E","desc":"On a body, found near the gravestones leading down the cliff","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6372","x":0.276888867,"y":0.439530231,"cat":"Weapons","group":"Equipment","title":"Great Mace","desc":"Can be found inside a chest, in the bandit camp.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-warhammer.png?h=40"},{"id":"15301","x":0.283673289,"y":0.442458957,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Rare Crafting Material. Northeast the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Church+of+Inhibition' target=\"blank\">Church of Inhibition</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5853","x":0.242607088,"y":0.442979022,"cat":"Sites of Grace","group":"Locations","title":"The Ravine","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3103","x":0.415318667,"y":0.443101103,"cat":"Sites of Grace","group":"Locations","title":"Divine Tower of West Altus Gate","desc":"The Site of Grace can be found before the great entrance door to the Divine Tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8838","x":0.279945722,"y":0.443345265,"cat":"Key Items","group":"Items","title":"Lord of Blood's Favor - Church of Inhibition","desc":"<p>Key Item. Found on a seated deceased maiden with the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Church+of+Inhibition' target=\"\">Church of Inhibition</a>. Obtained from <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/White-Faced+Varre' target=\"\">White-Faced Varre</a> after invading other players 3 times and talking to him, then accepting to be knighted.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1574","x":0.25198979,"y":0.443406305,"cat":"NPCs","group":"Characters","title":"Nomadic Merchant North Liurnia of the Lakes","desc":"Merchant NPC located next to the river, just pass the <a href='https://eldenring.wiki.fextralife.com/Bellum+Church' target=\"_blank\">Bellum Church's</a> hole in order to find him.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"6004","x":0.281038138,"y":0.444505034,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (Church of Inhibition)","desc":"Found within the <a href='https://eldenring.wiki.fextralife.com/Church+of+Inhibition' target=\"_blank\">Church of Inhibition</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"14351","x":0.216688388,"y":0.444847018,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf - Road to the Manor","desc":"Rare Crafting Material. Near the Road to the Manor Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3802","x":0.281039415,"y":0.44511544,"cat":"Armor","group":"Equipment","title":"Finger Maiden Set","desc":"Light Armor Set by the Site of Grace of Church of Inhibition. Includes Finger Maiden Fillet, Finger Maiden Robe and Finger Maiden Shoes","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"6400","x":0.233832637,"y":0.445542723,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4]","desc":"Found on a dead body sitting on a chair.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"1819","x":0.280703721,"y":0.446305727,"cat":"Sites of Grace","group":"Locations","title":"Church of Inhibition","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"10223","x":0.300557612,"y":0.44633625,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Frenzy-Flaming Tower","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia' target=\"blank\">Liurnia</a>, down the cliffs directly north of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Frenzy-Flaming+Tower' target=\"blank\">Frenzy-Flaming Tower</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"5794","x":0.205027555,"y":0.446641452,"cat":"Armor","group":"Equipment","title":"Iji's Mirrorhelm","desc":"Need to confront <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/blaidd'>Blaidd</a> during <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/ranni+the+witch'>Ranni's</a> questline. <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/war+counselor+iji'>War Counselor Iji</a> will have new dialogue available. After that, his corpse can be found near his usual spot at the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Sites+of+Grace'>Road to the Manor Site of Grace</a>. The anvil has <strong>Iji's Mirrorhelm</strong> as well as <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/iji's+bell+bearing'>Iji's Bell Bearing</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"3102","x":0.415090137,"y":0.447007695,"cat":"Locations","group":"Locations","title":"Divine Tower of West Altus","desc":"The entrance to the Divine Tower of West Altus is found at the end of the Sealed Tunnel after going past many illusory walls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-divinetower.png?h=40"},{"id":"1816","x":0.27948087,"y":0.447038213,"cat":"Locations","group":"Locations","title":"Church of Inhibition","desc":"The remnants of an old church in the north of Liurnia, just before the Altus Plateau.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"8558","x":0.292665166,"y":0.447160295,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - 1x Bellum Highway East","desc":"Upgrade Material. Looted off a corpse on the slopes leading to Frenzy-Flaming Tower in eastern Bellum Highway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"808","x":0.20466149,"y":0.4476181,"cat":"NPCs","group":"Characters","title":"War Counselor Iji","desc":"Blacksmith - sells <a href='https://eldenring.wiki.fextralife.com/Upgrade+Materials' target=\"_blank\">Upgrade Materials</a> such as Somber Smithing Stone [1] through [4].","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"15302","x":0.274299309,"y":0.447771922,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Rare Crafting Material. Nearby the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Church+of+Inhibition' target=\"blank\">Church of Inhibition</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8559","x":0.292024267,"y":0.447984343,"cat":"Crafting Materials","group":"Items","title":"Yellow Ember - 1x Bellum Highway East","desc":"Crafting Material. Looted off a corpse on the slopes leading to Frenzy-Flaming Tower in eastern Bellum Highway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8560","x":0.294555996,"y":0.448533708,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - 1x Bellum Highway East","desc":"Consumable Item. Looted off a corpse on the slopes leading to Frenzy-Flaming Tower in eastern Bellum Highway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1571","x":0.249853472,"y":0.448686307,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (Bellum Church)","desc":"Flask Upgrade Material. Found Inside <a href='https://eldenring.wiki.fextralife.com/Bellum+Church' target=\"_blank\">Bellum Church</a>, below the big statue.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"1507","x":0.206401574,"y":0.448869429,"cat":"Sites of Grace","group":"Locations","title":"Road to the Manor","desc":"Site of Grace found along the main road towards <a href='https://eldenring.wiki.fextralife.com/Caria+Manor' target=\"_blank\">Caria Manor</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1074","x":0.250280324,"y":0.450517522,"cat":"Locations","group":"Locations","title":"Bellum Church","desc":"Located past the ruins and the forested area guarded by Mounted Knights.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"2820","x":0.251745083,"y":0.450944806,"cat":"NPCs","group":"Characters","title":"Hyetta (Fourth location)","desc":"Hyetta moves here if you have given her shabiri grapes at her previous locations.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"5706","x":0.29724143,"y":0.451677292,"cat":"Locations","group":"Locations","title":"Frenzy-Flaming Tower","desc":"A giant flame causing madness in the surrounding area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tower.png?h=40"},{"id":"5944","x":0.299075231,"y":0.451860414,"cat":"Spells","group":"Equipment","title":"Howl of Shabriri","desc":"<a href='https://eldenring.wiki.fextralife.com/Incantations' target=\"_blank\">Incantation</a>. Found in a chest on the second level of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Frenzy-Flaming+Tower'>Frenzy-Flaming Tower</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-orangespell.png?h=40"},{"id":"6369","x":0.283328569,"y":0.451890936,"cat":"Weapons","group":"Equipment","title":"Vyke's War Spear","desc":"Can be dropped from <a href='https://eldenring.wiki.fextralife.com/Festering+Fingerprint+Vyke' target=\"_blank\">Festering Fingerprint Vyke</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatspear.png?h=40"},{"id":"1075","x":0.248023464,"y":0.452837062,"cat":"Sites of Grace","group":"Locations","title":"Bellum Church (Site of Grace)","desc":"Right outside the entrance to Bellum Church","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1859","x":0.281465517,"y":0.453020183,"cat":"NPC Invaders","group":"Characters","title":"Festering Fingerprint Vyke","desc":"Invader using a War Spear of their name.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"1858","x":0.279152207,"y":0.453294867,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy D","desc":"Dropped by the invader Festering Fingerprint Vyke.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"4575","x":0.414479094,"y":0.453477989,"cat":"Sites of Grace","group":"Locations","title":"Divine Tower of West Altus","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8198","x":0.311644578,"y":0.454363074,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Black Knife Catacombs","desc":"Summoning Pool Effigy found In front of the Boss Doors of the Black Knife Catacombs in Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2062","x":0.209330165,"y":0.454942961,"cat":"Weapons","group":"Equipment","title":"Frozen Needle","desc":"Thrusting Sword. Found in a chest inside a small room in an underground area of the ruins. The <a href='https://eldenring.wiki.fextralife.com/Royal+Revenant' target=\"_blank\">Royal Revenant</a> needs to be defeated to gain access to this room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-thrusting_sword.png?h=40"},{"id":"6854","x":0.28150224,"y":0.455004002,"cat":"Key Items","group":"Items","title":"Fingerprint Grape","desc":"Dropped by <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Festering+Fingerprint+Vyke'>Festering Fingerprint Vyke</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6807","x":0.314756982,"y":0.455156601,"cat":"Key Items","group":"Items","title":"Deathroot - Black Knife Catacombs","desc":"Can be found inside a chest behind the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/cemetery+shade'>Cemetery Shade</a> in the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/black+knife+catacombs'>Black Knife Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1803","x":0.316741887,"y":0.455217641,"cat":"Talismans","group":"Equipment","title":"Assassin's Cerulean Dagger","desc":"Dropped by the Black Knife Assassin found inside Black Knife Catacombs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1595","x":0.313078817,"y":0.455553366,"cat":"Sites of Grace","group":"Locations","title":"Black Knife Catacombs","desc":"Site of Grace found at the top of the Black Knife Catacombs","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1605","x":0.227161089,"y":0.455614407,"cat":"Consumables","group":"Items","title":"Soporific Grease","desc":"Consumable Item. 3 are found under a fall structure.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8728","x":0.3144855,"y":0.455919609,"cat":"Consumables","group":"Items","title":"Rune Arc - 1x Black Knife Catacombs","desc":"Consumable Item. Found on a corpse on the lowest area of the catacombs, where two giant crabs spawn.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2061","x":0.207737378,"y":0.456133253,"cat":"Bosses","group":"Characters","title":"Royal Revenant","desc":"Optional Boss found in an underground area of the <a href='https://eldenring.wiki.fextralife.com/Kingsrealm+Ruins' target=\"_blank\">Kingsrealm Ruins</a>. The stairs leading down to the location is hidden by an illusory floor in the northeast section of the ruins. You need to step on the floor to dispel the illusion.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6511","x":0.318848634,"y":0.456652095,"cat":"Bosses","group":"Characters","title":"Cemetery Shade (Black Knife Catacombs)","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"1805","x":0.312193608,"y":0.456957298,"cat":"Spirit Ashes","group":"Equipment","title":"Twinsage Sorcerer Ashes","desc":"Dropped by the Cemetery Shade boss of the Black Knife Catacombs","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"8201","x":0.200725129,"y":0.457293019,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Kingsrealm Ruins","desc":"Summoning Pool Effigy found on the front-left side of the leftmost building when approaching the Kingsrealm Ruins in Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2060","x":0.206371319,"y":0.457628743,"cat":"Locations","group":"Locations","title":"Kingsrealm Ruins","desc":"A large set of ruins found in northwest Liurnia.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"8811","x":0.20792615,"y":0.457842383,"cat":"Crafting Materials","group":"Items","title":"Glintstone Firefly - 4x Kingsrealm Ruins","desc":"Crafting Material. Four can be looted from a corpse near the ghost that tells you about the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1599","x":0.315672956,"y":0.457872905,"cat":"Locations","group":"Locations","title":"Black Knife Catacombs","desc":"Black Knife Catacombs homes many skeletons and crabs within its depths, find and defeat the Black Knife Assassin within to obtain their dagger","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"8729","x":0.310914669,"y":0.458178108,"cat":"Consumables","group":"Items","title":"Spellproof Dried Liver - 1x Black Knife Catacombs","desc":"Consumable Item. Found on a corpse in the room with the saw traps.-11","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4490","x":0.319184352,"y":0.458269667,"cat":"Bosses","group":"Characters","title":"Black Knife Assassin (Liurnia of the Lakes East)","desc":"Miniboss of the Black Knife Catacombs. Drops <a href='https://eldenring.wiki.fextralife.com/Assassin's+Cerulean+Dagger' target=\"_blank\">Assassin's Cerulean Dagger</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"1851","x":0.285707368,"y":0.45848331,"cat":"Spells","group":"Equipment","title":"Frenzied Burst","desc":"<a href='https://eldenring.wiki.fextralife.com/Incantations' target=\"_blank\">Incantation</a>. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> south of the <a href='https://eldenring.wiki.fextralife.com/Church+of+Inhibition' target=\"_blank\">Church of Inhibition</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-orangespell.png?h=40"},{"id":"8557","x":0.265934,"y":0.45869695,"cat":"Crafting Materials","group":"Items","title":"Slumbering Egg - 2x Bellum Highway","desc":"Crafting Material. Two can be looted off a corpse defended by two soldiers on the eastern section of Bellum Highway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1865","x":0.31225614,"y":0.459093715,"cat":"Weapons","group":"Equipment","title":"Rosus' Axe","desc":"An Axe found in the room sealed by the Imp Statue in the Black Knife Catacombs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-axe.png?h=40"},{"id":"6856","x":0.318298995,"y":0.459368396,"cat":"Key Items","group":"Items","title":"Black Knifeprint","desc":"<strong>Black Knifeprint</strong> is a <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/key+items'>Key Item</a> needed to advance in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Sorcerer+Rogier'>Sorcerer Rogier's</a> questline. Dropped by <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/black+knife+assassin'>Black Knife Assassin</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3507","x":0.313474867,"y":0.460436607,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [2] - 4x Black Knife Catacombs","desc":"Spirit Ash Upgrade Material. The first is found to the left of the boss door, just before the steps leading downwards. The second one is found just past the Imp Statue-sealed room, in a dead end to the left. The third and fourth are found in the first section of the sewer area after dropping down the ladder.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"1812","x":0.30151177,"y":0.460497647,"cat":"Sites of Grace","group":"Locations","title":"Frenzied Flame Village Outskirts","desc":"Site of Grace at the Frenzied Flame Village Outskirts. You can see the Frenzied Flame from this location.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3509","x":0.317228947,"y":0.460924931,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [4] - 2x Black Knife Catacombs","desc":"Spirit Ash Upgrade Material. The first one is found in the room with the cleaver traps. Wait for the second-to-last cleaver to fall and then stand on top of it to use it as a lift. Jump onto the tunnel in the wall and the glovewort can be found just to the right of the entrance. The next one is found by continuing along the same tunnel. All the way to the end of the path is an illusory wall hiding the <a href='https://eldenring.wiki.fextralife.com/Black+Knife+Assassin' target=\"_blank\">Black Knife Assassin</a>'s mist gate. The glovewort is found just before this gate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"26854","x":0.254724676,"y":0.460973763,"cat":"Crafting Materials","group":"Items","title":"Sanctuary Stone","desc":"x3 are Found on a corpse among the ruins, guarded by several weak enemies and a shielded one.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6970","x":0.272553608,"y":0.461230133,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - Liurnia's North-East Sarcophagi","desc":"Looted off Liurnia of the Lakes' north-east sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7012","x":0.274232202,"y":0.461260651,"cat":"Consumables","group":"Items","title":"Golden Rune [7] - Liurnia's North-East Sarcophagi","desc":"Looted off Liurnia of the Lakes' north-east sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1867","x":0.321194012,"y":0.461443773,"cat":"Spells","group":"Equipment","title":"Cannon of Haima","desc":"Found in the chest at the top of the <a href='https://eldenring.wiki.fextralife.com/Converted+Fringe+Tower' target=\"_blank\">Converted Fringe Tower</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"3508","x":0.315092555,"y":0.461535336,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [3] - 4x Black Knife Catacombs","desc":"Spirit Ash Upgrade Material. The first one is found in the center of a small room past the hall with the cleaver traps. The second one is found in the second section of the sewer area, after dropping down the ladder. The third one is found by returning to the cleaver trap room, waiting for the second-to-last cleaver to fall and then standing on top of it. It will bring you up where you can jump onto a tunnel entrance. Follow this path past the statues and the glovewort will be in a small alcove on the right. The final one is found by dropping down the hole in the alcove where the third glovewort was found to a sewer section where the boss door's lever can also be found.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"7010","x":0.27093605,"y":0.461687935,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - Liurna's North-East Sarcophagi","desc":"Looted off Liurnia of the Lakes' north-east sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1140","x":0.198193463,"y":0.462542502,"cat":"Maps","group":"Locations","title":"Map (Liurnia, West)","desc":"Map Fragment. Reveals western Liurnia. Found on a monolith along the road by a junction.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"1868","x":0.322048571,"y":0.462664584,"cat":"Spells","group":"Equipment","title":"Gavel of Haima","desc":"Found in the chest at the top of the <a href='https://eldenring.wiki.fextralife.com/Converted+Fringe+Tower' target=\"_blank\">Converted Fringe Tower</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"7011","x":0.273499724,"y":0.462695105,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Liurnia's North-East Sarcophagi","desc":"Looted off Liurnia of the Lakes' north-east sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6963","x":0.27203477,"y":0.462969786,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - 4x Liurnia's North-East Sarcophagi","desc":"Four <strong>Golden Runes (3)</strong> looted off Liurnia of the Lakes' north-east sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"15303","x":0.318435132,"y":0.463085765,"cat":"Consumables","group":"Items","title":"Crystal Dart - Converted Fringe Tower","desc":"Consumable Throwable. <a href='https://eldenring.wiki.fextralife.com/Converted+Fringe+Tower' target=\"_blank\">Converted Fringe Tower</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1813","x":0.320098002,"y":0.463580191,"cat":"Locations","group":"Locations","title":"Converted Fringe Tower","desc":"Tower found on the Fringe, a puzzle seals the rest of the Tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"8713","x":0.853455668,"y":0.463671753,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] J - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse on a floating section of the plaza with the fallen dragon statue, near the <strong>Dragon Temple Rooftop</strong> site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4483","x":0.252751805,"y":0.463915915,"cat":"Weapons","group":"Equipment","title":"Nightrider Glaive","desc":"Halberd dropped by miniboss <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a>. Only appears at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-halberd.png?h=40"},{"id":"6064","x":0.287112372,"y":0.464556839,"cat":"Key Items","group":"Items","title":"Stonesword Key - Frenzied Flame Village","desc":"Key Item. Found atop the Frenzied Flame Village outer walls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6532","x":0.285647062,"y":0.46467892,"cat":"Crafting Materials","group":"Items","title":"Eye of Yelough - 3x Frenzied Flame Village","desc":"Crafting Material. Three can be looted from a corpse protected by 1 Giant Rat and 3 regular rats. This is on a lower platform accessible by dropping from the higher parts of Frenzied Flame Village, or by following the outer side of the walls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1856","x":0.289491164,"y":0.465289325,"cat":"Talismans","group":"Equipment","title":"Shabriri's Woe","desc":"Found on a body at the edge of the Frenzied Flame Village","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1141","x":0.195323693,"y":0.466143892,"cat":"Sites of Grace","group":"Locations","title":"Northern Liurnia Lake Shore","desc":"Site of Grace found by the road leading to north Liurnia.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6356","x":0.859895034,"y":0.466510135,"cat":"Armor","group":"Equipment","title":"Drake Knight Set","desc":"Armor Set comprised of the <a href='https://eldenring.wiki.fextralife.com/Drake+Knight+Helm' target=\"_blank\">Drake Knight Helm</a>, <a href='https://eldenring.wiki.fextralife.com/Drake+Knight+Armor' target=\"_blank\">Drake Knight Armor</a>, <a href='https://eldenring.wiki.fextralife.com/Drake+Knight+Gauntlets' target=\"_blank\">Drake Knight Gauntlets</a> and the <a href='https://eldenring.wiki.fextralife.com/Drake+Knight+Greaves' target=\"_blank\">Drake Knight Greaves</a>. This set can be acquired once you reach the <strong>Dragon Temple Rooftop</strong> site of grace. Use the red roof below the grace to reach the rooftop garden-like area in the northeast which has a rotunda structure with a lift inside. The lift can't be used initially so drop down onto the large red roof to the south, then down the walkway to the east. Check along the northeast edge of this walkway for a platform you can jump onto to reach the rotunda building's lower balcony. The armor set can be found in a chest at the northeast end of this balcony.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"4481","x":0.252036106,"y":0.466601698,"cat":"Bosses","group":"Characters","title":"Night's Cavalry (Liurnia of the Lakes North)","desc":"Spawns only at night. Drops Ash of War: Giant Hunt and Nightrider Glaive","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"4482","x":0.248787537,"y":0.466662738,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Giant Hunt","desc":"Ash of War dropped by miniboss <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry. Only appears at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"1857","x":0.292880635,"y":0.466937419,"cat":"Key Items","group":"Items","title":"Frenzied's Cookbook [1]","desc":"Key Item. Found on a body inside one of the first houses found when entering Frenzied Flame Village.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"4356","x":0.858125215,"y":0.467486783,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] D - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse northeast of the <strong>Dragon Temple Rooftop</strong> site of grace, in front of a large rotunda building in the rooftop gardens.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8727","x":0.294498189,"y":0.467486783,"cat":"Key Items","group":"Items","title":"Note: The Lord of Frenzied Flame","desc":"Info Item. Found on a corpse in a corner behind a broken shack, soon after entering Frenzied Flame Village from the northeast (Frenzy-Flaming Tower side)","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8717","x":0.856570439,"y":0.467547824,"cat":"Consumables","group":"Items","title":"Lightning Greatbolt - 5x Crumbling Farum Azula","desc":"Ammunition. A <strong>set of 5</strong> can be found on a corpse on a small upper balcony connected to the rotunda structure northeast of the <strong>Dragon Temple Rooftop</strong> site of grace. To get up here, drop down the large roof south of the gazebo and then down to the walkway in the east. Check the northeast edge of this walkway to find a platform you can jump onto to reach the rotunda's lower balcony where you can ride the lift to the top level. The corpse is guarded by a <a href='https://eldenring.wiki.fextralife.com/Azula+Beastman' target=\"_blank\">Beastman</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1604","x":0.219521674,"y":0.468036148,"cat":"Crafting Materials","group":"Items","title":"Old Fang","desc":"Crafting Material. 2 are found on a corpse hidden within a huge clutch of Poison Pods under a fallen structure.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"4355","x":0.85489009,"y":0.46806667,"cat":"Sites of Grace","group":"Locations","title":"Dragon Temple Rooftop","desc":"Site of Grace found atop the large structure in the north section of the region.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"26850","x":0.234683938,"y":0.468799156,"cat":"Crafting Materials","group":"Items","title":"Lump of Flesh","desc":"The item can be looted from a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8240","x":0.858583017,"y":0.468921237,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Crumbling Farum Azula (Dragon Temple Rooftop)","desc":"Summoning Pool Effigy found after defeating two birds at the top of the first ladder, past the Dragon Temple Rooftop site of grace in Crumbling Farum Azula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1811","x":0.292695483,"y":0.468951755,"cat":"Locations","group":"Locations","title":"Frenzied Flame Village","desc":"Madness-inducing location. Accessible only from Bellum Highway, northern Liurnia of the Lakes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-frenziedflamevillage.png?h=40"},{"id":"4509","x":0.855042707,"y":0.469379039,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] B - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse on a balcony south of the <strong>Dragon Temple Rooftop</strong> site of grace. To reach this balcony, you will need to head north from the <strong>Great Bridge</strong>, through the archway and exit to the balcony on the right.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"8726","x":0.860871862,"y":0.469775804,"cat":"Key Items","group":"Items","title":"Bernahl's Bell Bearing","desc":"Key Item. Dropped by the invader <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/recusant+bernahl'>Recusant Bernahl</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4506","x":0.859713988,"y":0.470752452,"cat":"Consumables","group":"Items","title":"Blasphemous Claw","desc":"Reusable Tool. Dropped by the invader <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/recusant+bernahl'>Recusant Bernahl</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4505","x":0.858430971,"y":0.471912222,"cat":"NPC Invaders","group":"Characters","title":"Recusant Bernahl","desc":"If you've killed <a href='https://eldenring.wiki.fextralife.com/Rykard,+Lord+of+Blasphemy' target=\"_blank\">Rykard</a> in the <a href='https://eldenring.wiki.fextralife.com/Volcano+Manor' target=\"_blank\">Volcano Manor</a>, you will be invaded by <a href='https://eldenring.wiki.fextralife.com/Recusant+Bernahl' target=\"_blank\">Recusant Bernahl</a> on the walkway leading to the rotunda with a chest containing the <a href='https://eldenring.wiki.fextralife.com/Old+Lord's+Talisman' target=\"_blank\">. This area is accessed by heading north from the <strong>Great Bridge</strong> and entering the building there. Exit onto the balcony on the right and take the ladder nearby down to the walkway leading to the rotunda. Berhnal drops the following items upon defeat: <ul> <li><a href='https://eldenring.wiki.fextralife.com/Bernahl's+Bell+Bearing' target=\"_blank\">Bernahl's Bell Bearing</a></li> <li><a href='https://eldenring.wiki.fextralife.com/Beast+Champion+Set' target=\"_blank\">Beast Champion Set</a></li> <li><a href='https://eldenring.wiki.fextralife.com/Blasphemous+Claw' target=\"_blank\">Blasphemous Claw</a></li> <li><a href='https://eldenring.wiki.fextralife.com/Devourer's+Scepter' target=\"_blank\">Devourer's Scepter</a></li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"3355","x":0.860811247,"y":0.472400546,"cat":"Talismans","group":"Equipment","title":"Old Lord's Talisman","desc":"Talisman. Found in a chest inside a rotunda on the east edge of the <strong>Dragon Temple Rooftop</strong> area. This area is accessed by heading north from the <strong>Great Bridge</strong> and entering the building there. Exit onto the balcony on the right and take the ladder nearby down to the walkway leading to the rotunda. Beware as the chest is surrounded by <a href='https://eldenring.wiki.fextralife.com/Azula+Beastman' target=\"_blank\">Beastmen</a> and, if you've killed <a href='https://eldenring.wiki.fextralife.com/Rykard,+Lord+of+Blasphemy' target=\"_blank\">Rykard</a> in the <a href='https://eldenring.wiki.fextralife.com/Volcano+Manor' target=\"_blank\">Volcano Manor</a>, you will be invaded by <a href='https://eldenring.wiki.fextralife.com/Recusant+Bernahl' target=\"_blank\">Recusant Bernahl</a> on the walkway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4284","x":0.845003197,"y":0.472919389,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] B - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse behind a fallen pillar in the northern section past a narrow path laden with dragon statues.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8724","x":0.854737767,"y":0.472980429,"cat":"Talismans","group":"Equipment","title":"Boltdrake Talisman +2","desc":"Talisman. Found on a corpse hanging off an opening in a tall tower south of the <strong>Dragon Temple Rooftop</strong> site of grace. Reaching this area is a bit complex: <ol> <li>You will first need to head southeast to the large plaza guarded by a stationary <a href='https://eldenring.wiki.fextralife.com/Farum+Azula+Dragon' target=\"_blank\">Farum Azula Dragon</a> which is constantly raining red lightning all around the area.</li> <li>From here, drop down a series of cliffs to the east to reach the opening at the bottom of a large building.</li> <li>Follow the linear path here to a balcony with a ladder leading up to a terrace.</li> <li>Directly in front of the ladder is a lift building. Take the lift up to a series of slopes leading to a hallway underneath the same bridge you crossed to get to the southeast plaza.</li> <li>Fight your way through the hallway to reach a ladder at the end.</li> <li>Climb up the ladder to reach the opening where the corpse holding the talisman can be found.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"8555","x":0.290833912,"y":0.473468753,"cat":"Summoning Pools","group":"Locations","title":"Effigy of Martyr: Liurnia East Minor Erdtree","desc":"Summoning Pool Effigy found to the west of the Minor Erdtree in Eastern Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4508","x":0.859314543,"y":0.473743437,"cat":"Armor","group":"Equipment","title":"Beast Champion Set","desc":"Armor Set comprised of the <a href='https://eldenring.wiki.fextralife.com/Beast+Champion+Helm' target=\"_blank\">Beast Champion Helm</a>, <a href='https://eldenring.wiki.fextralife.com/Beast+Champion+Armor+(Altered)' target=\"_blank\">Beast Champion Armor (Altered)</a>, <a href='https://eldenring.wiki.fextralife.com/Beast+Champion+Gauntlets' target=\"_blank\">Beast Champion Gauntlets</a> and <a href='https://eldenring.wiki.fextralife.com/Beast+Champion+Greaves' target=\"_blank\">Beast Champion Greaves</a>. Reusable Tool. Dropped by the invader <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/recusant+bernahl'>Recusant Bernahl</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"4285","x":0.841554447,"y":0.473926559,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9] D - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse on an upper level balcony in the northern section past the <strong>Dragon Temple</strong>. From the north end of the temple, navigate your way across the floating debris to a narrow path laden with dragon statues, at the end of which you will find a spiral staircase on the right side. Head up these stairs and continue west to a balcony with a sealed Imp Statue barrier and several fallen pillars. The corpse holding the stone can be found behind one of these pillars.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4594","x":0.276886875,"y":0.473957077,"cat":"Locations","group":"Locations","title":"Walking Mausoleum (Liurnia of the Lakes East)","desc":"Attack the legs to bring down the mausoleum and go inside it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-walking-mausoleum.png?h=40"},{"id":"8723","x":0.866672531,"y":0.47410968,"cat":"Consumables","group":"Items","title":"Golden Rune [12] H - Crumbling Farum Azula","desc":"Rune Consumable. Found on a corpse inside a building far to the bottom of the plaza southeast from the <strong>Dragon Temple Rooftop</strong> site of grace. This building can be reached by dropping down a series of cliffs east of the plaza.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1861","x":0.299134505,"y":0.474659045,"cat":"Locations","group":"Locations","title":"Minor Erdtree (Liurnia Northeast)","desc":"Minor Erdtree in the Northeast part of the Liurnia of the Lakes region.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tree.png?h=40"},{"id":"4507","x":0.860503711,"y":0.474659045,"cat":"Weapons","group":"Equipment","title":"Devourer's Scepter","desc":"Great Hammer. Dropped by the invader <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/recusant+bernahl'>Recusant Bernahl</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-warhammer.png?h=40"},{"id":"4352","x":0.8476274,"y":0.474872684,"cat":"Talismans","group":"Equipment","title":"Dragoncrest Shield Talisman +2","desc":"Upgraded Talisman. Found on a corpse on a chunk of floating debris in the north of the region. From the <strong>Dragon Temple Lift</strong> site of grace, take the lift back down and then head east and down the spiral staircase. Around halfway down the steps where you see some broken railings, jump off the edge to a series of floating debris below. Once you reach the lowest platforms, turn around and look for a small platform underneath one of the upper ones to find the corpse with the talisman.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6103","x":0.24008803,"y":0.474903207,"cat":"NPCs","group":"Characters","title":"Boc the Seamster (Fourth Location)","desc":"NPC. He can be found kneeling by the East Raya Lucaria Gate Site of Grace (southwest most point of the Bellum Road). You have to rest at this Site of Grace for him to appear.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"5712","x":0.867344818,"y":0.475452571,"cat":"Shields","group":"Equipment","title":"Dragon Towershield","desc":"Greatshield. Found in a chest in the terrace section of a building far to the bottom of the plaza southeast from the <strong>Dragon Temple Rooftop</strong> site of grace. This building can be reached by dropping down a series of cliffs east of the plaza until you see the archway leading into the building. Follow the linear path from here to a lower balcony with a ladder. Climb up the ladder to the terrace and look to the east to find the chest by the railings.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"8703","x":0.841066321,"y":0.475666211,"cat":"Consumables","group":"Items","title":"Lightning Grease - 5x Crumbling Farum Azula","desc":"Weapon Coating. A <strong>set of 5</strong> can be found behind the narrow path laden with dragon statues. Traverse the length of the path and then turn left at the end to get to the backside, behind the wall. The items are found on a corpse near the southern end of this area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4354","x":0.84897098,"y":0.475849333,"cat":"Consumables","group":"Items","title":"Golden Rune [12] E - Crumbling Farum Azula","desc":"Rune Consumable. Found on a corpse at the edge of some floating debris in the northern section of the region. From the <strong>Dragon Temple Lift</strong> site of grace, take the lift back down and then head east and down the spiral staircase. Around halfway down the steps where you see some broken railings, jump off the edge to a series of floating debris below. Look for one of the chunks facing southward to find the corpse holding the rune.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8721","x":0.862274272,"y":0.476185057,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed (B) - Crumbling Farum Azula","desc":"Flask Upgrade Material. Found under a Phantom Tree amongst several sets of pillar structures up on a hill in the plaza southeast from the <strong>Dragon Temple Rooftop</strong> site of grace. Beware the <a href='https://eldenring.wiki.fextralife.com/Warhawk' target=\"_blank\">Warhawks</a> guarding the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"1569","x":0.239935481,"y":0.476398697,"cat":"Sites of Grace","group":"Locations","title":"East Raya Lucaria Gate","desc":"Site of grace at the eastern gate of Raya Lucaria.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4353","x":0.843355123,"y":0.4765513,"cat":"Upgrade Materials","group":"Items","title":"Ancient Dragon Smithing Stone (B) - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse on a floating platform north of the <strong>Dragon Temple</strong>, guarded by a <a href='https://eldenring.wiki.fextralife.com/Azula+Beastman' target=\"_blank\">Beastman</a>. From the north end of the temple, navigate your way through the floating debris to a narrow path laden with dragon statues, at the end of which you will find a spiral staircase on the right. Head up these stairs and then turn towards the south to find a floating pillar adjoining the aforementioned floating platform. Use the pillar to get up to the platform and collect the stone.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8722","x":0.860691604,"y":0.476642859,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] E - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse near a Phantom Tree amongst several sets of pillar structures up on a hill in the plaza southeast from the <strong>Dragon Temple Rooftop</strong> site of grace. Beware the <a href='https://eldenring.wiki.fextralife.com/Warhawk' target=\"_blank\">Warhawks</a> guarding the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2112","x":0.296416684,"y":0.476734422,"cat":"Bosses","group":"Characters","title":"Erdtree Avatar (Liurnia Northeast)","desc":"Field Boss. Drops Holy-Shrouding Cracked Tear, Lightning-Shrouding Cracked Tear and Magic-Shrouding Cracked Tear","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"4286","x":0.840090411,"y":0.476978584,"cat":"Sites of Grace","group":"Locations","title":"Dragon Temple Lift","desc":"Site of Grace found by ascending the lift. The entrance to the lift is locked behind an Imp Statue seal that requires 2x <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Keys</a>to unlock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4504","x":0.853852571,"y":0.477314305,"cat":"Sites of Grace","group":"Locations","title":"Beside the Great Bridge","desc":"A Site of Grace located in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/crumbling+farum+azula'>Crumbling Farum Azula</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4281","x":0.842715356,"y":0.477588989,"cat":"Crafting Materials","group":"Items","title":"Old Fang - 5x Crumbling Farum Azula (B)","desc":"Crafting Material. A <strong>set of 5</strong> can be found on a corpse hanging off the crumbled floor of a ruined building north of the <strong>Dragon Temple</strong>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6813","x":0.850830809,"y":0.477863669,"cat":"Key Items","group":"Items","title":"Somberstone Miner's Bell Bearing [5]","desc":"Key Item. Found on a corpse sitting in front of an altar right at the entrance to the building with the <strong>Beside the Great Bridge</strong> site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6534","x":0.226601814,"y":0.47792471,"cat":"Crafting Materials","group":"Items","title":"Fulgurbloom","desc":"Can be found on <a href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes' target=\"_blank\">Liurnia of the Lakes</a> , near to <a href='https://eldenring.wiki.fextralife.com/Testu's+Rise' target=\"_blank\">Testu's Rise</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8163","x":0.244696443,"y":0.478077313,"cat":"NPCs","group":"Characters","title":"Finger Reader Crone (East Raya Lucaria Gate)","desc":"NPC. Talk to the Finger Reader to obtain some lore information regarding the lift ahead, and a hint about the secret passage to Altus Plains.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"5852","x":0.278354703,"y":0.478168872,"cat":"Sites of Grace","group":"Locations","title":"Mausoleum Compound","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8238","x":0.852113795,"y":0.478290953,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Crumbling Farum Azula (Beside the Great Bridge)","desc":"Summoning Pool Effigy found at the top of the stairs past the Beside the Great Bridge site of grace in Crumbling Farum Azula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1863","x":0.295684861,"y":0.478443556,"cat":"Flask Upgrades","group":"Items","title":"Lightning-Shrouding Cracked Tear","desc":"Crystal Tear for the Flask of Wondrous Physick. Dropped by the Erdtree Avatar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"4280","x":0.844118313,"y":0.478596155,"cat":"Consumables","group":"Items","title":"Golden Rune [11] B - Crumbling Farum Azula","desc":"Rune Consumable. Found on a corpse hanging off a ledge north of the <strong>Dragon Temple</strong>. After defeating the <a href='https://eldenring.wiki.fextralife.com/Godskin+Duo' target=\"_blank\">Godskin Duo</a> bosses and unlocking the <strong>Dragon Temple Altar</strong> site of grace, head directly north through the stairs and then drop down one level below from the edges. Head through the archway in the west which connects to the platform where the corpse holding the rune can be found.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4282","x":0.842470238,"y":0.47920656,"cat":"Consumables","group":"Items","title":"Hero's Rune [5] B","desc":"Rune Consumable. One found on a corpse by an outer ledge behind a wall. You can get to the ledge by carefully walking on the broken section while hugging the wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1862","x":0.294097827,"y":0.479420204,"cat":"Flask Upgrades","group":"Items","title":"Magic-Shrouding Cracked Tear","desc":"Crystal Tear for the Flask of Wondrous Physick. Dropped by the Erdtree Avatar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"8237","x":0.840761737,"y":0.479633844,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Crumbling Farum Azula (Dragon Temple Lift)","desc":"Summoning Pool Effigy found just outside the room with the Dragon Temple Lift site of grace in Crumbling Farum Azula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1864","x":0.297424414,"y":0.479816965,"cat":"Flask Upgrades","group":"Items","title":"Holy-Shrouding Cracked Tear","desc":"Crystal Tear for the Flask of Wondrous Physick. Dropped by the Erdtree Avatar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"4288","x":0.846560133,"y":0.479847488,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly - 2x Crumbling Farum Azula","desc":"Crafting Materia. A <strong>set of 2</strong> found on a corpse under a tree east of the fountain plaza. This area is accessed after ascending the <strong>Dragon Temple Lift</strong> northwest of the temple.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8241","x":0.848422193,"y":0.479878006,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Crumbling Farum Azula (Dragon Temple Altar)","desc":"Summoning Pool Effigy found north of the Dragon Temple Altar site of grace, after defeating the Godskin Duo in Crumbling Farum Azula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"8704","x":0.842714395,"y":0.480671533,"cat":"Consumables","group":"Items","title":"Lord's Rune - Crumbling Farum Azula","desc":"Rune Consumable. Found atop the fountain located just outside the <strong>Dragon Temple Lift</strong>, after ascending the lift into the plaza.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4358","x":0.861301026,"y":0.480885176,"cat":"Consumables","group":"Items","title":"Golden Rune [12] G - Crumbling Farum Azula","desc":"Rune Consumable. Found on a corpse in front of a stationary <a href='https://eldenring.wiki.fextralife.com/Farum+Azula+Dragon' target=\"_blank\">Farum Azula Dragon</a> sitting at the back of the plaza southeast of the <strong>Dragon Temple Rooftop</strong> site of grace. The dragon is constantly raining red lightning around the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8705","x":0.847842314,"y":0.481129338,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] C - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse on an upper cliff east of the fountain plaza. This is in an upper area accessed after ascending the <strong>Dragon Temple Lift</strong> northwest of the temple. From the lift, head east and down the stairs past a tree. Climb up the ledges to reach the top of the cliff and collect the stone.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8808","x":0.215371641,"y":0.481220897,"cat":"Locations","group":"Locations","title":"1st Turtle Testu's Rise","desc":"First Spirit Turtle: Found north-west from the tower's door.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit-turtle.png?h=40"},{"id":"8720","x":0.859193251,"y":0.48158714,"cat":"Crafting Materials","group":"Items","title":"Fulgurbloom (B) - 8x Crumbling Farum Azula","desc":"Crafting Material. A <strong>set of 8</strong> found on a corpse in front of a stationary <a href='https://eldenring.wiki.fextralife.com/Farum+Azula+Dragon' target=\"_blank\">Farum Azula Dragon</a> sitting at the back of the plaza southeast of the <strong>Dragon Temple Rooftop</strong> site of grace. The dragon is constantly raining red lightning around the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8725","x":0.853486165,"y":0.481648181,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [7] B - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse by the cliffs underneath a section of the <strong>Great Bridge</strong>, accessible by circling around the plaza southeast of the <strong>Dragon Temple Rooftop</strong> site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"8706","x":0.849368195,"y":0.481892343,"cat":"Consumables","group":"Items","title":"Golden Rune [12] D - Crumbling Farum Azula","desc":"Rune Consumable. Found on an upper level east of the fountain plaza. This is in an upper area accessed after ascending the <strong>Dragon Temple Lift</strong> northwest of the temple. From the lift, head east and down the stairs past a tree. Climb up the ledges at the end of the path to reach the upper level and head south. The rune is found on a corpse under a tree in this area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8707","x":0.840212222,"y":0.482380667,"cat":"Consumables","group":"Items","title":"Dragonwound Grease (C) - 2x Crumbling Farum Azula","desc":"Weapon Coating. A <strong>set of 2</strong> can be found on a corpse by the very edge of the cliffs southwest of the fountain plaza. This is in an upper area accessed after ascending the <strong>Dragon Temple Lift</strong> northwest of the temple.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10222","x":0.246240025,"y":0.48253327,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: East Raya Lucaria Gate","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia' target=\"blank\">Liurnia</a>, down the cliffs next to East Raya Lucaria Gate Site of Grace. Across the Bridge from main gate of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"\">Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"1592","x":0.218028234,"y":0.482563788,"cat":"Key Items","group":"Items","title":"Memory Stone - Testu's Rise","desc":"Memory Slot Upgrade Material. Found in a chest at the top floor of <a href='https://eldenring.wiki.fextralife.com/Testu's+Rise' target=\"_blank\">Testu's Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"2059","x":0.189282018,"y":0.482563788,"cat":"Weapons","group":"Equipment","title":"Carian Knight's Sword","desc":"Straight Sword. Found in a chest at the back of a large stagecoach being pulled by 2 Trolls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"4279","x":0.848242134,"y":0.482868991,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Black Flame Tornado","desc":"Ash of War. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Godskin+Duo' target=\"_blank\">Godskin Duo</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"4145","x":0.282990859,"y":0.483265756,"cat":"Locations","group":"Locations","title":"Walking Mausoleum (Liurnia of the Lakes)","desc":"Attack the legs to bring down the mausoleum and go inside it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-walking-mausoleum.png?h=40"},{"id":"3963","x":0.846285683,"y":0.483418355,"cat":"Consumables","group":"Items","title":"Golden Rune [12] C - Crumbling Farum Azula","desc":"Rune Consumable. Found on the broken spiral staircase in the center of the <strong>Dragon Temple</strong>. Requires circling around the back of the temple in the east to reach it. From the <strong>Dragon Temple</strong> site of grace, head inside the archway and turn right then down the stairs on the left. Take another right and then a left into a long hallway that leads to a semi-open area with pillars and a set of stairs on the left. Head up the stairs and follow the hallway to a crumbled section where you can jump onto the aforementioned spiral staircase. The rune is found on a corpse on the top end of it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4357","x":0.862554542,"y":0.483418355,"cat":"Upgrade Materials","group":"Items","title":"Somber Ancient Dragon Smithing Stone - Crumbling Farum Azula","desc":"Upgrade Material. Found in a gazebo behind the stationary <a href='https://eldenring.wiki.fextralife.com/Farum+Azula+Dragon' target=\"_blank\">Farum Azula Dragon</a> sitting at the back of the plaza southeast of the <strong>Dragon Temple Rooftop</strong> site of grace. The dragon is constantly raining red lightning around the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"8719","x":0.861059064,"y":0.483448878,"cat":"Upgrade Materials","group":"Items","title":"Ancient Dragon Smithing Stone (C) - Crumbling Farum Azula","desc":"Upgrade Material. Dropped by the stationary <a href='https://eldenring.wiki.fextralife.com/Farum+Azula+Dragon' target=\"_blank\">Farum Azula Dragon</a> sitting at the back of the plaza southeast of the <strong>Dragon Temple Rooftop</strong> site of grace. The dragon is constantly raining red lightning around the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3967","x":0.849370163,"y":0.48369304,"cat":"Bosses","group":"Characters","title":"Godskin Duo","desc":"The <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle' target=\"_blank\">Godskin Apostle</a> and <a href='https://eldenring.wiki.fextralife.com/Godskin+Noble' target=\"_blank\">Godskin Noble</a> are encountered once again in a simultaneous boss encounter in the center of the <strong>Dragon Temple</strong>. Drops <a href='https://eldenring.wiki.fextralife.com/Smithing-Stone+Miner's+Bell+Bearing+(4)' target=\"_blank\">Smithing-Stone Miner's Bell Bearing (4)</a> and <a href='https://eldenring.wiki.fextralife.com/Ashes+of+War:+Black+Flame+Tornado' target=\"_blank\">Ashes of War: Black Flame Tornado</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"1589","x":0.216683916,"y":0.483998242,"cat":"Locations","group":"Locations","title":"Testu's Rise","desc":"Lookout Tower. Initially sealed by a barrier. Inspecting the statue at the entrance, you are asked to \"seek three wise beasts\". These can be found as Ghostly Tortoises. Skeletal Spirits will also appear all over the isle, attempting to hinder your progress. The first Tortoise can be found by the cliffs north of the tower. The second one can be found in the south, below the cliffs. The last one can be found high up on one of the trees east of the tower. Once all three have been defeated, the tower's seal is broken.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"3958","x":0.841005738,"y":0.484272922,"cat":"Consumables","group":"Items","title":"Golden Rune [11] A - Crumbling Farum Azula","desc":"Rune Consumable. From the <strong>Dragon Temple</strong> site of grace, go through the archway ahead and immediately turn left to collect the rune on a corpse by a collapsed pillar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4501","x":0.84772039,"y":0.484486566,"cat":"Sites of Grace","group":"Locations","title":"Dragon Temple Altar","desc":"This Site of Grace becomes available after defeating the <a href='https://eldenring.wiki.fextralife.com/Godskin+Duo'>Godskin Duo</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8701","x":0.839510264,"y":0.484608647,"cat":"Consumables","group":"Items","title":"Rune Arc - Crumbling Farum Azula (A)","desc":"Consumable. Found on the northeastern edge of the <strong>Dragon Temple</strong>, at the bottom level. To reach this, turn around from the <strong>Dragon Temple</strong> site of grace and face west. Drop down by using the crumbled ledges below and then head north to find the corpse holding the item by one of the crumbled pillars.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8809","x":0.219369765,"y":0.484608647,"cat":"Locations","group":"Locations","title":"2nd Turtle Testu's Rise","desc":"Second Spirit Turtle. Found hanging from a tree east from the tower. Look up and bring it down with ranged attacks or magic.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit-turtle.png?h=40"},{"id":"6257","x":0.188641049,"y":0.484700206,"cat":"Locations","group":"Locations","title":"Enemy Caravan (West Liurnia of the Lakes)","desc":"An enemy caravan travels this road. Loot the Carian Night's Sword from the chest they protect.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-wagon.png?h=40"},{"id":"3960","x":0.850896162,"y":0.484730728,"cat":"Key Items","group":"Items","title":"Stonesword Key - Crumbling Farum Azula","desc":"Key Item. Found on a corpse in a semi-open area in the back of the temple to the east. From the <strong>Dragon Temple</strong> site of grace, head inside the temple and turn right then down the stairs on the left. Take another right when you can and then another left into a long hallway. The said area is to the left at the end of this hallway and the corpse can be found in the crumbled edge past the pillars.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3962","x":0.846438283,"y":0.484883328,"cat":"Consumables","group":"Items","title":"Dragonwound Grease (B) - 2x Crumbling Farum Azula","desc":"Weapon Coating. A <strong>set of 2</strong> on a corpse near the center of the <strong>Dragon Temple</strong> which can only be accessed by circling around the back of the temple in the east. From the site of grace, head inside the archway and turn right then down the stairs on the left. Take another right and another left into a very long hallway. At the end of this hallway is a semi-outdoors area with pillars and a set of stairs on the left. Head up the stairs and follow the hallway to find a corpse holding the item on a ledge on the left in the crumbled section at the end.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4278","x":0.849428376,"y":0.485096971,"cat":"Key Items","group":"Items","title":"Smithing-Stone Miner's Bell Bearing [4]","desc":"Key Item. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Godskin+Duo' target=\"_blank\">Godskin Duo</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1762","x":0.263158763,"y":0.485127489,"cat":"Bosses","group":"Characters","title":"Crystalian (Ring Blade)","desc":"Optional Boss. Found at the bottom-most level of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Crystal+Tunnel' target=\"_blank\">Raya Lucaria Crystal Tunnel</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Smithing-Stone+Miner's+Bell+Bearing+(1)' target=\"_blank\">Smithing-Stone Miner's Bell Bearing (1)</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"3271","x":0.26147877,"y":0.485371652,"cat":"Weapons","group":"Equipment","title":"Digger's Staff","desc":"Drops from <a href='https://eldenring.wiki.fextralife.com/Digger' target=\"_blank\">Diggers</a> inside the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Crystal+Tunnel' target=\"_blank\">Raya Lucaria Crystal Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"5910","x":0.271916681,"y":0.485432692,"cat":"Talismans","group":"Equipment","title":"Stalwart Horn Charm","desc":"Can be found in Eastern Liurnia. Fast travel to Mausoleum Compound, head up the light incline to the left towards the cliff to the West. When you are at the cliff, look South for a hole in the wall. The talisman can be found on a corpse on a cliff through the hole.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1607","x":0.241828626,"y":0.485676854,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [3] B","desc":"Upgrade Material. Found on a corpse sitting on a chair by the shore.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4301","x":0.853490352,"y":0.485798935,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] H - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse at the edge of the cliffs southeast of the fountain plaza, past a gazebo and a tree. This is in an upper area accessed after ascending the <strong>Dragon Temple Lift</strong> northwest of the temple.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1763","x":0.260227515,"y":0.485921016,"cat":"Key Items","group":"Items","title":"Smithing-Stone Miner's Bell Bearing [1]","desc":"Key Item. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Crystalians' target=\"_blank\">Crystalian (Ring Blade)</a> Boss at the bottom-most level of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Crystal+Tunnel' target=\"_blank\">Raya Lucaria Crystal Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4302","x":0.845675284,"y":0.485921016,"cat":"Consumables","group":"Items","title":"Rune Arc - Crumbling Farum Azula (B)","desc":"Consumable. Found on a corpse near a <strong>Phantom Tree</strong> by some pillars south of the fountain plaza. This is in an upper area accessed after ascending the <strong>Dragon Temple Lift</strong> northwest of the temple.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4303","x":0.844363044,"y":0.486043097,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed (A) - Crumbling Farum Azula","desc":"Flask Upgrade Material. Found under a Phantom Tree by some pillars south of the fountain plaza. This is in an upper area accessed after ascending the <strong>Dragon Temple Lift</strong> northwest of the temple.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"4503","x":0.856968255,"y":0.486043097,"cat":"Bosses","group":"Characters","title":"Draconic Tree Sentinel","desc":"Non-Boss variant of the <strong>Draconic Tree Sentinel</strong> found at the end of the <strong>Great Bridge</strong>, guarding the final area of <a href='https://eldenring.wiki.fextralife.com/Crumbling+Farum+Azula' target=\"_blank\">Crumbling Farum Azula</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Malformed+Dragon+Set' target=\"_blank\">Malformed Dragon Set</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"8236","x":0.8394799,"y":0.486073619,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Crumbling Farum Azula (Dragon Temple)","desc":"Summoning Pool Effigy found next to the Dragon Temple site of grace in Crumbling Farum Azula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3951","x":0.834780903,"y":0.486592462,"cat":"Upgrade Materials","group":"Items","title":"Gravel Stone - 3x Crumbling Farum Azula (C)","desc":"Crafting Material. A <strong>set of 3</strong> found on a corpse in the roofed hallway in the heavily-ruined section leading to the <strong>Dragon Temple</strong>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8622","x":0.837556988,"y":0.486745065,"cat":"Consumables","group":"Items","title":"Golden Rune [12] B - Crumbling Farum Azula","desc":"Rune Consumable. After dropping down the pit into a narrow hallway in the heavily-ruined section leading to the <strong>Dragon Temple</strong>, ignore the first archway on the left and enter the second one instead. The rune is on a corpse at the edge of the crumbled section here.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3955","x":0.836336351,"y":0.486897664,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9] B - Crumbling Farum Azula","desc":"Upgrade Material. Found under a leaning pillar in the heavily-ruined section just before jumping towards the <strong>Dragon Temple</strong>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3956","x":0.840761737,"y":0.487141826,"cat":"Sites of Grace","group":"Locations","title":"Dragon Temple","desc":"Found after passing through the platform that is below the Ancient Dragon that can be seen from a distance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5709","x":0.848391828,"y":0.487202867,"cat":"Sites of Grace","group":"Locations","title":"Dragon Temple Transept","desc":"Site of Grace found to the southeast of the bottom level of the <strong>Dragon Temple</strong>, serving as an alternate route to the <a href='https://eldenring.wiki.fextralife.com/Godskin+Duo' target=\"_blank\">Godskin Duo</a> boss fight. From the <strong>Dragon Temple</strong> site of grace, turn around and face west then jump onto the crumbled ledges below to reach the bottom level. From here, head into the central archway and then turn right to find a hidden crypt with several sarcophagi. Go through the long crumbled hallway in the east to find the Transept site of grace in the corner of the next section.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8197","x":0.262974439,"y":0.487263907,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Marty: Raya Lucaria Crystal Tunnel","desc":"Summoning Pool Effigy found next to the Raya Lucaria Crystal Tunnel site of grace in Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"7652","x":0.858647994,"y":0.487294429,"cat":"Armor","group":"Equipment","title":"Malformed Dragon Set","desc":"Armor Set comprised of the <a href='https://eldenring.wiki.fextralife.com/Malformed+Dragon+Helm' target=\"_blank\">Malformed Dragon Helm</a>, <a href='https://eldenring.wiki.fextralife.com/Malformed+Dragon+Armor' target=\"_blank\">Malformed Dragon Armor</a>, <a href='https://eldenring.wiki.fextralife.com/Malformed+Dragon+Gauntlets' target=\"_blank\">Malformed Dragon Gauntlets</a> and the <a href='https://eldenring.wiki.fextralife.com/Malformed+Dragon+Greaves' target=\"_blank\">Malformed Dragon Greaves</a>. Dropped by the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Draconic+Tree+Sentinel'>Draconic Tree Sentinel</a> at the end of the <strong>Great Bridge</strong>, guarding the final area of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Crumbling+Farum+Azula'>Crumbling Farum Azula</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"8709","x":0.833194611,"y":0.487385988,"cat":"Consumables","group":"Items","title":"Golden Rune [12] F - Crumbling Farum Azula","desc":"Rune Consumable. Found on a corpse in the upper crumbled segment west of the <strong>Dragon Temple</strong>, right next to where <a href='https://eldenring.wiki.fextralife.com/Alexander' target=\"_blank\">Alexander</a> is standing if you followed his questline. To get up here, you need to ascend the <strong>Dragon Temple Lift</strong> northwest of the temple and then head south from the fountain plaza until you reach the Phantom Tree surrounded by pillars. From here, head west and use the top of another group of pillars to make your way to the start of the upper crumbled section.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1578","x":0.207834555,"y":0.487782753,"cat":"Sites of Grace","group":"Locations","title":"Sorcerer's Isle","desc":"Site of Grace found on the western edge of the isle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5916","x":0.835451432,"y":0.487996393,"cat":"Talismans","group":"Equipment","title":"Shard of Alexander","desc":"Drops from <a href='https://eldenring.wiki.fextralife.com/Iron+Fist+Alexander' target=\"_blank\">Iron Fist Alexander</a> after completing his questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"8810","x":0.217447572,"y":0.488057434,"cat":"Locations","group":"Locations","title":"3rd Turtle Testu's Rise","desc":"Third Spirit Turtle of Testu's Rise Puzzle. Found by going south and slightly east and finding a drop-down on the cliffs that doesn't go all the way to the shore.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit-turtle.png?h=40"},{"id":"6900","x":0.257542296,"y":0.488118474,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [3] - 4x Raya Lucaria Crystal Tunnel","desc":"Upgrade Material. A total of 4 can be found in the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Crystal+Tunnel' target=\"_blank\">Raya Lucaria Crystal Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"6530","x":0.843264324,"y":0.488179515,"cat":"Spirit Ashes","group":"Equipment","title":"Azula Beastman Ashes","desc":"Spirit Ashes. Found at the bottom level of the <strong>Dragon Temple</strong> accessed by turning around to face west from the Site of Grace and then jumping down the crumbled ledges below. From here, head into the central archway and then turn right to find a crypt with several sarcophagi. The ashes can be found on the sarcophagus in the back.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"1764","x":0.264866214,"y":0.488210037,"cat":"Spells","group":"Equipment","title":"Shatter Earth","desc":"Sorcery. Found on a corpse in the second-to-last level of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Crystal+Tunnel' target=\"_blank\">Raya Lucaria Crystal Tunnel</a>. Inside an opening in the north.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"3959","x":0.842135087,"y":0.488820442,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] C - Crumbling Farum Azula","desc":"Upgrade Material. From the <strong>Dragon Temple</strong> site of grace, take the path on the right to find the rune on a corpse hanging off the edge of the broken passage.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"7803","x":0.834415466,"y":0.48885096,"cat":"NPCs","group":"Characters","title":"Iron Fist Alexander (Eight Location)","desc":"Found in Crumbling Farum Azula. From the Dragon Temple Lift grace (can be accessed by using two Stonesword Keys), go past the plaza full of undead up the flight of stairs, turn right and you'll see two square bracket shaped archways. Jump on the archway on the left (closest to the dragon) to get over to the other side. Alexander can be found directly on the flat arena after crossing the crumbling tower. He will challenge you to a warrior's duel, and if you win, he will reward you with Alexander's Innards and Shard of Alexander. If you lose, he will continue letting you challenge him until you win.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"8702","x":0.84091429,"y":0.488881483,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9] C - Crumbling Farum Azula","desc":"Upgrade Material. Found in the southwest at the bottom level of the <strong>Dragon Temple</strong> accessed by turning around to face west from the Site of Grace and then jumping down the crumbled ledges below. From here, head into the central archway and then turn right to find a crypt with several sarcophagi. Go through the archway in the west to an outdoor area where you can find a corpse holding the stone between two pillars.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"5851","x":0.263553857,"y":0.489461365,"cat":"Sites of Grace","group":"Locations","title":"Raya Lucaria Crystal Tunnel","desc":"Site of Grace found inside the Raya Lucaria Crystal Tunnel, after taking the first lift down.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4660","x":0.86575799,"y":0.489491888,"cat":"Bosses","group":"Characters","title":"Beast Clergyman / Maliketh, The Black Blade","desc":"This Bossfight constitutes the final stage of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Crumbling+Farum+Azula'>Crumbling Farum Azula</a> zone. The fight starts against <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Beast+Clergyman'>Beast Clergyman</a> but it is revealed mid-fight whis was <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Maliketh,+The+Black+Blade'>Maliketh, The Black Blade</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5715","x":0.281740827,"y":0.489888649,"cat":"Shields","group":"Equipment","title":"Spiralhorn Shield","desc":"Found a corpse near Mausoleum Compound. NW of Ruined Labyrinth Site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-smallshield.png?h=40"},{"id":"1515","x":0.306793223,"y":0.490132811,"cat":"Key Items","group":"Items","title":"Stonesword Key - East Liurnia of the Lakes","desc":"Key Item. Found on a body sitting on a chair, in the open field, north from Ainsel River Well.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"5905","x":0.261601733,"y":0.490132811,"cat":"Locations","group":"Locations","title":"Raya Lucaria Crystal Tunnel","desc":"One of the vast networks of tunnels used prominently for the academy's crystal mining operation.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tunnel.png?h=40"},{"id":"8556","x":0.259033286,"y":0.490163333,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - 1x Raya Lucaria Crystal Tunnel","desc":"Consumable Item. Looted from a corpse under the ramparts leading to the first working elevator of Raya Lucaria Crystal Tunnel.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8621","x":0.835757836,"y":0.490163333,"cat":"Consumables","group":"Items","title":"Golden Rune [10] - Crumbling Farum Azula","desc":"Rune Consumable. Found by dropping into a pit in the heavily-ruined section leading to the <strong>Dragon Temple</strong>. This pit leads to a narrow hallway below. Turn around as you drop into the hallway to find a corpse sitting along the edge which contains the rune.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1611","x":0.256840524,"y":0.490193852,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [2] - 3x Raya Lucaria Crystal Tunnel","desc":"Upgrade Material. A total of 3 can be found in the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Crystal+Tunnel' target=\"_blank\">Raya Lucaria Crystal Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4304","x":0.841890931,"y":0.490376973,"cat":"Spells","group":"Equipment","title":"Golden Lightning Fortification","desc":"<a href='https://eldenring.wiki.fextralife.com/Incantations' target=\"_blank\">Incantation</a>. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> by the cliffs south of the fountain plaza. This is in an upper area accessed after ascending the <strong>Dragon Temple Lift</strong> northwest of the temple.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"1765","x":0.265354817,"y":0.490529576,"cat":"Weapons","group":"Equipment","title":"Crystal Knife","desc":"Dagger. Found in a chest inside the storage room in the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Crystal+Tunnel' target=\"_blank\">Raya Lucaria Crystal Tunnel</a> protected by Marionettes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"7653","x":0.864963014,"y":0.490834779,"cat":"Remembrances","group":"Items","title":"Remembrance of the Black Blade","desc":"Key Item. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Maliketh,+The+Black+Blade'>Maliketh, the Black Blade</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6066","x":0.83264451,"y":0.49095686,"cat":"Upgrade Materials","group":"Items","title":"Great Grave Glovewort - Crumbling Farum Azula (B)","desc":"Upgrade Material. After dropping down the pit into a narrow hallway in the heavily-ruined section leading to the <strong>Dragon Temple</strong>, head into the first archway on the left and up the stairs heading northwest to a ruined balcony where you can navigate across a series of floating debris to reach a second balcony with a ladder. Head up the ladder to reach a hidden tomb with the glovewort sitting on the main sarcophagus in the back.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"8620","x":0.834506519,"y":0.491048419,"cat":"Consumables","group":"Items","title":"Golden Arrow - 14x Crumbling Farum Azula","desc":"Bow Ammunition. A <strong>set of 14</strong> found on a corpse at the edge of a floating platform adjoined to a long chunk of debris as you traverse the heavily-ruined section leading to the <strong>Dragon Temple</strong>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8807","x":0.190048872,"y":0.491139981,"cat":"Consumables","group":"Items","title":"Throwing Dagger - 6x Liurnia Western Lake Shore","desc":"Consumable Throwable Item. Six can be looted off a corpse by a cart being protected by several soldiers on the shore of the lake.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6533","x":0.26785656,"y":0.491262062,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found on <a href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes' target=\"_blank\">Liurnia of the Lakes</a> around forested areas.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8710","x":0.830782795,"y":0.491323103,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] D - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse in the second large segment of the upper crumbled section west of the <strong>Dragon Temple</strong>. To get up here, you need to ascend the <strong>Dragon Temple Lift</strong> northwest of the temple and then head south from the fountain plaza until you reach the Phantom Tree surrounded by pillars. From here, head west and use the top of another group of pillars to make your way to the start of the upper crumbled section.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4351","x":0.842531849,"y":0.491994548,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] G - Crumbling Farum Azula","desc":"Upgrade Material. One found on a corpse in front of a sleeping dragon, far south of the fountain plaza. This is in an upper area accessed after ascending the <strong>Dragon Temple Lift</strong> northwest of the temple.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4102","x":0.257389894,"y":0.49245235,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [1] - Raya Lucaria Crystal Tunnel","desc":"Upgrade Material. One can be found in the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Crystal+Tunnel' target=\"_blank\">Raya Lucaria Crystal Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"1594","x":0.287753193,"y":0.492543913,"cat":"Sites of Grace","group":"Locations","title":"Ruined Labyrinth","desc":"Site of Grace found amongst the ruins and broken statues in the area of unmarked \"Uld Palace Ruins\"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3455","x":0.264018681,"y":0.492805662,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] - 3x Raya Lucaria Crystal Tunnel","desc":"Upgrade Material. A total of 3 can be found in the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Crystal+Tunnel' target=\"_blank\">Raya Lucaria Crystal Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5711","x":0.848576648,"y":0.492910156,"cat":"Bosses","group":"Characters","title":"Dragonlord Placidusax","desc":"Optional Boss found near the tempest. Drops the <a href='https://eldenring.wiki.fextralife.com/Remembrance+of+the+Dragonlord' target=\"_blank\">Remembrance of the Dragonlord</a> upon defeat. To reach this boss: <ol> <li>From the <strong>Beside the Great Bridge</strong> site of grace, take the lift back down and head back towards the entrance of the building.</li> <li>From the entrance, head for cliffs directly west and look down at the edge for a series of ledges you can drop down onto.</li> <li>Follow the floating platforms towards the tempest where you will find a large chunk of building debris with decorative frames containing skeletal remains. Look for the empty frame which will have a prompt for you to <em>Lie Down</em>. Doing so will teleport you to the boss' arena.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3947","x":0.834384888,"y":0.493215359,"cat":"Consumables","group":"Items","title":"Golden Rune [9] B - Crumbling Farum Azula","desc":"Rune Consumable. Found on a corpse behind a stone column after dropping down the floating platforms north of the <strong>Tempest-Facing Balcony</strong>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1591","x":0.291598032,"y":0.493428999,"cat":"Consumables","group":"Items","title":"Frenzyflame Stone","desc":"Frenzyflame Stone is a consumable that uses FP to continuously heal chaos followers","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7651","x":0.846528984,"y":0.493795241,"cat":"Remembrances","group":"Items","title":"Remembrance of the Dragonlord","desc":"Key Item. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Dragonlord+Placidusax'>Dragonlord Placidusax</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3948","x":0.835636201,"y":0.493917322,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [7] A - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse on a chunk of floating debris, on the eastern edge of the heavily-ruined section between the <strong>Tempest-Facing Balcony</strong> and the <strong>Dragon Temple</strong>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3502","x":0.259099615,"y":0.493978363,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] - 8x Raya Lucaria Crystal Tunnel","desc":"Upgrade Material. A total of 8 can be found in the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Crystal+Tunnel' target=\"_blank\">Raya Lucaria Crystal Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3503","x":0.261388916,"y":0.493978363,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - 5x Raya Lucaria Crystal Tunnel","desc":"Upgrade Material. A total of 5 can be found in the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Crystal+Tunnel' target=\"_blank\">Raya Lucaria Crystal Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4595","x":0.253421342,"y":0.494375128,"cat":"Locations","group":"Locations","title":"Walking Mausoleum (Liurnia of the Lakes Central)","desc":"Use the spirit spring west from the mausoleum (hidden on the lower area of the cliffs of Bellum Church) and jump onto the mausoleum when it's close to the northern cliffside of the lake.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-walking-mausoleum.png?h=40"},{"id":"8711","x":0.833316687,"y":0.494375128,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] A - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse hanging off a ledge in the upper crumbled segment west of the <strong>Dragon Temple</strong>. To get up here, you will first need to ascend the <strong>Dragon Temple Lift</strong> northwest of the temple and then head south from the fountain plaza until you reach the Phantom Tree surrounded by pillars. From here, head west and use the top of another group of pillars to make your way to the start of the upper crumbled section. You will need to traverse the massive floating chunks of debris, heading further west. Once you get to the second large chunk, look in the northwest section of it for a series of makeshift stone bridges that will lead you to a gazebo-like structure. Head slightly north from the gazebo to find the corpse that holds the stone, hanging off the right edge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"5708","x":0.849826266,"y":0.494405646,"cat":"Sites of Grace","group":"Locations","title":"Dragonlord Placidusax","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5854","x":0.872772598,"y":0.494497209,"cat":"Sites of Grace","group":"Locations","title":"Maliketh, the Black Blade","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8712","x":0.834476217,"y":0.49483293,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] I - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse hanging off a ledge in the upper crumbled segment west of the <strong>Dragon Temple</strong>. To get up here, you will first need to ascend the <strong>Dragon Temple Lift</strong> northwest of the temple and then head south from the fountain plaza until you reach the Phantom Tree surrounded by pillars. From here, head west and use the top of another group of pillars to make your way to the start of the upper crumbled section. You will need to traverse the massive floating chunks of debris, heading further west. Once you get to the second large chunk, look in the northwest section of it for a series of makeshift stone bridges that will lead you to a gazebo-like structure. Head slightly north from the gazebo to find a corpse holding a <a href='https://eldenring.wiki.fextralife.com/Somber+Smithing+Stone+(8)' target=\"_blank\">Somber Smithing Stone [8]</a> and then drop off the edge onto a small floating platform below to pick up the <a href='https://eldenring.wiki.fextralife.com/Smithing+Stone+(8)' target=\"_blank\">Smithing Stone [8]</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2058","x":0.18788055,"y":0.494863452,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [3] - Western Liurnia of the Lakes","desc":"Upgrade Material. Found on a corpse sitting on a chair overlooking the cliffs. Beware of enemies that spawn behind you.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"7064","x":0.174941516,"y":0.494924493,"cat":"Consumables","group":"Items","title":"Cuckoo Glintstone - 10x Eastern Liurnia of the Lakes","desc":"COnsumable Item. Can be found inside a chest in an enemy camp.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3686","x":0.854004566,"y":0.496328424,"cat":"Locations","group":"Locations","title":"Crumbling Farum Azula","desc":"Reached by talking to Melina by the Site of Grace at the Forge of the Giants in Mountaintops of the Giants.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crumbling-faromazula.png?h=40"},{"id":"5782","x":0.834473616,"y":0.496450505,"cat":"Key Items","group":"Items","title":"Ancient Dragon Apostle's Cookbook [4]","desc":"Cookbook found in a gazebo-like structure high above in the heavily-crumbled section in the northwest. To get up here, you will first need to ascend the <strong>Dragon Temple Lift</strong> northwest of the temple and then head south from the fountain plaza until you reach the Phantom Tree surrounded by pillars. From here, head west and use the top of another group of pillars to make your way to the start of the upper crumbled section. You will need to traverse the massive floating chunks of debris, heading further west. Once you get to the second large chunk, look in the northwest section of it for a series of makeshift stone bridges that will lead you to the gazebo where the cookbook can be looted off a corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"2056","x":0.172744079,"y":0.496572586,"cat":"Consumables","group":"Items","title":"Rune Arc - Liurnia West Encampment","desc":"Consumable Item. Found on a corpse inside a large enemy outpost.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3919","x":0.837617169,"y":0.496633627,"cat":"Key Items","group":"Items","title":"Somberstone Miner's Bell Bearing [4]","desc":"Key Item. Found on a corpse at the edge of the cliffs by the <strong>Tempest-Facing Balcony</strong>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1975","x":0.184554857,"y":0.496755708,"cat":"Key Items","group":"Items","title":"Imbued Sword Key - The Four Belfries","desc":"Key Item used to activate a Waygate at <a href='https://eldenring.wiki.fextralife.com/The+Four+Belfries' target=\"_blank\">The Four Belfries</a>. Found in a chest at the very top of the hill, at the fourth belfry tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8239","x":0.836398458,"y":0.497152469,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Crumbling Farum Azula (Tempest-Facing Balcony)","desc":"Summoning Pool Effigy found just on a ledge after dropping down from the Tempest-Facing Balcony site of grace in Crumbling Farum Azula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"7002","x":0.197825901,"y":0.497274551,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - 2x Liurna's West Sarcophagi","desc":"Two (<strong>2</strong>) found within the sarcophagi in <em>West Liurnia of the Lakes</em>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8617","x":0.831271629,"y":0.497396631,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] F - Crumbling Farum Azula","desc":"Found on a corpse at the edge of the large stone platform behind the large building next to the <strong>Crumbling Beast Grave Depths</strong> site of grace. To reach this platform, head into the terrace southwest of the building and take the lift to the cliffs below. Navigate the floating debris north of the lift. Beware as a <a href='https://eldenring.wiki.fextralife.com/Farum+Azula+Dragon' target=\"_blank\">Farum Azula Dragon</a> will swoop in and ambush you from behind as you pick up the item.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"7001","x":0.199779521,"y":0.497488194,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - 3x Liurna's West Sarcophagi","desc":"Three (<strong>3</strong>) found within the sarcophagi in <em>West Liurnia of the Lakes</em>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5420","x":0.230294553,"y":0.497640793,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Shield Bash","desc":"Ash of War. Dropped by a Teardrop Scarab under a bridge very close to East Gate Bridge Trestle site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"7003","x":0.201885042,"y":0.498098599,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - Liurna's West Sarcophagi","desc":"Found within the sarcophagi in <em>West Liurnia of the Lakes</em>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"951","x":0.276828131,"y":0.49822068,"cat":"Crafting Materials","group":"Items","title":"Grave Violet - 1x Liurnia East Graveyard","desc":"Crafting Material. One can be found by a tombstone north from the Chuch of Vows. Beware of an undead ambush.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3268","x":0.249640319,"y":0.49843432,"cat":"Shields","group":"Equipment","title":"Eclipse Crest Greatshield","desc":"Drops from Mausoleum Knights wielding it in Liurnia of the Lakes (chance to drop, not guaranteed)","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"3918","x":0.839357936,"y":0.498831085,"cat":"Sites of Grace","group":"Locations","title":"Tempest-Facing Balcony","desc":"The main door of the hall leaves to the balcony that faces the tornados in the center, and the site of grace is right there in the middle of the balcony.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6966","x":0.198330253,"y":0.499166806,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - 5x Liurnia's West Sarcophagi","desc":"Five (<strong>5</strong>) found within the sarcophagi in <em>West Liurnia of the Lakes</em>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1356","x":0.189161848,"y":0.499197328,"cat":"Waygates","group":"Locations","title":"Chapel of Anticipation Waygate","desc":"A Teleporter Waygate at The Four Belfries that transports you to the <a href='https://eldenring.wiki.fextralife.com/Chapel+of+Anticipation' target=\"_blank\">Chapel of Anticipation</a>. The same location you begin the game in. Requires an <a href='https://eldenring.wiki.fextralife.com/Imbued+Sword+Key' target=\"_blank\">Imbued Sword Key</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"26852","x":0.219332248,"y":0.499288889,"cat":"Crafting Materials","group":"Items","title":"Smithing Stone [2]","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8616","x":0.838047048,"y":0.499533049,"cat":"Upgrade Materials","group":"Items","title":"Great Grave Glovewort - Crumbling Farum Azula (A)","desc":"Spirit Ash Upgrade Material. Found in a recess in the northeastern-most wall of the upper level of the large building next to the <strong>Crumbling Beast Grave Depths</strong>. To reach this upper area, head out of the balcony of the room next to the site of grace and jump up onto the red roof right next to it. You can head into the building's upper level from here.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"6969","x":0.200634072,"y":0.499624612,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - 2x Liurnia's West Sarcophagi","desc":"Two (<strong>2</strong>) found within the sarcophagi in <em>West Liurnia of the Lakes</em>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1974","x":0.183484809,"y":0.499716171,"cat":"Locations","group":"Locations","title":"The Four Belfries","desc":"A hub for transporter waygates that lead to various locations. Each waygate requires an <a href='https://eldenring.wiki.fextralife.com/Imbued+Sword+Key' target=\"_blank\">Imbued Sword Key</a> to activate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fourbelfries.png?h=40"},{"id":"3915","x":0.833468905,"y":0.500448657,"cat":"Consumables","group":"Items","title":"Golden Rune [12] A - Crumbling Farum Azula","desc":"Rune Consumable. Found on a corpse hanging off a crumbled ledge outside of the large building next to the <strong>Crumbling Beast Grave Depths</strong> site of grace. This can be reached through an exit in the northwest section of the building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3917","x":0.836732089,"y":0.500723341,"cat":"Key Items","group":"Items","title":"Ancient Dragon Prayerbook","desc":"Incantation Tome. Found at ground level in the middle of the large building next to the <strong>Crumbling Beast Grave Depths</strong> site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tome.png?h=40"},{"id":"2053","x":0.178296729,"y":0.500967503,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] - Western Liurnia Enemy Camp","desc":"Upgrade material. Looted from a chest in the higher area of the enemy encampment, protected by a Cuckoo Knight, some soldiers and a Mad Pumpkin Head.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8615","x":0.835269737,"y":0.501364264,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] B - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse hanging off a crumbled section of the upper floor of the large building northwest from the <strong>Crumbling Beast Grave Depths</strong> site of grace. To reach this upper level, head out of the balcony of the next room from the site of grace and jump up onto the red roof right next to it. You can enter the building's upper level from here.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1355","x":0.181745436,"y":0.501547386,"cat":"Sites of Grace","group":"Locations","title":"The Four Belfries","desc":"Site of Grace by The Four Belfries.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8614","x":0.83414059,"y":0.502157791,"cat":"Crafting Materials","group":"Items","title":"Gravel Stone - 3x Crumbling Farum Azula (B)","desc":"Crafting Material. A <strong>set of 3</strong> found on a sarcophagus in the upper level of the large building. To reach this area, head out of the balcony of the room after the <strong>Crumbling Beast Grave Depths</strong> site of grace and jump up onto the roof right next to it. You can enter the building's upper level from here.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8806","x":0.177929722,"y":0.502157791,"cat":"Crafting Materials","group":"Items","title":"Albinauric Bloodclot - 3x Liurnia West Enemy Camp","desc":"Crafting Material. Three can be looted from a chest in the higher area of the enemy encampment, protected by a Cuckoo Knight, some soldiers and a Mad Pumpkin Head.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2001","x":0.184736075,"y":0.502554556,"cat":"Waygates","group":"Locations","title":"Waygate to Underground Area","desc":"<p>A Teleporter Waygate at <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/The+Four+Belfries' target=\"\">The Four Belfries</a> that transports you to section of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Nokron,+Eternal+City' target=\"\">Nokron, Eternal City</a>/ <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Siofra+River' target=\"\">Siofra River</a>(Underground area that is inaccessable without a waygate to access). Requires an <a href='https://eldenring.wiki.fextralife.com/Imbued+Sword+Key' target=\"_blank\" rel=\"noopener noreferrer\">Imbued Sword Key</a><a href='https://eldenring.wiki.fextralife.com/Nokron,+Eternal+City' target=\"_blank\" rel=\"noopener noreferrer\">. </a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"4551","x":0.227639337,"y":0.502798718,"cat":"Sites of Grace","group":"Locations","title":"East Gate Bridge Trestle","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8288","x":0.837330028,"y":0.503348083,"cat":"Shields","group":"Equipment","title":"Beastman's Jar-Shield","desc":"Found in the room next to the site of the grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"3920","x":0.831546521,"y":0.503927965,"cat":"Consumables","group":"Items","title":"Hero's Rune [2] - Crumbling Farum Azula","desc":"Rune Consumable. Found on a corpse sitting by the wall next to the staircase to the terrace southwest of the large building next to the <strong>Crumbling Beast Grave Depths</strong> site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5967","x":0.226266178,"y":0.504599411,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Liurnia of the Lakes","desc":"Can be found north of the Main Academy Gate site of grace, on the bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"3762","x":0.83835105,"y":0.504752014,"cat":"Sites of Grace","group":"Locations","title":"Crumbling Beast Grave Depths","desc":"This Site of Grace is right next to the Farum Azula Dragon that you encounter in the bridge, the dragon can be easily skipped to reach this site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"952","x":0.272095806,"y":0.504813055,"cat":"Consumables","group":"Items","title":"Golden Rune [1] B","desc":"Found on the ground East of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/church+of+vows'>Church of Vows</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3914","x":0.835605458,"y":0.505087735,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] A - Crumbling Farum Azula","desc":"Upgrade Material. Found on a sarcophagus closest to the balcony in the next room after the <strong>Crumbling Beast Grave Depths</strong> site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8235","x":0.837161972,"y":0.505362419,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Crumbling Farum Azula (Crumbling Beast Grave Depths)","desc":"Summoning Pool Effigy found at the exit of the room after the Crumbling Beast Grave Depths site of grace in Crumbling Farum Azula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3757","x":0.844334368,"y":0.505576059,"cat":"Consumables","group":"Items","title":"Dragonwound Grease (A) - Crumbling Farum Azula","desc":"Weapon Coating. On a corpse hanging off the edge of the curved platform.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1976","x":0.186993494,"y":0.506674789,"cat":"Waygates","group":"Locations","title":"Crumbling Farum Azula Waygate","desc":"A Teleporter Waygate that transports you to the <a href='https://eldenring.wiki.fextralife.com/Crumbling+Farum+Azula' target=\"_blank\">Crumbling Farum Azula</a>. Requires an <a href='https://eldenring.wiki.fextralife.com/Imbued+Sword+Key' target=\"_blank\">Imbued Sword Key</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"8613","x":0.840885403,"y":0.506796869,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] C - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse under a roofed section on the left as you reach the end of the curved platform. Directly opposite the <strong>Crumbling Beast Grave Depths</strong> site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3755","x":0.846501066,"y":0.507315716,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] B - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse along the curved bridge/platform. Before reaching it, a <a href='https://eldenring.wiki.fextralife.com/Farum+Azula+Dragon' target=\"_blank\">Farum Azula Dragon</a> will swoop in and attack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8612","x":0.84821018,"y":0.507559878,"cat":"Upgrade Materials","group":"Items","title":"Ancient Dragon Smithing Stone (A) - Crumbling Farum Azula","desc":"Upgrade Material. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Farum+Azula+Dragon' target=\"_blank\">Farum Azula Dragon</a> that swoops in to attack as you make your way along the curved platform.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3751","x":0.860296284,"y":0.507651436,"cat":"Consumables","group":"Items","title":"Lightningproof Dried Liver - Crumbling Farum Azula","desc":"Consumable. On a corpse in front of a hole in the wall on the right, guarded by <a href='https://eldenring.wiki.fextralife.com/Azula+Beastman' target=\"_blank\">Beastmen</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3753","x":0.850468653,"y":0.508017679,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] A - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse along the middle of the curved bridge/platform.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3688","x":0.869574337,"y":0.508200801,"cat":"Consumables","group":"Items","title":"Golden Rune [9] A - Crumbling Farum Azula","desc":"Rune Consumable. Found on a corpse on some floating debris to the right and below the walkway, leading to the balcony.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5855","x":0.857090277,"y":0.508261841,"cat":"Sites of Grace","group":"Locations","title":"Crumbling Beast Grave","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5604","x":0.169997038,"y":0.508322882,"cat":"Shields","group":"Equipment","title":"Jellyfish Shield","desc":"On a dead body surrounded by four Jellyfish directly north of the Foot of the Four Belfries Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"1456","x":0.306427255,"y":0.508444963,"cat":"Locations","group":"Locations","title":"Ainsel River Well","desc":"A small structure housing a lift that takes you down to the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Ainsel+River'>Ainsel River</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-well.png?h=40"},{"id":"3944","x":0.835361297,"y":0.508597566,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9] A - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse under a tree by the cliffside south of the large building next to the <strong>Crumbling Beast Grave Depths</strong> site of grace. You can reach this area by taking the lift in the terrace southwest of the building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3701","x":0.865326643,"y":0.508658607,"cat":"Crafting Materials","group":"Items","title":"Old Fang - 3x Crumbling Farum Azula (A)","desc":"Crafting Material. <strong>3</strong> found on a corpse in a room where the <a href='https://eldenring.wiki.fextralife.com/Azula+Beastman' target=\"_blank\">Beastmen</a> are roaming around.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8619","x":0.838321424,"y":0.508750165,"cat":"Crafting Materials","group":"Items","title":"Fulgurbloom (A) - 4x Crumbling Farum Azula","desc":"Crafting Material. A <strong>set of 4</strong> can be found on a corpse by a tree behind the western-most broken bridge along the southern cliffs. This area can be reached by taking the lift in the terrace southwest of the large building next to the <strong>Crumbling Beast Grave Depths</strong> site of grace and then navigating the slopes and pathways by the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7063","x":0.171322859,"y":0.508841728,"cat":"Consumables","group":"Items","title":"Blood Grease - 3x Eastern Liurnia of the Lakes","desc":"Can be found alongside the road, on a corpse. Near the cart with the <a href='https://eldenring.wiki.fextralife.com/Jellyfish+Shield' target=\"_blank\"> Jellyfish Shield</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8234","x":0.858800591,"y":0.508994327,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Crumbling Farum Azula (Crumbling Beast Grave)","desc":"Summoning Pool Effigy found just outside the room with the Crumbling Beast Grave site of grace in Crumbling Farum Azula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4753","x":0.269810934,"y":0.51024566,"cat":"Key Items","group":"Items","title":"Meat Peddler's Bell Bearing","desc":"Key Item. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Bell+Bearing+Hunter' target=\"_blank\">Bell Bearing Hunter</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Vows' target=\"_blank\">Church of Vows</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3687","x":0.868261765,"y":0.5103067,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] A - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse sitting at the end of the walkway that you begin on when first visiting the region.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3941","x":0.835208696,"y":0.511100227,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] D - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse sitting at the edge of the broken bridge atop the arch ruins, guarded by a <a href='https://eldenring.wiki.fextralife.com/Lesser+Wormface' target=_blank\">Lesser Wormface</a>. This area can be reached by taking the lift in the terrace southwest of the large building next to the <strong>Crumbling Beast Grave Depths</strong> site of grace and then navigating the slopes and pathways by the cliffs. There is a ladder that you can climb on the back side of the arch to get on top.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4752","x":0.268192864,"y":0.51169842,"cat":"Bosses","group":"Characters","title":"Bell Bearing Hunter (Church of Vows)","desc":"Field Boss. Found at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Vows' target=\"_blank\">Church of Vows</a> during night time. Alternatively, you can spawn him by advancing to night, resting at the grace once more and then advancing to morning. Drops the <a href='https://eldenring.wiki.fextralife.com/Meat+Peddler's+Bell+Bearing' target=\"_blank\">Meat Peddler's Bell Bearing</a. upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6130","x":0.220041051,"y":0.511924272,"cat":"NPCs","group":"Characters","title":"Bloody Finger Hunter Yura (Third Location)","desc":"He can be found requesting aid from the player in the form of a Red Summon Sign on the bridge north of the Main Gate Grace. Walk past the magic seal to find. Enter his world and defeat Bloody Finger Ravenmount Assassin. Afterward, talk to Yura who will be standing against the railing near to where his summon sign was","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3927","x":0.851350929,"y":0.512198956,"cat":"Crafting Materials","group":"Items","title":"Gravel Stone - 5x Crumbling Farum Azula (A)","desc":"Crafting Material. A <strong>set of 5</strong> can be found on a corpse far to the east of the southern cliffs. You can reach this area by taking the lift in the terrace southwest of the large building next to the <strong>Crumbling Beast Grave Depths</strong> site of grace and then navigating the slopes and pathways by the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1465","x":0.29657278,"y":0.51290092,"cat":"Consumables","group":"Items","title":"Immunizing White Cured Meat","desc":"Temporarily boosts immunity.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8164","x":0.218728854,"y":0.51296196,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - 1x Yura Questline Reward","desc":"Upgrade Material. Obtained as a reward by talking to <a href='https://eldenring.wiki.fextralife.com/Bloody+Finger+Hunter+Yura' target=\"_blank\">Bloody Finger Hunter Yura</a> at this location after assisting him in defeating Bloody Finger Ravenmount Assassin via a red summon sign.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"830","x":0.272403593,"y":0.513541847,"cat":"Sites of Grace","group":"Locations","title":"Church of Vows","desc":"Church of Vows Site of Grace. Located at <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Church+of+Vows'>Church of Vows</a> prior to the main entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5936","x":0.219978823,"y":0.51384705,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Raptor of the Mists","desc":"Questline Reward: Found after aiding <a href='https://eldenring.wiki.fextralife.com/Bloody+Finger+Hunter+Yura' target=\"_blank\">Bloody Finger Hunter Yura</a> in defeating his target in Raya Lucaria","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"811","x":0.266422935,"y":0.513877568,"cat":"Key Items","group":"Items","title":"Golden Tailoring Tools","desc":"Tools made of gold brought with the red-haired Radagon when he married into the Carian line. Located inside a chest at the right of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Church+of+Vows'>Church of Vows'</a> main entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"801","x":0.269016833,"y":0.514152252,"cat":"Locations","group":"Locations","title":"Church of Vows","desc":"Church of Vows is a forgotten church guarded by <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Miriel,+Pastor+of+Vows'>Miriel, Pastor of Vows</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"8830","x":0.217507846,"y":0.514854216,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Raya Lucaria Main Academy Gate","desc":"<p>Summoning Pool Effigy found at the north <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"\">Raya Lucaria Academy</a> gate. Activate this effigy to send your summon sign to this summoning pool.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3940","x":0.840824578,"y":0.51506786,"cat":"Consumables","group":"Items","title":"Rejuvenating Boluses - Crumbling Farum Azula","desc":"Consumable. Found on a corpse in the center of the shallow pond infested with <a href='https://eldenring.wiki.fextralife.com/Lesser+Wormface' target=\"_blank\">Lesser Wormfaces</a>. This area can be reached by taking the lift in the terrace southwest of the large building next to the <strong>Crumbling Beast Grave Depths</strong> site of grace and then navigating the slopes and pathways by the southern cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"810","x":0.266301144,"y":0.515495143,"cat":"Key Items","group":"Items","title":"Gold Sewing Needle","desc":"Sewing needle made of gold. Unique item made to alter demigod attire. Located inside a chest at the right of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Church+of+Vows'>Church of Vows'</a> main entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"804","x":0.270786234,"y":0.516075027,"cat":"NPCs","group":"Characters","title":"Miriel, Pastor of Vows","desc":"Miriel is the steward of <a class=\"wikilink\" target=\"blank\" href='https://eldenring.wiki.fextralife.com/Church+of+Vows'>Church of Vows</a>, and will accept Scrolls and Tomes and teach lore, Incantations and Sorceries.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"14252","x":0.841112648,"y":0.516098224,"cat":"Bosses","group":"Characters","title":"Wormface - Crumbling Farum Azula","desc":"<p> Boss. Located in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Crumbling+Farum+Azula' target=\"blank\">Crumbling Farum Azula</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6252","x":0.217446509,"y":0.516136067,"cat":"NPC Invaders","group":"Characters","title":"Bloody Finger Ravenmount Assassin","desc":"Technically you are the invader of an NPC called \"Bloody Finger Ravenmount Assassin\".","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"3937","x":0.842380877,"y":0.51634971,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] E - Crumbling Farum Azula","desc":"Upgrade Material. Found on a corpse on the eastern edge of the shallow pond infested by <a href='https://eldenring.wiki.fextralife.com/Lesser+Wormface' target=\"_blank\">Lesser Wormfaces</a>. You can reach this area by taking the lift in the terrace southwest of the large building next to the <strong>Crumbling Beast Grave Depths</strong> site of grace and then navigating the slopes and pathways by the southern cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3935","x":0.841065919,"y":0.518852371,"cat":"Key Items","group":"Items","title":"Glovewort Picker's Bell Bearing [3]","desc":"Key Item. Found inside a gazebo by the shallow pond infested by <a href='https://eldenring.wiki.fextralife.com/Lesser+Wormface' target=\"_blank\">Lesser Wormfaces</a>. You can reach this area by taking the lift in the terrace southwest of the large building next to the <strong>Crumbling Beast Grave Depths</strong> site of grace and then navigating the slopes and pathways by the southern cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"950","x":0.216348457,"y":0.51888289,"cat":"Sites of Grace","group":"Locations","title":"Main Academy Gate","desc":"Site of grace at the main entrance to <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/raya+lucaria+academy'>Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1514","x":0.301271593,"y":0.520073181,"cat":"Sites of Grace","group":"Locations","title":"Eastern Tableland","desc":"Site of Grace found in the middle of a rocky section of the road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1357","x":0.169295036,"y":0.520592024,"cat":"Sites of Grace","group":"Locations","title":"Foot of the Four Belfries","desc":"Site of Grace found before ascending the mountain with the Four Belfries.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1139","x":0.201335187,"y":0.522118036,"cat":"Sites of Grace","group":"Locations","title":"Crystalline Woods","desc":"Site of Grace found by the Crystalline Woods.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2973","x":0.217965574,"y":0.522514802,"cat":"Key Items","group":"Items","title":"Dark Moon Ring","desc":"Quest Item. Found in a locked chest next to the Raya Lucaria Grand Library Site of Grace. Unlocked using the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Discarded+Palace+Key'>Discarded Palace Key</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"943","x":0.20356755,"y":0.52254532,"cat":"Consumables","group":"Items","title":"Cuckoo Glintstone - Academy Crystal Cave","desc":"Inside the <a href='https://eldenring.wiki.fextralife.com/Academy+Crystal+Cave' target=\"_blank\">Academy Crystal Cave</a>. On the room full of Sages, turn to the right. It is against the wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5430","x":0.611721762,"y":0.522881045,"cat":"Locations","group":"Locations","title":"Isolated Divine Tower","desc":"Tower to activate Malenia's Great Rune","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-divinetower.png?h=40"},{"id":"8907","x":0.221340773,"y":0.522966482,"cat":"NPCs","group":"Characters","title":"Rennala, Queen of the Full Moon (NPC)","desc":"Rennala becomes a merchant in her boss room after defeating her. She provides rebirthing services, allowing you to respec your character.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"793","x":0.219571711,"y":0.523033644,"cat":"Bosses","group":"Characters","title":"Rennala, Queen of the Full Moon","desc":"One of the demigods. She can be fought at the top of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy'>Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mainboss.png?h=40"},{"id":"5846","x":0.214883694,"y":0.523735612,"cat":"Sites of Grace","group":"Locations","title":"Raya Lucaria Grand Library","desc":"Site of Grace at the Main Library of the Raya Lucaria Academy","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6526","x":0.217752234,"y":0.523735612,"cat":"NPCs","group":"Characters","title":"Witch-Hunter Jerren (Third Location)","desc":"<p>Witch-Hunter Jerren can be found here at the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"\">Raya Lucaria Academy</a> Library after progressing towards the end of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sorceress+Sellen' target=\"\">Sorceress Sellen</a> questline. Choose to side with Sellen to face him in combat in this location, or choose to side with Jerren to face Sellen instead. He will also be here provide your reward should you choose to side with him.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"8803","x":0.183149005,"y":0.524162895,"cat":"Crafting Materials","group":"Items","title":"Strip of White Flesh - Liurnia West","desc":"Crafting Material. One can be looted off a body surrounded by giant lobsters.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2296","x":0.220864965,"y":0.524193414,"cat":"Remembrances","group":"Items","title":"Remembrance of the Full Moon Queen","desc":"Remembrance of Rennala, Queen of the Moon. Acquired as a reward for defeating the supreme sorceress. To be given to <a href='https://eldenring.wiki.fextralife.com/Enia' target=\"_blank\">Enia</a> to draw out the power within.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8196","x":0.202251279,"y":0.524346017,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Academy Crystal Cave","desc":"Summoning Pool Effigy found just past the Academy Crystal Cave site of grace in Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"945","x":0.199722039,"y":0.524437576,"cat":"Consumables","group":"Items","title":"Rune Arc - Academy Crystal Cave","desc":"Found inside the <a href=\"Academy+Crystal+Cave\" target=\"_blank\">Academy Crystal Cave</a>. Enter the room protected by a Great Sage, open the chest to find the Rune Arc.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2295","x":0.21909481,"y":0.524498616,"cat":"Key Items","group":"Items","title":"Great Rune of the Unborn","desc":"<a href='https://eldenring.wiki.fextralife.com/Great+Runes' target=\"_blank\">Great Rune</a> of Rennala, Queen of the Moon. Acquired as a reward for defeating the supreme sorceress.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8908","x":0.225343369,"y":0.52502967,"cat":"NPCs","group":"Characters","title":"Sorceress Sellen (Fourth Location)","desc":"Summon signs to either help or betray Sorceress Sellen at the end of her quest can be found right by the entrance to the <a target=\"_blank\" Raya Lucaria Academy</a> Library. She will also be here to provide your reward should you choose to side with her.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6611","x":0.227182587,"y":0.525353183,"cat":"Key Items","group":"Items","title":"Stonesword Key - Raya Lucaria Academy (C)","desc":"Held by a sitting corpse outside the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/raya+lucaria+academy'>Academy</a>, beneath the bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8292","x":0.217233435,"y":0.525566827,"cat":"Armor","group":"Equipment","title":"Eccentric Set","desc":"Obtained as drop for defeating <a href='https://eldenring.wiki.fextralife.com/'>Witch-Hunter Jerren</a> as part of Sorceress Sellen Questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"6537","x":0.224007174,"y":0.525627867,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily - Raya Lucaria Academy","desc":"You can find x3 Miquella's Lily near the a fountain, in the center of the academy's courtyard, guarded by five lake humanoid creatures.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5429","x":0.611509789,"y":0.52599411,"cat":"Sites of Grace","group":"Locations","title":"Isolated Divine Tower","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6205","x":0.205483599,"y":0.526116191,"cat":"Weapons","group":"Equipment","title":"Crystal Staff","desc":"Crystal Staff can be found in <a href='https://eldenring.wiki.fextralife.com/Academy+Crystal+Cave' target=\"_blank\">Academy Crystal Cave</a>. It's in a room guarded by a sorcerer behind a fog wall, located right before the boss gate. The path to the chest containing the staff is through an illusory rock wall on the left side of the tunnel, just before the stone archway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"2287","x":0.229317401,"y":0.52614671,"cat":"Waygates","group":"Locations","title":"Raya Lucaria Academy Waygate","desc":"A Teleporter Waygate located past the Iron ball trap. Transports users to the <a href='https://eldenring.wiki.fextralife.com/Church+of+Vows' target=\"_blank\">Church of Vows</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"2805","x":0.225858817,"y":0.526451912,"cat":"NPC Invaders","group":"Characters","title":"Moongrum, Carian Knight","desc":"Moongrum, Carian Knight. The last line of denfense before reaching Rennala's arena. Drops the <a href='https://eldenring.wiki.fextralife.com/Carian+Knight's+Shield' target=\"_blank\">Carian Knight's Shield</a> upon defeating the hostile NPC.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"8059","x":0.210037772,"y":0.526573993,"cat":"Consumables","group":"Items","title":"Magic Grease - 1x Raya Lucaria Academy Entrance","desc":"Consumable Item. Found on a corpse on the platform to the right of the gate after entering Raya Lucaria Academy","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"957","x":0.294358369,"y":0.526665556,"cat":"Crafting Materials","group":"Items","title":"Smoldering Butterfly - 8x at Fire Monk Camp","desc":"Crafting Material. There are 8 Smoldering Butterflies scattered among the corpses in the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Fire+Monk'>Fire Monk camp</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6535","x":0.212534086,"y":0.526787637,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily (D) - Raya Lucaria Academy","desc":"Can be found in the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a> in the corner of the fountain courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7017","x":0.223161337,"y":0.526909718,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - Raya Lucaria Academy (B)","desc":"North area of the courtyard, beware of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/giant+crab'>Giant Crab</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5932","x":0.224831491,"y":0.526970759,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Spectral Lance","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\"> Teardrop Scarab</a> in the large graveyard east of the Church of the Cuckoo site of grace. From the site of grace, exit east into the graveyard and head northeast to find a wooden bridge. Just past the bridge, head slightly southeast towards the cliff edge behind a cluster of gravestones. There should be a lower path you can jump down onto and the scarab should be in view at this point.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"2290","x":0.226774412,"y":0.52715388,"cat":"Shields","group":"Equipment","title":"Carian Knight's Shield","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Moongrum+Carian+Knight' target=\"_blank\">Moongrum Carian Knight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"5953","x":0.21988895,"y":0.52715388,"cat":"Spirit Ashes","group":"Equipment","title":"Marionette Soldier Ashes","desc":"When you reach the graveyard section, as you cross the other side of the bridge, make a hard left and drop down to find a path that curves to where the Marionette Soldiers are, kill the two soldiers and then loot the corpse that is hanging by the ledge to find this item.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"942","x":0.203379801,"y":0.527306479,"cat":"Locations","group":"Locations","title":"Academy Crystal Cave","desc":"A cave located east of the Academy. Requires a <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a> in order to unlock the seal. Grants passage to the Academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"2302","x":0.228025729,"y":0.527337002,"cat":"Armor","group":"Equipment","title":"Glintstone Scarab","desc":"Found inside a chest. From the garden section where you encountered the hostile NPC Moongrum Carian Knight, go west, by the gate, hug the wall and jump over the fence. Follow the path and then climb the ladder. The chest is inside the room at the top of the ladder.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"944","x":0.199868121,"y":0.527398042,"cat":"Key Items","group":"Items","title":"Stonesword Key - Academy Crystal Cave","desc":"Found inside the <a href=\"Academy+Crystal+Cave\" target=\"_blank\">Academy Crystal Cave</a>. Head to the left to where the Sages are, and enter the next room. You will find it inside a cage.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"7020","x":0.229246526,"y":0.527733763,"cat":"Consumables","group":"Items","title":"Golden Rune [7] - Raya Lucaria Academy","desc":"Consumable. Held by a corpse accessible only by taking the ladder in the hidden room leading to the Sorcerers summoning the magic ball trap, then jumping out the window above the waygate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8061","x":0.221482741,"y":0.527855844,"cat":"Consumables","group":"Items","title":"Silver-Pickled Fowl Foot - 1x Raya Lucaria Academy","desc":"Consumable Item. Looted from a corpse guarded by dogs and undead in the second graveyard of the area, after crossing a wooden hanging bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6539","x":0.224465827,"y":0.528496771,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily (A) - Raya Lucaria Academy","desc":"You can find one at the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>, by a cliff on the left side of the path.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7906","x":0.296067429,"y":0.529107176,"cat":"Key Items","group":"Items","title":"Fire Spur Me (Gesture)","desc":"Gesture. Collected from the Fire Altar within the Fire Monk camp north-west from Lakeside Cave in Southern Liurnia of the Lakes","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"7024","x":0.220811303,"y":0.529137695,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - 3x Raya Lucaria Academy (C)","desc":"<ol><li>On a dead body with its back to the precipice, near the main courtyard.</li> <li>Held by a corpse lying against one of the stones.</li> <li>On a corpse lying against one of the walls of the small garden, next to the stairs.</li></ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6541","x":0.228889741,"y":0.529442897,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily (B) - Raya Lucaria Academy","desc":"You can find one Trina's Luly at <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a> in the far end of the courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2203","x":0.213333921,"y":0.529473419,"cat":"Consumables","group":"Items","title":"Grace Mimic - 3x Raya Lucaria Academy","desc":"Consumable Item. Three can be Looted off a corpse at the northwest of the graveyard. The body is next to a gravestone, sitting by the ledge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6536","x":0.215500838,"y":0.529626019,"cat":"Consumables","group":"Items","title":"Spellproof Dried Liver - Raya Lucaria Academy","desc":"One can be found in <a href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes' target=\"_blank\">Liurnia of the Lakes</a> area at the foot of a large tombstone.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6540","x":0.225381427,"y":0.5297481,"cat":"Crafting Materials","group":"Items","title":"Mushroom - 5x Raya Lucaria Academy","desc":"You can find x5 Mushroom at the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a> on a corpse that is behind a tree by the wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8063","x":0.226814822,"y":0.529900703,"cat":"Crafting Materials","group":"Items","title":"Mushroom - 5x Second Graveyard Raya Lucaria Academy","desc":"Crafting Material. Five can be looted of a corpse hidden behind some tombstones to the left of the doorway leading to the lift on the second graveyard area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"956","x":0.293427872,"y":0.530053302,"cat":"Spells","group":"Equipment","title":"Flame, Cleanse Me","desc":"Held by one of the corpses at the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Fire+Monk'>Fire Monk camp</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"1310","x":0.200237514,"y":0.530053302,"cat":"Spells","group":"Equipment","title":"Crystal Release","desc":"<a href='https://eldenring.wiki.fextralife.com/Sorceries'>Sorcery Spell</a>. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Crystalians' target=\"_blank\">Crystalians</a> duo bosses inside the <a href='https://eldenring.wiki.fextralife.com/Academy+Crystal+Cave' target=\"_blank\">Academy Crystal Cave</a> upon their defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"4546","x":0.243598309,"y":0.530144865,"cat":"Sites of Grace","group":"Locations","title":"Gate Town North","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2286","x":0.231394335,"y":0.530266946,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy F","desc":"Looted off a corpse in the middle part of the Iron Ball trap stairs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"2278","x":0.210367088,"y":0.530358505,"cat":"Spells","group":"Equipment","title":"Shattering Crystal","desc":"Looted off a corpse on the second floor, west side, of the Church of the Cuckoo in <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>. The only way to reach this is going through the broken glass window of the church via the rooftops","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"2301","x":0.217538968,"y":0.530358505,"cat":"Weapons","group":"Equipment","title":"Azur's Glintstone Staff","desc":"Looted on the ground inside a room that is full of crystals. It's on the east side, the second floor of the Church of the Cuckoo within Raya Lucaria Academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"8062","x":0.224343895,"y":0.530358505,"cat":"Consumables","group":"Items","title":"Magic Grease - 1x Second Graveyard Raya Lucaria Academy","desc":"Consumable Item. Looted of a corpse in the second graveyard of Raya Lucaria Academy, before the room leading to the elevator to the higher areas.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"941","x":0.203563676,"y":0.530938391,"cat":"Sites of Grace","group":"Locations","title":"Academy Crystal Cave","desc":"Site of grace located inside a cave. Need to use a <a href='https://eldenring.wiki.fextralife.com/Stonesword Key' target=\"_blank\">Stonesword Key</a> in order to access it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2277","x":0.21149575,"y":0.531121513,"cat":"Key Items","group":"Items","title":"Academy Glintstone Key (B)","desc":"Looted off a corpse that's on the chandelier of Church of the Cuckoo. The only way to reach this is going through the broken glass window of the church via the rooftops of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"947","x":0.220865938,"y":0.531335153,"cat":"Spells","group":"Equipment","title":"Terra Magica","desc":"<a href='https://eldenring.wiki.fextralife.com/Sorceries' target=\"_blank\">Sorcery</a>. Found at the top of a tower in the middle of the Raya Lucaria Academy. This area is accessed by completing the <a href='https://eldenring.wiki.fextralife.com/Academy+Crystal+Cave' target=\"_blank\">Academy Crystal Cave</a> dungeon and taking the lift behind the boss' door.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"2267","x":0.223641406,"y":0.531457234,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Raya Lucaria Academy","desc":"1 can be found on the ground, next to the glowing sapling. West of the academy's courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"5954","x":0.218972956,"y":0.531518274,"cat":"Spirit Ashes","group":"Equipment","title":"Avionette Soldier Ashes","desc":"Spirit Ashes. Located on a corpse after taking the rotating lift down in Raya Lucaria Academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"2266","x":0.226814385,"y":0.531548797,"cat":"Crafting Materials","group":"Items","title":"Glintstone Firefly - 5x Raya Lucaria Academy","desc":"You can find x5 Glintstone Firefly Looted off a corpse, north section of the courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"948","x":0.212900414,"y":0.531609837,"cat":"Sites of Grace","group":"Locations","title":"Church of the Cuckoo","desc":"Site of Grace at the hall to the right of the altar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2283","x":0.231279633,"y":0.531762436,"cat":"Consumables","group":"Items","title":"Crystal Dart - Raya Lucaria Academy","desc":"Looted off a corpse on the broken beam connected to the stars of the Iron ball trap.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8161","x":0.208939056,"y":0.53191504,"cat":"Consumables","group":"Items","title":"Magic Grease - 2x Raya Lucaria Rooftops","desc":"Consumable Item. Looted off a corpse on the rooftops of the Church of Cuckoo, protected by two Avionette Soldiers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2275","x":0.211411169,"y":0.53225076,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Raya Lucaria Academy (B)","desc":"Pillaged from a corpse located on a wooden beam of the Church of the Cuckoo ceiling. The only way though is going through the broken glass window of the church via the rooftops of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8060","x":0.212809799,"y":0.532739085,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Raya Lucaria Academy Cuckoo Church","desc":"Summoning Pool Effigy found near the Church of Cuckoo site of grace in Raya Lucaria Academy. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"946","x":0.205272802,"y":0.53334949,"cat":"Bosses","group":"Characters","title":"Crystalians","desc":"Duo Field Bosses. Found at the end of the <a href='https://eldenring.wiki.fextralife.com/Academy+Crystal+Cave' target=\"_blank\">Academy Crystal Cave</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Crystal+Release' target=\"_blank\">Crystal Release</a> sorcery spell upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6542","x":0.225654616,"y":0.533380012,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily (C) - Raya Lucaria Academy","desc":"You can find one at <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a> in the flowerbed of the main courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2201","x":0.209946212,"y":0.533532611,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - Raya Lucaria Academy (C)","desc":"Looted off a corpse at the Church of the Cuckoo in <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2308","x":0.22024315,"y":0.533532611,"cat":"Armor","group":"Equipment","title":"Carian Knight Set","desc":"The Carian Knight Set can be picked up next to a large tombstone, past the graveyard section of Raya Lucaria Academy. When you reach the gate entrance leading to the large rotating lift, make a hard right and look below the ledge, jump down and follow the narrow path where you'll see a group of Glintstone Zombies worshipping a tombstone.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"2272","x":0.214915034,"y":0.533868336,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] - Raya Lucaria Academy","desc":"Upgrade Material. Looted off a corpse found by dropping down to the right of the door as soon as entering the first graveyard in <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2279","x":0.213950811,"y":0.533898854,"cat":"Armor","group":"Equipment","title":"Twinsage Glintstone Crown","desc":"Drops from a Crystallized Crab once killed. You'll find it outside the second-floor balcony, east section of the Church of the Cuckoo in <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>. It's hiding by the corner of the scaffolding.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"2151","x":0.211435222,"y":0.53435666,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [3] A - Raya Lucaria Academy","desc":"Looted off a corpse behind the altar of the Church of the Cuckoo in the academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2268","x":0.220700948,"y":0.534753421,"cat":"Armor","group":"Equipment","title":"Karolos Glintstone Crown","desc":"Drops from the Crystallized Crab that can be found by a corner on the west side of the academy's courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"2281","x":0.230631571,"y":0.535089146,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] B - Raya Lucaria Academy","desc":"Looted off a corpse at the end of the cut out steps of the Iron ball trap.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6108","x":0.24765707,"y":0.535241745,"cat":"Spells","group":"Equipment","title":"Ancient Death Rancor","desc":"Dropped by the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Death+Rite+Bird'>Death Rite Bird</a> in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes'>Liurnia of the Lake</a>, to the east of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy'>Raya Lucaria Academy</a> at night, south of the Gate Town North site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-purplespell.png?h=40"},{"id":"2265","x":0.227518792,"y":0.535363826,"cat":"Key Items","group":"Items","title":"Stonesword Key - Raya Lucaria Academy (B)","desc":"Looted on a fountain, center of the academy's courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2274","x":0.211375002,"y":0.535516429,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4] - Raya Lucaria Academy","desc":"Looted off a corpse that can be found in a small room with some small crabs. Located at the rooftops section of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2309","x":0.224648851,"y":0.535546948,"cat":"Talismans","group":"Equipment","title":"Longtail Cat Talisman","desc":"Looted off a corpse that can be found at the bottom section of the large rotating lift. Past the graveyard section of Raya Lucaria Academy, simply ride the lift down and defeat the single Pendulum Statue enemy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"2121","x":0.194747295,"y":0.535669029,"cat":"Consumables","group":"Items","title":"Dragonwound Grease (A)","desc":"Looted off a corpse behind the Glintstone Dragon Smarag.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4671","x":0.234413652,"y":0.535669029,"cat":"NPCs","group":"Characters","title":"Isolated Merchant (Raya Lucaria)","desc":"Merchant. Sells Spirit Ashes, Cookbook, Stonesword Key, Warrior Set, and several useful items.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"1877","x":0.196357873,"y":0.53573007,"cat":"Key Items","group":"Items","title":"Academy Glintstone Key (A)","desc":"Key used to unlock the gate of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2269","x":0.225657077,"y":0.535760591,"cat":"Key Items","group":"Items","title":"Glintstone Whetblade","desc":"Looted off a corpse that is hanging on the fence of an office balcony. From the fountain of the academy's courtyard, go west and head up the slope. The office is in front of the group of kneeling Noble Zombies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"6402","x":0.222970732,"y":0.535882673,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] A - Raya Lucaria Academy","desc":"At the lower level accessed descending from the elevator. On a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8160","x":0.213938398,"y":0.536035272,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] - 2x Raya Lucaria Rooftops","desc":"Upgrade Material. Found in Raya Lucaria Academy Rooftops, by jumping from the Tower with the Imbued Sword Key and going around until they can be looted off a corpse overseeing the lift and graveyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"7022","x":0.208237097,"y":0.536065794,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Raya Lucaria Academy (B)","desc":"Held by a corpse situated on top of the roofs of the Academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5972","x":0.295837817,"y":0.536309956,"cat":"Spells","group":"Equipment","title":"Briars of Sin","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes'>Liurnia of the Lakes</a>: Dropped by a mob directly north-west from the Artists Shack. Jump across the rocks and they'll be by a group of fire slugs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"2270","x":0.221635339,"y":0.536370997,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Raya Lucaria Academy (A)","desc":"Looted off a corpse that is hanging on a balcony fence that you can jump over to reach the rooftops. West side of the academy's courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1584","x":0.217020489,"y":0.536920361,"cat":"Locations","group":"Locations","title":"Raya Lucaria Academy","desc":"The second <a href='https://eldenring.wiki.fextralife.com/Legacy+Dungeons' target=\"_blank\">Legacy Dungeon</a> of the game, Raya Lucaria hides multiple riches, particularly for those interested in magic.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-rayalucaria.png?h=40"},{"id":"2273","x":0.213784747,"y":0.536981402,"cat":"Key Items","group":"Items","title":"Imbued Sword Key - Raya Lucaria Academy","desc":"Key Item used to activate a Waygate. It can be looted off a corpse found on the east side of the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a> rooftops.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6131","x":0.244036976,"y":0.53734618,"cat":"Bosses","group":"Characters","title":"Death Rite Bird (Raya Lucaria Academy East)","desc":"Death Rite Bird Miniboss that spawns only at night, south from the Gate Town North site of grace. Drops Ancient Death Rancor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6207","x":0.227272296,"y":0.537408685,"cat":"Weapons","group":"Equipment","title":"Academy Glintstone Staff","desc":"Staff. Can be found on <a href='https://eldenring.wiki.fextralife.com/Sorcerer+Thops' target=\"_blank\">Sorcerer Thops'</a> body near the Schoolhouse Classroom site of grace after giving him the Academy Glintstone Key.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"6855","x":0.228525124,"y":0.537469726,"cat":"Key Items","group":"Items","title":"Thops's Bell Bearing","desc":"Looted from <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/thops'>Thops' corpse</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"7025","x":0.224931492,"y":0.537561284,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - 2x Raya Lucaria Academy (D)","desc":"<ol><li>Within a tunnel, on a dead noble's body.</li> <li>On a noble's corpse at the 2nd floor's balcony.</li></ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7016","x":0.223100296,"y":0.537652847,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - Raya Lucaria Academy (A)","desc":"Within the terrace reached by the principal courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2123","x":0.195540814,"y":0.537713888,"cat":"Consumables","group":"Items","title":"Kukri","desc":"Looted off a corpse behind the Glintstone Dragon Smarag.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5701","x":0.210672172,"y":0.537988568,"cat":"Armor","group":"Equipment","title":"Lazuli Glintstone Crown","desc":"Looted from a <strong>Crystal Crab</strong>. Click <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Lazuli+Glintstone+Crown'>Here</a> for a detailed guide on how to get it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"8162","x":0.21204644,"y":0.537988568,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] - 1x Raya Lucaria Rooftop","desc":"Upgrade Material. Only accessible by dropping down from the tower with the <a href='https://eldenring.wiki.fextralife.com/Full+Moon+Crossbow' target=\"_blank\">Full Moon Crossbow</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8167","x":0.229653443,"y":0.538568455,"cat":"Spells","group":"Equipment","title":"Thop's Barrier","desc":"Sorcery. Looted from Thop's body found near the Schoolhouse Classroom site of grace after giving him the Academy Glintstone Key.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"2212","x":0.226876003,"y":0.538690536,"cat":"Sites of Grace","group":"Locations","title":"Schoolhouse Classroom Site of Grace","desc":"Site of Grace found in a room at the top section of the large rotating lift.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2305","x":0.228952402,"y":0.538690536,"cat":"NPCs","group":"Characters","title":"Thops (Deceased)","desc":"If you give him the Academy Glintstone Key that you find in Raya Lucaria Academy, you'll find him dead, sitting in a chair, outside the Schoolhouse Classroom Site. You can loot the following from his body: <a href='https://eldenring.wiki.fextralife.com/Thops's+Bell+Bearing' target=\"_blank\">Thops's Bell Bearing</a>, <a href='https://eldenring.wiki.fextralife.com/Academy+Glintstone+Staff' target=\"_blank\">Academy Glintstone Staff</a>, and <a href='https://eldenring.wiki.fextralife.com/Thops's+Barrier+(Spell)' target=\"_blank\">Thops's Barrier</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"8064","x":0.227944668,"y":0.538751576,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Schoolhouse Classroom","desc":"Summoning Pool Effigy found near the Schoolhouse Classroom site of grace in Raya Lucaria Academy. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3868","x":0.258734166,"y":0.539148338,"cat":"Waygates","group":"Locations","title":"Waygate to Liurnia West (from Liurnia East)","desc":"Waygate teleports players to the western side of Liurnia of the Lakes, by the Northern Liurnia Lakeshore Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"2207","x":0.225899804,"y":0.539270419,"cat":"Spells","group":"Equipment","title":"Gravity Well","desc":"Dropped by the Monolith Guardian enemy that appears from a gravity portal. The section is near the graveyard and the large rotating lift of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-purplespell.png?h=40"},{"id":"2261","x":0.230865827,"y":0.539270419,"cat":"Armor","group":"Equipment","title":"Olivinus Glintstone Crown","desc":"Looted from a corpse on a narrow path that leads back to the Schoolhouse Classroom site of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>. You need to pass through the illusory wall and jump over the balcony on the left, and circle back to the said site of grace. To find the illusory wall, go to the hallway from the schoolhouse classroom site, turn left. The illusory wall is in front of the corpse inside the room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"8065","x":0.224831296,"y":0.539270419,"cat":"Consumables","group":"Items","title":"Crystal Dart - 5x Schoolhouse Classroom","desc":"Consumable Throwable Item. Found on a corpse just outside the Schoolhouse Classroom site of grace, by some digging aristocrats.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2210","x":0.229654158,"y":0.539758743,"cat":"Key Items","group":"Items","title":"Conspectus Scroll","desc":"Looted off a body inside a room. From the Schoolhouse Classroom site of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>, go to the hallway, turn left. You'll see the corpse in front a an illusory wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-scroll.png?h=40"},{"id":"2209","x":0.227396458,"y":0.539850305,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [3] B - Raya Lucaria Academy","desc":"Looted on the monolith. It can be found past the Graveyard section where you'll see a large rotating lift. It is protected by a Monolith Guardian in <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"8159","x":0.212693003,"y":0.539850305,"cat":"Consumables","group":"Items","title":"Meteor Bolt - 5x Raya Lucaria Academy Rooftops","desc":"Consumable Item. Five can be looted from a corpse on the tower after the encounter with three Avionette Soldiers and a Sorcerer","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1879","x":0.194527135,"y":0.539911346,"cat":"Bosses","group":"Characters","title":"Glintstone Dragon Smarag","desc":"A fearsome magic dragon with crystalized magic formation for scales. Guards the <a href='https://eldenring.wiki.fextralife.com/Academy+Glinststone+Key' target=\"_blank\">Academy Glintstone Key</a>. Also drops a <a href='https://eldenring.wiki.fextralife.com/Dragon+Heart' target=\"_blank\">Dragon Heart</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"8066","x":0.229043384,"y":0.540002905,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Debate Hall","desc":"Summoning Pool Effigy found near the Debate Hall site of grace in Raya Lucaria Academy. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2109","x":0.197280449,"y":0.540155508,"cat":"Consumables","group":"Items","title":"Dragon Heart (Glintstone Dragon Smarag)","desc":"Key Consumable. Drops from <a href='https://eldenring.wiki.fextralife.com/Glintstone+Dragon+Smarag' target=\"_blank\"> Glintstone Dragon Smarag</a> upon defeat. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\"> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6549","x":0.22812707,"y":0.540308107,"cat":"Crafting Materials","group":"Items","title":"Living Jar Shard - 3x Raya Lucaria Academy","desc":"You can find x3 Living Shard at the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a> in the Debate Hall door.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6546","x":0.226540648,"y":0.540643832,"cat":"Key Items","group":"Items","title":"Cracked Pot - Raya Lucaria Academy","desc":"Can be found at the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a> near the Debate Hall door.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"2869","x":0.224770494,"y":0.540735391,"cat":"Key Items","group":"Items","title":"Stonesword Key - Raya Lucaria Academy (A)","desc":"Found in Raya Lucaria through an Illusory Wall just before the Site of Grace at Debate Parlor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1959","x":0.184916411,"y":0.540826954,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [2] - Teardrop Scarab Liurnia","desc":"Upgrade Material. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> found on a small isle on the western side of the lake. This scarab previously dropped Ash of War: Thop's Barrier.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2211","x":0.229074279,"y":0.540857472,"cat":"Key Items","group":"Items","title":"Glintstone Craftsman's Cookbook [5]","desc":"Looted from a treasure chest inside a room. From the Schoolhouse Classroom site of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>, go to the hallway, turn left.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"8165","x":0.235512837,"y":0.540857472,"cat":"Crafting Materials","group":"Items","title":"Strip of White Flesh - 2x Raya Lucaria Road","desc":"Crafting Material. Two can be looted from a corpse by traveling the road south from Main Academy Gate, past the Isolated Merchant.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8158","x":0.215439798,"y":0.540887994,"cat":"Consumables","group":"Items","title":"Crystal Dart - 5x Raya Lucaria Academy Rooftops","desc":"Consumable Item. Found on a corpse on the rooftop area of Raya Lucaria Academy, when a Sorcerer and three Avionette Soldiers attack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2260","x":0.230692607,"y":0.541254237,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] - Raya Lucaria Academy","desc":"Looted from a corpse on the balcony behind an illusory wall. From the Schoolhouse Classroom site of <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>, go to the hallway, turn left. The illusory wall is in front of the corpse inside the room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1895","x":0.172987107,"y":0.541437359,"cat":"Spells","group":"Equipment","title":"Greatblade Phalanx","desc":"<a href='https://eldenring.wiki.fextralife.com/Sorceries' target=\"_blank\">Sorcery</a>. Dropped by <a href='https://eldenring.wiki.fextralife.com/Bols,+Carian+Knight' target=\"_blank\">Bols, Carian Knight</a> inside the <a href='https://eldenring.wiki.fextralife.com/Cuckoo's+Evergaol' target=\"_blank\">Cuckoo's Evergaol</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"6206","x":0.212564407,"y":0.541437359,"cat":"Weapons","group":"Equipment","title":"Full Moon Crossbow","desc":"Weapon. From the Debate Parlor Site of Grace, head out into the courtyard and to the left to reach the rooftops. Continue along the rooftops until the tower past the Glintstone Sorcerer and three Avionette Soldiers. Across from the tower on another rooftop, an item will be visible. Drop down to the rooftop below and jump on top of the spike near the right edge. From the spike, turn left and jump onto the gargoyle (architectural, not an enemy) protruding from a corner of the building. Another jump will bring you to the rooftop with the item, a Smithing Stone [4]. Alternatively, you can reach this item by jumping from the tower onto a roof opposite the Full Moon Crossbow's chest in the tower. From that roof, a long jump will be required to reach the rooftops with the patrolling Marionette Soldier with spears. Sprinting before the jump is required, as a normal jump will not cover the distance. Note that there is a delay before sprinting starts (likely to determine whether the player is trying to roll or sprint). Continue along the rooftops to the left, past the four Marionette Soldiers and jump onto a platform connected to a tower. Inside, two Marionette Soldiers will ambush you from either side. Climb up the ladder to find a chest with the Full Moon Crossbow.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crossbow.png?h=40"},{"id":"2271","x":0.218064508,"y":0.541681521,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Raya Lucaria Academy (A)","desc":"Looted off a corpse that's sitting on a ledge. Past the first two Marionette Soldiers, you encounter on the rooftops of the academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2866","x":0.224587451,"y":0.541681521,"cat":"Spells","group":"Equipment","title":"Comet","desc":"Found behind an Illusory Wall before the Debate Hall Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"2264","x":0.227426205,"y":0.54183412,"cat":"Key Items","group":"Items","title":"Memory Stone - Raya Lucaria Academy","desc":"Rewarded as a drop upon defeating <a href='https://eldenring.wiki.fextralife.com/Red+Wolf+of+Radagon' target=\"_blank\">Red Wolf of Radagon</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"1517","x":0.294405543,"y":0.542108804,"cat":"Sites of Grace","group":"Locations","title":"Eastern Liurnia Lake Shore","desc":"Site of Grace found on the eastern side of Liurnia of the Lakes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2262","x":0.229164558,"y":0.542597128,"cat":"Sites of Grace","group":"Locations","title":"Debate Parlor","desc":"Site of Grace found on the third floor of the Schoolhouse Classroom building. Available to use after defeating the boss <a href='https://eldenring.wiki.fextralife.com/Red+Wolf+of+Radagon' target=\"_blank\">Red Wolf of Radagon</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6355","x":0.235939704,"y":0.542658169,"cat":"Key Items","group":"Items","title":"Celestial Dew - 1x Raya Lucaria South Gate","desc":"Used to seek absolution at the Church of Vows. Found on a corpse leaning against the inner side of the locked gate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1894","x":0.17152352,"y":0.542749728,"cat":"Bosses","group":"Characters","title":"Bols, Carian Knight","desc":"Optional Boss. Imprisoned within the <a href='https://eldenring.wiki.fextralife.com/Cuckoo's+Evergaol' target=\"_blank\">Cuckoo's Evergaol</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Greatblade+Phalanx' target=\"_blank\">Greatblade Phalanx</a> spell upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"2303","x":0.227181223,"y":0.543573776,"cat":"Talismans","group":"Equipment","title":"Radagon Icon","desc":"Found inside a treasure chest on the second floor of the Debate Hall Site of Grace. From the gate entrance leading to the courtyard, make a hard right and jump over the fence. Climb up the ladder and head through the broken glass window. The treasure chest is on the east section.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1358","x":0.173628721,"y":0.543695857,"cat":"Locations","group":"Locations","title":"Cuckoo's Evergaol","desc":"Evergaol located on the western landmass of Liurnia. <a href='https://eldenring.wiki.fextralife.com/Bols,+Carian+Knight' target=\"_blank\">Bols, Carian Knight</a> is imprisoned within.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-evergaol.png?h=40"},{"id":"2214","x":0.219705611,"y":0.543817938,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy E","desc":"Looted off a corpse hanging on the fence of the second-floor balcony. The nearest site of grace is the Schoolhouse Classroom in <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"6502","x":0.23050892,"y":0.543878979,"cat":"Bosses","group":"Characters","title":"Red Wolf of Radagon","desc":"Sub-boss of the area. A giant red wolf Great Enemy Boss found in Raya Lucaria within Liurnia of the Lakes. Drops 1x Memory Stone.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2871","x":0.225503238,"y":0.543940019,"cat":"Talismans","group":"Equipment","title":"Graven-School Talisman","desc":"Talisman. Found beyond the illusory wall before the Red Wolf of Radagon boss fight. Go up the ladder close to the Debate Hall Site of Grace and then down the hole to another the room with potboys. This opens the door inaccessible as you entered this area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"8716","x":0.193523092,"y":0.544275741,"cat":"Summoning Pools","group":"Locations","title":"Effigy of Martyr: Glintstone Dragon Smarag","desc":"Summoning Pool Effigy located before encountering <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Glintstone+Dragon+Smarag' target=\"\">Glintstone Dragon Smarag</a>, found among some lilypads beneath the flying scarabs found directly North from the Temple Quarter site of grace. Activate this effigy to send your summon sign to this summoning pool.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2213","x":0.223215065,"y":0.544428343,"cat":"Key Items","group":"Items","title":"Ritual Pot - Raya Lucaria Academy","desc":"Special Tool Key Item. Found inside a treasure chest, at the end of the hallway that is guarded by sorcerers and a giant Living Jar. The nearest site of grace is the Schoolhouse Classroom in <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"6548","x":0.228890018,"y":0.544489384,"cat":"Crafting Materials","group":"Items","title":"Crystal Bud - 5x Raya Lucaria Academy","desc":"You can find x5 at the second floor, on a corpse on the ledge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"759","x":0.234535798,"y":0.545130308,"cat":"Maps","group":"Locations","title":"Meeting Place Map","desc":"Can be found at the entrace of the Raya Lucarian academy, on lying corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"6610","x":0.242013169,"y":0.545557591,"cat":"Key Items","group":"Items","title":"Stonesword Key - Academy Gate Town","desc":"Found within a chest, in one of the small islands next to the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/raya+lucaria+academy'>Raya Lucaria Academy</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6409","x":0.307463916,"y":0.545923834,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4]","desc":"Found on a dead body sitting on a chair by following the main path.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"756","x":0.235236621,"y":0.547144644,"cat":"Sites of Grace","group":"Locations","title":"South Raya Lucaria Gate","desc":"Site of grace at the entrance of the Raya Academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6734","x":0.307799254,"y":0.549983029,"cat":"Key Items","group":"Items","title":"Resurrection Painting","desc":"Key Info Item. Painting found inside the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/artist's+shack'>Artist's Shack</a> in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/liurnia+of+the+lakes'>Liurnia of the Lakes</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1360","x":0.306182051,"y":0.55025771,"cat":"Locations","group":"Locations","title":"Artist's Shack (Liurnia of the Lakes)","desc":"A small cabin in North <a targer=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+lakes'>Liurnia of The Lakes</a>. Its strongly perceived tranquility seems overshadowed by oblivion.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"10201","x":0.312949229,"y":0.550349273,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [3] - Carian Study Hall","desc":"Upgrade Material. Dropped by a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"blank\">Teardrop Scarab</a> found off the road toward <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Carian+Study+Hall' target=\"blank\">Carian Study Hall</a>. It will be just north of the Study Hall Entrance Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"1361","x":0.307681708,"y":0.551661641,"cat":"Sites of Grace","group":"Locations","title":"Artist's Shack (Liurnia of the Lakes)","desc":"Site of Grace at <a target=\"\" href='https://eldenring.wiki.fextralife.com/Artist's+Shack'>Artist's Shack</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2124","x":0.358637915,"y":0.552211006,"cat":"Key Items","group":"Items","title":"Cursemark of Death","desc":"Key Item. Found on a body lying at the top of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+Liurnia'>Divine Tower of Liurnia</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8056","x":0.261264953,"y":0.552607771,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [2] - Academy Gate Town","desc":"Upgrade Material. Dropped by a Teardrop Scarab in the northern ruins of Academy Gate Town.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"6871","x":0.287355439,"y":0.553004533,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] - 3x Eastern Academy Gate Town","desc":"Upgrade Material. Three can be looted from a corpse sitting on a chair amid a group of Poison Flowers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6403","x":0.221017718,"y":0.553065573,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - Raya Lucaria Academy","desc":"Upgrade Material. Found on a gazebo near Giant Flowers on the outskirts of Raya Lucaria Academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6550","x":0.238563001,"y":0.553096095,"cat":"Crafting Materials","group":"Items","title":"Glintstone Firefly - 4x","desc":"You can loot 4 on a corpe that is on the side of the building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2122","x":0.36248368,"y":0.553218176,"cat":"Sites of Grace","group":"Locations","title":"Divine Tower of Liurnia","desc":"Site of Grace found on an upper floor of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+Liurnia'>Divine Tower of Liurnia</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1516","x":0.31760068,"y":0.553340257,"cat":"Sites of Grace","group":"Locations","title":"Study Hall Entrance","desc":"Site of Grace that can be found just inside the entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2120","x":0.360407301,"y":0.553431816,"cat":"Locations","group":"Locations","title":"Divine Tower of Liurnia","desc":"A tower standing on a lone island. Seems like an event of historical value took place here...","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-divinetower.png?h=40"},{"id":"4475","x":0.196971529,"y":0.553523379,"cat":"Sites of Grace","group":"Locations","title":"Temple Quarter","desc":"Site of grace at Temple Quarter","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2125","x":0.357812735,"y":0.553737019,"cat":"Talismans","group":"Equipment","title":"Stargazer Heirloom","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Talismans'>Talisman</a>. Found on a body lying at the top of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+Liurnia'>Divine Tower of Liurnia</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"940","x":0.205455638,"y":0.554408464,"cat":"Locations","group":"Locations","title":"Temple Quarter","desc":"Located at the Southwestern of the Raya Lucaria Academy, the Temple Quarter isn't what it used to be in its glory.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sunkentown.png?h=40"},{"id":"5657","x":0.340105935,"y":0.555171473,"cat":"Armor","group":"Equipment","title":"Godskin Noble Set","desc":"Armor Set comprised of the <a href='https://eldenring.wiki.fextralife.com/Godskin+Noble+Hood' target=\"_blank\">Godskin Noble Hood</a>, <a href='https://eldenring.wiki.fextralife.com/Godskin+Noble+Robe' target=\"_blank\">Godskin Noble Robe</a>, <a href='https://eldenring.wiki.fextralife.com/Godskin+Noble+Bracelets' target=\"_blank\">Godskin Noble Bracelets</a> and the <a href='https://eldenring.wiki.fextralife.com/Godskin+Noble+Trousers' target=\"_blank\">Godskin Noble Trousers</a>. Dropped by <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/godskin+noble'>Godskin Noble</a> <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Bosses'>Boss</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"763","x":0.232124834,"y":0.555201991,"cat":"Shields","group":"Equipment","title":"Blue-White Wooden Shield","desc":"Shield in Academy Gate Town (near Raya Lucaria Academy Entrance). Can be found on the outskirts of the buildings, towards the west side.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-smallshield.png?h=40"},{"id":"6556","x":0.206919639,"y":0.556422801,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily - 3x Temple Quarter","desc":"Crafting Material. Can be gathered from the ruins near the circle of white flowers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6962","x":0.318637431,"y":0.557063728,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Carian Study Hall","desc":"Held by a corpse at inside the tower, west side.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8286","x":0.312071477,"y":0.55724685,"cat":"Crafting Materials","group":"Items","title":"Great Dragonfly Head - 5x Liurnia East","desc":"Crafting Material. Five can be looted from a corpse in a graveyard just south-east from the Artists's Shack in Eastern Liurnia of the Lakes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8053","x":0.20524104,"y":0.558131935,"cat":"Crafting Materials","group":"Items","title":"Rimed Crystal Bud - 3x in Temple Quarter","desc":"Crafting Material. 3 are found as a treasure within a circle of white flowers in Temple Quarter. They are protected by Albinaurics and entering the circle triggers an ambush.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5865","x":0.339498638,"y":0.558192976,"cat":"Bosses","group":"Characters","title":"Godskin Noble (Divine Tower of Liurnia)","desc":"Field boss guarding the bridge to the <a href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+Liurnia' target=\"_blank\">Divine Tower of Liurnia</a>. Only accessible after progressing <a href='https://eldenring.wiki.fextralife.com/Ranni+the+Witch' target=\"_blank\">Ranni</a>'s questline and acquiring the <a href='https://eldenring.wiki.fextralife.com/Carian+Inverted+Statue' target=\"_blank\">Carian Inverted Statue</a>, allowing access to a secret area in <a href='https://eldenring.wiki.fextralife.com/Carian+Study+Hall' target=\"_blank\">Carian Study Hall</a> leading to the bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2118","x":0.321376844,"y":0.558345559,"cat":"Armor","group":"Equipment","title":"Mask of Confidence","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Helms'>Helm</a>. Found on a corpse laying on the walls of the secret area of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Carian+Study+Hall'>Carian Study Hall</a> unlocked using the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Carian+Inverted+Statue'>Carian Inverted Statue</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"8058","x":0.236182787,"y":0.55874234,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] - 1x Academy Gate Town","desc":"Upgrade Material. Looted off a corpse in the middle of the upper road by the Flame Chariot and Raya Lucaria Soldiers that guard the path to Raya Lucaria Academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6253","x":0.316802658,"y":0.558803381,"cat":"NPC Invaders","group":"Characters","title":"Preceptor Miriam","desc":"Found at the hall middle way up the stairs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"6128","x":0.267856142,"y":0.558986502,"cat":"NPCs","group":"Characters","title":"Diallos","desc":"NPC. He leaves the <a href='https://eldenring.wiki.fextralife.com/Roundtable+Hold' target=\"_blank\"> Roundtable Hold</a> and then be found over the corpse of Lanya.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"8057","x":0.24391488,"y":0.559078065,"cat":"Consumables","group":"Items","title":"Shatthershard Arrow (Fletched) - 6x Academy Gate Town","desc":"Consumable Ammo. Six can be looted from a corpse hanging off a ledge on a balcony overseeing the main stairs leading to the Academy proper.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8055","x":0.257786878,"y":0.559169624,"cat":"Crafting Materials","group":"Items","title":"Crystal Bud - 1x Academy Gate Town","desc":"Crafting Material. Looted from a corpse in a corner of the destroyed church in the middle section of Academy Gate Town.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5847","x":0.326176775,"y":0.559413786,"cat":"Sites of Grace","group":"Locations","title":"Liurnia Tower Bridge","desc":"<a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'>Site of Grace</a> at the bridge leading to the Divine Tower of Liurnia.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5922","x":0.180708529,"y":0.559474826,"cat":"Key Items","group":"Items","title":"Shabriri Grape - Revenger's Shack","desc":"Key Item. Dropped by <a href='https://eldenring.wiki.fextralife.com/Edgar+the+Revenger' target=\"_blank\">Edgar the Revenger</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2876","x":0.308259442,"y":0.560054713,"cat":"Key Items","group":"Items","title":"Dragon Cult Prayerbook","desc":"Dropped by a knight patrolling immediately south of the Liurnia Artist Shack","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tome.png?h=40"},{"id":"2115","x":0.319822626,"y":0.560115754,"cat":"Locations","group":"Locations","title":"Carian Study Hall","desc":"A large library-like location full of spectres and magic users that leads to the Divine Tower of Liurnia. Using the Carian Inverted Statue unlocks an alternative version of the map.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-studyhall.png?h=40"},{"id":"2853","x":0.204905701,"y":0.560146272,"cat":"Weapons","group":"Equipment","title":"Icerind Hatchet","desc":"Axe found inside a chest in the <a href='https://eldenring.wiki.fextralife.com/Temple+Quarter' target=\"_blank\">Temple Quarter</a>. The chest is located in what remains of the tower of a ruined building, by some poison flowers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-axe.png?h=40"},{"id":"5919","x":0.178724421,"y":0.560176794,"cat":"Locations","group":"Locations","title":"Revenger's Shack","desc":"An isolated shack north of the Minor Erdtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"930","x":0.264377775,"y":0.560298875,"cat":"Locations","group":"Locations","title":"Academy Gate Town","desc":"A sunken town, now crawling with soldiers and all kinds of powerful sea creatures.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sunkentown.png?h=40"},{"id":"8303","x":0.270215327,"y":0.560298875,"cat":"Armor","group":"Equipment","title":"Diallos's Mask","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Diallos'>Diallos</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"8802","x":0.176254498,"y":0.560695636,"cat":"Consumables","group":"Items","title":"Raw Meat Dumpling - 5x Revenger's Shack","desc":"Consumable Item. Five can be looted from corpses within the Revenger's Shack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1303","x":0.24237668,"y":0.560726159,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - 3x Academy Gate Town","desc":"Upgrade Material. Three can be looted off a corpse. The corpse is resting against a wall in the water near a Giant Crab.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6001","x":0.316830916,"y":0.560726159,"cat":"Spells","group":"Equipment","title":"Magic Downpour","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Magic+Downpour'>Magic Downpour</a> is a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Sorceries'>Sorcery</a> dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Preceptor+Miriam'>Preceptor Miriam</a> in the Carian Study Hall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"6368","x":0.321500463,"y":0.560817717,"cat":"Spells","group":"Equipment","title":"Lucidity","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Preceptor+Miriam' target=\"_blank\">Preceptor Miriam</a> in the secret area of the <a href='https://eldenring.wiki.fextralife.com/Carian+Study+Hall' target=\"_blank\">Carian Study Hall</a> unlocked using the <a href='https://eldenring.wiki.fextralife.com/Carian+Inverted+Statue' target=\"_blank\">Carian Inverted Statue</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"5923","x":0.18238678,"y":0.56112292,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy - Revenger's Shack","desc":"Multiplayer Item. Dropped by <a href='https://eldenring.wiki.fextralife.com/Edgar+the+Revenger' target=\"_blank\">Edgar the Revenger</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"5771","x":0.260781576,"y":0.561153442,"cat":"Key Items","group":"Items","title":"Glintstone Craftsman's Cookbook [4]","desc":"Key Item. Found at <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Academy+Gate+Town'>Academy Gate Town</a> inside a chest within a tower on the rooftop of a destroyed building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"1887","x":0.180677392,"y":0.561245001,"cat":"NPC Invaders","group":"Characters","title":"Edgar the Revenger","desc":"Hostile NPC invader. Invades when you interact with the Site of Grace at the <a href='https://eldenring.wiki.fextralife.com/Revenger's+Shack' target=\"_blank\">Revenger's Shack</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"5951","x":0.296968397,"y":0.561397604,"cat":"Spirit Ashes","group":"Equipment","title":"Land Squirt Ashes","desc":"Spirit Ashes. Found at a grave with several groups of land squirts nearby on the east shore of Liurnia Lake. To reach it, start at the Gate Town Bridge site of grace, go down to ground level, and simply travel north along the shore.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"5921","x":0.181258254,"y":0.562099568,"cat":"Weapons","group":"Equipment","title":"Banished Knight's Halberd +8","desc":"An upgraded <a href='https://eldenring.wiki.fextralife.com/Banished+Knight's+Halberd' target=\"_blank\">Banished Knight's Halberd</a> dropped by <a href='https://eldenring.wiki.fextralife.com/Edgar+the+Revenger' target=\"_blank\">Edgar the Revenger</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-halberd.png?h=40"},{"id":"5849","x":0.176954348,"y":0.562404771,"cat":"Sites of Grace","group":"Locations","title":"Revenger's Shack","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8287","x":0.326720473,"y":0.562557374,"cat":"Crafting Materials","group":"Items","title":"Living Jar Shard - 1x Jarburg","desc":"Crafting Material. Looted from a body inside one of the shacks in Jarburg.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8801","x":0.179611691,"y":0.562587892,"cat":"Consumables","group":"Items","title":"Raw Meat Dumpling - 5x Edgar the Revenger","desc":"Consumable Item. Five are dropped by Edgar the Revenger if deafeated in the scripted invasion at Revenger's Shack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1302","x":0.250249968,"y":0.562832054,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Academy Gate Town","desc":"Flask Upgrade Material. One can be found on the ground next to a glowing sapling.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"2925","x":0.322203441,"y":0.563137257,"cat":"Weapons","group":"Equipment","title":"Carian Glintstone Staff","desc":"Found at the Carian Study Hall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"6552","x":0.279302596,"y":0.56328986,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"You can found one near to the Tree etween two fallen houses.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5909","x":0.318053014,"y":0.563320378,"cat":"Talismans","group":"Equipment","title":"Cerulean Seed Talisman","desc":"Found at <a href='https://eldenring.wiki.fextralife.com/Carian+Study+Hall' target=\"_blank\">Carian Study Hall</a>. look for it at the rafters, next to a body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6551","x":0.260899911,"y":0.5633509,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf - Academy Gate Town","desc":"Crafting Material. Can be found on a corpse on a rooftop near to the tower with the chest for <a href='https://eldenring.wiki.fextralife.com/Glintstone+Craftsman's+Cookbook+(4)' target=\"_blank\">Glintstone Craftsman's Cookbook [4]</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2135","x":0.242648025,"y":0.563472962,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Charge Forth","desc":"Dropped by a Teardrop Scarab. You'll find it attached to a ceiling, under some Poison Pods.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"7028","x":0.319888744,"y":0.564419107,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Carian Study Hall","desc":"In a balcony on a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"924","x":0.245398594,"y":0.565182116,"cat":"NPCs","group":"Characters","title":"Finger Reader (Academy Bridge)","desc":"Palm Reader. Can be found at the edge of the broken bridge that leads to the Raya Lucaria Academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"4265","x":0.327178857,"y":0.566372403,"cat":"Locations","group":"Locations","title":"Jarburg","desc":"Jarburg Village of Living Jars. Abundant herb materials and some Smithing Stone (3) can be found here.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-location_49.png?h=40"},{"id":"4267","x":0.323546158,"y":0.566402926,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] - 3x Jarburg","desc":"Upgrade Material. 3 are found on a corpse on top of the hut that you land on as you descend into the village.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"7021","x":0.324673653,"y":0.566982809,"cat":"NPCs","group":"Characters","title":"Diallos - Jarburg","desc":"NPC. If players have completed Volcano Manor, after progressing the Jarburg questline he will appear in one of the shacks, tending to a little jar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6553","x":0.263829002,"y":0.567196452,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"You can found one near to the Church metal Door.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5861","x":0.329454484,"y":0.567226971,"cat":"Key Items","group":"Items","title":"Cracked Pot - 3x Jarburg","desc":"Crafting Pot. Three can be found in the village of <a href='https://eldenring.wiki.fextralife.com/Jarburg' target=\"_blank\">Jarburg</a>: <ol> <li>The first is on a corpse in front of the blocked door of a hut north of where you drop down into the village. </li> <li>The second is in a hut northeast of the first. </li> <li>The last Cracked Pot is found on a large headstone in the south along the main road in the village.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"6877","x":0.32534517,"y":0.568203619,"cat":"NPCs","group":"Characters","title":"Jar Bairn","desc":"Jar Bairn can be found in <a href='https://eldenring.wiki.fextralife.com/Jarburg' target=\"_blank\">Jarburg</a> and will ask you to become Potentate, but deems your hands too rough.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"2008","x":0.315641558,"y":0.56838674,"cat":"Spirit Ashes","group":"Equipment","title":"Skeletal Bandit Ashes","desc":"Spirit Ash that drops from the <a href='https://eldenring.wiki.fextralife.com/Tibia+Mariner' target=\"_blank\"> Tibia Mariner</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"1321","x":0.211404338,"y":0.568875064,"cat":"Spells","group":"Equipment","title":"Bloodflame Blade","desc":"<a href='https://eldenring.wiki.fextralife.com/Incantations' target=\"_blank\">Incantation</a>. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> along the marshes outside of the nearby island. Note that there is another scarab nearby that does not drop anything.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"5864","x":0.329454484,"y":0.56960755,"cat":"Key Items","group":"Items","title":"Ritual Pot - 2x Jarburg","desc":"Crafting Pot. <strong>Two</strong> can be found in the village of <a href='https://eldenring.wiki.fextralife.com/Jarburg' target=\"_blank\">Jarburg</a>: <ol> <li>The first is found on a corpse on the roof of a hut in the north, use the cliffs to get on top of the hut and loot the corpse.</li> <li>The second can be found on top of a large decorative jar in the south. Use the boulders nearby or your horse to get on top of the jar.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"8285","x":0.3152456,"y":0.570706279,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily - 1x Liurnia East","desc":"Crafting Material. One can be found as a treasure on a corpse in the flooded graves near the small forest with a Tibia Mariner boss spawn.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7026","x":0.281179697,"y":0.570889401,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Academy Gate Town","desc":"Within the ruined chapel, surrounded by <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/albinauric'>Albinaurics</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2010","x":0.318819333,"y":0.571011482,"cat":"Key Items","group":"Items","title":"Deathroot - East Liurnia of the Lakes","desc":"Deathroot dropped by <a href='https://eldenring.wiki.fextralife.com/Tibia+Mariner' target=\"_blank\"> Tibia Mariner</a> located at <a href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes' target=\"_blank\">Liurnia of the Lakes</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1359","x":0.316514041,"y":0.57177449,"cat":"Bosses","group":"Characters","title":"Tibia Mariner (Liurnia of the Lakes)","desc":"One of the locations where Tibia Mariner <a targer=\"\" href='https://eldenring.wiki.fextralife.com/bosses'>Boss</a> appears.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"8731","x":0.22052312,"y":0.57198813,"cat":"Key Items","group":"Items","title":"Pureblood Knight's Medal","desc":"Key Tool Item. Reward for advancing White-Mask Varre questline and giving him the blood-soaked Lord of Blood's Favor item. Gives player early access to Mohgwyn Dynasty underground.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4266","x":0.327939587,"y":0.572018652,"cat":"Sites of Grace","group":"Locations","title":"Jarburg","desc":"Site of Grace found in the village of Jarburg.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"928","x":0.267093819,"y":0.572293333,"cat":"Sites of Grace","group":"Locations","title":"Academy Gate Town","desc":"Site of grace in the deluged part of the academy town.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1326","x":0.218331651,"y":0.572659576,"cat":"NPCs","group":"Characters","title":"White-Mask Varre (Second Location)","desc":"<a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/White-Faced+Varre' target=\"blank\">White-Faced Varre</a>, Location 2. Found standing outside of the Rose Church. Gives you the <a href='https://eldenring.wiki.fextralife.com/Festering+Bloody+Finger' target=\"blank\">Festering Bloody Finger</a> after exhausting his dialogue.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"8730","x":0.2206452,"y":0.573453102,"cat":"Key Items","group":"Items","title":"Bloody Finger","desc":"Key Multiplayer Item. Reward for advancing White-Mask Varre questline and giving him the blood-soaked Lord of Blood's Favor item.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"7030","x":0.315506884,"y":0.573819345,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3]","desc":"Upgrade Material. Found on a gravesite near the <a href='https://eldenring.wiki.fextralife.com/Tibia+Mariner' target=\"_blank\">Tibia Mariner</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5714","x":0.237557356,"y":0.57409403,"cat":"Sites of Grace","group":"Locations","title":"Fallen Ruins of the Lakes","desc":"Site of Grace found in the marshes east of Rose Church.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6967","x":0.327696922,"y":0.574399232,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - 2x Jarburg Cemetery","desc":"Two (<strong>2</strong>) <strong>Golden Runes (3)</strong> found within the graveyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8052","x":0.220065322,"y":0.57442975,"cat":"Key Items","group":"Items","title":"Lord of Blood's Favor","desc":"Key Item. Obtained from White-Faced Varre after invading other players 3 times and talking to him, then accepting to be knighted.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1325","x":0.217081213,"y":0.574795993,"cat":"Locations","group":"Locations","title":"Rose Church","desc":"An abandoned church overgrown with bloodroses and rot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"7009","x":0.329467077,"y":0.575223277,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Jarburg Cemetery","desc":"Found within the graveyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7007","x":0.326170927,"y":0.575253799,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - 2x Jarburg Cemetery","desc":"Two (<strong>2</strong>) <strong>Golden Runes (2)</strong> found within the graveyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5416","x":0.321135128,"y":0.57531484,"cat":"NPCs","group":"Characters","title":"Iron Fist Alexander (Fifth Location)","desc":"NPC. Alexander's fifth location on this questline. Found in Liurnia of the Lakes, just south of Carian Study Hall. Follow the path south from the Artist's Shack Site of Grace. Alexander will call out for help as the player gets closer to his location. He will ask you to make him \"slippery\". Use an Oil Pot to free him.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"927","x":0.27188463,"y":0.575711601,"cat":"Maps","group":"Locations","title":"Map: Liurnia, North","desc":"Can be found over a grave-like big stone, at Academy Gate Town,","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"1328","x":0.220865727,"y":0.575711601,"cat":"Key Items","group":"Items","title":"Festering Bloody Finger","desc":"Multiplayer Item. Given by <a href='https://eldenring.wiki.fextralife.com/White-Faced+Varre' target=\"_blank\">White-Faced Varre</a> after exhausting his dialogue.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"939","x":0.198101012,"y":0.576138885,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - 3x Liurnia of the Lakes Gazebo","desc":"Upgrade Material. Three can be found Inside a gazebo south-west from Temple Quarter.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6968","x":0.327793403,"y":0.576138885,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - Jarburg Cemetery","desc":"Found within the graveyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6554","x":0.288363154,"y":0.57674929,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"Can be found 2x near an abandoned house.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1330","x":0.217844255,"y":0.577603857,"cat":"Key Items","group":"Items","title":"Nomadic Warrior's Cookbook [12]","desc":"Cookbook item found inside the Rose Church, by the southern walls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"6961","x":0.281240733,"y":0.578366865,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Academy Gate Town","desc":"Held by a corpse within <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/academy+gate+town'>Academy Gate Town</a> next to some <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/albinauric'>Albinaurics</a>, on the bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2110","x":0.605191333,"y":0.578580505,"cat":"Talismans","group":"Equipment","title":"Dragoncrest Shield Talisman","desc":"Talisman found on one of the edges of <a href='https://eldenring.wiki.fextralife.com/Bestial+Sanctum' target=\"_blank\"> Bestial Sanctum</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1345","x":0.179395805,"y":0.57891623,"cat":"Locations","group":"Locations","title":"Minor Erdtree (Liurnia Southwest)","desc":"Minor Erdtree found in the plateaus in the southwest of Liurnia.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tree.png?h=40"},{"id":"934","x":0.298057209,"y":0.579282473,"cat":"Consumables","group":"Items","title":"Silver-Pickled Fowl Foot","desc":"One can be found at the northern side of the broken bridge that leads to Raya Lucaria Academy","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1069","x":0.173811221,"y":0.579953918,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Sword Dance","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> found along the narrow path west of the Minor Erdtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"6555","x":0.259586722,"y":0.580381202,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily - 2x","desc":"Can be found x2 mear to the fallen ruins, at the down-left corner.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5602","x":0.599393596,"y":0.58047276,"cat":"Weapons","group":"Equipment","title":"Cinquedea","desc":"Dagger. Found outside the bestial sanctum, after a long series of platforms starting on the west side to drop down onto the external structure's base.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"1527","x":0.313275537,"y":0.582639212,"cat":"Consumables","group":"Items","title":"Starlight Shards E","desc":"Can be found in front of the half bowl stone statue by the cliff, overlooking the fog covered Academy Gate Town and Gate Town Bridge,","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6385","x":0.604551468,"y":0.583189065,"cat":"Spells","group":"Equipment","title":"Gurranq's Beast Claw","desc":"<a href='https://eldenring.wiki.fextralife.com/Bestial+Sanctum' target=\"_blank\">Bestial Sanctum</a>: Reward from <a href='https://eldenring.wiki.fextralife.com/Gurranq+Beast+Clergyman' target=\"_blank\">Gurranq, Beast Clergyman</a> after giving him the eighth <a href='https://eldenring.wiki.fextralife.com/Deathroot' target=\"_blank\">Deathroot</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-orangespell.png?h=40"},{"id":"1064","x":0.177351,"y":0.583250105,"cat":"Flask Upgrades","group":"Items","title":"Cerulean Crystal Tear A","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Erdtree+Avatar' target=\"_blank\">Erdtree Avatar</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"1065","x":0.180067271,"y":0.583250105,"cat":"Flask Upgrades","group":"Items","title":"Ruptured Crystal Tear","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Erdtree+Avatar' target=\"_blank\">Erdtree Avatar</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"5931","x":0.60684041,"y":0.583280624,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Beast's Roar","desc":"Reward from <a href='https://eldenring.wiki.fextralife.com/Gurranq,+Beast+Clergyman' target=\"_blank\">Gurranq, Beast Clergyman</a> after giving him the fourth <a href='https://eldenring.wiki.fextralife.com/Deathroot' target=\"_blank\">Deathroot</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"8102","x":0.60201831,"y":0.583829988,"cat":"Weapons","group":"Equipment","title":"Beastclaw Greathammer","desc":"Given by <a href='https://eldenring.wiki.fextralife.com/Gurranq'>Gurranq</a> after turning in their 7th Deathroot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-warhammer.png?h=40"},{"id":"10220","x":0.311543515,"y":0.583921551,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Gate Town Bridge","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia' target=\"blank\">Liurnia</a>, next to the Gate Town Bridge Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"3864","x":0.305205876,"y":0.584898199,"cat":"NPCs","group":"Characters","title":"Hyetta (Third Location)","desc":"Hyetta spawns near the site of grace. She will ask for another Shabriri Grape and will ask what the grapes really are. Telling her will make her puke and then thank you for telling her. After sitting down at the grace nearby she will have more dialog. After once again sitting at the grace she will move to her next location.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"1053","x":0.179969949,"y":0.585142361,"cat":"Bosses","group":"Characters","title":"Erdtree Avatar (Liurnia Southwest)","desc":"Field Boss. Drops <a href='https://eldenring.wiki.fextralife.com/Cerulean+Crystal+Tear' target=\"_blank\">Cerulean Crystal Tear</a> and <a href='https://eldenring.wiki.fextralife.com/Ruptured+Crystal+Tear' target=\"_blank\">Ruptured Crystal Tear</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"1150","x":0.605191199,"y":0.58523392,"cat":"NPCs","group":"Characters","title":"Gurranq Beast Clergyman","desc":"A non-hostile NPC found within the <a href='https://eldenring.wiki.fextralife.com/Bestial+Sanctum' target=\"_blank\">Bestial Sanctum</a>. Awards various items for handing in <a href='https://eldenring.wiki.fextralife.com/Deathroot' target=\"_blank\">Deathroot</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"933","x":0.301636788,"y":0.585569645,"cat":"Crafting Materials","group":"Items","title":"Strip of White Flesh - 3x under Gate Town Bridge","desc":"Crafting Material. Can be found in the back of the bridge. Beware of the Infested pods lurking there.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1512","x":0.302549427,"y":0.585691726,"cat":"Sites of Grace","group":"Locations","title":"Gate Town Bridge","desc":"Site of Grace found on the top of the broken bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6407","x":0.280827903,"y":0.585935888,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - 3x (Liurnia South Gazebo)","desc":"Upgrade Material. Three can be looted from a gazebo close to the South-East of Academy Gate Town. Beware of a Giant Lobster ambush.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8849","x":0.235241058,"y":0.585948096,"cat":"Key Items","group":"Items","title":"Larval Tear - Liurnia of the Lakes","desc":"<p>Key item used for Rebirth. Dropped by a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Grafted+Scion' target=\"\">Grafted Scion</a> disguised as a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Giant+Lobster' target=\"\">Giant Lobster</a> when defeated. Located between <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Rose+Church' target=\"\">Rose Church</a> and <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Boilprawn+Shack' target=\"\">Boilprawn Shack</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1149","x":0.610072223,"y":0.586088487,"cat":"Sites of Grace","group":"Locations","title":"Bestial Sanctum","desc":"Site of Grace found inside the Bestial Sanctum.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8195","x":0.175886151,"y":0.58639369,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Road's End Catacombs","desc":"Summoning Pool Effigy found against the left wall in the first big room after the Road's End Catacombs site of grace in Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6384","x":0.602781313,"y":0.586576812,"cat":"Spells","group":"Equipment","title":"Beast Claw","desc":"<a href='https://eldenring.wiki.fextralife.com/Bestial+Sanctum' target=\"_blank\">Bestial Sanctum</a>: Reward from <a href='https://eldenring.wiki.fextralife.com/Gurranq+Beast+Clergyman' target=\"_blank\">Gurranq, Beast Clergyman</a> after giving him the fifth <a href='https://eldenring.wiki.fextralife.com/Deathroot' target=\"_blank\">Deathroot</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-orangespell.png?h=40"},{"id":"7062","x":0.173292187,"y":0.587492419,"cat":"Consumables","group":"Items","title":"Root Resin - Road's End Catacomb","desc":"Can be found by breaking a hidden wall next to the stairs, inside <a href='https://eldenring.wiki.fextralife.com/Road's+End+Catacomb' target=\"_blank\"> Road's End Catacomb</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"936","x":0.2396009,"y":0.587522941,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] C","desc":"Upgrade Material. Found inside a gazebo.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2325","x":0.615141828,"y":0.587767103,"cat":"Weapons","group":"Equipment","title":"Gargoyle's Blackblade","desc":"Greatsword dropped by the <a href='https://eldenring.wiki.fextralife.com/Black+Blade+Kindred' target=\"_blank\"> Black Blade Kindred</a> guarding the entrance to the <a href='https://eldenring.wiki.fextralife.com/Bestial+Sanctum' target=\"_blank\">Bestial Sanctum</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"6405","x":0.216777723,"y":0.587858662,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [1]","desc":"Found on a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2111","x":0.610989201,"y":0.58856063,"cat":"Locations","group":"Locations","title":"Bestial Sanctum","desc":"Bestial Sanctum, <a href='https://eldenring.wiki.fextralife.com/Gurranq+Beast+Clergyman' target=\"_blank\"> Gurranq, Beast Clergyman</a> can be found inside.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-location_45.png?h=40"},{"id":"1071","x":0.176222415,"y":0.58862167,"cat":"Sites of Grace","group":"Locations","title":"Road's End Catacombs (Site of Grace)","desc":"Site of grace located just inside the <a href='https://eldenring.wiki.fextralife.com/Road's+End+Catacombs target='_blank\">Road's End Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6386","x":0.605833254,"y":0.589109994,"cat":"Spells","group":"Equipment","title":"Bestial Vitality","desc":"<a href='https://eldenring.wiki.fextralife.com/Bestial+Sanctum' target=\"_blank\">Bestial Sanctum</a>: Reward from <a href='https://eldenring.wiki.fextralife.com/Gurranq+Beast+Clergyman' target=\"_blank\">Gurranq, Beast Clergyman</a> after giving him the fifth <a href='https://eldenring.wiki.fextralife.com/Deathroot' target=\"_blank\">Deathroot</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-orangespell.png?h=40"},{"id":"932","x":0.291931926,"y":0.589140513,"cat":"Consumables","group":"Items","title":"Golden Rune [6] A","desc":"You will spot a ballon, that has some enemies attached to it. Defeat all of them and destroy the ballon to obtain the Golden Rune.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3182","x":0.308188575,"y":0.589140513,"cat":"Bosses","group":"Characters","title":"Night's Cavalry (Liurnia)","desc":"<a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> Miniboss found patrolling near the Gate Town Bridge. Only appears at night. Drops <a href='https://eldenring.wiki.fextralife.com/Ash+of+War:+Ice+Spear' target=\"_blank\">Ash of War: Ice Spear</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"1076","x":0.172316887,"y":0.589750917,"cat":"Spirit Ashes","group":"Equipment","title":"Glintstone Sorcerer Ashes","desc":"Inside Road's End Catacombs. Defeat the <a href='https://eldenring.wiki.fextralife.com/Spirit-Caller+Snail' target=\"_blank\"> Spirit-Caller Snail</a> to obtain.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6204","x":0.178694233,"y":0.59011716,"cat":"Weapons","group":"Equipment","title":"Watchdog's Staff","desc":"Located in <a href='https://eldenring.wiki.fextralife.com/Road's+End+Catacombs' target=\"_blank\">Road's End Catacombs</a>, behind an illusory wall near the stairs at the beginning of the dungeon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossal_weapon.png?h=40"},{"id":"1251","x":0.613127512,"y":0.590391845,"cat":"Bosses","group":"Characters","title":"Black Blade Kindred (Bestial Sanctum)","desc":"Boss found at the entrance of the Bestial Sanctum. Drops <a href='https://eldenring.wiki.fextralife.com/Gargoyle's+Blackblade' target=\"_blank\">Gargoyle's Blackblade</a> and <a href=\"Gargoyle's+Black+Halberd\" target=\"_blank\"> Gargoyle's Black Halberd</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2324","x":0.616826133,"y":0.590452885,"cat":"Weapons","group":"Equipment","title":"Gargoyle's Black Halberd","desc":"Halberd dropped by the <a href='https://eldenring.wiki.fextralife.com/Black+Blade+Kindred' target=\"_blank\"> Black Blade Kindred</a> guarding the entrance to the <a href='https://eldenring.wiki.fextralife.com/Bestial+Sanctum' target=\"_blank\">Bestial Sanctum</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-halberd.png?h=40"},{"id":"3183","x":0.305544499,"y":0.591124331,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Ice Spear","desc":"Ash of War. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> miniboss roaming near the broken bridge upon defeat. Only appears at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"8008","x":0.264193638,"y":0.591521092,"cat":"Weapons","group":"Equipment","title":"Iron Ball","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Blackguard+Big+Boggart'>Blackguard Big Boggart</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fist.png?h=40"},{"id":"1070","x":0.176252764,"y":0.591795776,"cat":"Locations","group":"Locations","title":"Road's End Catacombs","desc":"A tomb found at the end of a narrow path below the western edge of the plateau that the Minor Erdtree is sitting on.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"8715","x":0.183637706,"y":0.591948376,"cat":"Summoning Pools","group":"Locations","title":"Effigy of Martyr: Northwest of Converted Tower Liurnia","desc":"<p>Summoning Pool Effigy located northwest of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Converted+Tower' target=\"\">Converted Tower</a>��in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia' target=\"\">Liurnia</a>��by the tall grass next to the stake of Marika. Activate this effigy to send your summon sign to this summoning pool.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1347","x":0.170912224,"y":0.5924367,"cat":"Bosses","group":"Characters","title":"Spirit-Caller Snail","desc":"Optional Boss. Found at the end of the <a href='https://eldenring.wiki.fextralife.com/Road's+End+Catacombs' target=\"_blank\">Road's End Catacombs</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Glintstone+Sorcerer+Ashes' target=\"_blank\">Glintstone Sorcerer Ashes</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"4547","x":0.261052797,"y":0.592833465,"cat":"Locations","group":"Locations","title":"Boilprawn Shack","desc":"A shack in Liurnia of the Lakes where players can meet <a href='https://eldenring.wiki.fextralife.com/Blackguard+Big+Boggart' target=\"_blank\">Blackguard Big Boggart</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"1077","x":0.180130529,"y":0.592925024,"cat":"Consumables","group":"Items","title":"Rune Arc - Road's End Catacombs","desc":"Consumable. In the room with the boss' door lever, drop down one level and hit the wall under the arch in the back, closest to the stairs to reveal a hidden corridor. The Rune Arc is found on a corpse on the right.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1344","x":0.193921865,"y":0.593199708,"cat":"Key Items","group":"Items","title":"Memory Stone - Converted Tower","desc":"Memory Upgrade Material. Found in a chest on the top floor of the <a href='https://eldenring.wiki.fextralife.com/Converted+Tower' target=\"_blank\">Converted Tower</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"8280","x":0.31595489,"y":0.593535429,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [2] - Liurnia Highway North","desc":"Upgrade Material. One can be looted from a teardrop scarab that explodes upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4545","x":0.258122451,"y":0.593626992,"cat":"Sites of Grace","group":"Locations","title":"Boilprawn Shack","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4549","x":0.26325039,"y":0.593871154,"cat":"NPCs","group":"Characters","title":"Blackguard Big Boggart","desc":"Merchant who sells an item for Rya's quest and can also be summoned for the Magma Wyrm boss fight.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"7605","x":0.257940534,"y":0.594267915,"cat":"Key Items","group":"Items","title":"Spread Out (Gesture)","desc":"Gesture. Unlocked by befriending Blackguard Boggart by purchasing a Boiled Prawn from his shop in Liurnia of the Lakes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1073","x":0.171798049,"y":0.594817279,"cat":"Spirit Ashes","group":"Equipment","title":"Raya Lucaria Soldier Ashes","desc":"Found inside a chest at the end of the <a href='https://eldenring.wiki.fextralife.com/Road's+End+Catacombs' target=\"_blank\">Road's End Catacombs</a>. Hit the final wall to dispel the illusion, allowing you to move on. Beware of the many <a href='https://eldenring.wiki.fextralife.com/Imp' target=\"_blank\">Imps</a> in the final room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"8301","x":0.266995416,"y":0.594933258,"cat":"Armor","group":"Equipment","title":"Blackguard's Iron Mask","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Blackguard Big Boggart'>Blackguard Big Boggart</a>..","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"5414","x":0.193040453,"y":0.595061442,"cat":"Consumables","group":"Items","title":"Magic Grease - 2x Converted Tower","desc":"Consumable Item.Two can be looted from a corpse behind Converted Tower","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3528","x":0.179701369,"y":0.595702369,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [2] - Road's End Catacombs","desc":"Spirit Ash Upgrade Material. In the room with the boss' door lever, drop down one level and hit the wall under the arch in the back, closest to the stairs to dispel it and reveal a hidden corridor where the glovewort can be found.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"1068","x":0.191907045,"y":0.595946531,"cat":"Locations","group":"Locations","title":"Converted Tower","desc":"An abandoned tower, with a few secrets to loot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"3526","x":0.173872706,"y":0.596770576,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [2] - 4x Road's End Catacombs","desc":"Spirit Ash Upgrade Material. A total of 4 are found inside the dungeon. 1) In the room with the boss' door lever, drop down one level to find it on the floor. 2) Found in a corridor to the east of the room with the boss door lever, accessed from the bottom-most floor of the room. 3) From the second glovewort, the third one is found in the right corner by the entrance of the next room. 4) Found just before the illusory wall concealing the boss door.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"1072","x":0.177046779,"y":0.597197859,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [3] - 4x Road's End Catacombs","desc":"Spirit Ash Upgrade Material. A total of 4 are found inside the dungeon. 1) In the room with the boss' door lever, drop down one level to find it on the floor. 2) Just a few steps from the first. 3) In the same room, drop down to the bottom most level and hit the wall under the arch in the back, closest to the stairs to reveal a hidden room. 4) In the next room to the east, near the back.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"7061","x":0.193620331,"y":0.597594624,"cat":"Consumables","group":"Items","title":"Cuckoo Glintstone - 5x Converted Tower","desc":"Consumable Item. Five can be found on a desk, inside the Converted Tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1342","x":0.206524846,"y":0.597869305,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [2]","desc":"Upgrade Material. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> near the edge of the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2826","x":0.62105984,"y":0.597930345,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Dragonbarrow Northeast","desc":"Flask upgrade material. Found along the main road, while heading to the <a href='https://eldenring.wiki.fextralife.com/Bestial+Sanctum' target=\"_blank\">Bestial Sanctum</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"3195","x":0.308371696,"y":0.598113467,"cat":"Key Items","group":"Items","title":"Glintstone Craftsman's Cookbook [3]","desc":"Cookbook Key Item. Found on a corpse on a wooden walkway in an upper level of the <a href='https://eldenring.wiki.fextralife.com/Highway+Lookout+Tower+(Liurnia)' target=\"_blank\">Highway Lookout Tower</a> in <a href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes' target=\"_blank\">Liurnia</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"1067","x":0.190655802,"y":0.598357629,"cat":"Sites of Grace","group":"Locations","title":"Converted Tower (Site of Grace)","desc":"Site of grace by the <a href='https://eldenring.wiki.fextralife.com/Converted+Tower' target=\"_blank\">Converted Tower</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3196","x":0.310508088,"y":0.598510232,"cat":"Weapons","group":"Equipment","title":"Carian Glintblade Staff","desc":"Staff. Found on the top floor of the <a href='https://eldenring.wiki.fextralife.com/Highway+Lookout+Tower+(Liurnia)' target=\"_blank\">Highway Lookout Tower</a> in <a href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes' target=\"_blank\">Liurnia</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"7059","x":0.637506285,"y":0.599151155,"cat":"Consumables","group":"Items","title":"Starlight Shards - Beast Sanctum","desc":"Can be found in front of a stone chalice","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"937","x":0.227303941,"y":0.599273236,"cat":"Sites of Grace","group":"Locations","title":"Folly on the Lake","desc":"Site of Grace inside a gazebo, in the southwestern side of the lake.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8902","x":0.29834008,"y":0.599914164,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily (A) - 4x Liurnia East","desc":"4x can be found in Liurnia East. From the Bird's-Eye Telescope, head east to the gazebo filled with landsquirts by the shoreline. They are just north in the water beside the cliff, near a landsquirt.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3184","x":0.308806379,"y":0.600127804,"cat":"Locations","group":"Locations","title":"Highway Lookout Tower (Liurnia)","desc":"Tower overlooking the highway of Liurnia's eastern landmass.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tower.png?h=40"},{"id":"5934","x":0.17063475,"y":0.601196014,"cat":"Bosses","group":"Characters","title":"Alecto, Black Knife Ringleader","desc":"<p>Field boss imprisoned within the <a href='https://eldenring.wiki.fextralife.com/Ringleader's+Evergaol' target=\"_blank\" rel=\"noopener noreferrer\">Ringleader's Evergaol</a>. Drops the <a class=\"wiki_link\" title=\"Black Knife Tiche Spirit Ashes\" href='https://eldenring.wiki.fextralife.com/Black+Knife+Tiche+Ashes'>Black Knife Tiche Spirit Ashes</a>&nbsp;upon defeat.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"4471","x":0.269221736,"y":0.601652597,"cat":"Bosses","group":"Characters","title":"Deathbird (Liurnia of the Lakes South)","desc":"Only spawns at night. North east of the Scenic Isle site of grace in Liurnia under the ruin wall. It drops the <a href='https://eldenring.wiki.fextralife.com/Red-Feathered+Branchsword' target=\"_blank\">Red-Feathered Branchsword</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6575","x":0.642266611,"y":0.6019285,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily","desc":"Can be found next to a tree on the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6559","x":0.250798291,"y":0.601959019,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"You can found one in In a bush near a stump.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6558","x":0.252557104,"y":0.602233703,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"You can found one between the three.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1057","x":0.24860185,"y":0.602264221,"cat":"Flask Upgrades","group":"Items","title":"Dexterity-knot Crystal Tear","desc":"Physick Flask Material. Found inside a stone receptacle on top of a craggy hill.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"5907","x":0.270998711,"y":0.602722027,"cat":"Talismans","group":"Equipment","title":"Red-Feathered Branchsword","desc":"Dropped by the <a href='https://eldenring.wiki.fextralife.com/Deathbird' target=\"_blank\">Deathbird</a> at <a href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes' target=\"_blank\"> Liurnia of the Lakes</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"7029","x":0.306795703,"y":0.602783068,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Highway Lookout Tower (Liurnia)","desc":"Consumable Item. Held by a corpse in the central area near the tower. Beware of a spirit ambush.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6561","x":0.175764036,"y":0.603393473,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"You can found one, near to the big Rock at the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8279","x":0.315890636,"y":0.603881797,"cat":"Consumables","group":"Items","title":"Crystal Dart - 5x Liurnia Highway North","desc":"Consumable Throwable. Five can be looted off a corpse where a spirit giant spawns and fights regular soldiers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"938","x":0.225586061,"y":0.604016894,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - 2x South from Folly on the Lake","desc":"Upgrade Material. Found on a corpse being eaten by crabs under a large tree, where the poison ground starts after going south from the Folly on the Lake site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2103","x":0.167524229,"y":0.604980526,"cat":"Spirit Ashes","group":"Equipment","title":"Black Knife Tiche","desc":"Spirit Ashes. Dropped by <a href='https://eldenring.wiki.fextralife.com/Alecto,+Black+Knife+Ringleader' target=\"_blank\"> Alecto, Black Knife Ringleader</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6366","x":0.318602911,"y":0.605835093,"cat":"Weapons","group":"Equipment","title":"Lucerne","desc":"East of <ah ref=\"/Highland+Lookout+Tower\" target=\"_blank\">Highland Lookout Tower</a> in East Liurnia of the Lakes, found in the battlefield between phantoms and knights near where the armored giant spawns. Break some carts to reveal the treasure.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-halberd.png?h=40"},{"id":"2101","x":0.173292348,"y":0.605865611,"cat":"Locations","group":"Locations","title":"Ringleader's Evergaol","desc":"Evergaol located at the west of <a href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes' target=\"_blank\"> Liurnia of the Lakes</a>. You can fight <a href='https://eldenring.wiki.fextralife.com/Alecto,+Black+Knife+Ringleader' target=\"_blank\"> Alecto, Black Knife Ringleader</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-evergaol.png?h=40"},{"id":"14301","x":0.299999638,"y":0.605871717,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] - South Liurnia","desc":"Upgrade Material. Found along the south of the waters within Liurnia of the Lakes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"10219","x":0.300557198,"y":0.605896133,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Liurnia Highway Lookout Tower Cliff","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia' target=\"blank\">Liurnia</a>, at the <a class=\"wiki_link\" title=\"Liurnia Highway Lookout Tower\" href=\"Highway Lookout Tower (Liurnia)\">Liurnia Highway Lookout Tower</a> Cliffside.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"6960","x":0.316245831,"y":0.606079255,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Liurnia Highway North","desc":"Consumable Item. Held by a corpse near the armored giant spawn.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7014","x":0.317565516,"y":0.607818907,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Liurnia Highway North","desc":"Consumable Item. Held by a corpse near the <em>armored giant</em> spawn.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2107","x":0.622370432,"y":0.60907024,"cat":"Consumables","group":"Items","title":"Dragon Heart (Flying Dragon Greyll)","desc":"Key Consumable. Dropped by <a href='https://eldenring.wiki.fextralife.com/Flying+Dragon+Greyll' target=\"_blank\">Flying Dragon Greyll</a> upon defeat. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6127","x":0.279055264,"y":0.609436483,"cat":"NPCs","group":"Characters","title":"Rya (First Location)","desc":"Npc. She can be found next to the telescope. She is runnng an errand for the Volcano Manor but was robbed. She asks you to retrieve <a href='https://eldenring.wiki.fextralife.com/Rya's+Necklace' target=\"_blank\">Rya's Necklace</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"10221","x":0.17990114,"y":0.609985847,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Ringleader's Evergaol","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia' target=\"blank\">Liurnia</a>, directly Southeast <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Ringleader's+Evergaol' target=\"blank\">Ringleader's Evergaol</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"1348","x":0.625973313,"y":0.610474171,"cat":"Bosses","group":"Characters","title":"Flying Dragon Greyll","desc":"Optional Dragon Boss guarding the bridge to the <a href='https://eldenring.wiki.fextralife.com/Bestial+Sanctum' target=\"_blank\">Bestial Sanctum</a>. Drops a <a href='https://eldenring.wiki.fextralife.com/Dragon+Heart' target=\"_blank\">Dragon Heart</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3200","x":0.265078202,"y":0.610993014,"cat":"Sites of Grace","group":"Locations","title":"Scenic Isle","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4263","x":0.17997457,"y":0.611450819,"cat":"Key Items","group":"Items","title":"Chelona's Rise Turtle Marker 3","desc":"Giant Ghostly Turtle #3. One of three required to break the seal to <a href='https://eldenring.wiki.fextralife.com/Chelona's+Rise'>Chelona's Rise</a>. Found flying high above in the air southeast of Ringleader's Evergaol. You can use a bow to hit it or use the Spiritspring nearby to jump with Torrent and hit it while in the air.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"5601","x":0.618099174,"y":0.611969662,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [9] - Farum Greatbridge","desc":"Upgrade Material. Dropped by a Teardrop Scarab found to the west of Farum Greatbridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"9839","x":0.624000177,"y":0.612052532,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Farum Greatbridge","desc":"Summoning Pool Effigy around the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Bestial+Sanctum' target=\"blank\">Bestial Sanctum</a> area where <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Flying+Dragon+Greyll' target=\"blank\">Flying Dragon Greyll</a> is encountered. It is located next to the Farum Greatbridge Site of Grace. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4149","x":0.203015395,"y":0.612213824,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] - 1x Moonfolk Ruins","desc":"Upgrade Material. One found in a chest inside an underground treasure room in the northest section of the ruins. The entrance is concealed by an illusory floor. Hit the floor to reveal the stairs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3272","x":0.266270108,"y":0.612366427,"cat":"NPCs","group":"Characters","title":"Patches (First Liurnia Location)","desc":"Location of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/patches'>Patches</a> if forgiven during the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/bosses'>Bossfight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"2323","x":0.628778395,"y":0.613098913,"cat":"Sites of Grace","group":"Locations","title":"Farum Greatbridge","desc":"Site of grace of the Farum Greatbridge","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1890","x":0.212542679,"y":0.613251512,"cat":"Consumables","group":"Items","title":"Dragon Heart (Glintstone Dragon Adula)","desc":"Key Consumable. <strong>3 Hearts</strong> by <a href='https://eldenring.wiki.fextralife.com/Glintstone+Dragon+Adula' target=\"_blank\"> Glintstone Dragon Adula</a> upon defeating it at the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Manus+Celes' target=\"_blank\">Cathedral of Manus Celes</a>. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1893","x":0.21018442,"y":0.613343075,"cat":"Spells","group":"Equipment","title":"Adula's Moonblade","desc":"Dropped by the <a href='https://eldenring.wiki.fextralife.com/Glintstone+Dragon+Adula' target=\"_blank\"> Glintstone Dragon Adula</a> in the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Manus+Celes' target=\"_blank\"> Cathedral of Manus Celes</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"1417","x":0.215708194,"y":0.614380764,"cat":"Locations","group":"Locations","title":"Cathedral of Manus Celes","desc":"Located at South West <a target=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes'>Liurnia of The Lakes</a>. Accessible only after making significant progress in <a href='https://eldenring.wiki.fextralife.com/Ranni' target=\"_blank\">Ranni</a>'s questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cathedral.png?h=40"},{"id":"8843","x":0.222451507,"y":0.614411282,"cat":"NPCs","group":"Characters","title":"Ranni the Witch (2nd Location)","desc":"<p>�� Ranni the Witch can be found in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Cathedral+of+Manus+Celes' target=\"\">Cathedral of Manus Celes</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"1509","x":0.318907858,"y":0.614502845,"cat":"Sites of Grace","group":"Locations","title":"Liurnia Highway North","desc":"Site of Grace found on the side of the road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1454","x":0.227791481,"y":0.615265849,"cat":"Weapons","group":"Equipment","title":"Dark Moon Greatsword","desc":"<a href='https://eldenring.wiki.fextralife.com/Greatswords' target=\"_blank\">Greatsword</a>. Found below the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Manus+Celes' target=\"_blank\"> Cathedral of Manus Celes</a> after progressing <a href='https://eldenring.wiki.fextralife.com/Ranni' target=\"_blank\">Ranni</a>'s questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"4126","x":0.221292153,"y":0.615510011,"cat":"Sites of Grace","group":"Locations","title":"Cathedral of Manus Celes","desc":"Site of Grace found in the center of the Cathedral of Manus Celes","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4138","x":0.223703559,"y":0.615571052,"cat":"Consumables","group":"Items","title":"Starlight Shards - 10x Cathedral of Manus Celes","desc":"Consumable Item. 9 can be found all around the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Manus+Celes' target=\"_blank\">Cathedral of Manus Celes</a>. One more can be found outside the cathedral, in the north by the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4115","x":0.20121317,"y":0.615906776,"cat":"Locations","group":"Locations","title":"Moonfolk Ruins","desc":"Ruins found in the southwest of the Liurnia of the Lakes region","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"1418","x":0.211150592,"y":0.616059376,"cat":"Bosses","group":"Characters","title":"Glintstone Dragon Adula (Cathedral of Manus Celes)","desc":"Great Enemy. This dragon is first found roaming the <a href='https://eldenring.wiki.fextralife.com/Three+Sisters' target=\"_blank\">Three Sisters</a> sub-region in the north. After dealing enough damage to it, it will teleport here outside the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Manus+Celes' target=\"_blank\">Cathedral of Manus Celes</a>. Drops 3x <a href='https://eldenring.wiki.fextralife.com/Dragon+Heart' target=\"_blank\">Dragon Hearts</a> and the <a href='https://eldenring.wiki.fextralife.com/Adula's+Moonblade' target=\"_blank\">Adula's Moonblade</a> spell upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"7015","x":0.198015201,"y":0.616791862,"cat":"Consumables","group":"Items","title":"Golden Rune [9] - Moonfolk Ruins","desc":"Held by a corpse in one of the edges of the structure.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"14152","x":0.515327038,"y":0.61749383,"cat":"Locations","group":"Locations","title":"Caelid Colosseum","desc":"Found in Northern Caelid, North of the Deep Siofra River Well Site of Grace, near The Great-Jar's location.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-location_41.png?h=40"},{"id":"1336","x":0.204236192,"y":0.61871464,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - 2x Under Village of the Albinaurics","desc":"Upgrade Material. Two can be found on a corpse being eaten by crabs between a wall and a tree in the swamp directly under Village of the Albinaurics","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1060","x":0.206675856,"y":0.618806198,"cat":"Bosses","group":"Characters","title":"Omenkiller (Village of the Albinaurics)","desc":"Field Boss.Found at the <a href='https://eldenring.wiki.fextralife.com/Village+of+the+Albinaurics' target=\"_blank\">Village of the Albinaurics</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Crucible+Knot+Talisman' target=\"_blank\">Crucible Knot Talisman</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"754","x":0.311675379,"y":0.619477644,"cat":"Waygates","group":"Locations","title":"Purified Ruins Waygate","desc":"Leads to the entrance of the Academy","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"5906","x":0.209206956,"y":0.619569207,"cat":"Talismans","group":"Equipment","title":"Crucible Knot Talisman","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Omenkiller' target=\"_blank\">Omenkiller</a>, located in the <a href='https://eldenring.wiki.fextralife.com/Village+of+the+Albinaurics' target=\"_blank\">Village of the Albinaurics</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1503","x":0.285365753,"y":0.62021013,"cat":"Key Items","group":"Items","title":"Ritual Pot - Laskyar Ruins","desc":"Special Tool Key Item. Found on a corpse in the northern section of the <a href='https://eldenring.wiki.fextralife.com/Laskyar+Ruins' target=\"_blank\">Laskyar Ruins</a>, in front of a set of pillars.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"1504","x":0.280126581,"y":0.620240652,"cat":"Consumables","group":"Items","title":"Wraith Calling Bell","desc":"Offensive Consumable Item. Found in a chest in a small room of an underground aea in the northwestern section of the <a href='https://eldenring.wiki.fextralife.com/Laskyar+Ruins' target=\"_blank\">Laskyar Ruins</a>. Find a set of steps leading downwards to locate the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6562","x":0.200389158,"y":0.620545855,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily - Village of the Albinaurics","desc":"You can found one at the swamp, also there are 9 near to the big tree, and another one behind the giant rock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1055","x":0.233954963,"y":0.620637414,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Vow of the Indomitable","desc":"Dropped by a Teardrop Scarab, in the southwestern swampy area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"8218","x":0.308348671,"y":0.620881576,"cat":"Crafting Materials","group":"Items","title":"Mushroom - 5x Purified Ruins North","desc":"Crafting Material. Four can be looted from a corpse guarded by two zombie dogs north from Purified Ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8783","x":0.207987433,"y":0.621308859,"cat":"Crafting Materials","group":"Items","title":"Albinauric Bloodclot - Village of the Albinaurics","desc":"Crafting Material. One can be looted from a corpse behind a tree across the hanging wooden bridge heading toward the light from Village of the Albinaurics site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6560","x":0.285188718,"y":0.621583543,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"You can found x2 between two ruins","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1056","x":0.209451004,"y":0.621705624,"cat":"Weapons","group":"Equipment","title":"Crystal Sword","desc":"CStraight Sword. Can be found at <a herf=\"/Village+of+the+Albinaurics\" target=\"_blank\">Village of the Albinaurics</a>. Past the well and the wooden bridge, on a body near the edge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"1062","x":0.205363445,"y":0.621980305,"cat":"Locations","group":"Locations","title":"Village of the Albinaurics","desc":"An abandoned Village found within the cavernous depths of Liurnia's poison swamp.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-location_53.png?h=40"},{"id":"1502","x":0.28253512,"y":0.623353718,"cat":"Locations","group":"Locations","title":"Laskyar Ruins","desc":"Ruins found in the marshes south of the lake.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"1063","x":0.202068119,"y":0.623384236,"cat":"Sites of Grace","group":"Locations","title":"Village of the Albinaurics (Site of Grace)","desc":"Site of Grace for the Village of Albinaurics","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1505","x":0.279145813,"y":0.62353684,"cat":"Waygates","group":"Locations","title":"Laskyar Ruins Waygate","desc":"A Waygate that transports the user to the <a href='https://eldenring.wiki.fextralife.com/Raya+Lucaria+Academy' target=\"_blank\">Raya Lucaria Academy</a>'s main entrance. Found in a gazebo in the center of the <a href='https://eldenring.wiki.fextralife.com/Laskyar+Ruins' target=_blank\">Laskyar Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"1061","x":0.210854675,"y":0.624421925,"cat":"Consumables","group":"Items","title":"Rune Arc - Village of the Albinaurics","desc":"After fighting <a href='https://eldenring.wiki.fextralife.com/Omenkiller' target=\"_blank\">Omenkiller</a>, turn to the right and you will find it at the end of the path, on a body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8202","x":0.20124385,"y":0.624666087,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Village of the Albinaurics","desc":"Summoning Pool Effigy found directly north of the Village of the Albinaurics site of grace in Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1059","x":0.204603348,"y":0.625276492,"cat":"Key Items","group":"Items","title":"Larval Tear - Village of the Albinaurics","desc":"Key Item. Can be found at the graveyard in the <a href='https://eldenring.wiki.fextralife.com/Village+of+the+Albinaurics target='_blank\">Village of the Albinaurics</a>, near the town well.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6118","x":0.516244164,"y":0.625276492,"cat":"NPCs","group":"Characters","title":"The Great-Jar","desc":"Interact with the Great-Jar to fight three invading Npcs. If you beat all three of them, you will receive the <a href='https://eldenring.wiki.fextralife.com/Great-Jar's+Arsenal' target=\"_blank\"> Great-Jar's Arsenal</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"2817","x":0.20878251,"y":0.626100541,"cat":"Key Items","group":"Items","title":"Haligtree Secret Medallion (Right)","desc":"Key Item. Hit <a href='https://eldenring.wiki.fextralife.com/Albus' target=\"_blank\">Albus</a>, who is disguised as a pot past the Perfumer guarding the path up from the <a href='https://eldenring.wiki.fextralife.com/Village+of+the+Albinaurics' target=\"_blank\">Village of the Albinaurics</a> Site of Grace. This medallion opens the path to a secret location past Lyndell.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"5930","x":0.638665464,"y":0.626100541,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Bloodhound's Step","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> at the bridge in front of the <a href='https://eldenring.wiki.fextralife.com/Lenne's+Rise' target=\"_blank\"> Lenne's Rise</a> tower,","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"1506","x":0.279939941,"y":0.626131059,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] - Laskyar Ruins","desc":"Upgrade Material. Found on a corpse to the right of the steps to the gazebo in the center of the <a href='https://eldenring.wiki.fextralife.com/Laskyar+Ruins' target=\"_blank\">Laskyar Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3220","x":0.286876737,"y":0.626466784,"cat":"Key Items","group":"Items","title":"Glintstone Craftsman's Cookbook [2]","desc":"Found in a corpse just by the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Laskyar+Ruins'>Laskyar Ruins</a> Site of Grace. Unlocks crafting of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Freezing+Grease'>Freezing Grease</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"3217","x":0.285951588,"y":0.626588865,"cat":"Sites of Grace","group":"Locations","title":"Laskyar Ruins","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6124","x":0.200786513,"y":0.626771987,"cat":"NPCs","group":"Characters","title":"Nepheli Loux (Second Location)","desc":"NPC. If her quest is being progressed, she can be found at the <a href='https://eldenring.wiki.fextralife.com/Village+of+the+Albinaurics' target=\"_blank\">Village of the Albinaurics</a> after meeting her at the <a href='https://eldenring.wiki.fextralife.com/Roundtable+Hold' target=\"_blank\">Roundtable Hold</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"7604","x":0.283602332,"y":0.626833027,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [2] - Laskyar Ruins drop","desc":"Upgrade Material. Dropped by the Grafted Scion enemy that spawns in the middle of Laskyar Ruins before the Waygate Gazebo.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"4143","x":0.221994799,"y":0.626894068,"cat":"Talismans","group":"Equipment","title":"Cerulean Amber Medallion +2","desc":"Upgraded Talisman. Found in an underground room in the northwest section of the <a href='https://eldenring.wiki.fextralife.com/Lunar+Estate+Ruins' target=\"_blank\">Lunar Estate Ruins</a>. The entrance is sealed by both an Imp Statue that requires 1 <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a>, as well as an illusory floor that can be dispelled with an attack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1058","x":0.208537736,"y":0.627534991,"cat":"Weapons","group":"Equipment","title":"Ivory Sickle","desc":"Dagger. Can be found at the <a href=\"Village+of+the+Albinaurics\" target=\"_blank\">Village of the Albinaurics</a>.It is up a small hill from the Site of Grace, past a perfumer enemy, behind a coffin. Nearby, Albus hides as a pot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"6122","x":0.206127498,"y":0.627596032,"cat":"NPCs","group":"Characters","title":"Albus","desc":"NPC who is hiding from the calamity that befell the <a href='https://eldenring.wiki.fextralife.com/Village+of+the+Albinaurics' target=\"_blank\">Village of the Albinaurics</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"2816","x":0.199961821,"y":0.627779153,"cat":"Weapons","group":"Equipment","title":"Stormhawk Axe","desc":"2x Found under the bridge leading from the swamp up to <a href='https://eldenring.wiki.fextralife.com/Village+of+the+Albinaurics' target=\"_blank\">Village of the Albinaurics</a> if Nepheli Leux has died.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-axe.png?h=40"},{"id":"1501","x":0.305053256,"y":0.627931756,"cat":"NPCs","group":"Characters","title":"Hyetta (Second Location)","desc":"<a href='https://eldenring.wiki.fextralife.com/Hyetta' target=\"_blank\">Hyetta</a>, Location 2. She is found at the western side of the <a href='https://eldenring.wiki.fextralife.com/Purified+Ruins' target=\"_blank\">Purified Ruins</a>. She asks for another <a href='https://eldenring.wiki.fextralife.com/Shabriri+Grape' target=\"_blank\">Shabriri Grape</a> but does not give any reward this time.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6563","x":0.203165981,"y":0.628023315,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily","desc":"Can be found near the <a href='https://eldenring.wiki.fextralife.com/Village+of+the+Albinaurics' target=\"_blank\">Village of the Albinaurics</a> before the bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5753","x":0.514931807,"y":0.628145396,"cat":"Talismans","group":"Equipment","title":"Great-Jar's Arsenal","desc":"Reward for completing the 3 duelist NPC invasions in Dragonbarrow (Caelid North) for The Great-Jar. You will only be able to access this area by coming up from Siofra Deep River Well in the underground.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"5719","x":0.312620929,"y":0.628175918,"cat":"Locations","group":"Locations","title":"Purified Ruins","desc":"A set of ruins along the lake shore of the eastern landmass.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"750","x":0.314788205,"y":0.62835904,"cat":"Consumables","group":"Items","title":"Cuckoo Glintstone - 4x Purified Ruins","desc":"Consumable Item. Four can be found on a dead body, against a wall within Purified Ruins. Beware of the group of Soldiers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6068","x":0.638573904,"y":0.628816842,"cat":"Bosses","group":"Characters","title":"Night's Cavalry (Dragonbarrow East)","desc":"Boss that spawns only at night. Drops Ash of War: Bloodhound's Step.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"8193","x":0.327115493,"y":0.628938923,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Cliffbottom Catacombs","desc":"Summoning Pool Effigy found in front of the Boss Doors of the Cliffbottom Catacombs in Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4254","x":0.233589913,"y":0.629061004,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - 3x Lunar Estate Ruins","desc":"Upgrade Material. Three can be found in a chest in an underground area concealed by an illusory floor on the eastern side of the ruins. Attack the floor to reveal the path.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4139","x":0.22553318,"y":0.62973245,"cat":"Locations","group":"Locations","title":"Lunar Estate Ruins","desc":"The ruins of a large estate found in the southern plateau of <a href='https://eldenring.wiki.fextralife.com/Liurnia' target=\"_blank\">Liurnia</a>, accessible only after making significant progress in <a href='https://eldenring.wiki.fextralife.com/Ranni' target=\"_blank\">Ranni</a>'s questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"5904","x":0.328947024,"y":0.62979349,"cat":"Weapons","group":"Equipment","title":"Scythe","desc":"Found in <a href='https://eldenring.wiki.fextralife.com/Cliffbottom+Catacombs' target=\"_blank\">Cliffbottom Catacombs</a>: toward the end of the dungeon, find a staircase to go up into a room with some Imps and a trap.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-reaper.png?h=40"},{"id":"2949","x":0.331109031,"y":0.629946093,"cat":"Bosses","group":"Characters","title":"Erdtree Burial Watchdog (Cliffbottom Catacombs)","desc":"Optional Boss found at the end of the <a href='https://eldenring.wiki.fextralife.com/Cliffbottom+Catacombs' target=\"_blank\">Cliffbottom Catacombs</a>. Drops the <a href=\"Kaiden+Sellsword+Ashes\" target=\"_blank\">Kaiden Sellsword Ashes</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"4142","x":0.222086004,"y":0.630129214,"cat":"Consumables","group":"Items","title":"Golden Rune [10] - Lunar Estate Ruins","desc":"Rune Consumable. Found on a corpse near the central section of the <a href='https://eldenring.wiki.fextralife.com/Lunar+Estate+Ruins' target=\"_blank\">Lunar Estate Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"917","x":0.30868422,"y":0.630190255,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Purified Ruins","desc":"Found in the Purified Ruins. On a body, against a few barrels in a narrow corridor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8850","x":0.188151422,"y":0.630220773,"cat":"Consumables","group":"Items","title":"Dragon Heart (Moonlight Altar Dragons)","desc":"<p>Key Consumable. Dropped by Dragons upon defeat. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\" rel=\"noopener noreferrer\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\" rel=\"noopener noreferrer\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\" rel=\"noopener noreferrer\">Cathedral of Dragon Communion</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1407","x":0.199809635,"y":0.630953259,"cat":"Sites of Grace","group":"Locations","title":"Moonlight Altar","desc":"Site of Grace located outside of the <a href='https://eldenring.wiki.fextralife.com/Deep+Ainsel+Well' target=\"_blank\">Deep Ainsel Well</a>'s exit point, high above the Moonlight Altar plateau in the southwest of <a target=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+lakes'>Liurnia of The Lakes</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1535","x":0.327298805,"y":0.631136381,"cat":"Sites of Grace","group":"Locations","title":"Cliffbottom Catacombs","desc":"Site of grace at the entrance of the Cliffbottom Catacombs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8223","x":0.325501875,"y":0.631136381,"cat":"Consumables","group":"Items","title":"Rune Arc - 1x Cliffbottom Catacombs","desc":"Consumable. Found on a corpse on a dead-end chamber within Cliffbottom Catacombs, near the Stone Sword Key Imp gate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"751","x":0.31506182,"y":0.631288984,"cat":"Key Items","group":"Items","title":"Shabriri Grape - Purified Ruins","desc":"Can be found in a hidden cellar. The path is blocked by debris and barrels that you can roll onto or attack to destroy. Once downstairs, you can find it on your left.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1880","x":0.332911694,"y":0.631319502,"cat":"Spirit Ashes","group":"Equipment","title":"Kaiden Sellsword Ashes","desc":"Found within <a href='https://eldenring.wiki.fextralife.com/Cliffbottom+Catacombs' target=\"_blank\">Cliffbottom Catacombs</a>. Dropped by Erdtree Burial Watchdog.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"8227","x":0.331719429,"y":0.631594187,"cat":"Crafting Materials","group":"Items","title":"Old Fang - 3x Cliffbottom Catacombs","desc":"Crafting Material. Found on a corpse by the lever that opens the Boss Room Door in Cliffbottom Catacombs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7013","x":0.322877165,"y":0.631655227,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Liurnia Highway South","desc":"Dropped from a balloon in the deluged area of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/liurnia+of+the+lakes'>Liurnia of the Lakes</a> that has some enemies attached to it. Defeat all of them and destroy the balloon to obtain the <strong>Golden Rune (6)</strong>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1419","x":0.254454171,"y":0.632051988,"cat":"Key Items","group":"Items","title":"Fire Monks' Prayerbook","desc":"Incantation Tome. Found on a corpse in an enemy outpost in the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tome.png?h=40"},{"id":"752","x":0.31329261,"y":0.632113029,"cat":"Talismans","group":"Equipment","title":"Two Fingers Heirloom","desc":"Talisman. Found in a chest inside a hidden cellar in the <a href='https://eldenring.wiki.fextralife.com/Purified+Ruins' target=\"_blank\">Purified Ruins</a>. The cellar entrance is concealed by wooden planks and barrels that you can roll onto or attack to destroy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1533","x":0.330411197,"y":0.632540312,"cat":"Locations","group":"Locations","title":"Cliffbottom Catacombs","desc":"Catacombs found at the bottom of the cliffs in the eastern side of the Liurnia of the Lakes region, now infested by Imps and Ogres","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"8221","x":0.328000123,"y":0.632814997,"cat":"Crafting Materials","group":"Items","title":"Root Resin - 5x Cliffbottom Catacombs","desc":"Crafting Material. Five can be looted from a corpse in the first chamber after descending the lift into Cliffbottom Catacombs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6662","x":0.326597729,"y":0.632906555,"cat":"Key Items","group":"Items","title":"Prattling Pate (Wonderful)","desc":"Found in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/cliffbottom+catacombs'>Cliffbottom Catacombs</a>, in the very bottom level of the large multi-leveled hall. You can drop down to this level via the gap on either side of the central stair-bridge. Check around the corridors here for several items, one of which is the Prattling Pate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"8225","x":0.332063658,"y":0.632967596,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - 1x Cliffbottom Catacombs","desc":"Consumable Item. Found on a corpse on the higher level of Cliffbottom Catacombs, after an ambush by two Imps and next to a Glovewort (3).","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8194","x":0.257994481,"y":0.63345592,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Lakeside Crystal Cave","desc":"Summoning Pool Effigy found next to the Lakeside Crystal Cave site of grace in Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5653","x":0.334043321,"y":0.633547483,"cat":"Armor","group":"Equipment","title":"Nox Mirrorhelm","desc":"Helmet. Found in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/cliffbottom+catacombs'>Cliffbottom Catacombs</a>: In the sealed room, accessible by using a <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Stonesword+Key'>Stonesword Key</a> at the Imp Statue.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"4205","x":0.174849291,"y":0.634188406,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] - 3x Moonlight Altar","desc":"Upgrade Material. 3 more are found in the right-most gazebo by the cliffs in this area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6557","x":0.323574737,"y":0.634249447,"cat":"Crafting Materials","group":"Items","title":"Stormhawk Feather","desc":"Found on a corpse by the road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2956","x":0.198894461,"y":0.634279969,"cat":"Locations","group":"Locations","title":"Deep Ainsel Well","desc":"A small structure that houses a lift that takes players back underground to <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Astel+Naturalborn+of+the+Void'>Astel, Naturalborn of the Void's</a> boss room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-well.png?h=40"},{"id":"3516","x":0.327938763,"y":0.634920892,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [2] - 4x Cliffbottom Catacombs","desc":"Spirit Ash Upgrade Material. The first is found by facing east while riding down the lift by the entrance and jumping onto a small balcony as the lift passes it by. The second one is found by turning the corner in the corridor to the right of the boss door. The third one is found by heading up the stairs to the right of the door sealed by an Imp Statue and following the path to an alcove in a small room at the end. The final one is found along a corridor leading up to the room with a ladder to the library.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"3520","x":0.330624513,"y":0.635165054,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [3] - Cliffbottom Catacombs","desc":"Spirit Ash Upgrade Material. In the large multi-level hall, drop down to the very bottom via the gaps on either side of the central stair-bridge. Check around the corridors of this bottom pit for several items, one of which is a Ghost Glovewort (3).","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5418","x":0.332392856,"y":0.635195576,"cat":"Spirit Ashes","group":"Equipment","title":"Page Ashes","desc":"Spirit Ashes. Found in Cliffbottom Catacombs, in an altar right before you pull the lever to open the Boss Door.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"3518","x":0.329403716,"y":0.635378698,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [3] - 4x Cliffbottom Catacombs","desc":"Spirit Ash Upgrade Material. The first one is found in the large room with the Imp Statue seal - Check the area behind the stairs leading up to the Imp Statue. The second one is found in a narrow corridor on the top level of the multi-leveled hall where you can see the boss lever statue. In the same multi-leveled hall, drop down onto the central stair-bridge and then drop further down into the pit below and check the corridors for the third and fourth Grave Glovewort (3).","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"4269","x":0.257511768,"y":0.635378698,"cat":"Sites of Grace","group":"Locations","title":"Lakeside Crystal Cave","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4268","x":0.260929947,"y":0.6358365,"cat":"Locations","group":"Locations","title":"Lakeside Crystal Cave","desc":"Small cave south from the Scenic Isle Site of Grace in Liurnia of the Lakes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"4271","x":0.255827568,"y":0.636294306,"cat":"Bosses","group":"Characters","title":"Bloodhound Knight","desc":"Found within <a href='https://eldenring.wiki.fextralife.com/Lakeside+Crystal+Cave' target=\"_blank\">Lakeside Crystal Cave</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Cerulean+Amber+Medallion' target=\"_blank\">Cerulean Amber Medallion</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"7202","x":0.258031797,"y":0.636660549,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - Lakeside Crystal Cave","desc":"<p><a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Smithing+Stone+(4)' target=\"\">Smithing Stone (4)</a> and <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Smithing+Stone+(2)' target=\"\">Smithing Stone (2)</a> are Looted from two corpses on one of the lower levels of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Lakeside+Crystal+Cave' target=\"\">Lakeside Crystal Cave</a>, just before the fog gate.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"7201","x":0.257143562,"y":0.636813148,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] - Lakeside Crystal Cave","desc":"<p><a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Smithing+Stone+(4)' target=\"\">Smithing Stone (4)</a> and <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Smithing+Stone+(2)' target=\"\">Smithing Stone (2)</a>are Looted from two corpses on one of the lower levels of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Lakeside+Crystal+Cave' target=\"\">Lakeside Crystal Cave</a>, just before the fog gate.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"7907","x":0.268216338,"y":0.636813148,"cat":"Consumables","group":"Items","title":"Ballista Bolt","desc":"Ammo Item. Found by a cart alongside the road leading to the Evergaol","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6564","x":0.246008539,"y":0.63684367,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found near to the bat, in front cliffside.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5959","x":0.624966778,"y":0.63699627,"cat":"Spells","group":"Equipment","title":"Bestial Constitution","desc":"<a href='https://eldenring.wiki.fextralife.com/Bestial+Incantations' target=\"_blank\">Bestial Incantation</a>. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> along the cliffside northeast of the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Dragonbarrow)' target=\"_blank\">Minor Erdtree</a> in <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow'>Dragonbarrow</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"3154","x":0.571811608,"y":0.637026792,"cat":"Weapons","group":"Equipment","title":"Godslayer's Greatsword","desc":"Greatsword found in a chest in a room behind the <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle' target=\"_blank\">Godskin Apostle's</a> arena at the <a href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+Caelid' target=\"_blank\">Divine Tower of Caelid</a> after defeating him.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"3040","x":0.573948,"y":0.63711835,"cat":"Sites of Grace","group":"Locations","title":"Divine Tower of Caelid: Center","desc":"Site of Grace found on a balcony in the middle floor of the Divine Tower. This is where you enter the tower initially by carefully platforming along the outer edge of the tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2321","x":0.640040244,"y":0.637423553,"cat":"Sites of Grace","group":"Locations","title":"Lenne's Rise. (Site of Grace)","desc":"Site of Grace at the entrance of Lenne's Rise","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4272","x":0.253788977,"y":0.637667715,"cat":"Talismans","group":"Equipment","title":"Cerulean Amber Medallion","desc":"Talisman dropped by <a href='https://eldenring.wiki.fextralife.com/Bloodhound+Knight' target=\"_blank\">Bloodhound Knight</a>, the miniboss of <a href='https://eldenring.wiki.fextralife.com/Lakeside+Crystal+Cave' target=\"_blank\">Lakeside Crystal Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3153","x":0.569247934,"y":0.637942399,"cat":"Armor","group":"Equipment","title":"Godskin Apostle Set","desc":"Armor set comprised of the <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle+Hood' target=\"_blank\">Godskin Apostle Hood</a>, <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle+Robe' target=\"_blank\">Godskin Apostle Robe</a>, <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle+Bracers' target=\"_blank\">Godskin Apostle Bracers</a> and <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle+Trousers' target=\"_blank\">Godskin Apostle Trousers</a>. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle' target=\"_blank\">Godskin Apostle</a> boss at the bottom of the <a href=\"Divine+Tower+of+Caelid\" target=\"_blank\">Divine Tower of Caelid</a> upon his defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"4270","x":0.262761962,"y":0.637942399,"cat":"Talismans","group":"Equipment","title":"Spear Talisman","desc":"Talisman found in a chest within <a href='https://eldenring.wiki.fextralife.com/Lakeside+Crystal+Cave' target=\"_blank\">Lakeside Crystal Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4202","x":0.17539865,"y":0.638400201,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8] - 3x Moonlight Altar","desc":"Upgrade Material. 3 are found in the central gazebo by the cliffs in this area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"10218","x":0.293353552,"y":0.638735926,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: South Liurnia Lake Shore","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia' target=\"blank\">Liurnia</a>, next to Liurnia Highway South","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"6884","x":0.575652163,"y":0.639102169,"cat":"Consumables","group":"Items","title":"Golden Rune [12] - Divine Tower of Caelid","desc":"Held by a corpse under a broken pillar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4207","x":0.179304424,"y":0.63949893,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] - 3x Moonlight Altar","desc":"Upgrade Material. 3 are found in the left-most gazebo by the cliffs in this area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2322","x":0.645502751,"y":0.639590493,"cat":"Locations","group":"Locations","title":"Lenne's Rise","desc":"Tower located at the eastern part of Caelid.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"3152","x":0.568118697,"y":0.639773614,"cat":"Bosses","group":"Characters","title":"Godskin Apostle (Caelid)","desc":"Great Enemy. Found at the basement of the <a href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+Caelid' target=\"_blank\">Divine Tower of Caelid</a> (See page for how to reach). Drops the <a href='https://eldenring.wiki.fextralife.com/Godskin+Apostle+Set' target=\"_blank\">Godskin Apostle Set</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"1051","x":0.301300516,"y":0.639895695,"cat":"Maps","group":"Locations","title":"Map (Liurnia, East)","desc":"It's in the middle of the swampy lake, by a monument that has highlightened texts over it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"5654","x":0.637926993,"y":0.640261938,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Caelid's North East Sarcophagi","desc":"Rune Consumable. Found among a cluster of sarcophagi high up on a cliff. You can reach this area by using the Spiritspring at <a href='https://eldenring.wiki.fextralife.com/Lenne's+Rise' target=\"_blank\">Lenne's Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6408","x":0.33297491,"y":0.640475578,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [2] - 2x Eastern Liurnia of the Lakes Cliffs","desc":"Upgrade Material. Two can be found on a corpse sitting on a chair by the cliffs to the southeast of Liurnia of the Lakes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4277","x":0.647520856,"y":0.6405061,"cat":"Key Items","group":"Items","title":"Memory Stone - Lenne's Rise","desc":"Memory Slot Upgrade Item. Found in a chest at the top of <a href='https://eldenring.wiki.fextralife.com/Lenne's+Rise' target=\"_blank\">Lenne's Rise</a>. The entrance to the tower is sealed but you can use a Spiritspring in the back of the tower to land on a balcony and gain entry.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"3038","x":0.572755954,"y":0.640567141,"cat":"Locations","group":"Locations","title":"Divine Tower of Caelid","desc":"Divine Tower located in central <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a>. Accessed via careful platforming.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-divinetower.png?h=40"},{"id":"5656","x":0.63643152,"y":0.640841822,"cat":"Consumables","group":"Items","title":"Golden Rune [8]","desc":"Rune Consumable. Found among a cluster of sarcophagi high up on a cliff. You can reach this area by using the Spiritspring at <a href='https://eldenring.wiki.fextralife.com/Lenne's+Rise' target=\"_blank\">Lenne's Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5950","x":0.265962192,"y":0.641085983,"cat":"Spirit Ashes","group":"Equipment","title":"Latenna the Albinauric","desc":"In order for Latenna to be friendly and become a spirit, one has to have the <a href='https://eldenring.wiki.fextralife.com/Haligtree+Secret+Medallion+(Right)' target=\"_blank\"> Haligtree Secret Medallion (Right)</a>, give to the player by Albus at the <a href='https://eldenring.wiki.fextralife.com/Village+of+the+Albinaurics' target=\"_blank\"> Village of the Albinaurics</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6576","x":0.643425548,"y":0.641147024,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Lenne's+Rise' target=\"_blank\">Lenne's Rise</a> , under the arch tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7060","x":0.26150943,"y":0.641269105,"cat":"Consumables","group":"Items","title":"Rune Arc - Southern Liurnia of the Lakes","desc":"Can be found on some scaffolind behind the <a href='https://eldenring.wiki.fextralife.com/Slumbering+Wolf's+Shack' target=\"_blank\">Slumbering Wolf's Shack</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6870","x":0.639795911,"y":0.641696389,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - Caelid's North East Sarcophagi","desc":"Rune Consumable. Found among a cluster of sarcophagi high up on a cliff. You can reach this area by using the Spiritspring at <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/lenne's+rise'>Lenne's Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6883","x":0.575870756,"y":0.641757429,"cat":"Consumables","group":"Items","title":"Numen's Rune - Divine Tower of Caelid","desc":"Found on the backside of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/divine+tower+of+caelid'>Divine Tower of Caelid</a>. This requires some jumping and ladder puzzles.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5655","x":0.638086707,"y":0.641787951,"cat":"Consumables","group":"Items","title":"Golden Rune [6]","desc":"Rune Consumable. Found among a cluster of sarcophagi high up on a cliff. You can reach this area by using the Spiritspring at <a href='https://eldenring.wiki.fextralife.com/Lenne's+Rise' target=\"_blank\">Lenne's Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5426","x":0.532355099,"y":0.641848992,"cat":"Key Items","group":"Items","title":"Gravity Stone Peddler's Bell Bearing","desc":"Key Item. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Bell+Bearing+Hunter' target=\"_blank\">Bell Bearing Hunter</a> that spawns at this location at night time.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6574","x":0.568086459,"y":0.642062631,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf - Divine Tower of Caelid","desc":"Can be found at the base of <a href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+Caelid' target=\"_blank\">Divine Tower of Caelid</a> on a corpse.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5431","x":0.528631669,"y":0.642367834,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Sky Shot","desc":"Ash of War. Drops from Teardrop Scarab behind Isolated Merchant's Shack","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"4275","x":0.258000086,"y":0.642550956,"cat":"Sites of Grace","group":"Locations","title":"Slumbering Wolf's Shack","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6566","x":0.277652335,"y":0.642642518,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"Can be found at the right side of the road, near to the big rock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10239","x":0.642790382,"y":0.642995291,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Lenne's Rise","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"blank\">Dragonbarrow</a>, immediately south of a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Lenni's+Rise' target=\"blank\">Lenni's Rise.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"4273","x":0.26071631,"y":0.64303928,"cat":"Locations","group":"Locations","title":"Slumbering Wolf's Shack","desc":"Special location to meet NPC <a href='https://eldenring.wiki.fextralife.com/Latenna' target=\"_blank\">Latenna</a>, who is part of a questline for Village of the Albinaurics. Only accessible through <a href='https://eldenring.wiki.fextralife.com/Lakeside+Crystal+Cave' target=\"_blank\">Lakeside Crystal Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"2353","x":0.530829105,"y":0.643466563,"cat":"NPCs","group":"Characters","title":"Isolated Merchant Dragonbarrow","desc":"General Goods vendor found sitting outside his shack in western <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"5425","x":0.533606416,"y":0.643497085,"cat":"Bosses","group":"Characters","title":"Bell Bearing Hunter (Isolated Merchant Dragonbarrow)","desc":"Field Boss. Found outside the shack at night time, where the merchant usually sits. Drops the <a href='https://eldenring.wiki.fextralife.com/Gravity+Stone+Peddler's+Bell+Bearing' target=\"_blank\">Gravity Stone Peddler's Bell Bearing</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"4274","x":0.264103125,"y":0.643558126,"cat":"NPCs","group":"Characters","title":"Latenna","desc":"NPC found in <a href='https://eldenring.wiki.fextralife.com/Slumbering+Wolfs+Shack' target=\"_blank\">Slumbering Wolf's Shack</a>. Promising Latenna to take her to the Haligtree, she will join the player and willingly become a Spirit Ash summon, Latenna the Albinauric. She will also hint at the location of the Haligtree Secret Medallion (Left).","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"9831","x":0.573603397,"y":0.643771766,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Divine Tower of Caelid","desc":"Summoning Pool Effigy in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+Caelid' target=\"blank\">Divine Tower of Caelid</a> after the Center Site of Grace, just down the stairs. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3151","x":0.575046721,"y":0.643985409,"cat":"Sites of Grace","group":"Locations","title":"Divine Tower of Caelid: Basement","desc":"Site of Grace found at the bottom of the tower, after a long platforming section to descend the central area of the tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1462","x":0.29461072,"y":0.644015928,"cat":"Bosses","group":"Characters","title":"Adan, Thief of Fire","desc":"Optional Boss. Imprisoned within the <a href='https://eldenring.wiki.fextralife.com/Malefactor's+Evergaol' target=_blank\">Malefactor's Evergaol</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Flame+of+the+Fell+God' target=\"_blank\">Flame of the Fell God</a> spell upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mainboss.png?h=40"},{"id":"7058","x":0.5693381,"y":0.644076968,"cat":"Consumables","group":"Items","title":"Dragonwound Grease - Divine Tower of Caelid","desc":"Weapon Coating. Can be found on one of the 4 bodies sitting, at the base of the tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3037","x":0.572084891,"y":0.644778936,"cat":"Key Items","group":"Items","title":"Stonesword Key - Divine Tower of Caelid (Caelid)","desc":"<a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a>. Found on a corpse on a ledge on the outside of the tower. Accessible via careful platforming.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2351","x":0.531957857,"y":0.645511422,"cat":"Locations","group":"Locations","title":"Isolated Merchant's Shack (Dragonbarrow)","desc":"Secluded hut found in western <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"2352","x":0.529608308,"y":0.645908183,"cat":"Sites of Grace","group":"Locations","title":"Isolated Merchant's Shack (Dragonbarrow)","desc":"Site of Grace found inside the Isolated Merchant's Shack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4262","x":0.232187366,"y":0.645969224,"cat":"Key Items","group":"Items","title":"Chelona's Rise Turtle Marker 2","desc":"Giant Ghostly Turtle #2. One of three required to break the seal to <a href='https://eldenring.wiki.fextralife.com/Chelona's+Rise'>Chelona's Rise</a>. Found sitting on a lower cliff south of Lunar Estate Ruins. Head to the edge of the plateau and look down. You can hit the turtle with a ranged attack from here.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6565","x":0.259311861,"y":0.645969224,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"Can be found near to the rocks, at the left of the Slumbering Wolf's Shack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6573","x":0.570131615,"y":0.645969224,"cat":"Crafting Materials","group":"Items","title":"Faded Erdleaf Flower","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+Caelid' target=\"_blank\">Divine Tower of Caelid</a>, on the outside of the tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2970","x":0.615964586,"y":0.646091305,"cat":"Talismans","group":"Equipment","title":"Flamedrake Talisman +2","desc":"Talisman. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Beastman+of+Farum+Azula'>Beastman of Farum Azula</a>duo bosses in <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow+Cave' target=\"_blank\">Dragonbarrow Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1463","x":0.293459201,"y":0.646152345,"cat":"Spells","group":"Equipment","title":"Flame of the Fell God","desc":"<a href='https://eldenring.wiki.fextralife.com/Incantations' target=\"_blank\">Incantation</a>. Dropped by <a href='https://eldenring.wiki.fextralife.com/Adan,+Thief+of+Fire' target=\"_blank\">Adan, Thief of Fire</a> inside the <a href='https://eldenring.wiki.fextralife.com/Malefactor's+Evergaol' target=\"_blank\">Malefactor's Evergaol</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"1421","x":0.297057806,"y":0.64642703,"cat":"Locations","group":"Locations","title":"Malefactor's Evergaol","desc":"Evergaol found on the southern landmass of Liurnia. The boss <a href='https://eldenring.wiki.fextralife.com/Adan,+Thief+of+Fire' target=\"_blank\">Adan, Thief of Fire</a> is imprisoned within.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-evergaol.png?h=40"},{"id":"4460","x":0.302642335,"y":0.646610151,"cat":"Crafting Materials","group":"Items","title":"Crystal Bud - 2x - Liurnia Lake Shore","desc":"Found within the proximities of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'>Liurnia Lake Shore Site of Grace</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2965","x":0.613004154,"y":0.64676275,"cat":"Bosses","group":"Characters","title":"Beastman of Farum Azula (Dragonbarrow Cave)","desc":"Duo Boss encounter against two beastmen at the end of <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow+Cave' target=\"_blank\">Dragonbarrow Cave</a>. One wielding a Greatsword and one wielding Throwing Knives. Drops the <a href='https://eldenring.wiki.fextralife.com/Flamedrake+Talisman' target=\"_blank\">Flamedrake Talisman +2</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"1511","x":0.3213483,"y":0.647190034,"cat":"Sites of Grace","group":"Locations","title":"Liurnia Highway South","desc":"Site of Grace on the side of the road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2972","x":0.619198262,"y":0.647464718,"cat":"Sites of Grace","group":"Locations","title":"Dragonbarrow Cave","desc":"Site of Grace by the entrance to Dragonbarrow Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8182","x":0.511239724,"y":0.647586799,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Minor Erdtree Catacombs","desc":"Summoning Pool Effigy found at the top of the first elevator, just after the Minor Erdtree Catacombs site of grace in Caelid. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5435","x":0.502419469,"y":0.647678358,"cat":"Key Items","group":"Items","title":"Cracked Pot - Minor Erdtree (Caelid)","desc":"Crafting Pot. One found at the end of a tree branch extending from the northwest cliffs behind the tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"2963","x":0.610013241,"y":0.648166682,"cat":"Talismans","group":"Equipment","title":"Bull-Goat's Talisman","desc":"Talisman. Found on a corpse inside <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow+Cave' target=\"_blank\">Dragonbarrow Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"2926","x":0.508125708,"y":0.648563447,"cat":"Locations","group":"Locations","title":"Minor Erdtree (Caelid)","desc":"Erdtree of <a href='https://eldenring.wiki.fextralife.com/Caelid' target=\"_blank\">Caelid</a> found in the northwest, near the border to <a href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"_blank\">Limgrave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tree.png?h=40"},{"id":"2317","x":0.562564684,"y":0.648960209,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [8] - Dragonbarrow West","desc":"Upgrade Material. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> found sitting on a fallen tree in western <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a>. Warning: This scarab explodes upon death, dealing massive damage!","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"1422","x":0.301086875,"y":0.64914333,"cat":"Sites of Grace","group":"Locations","title":"Liurnia Lake Shore","desc":"Site of Grace found on the southern landmass, by the Nomadic Merchant.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2962","x":0.614895925,"y":0.649265411,"cat":"Locations","group":"Locations","title":"Dragonbarrow Cave","desc":"Optional Dungeon found in eastern <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a>. The entrance is found by following the road along the cliffs north of the Minor Erdtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"2933","x":0.510812447,"y":0.649326452,"cat":"Sites of Grace","group":"Locations","title":"Minor Erdtree Catacombs","desc":"Site of Grace found within the Minor Erdtree Catacombs, a few steps from the entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"7753","x":0.512643642,"y":0.649387493,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [4] - Minor Erdtree Catacombs","desc":"Spirit Ash Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+Catacombs' target=\"_blank\">Minor Erdtree Catacombs</a>. After descending the lift, step on its pressure plate again to send it up and immediately jump off. Drop down into the opening and head into the scarlot rot-flooded corridor to find the glovewort, by the narrow opening on the right.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"6255","x":0.637292477,"y":0.649448533,"cat":"Bosses","group":"Characters","title":"Putrid Tree Spirit (War-Dead Catacombs)","desc":"Boss of the War-Dead Catacombs in eastern Caelid. Drops Redmane Knight Ogha Spirit Ashes and a Golden Seed","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6428","x":0.516397589,"y":0.649784257,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4] - East of the Minor Erdtree (Caelid)","desc":"Found by the sea past the Minor Erdtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"7056","x":0.500770969,"y":0.649784257,"cat":"Consumables","group":"Items","title":"Rune Arc - Caelid Minor Erdtree","desc":"Can be found on one of the roots of the erdtrees. You can reach it by dropping down from the roots above.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8189","x":0.618069025,"y":0.649875816,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Dragonbarrow Cave","desc":"Summoning Pool Effigy found next to the Dragonbarrow Cave site of grace in Dragonbarrow. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1467","x":0.298981631,"y":0.649906338,"cat":"Talismans","group":"Equipment","title":"Sacrificial Twig","desc":"Special Consumable Talisman. Found on a corpse on a stone platform jutting out of the cliff to the east. Accessible from above only, by heading east from Malefactor's Evergaol.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"5963","x":0.639764883,"y":0.650272581,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - War-Dead Catacombs","desc":"Obtained by defeating the <a href='https://eldenring.wiki.fextralife.com/Putrid+Tree+Spirit' target=\"_blank\">Putrid Tree Spirit</a> inside the <a href='https://eldenring.wiki.fextralife.com/War-Dead+Catacombs' target=\"_blank\"> War-Dead Catacombs</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"10217","x":0.318496102,"y":0.650272581,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Liurnia Highway South","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Liurnia' target=\"blank\">Liurnia</a>, next to Liurnia Highway South","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"4406","x":0.634820363,"y":0.6503031,"cat":"Spirit Ashes","group":"Equipment","title":"Radahn Soldier Ashes","desc":"Spirit Ashes found within <a href='https://eldenring.wiki.fextralife.com/War-Dead+Catacombs' target=\"_blank\">War-Dead Catacombs</a> Go up the stairs to the back right of the first room and go left. Past the archer at the end of the hall turn right, turning right again at the end of that hall past the greatsword knight. Jump through the window to the right near the end of this hall. Go left up the stairs and the ashes will be in a room in front of you behind a knight.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6885","x":0.620510619,"y":0.650547262,"cat":"Consumables","group":"Items","title":"Golden Rune [12] - Dragonbarrow Cave","desc":"Within <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/dragonbarrow+cave'>Dragonbarrow Cave</a>, held by a corpse near a <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/lesser+runebear'>Lesser Runebear</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3806","x":0.513803399,"y":0.650608302,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [3] - 3x Minor Erdtree Catacombs","desc":"Spirit Ash Upgrade Material. A total of <strong>3</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+Catacombs' target=\"_blank\">Minor Erdtree Catacombs</a>: <ol> <li>After descending the lift by the entrance, head into the western corridor and look behind the central support of the next room to find the first glovewort.</li> <li>The second one is found in the scarlet rot-flooded room east of the lift. The glovewort is to the right of the doorway.</li> <li>The last one can be found by returning to the lift, sending it up and then dropping into the opening below it. Go through the scarlet rot-flooded corridor and enter the small opening on the right. Continue through the next room and look for a ladder on the right. Climb the ladder and you can find the glovewort in the hallway above.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"6441","x":0.607876849,"y":0.650730383,"cat":"Bosses","group":"Characters","title":"Putrid Avatar (Dragonbarrow)","desc":"Optional boss. It guards the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Dragonbarrow)' target=\"_blank\">Minor Erdtree</a> in <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a>, just before the bridge leading to the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/bestial+sanctum'>Bestial Sanctum</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"1052","x":0.314484187,"y":0.650882987,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - South Liurnia of the Lakes","desc":"At the edge of the lake on the ground.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4542","x":0.596922591,"y":0.651188189,"cat":"Sites of Grace","group":"Locations","title":"Dragonbarrow Fork","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2930","x":0.511451549,"y":0.651645991,"cat":"Locations","group":"Locations","title":"Minor Erdtree Catacombs","desc":"Optional Dungeon found beneath the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Caelid)' target=\"_blank\">Minor Erdtree</a>. The entrance is found slightly southeast of the tree, by the cliff face.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"2928","x":0.502297388,"y":0.651829112,"cat":"Flask Upgrades","group":"Items","title":"Greenburst Crystal Tear","desc":"Physick Flask material. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Erdtree+Avatar' target=\"_blank\">Erdtree Avatar</a> guarding this tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"5603","x":0.530920662,"y":0.651859635,"cat":"Shields","group":"Equipment","title":"Spiked Palisade Shield","desc":"On dead body under a Golem, west of Deep Siofra Well, Caelid","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"6107","x":0.633996679,"y":0.652134315,"cat":"Spells","group":"Equipment","title":"Collapsing Stars","desc":"<a href='https://eldenring.wiki.fextralife.com/Gravity+Sorceries' target=\"_blank\">Gravity Sorcery</a>. Looted from a chest inside the <a href='https://eldenring.wiki.fextralife.com/War-Dead+Catacombs' target=\"_blank\">War-Dead Catacombs</a>. In the main chamber with 4 staircases, drop into the lower level from the left side to find the chest amongst the ghostly knights fighting each other.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-purplespell.png?h=40"},{"id":"4405","x":0.636011085,"y":0.652225878,"cat":"Sites of Grace","group":"Locations","title":"War-Dead Catacombs","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3808","x":0.514200156,"y":0.652347959,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [4] - 2x Minor Erdtree Catacombs","desc":"Spirit Ash Upgrade Material. A total of <strong>2</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+Catacombs' target=\"_blank\">Minor Erdtree Catacombs</a>: <ol> <li>The first one is found inside the eastern corridor, after descending the lift by the entrance.</li> <li>Go back to the lift and step on the plate to send it up and immediately jump off. Head into the opening and through the scarlot rot-flooded corridor. Look to the right for a narrow opening and follow it into a room where you can find the glovewort in the back.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"8190","x":0.638452679,"y":0.652408999,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: War-Dead Catacombs","desc":"Summoning Pool Effigy found on the staircase platform just after the War-Dead Catacombs site of grace in Caelid. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1367","x":0.301878449,"y":0.65247004,"cat":"NPCs","group":"Characters","title":"Nomadic Merchant Liurnia of the Lakes","desc":"Found by a campfire on the west road after passing through the outpost to the northwest of Church of Irith, before entering the forest in Liurnia of the Lakes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"5945","x":0.640619591,"y":0.652592121,"cat":"Spirit Ashes","group":"Equipment","title":"Redmane Knight Ogha Ashes","desc":"Dropped by the <a href='https://eldenring.wiki.fextralife.com/Putrid+Tree+Spirit' target=\"_blank\">Putrid Tree Spirit</a> in the <a href='https://eldenring.wiki.fextralife.com/War-Dead+Catacombs' target=\"_blank\">War-Dead Catacombs</a> located in eastern Caelid. To find the entrance of the catacombs, travel to the site of grace that appears after defeating Starcourge Radahn and proceed to head north until you have reached the upper most corner of the area, you'll be able to see the small door along the cliffside.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"8752","x":0.61974742,"y":0.652866801,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Putrid Avatar","desc":"Summoning Pool Effigy found on the path from the northeast, next to the stake of Marika Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2929","x":0.504281185,"y":0.652927842,"cat":"Flask Upgrades","group":"Items","title":"Flame-Shrouding Cracked Tear","desc":"Physick Flask material. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Erdtree+Avatar' target=\"_blank\">Erdtree Avatar</a> guarding this tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"1172","x":0.549200134,"y":0.653263566,"cat":"Sites of Grace","group":"Locations","title":"Dragonbarrow West","desc":"Site of Grace found in western Dragonbarrow.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5927","x":0.607968409,"y":0.653507728,"cat":"Flask Upgrades","group":"Items","title":"Stonebarb Cracked Tear","desc":"Obtained by defeating the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Putrid+Avatar'>Putrid Avatar</a> at the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Dragonbarrow)'>Minor Erdtree</a> in <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"6711","x":0.610654445,"y":0.653568769,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily","desc":"Crafting Item. Can be found on the road to the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Dragonbarrow)' target=\"_blank\">Minor Erdtree (Dragonbarrow)</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3819","x":0.513833919,"y":0.654057093,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [5] - 2x Minor Erdtree Catacombs","desc":"Spirit Ash Upgrade Material. A total of <strong>2</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+Catacombs' target=\"_blank\">Minor Erdtree Catacombs</a>: <ol> <li>The first one is found in the back of the scarlet rot-flooded room, east of the lift.</li> <li>The second glovewort can be found by sending the lift up and dropping into the opening below. Head into the scarlot rot-flooded corridor and go through the narrow opening on the right. Continue on through the next room and climb up the ladder on the right. Follow the linear path and turn right to wind up on the upper balcony of the scarlot rot-flooded room. The glovewort is found by a pillar in the back on the left side.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"2927","x":0.501351273,"y":0.654179174,"cat":"Bosses","group":"Characters","title":"Erdtree Avatar (Caelid)","desc":"Field Boss. Drops <a href='https://eldenring.wiki.fextralife.com/Greenburst+Crystal+Tear' target=\"_blank\">Greenburst Crystal Tear</a> and <a href='https://eldenring.wiki.fextralife.com/Flame-Shrouding+Cracked+Tear' target=\"_blank\">Flame-Shrouding Cracked Tear</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"4404","x":0.638055999,"y":0.654301255,"cat":"Locations","group":"Locations","title":"War-Dead Catacombs","desc":"Catacombs found within <a href='https://eldenring.wiki.fextralife.com/Starscourge+Radahn' target=\"_blank\">Starscourge Radahn's</a> boss arena","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"5844","x":0.173750118,"y":0.654484376,"cat":"Sites of Grace","group":"Locations","title":"Altar South","desc":"<a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'>Site of Grace</a> next to <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/chelona's+rise'>Chelona's Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"7903","x":0.640497378,"y":0.654789579,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - War-Dead Catacombs","desc":"Rune Consumable. Found inside the <a href='https://eldenring.wiki.fextralife.com/War-Dead+Catacombs' target=\"_blank\">War-Dead Catacombs</a>. In the main chamber with the 4 staircases, drop down into the lower level from the left and loot the corpse by the support structure in the northeast.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7904","x":0.634050966,"y":0.654820097,"cat":"Consumables","group":"Items","title":"Magic Grease - 3x War-Dead Catacombs","desc":"Weapon Coating. Found inside the <a href='https://eldenring.wiki.fextralife.com/War-Dead+Catacombs' target=\"_blank\">War-Dead Catacombs</a>, on a corpse right in the center of the large chamber with the 4 staircases.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5553","x":0.508981251,"y":0.655094781,"cat":"Armor","group":"Equipment","title":"Imp Head (Wolf)","desc":"Helmet. Found inside <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/minor+erdtree+catacombs'>Minor Erdtree Catacombs</a>, held by a corpse laying over a sarcophagus.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"2942","x":0.512399481,"y":0.6551253,"cat":"Bosses","group":"Characters","title":"Erdtree Burial Watchdog (Minor Erdtree Catacombs)","desc":"Duo boss fight against a Watchdog wielding a Sword and another wielding a Scepter. Drops the <a href='https://eldenring.wiki.fextralife.com/Mad+Pumpkin+Head+Ashes' target=\"_blank\">Mad Pumpkin Head Ashes</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"5928","x":0.620997827,"y":0.655430502,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Rain of Arrows","desc":"Appears at edge of a cliff after you've looted the \"Redmane\" Painting in <a href='https://eldenring.wiki.fextralife.com/Sellia,+Town+of+Sorcery' target=\"_blank\"> Sellia, Town of Sorcery</a>. You'll find it down the cliff on a plateau south east of the Eastern Minor Erdtree in Caelid. The Erdtree is located in the Caelid subregion called Dragonbarrow. Once you've made your way down, walk to the edge and you'll briefly see the spirit of a painter, he'll vanish and the Ash of War will appear in his place","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"2944","x":0.510751407,"y":0.655491543,"cat":"Spirit Ashes","group":"Equipment","title":"Mad Pumpkin Head Ashes","desc":"Spirit Summon Ash. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Erdtree+Burial+Watchdog' target=\"_blank\">Erdtree Burial Watchdog</a> duo bosses within the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+Catacombs' target=\"_blank\">Minor Erdtree Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"768","x":0.447190528,"y":0.655613624,"cat":"Sites of Grace","group":"Locations","title":"Divine Tower of Limgrave","desc":"Site of grace near the Tower of Limgrave","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4497","x":0.616176727,"y":0.655674664,"cat":"Locations","group":"Locations","title":"Minor Erdtree (Dragonbarrow)","desc":"A Minor Erdtree in eastern <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a>, overlooking the eastern roads.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tree.png?h=40"},{"id":"1171","x":0.561220986,"y":0.655827268,"cat":"Maps","group":"Locations","title":"Map (Dragonbarrow)","desc":"Map Fragment. Reveals the <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a> region. Found on a monolith along the road east of the Dragonbarrow West Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"5929","x":0.610318443,"y":0.655888308,"cat":"Flask Upgrades","group":"Items","title":"Opaline Hardtear","desc":"Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Putrid+Avatar'>Putrid Avatar</a> at the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Dragonbarrow)'>Minor Erdtree</a> in <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"904","x":0.444900676,"y":0.656193511,"cat":"Locations","group":"Locations","title":"Divine Tower of Limgrave","desc":"Accessible only from <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a>, this location allows the player to activate the power of Godrick's Great Rune.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-divinetower.png?h=40"},{"id":"7902","x":0.63970387,"y":0.657200677,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [6] - War-Dead Catacombs","desc":"Spirit Ash Upgrade Material. A total of <strong>5</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/War-Dead+Catacombs' target=\"_blank\">War-Dead Catacombs</a>: <ol> <li>Right in the center of the main chamber with the 4 staircases, you can find the glovewort under a torch on the left wall.</li> <li>In the same chamber, take the first staircase on the left, closest to the entrance and follow the ledge west to find the second glovewort.</li> <li>Get back into the center of the main chamber and take the stairs in the back on the right this time and head down the corridor on the left. Continue all the way to the end and then turn right to find the third glovewort on the left side in the next corridor.</li> <li>Continue on from the previous glovewort and you will find the fourth one in a small room at the very end of the path.</li> <li>Backpedal a bit from the previous glovewort and you will find a window in the west side of the hallway. Jump through and then head up the stairs on the left in the next room. Turn right to find another window, through which you can find the final glovewort.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"6567","x":0.302305578,"y":0.657231199,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Found at a Graveyard at the south of <a href='https://eldenring.wiki.fextralife.com/Liurnia+of+the+Lakes' target=\"_blank\">Liurnia of the Lakes</a>, by a grave","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7901","x":0.635034324,"y":0.657383799,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [4] - War-Dead Catacombs","desc":"Spirit Ash Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/War-Dead+Catacombs' target=\"_blank\">War-Dead Catacombs</a>. In the main chamber with the 4 staircases, drop into the lower level and search the northeast corner for a corridor that leads to another room. Check the back of this room past the arches to find the glovewort.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"4665","x":0.518134877,"y":0.657444839,"cat":"Weapons","group":"Equipment","title":"Greatsword","desc":"Colossal Sword. Looted from the chest in the enemy caravan traveling the <strong>Caelid Highway</strong>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossalsword.png?h=40"},{"id":"986","x":0.48551489,"y":0.657627961,"cat":"Key Items","group":"Items","title":"Missionary's Cookbook [3]","desc":"Cookbook item. Found on one of the two corpses in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Smoldering+Church'>Smoldering Church</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"985","x":0.483470058,"y":0.657658483,"cat":"Key Items","group":"Items","title":"Nomadic Warrior's Cookbook [14]","desc":"Cookbook item. Found on one of the two corpses in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Smoldering+Church'>Smoldering Church</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"4261","x":0.173642587,"y":0.658543572,"cat":"Key Items","group":"Items","title":"Chelona's Rise Turtle Marker 1","desc":"Giant Ghostly Turtle #1. One of three required to break the seal to <a href='https://eldenring.wiki.fextralife.com/Chelona's+Rise'>Chelona's Rise</a>. Found hanging off the side of the cliffs west of the tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"7905","x":0.637377635,"y":0.658757212,"cat":"Consumables","group":"Items","title":"Silver-Pickled Fowl Foot - War-Dead Catacombs","desc":"Consumable. Found inside the <a href='https://eldenring.wiki.fextralife.com/War-Dead+Catacombs' target=\"_blank\">War-Dead Catacombs</a>. In the main chamber with the 4 staircases, drop down into the lower level from the left and check the southeast corner to find a corpse with the item.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4259","x":0.176314425,"y":0.658787731,"cat":"Locations","group":"Locations","title":"Chelona's Rise","desc":"A tower found in the very corner of the upper plateau in Liurnia's southwest. This tower is initially sealed, with an imp statue at the entrance holding a glowing book, instructing you to \"seek three great wise beasts\". See the tower's page for details.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"5957","x":0.514197739,"y":0.658787731,"cat":"Spells","group":"Equipment","title":"Whirl, O Flame!","desc":"Dropped from a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> on the road between Rotview Balcony and <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Caelem+Ruins'>Caelem Ruins</a> next to the wagon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"840","x":0.305817255,"y":0.659031892,"cat":"Key Items","group":"Items","title":"Glintstone Craftsman's Cookbook [1]","desc":"Dropped by one of the Nobles in that enemy outpost.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"984","x":0.484689347,"y":0.659550738,"cat":"Sites of Grace","group":"Locations","title":"Smoldering Church","desc":"Site of Grace located at the far side of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Smoldering+Church'>Smoldering Church</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4666","x":0.524114961,"y":0.659581257,"cat":"Consumables","group":"Items","title":"Rune Arc","desc":"Consumable. Looted from a chest near the enemy caravan traveling Dragonbarrow's Road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1175","x":0.549322214,"y":0.659611779,"cat":"Sites of Grace","group":"Locations","title":"Deep Siofra Well","desc":"Site of Grace found outside of the Deep Siofra Well.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"10238","x":0.612217786,"y":0.659811054,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Minor Erdtree (Dragonbarrow)","desc":"Spiritspring Jump for <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Torrent' target=\"blank\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"blank\">Dragonbarrow</a>, immediately southwest of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Dragonbarrow)' target=\"blank\">Minor Erdtree (Dragonbarrow)</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"9841","x":0.491251336,"y":0.659855941,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Smoldering Church","desc":"Summoning Pool Effigy next to the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Smoldering+Church' target=\"blank\">Smoldering Church</a> Site of Grace. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4664","x":0.519416499,"y":0.660374783,"cat":"Locations","group":"Locations","title":"Enemy Caravan (Caelid)","desc":"Enemy Caravan. The <a href='https://eldenring.wiki.fextralife.com/Greatsword' target=\"_blank\">Greatword</a> can be looted from its chest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-wagon.png?h=40"},{"id":"1413","x":0.322935611,"y":0.660557905,"cat":"Talismans","group":"Equipment","title":"Winged Sword Insignia","desc":"Talisman. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Cleanrot+Knight' target=\"_blank\">Cleanrot Knight</a> boss inside the <a href='https://eldenring.wiki.fextralife.com/Stillwater+Cave' target=\"_blank\">Stillwater Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4264","x":0.177991988,"y":0.661015711,"cat":"Spells","group":"Equipment","title":"Ranni's Dark Moon","desc":"<a href='https://eldenring.wiki.fextralife.com/Sorceries' target=\"_blank\">Sorcery</a> Spell. Found in a chest at the top of <a href=\"Chelona's+Rise\" target=\"_blank\">Chelona's Rise</a> after unlocking the tower's seal.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"9843","x":0.579727364,"y":0.661198832,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Dragonbarrow Fork","desc":"Summoning Pool Effigy down the path of the Dragonbarrow Fork Site of Grace. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1174","x":0.554201816,"y":0.661290391,"cat":"Locations","group":"Locations","title":"Deep Siofra Well","desc":"A small structure that houses a lift that takes players underground to the northern section of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Siofra+River'>Siofra River</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-well.png?h=40"},{"id":"1412","x":0.324306599,"y":0.661656634,"cat":"Bosses","group":"Characters","title":"Cleanrot Knight - Stillwater Cave","desc":"Optional Boss found at the end of the <a href='https://eldenring.wiki.fextralife.com/Stillwater+Cave' target=\"_blank\">Stillwater Cave</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Winged+Sword+Insignia' target=\"_blank\">Winged Sword Insignia</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"2831","x":0.571595897,"y":0.661656634,"cat":"Crafting Materials","group":"Items","title":"Gravel Stone (B)","desc":"Crafting Material, found in the middle of the lake. Before of the lurking Dragons in the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"983","x":0.485942348,"y":0.661992359,"cat":"Locations","group":"Locations","title":"Smoldering Church","desc":"The remains of an old church glowing with red embers. Houses a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Sites+of+Grace'>Site of Grace</a> for weary travelers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"978","x":0.482523969,"y":0.662297561,"cat":"NPC Invaders","group":"Characters","title":"Anastasia, Tarnished-Eater A","desc":"Hostile invader with cloth armor and a curved greatsword equipped. Invades when you first approach the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Smoldering+Church'>Smoldering Church</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"8782","x":0.322996995,"y":0.662602764,"cat":"Consumables","group":"Items","title":"Poison Grease - 2x Stillwater Cave","desc":"Consumable Item. Two can be looted from a corpse found just before the boss room fog in Stillwater Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2864","x":0.421686388,"y":0.662963331,"cat":"Talismans","group":"Equipment","title":"Lance Talisman","desc":"Found at the north of Limgrave past the main road close to the edge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"8192","x":0.319242482,"y":0.663457331,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Stillwater Cave","desc":"Summoning Pool Effigy found next to the Stillwater Cave site of grace in Liurnia of the Lakes. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1130","x":0.429338115,"y":0.663579412,"cat":"Consumables","group":"Items","title":"Silver-Pickled Fowl Foot","desc":"Consumable. Found on a corpse surrounded by Eagles.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2834","x":0.565533756,"y":0.663701493,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - North Caelid","desc":"Found at the edge of the lake where the dragons dwell.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"910","x":0.326171431,"y":0.663884614,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - Stillwater Cave","desc":"Found on a dead body, inside Stillwater Cave. In the same room as the Golden Rune (6).","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1301","x":0.32073944,"y":0.663945655,"cat":"Sites of Grace","group":"Locations","title":"Stillwater Cave","desc":"Site of Grace inside Stillwater Cave close to the entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8781","x":0.32491845,"y":0.664037214,"cat":"Crafting Materials","group":"Items","title":"Toxic Mushroom - 3x Stillwater Cave","desc":"Crafting Material. Three Toxic Mushrooms can be looted from corpses within the cave. They can also be farmed from the Servant of Rot enemies within.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"744","x":0.323423672,"y":0.664403457,"cat":"Locations","group":"Locations","title":"Stillwater Cave","desc":"A dark and murky water, poisonous cave. Infested with Giant Bats and large Poison Flowers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"982","x":0.484294332,"y":0.664403457,"cat":"Talismans","group":"Equipment","title":"Sacred Scorpion Charm","desc":"Talisman. Dropped by invader <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Anastasia,+Tarnished-Eater'>Anastasia, Tarnished-Eater</a> when defeated.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"10377","x":0.584277517,"y":0.664786752,"cat":"Consumables","group":"Items","title":"Crystal Dart - 10x Sellia Hideaway","desc":"<p>Looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"blank\">Sellia Hideaway</a> at the bottom of the second room with huge crystal formations</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"981","x":0.481700141,"y":0.664983344,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy - Smoldering Church","desc":"Multiplayer Item. Dropped by invader <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Anastasia,+Tarnished-Eater'>Anastasia, Tarnished-Eater</a> when defeated.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"6804","x":0.425004094,"y":0.665074902,"cat":"Crafting Materials","group":"Items","title":"Stormhawk Feather - 1x Divine Tower of Limgrave Bridge","desc":"Can be found on a dead body neabry the collapsed section bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3009","x":0.527289029,"y":0.665441145,"cat":"Sites of Grace","group":"Locations","title":"Caelem Ruins","desc":"Site of Grace found by the main road near some ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8779","x":0.318876045,"y":0.665441145,"cat":"Consumables","group":"Items","title":"Glowstone - 5x Stillwater Cave","desc":"Consumable Item. Five can be looted off a corpse on the walkway leading to the boss area, where you are ambushed by three bats.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1078","x":0.492271702,"y":0.665593749,"cat":"Consumables","group":"Items","title":"Drawstring Lightning Grease - 2x Northwest Caelid","desc":"Consumable Item. Two can be found on a corpse by the side of the road guarded by a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Zombie+Dog'>Zombie Dog</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6712","x":0.611996857,"y":0.66571583,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found by following the path behind the Minor Erdtree Dragonbarrow to a pillar stone on a cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2508","x":0.321349569,"y":0.665746348,"cat":"Armor","group":"Equipment","title":"Sage Set","desc":"Armor Set comprised of the <a href='https://eldenring.wiki.fextralife.com/Sage+Robe' target=\"_blank\">Sage Hood</a>, <a href='https://eldenring.wiki.fextralife.com/Sage+Robe' target=\"_blank\">Sage Robe</a> and <a href='https://eldenring.wiki.fextralife.com/Sage+Trousers' target=\"_blank\">Sage Trousers</a>. Can be found in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/stillwater+cave'>Stillwater Cave</a> - <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/liurnia+of+the+lakes'>Liurnia of the Lakes</a>, just ahead and below the Lake Facing Cliffs. Sitting on a poison submerged corpse near the end, guarded by Giant Bats that will attack you when you take it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"6569","x":0.508126805,"y":0.665746348,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"Can be found 6 in total, 2 at the ruins, and 5 near the Statue.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6568","x":0.505929372,"y":0.665929469,"cat":"Crafting Materials","group":"Items","title":"Nascent Butterfly","desc":"Can be found on a corpse on the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8778","x":0.325469473,"y":0.666448316,"cat":"Consumables","group":"Items","title":"Serpent Arrow - 15x Stillwater Cave","desc":"Consumable Ammunition. Fifteen can be looted from a corpse inside Stillwater Cave, in the dark room with several bats.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8780","x":0.319792766,"y":0.667302883,"cat":"Consumables","group":"Items","title":"Golden Rune [4]","desc":"Consumable Item. Looted from a corpse in the poison floor area near the Giant Flowers in the path to the boss within Stillwater Cave","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"798","x":0.311798276,"y":0.667424964,"cat":"Key Items","group":"Items","title":"Academy Scroll","desc":"Key Item. Give to a mage to unlock more sorceries. It's by one of the big gravestones where the Skeleton Mages are rising.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-scroll.png?h=40"},{"id":"854","x":0.321072822,"y":0.667760685,"cat":"NPCs","group":"Characters","title":"Hyetta (First Location)","desc":"<a href='https://eldenring.wiki.fextralife.com/Hyetta' target=\"_blank\">Hyetta</a>, Location 1. Hyetta roams The Lands Between in search of the distant light, drawn to her destiny by a guiding shine she feels in the back of her eyes when eating Shabriri grapes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"1101","x":0.500652771,"y":0.668004847,"cat":"Sites of Grace","group":"Locations","title":"Rotview Balcony","desc":"Site of Grace on a cliffside overlooking <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Caelid'>Caelid</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8653","x":0.558657699,"y":0.668035369,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone (5) - North Caelid","desc":"<p>North of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sellia+Crystal+Tunnel' target=\"\">Sellia Crystal Tunnel</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Caelid' target=\"\">Caelid</a>. Can be found within a Breakable Statue. The Dragon east of this location can be used to break it. </p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6959","x":0.323638277,"y":0.66815745,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Stillwater Cave","desc":"Held by a corpse within <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/stillwater+cave'>Stillwater Cave</a>, beyond the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'>Stillwater Cave Site of Grace</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6604","x":0.551055991,"y":0.668310049,"cat":"Key Items","group":"Items","title":"Stonesword Key - Deep Siofra Well Ravine","desc":"Stonesword Key. Found on a body in the ravine south of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Deep+Siofra+Well' target=_blank\">Deep Siofra Well</a>, near the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1466","x":0.343014459,"y":0.668401612,"cat":"Weapons","group":"Equipment","title":"Treespear","desc":"Found on the Caravan left at the edge of the collapsed bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatspear.png?h=40"},{"id":"8953","x":0.527857928,"y":0.668428958,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Caelem Ruins","desc":"Summoning Pool Effigy found just a few meters south of the grace by the Caelem Ruins in NW Caelid. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3181","x":0.509438155,"y":0.668676292,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - Forsaken Ruins","desc":"Looted at the <a href='https://eldenring.wiki.fextralife.com/Forsaken+Ruins' target=\"_blank\">Forsaken Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"745","x":0.320464025,"y":0.668798373,"cat":"Sites of Grace","group":"Locations","title":"Lake-Facing Cliffs","desc":"Site of grace facing the vast lake","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3178","x":0.50592915,"y":0.668950976,"cat":"Weapons","group":"Equipment","title":"Sword of St. Trina","desc":"Found inside a chest in the underground cellar of the <a href='https://eldenring.wiki.fextralife.com/Forsaken+Ruins' target=\"_blank\">Forsaken Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"1105","x":0.499126773,"y":0.669286697,"cat":"Locations","group":"Locations","title":"Shack of the Rotting","desc":"A worn down shack infested with <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Skeleton'>Skeletons</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"845","x":0.31899747,"y":0.669347738,"cat":"NPCs","group":"Characters","title":"Boc the Seamster (Third Location)","desc":"<a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Boc+the+Seamster'>Boc the Seamster</a> Location 3. After meeting him for the second time, Boc will move to Liurnia of the Lakes. Find him kneeling by the Lake-Facing Site of Grace, a cliff above to the entrance to <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Stillwater+Cave'>Stillwater Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"1107","x":0.496685179,"y":0.669408778,"cat":"Consumables","group":"Items","title":"Preserving Boluses - 5x Shack of the Rotting","desc":"Consumable Item. Five can be found inside the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Shack+of+the+Rotting'>Shack of the Rotting</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"14153","x":0.392677056,"y":0.669471042,"cat":"Locations","group":"Locations","title":"Limgrave Colosseum","desc":"Can be reached by following the path north of Warmaster's Shack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-location_41.png?h=40"},{"id":"5752","x":0.564059068,"y":0.669775021,"cat":"Talismans","group":"Equipment","title":"Faithful's Canvas Talisman","desc":"Located on a corpse guarded by two Prawn Miner inside <a href='https://eldenring.wiki.fextralife.com/Sellia+Crystal+Tunnel' target=\"_blank\">Sellia Crystal Tunnel</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"2955","x":0.566195461,"y":0.670415949,"cat":"Spells","group":"Equipment","title":"Rock Blaster","desc":"<a href='https://eldenring.wiki.fextralife.com/Glintstone+Sorceries' target=\"_blank\">Glintstone Sorcery</a>. Found inside the <a href=\"Sellia+Crystal+Tunnel\" target=\"_blank\">Sellia Crystal Tunnel</a>, in a chest inside a shed at the top level of the main cavern.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"3011","x":0.530097349,"y":0.670476989,"cat":"Bosses","group":"Characters","title":"Mad Pumpkin Head (Caelem Ruins)","desc":"Dual Boss Fight against two <a href='https://eldenring.wiki.fextralife.com/Mad+Pumpkin+Head' target=\"_blank\">Mad Pumpkin Heads</a>. They are found in an underground room, the entrance to which is in the eastern side of the ruins. No drops but allows access to a treasure room upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"3010","x":0.528113748,"y":0.670629588,"cat":"Locations","group":"Locations","title":"Caelem Ruins","desc":"Ruins found on the western portion of Caelid, where the Caelid Highway cuts through.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"2255","x":0.562288913,"y":0.670660111,"cat":"Consumables","group":"Items","title":"Gravity Stone Fan - 6x Sellia Crystal Tunnel","desc":"Offensive Throwable. 6x found inside a chest in the central storage shed in the main cavern. This is the same shed you are teleported to upon using the trap coffer at the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/dragon-burnt+ruins'>Dragon-Burnt Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10376","x":0.590176875,"y":0.670829762,"cat":"Consumables","group":"Items","title":"Glowstone - 4x Sellia Hideaway","desc":"<p>Looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"blank\">Sellia Hideaway</a> guarded by two <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sorcerer+Miner' target=\"blank\">Sorcerer Miner</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2355","x":0.595870549,"y":0.670965313,"cat":"Consumables","group":"Items","title":"Dragon Heart (Elder Dragon Greyoll)","desc":"Key Consumable. <strong>5 Hearts</strong> are dropped by <a href='https://eldenring.wiki.fextralife.com/Elder+Dragon+Greyoll' target=\"_blank\"> Elder Dragon Greyoll</a> upon her defeat. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3008","x":0.507639597,"y":0.670995831,"cat":"Locations","group":"Locations","title":"Forsaken Ruins","desc":"Ruins found southeast of the <a href='https://eldenring.wiki.fextralife.com/Shack+of+Rotting' target=\"_blank\">Shack of Rotting</a> in <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"2958","x":0.567903083,"y":0.671880921,"cat":"Key Items","group":"Items","title":"Somberstone Miner's Bell Bearing [1]","desc":"Key Item. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Fallingstar+Beast' target=\"_blank\">Fallingstar Beast</a> at the end of the <a href='https://eldenring.wiki.fextralife.com/Sellia+Crystal+Tunnel' target=\"_blank\">Sellia Crystal Tunnel</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8184","x":0.563695772,"y":0.672125083,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Sellia Crystal Tunnel","desc":"Summoning Pool Effigy found at the top of the ladder, just past the Sellia Crystal Tunnel site of grace in Caelid. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2256","x":0.560640839,"y":0.672308204,"cat":"Consumables","group":"Items","title":"Gravity Stone Chunk - 3x Sellia Crystal Tunnel","desc":"Offensive Throwable. 6x found inside a chest in the central storage shed in the main cavern. This is the same shed you are teleported to upon using the trap coffer at the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/dragon-burnt+ruins'>Dragon-Burnt Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3179","x":0.509925867,"y":0.672338723,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] - Forsaken Ruins","desc":"Looted at the <a href='https://eldenring.wiki.fextralife.com/Forsaken+Ruins' target=\"_blank\">Forsaken Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3018","x":0.424127264,"y":0.672399763,"cat":"Talismans","group":"Equipment","title":"Blue Dancer Charm","desc":"Dropped by the <a href='https://eldenring.wiki.fextralife.com/Guardian+Golem' target=\"_blank\">Guardian Golem</a> within <a href='https://eldenring.wiki.fextralife.com/Highroad+Cave' target=\"_blank\"> Highroad Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3012","x":0.529975073,"y":0.672552366,"cat":"Shields","group":"Equipment","title":"Visage Shield","desc":"Greatshield. Found in a chest in a small room behind the <a href='https://eldenring.wiki.fextralife.com/Mad+Pumpkin+Head' target=\"_blank\">Mad Pumpkin Head</a> duo bosses. Accessible after defeating them.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"9847","x":0.557237279,"y":0.672674447,"cat":"Crafting Materials","group":"Items","title":"Sliver of Meat - Dragonbarrow","desc":"Material. Found on a corpse south of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Deep+Siofra+Well' target=\"blank\">Deep Siofra Well</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2354","x":0.598174713,"y":0.672704966,"cat":"Bosses","group":"Characters","title":"Elder Dragon Greyoll","desc":"Massive boss surrounded by dragons. Drops 10,845 Runes and x5 <a href='https://eldenring.wiki.fextralife.com/Dragon+Heart' target=\"_blank\"> Dragon Heart</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"604","x":0.388937779,"y":0.672796528,"cat":"NPCs","group":"Characters","title":"Frustrated Spirit","desc":"Laying down on the floor, next to the remains of a burnt pillage.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"954","x":0.329708718,"y":0.672796528,"cat":"Key Items","group":"Items","title":"Shabriri Grape - Stormveil Castle","desc":"Key Item. Found next to a ghostly NPC in the underground section of Godrick's throne room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2356","x":0.604884889,"y":0.672918609,"cat":"Sites of Grace","group":"Locations","title":"Fort Faroth","desc":"Site of Grace found just outside the fort.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6886","x":0.608028441,"y":0.67304069,"cat":"Consumables","group":"Items","title":"Golden Rune [12] - Fort Faroth","desc":"Held by a corpse on top of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/fort+faroth'>Fort Faroth</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4523","x":0.549107703,"y":0.673071209,"cat":"Crafting Materials","group":"Items","title":"Glintstone Firefly - 3x Deep Siofra Well Ravine","desc":"Crafting Material. 3x found in the crystal cluster in the ravine south of the <a href='https://eldenring.wiki.fextralife.com/Deep+Siofra+Well' target=\"_blank\">Deep Siofra Well</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2815","x":0.310880954,"y":0.673315371,"cat":"Consumables","group":"Items","title":"Warming Stone (Church of Irith Graveyard)","desc":"Consumable. 3x Warming Stone on a graveyard protected by several undead.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6880","x":0.495402322,"y":0.673315371,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - Caelid's North-West Sarcophagi","desc":"Found within the Sarcophagi located in the northwestern zone of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/caelid'>Caelid</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"651","x":0.392004672,"y":0.673376411,"cat":"Key Items","group":"Items","title":"Duelist's Furled Finger","desc":"Creates competitive multiplayer summon sign.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"8837","x":0.333003723,"y":0.673773176,"cat":"NPCs","group":"Characters","title":"Kenneth Haight (Final Location)","desc":"<p><a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Kenneth+Haight' target=\"\">Kenneth Haight</a> can be located in the Throne Room in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"\">Stormveil Castle</a>��for��his final location.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6878","x":0.497265061,"y":0.673803695,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - Caelid's North-West Sarcophagi","desc":"Found within the Sarcophagi located in the Northwestern zone of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/caelid'>Caelid</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"652","x":0.385183852,"y":0.673895257,"cat":"Key Items","group":"Items","title":"Small Red Effigy","desc":"Sends competitive sign to summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"2957","x":0.568391402,"y":0.674017338,"cat":"Bosses","group":"Characters","title":"Fallingstar Beast","desc":"Optional Boss found at the end of the <a href='https://eldenring.wiki.fextralife.com/Sellia+Crystal+Tunnel' target=\"_blank\">Sellia Crystal Tunnel</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Somberstone+Miner's+Bell+Bearing+(1)' target=\"_blank\">Somberstone Miner's Bell Bearing (1)</a> as well as 1 x <a href='https://eldenring.wiki.fextralife.com/Somber+Smithing+Stone+(6)' target=\"_blank\">Somber Smithing Stone (6)</a>, 5 x <a href='https://eldenring.wiki.fextralife.com/Smithing+Stone+(7)' target=\"_blank\">Smithing Stone (7)</a> and 4x <a href='https://eldenring.wiki.fextralife.com/Gravity+Stone+Chunk' target=\"_blank\">Gravity Stone Chunk</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6002","x":0.320250814,"y":0.674047857,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (Church of Irith)","desc":"Found inside the <a href='https://eldenring.wiki.fextralife.com/Church+of+Irith' target=\"_blank\">Church of Irith</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"2921","x":0.420336207,"y":0.67420046,"cat":"Weapons","group":"Equipment","title":"Shamshir","desc":"Found inside the Highroad Cave, on a platform after the waterfall section, being feasted on by Giant Bats.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedsword.png?h=40"},{"id":"1177","x":0.565431243,"y":0.674322541,"cat":"Locations","group":"Locations","title":"Sellia Crystal Tunnel","desc":"A crystal mining operation in Caelid, overseen by greedy and aggressive insectoids.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tunnel.png?h=40"},{"id":"1178","x":0.562473307,"y":0.674383582,"cat":"Sites of Grace","group":"Locations","title":"Sellia Crystal Tunnel","desc":"Site of Grace found inside Sellia Crystal Tunnel.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3017","x":0.426217498,"y":0.674383582,"cat":"Bosses","group":"Characters","title":"Guardian Golem","desc":"Found within the <a href='https://eldenring.wiki.fextralife.com/Highroad+Cave' target=\"_blank\"> Highroad Cave</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Blue+Dancer+Charm' target=\"_blank\"> Blue Dancer Charm</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"8835","x":0.330043291,"y":0.674383582,"cat":"NPCs","group":"Characters","title":"Gatekeeper Gostoc (Final Location)","desc":"<a href='https://eldenring.wiki.fextralife.com/Gatekeeper+Gostoc' target=\"_blank\"><p><a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Gatekeeper+Gostoc' target=\"\">Gatekeeper Gostoc</a> can be located in the��Throne Room in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"\">Stormveil Castle</a>��for his final location.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"1570","x":0.423134985,"y":0.6744141,"cat":"Sites of Grace","group":"Locations","title":"Highroad Cave Site","desc":"Site of grace, located inside the entrance of Highroad Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2359","x":0.610531075,"y":0.6744141,"cat":"Key Items","group":"Items","title":"Dectus Medallion (Right)","desc":"Key Quest Item. Found in a chest atop the eastern tower in <a href='https://eldenring.wiki.fextralife.com/Fort+Faroth' target=\"_blank\">Fort Faroth</a>, accessible via ladder past all the bats on the bottom level.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6426","x":0.585695043,"y":0.674444622,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [8]","desc":"Found on a dead body over a rock near the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"839","x":0.412798671,"y":0.674505663,"cat":"Crafting Materials","group":"Items","title":"Bloodrose - Deathtouched Catacombs","desc":"Can be found inside the <a href=/Deathtouched+Catacombs target=\"_blank\">Deathtouched Catacombs</a>. On a body, against a wall, past a big hall with many <href='https://eldenring.wiki.fextralife.com/Skeleton' target=\"_blank\">Skeletons</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8836","x":0.332088124,"y":0.674536181,"cat":"NPCs","group":"Characters","title":"Nepheli Loux (Final Location)","desc":"<a href='https://eldenring.wiki.fextralife.com/Nepheli+Loux' target=\"_blank\"><p><a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Nepheli+Loux' target=\"\">Nepheli Loux</a> can be located in the Throne Room in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"\">Stormveil Castle</a>������������������for������������������her final location.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6471","x":0.467703168,"y":0.674597222,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Summonwater Village","desc":"Found by the ruins on a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3870","x":0.42894206,"y":0.674658262,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] - Highroad Cave","desc":"Smithing Stone (1) Upgrade Material can be found within <p><a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Highroad+Cave' target=\"\">Highroad Cave</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2951","x":0.56016225,"y":0.674688784,"cat":"Consumables","group":"Items","title":"Rune Arc - Sellia Crystal Tunnel","desc":"Consumable. Found inside <a href='https://eldenring.wiki.fextralife.com/Sellia+Crystal+Tunnel' target=\"_blank\">Sellia Crystal Tunnel</a>. Head up the slope in the main cavern all the way to the top and then look for a corpse hanging off the edge of a wooden walkway on the left.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8166","x":0.3188167,"y":0.674688784,"cat":"Key Items","group":"Items","title":"Erudition Gesture (Thops Quest)","desc":"Gesture. Obtained as a reward for giving Thops a Glintstone Academy Key, found in Raya Lucaria Academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"842","x":0.317227315,"y":0.674749825,"cat":"NPCs","group":"Characters","title":"Thops","desc":"Tops is a former student of the Academy of Raya Lucaria. Teaches basic Sorceries, and will move if you give him a Glintstone Academy Key.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3229","x":0.574127981,"y":0.674932946,"cat":"Weapons","group":"Equipment","title":"Lusat's Glintstone Staff","desc":"Glintstone Staff. Found in a chest in the building north of the <a href='https://eldenring.wiki.fextralife.com/Nox+Swordstress+&+Nox+Priest' target=\"_blank\">Nox Swordstress & Nox Priest</a> bosses' chamber after defeating them.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"6881","x":0.496165419,"y":0.675085545,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Caelid's North-West Sarcophagi","desc":"Found within the Sarcophagi located in the northwestern zone of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/caelid'>Caelid</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4521","x":0.55023649,"y":0.675116068,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5] - Deep Siofra Well Ravine","desc":"Upgrade Material. Found on a body lying against the cluster of crystals in the ravine south of the <a href='https://eldenring.wiki.fextralife.com/Deep+Siofra+Well' target=\"_blank\">Deep Siofra Well</a>. Also accessible by heading north from the <a href='https://eldenring.wiki.fextralife.com/Swamp+of+Aeonia' target=\"_blank\">Swamp of Aeonia</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"6571","x":0.543675161,"y":0.675268667,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud","desc":"Can be found next to the Raven enemy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10375","x":0.592758563,"y":0.675285719,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4] - Sellia Hideaway","desc":"<p>Looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"blank\">Sellia Hideaway</a>, in the middle of a small tunnel leading to the top</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"523","x":0.388693064,"y":0.675390748,"cat":"NPC Invaders","group":"Characters","title":"Recusant Henricus","desc":"Hostile invader equipping a mace and wearing full body armor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"6427","x":0.587920258,"y":0.675573869,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] x2","desc":"Found on a dead body over a rock near the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2360","x":0.607358792,"y":0.67563491,"cat":"Locations","group":"Locations","title":"Fort Faroth","desc":"Fort found in eastern Dragonbarrow, behind an very massive dragon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-forthaight.png?h=40"},{"id":"9832","x":0.601344516,"y":0.675726473,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Fort Faroth","desc":"Summoning Pool Effigy west of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Fort+Faroth' target=\"blank\">Fort Faroth</a> where you fight <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Elder+Dragon+Greyoll' target=\"blank\">Elder Dragon Greyoll</a>. It is close to the Farum Greatbridge Site of Grace. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"969","x":0.465559127,"y":0.676001153,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] - Summonwater Village","desc":"Upgrade Material. Found among the flooded gravestones surrounding <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Summonwater+Village'>Summonwater Village</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"7909","x":0.567964124,"y":0.676001153,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [6] - Sellia Crystal Tunnel","desc":"Upgrade Material. <strong>One</strong> is acquired by defeating the <a href='https://eldenring.wiki.fextralife.com/Fallingstar+Beast' target=\"_blank\">Fallingstar Beast</a> at the end of the <a href='https://eldenring.wiki.fextralife.com/Sellia+Crystal+Tunnel' target=\"_blank\">Sellia Crystal Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"6603","x":0.589446014,"y":0.676153756,"cat":"Key Items","group":"Items","title":"Stonesword Key - North Caelid","desc":"On top of a large rock with bodies and chairs on top.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"10374","x":0.586530968,"y":0.676153756,"cat":"Consumables","group":"Items","title":"Stimulating Boluses - Sellia Hideaway","desc":"Looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"blank\">Sellia Hideaway</a>, at the bottom of a pit.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"526","x":0.391808018,"y":0.676275837,"cat":"Talismans","group":"Equipment","title":"Hammer Talisman","desc":"Enhances stamina-reducing attacks against blockers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3357","x":0.572056557,"y":0.676367396,"cat":"Sites of Grace","group":"Locations","title":"Chair-Crypt of Sellia","desc":"Site of Grace found in the chamber of the <a href='https://eldenring.wiki.fextralife.com/Nox+Swordstress+&+Nox+Priest' target=\"_blank\">Nox Swordstress & Nox Priest</a> boss duo. Accessible after defeating them.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1559","x":0.425432875,"y":0.676489477,"cat":"Locations","group":"Locations","title":"Highroad Cave","desc":"A cave that houses a tomb, deep within. It is situated at the northmost part of Limgrave. It has been inhabited by a pack of Wolves, Land Octopuses, and Giant Bats.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"2907","x":0.491527314,"y":0.67658104,"cat":"NPCs","group":"Characters","title":"Iron Fist Alexander (Second Location)","desc":"Found inside <a href='https://eldenring.wiki.fextralife.com/Gael+Tunnel' target=\"_blank\">Gael Tunnel</a>, at the rear entrance. After talking to him, he sets off to <a href='https://eldenring.wiki.fextralife.com/Redmane+Castle' target=\"_blank\">Redmane Castle</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"8168","x":0.422692826,"y":0.676733639,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Highroad Cave","desc":"Summoning Pool Effigy found near the Highroad Cave site of grace in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3024","x":0.489571589,"y":0.676764161,"cat":"Sites of Grace","group":"Locations","title":"Rear Gael Tunnel Entrance","desc":"Site of Grace found by the rear entrance to Gael Tunnel.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2953","x":0.561402342,"y":0.67679468,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - 8x Sellia Crystal Tunnel","desc":"Upgrade Material. A total of <strong>8</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sellia+Crystal+Tunnel' target=\"_blank\">Sellia Crystal Tunnel</a>: <ol> <li>The first one is found behind the storage shed on the bottom level of the main cavern.</li> <li>The second stone is found on the slope next to the storage shed at the bottom of the main cavern.</li> <li>The third stone is found on the same slope.</li> <li>Continue heading up the slope all the way to the top. The fourth stone is found in the deep indent on the western wall.</li> <li>Jump on top of the central shed in the main cavern and then onto the wooden platform in the east to hop over the barricade blocking a tunnel. Go through the tunnel and pick up the fifth stone on the left.</li> <li>Continuing on from the previous stone, head up the ladder in the next room and head north to find the sixth stone in the cavity in the wall.</li> <li>The seventh stone is found in the same wall cavity.</li> <li>In the same area, climb up the ladder on the side of the shed and continue along the tunnel ahead to find a cavern with a raised wooden platform. Head up to the platform and check the left wall for the final stone.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5716","x":0.32046324,"y":0.677038842,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Thops's Barrier - Church of Irith","desc":"Ash of War. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> that spawns inside the church after <a href='https://eldenring.wiki.fextralife.com/Thops' target=\"_blank\">Thops</a> leaves for the academy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"2960","x":0.609432355,"y":0.677099882,"cat":"Talismans","group":"Equipment","title":"Radagon's Soreseal","desc":"Talisman. Found on a corpse by dropping down the opening on the roof and looking around the wooden walkways.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3875","x":0.428598051,"y":0.677130404,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - Highroad Cave","desc":"Smithing Stone (2) Upgrade Material can be found within <p><a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Highroad+Cave' target=\"\">Highroad Cave</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"799","x":0.319153644,"y":0.677221963,"cat":"Locations","group":"Locations","title":"Church of Irith","desc":"A church found behind the walls of <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a>. Easily accessible by riding west along the walls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"8181","x":0.499096253,"y":0.677252485,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Gael Tunnel","desc":"Summoning Pool Effigy found next to the main Gael Tunnel site of grace in Caelid. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3227","x":0.576051389,"y":0.677313526,"cat":"Weapons","group":"Equipment","title":"Nox Flowing Sword","desc":"Curved Sword. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Nox+Swordstress+&+Nox+Priest' target=\"_blank\">Nox Swordstress & Nox Priest</a> bosses upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedsword.png?h=40"},{"id":"10372","x":0.588199798,"y":0.677516618,"cat":"Key Items","group":"Items","title":"Lost Ashes of War - Sellia Hideaway","desc":"Found on a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"blank\">Sellia Hideaway</a>, at the bottom of a pit.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"10373","x":0.589987404,"y":0.677520431,"cat":"Consumables","group":"Items","title":"Golden Rune [5] -  Sellia Hideaway B","desc":"Looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"blank\">Sellia Hideaway</a>, at the bottom of a pit.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10371","x":0.59273698,"y":0.677544218,"cat":"Consumables","group":"Items","title":"Golden Rune [5] -  Sellia Hideaway","desc":"Looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"blank\">Sellia Hideaway</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1558","x":0.573486734,"y":0.677771328,"cat":"Bosses","group":"Characters","title":"Nox Swordstress & Nox Priest","desc":"Duo Boss fight. The entrance to their chamber is initially sealed by a barrier which can be dispelled by lighting a brazier atop a tower in the northwest section of town. Drops <a href='https://eldenring.wiki.fextralife.com/Nox+Flowing+Sword' target=\"_blank\"> Nox Flowing Sword</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2959","x":0.565827731,"y":0.677832368,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [7] - 5x Sellia Crystal Tunnel","desc":"Upgrade Material. <strong>5</strong> stones are acquired by defeating the <a href='https://eldenring.wiki.fextralife.com/Fallingstar+Beast' target=\"_blank\">Fallingstar Beast</a> at the end of the <a href='https://eldenring.wiki.fextralife.com/Sellia+Crystal+Tunnel' target=\"_blank\">Sellia Crystal Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2954","x":0.563294578,"y":0.677923931,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4] - 3x Sellia Crystal Tunnel","desc":"Upgrade Material. A total of <strong>3</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Sellia+Crystal+Tunnel' target=\"_blank\">Sellia Crystal Tunnel</a>: <ol> <li>In the main chamber, head up the slope until you are able to jump on the roof of the central storage shed. Jump onto the wooden platform in the east and hop over the barricade blocking the tunnel. Go through the tunnel until you end up in a room with a ladder and wooden walkways above. The stone is found on a body on one of the walkways.</li> <li>Continue to the cavern in the north and climb up the ladder on the side of the shed in front of you. Check the cavity in the wall to the right of the entrance to the next tunnel for the second stone.</li> <li>Continue into the tunnel and check the hollow on the left in the next cavern to find the final stone.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"855","x":0.414540373,"y":0.67807653,"cat":"Key Items","group":"Items","title":"Deathroot - Deathtouched Catacombs","desc":"Inside Deathtouched Catacombs. Found on a chest behind the Black Knife Assassin.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"533","x":0.389440998,"y":0.678229133,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy A","desc":"Reveals co-op and hostile summoning. Dropped by <a class=\"wiki_link\">Recusant Henricus</a> when invading.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"6580","x":0.607449891,"y":0.678229133,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily","desc":"Can be found Behind <a href='https://eldenring.wiki.fextralife.com/Forth+Faroth' target=\"_blank\">Forth Faroth</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8183","x":0.549809208,"y":0.678259652,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Abandoned Cave","desc":"Summoning Pool Effigy found in Abandoned Cave in Caelid, in the left tunnel after dropping down from the site of grace and after the first pool of scarlet rot. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"8351","x":0.337828374,"y":0.678290174,"cat":"Key Items","group":"Items","title":"Godrick's Great Rune","desc":"Dropped as a reward for defeating <a href='https://eldenring.wiki.fextralife.com/Godrick+the+Grafted' target=\"_blank\">Godrick the Grafted</a> located at <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3881","x":0.421529433,"y":0.678534336,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy - Highroad Cave","desc":"Furlcalling Finger Remedy can be dropped in <p><a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Highroad+Cave' target=\"\">Highroad Cave</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"8651","x":0.598204178,"y":0.678595376,"cat":"Spirit Ashes","group":"Equipment","title":"Crystalian Ashes","desc":"<p>Located in a chest protected by three masked magic users in a room that is located down a pathway up the purple crystals next to the Trio Putrid Crystallin's (bosses) boss door in��<a class=\"wiki_link\" title=\"Elden Ring Sellia Hideaway\" href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway'>Sellia Hideaway</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"2910","x":0.50034512,"y":0.678809016,"cat":"Sites of Grace","group":"Locations","title":"Gael Tunnel (Site of Grace)","desc":"Site of grace located inside <a href='https://eldenring.wiki.fextralife.com/Gael+Tunnel' target=\"_blank\"> Gael Tunnel</a>. Found once you reach the lower level.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3768","x":0.509315856,"y":0.678870057,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4] - Gael Tunnel","desc":"Upgrade Material. <strong>One</strong> can be found inside <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Gael+Tunnel'>Gael Tunnel</a>, in the back of the water-logged cavern crawling with <a href='https://eldenring.wiki.fextralife.com/Land+Octopus' target=\"_blank\">Land Octopi</a> and a single <a href='https://eldenring.wiki.fextralife.com/Giant+Land+Octopus' target=\"_blank\">Giant Land Octopus</a> hanging from the ceiling.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4155","x":0.553044321,"y":0.678900579,"cat":"Consumables","group":"Items","title":"Fire Grease - Abandoned Cave","desc":"Weapon Coating. Found on a corpse inside the <a href='https://eldenring.wiki.fextralife.com/Abandoned+Cave' target=\"_blank\">Abandoned Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"846","x":0.405994638,"y":0.678961619,"cat":"Weapons","group":"Equipment","title":"Uchigatana","desc":"Found inside the Deathtouched Catacombs. It is in a body, hanging from the upper platform. You need to use the lever in order to reach that room. Beware of the Skeleton Archers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-katana.png?h=40"},{"id":"794","x":0.355036865,"y":0.67902266,"cat":"Key Items","group":"Items","title":"Nomadic Warrior's Cookbook [7]","desc":"It can be taken from a dead man sitting at the edge of the collapsed bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"1128","x":0.335995726,"y":0.679053178,"cat":"Bosses","group":"Characters","title":"Godrick the Grafted","desc":"The Lord of Stormveil and the first Demigod encountered. Drops <a href='https://eldenring.wiki.fextralife.com/Godrick's+Great+Rune' target=\"_blank\">Godrick's Great Rune</a> and <a href='https://eldenring.wiki.fextralife.com/Remembrance+of+the+Grafted' target=\"_blank\">Remembrance of the Grafted</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"4667","x":0.508186619,"y":0.6792363,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4] - 1x Caelid Scarab Drop","desc":"Upgrade Material. Dropped by a Teardrop Scarab.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"4480","x":0.601529945,"y":0.679297341,"cat":"Spells","group":"Equipment","title":"Crystal Torrent","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Crystalians' target=\"_blank\">Crystalians Trio</a> boss in <a href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"_blank\">Sellia Hideaway</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"6570","x":0.51956949,"y":0.679480462,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf 4x","desc":"Can be found 4 next to the mushrooms.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"838","x":0.412190621,"y":0.679755146,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [1] - 5x Deathtouched Catacombs","desc":"Spirit Ash Upgrade Material. The first one is located in the first large room left of the boss' door, right in front of the stairs. The second one is an alcove under the stairs in the same room. The third is found by going through the very narrow corridor adjacent to the stairs in the same room. The fourth one is found by going through the doorway south of where you collected the previous one, sitting on an L-shaped ledge. The fifth one is found by dropping down from where you collected the fourth.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"1129","x":0.334167948,"y":0.679785664,"cat":"Sites of Grace","group":"Locations","title":"Godrick the Grafted","desc":"Site of Grace inside <a href='https://eldenring.wiki.fextralife.com/Godrick+the+Grafted' target=\"_blank\">Godrick the Grafted</a>'s boss arena. Accessible after defeating him.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8187","x":0.597319103,"y":0.679877227,"cat":"NPCs","group":"Characters","title":"Master Lusat","desc":"A Quest NPC found inside the <a href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"_blank\">Sellia Hideaway</a> dungeon, by dropping down pits surrounded by crystals. The path to him is sealed by a barrier that requires a key acquired from <a href='https://eldenring.wiki.fextralife.com/Sorceress+Sellen' target=\"_blank\">Sorceress Sellen</a> during her questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"976","x":0.465939547,"y":0.679907745,"cat":"Talismans","group":"Equipment","title":"Green Turtle Talisman","desc":"Talisman. Found in an underground area filled with <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Turtle'>Turtles</a>. The entrance is found slightly south-east of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Summmonwater+Village'>Summonwater Village</a> and requires 1 <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stonesword+Key'>Stonesword Key</a> to unlock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"8307","x":0.594785812,"y":0.679938268,"cat":"Armor","group":"Equipment","title":"Lusat's Set","desc":"After completing Sorceress Sellen questline, you will find the complete Lusat's Set at <a href='https://eldenring.wiki.fextralife.com/Master+Lusat'>Master Lusat</a>'s location.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"4154","x":0.555028113,"y":0.679999308,"cat":"Consumables","group":"Items","title":"Dragonwound Grease - Abandoned Cave","desc":"Weapon Coating. Found on a corpse inside the <a href='https://eldenring.wiki.fextralife.com/Abandoned+Cave' target=\"_blank\">Abandoned Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2913","x":0.49802524,"y":0.680060349,"cat":"Consumables","group":"Items","title":"Dragon Heart (Magma Wyrm - Gael Tunnel)","desc":"Key Consumable. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Magma+Wyrm' target=\"_blank\">Magma Wyrm</a> boss inside <a href='https://eldenring.wiki.fextralife.com/Gael+Tunnel' target=\"_blank\">Gael Tunnel</a>. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3356","x":0.577117429,"y":0.680396069,"cat":"Sites of Grace","group":"Locations","title":"Sellia Backstreets","desc":"Site of Grace found behind a sealed door in northern Sellia. Requires lighting the brazier in the southeast of town to unlock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"852","x":0.414177772,"y":0.68051815,"cat":"Talismans","group":"Equipment","title":"Assassin's Crimson Dagger","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Black+Knife+Assassin' target=\"_blank\">Black Knife Assassin</a>, found inside Deathtouched Catacombs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4479","x":0.60320854,"y":0.680579191,"cat":"Bosses","group":"Characters","title":"Crystalians (Trio - Sellia Hideaway)","desc":"Miniboss Trio fight against Putrid Crystalian's. Crystalian (Spear), Crystalian (Ringblade) & Crystalian (Staff). Damage received from all attacks builds Scarlet Rot. Drop <a href='https://eldenring.wiki.fextralife.com/Crystal+Torrent' target=\"_blank\">Crystal Torrent</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"836","x":0.410326241,"y":0.680640231,"cat":"Sites of Grace","group":"Locations","title":"Deathtouched Catacombs","desc":"Site of grace just inside <a href='https://eldenring.wiki.fextralife.com/Deathtouched+Catacombs' target=\"_blank\">Deathtouched Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4544","x":0.548408568,"y":0.680640231,"cat":"Sites of Grace","group":"Locations","title":"Abandoned Cave","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"12451","x":0.336310063,"y":0.680647607,"cat":"Remembrances","group":"Items","title":"Remembrance of the Grafted","desc":"Obtained as a reward for defeating <a class=\"wiki_link\" title=\"Elden Ring Godrick the Grafted\" href='https://eldenring.wiki.fextralife.com/Godrick+the+Grafted' target=\"blank\">Godrick the Grafted</a> at <a class=\"wiki_link\" title=\"Elden Ring Stormveil Castle\" href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"blank\">Stormveil Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3764","x":0.502907904,"y":0.680731794,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] - 8x Gael Tunnel","desc":"Upgrade Material. A total of <strong>8</strong> can be found inside <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Gael+Tunnel'>Gael Tunnel</a>: <ol> <li>From the Site of Grace, head into the next chamber and down one level on the wooden walkways. Head east to find the stone by the left wall of the tunnel entrance here.</li> <li>Continuing on from the previous stone, head into the eastern tunnel to find a water-logged cavern with several <a href='https://eldenring.wiki.fextralife.com/Land+Octopus' target=\"_blank\">Land Octopi</a>. Check the corner directly to the right as you enter for the second stone.</li> <li>Still in the same water-logged cavern, hug the wall on the right to find the third stone.</li> <li>Back in the first chamber, check under the wooden platform for another stone on the eastern wall.</li> <li>The fifth stone is found further along the same wall as the previous one.</li> <li>Turn towards the west and head through the tunnel to find a ladder leading downwards. The sixth stone is found at this bottom level, to the left just before the next tunnel.</li> <li>In the final cavern just before the boss door, check the wall directly opposite the boss door to find the seventh stone.</li> <li>In the same final cavern, unlock the smaller door in the west and check the back wall to the left of that room for the final stone.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"10215","x":0.482907283,"y":0.680792835,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: East Summonwater Village Upper Cliff","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"blank\">Limgrave</a>, on the upper cliff east of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Summonwater+Village' target=\"blank\">Summonwater Village</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"2909","x":0.495584088,"y":0.680853875,"cat":"Weapons","group":"Equipment","title":"Moonveil","desc":"Katana. Dropped by <a href='https://eldenring.wiki.fextralife.com/Magma+Wyrm' target=\"_blank\">Magma Wyrm</a> inside <a href='https://eldenring.wiki.fextralife.com/Gael+Tunnel' blank=\"_blank\"> Gael Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-katana.png?h=40"},{"id":"4478","x":0.599668117,"y":0.680945434,"cat":"Spells","group":"Equipment","title":"Stars of Ruin","desc":"Given by Master Lusat when interacted with inside the Sellia Hideaway behind an arcane ward in the second pit. Requires the Sellian Sealbreaker to get through arcane ward (Acquired during Sorceress Sellen Questline).","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"965","x":0.462019013,"y":0.681036997,"cat":"Locations","group":"Locations","title":"Summonwater Village","desc":"The flooded remains of a dilapidated village. Here you will find the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Tibia+Mariner'>Tibia Mariner</a> boss.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"3409","x":0.386831348,"y":0.681036997,"cat":"NPC Invaders","group":"Characters","title":"Old Knight Istvan","desc":"Assassination target for the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Volcano+Manor'>Volcano Manor</a>. You can invade their world using a summoning sign after accepting the assassination request.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"4150","x":0.551669354,"y":0.681036997,"cat":"Locations","group":"Locations","title":"Abandoned Cave","desc":"East of Smoldering Wall Grace on the eastern wall of the canyon, and slightly northwest of the Sellia Evergaol. The location is only reachable by approaching from the west and crossing the canyon using a tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"10370","x":0.596906038,"y":0.681156902,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Sellia Hideaway","desc":"Looted from a corpse in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"blank\">Sellia Hideaway</a>, just before the illusory wall","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6805","x":0.464460474,"y":0.681189596,"cat":"Crafting Materials","group":"Items","title":"Mushroom","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Summonwater+Village' target=\"_blank\">Summonwater Village</a> on a dead body","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"708","x":0.406850541,"y":0.681220118,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Golden Vow","desc":"Ash of War: Golden Vow provides Sacred affinity and the Golden Vow Skill. Dropped upon defeating Mounted Knight.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"3411","x":0.38445272,"y":0.681494799,"cat":"Armor","group":"Equipment","title":"Scaled Set","desc":"Armor Set. Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Old+Knight+Istvan'>Old Knight Istvan</a> after successfully invading his world.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"10216","x":0.590379611,"y":0.681708442,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Sellia Streets","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Caelid' target=\"\">Caelid</a>, at the fork in the road between the Sellia Backstreets Site of Grace, <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Church+of+the+Plague' target=\"blank_\">Church of the Plague</a> and <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"blank_\">Sellia Hideaway</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"4669","x":0.514656841,"y":0.682196766,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] - 1x Caelid Treasure","desc":"Upgrade Material. Looted as a treasure in the open field in Caelid.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2906","x":0.500802981,"y":0.682257807,"cat":"Locations","group":"Locations","title":"Gael Tunnel","desc":"<a href='https://eldenring.wiki.fextralife.com/Alexander' TARGET=\"_blank\">Alexander</a> can be found inside for the second time.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tunnel.png?h=40"},{"id":"4670","x":0.524176485,"y":0.682288326,"cat":"Consumables","group":"Items","title":"Golden Rune [9] - 1x Caelid Treasure","desc":"Consumable Item. Found as a treasure in Caelid","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4476","x":0.601987329,"y":0.682440928,"cat":"Locations","group":"Locations","title":"Sellia Hideaway","desc":"Cave in Caelid, part of <a href='https://eldenring.wiki.fextralife.com/Sorceress+Sellen' target=\"_blank\">Selen's Quesline</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"3766","x":0.503854024,"y":0.682532487,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [2] - Gael Tunnel","desc":"Upgrade Material. <strong>One</strong> can be found inside <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Gael+Tunnel'>Gael Tunnel</a>. From the entrance, go to the left of the wooden platform and drop down on to the ledge below. Drop down onto the second ledge ahead and enter the small tunnel to find the stone.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2911","x":0.496408131,"y":0.682593528,"cat":"Bosses","group":"Characters","title":"Magma Wyrm (Gael Tunnel)","desc":"Found inside <a href='https://eldenring.wiki.fextralife.com/Gael+Tunnel' target=\"_blank\">Gael Tunnel</a>. Drops x1 <a href='https://eldenring.wiki.fextralife.com/Dragon+Heart' target=\"_blank\"> Dragon Heart</a> and <a href='https://eldenring.wiki.fextralife.com/Moonveil' target=\"_blank\"> Moonveil</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6579","x":0.606870603,"y":0.682593528,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily","desc":"Can be found in front of a massive tree next to the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5924","x":0.327818537,"y":0.682715609,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Storm Assault","desc":"Starting from the Rampart Tower grace, exit onto the ramparts where the war hawks and explosive barrels are. At the tower on the west side where the second war hawk holding an explosive barrel is, jump up onto the battlements on the north side. There is a corpse visible with an item (Marred Wooden Shield). Jumping down to the walls beneath will allow the player to get to the shield. Jumping down further will land the player on a ledge that will collapse, causing them to fall far below into some bushes. A Silver <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> holds the Ash of War","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"1547","x":0.464581031,"y":0.682807171,"cat":"Key Items","group":"Items","title":"Deathroot - Summonwater Village","desc":"Key Item. Obtained upon defeating the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Tibia+Mariner'>Tibia Mariner</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3413","x":0.385696155,"y":0.68283769,"cat":"Consumables","group":"Items","title":"Rune Arc","desc":"Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Old+Knight+Istvan'>Old Knight Istvan</a> after successfully invading his world.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6119","x":0.535345028,"y":0.68283769,"cat":"NPCs","group":"Characters","title":"Finger Reader (Caelid)","desc":"She can be found near the telescope.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"931","x":0.34057713,"y":0.682868212,"cat":"Sites of Grace","group":"Locations","title":"Secluded Cell","desc":"Site of Grace in the northern section of the castle. Found next to a fog gate leading to <a href='https://eldenring.wiki.fextralife.com/Godrick+the+Grafted' target=\"_blank\">Godrick the Grafted</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4151","x":0.554967077,"y":0.682868212,"cat":"Talismans","group":"Equipment","title":"Golden Scarab","desc":"Dropped by Cleanrot Knight (Sickle) & Cleanrot Knight (Spear) boss found in <a href='https://eldenring.wiki.fextralife.com/Abandoned+Cave' target=\"_blank\">Abandoned Cave</a>. It can be accessed by going east from Smoldering Wall site of grace and walking across canyon by using tree branches.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4477","x":0.603818939,"y":0.682929252,"cat":"Sites of Grace","group":"Locations","title":"Sellia Hideaway","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6851","x":0.324886571,"y":0.682929252,"cat":"Shields","group":"Equipment","title":"Marred Wooden Shield","desc":"Medium Shield. From the Rampart Tower site of grace, exit onto the walkway with explosive barrels and <a href='https://eldenring.wiki.fextralife.com/War+Hawk' target=\"_blank\">War Hawks</a>. Kill the War Hawk sitting on the western tower and then jump down the edge onto a ledge below. Follow the ledge north and jump down to the broken pillar below to find the shield.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"3414","x":0.387505357,"y":0.683051333,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy","desc":"Dropped by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Old+Knight+Istvan'>Old Knight Istvan</a> after successfully invading his world.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"835","x":0.41060234,"y":0.683112374,"cat":"Locations","group":"Locations","title":"Deathtouched Catacombs","desc":"Located west of Saintsbridge, a door with a grieving spirit beside it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"704","x":0.404102844,"y":0.683142893,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [1]","desc":"As a drop when defeating a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> at the top of a ruined building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"851","x":0.414299852,"y":0.683264973,"cat":"Bosses","group":"Characters","title":"Black Knife Assassin","desc":"Field Boss. Can be found inside the Deathtouched Catacombs. Drops <a href='https://eldenring.wiki.fextralife.com/Assassin's+Crimson+Dagger' target=\"_blank\">Assassin's Crimson Dagger</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mainboss.png?h=40"},{"id":"1546","x":0.466808984,"y":0.683600698,"cat":"Spirit Ashes","group":"Equipment","title":"Skeletal Militiaman Ashes","desc":"Spirit Ashes. Obtained when defeating the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Tibia+Mariner'>Tibia Mariner</a> in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Summonwater+Village'>Summonwater Village</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"3221","x":0.578461177,"y":0.683600698,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Sellia, Town of Sorcery","desc":"Flask Upgrade Material. Found under a <strong>Phantom Tree</strong> at the top of the large stairs in the northern section of town.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"795","x":0.351501993,"y":0.683814338,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Storm Wall","desc":"Find a <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/teardrop+scarab'>Teardrop Scarab</a>, defeat it to obtain the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/ashes+of+war'>Ash of War</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"792","x":0.359704545,"y":0.6840585,"cat":"NPCs","group":"Characters","title":"Finger Reader (Collapsed Bridge)","desc":"She is sitting on at table at the start of the collapsed bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"1351","x":0.427538146,"y":0.684180581,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1]","desc":"Upgrade Material. Two can be found on a corpse at the Saintsbridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6063","x":0.338588713,"y":0.684241621,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] F - Stormveil Castle","desc":"Upgrade Material. Found on a corpse sitting on an upper ledge in the corridor leading up to the Secluded Chamber site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"973","x":0.465740787,"y":0.684333184,"cat":"Bosses","group":"Characters","title":"Tibia Mariner (Limgrave)","desc":"Optional Boss. Found riding its boat in the flooded areas of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Summonwater+Village'>Summonwater Village</a>. Defeat it to progress <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/D+Hunter+of+the+Dead'>D's</a> questline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"8169","x":0.405937395,"y":0.684424743,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Deathtouched Catacombs","desc":"Summoning Pool Effigy found in front of the Boss Doors of the Deathtouched Catacombs in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5434","x":0.553898877,"y":0.684668905,"cat":"Bosses","group":"Characters","title":"Cleanrot Knight Duo (Abandoned Cave)","desc":"Duo Boss Fight at the end of the <a href='https://eldenring.wiki.fextralife.com/Abandoned+Cave' target=\"_blank\">Abandoned Cave</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Gold+Scarab' target=\"_blank\">Gold Scarab</a> talisman upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"3021","x":0.49686546,"y":0.684852027,"cat":"Weapons","group":"Equipment","title":"Cross-Naginata","desc":"Spear. Found on a corpse inside the <a href='https://eldenring.wiki.fextralife.com/Gael+Tunnel' target=\"_blank\">Gael Tunnel</a>, in the cavern filled with Land Octopi and a single Giant Land Octopus.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spear.png?h=40"},{"id":"962","x":0.443949568,"y":0.684913067,"cat":"NPCs","group":"Characters","title":"D, Hunter of the Dead","desc":"D can be found mourning a person dead at his feet. Here, he will warn you against going any further east towards <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Summonwater+Village'>Summonwater Village</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6660","x":0.556584631,"y":0.684943589,"cat":"Locations","group":"Locations","title":"Sellia Evergaol","desc":"Evergaol found in central Caelid. The boss <a href='https://eldenring.wiki.fextralife.com/Battlemage+Hugues' target=\"_blank\">Battlemage</a> Hugues drops <a href='https://eldenring.wiki.fextralife.com/Battlemage+Hugues+Ashes' target=\"_blank\">Battlemage Hugues Ashes</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-evergaol.png?h=40"},{"id":"8298","x":0.441172253,"y":0.684974107,"cat":"Armor","group":"Equipment","title":"Twinned Set","desc":"Dropped by </a href='https://eldenring.wiki.fextralife.com/D+Hunter+of+the+Dead'>D, Hunter of the Dead</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"8153","x":0.33764366,"y":0.68500463,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Secluded Cell","desc":"Summoning Pool Effigy found near the Secluded Cell site of grace in Stormveil Castle, by the area with the Living Jars and the Teardrop Scarab. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6661","x":0.558751544,"y":0.685035148,"cat":"Bosses","group":"Characters","title":"Battlemage Hugues","desc":"Boss of <a href='https://eldenring.wiki.fextralife.com/Sellia+Evergaol' target=\"_blank\">Sellia Evergaol</a>, drops <a href='https://eldenring.wiki.fextralife.com/Battlemage+Hugues+Ashes' target=\"_blank\">Battlemage Hugues Ashes</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"4153","x":0.548649452,"y":0.685187751,"cat":"Weapons","group":"Equipment","title":"Venomous Fang","desc":"Claw Weapons. Climb on the Iron Maidens near the end of the <a href='https://eldenring.wiki.fextralife.com/Abandoned+Cave' target=\"_blank\">Abandoned Cave</a> to acquire them.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-claws.png?h=40"},{"id":"8188","x":0.603574777,"y":0.685187751,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Sellia Hideaway","desc":"Summoning Pool Effigy found at the end of the tunnel past the Sellia Hideway site of grace in Caelid. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6577","x":0.597563045,"y":0.685309832,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily","desc":"Can be found in front of the cliffside near the trees.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10214","x":0.482692646,"y":0.685401391,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: East Summonwater Village Mid Cliff","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"blank\">Limgrave</a>, on the middle cliff east of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Summonwater+Village' target=\"blank\">Summonwater Village</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"4152","x":0.551884276,"y":0.685462431,"cat":"Weapons","group":"Equipment","title":"Serpent Bow","desc":"Found by a pool of rot within <a href='https://eldenring.wiki.fextralife.com/Abandoned+Cave' target=\"_blank\">Abandoned Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bow.png?h=40"},{"id":"6581","x":0.581086556,"y":0.685462431,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily","desc":"Can be found at the end of the righ side of <a href='https://eldenring.wiki.fextralife.com/Sellia,+Town+of+Sorcery' target=\"_blank\">Sellia, Town of Sorcery</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6802","x":0.425645266,"y":0.685462431,"cat":"Crafting Materials","group":"Items","title":"Sanctuary Stone","desc":"Can be found on the stone bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"834","x":0.42155757,"y":0.685767634,"cat":"Sites of Grace","group":"Locations","title":"Saintsbridge","desc":"Site of grace, located just at the tip of the bridge","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6803","x":0.430711571,"y":0.685767634,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"Can be found under the stone bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"929","x":0.336486196,"y":0.685981278,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Stormcaller","desc":"Ash of War Upgrade. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> in the northern section of the castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"5433","x":0.574555493,"y":0.686011796,"cat":"Talismans","group":"Equipment","title":"Spelldrake Talisman +1","desc":"Upgraded Talisman. Found in a chest in a small room the northwest section of town. Right below where the <a href='https://eldenring.wiki.fextralife.com/Staff+of+Loss' target=\"_blank\">Staff of Loss</a> is obtained. This room is initially sealed by a barrier that can be dispelled by lighting a brazier atop a tower in the southwest of town.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3365","x":0.562566535,"y":0.686133877,"cat":"Spells","group":"Equipment","title":"Poison Armament","desc":"<a href='https://eldenring.wiki.fextralife.com/Incantations' target=\"_blank\">Incantation</a>. Dropped by an invisible <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> roaming around the northeast section of Aeonia Swamp. Figure out its pattern via the footprints and wait for the prints to approach and then attack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"7558","x":0.381065011,"y":0.686133877,"cat":"Armor","group":"Equipment","title":"Ash of War Scarab","desc":"Head Armor. Found on a corpse in the broken bridge leading from Stormveil Castle to the Divine Tower of Limgrave. After the three golems, continue on without taking the waygate and drop down to find the item.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"5756","x":0.339629842,"y":0.686194918,"cat":"Key Items","group":"Items","title":"Nomadic Warrior's Cookbook [10]","desc":"Can be found on a dead body in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stormveil+Castle'>Stormveil Castle</a>. From Rampart Tower (Site of Grace), head out the north door. Jump to the roof immediately visible to the east. Follow the left ledge, then jump down to the level with the 2 enemies (optional combat). Cross the bridge, the recipe is on the corpse directly ahead guarded by 2 weak enemies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"4532","x":0.571869683,"y":0.68622544,"cat":"Spirit Ashes","group":"Equipment","title":"Rotten Stray Ashes","desc":"Found on a body within a broken building, there is a Rotten Stray nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6201","x":0.599271601,"y":0.686316999,"cat":"Weapons","group":"Equipment","title":"Crystal Spear","desc":"Can be found inside <a href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"_blank\"> Sellia Hideaway</a>. It can be found in a chest to the right of the entrance of the second room with huge crystal formations. The hidden wall is on the left side of a corpse","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spear.png?h=40"},{"id":"1131","x":0.379540251,"y":0.686378039,"cat":"Waygates","group":"Locations","title":"Divine Bridge Waygate","desc":"Waygate. Found at the edge of the bridge where it's been broken, past all the Golems. Transports you past the broken bridge sections directly to the <a href='https://eldenring.wiki.fextralife.com/Divine+Tower+of+Limgrave' target=\"_blank\">Divine Tower of Limgrave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"3240","x":0.579682013,"y":0.686378039,"cat":"Armor","group":"Equipment","title":"Cerulean Tear Scarab","desc":"Helmet. Found on a corpse on the roof of a building. Accessible by jumping across the rooftops.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"10378","x":0.597399316,"y":0.686395091,"cat":"Consumables","group":"Items","title":"Preserving Boluses - Sellia Hideaway","desc":"<p>Can be looted from a corpse located at the right of the entrance of the second room with huge crystal formations in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sellia+Hideaway' target=\"\">Sellia Hideaway</a>. To the left of the corpse there's also an illusory wall.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8834","x":0.464002667,"y":0.686469602,"cat":"NPCs","group":"Characters","title":"D, Hunter of the Dead Summonwater Village","desc":"D may be encountered at the southern entrance of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Summonwater+Village' target=\"\">Summonwater Village</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"10212","x":0.42466624,"y":0.686591683,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Saintsbridge","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"blank\">Limgrave</a>. At the bridge, close to the Saintsbridge Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"1152","x":0.531898024,"y":0.686622201,"cat":"Sites of Grace","group":"Locations","title":"Smoldering Wall","desc":"Site of Grace directly south of the telescope.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5943","x":0.55734763,"y":0.686774804,"cat":"Spirit Ashes","group":"Equipment","title":"Battlemage Hugues Ashes","desc":"Dropped by Battlemage Hugues (boss) located in the Sellia Evergaol. The best way to reach the evergaol is to travel south east along the cliff from the Dragonbarrow West site of grace. It will be on top of a plateau overlooking Aeonia Swamp.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6510","x":0.332733214,"y":0.686805323,"cat":"Consumables","group":"Items","title":"Golden Rune [2] I - Stormveil Castle","desc":"Found on the roof of the castle in the northern section.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6810","x":0.334502498,"y":0.686988445,"cat":"Key Items","group":"Items","title":"Cracked Pot - 2x Stormveil Castle","desc":"Found behind the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Living+Jar'>Living Jar</a> enemies between the Secluded Cell and Liftside Chamber (after 2nd shortcut) <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'>Sites of Grace</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"3223","x":0.575623459,"y":0.687110525,"cat":"Weapons","group":"Equipment","title":"Staff of Loss","desc":"Glintstone Staff. Found on a corpse leaning over a building's balcony. Accessible by jumping across the rooftops.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"6572","x":0.549595802,"y":0.687263128,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found one next to the Tree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7032","x":0.381667527,"y":0.687385209,"cat":"Consumables","group":"Items","title":"Soft Cotton - Divine Tower Bridge","desc":"Consumable. Can be found on the broken part of the bridge leading to the Divine Tower of Limgrave, past the teleporter waygate, by dropping down.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"772","x":0.418292219,"y":0.687568331,"cat":"NPCs","group":"Characters","title":"Iron Fist Alexander (First Location)","desc":"Alexander, a huge cauldron with arms and legs, is stuck on the ground and needs help.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3848","x":0.330199353,"y":0.687751452,"cat":"Shields","group":"Equipment","title":"Manor Towershield","desc":"Greatshield. From the Secluded Cell site of grace, backtrack to the west and up the ramp where the <a href='https://eldenring.wiki.fextralife.com/Living+Jar' target=\"_blank\">Living Jars</a> are and turn around towards the wooden platform. At the end of the platform, jump onto the ledge on the wall and follow it to the right towards some archways. Past the archways, enter the storage room on the right and head up the stairs to a walkway above. Head to the left towards a larger storage room full of <a href='https://eldenring.wiki.fextralife.com/Commoner' target=\"_blank\">Commoners</a>. You can find the shield under the second set of stairs in this room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"6578","x":0.603117901,"y":0.687873533,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily","desc":"Can be foun near a broken pillar on the cliff, next the Gatekeeper Statue.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3212","x":0.581422,"y":0.688758619,"cat":"Key Items","group":"Items","title":"Imbued Sword Key - Sellia, Town of Sorcery","desc":"Key Item used to activate a Waygate at <a href='https://eldenring.wiki.fextralife.com/The+Four+Belfries' target=\"_blank\">The Four Belfries</a>. Found in a chest in the northeast section of town. This location is initially sealed by a barrier that can be dispelled by lighting a brazier atop a tower in the southwest of town.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3214","x":0.578614958,"y":0.68894174,"cat":"Spells","group":"Equipment","title":"Night Comet","desc":"<a href=\"Night+Sorceries\" target=\"_blank\">Night Sorcery</a> spell. Found in a chest in the central section of town. This location is initially sealed by a barrier that can be dispelled by lighting a brazier atop a tower in the southwest of town.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"7052","x":0.329223424,"y":0.689094344,"cat":"Consumables","group":"Items","title":"Rainbow Stone - Stormveil Castle","desc":"Can be found on a corpse near the Lifside Chamber site of grace. You can only access if you head through the hidden passage and drop down.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6584","x":0.579896279,"y":0.689430064,"cat":"Crafting Materials","group":"Items","title":"Miquella's Lily - Sellia, Town of Sorcery","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Sellia,+Town+of+Sorcery' target=\"_blank\">Sellia, Town of Sorcery</a>, right from the main road of Siella, between two houses.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3358","x":0.573124758,"y":0.689491105,"cat":"Sites of Grace","group":"Locations","title":"Sellia Under-Stair","desc":"Site of Grace found west of town, at the bottom of a set of stairs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"959","x":0.435745785,"y":0.689552146,"cat":"NPCs","group":"Characters","title":"Nomadic Merchant North Limgrave","desc":"Nomadic Merchant. General Goods vendor found playing music by a campfire east of the bridge connecting <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stormhill'>Stormhill</a> and <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Limgrave'>East Limgrave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"8296","x":0.571046019,"y":0.689613186,"cat":"Armor","group":"Equipment","title":"Marionette Soldier Birdhelm","desc":"<p>Dropped by <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Avionette+Soldier' target=\"blank\">Avionette Soldier</a> enemies. Right next to the site of grace</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"960","x":0.342649049,"y":0.689674226,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed (A) - Stormveil Castle","desc":"Flask Upgrade Material. Found next to a Phantom Tree in the northeastern section of the castle, behind the courtyard. This tree is outside the cellar where you meet <a href='https://eldenring.wiki.fextralife.com/Nepheli+Loux' target=\"_blank\">Nepheli Loux</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"4461","x":0.454116298,"y":0.689704749,"cat":"Sites of Grace","group":"Locations","title":"Summonwater Village Outskirts","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8955","x":0.568954755,"y":0.689863454,"cat":"Consumables","group":"Items","title":"Rune Arc  - Caelid Swamp","desc":"Located on the island in the Caelid Swamp","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1352","x":0.420418714,"y":0.689918388,"cat":"Key Items","group":"Items","title":"Triumphant Delight (Gesture)","desc":"Gesture. Obtained as you push Alexander out of the ground he's stuck in.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6509","x":0.327941586,"y":0.690132032,"cat":"Consumables","group":"Items","title":"Golden Rune [5] B - Stormveil Castle","desc":"Found on a dead body reached by a walking on a ledge at the outer side of the northern section of the castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6508","x":0.330627337,"y":0.690345672,"cat":"Consumables","group":"Items","title":"Golden Rune [2] H - Stormveil Castle","desc":"Found on a dead body laying on the roof in the northern section of the castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8152","x":0.335874157,"y":0.690406713,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Liftside Chamber","desc":"Summoning Pool Effigy found near the Liftside Chamber site of grace in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6468","x":0.473105193,"y":0.690681397,"cat":"Consumables","group":"Items","title":"Golden Rune [1]","desc":"x5 Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5843","x":0.332454877,"y":0.690803478,"cat":"Sites of Grace","group":"Locations","title":"Liftside Chamber","desc":"<a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sites+of+grace'>Site of Grace</a> within Stormveil Castle, towards the west.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3204","x":0.574768657,"y":0.690833996,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Double Slash","desc":"Ash of War. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab'>Teardrop Scarab</a> found high up on a very large root. Accessible by jumping across the rooftops.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"3189","x":0.578246486,"y":0.690864518,"cat":"Locations","group":"Locations","title":"Sellia, Town of Sorcery","desc":"A once-great town renowned for its study of the sorcerous arts. Now lying in ruin, the ghosts of its former scholars still roam the streets.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sellia.png?h=40"},{"id":"6583","x":0.579560562,"y":0.690895037,"cat":"Crafting Materials","group":"Items","title":"Toxic Mushroom - Sellia, Town of Sorcery","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Sellia,+Town+of+Sorcery' target=\"_blank\">Sellia, Town of Sorcery</a> on a body on the rooftops.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6730","x":0.336728713,"y":0.690895037,"cat":"Crafting Materials","group":"Items","title":"Mushroom","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a>, on a dead body down stars.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5960","x":0.329494921,"y":0.690986599,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed (B) - Stormveil Castle","desc":"Obtained by defeating a <a href='https://eldenring.wiki.fextralife.com/Lesser+Ulcerated+Tree+Spirit' target=\"_blank\"> Lesser Ulcerated Tree Spirit</a> in the underground area of Stormveil Castle. This area can be accessed via a hidden path above the door of the room with some <a href='https://eldenring.wiki.fextralife.com/Living+Jar' target=\"_blank\">Living Jar</a> enemies, or by making a damaging drop outside the Liftside Chamber Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"4668","x":0.508928893,"y":0.69104764,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Flame of the Redmanes","desc":"Ash of War. Dropped by an invisible Teardrop Scarab near the North Fort Gael Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"3953","x":0.342434225,"y":0.69110868,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] D - Stormveil Castle","desc":"Upgrade Material. Held by a corpse outside the room where <a target=\"blank\" href=\"nepheli+loux\">Nepheli Loux</a> is located, passing the wooden barricades to the west and up the stairs on your right.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6507","x":0.340454749,"y":0.691413883,"cat":"Consumables","group":"Items","title":"Golden Rune [2] G - Stormveil Castle","desc":"Found on a dead body sitting on the ground in the wine cellar where you meet <a href=\"Nepheli+Loux\" target=\"_blank\">Nepheli Loux</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"964","x":0.335201058,"y":0.691688564,"cat":"Weapons","group":"Equipment","title":"Omen Cleaver","desc":"Curved Greatsword. Dropped by the Omen enemy in the northwest section of the courtyard. It is advised to take out all of the lesser enemies nearby before taking on the ogre.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedgreatsword.png?h=40"},{"id":"6469","x":0.471182437,"y":0.692054806,"cat":"Consumables","group":"Items","title":"Golden Rune [2]","desc":"Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6903","x":0.337340849,"y":0.692054806,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy","desc":"One is held by a corpse at <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a>, reached by descending through the stairs beside Stormveil Front Gates Site of Grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"6151","x":0.405293211,"y":0.692176887,"cat":"Weapons","group":"Equipment","title":"Lance","desc":"On top of the big square structure to the west of <a href='https://eldenring.wiki.fextralife.com/Deathtouched+Catacombs' target=\"_blank\"> Deathtouched Catacombs</a>. Jump off the nearby cliff to reach the top.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatspear.png?h=40"},{"id":"6582","x":0.573334243,"y":0.692207409,"cat":"Crafting Materials","group":"Items","title":"Poisonbloom - Sellia, Town of Sorcery","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Sellia,+Town+of+Sorcery' target=\"_blank\">Sellia, Town of Sorcery</a>, on the roof of a building on the lower leve. Accessible by jumping across the rooftops.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"7031","x":0.373854428,"y":0.692237928,"cat":"Consumables","group":"Items","title":"Warming Stone - Stormhill","desc":"Consumable. From Stormveil Castle, on the bridge linking to Divine Tower of Limgrave. Can be found near the edge of the cratered portion of the bridge that leads to the tower, same area as the golem fight.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6726","x":0.330227315,"y":0.692298968,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf - Stormveil Castle","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a>. There is an Arteria Leaf inside the tower, guarded by a <a href='https://eldenring.wiki.fextralife.com/Giant+Bat' target=\"_blank\">Giant Bat</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"961","x":0.340328395,"y":0.692421049,"cat":"NPCs","group":"Characters","title":"Nepheli Loux (First Location)","desc":"<a href='https://eldenring.wiki.fextralife.com/Nepheli+Loux' target=\"_blank\">Nepheli Loux</a> Location 1. A fellow Tarnished warrior NPC found in a small room near the north of the castle. The entrance to this room is behind the courtyard, along the path leading up to the huge steps guarded by a Troll.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3193","x":0.579542396,"y":0.692421049,"cat":"Consumables","group":"Items","title":"Poison Grease - 2x Sellia, Town of Sorcery","desc":"Weapon Coating. 2x found on a corpse under a dead tree in the eastern section of town.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10213","x":0.483638567,"y":0.692726252,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: East Summonwater Village Lower Cliff","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"blank\">Limgrave</a>, on the lower cliff east of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Summonwater+Village' target=\"blank\">Summonwater Village</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"711","x":0.406330742,"y":0.692817814,"cat":"Shields","group":"Equipment","title":"Beast Crest Heater Shield","desc":"A large shield kept inside a chest at a camp.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"790","x":0.465924736,"y":0.693000936,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2]","desc":"Upgrade Material. Found in a corpse at the bottom of a cliff. The site is full of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/wolf'>Wolves</a> fighting a huge <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/lesser+runebear'>Lesser Runebear</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"966","x":0.333131752,"y":0.693000936,"cat":"Key Items","group":"Items","title":"Prophecy Painting","desc":"Info Item. Found by inspecting the large painting inside a building in the northwest section of the main courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6470","x":0.473532471,"y":0.693123017,"cat":"Consumables","group":"Items","title":"Golden Rune [5]","desc":"Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"926","x":0.337461192,"y":0.693306138,"cat":"Shields","group":"Equipment","title":"Wooden Greatshield","desc":"Greatshield. Found in a guardhouse near the northern section of the castle courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"963","x":0.342251104,"y":0.693306138,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] - Stormveil Castle (B)","desc":"Upgrade Material. 4 can be found on a corpse in the same room where <a href='https://eldenring.wiki.fextralife.com/Nepheli+Loux' target=\"_blank\">Nepheli Loux is.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1104","x":0.330653702,"y":0.693519778,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] E - Stormveil Castle","desc":"Upgrade Material. Found behind some explosive barrels on the top level of the castle walls accessed from the Rampart Tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1350","x":0.385885447,"y":0.693550301,"cat":"Flask Upgrades","group":"Items","title":"Strength-Knot Crystal Tear","desc":"Physick Flask Material. Found inside a stone receptacle near the edge of the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"3202","x":0.577577051,"y":0.693641859,"cat":"Key Items","group":"Items","title":"Redmane Painting","desc":"Key Info Item. Found as a large painting under some rubble near the center of town.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2934","x":0.504160112,"y":0.6937029,"cat":"Sites of Grace","group":"Locations","title":"Fort Gael North Site","desc":"Site of Grace for Fort Gael North in Caelid","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6727","x":0.33190587,"y":0.69376394,"cat":"Crafting Materials","group":"Items","title":"Poisonbloom - Stormveil Castle","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a> Castle's Underground Crypt, on a dead body nex to the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"791","x":0.482468913,"y":0.694032519,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Sacred Blade","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a>, situated next to a <strong>Spiritspring</strong>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"6505","x":0.33807159,"y":0.694252265,"cat":"Consumables","group":"Items","title":"Golden Rune [2] F - Stormveil Castle","desc":"x2 Found on one of the dead bodies at the ramp in the northern section of the main courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3269","x":0.588348075,"y":0.694496426,"cat":"NPCs","group":"Characters","title":"Millicent (First Location)","desc":"Millicent can be found in the Church of the Plague slumped against a wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6506","x":0.336120923,"y":0.694496426,"cat":"Consumables","group":"Items","title":"Golden Rune [4] B - Stormveil Castle","desc":"Found on one of the dead bodies at the ramp in the northern section of the main courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3208","x":0.575714773,"y":0.694618507,"cat":"Key Items","group":"Items","title":"Stonesword Key - Sellia, Town of Sorcery (Caelid)","desc":"<a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a>. Found on a corpse sitting high above on a ledge connecting two buildings. Accessible by jumping across the rooftops.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"7033","x":0.40937961,"y":0.694893192,"cat":"Consumables","group":"Items","title":"Exalted Flesh - Stormhill","desc":"Can be found on one of the bodies of the camp.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1103","x":0.331935418,"y":0.694954232,"cat":"NPCs","group":"Characters","title":"Sorcerer Rogier (First Location)","desc":"<p><a href='https://eldenring.wiki.fextralife.com/Sorcerer+Rogier' target=\"_blank\" rel=\"noopener noreferrer\">Sorcerer Rogier</a> Location 1. Friendly NPC who sells&nbsp;<a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Ashes+of+War' target=\"\">Ashes of War</a>&nbsp;. Initially met in the Chapel in the western section of the Castle. After you defeat Godrick, he moves to the <a href='https://eldenring.wiki.fextralife.com/Roundtable+Hold' target=\"_blank\" rel=\"noopener noreferrer\">Roundtable Hold</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"9837","x":0.596659077,"y":0.695039056,"cat":"Consumables","group":"Items","title":"Starlight Shards - Caelid","desc":"Can be found in front of a stone chalice monument.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6728","x":0.33962664,"y":0.695137354,"cat":"Crafting Materials","group":"Items","title":"Smoldering Butterfly - Stormveil Castle","desc":"Can be found at the <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a> courtyard, there are some corpses you can loot to find x1 <a href='https://eldenring.wiki.fextralife.com/Magic+Grease' target=\"_blank\">Magic Grease</a>, x1 Golden Rune (1), x2 Golden Rune (2), x1 Pike1, and x5 Smoldering Butterfly.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6370","x":0.330501956,"y":0.695259435,"cat":"Spells","group":"Equipment","title":"Rancorcall","desc":"Dropped from a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> that can be found at the underground crypt of the castle","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"3362","x":0.585936673,"y":0.695473075,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (Church of the Plague)","desc":"Flask Upgrade Material. Found on the ground in front of the altar at the <a href='https://eldenring.wiki.fextralife.com/Church+of+the+Plague' target=\"_blank\">Church of the Plague</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"6504","x":0.337707958,"y":0.695473075,"cat":"Consumables","group":"Items","title":"Golden Rune [1] D - Stormveil Castle","desc":"Found on one of the dead bodies at the ramp in the northern section of the main courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4527","x":0.546267883,"y":0.696022439,"cat":"Spells","group":"Equipment","title":"Rock Sling","desc":"<a href='https://eldenring.wiki.fextralife.com/Gravity+Sorceries' target=\"_blank\">Gravity Sorcery</a>. Found inside a chest in a cellar in the northern section of the <a href='https://eldenring.wiki.fextralife.com/Street+of+Sages+Ruins' target=\"_blank\">Street of Sages Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-purplespell.png?h=40"},{"id":"3219","x":0.589844494,"y":0.696052961,"cat":"Sites of Grace","group":"Locations","title":"Church of the Plague","desc":"Site of grace found within the Church of the Plague","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"5754","x":0.595703368,"y":0.696236083,"cat":"Talismans","group":"Equipment","title":"Prosthesis-Wearer Heirloom","desc":"Finish the sidequest given by Gowry in Caelid, then return to Millicent to receive the talisman.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"2924","x":0.340297887,"y":0.696358164,"cat":"Weapons","group":"Equipment","title":"Pike","desc":"Can be looted off a corpse that's lying on the heavily guarded courtyard. The nearest checkpoint is the Liftside Chamber site of grace","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spear.png?h=40"},{"id":"4403","x":0.359949815,"y":0.696449723,"cat":"Weapons","group":"Equipment","title":"Golem's Halberd","desc":"Dropped by one of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/golem'>Golems</a> at the bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-halberd.png?h=40"},{"id":"1119","x":0.332977371,"y":0.696602326,"cat":"Consumables","group":"Items","title":"Grace Mimic","desc":"Consumable. Given as a reward by a non-hostile Commoner NPC sitting on the roof of a building. Use the ladder nearby to reach him.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"802","x":0.486063611,"y":0.696877006,"cat":"Waygates","group":"Locations","title":"Sending Gate (Bestial Sanctum)","desc":"Teleporter to the <a href='https://eldenring.wiki.fextralife.com/Bestial+Sanctum' target=\"_blank\">Bestial Sanctum</a> in Caelid. See <a href='https://eldenring.wiki.fextralife.com/D+Hunter+of+the+Dead' target=\"_blank\">D, Hunter of the Dead</a> for details.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"1353","x":0.304749301,"y":0.696968569,"cat":"Shields","group":"Equipment","title":"Golden Beast Crest Shield","desc":"Greatshield. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Grafted+Scion' target=\"_blank\">Grafted Scion</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"7041","x":0.335693646,"y":0.696968569,"cat":"Consumables","group":"Items","title":"Magic Grease - Stormveil Castle","desc":"Can be found inside Stormveil Castle, on a corpse laying in the courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3218","x":0.588501261,"y":0.697273771,"cat":"Locations","group":"Locations","title":"Church of the Plague","desc":"Abandoned church overcome by the decay of rot that pollutes Caelid.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"914","x":0.337764584,"y":0.697499623,"cat":"Talismans","group":"Equipment","title":"Claw Talisman","desc":"Talisman. Found on a corpse atop a tower accessible by ladder. The tower has several none-hostile Eagles at the top.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6413","x":0.51764893,"y":0.697517933,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4] - West Caelid","desc":"Upgrade Material. Found on a dead body sitting on a chair.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"1223","x":0.307011902,"y":0.697731573,"cat":"Bosses","group":"Characters","title":"Grafted Scion (Tutorial)","desc":"Boss fought within the tutorial stage at <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Chapel+of+Anticipation'>Chapel of Anticipation</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"9830","x":0.332553315,"y":0.697762095,"cat":"Bosses","group":"Characters","title":"Ulcerated Tree Spirit - Stormveil Castle","desc":"Found at the bottom of a gutter. The entrance to the crypt is found near the Liftside Chamber site of grace within <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"blank\">Stormveil Castle</a>. Defeating it grants a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Golden+Seed' target=\"blank\">Golden Seed</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"7045","x":0.339142395,"y":0.697914695,"cat":"Consumables","group":"Items","title":"Fireproof Dried Liver - Stormveil Castle","desc":"Can be found in a corpse located in the cellar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"968","x":0.35533672,"y":0.698097817,"cat":"Talismans","group":"Equipment","title":"Boltdrake Talisman","desc":"Talisman. Found on a corpse sitting against a tall brazier.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"1809","x":0.54309381,"y":0.698433541,"cat":"Armor","group":"Equipment","title":"Perfumer Traveler's Set","desc":"Set includes: <a class=\"wiki_link\" target=\"_blank\" title=\"Elden Ring Traveler's Hat\" href='https://eldenring.wiki.fextralife.com/Traveler's+Hat' target=\"_blank\" >Traveler's Hat</a>, <a class=\"wiki_link\" title=\"Elden Ring Perfumer's Traveling Garb\" href='https://eldenring.wiki.fextralife.com/Perfumer's+Traveling+Garb' target=\"_blank\" >Perfumer's Traveling Garb</a>, <a class=\"wiki_link\" title=\"Elden Ring Traveler's Gloves\" href='https://eldenring.wiki.fextralife.com/Traveler's+Gloves' target=\"_blank\" >Traveler's Gloves</a>, <a class=\"wiki_link\" title=\"Elden Ring Traveler's Slops\" href='https://eldenring.wiki.fextralife.com/Traveler's+Slops' target=\"_blank\" >Traveler's Slops</a>, can be found on a corpse in a corner in the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-armor.png?h=40"},{"id":"6731","x":0.333982074,"y":0.69858614,"cat":"Crafting Materials","group":"Items","title":"Smoldering Butterfly - Stormveil Castle","desc":"Can be found <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a> in the Underground Crypt area on a dead body inside the Root Monster room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"922","x":0.335719803,"y":0.698891343,"cat":"Weapons","group":"Equipment","title":"Misericorde","desc":"Dagger. Found on a corpse inside the Armory. Requires a <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a> in order to dispel the fog gate barring entry.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"980","x":0.339870601,"y":0.699043946,"cat":"Weapons","group":"Equipment","title":"Highland Axe","desc":"Axe. Found in the same hall as the Grafted Scion miniboss, under a large painting.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-axe.png?h=40"},{"id":"6503","x":0.338470957,"y":0.699288108,"cat":"Consumables","group":"Items","title":"Golden Rune [2] E - Stormveil Castle","desc":"Found on a dead body in a room with very long tables one level below the top one.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"967","x":0.352565029,"y":0.699379667,"cat":"Sites of Grace","group":"Locations","title":"Limgrave Tower Bridge","desc":"Site of Grace found near the eastern bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3022","x":0.363254909,"y":0.699379667,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Wild Strikes","desc":"Dropped from a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\"> Teardrop Scarab</a> located in the middle of the path leading from the Stormhill Shack site of grace to the Castleward Tunnel site of grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"1354","x":0.305875659,"y":0.69947123,"cat":"Weapons","group":"Equipment","title":"Ornamental Straight Sword","desc":"Straight Sword. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Grafted+Scion' target=\"_blank\">Grafted Scion</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"1806","x":0.546542763,"y":0.699562788,"cat":"Locations","group":"Locations","title":"Street of Sages Ruins","desc":"Ruins with lots of poison flowers and poison casters. You can pick up <a href='https://eldenring.wiki.fextralife.com/Rock+Sling' target=\"_blank\">Rock Sling</a> Sorcery as well as the <a href='https://eldenring.wiki.fextralife.com/Meteorite+Staff' target=\"_blank\">Meteorite Staff</a> here.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"3019","x":0.331845525,"y":0.699562788,"cat":"Talismans","group":"Equipment","title":"Prince of Death's Pustule","desc":"Looted off a corpse that can be found at the pit of the castle's crypt after defeating the <a href='https://eldenring.wiki.fextralife.com/Ulcerated+Tree+Spirit' target=\"_blank\">Ulcerated Tree Spirit</a>. The body can be found next to a giant face.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4530","x":0.558383077,"y":0.699562788,"cat":"Sites of Grace","group":"Locations","title":"Inner Aeonia","desc":"Site of grace within the Swamp of Aeonia","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"923","x":0.33715599,"y":0.699684869,"cat":"Key Items","group":"Items","title":"Iron Whetblade","desc":"Key Item. Found on a corpse inside the Armory. Requires a <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a> in order to dispel the fog gate barring entry.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"8956","x":0.573849663,"y":0.699715392,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Sellia Gate","desc":"Summoning Pool Effigy found right outside the Sellia Town gate. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3238","x":0.590972406,"y":0.699837473,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud (D)","desc":"Many sacramental buds can be found within the Church of the Plague","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8004","x":0.427355592,"y":0.699990072,"cat":"Spirit Ashes","group":"Equipment","title":"Banished Knight Engvall Ashes","desc":"Spirit Ashes. Dropped by the boss of Murkwater Catacombs: Grave Warden Duelist, after Patch 1.03.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"8101","x":0.424670095,"y":0.700203716,"cat":"Weapons","group":"Equipment","title":"Battle Hammer","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Grave+Warden+Duelist'>Grave Warden Duelist</a> in <a href='https://eldenring.wiki.fextralife.com/Murkwater+Catacombs'>Murkwater Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-warhammer.png?h=40"},{"id":"6904","x":0.342468065,"y":0.700417348,"cat":"Key Items","group":"Items","title":"Festering Bloody Finger","desc":"Can be found x3 Festering Bloody Finger at <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a> on a rooftop, in the courtyard","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"3101","x":0.429369826,"y":0.700447878,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [1] - Murkwater Cave","desc":"Multiple found inside <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Murkwater+Catacombs'>Murkwater Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"796","x":0.48194686,"y":0.700478396,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (Third Church of Marika)","desc":"Allows the user to upgrade the Crimson and Cerulean Flask Potency. Located on the ground in front of the statue in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Third+Church+of+Marika'>Third Church of Marika</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"6483","x":0.339356032,"y":0.700478396,"cat":"Consumables","group":"Items","title":"Golden Rune [1] C - Stormveil Castle","desc":"Found on a pile of limbs and dead bodies in the main courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6464","x":0.461561652,"y":0.700508918,"cat":"Consumables","group":"Items","title":"Golden Rune [2]","desc":"Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"9835","x":0.333426056,"y":0.700539437,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Rampart Tower","desc":"Summoning Pool Effigy in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"blank\">Stormveil Castle</a>. Make your way up the Rampart Tower. It will be near the Site of Grace. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"5707","x":0.543368491,"y":0.700569959,"cat":"Key Items","group":"Items","title":"Perfume Bottle - Street of Sages Ruins","desc":"Key Item. Found on a corpse in the corner of the ruins along with the <a href='https://eldenring.wiki.fextralife.com/Traveler's+Set' target=\"_blank\">Traveler's Set</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6152","x":0.346652074,"y":0.700844639,"cat":"Weapons","group":"Equipment","title":"Arbalest","desc":"Using a Stonesword Key to access, additionally obtaining the Godskin prayerbook and Godslayer Seal: From the Rampart Tower bonfire, take the shortcut lift down to where the Grafted miniboss is fought inside the storeroom (or reach this point manually). Exit into the courtyard with the flamethrowers and barricades. Take an immediate left and hug the wall until you enter a cellar containing rats. You will hit a fog wall that requires one Stonesword Key to open. Continue past this fog wall until you reach an outdoors area again. Pull an immediate right and hug the wall until you reach a ladder. Continue past this point and almost all the way across the bridge, then jump to the rocky outcropping to your right (it's a tight jump). Continue and jump back into a walled-in area with a ballista. The Arbalest is on a corpse in that area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crossbow.png?h=40"},{"id":"979","x":0.336209875,"y":0.701027761,"cat":"Bosses","group":"Characters","title":"Grafted Scion","desc":"Optional Miniboss. Patrols the main hall of his fortress. No special drops.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"1213","x":0.426134795,"y":0.701088802,"cat":"Bosses","group":"Characters","title":"Grave Warden Duelist (Limgrave)","desc":"Found within Murkwater Catacombs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5652","x":0.330135801,"y":0.701210882,"cat":"Armor","group":"Equipment","title":"Crimson Hood","desc":"<a target=\"blank\" href='https://eldenring.wiki.fextralife.com/roderika'>Roderika's</a> questline must be completed and spirit tuning must be unlocked for this item to appear on top of the pile of corpses surrounded by the <a href='https://eldenring.wiki.fextralife.com/Rotten+Stray' target=_blank\">Rotten Strays</a> where the <a href='https://eldenring.wiki.fextralife.com/Chrysalids'+Memento' target=\"_blank\">Chrysalids' Memento</a> was acquired.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"921","x":0.333556542,"y":0.701241404,"cat":"Shields","group":"Equipment","title":"Hawk Crest Wooden Shield","desc":"Medium Shield. Found on a corpse inside the Armory. Requires a <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a> to dispel the fog gate barring entry.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"1753","x":0.398454228,"y":0.701546607,"cat":"Bosses","group":"Characters","title":"Bell Bearing Hunter (Warmaster's Shack)","desc":"Field Boss. Invades the <a href='https://eldenring.wiki.fextralife.com/Warmaster's+Shack' target=\"_blank\">Warmaster's Shack</a>, but only at night time, replacing <a href='https://eldenring.wiki.fextralife.com/Knight+Bernahl' target=\"_blank\">Knight Bernahl</a>. You have to travel here from another site of grace to trigger it. Drops <a href='https://eldenring.wiki.fextralife.com/Bone+Peddler's+Bell+Bearing' target=\"_blank\">Bone Peddler's Bell Bearing</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6465","x":0.463369342,"y":0.701546607,"cat":"Consumables","group":"Items","title":"Golden Rune [4]","desc":"x2 Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"26853","x":0.44270245,"y":0.701668688,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6606","x":0.342982334,"y":0.701699206,"cat":"Key Items","group":"Items","title":"Stonesword Key - Stormveil Castle (C)","desc":"At <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/stormveil+castle'>Stormveil Castle's</a> Underground Crypt.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"920","x":0.339690883,"y":0.701729728,"cat":"Key Items","group":"Items","title":"Dozing Cross-Legged Gesture","desc":"Gesture. Found on a corpse on the largest roof in the area. Accessible from the top floor of the Rampart Tower with careful platforming.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6062","x":0.335385836,"y":0.701851809,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] C - Stormveil Castle","desc":"Upgrade Material. Found on a corpse on the rooftops accessible from the top of the very top of the Rampart Tower.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1349","x":0.393026936,"y":0.701882328,"cat":"NPCs","group":"Characters","title":"Bernahl (First Location)","desc":"<a href='https://eldenring.wiki.fextralife.com/Bernahl' target=\"_blank\">Bernahl</a>, Location 1. Tarnished Knight NPC found at the <a href='https://eldenring.wiki.fextralife.com/Warmaster's+Shack' target=\"_blank\">Warmaster's Shack</a>. Sells various <a href='https://eldenring.wiki.fextralife.com/Ashes+of+War' target=\"_blank\">Ashes of War</a>. Moves to the <a href='https://eldenring.wiki.fextralife.com/Volcano+Manor' target=\"_blank\">Volcano Manor</a> in <a href='https://eldenring.wiki.fextralife.com/Mt.+Gelmir' target=\"_blank\">Mt. Gelmir</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6501","x":0.334167647,"y":0.702004409,"cat":"Consumables","group":"Items","title":"Golden Rune [2] D - Stormveil Castle","desc":"x2 Found at the top of the castle on a dead body over a platform.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6463","x":0.459310194,"y":0.702340133,"cat":"Consumables","group":"Items","title":"Golden Rune [1]","desc":"x3 Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"789","x":0.484744868,"y":0.702462214,"cat":"Flask Upgrades","group":"Items","title":"Crimson Crystal Tear","desc":"A crystal mixed to enhance the effects of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Flask+of+Wondrous+Physick'>Flask of Wondrous Physick</a>. Located in front of the statue in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Third+Church+of+Marika'>Third Church of Marika</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"925","x":0.338409045,"y":0.702492733,"cat":"Key Items","group":"Items","title":"Chrysalids' Memento","desc":"Key Quest Item. Found on top of the pile of corpses surrounded by <a href='https://eldenring.wiki.fextralife.com/Rotten+Stray' target=\"_blank\">Rotten Strays</a> in a small room. This room is adjacent to the <a href='https://eldenring.wiki.fextralife.com/Grafted+Scion' target=\"_blank\">Grafted Scion</a>'s hall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"23","x":0.461010204,"y":0.702523255,"cat":"Key Items","group":"Items","title":"Fevor's Cookbook [1]","desc":"Found on a corpse on the graveyard south from <a href='https://eldenring.wiki.fextralife.com/Summonwater' target=\"_blank\">Summonwater</a>. Unlocks <a href='https://eldenring.wiki.fextralife.com/Sleep+Pot' target=\"_blank\">Sleep Pot</a> Recipe.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"1960","x":0.34472321,"y":0.702523255,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [1] - Stormveil Castle","desc":"Upgrade Material. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Lion+Guardian' target=\"_blank\"> Lion Guardian</a> east of the castle courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"788","x":0.479291634,"y":0.702553773,"cat":"Key Items","group":"Items","title":"Flask of Wondrous Physick","desc":"Laying on the ground in front of the statue. Bestows various special effects.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-flask.png?h=40"},{"id":"5925","x":0.385818236,"y":0.702614814,"cat":"Consumables","group":"Items","title":"Fire Arrow - 1x Stormhill Warmaster Shack","desc":"Consumable Item. One arrow can be looted from a corpse in the road, guarded by two Mercenaries.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1216","x":0.396566477,"y":0.702889498,"cat":"Locations","group":"Locations","title":"Warmaster's Shack","desc":"Small shack in a remote place of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Stormhill'>Stormhill</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"6605","x":0.341212358,"y":0.702920016,"cat":"Key Items","group":"Items","title":"Stonesword Key - Stormveil Castle (B)","desc":"Held by a corpse above the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/grafted+scion'>Grafted Scion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"919","x":0.337096688,"y":0.702950539,"cat":"Key Items","group":"Items","title":"Stonesword Key - Stormveil Castle (A)","desc":"<a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a>. Found on a corpse inside a building section with a broken roof. Accessed from the very top of the Rampart Tower with careful platforming.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4252","x":0.513618036,"y":0.70313366,"cat":"Bosses","group":"Characters","title":"Frenzied Duelist","desc":"Boss of <a href='https://eldenring.wiki.fextralife.com/Gaol+Cave' target=\"_blank\">Gaol Cave</a> in Caelid. Drops <a href='https://eldenring.wiki.fextralife.com/Putrid+Corspe+Ashes' target=\"_blank\">Putrid Corpse Ashes</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"1212","x":0.428301489,"y":0.703225219,"cat":"Locations","group":"Locations","title":"Murkwater Catacombs","desc":"Following the Murkwater, you can find the Murkwater Catacombs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"912","x":0.333516945,"y":0.703255741,"cat":"Sites of Grace","group":"Locations","title":"Rampart Tower","desc":"Site of grace located at the Rampart Tower of the Stormveil Castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4464","x":0.42460945,"y":0.703316782,"cat":"Sites of Grace","group":"Locations","title":"Murkwater Catacombs","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8001","x":0.399278264,"y":0.70340834,"cat":"Key Items","group":"Items","title":"Bone Peddler's Bell Bearing","desc":"Bell Bearing. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Bell+Bearing+Hunter' target=\"_blank\">Bell Bearing Hunter</a> that invades the <a href='https://eldenring.wiki.fextralife.com/Warmaster's+Shack' target=\"_blank\">War Master's Shack</a> at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4251","x":0.516029407,"y":0.703499903,"cat":"Spirit Ashes","group":"Equipment","title":"Putrid Corpse Ashes","desc":"Spirit Ash. Dropped by the boss of <a href='https://eldenring.wiki.fextralife.com/Gaol+Cave' target=\"_blank\">Gaol Cave</a>: <a href='https://eldenring.wiki.fextralife.com/Frenzied+Duelist' target=\"_blank\">Frenzied Duelist</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6873","x":0.539530787,"y":0.703591462,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Street of Sages Ruins","desc":"<strong>Golden Rune (4)</strong> held by a corpse within one of the shattered buildings.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1221","x":0.308319674,"y":0.703683025,"cat":"Locations","group":"Locations","title":"Chapel of Anticipation","desc":"The starting building players are placed in after the game introduction.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"6466","x":0.461538147,"y":0.703683025,"cat":"Consumables","group":"Items","title":"Golden Rune [6]","desc":"Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4253","x":0.511573497,"y":0.703744065,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5] - Gaol Cave","desc":"Upgrade Material. 1x Found as a treasure inside a chest in a cell within Gaol Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2706","x":0.32961633,"y":0.703957705,"cat":"Spells","group":"Equipment","title":"Aspects of the Crucible: Horns","desc":"Incantation. Dropped by <a href='https://eldenring.wiki.fextralife.com/Crucible+Knight' target=\"_blank\">Crucible Knight</a>found at the bottom floor of the Rampart Tower","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"3188","x":0.582001238,"y":0.704140826,"cat":"NPCs","group":"Characters","title":"Gowry","desc":"Quest NPC. A once great Sage living in isolation. Found inside his shack near <a href='https://eldenring.wiki.fextralife.com/Sellia,+Town+of+Sorcery' target=\"_blank\">Sellia, Town of Sorcery</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6482","x":0.335937803,"y":0.704171349,"cat":"Consumables","group":"Items","title":"Golden Rune [2] C - Stormveil Castle","desc":"Found on a wooden platform that can be reached by falling from above.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"977","x":0.340331801,"y":0.704415511,"cat":"Key Items","group":"Items","title":"Mimic's Veil","desc":"Reusable Key Item. Found in a chest inside the assembly room with the large war table. There is a Banished Knight in this room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"10211","x":0.415368982,"y":0.704415511,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: West Murkwater Catacombs","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"blank\">Limgrave</a>, Stormhill. <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Murkwater+Catacombs' target=\"blank\">Murkwater Catacombs</a> Cliffside, west of the Catacomb entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"1153","x":0.528509967,"y":0.704446029,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Lifesteal Fist","desc":"Ash of War Upgrade. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> near the Caelid Highway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"733","x":0.482310782,"y":0.704598632,"cat":"Locations","group":"Locations","title":"Third Church of Marika","desc":"The Ruins of an Old Church found in the Mistwood. The most prominent sight here is a statue of a lady with her arms outstretched.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"1804","x":0.54044015,"y":0.704659673,"cat":"Weapons","group":"Equipment","title":"Meteorite Staff","desc":"Glintstone Staff with S scaling but no upgrades. Found on a corpse hanging from a window in <a href='https://eldenring.wiki.fextralife.com/Street+of+Sages+Ruins' target=\"_blank\">Street of Sages Ruins</a> in the swamp of Caelid.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"918","x":0.337917743,"y":0.704781754,"cat":"Talismans","group":"Equipment","title":"Curved Sword Talisman","desc":"Talisman. Found in Stormveil Castle, a chest inside a dark room in the Wine Cellar with the <a href='https://eldenring.wiki.fextralife.com/Banished+Knight' target=\"_blank\">Banished Knight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"7036","x":0.344627595,"y":0.704864769,"cat":"Consumables","group":"Items","title":"Exalted Flesh - Stormveil Castle","desc":"Can be found on a corpse in the back of the first floor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4206","x":0.518104759,"y":0.705117475,"cat":"Shields","group":"Equipment","title":"Pillory Shield","desc":"Small Shield. Found inside <a href='https://eldenring.wiki.fextralife.com/Gaol+Cave' target=\"_blank\">Gaol Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-smallshield.png?h=40"},{"id":"4469","x":0.407034221,"y":0.705178515,"cat":"Bosses","group":"Characters","title":"Deathbird (Stormhill)","desc":"Appears only at night. East of Warmaster's Shack just over the cliff. It drops the <a href='https://eldenring.wiki.fextralife.com/Blue-Feathered+Branchsword' target=\"_blank\">Blue-Feathered Branchsword</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"5412","x":0.571871718,"y":0.705178515,"cat":"Spells","group":"Equipment","title":"Eternal Darkness","desc":"<a href='https://eldenring.wiki.fextralife.com/Night+Sorceries' target=\"_blank\">Night Sorcery</a>. Found in a jail cell inside the <a href='https://eldenring.wiki.fextralife.com/Swamp+Lookout+Tower' target=\"_blank\">Swamp Lookout Tower</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"915","x":0.3339483,"y":0.705239556,"cat":"Weapons","group":"Equipment","title":"Hookclaws","desc":"Claw weapon. Found on a corpse in the corner of a small corridor on the first level of the wine cellar, filled with crates and patrolled by a single Castle Guard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-claws.png?h=40"},{"id":"3187","x":0.580629223,"y":0.705300596,"cat":"Locations","group":"Locations","title":"Gowry's Shack","desc":"A lone shack found below the eastern hills near <a href='https://eldenring.wiki.fextralife.com/Sellia,+Town+of+Sorcery' target=\"_blank\">Sellia, Town of Sorcery</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"6364","x":0.339080484,"y":0.705300596,"cat":"Key Items","group":"Items","title":"Godskin Prayerbook","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a>, Nearest Site of Grace: Rampart Tower. From the Rampart Tower site of grace, go out the door to the outside (where the birds are). Take a running jump onto the roof across from the door. On the left side of the roof, there will be two separate areas you can drop down to. Drop down to the one without stairs on it, and drop down again. You'll land by a set of steps going down. Go down the steps to find some rats and a white fog wall. You'll need a Stonesword Key to pass through the fog wall, and inside will be two chests. One contains the Godskin Prayerbook, the other contains the <a href='https://eldenring.wiki.fextralife.com/Godslayer's+Seal' target=\"_blank\">Godslayer's Seal</a>. Alternatively, from the Liftside Chamber Site of Grace, exit from the door to the courtyard and turn right. Hug the right side wall past all the enemies. You'll find the set of stairs going down on the wall on the other side.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tome.png?h=40"},{"id":"6732","x":0.349002112,"y":0.705331118,"cat":"Crafting Materials","group":"Items","title":"Old Fang - Stormveil Castle","desc":"Can be acquierd at <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a> main castle grounds by defeating the Lion Guardian.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6480","x":0.342260665,"y":0.705450758,"cat":"Consumables","group":"Items","title":"Golden Rune [4] A - Stormveil Castle","desc":"Looted from a dead body hanging from the higher level.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4208","x":0.510017865,"y":0.705453199,"cat":"Weapons","group":"Equipment","title":"Wakizashi","desc":"Dagger. Found within <a href='https://eldenring.wiki.fextralife.com/Gaol+Cave' target=\"_blank\">Gaol Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"1209","x":0.416981713,"y":0.70557528,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] C","desc":"Found over a hanging body, near one of the structures","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3209","x":0.561343508,"y":0.705605799,"cat":"Sites of Grace","group":"Locations","title":"Heart of Aeonia","desc":"Site of grace in the heart of the Aeonia Swamp","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"7039","x":0.332397492,"y":0.705636321,"cat":"Consumables","group":"Items","title":"Drawstring Fire Grease - Stormveil Castle","desc":"Two of them can be looted from a corpse located at Stormveil Castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5411","x":0.570435543,"y":0.705788921,"cat":"Locations","group":"Locations","title":"Swamp Lookout Tower","desc":"A long-abandoned lookout tower, that now only oversees the poisonous swamp that plagues Caelid.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tower.png?h=40"},{"id":"6801","x":0.406086136,"y":0.705972042,"cat":"Crafting Materials","group":"Items","title":"Beast Liver","desc":"Can be found on a dead body near to <a href='https://eldenring.wiki.fextralife.com/Deathbird' target=\"_blank\">Deathbird</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"916","x":0.337798647,"y":0.706246726,"cat":"Key Items","group":"Items","title":"Rusty Key","desc":"Key Item. Found on a corpse inside the room with the Banished Knight.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"4473","x":0.410261081,"y":0.706271142,"cat":"Talismans","group":"Equipment","title":"Blue-Feathered Branchsword","desc":"Talisman. Dropped from miniboss that only spawns at night: <a href='https://eldenring.wiki.fextralife.com/Deathbird' target=\"_blank\">Deathbird</a> (Stormhill)","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"4255","x":0.516090443,"y":0.706307766,"cat":"Sites of Grace","group":"Locations","title":"Gaol Cave","desc":"Site of Grace within Gaol Cave","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8170","x":0.425493877,"y":0.706307766,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Murkwater Catacombs","desc":"Summoning Pool Effigy found at the end of a narrow hallway after the Murkwater Catacombs site of grace in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3244","x":0.567293732,"y":0.706338285,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Sacred Ring of Light","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> in the southeast section of Aeonia Swamp.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"6733","x":0.348231231,"y":0.706368807,"cat":"Crafting Materials","group":"Items","title":"Beast Blood - Stormveil Castle","desc":"Can be acquierd at <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a> by defeating the Lion Guardian.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"536","x":0.374077384,"y":0.706704528,"cat":"NPCs","group":"Characters","title":"Roderika","desc":"In <a href='https://eldenring.wiki.fextralife.com/Stormhill+Shack' target=\"_blank\">Stormhill Shack</a> there's a Woman with a Red Hood. She is <a href='https://eldenring.wiki.fextralife.com/Roderika' target=\"_blank\">Roderika</a> and has a quest for the player that unlocks Spirit Ash upgrades","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3900","x":0.372031114,"y":0.706704528,"cat":"Spirit Ashes","group":"Equipment","title":"Spirit Jellyfish Ashes","desc":"<p>Obtained from <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Roderika' target=\"\">Roderika</a> form <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Stormhill+Shack' target=\"\">Stormhill Shack</a> while pursuing her questline.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"4203","x":0.514505264,"y":0.706826609,"cat":"Locations","group":"Locations","title":"Gaol Cave","desc":"A cave locked behind two Stone Sword Key seals. The cave has a second exit on the coast North-West of Fort Gael, where the Regalia of Eochaid can be found.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"1154","x":0.530310642,"y":0.707101293,"cat":"Sites of Grace","group":"Locations","title":"Astray from Caelid Highway North","desc":"Site of Grace found by veering off the Caelid Highway towards the east.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"974","x":0.341396072,"y":0.707192852,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] B - Stormveil Castle","desc":"Upgrade Material. Found on a corpse on an upper platform where Castle Guards are mounted on ballistae.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1219","x":0.396080272,"y":0.707192852,"cat":"Sites of Grace","group":"Locations","title":"Warmaster's Shack","desc":"Site of grace in Warmaster's Shack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"787","x":0.482989555,"y":0.707375973,"cat":"Sites of Grace","group":"Locations","title":"Third Church of Marika","desc":"Site of Grace located at <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Third+Church+of+Marika'>Third Church of Marika</a>, an antique building in ruins featuring a large statue of a woman with her arms wide open.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4204","x":0.499428541,"y":0.707467536,"cat":"Weapons","group":"Equipment","title":"Regalia of Eochaid","desc":"Straight Sword. Accessed by dropping down to this area after progressing through <a href='https://eldenring.wiki.fextralife.com/Gaol+Cave' target=\"_blank\">Gaol Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"6060","x":0.441272437,"y":0.707528576,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1]","desc":"On a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6478","x":0.347921932,"y":0.707559095,"cat":"Consumables","group":"Items","title":"Golden Rune [2] A - Stormveil Castle","desc":"Looted from one of the three bodies at the entrance of Stormveil Castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3401","x":0.558321427,"y":0.707711698,"cat":"Key Items","group":"Items","title":"Unalloyed Gold Needle","desc":"Key Quest Item. Required to progress <a href='https://eldenring.wiki.fextralife.com/Gowry' target=\"_blank\">Gowry</a>'s questline. Dropped by <a href='https://eldenring.wiki.fextralife.com/Commander+O'Neil' target=\"_blank\">Commander O'Neil</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6602","x":0.510568704,"y":0.707772739,"cat":"Key Items","group":"Items","title":"Stonesword Key - Gaol Cave","desc":"Found within the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Gaol+Cave'>Gaol Cave</a>, near <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Wakizashi'>Wakizashi</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6729","x":0.445143915,"y":0.707986378,"cat":"Key Items","group":"Items","title":"Homing Instinct Painting","desc":"Key Info Item. Painting inside the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/artist's+shack'>Artist's Shack</a> in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Limgrave'>Limgrave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"7756","x":0.517861645,"y":0.707986378,"cat":"Consumables","group":"Items","title":"Rune Arc - Gaol Cave","desc":"Consumable. Found in a chest inside the <a href='https://eldenring.wiki.fextralife.com/Gaol+Cave' target=\"_blank\">Gaol Cave</a>, next to the Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7050","x":0.335293033,"y":0.708138982,"cat":"Consumables","group":"Items","title":"Gold-Pickled Fowl Foot - Stormveil Castle","desc":"Can be found at a stone balcony, above one of the rooms.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"12361","x":0.392779006,"y":0.708146185,"cat":"Consumables","group":"Items","title":"Golden Rune [3] - Warmaster's Shack Southwest","desc":"Located within a grave area, in a sarcophagi on the hill south-west above <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Warmaster's+Shack' target=\"blank\">Warmaster's Shack</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"12362","x":0.391239712,"y":0.708146185,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - Warmaster's Shack Southwest","desc":"Located within a grave area, in a sarcophagi on the hill south-west above <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Warmaster's+Shack' target=\"blank\">Warmaster's Shack</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6123","x":0.552493264,"y":0.708200022,"cat":"NPC Invaders","group":"Characters","title":"Millicent (NPC Invader)","desc":"Found in the South-East of the Swamp of Aeonia near the geysers. NPC drop: Sacremental Bud, Golden Rune [3], Golden Rune [5], Golden Rune [10]","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"527","x":0.371036004,"y":0.708413662,"cat":"Sites of Grace","group":"Locations","title":"Stormhill Shack","desc":"Site of Grace found right next to <a href='https://eldenring.wiki.fextralife.com/Stormhill+Shack' target=\"_blank\">Stormhill Shack</a>..","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2948","x":0.504403281,"y":0.708505225,"cat":"Waygates","group":"Locations","title":"Fort Gael Waygate Teleporter","desc":"Located at the top of the watchtower of <a href='https://eldenring.wiki.fextralife.com/Fort+Gael' target=\"_blank\">Fort Gael</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"6120","x":0.582275919,"y":0.708596783,"cat":"NPCs","group":"Characters","title":"Millicent (Second Location)","desc":"She will appear here, after you give her the <a href='https://eldenring.wiki.fextralife.com/Unalloyed+Gold+Needle' target=\"_blank\"> Unalloyed Gold Needle</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"29","x":0.373863575,"y":0.708627306,"cat":"Locations","group":"Locations","title":"Stormhill Shack","desc":"An important quest starts here! Make sure to visit to unlock Spirit Ash upgrades.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"1560","x":0.561189576,"y":0.708657824,"cat":"Bosses","group":"Characters","title":"Commander O'Neil","desc":"Great Enemy. Drops <a href='https://eldenring.wiki.fextralife.com/Commander's+Standard' target=\"_blank\">Commander's Standard</a> and <a href='https://eldenring.wiki.fextralife.com/Unalloyed+Gold+Needle' target=\"_blank\"> Unalloyed Gold Needle</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6481","x":0.336361229,"y":0.708871468,"cat":"Consumables","group":"Items","title":"Golden Rune [2] B - Stormveil Castle","desc":"Found on a dead body on a wooden platform in the back entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2923","x":0.340326962,"y":0.708901986,"cat":"Weapons","group":"Equipment","title":"Brick Hammer","desc":"Can be found on the 3rd floor. It is in a corpse dangling from a window.You have to access from the 4th floor, using the wooden platforms outside.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-warhammer.png?h=40"},{"id":"903","x":0.346552863,"y":0.708993549,"cat":"Locations","group":"Locations","title":"Stormveil Castle","desc":"The first <a href='https://eldenring.wiki.fextralife.com/Legacy+Dungeon' target=\"_blank\">Legacy Dungeon</a> of Elden Ring. Recommended level 30+ and Weapons +4. The stronghold of <a href='https://eldenring.wiki.fextralife.com/Godrick+the+Grafted' target=\"_blank\">Godrick the Grafted</a>. Other Bosses include <a href='https://eldenring.wiki.fextralife.com/Many+Armed+Key+Master' target=\"_blank\">Many Armed Key Master</a> and <a href='https://eldenring.wiki.fextralife.com/Lion+Guardian' target=\"_blank\">Lion Guardian</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-stormveilcastle.png?h=40"},{"id":"6905","x":0.351004441,"y":0.708993549,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a> on the main gate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"8753","x":0.559298063,"y":0.709085107,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Commander O'Neil","desc":"Summoning Pool Effigy located by the stake of Marika at the southeast entrance to the boss arena. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"10210","x":0.435354491,"y":0.70911563,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Murkwater Coast","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"blank\">Limgrave</a>, next to the Murkwater Coast Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"975","x":0.342281616,"y":0.70917667,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] - Stormveil Castle (A)","desc":"Upgrade Material. Found on a corpse by a staircase leading to a platform with ballistae emplacements.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"12364","x":0.390311157,"y":0.709210025,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - Warmaster's Shack Southwest","desc":"Located within a grave area, in a sarcophagi on the hill south-west above <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Warmaster's+Shack' target=\"blank\">Warmaster's Shack</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"764","x":0.403248254,"y":0.709237711,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] B","desc":"Found together with a Smithing Stone [2] inside a stone statue surrounded by trolls.The creatures can be manipulated into hitting and cracking the sculpture open in order to grab the Stones.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8185","x":0.515693685,"y":0.709268229,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Gaol Cave","desc":"Summoning Pool Effigy found next to the Gaol Cave site of grace in Caelid. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1371","x":0.305570735,"y":0.709359792,"cat":"Key Items","group":"Items","title":"The Stormhawk King","desc":"Key Item. Found on a corpse in the southern wing of the chapel, up on the roof.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"765","x":0.405079449,"y":0.70945135,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] B","desc":"Found together with a Smithing Stone [1] inside a stone statue surrounded by trolls.The creatures can be manipulated into hitting and cracking the sculpture open in order to grab the Stones.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"12363","x":0.391869445,"y":0.709519228,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - Warmaster's Shack Southwest","desc":"Located within a grave area, in a sarcophagi on the hill south-west above <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Warmaster's+Shack' target=\"blank\">Warmaster's Shack</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2922","x":0.337213797,"y":0.709787075,"cat":"Weapons","group":"Equipment","title":"Godslayer's Seal","desc":"Found in a room barred by an Imp Statue seal, requiring a <a href='https://eldenring.wiki.fextralife.com/Stoneswrod+Key' Stonesword Key</a> to access. From the Rampart Tower, take the lift that leads to the <a href='https://eldenring.wiki.fextralife.com/Grafted+Scion' target=\"_blank\">Grafted Scion</a>'s hall. Exit into the courtyard where plenty of Castle Guards are mounted on ballistae. Take a hard left from this exit to find a small stairway leading into a cellar. There are several <a href='https://eldenring.wiki.fextralife.com/Rat' target=\"_blank\">Rats</a> in this cellar and the Imp Statue barrier behind them. The Seal is found in one of the chests behind the barrier.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacredseal.png?h=40"},{"id":"1962","x":0.535040128,"y":0.709848116,"cat":"NPCs","group":"Characters","title":"Wandering Merchant Caelid Highway North","desc":"Nomadic Merchant. General Goods vendor found sitting by a campfire east of the Astray from Caelid Highway North Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"6394","x":0.347860892,"y":0.710031237,"cat":"NPCs","group":"Characters","title":"Gatekeeper Gostoc","desc":"<a href='https://eldenring.wiki.fextralife.com/Gatekeeper+Gostoc' target=\"_blank\">Gatekeeper Gostoc</a> can be found by the entrance of <a href='https://eldenring.wiki.fextralife.com/Stormveil+Castle' target=\"_blank\">Stormveil Castle</a>, in the room next to the main gate into the castle","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"905","x":0.350526622,"y":0.710092278,"cat":"Sites of Grace","group":"Locations","title":"Stormveil Main Gate","desc":"Site of Grace found right by the castle's southern gate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6888","x":0.43455607,"y":0.710092278,"cat":"Crafting Materials","group":"Items","title":"Poisonbloom","desc":"Can be found on a dead body in the waters.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3036","x":0.626927729,"y":0.710183837,"cat":"Sites of Grace","group":"Locations","title":"Starscourge Radahn","desc":"Site of Grace unlocked after defeating <a href='https://eldenring.wiki.fextralife.com/Starscourge+Radahn' target=\"_blank\">Starscourge Radahn</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6876","x":0.584534392,"y":0.71033644,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - Sellia Gateway","desc":"<strong>Golden Rune (5)</strong> held by a corpse on top of a broken column on the path East of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Sellia+Gateway'>Sellia Gateway</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6479","x":0.344056099,"y":0.71039748,"cat":"Consumables","group":"Items","title":"Golden Rune [5] A - Stormveil Castle","desc":"Looted from one of the three bodies behind the Stormveil Main Gate","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6477","x":0.349142725,"y":0.71055008,"cat":"Consumables","group":"Items","title":"Golden Rune [1] B - Stormveil Castle","desc":"Looted from one of the three bodies at the entrance of Stormveil Castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3402","x":0.559114946,"y":0.710580602,"cat":"Weapons","group":"Equipment","title":"Commander's Standard","desc":"Halberd. Dropped by <a href='https://eldenring.wiki.fextralife.com/Commander+O'Neil' target=\"_blank\">Commander O'Neil</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-halberd.png?h=40"},{"id":"4462","x":0.445296597,"y":0.710641642,"cat":"Locations","group":"Locations","title":"Artist's Shack (Limgrave)","desc":"A broken shack with a collectible picture. Many such shacks can be found in The Lands Between.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"5952","x":0.509192943,"y":0.710702683,"cat":"Spells","group":"Equipment","title":"Flame, Grant me Strength","desc":"Found behind <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Fort+Gael'>Fort Gael</a>, on a body between two Maneuverable Flamethrowers","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"6902","x":0.308683767,"y":0.710916323,"cat":"Key Items","group":"Items","title":"Tarnished's Wizened Finger","desc":"Can be found at the beginning of the game, on a body against a wall on the right side of the tutorial area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"2947","x":0.502419485,"y":0.711038404,"cat":"Talismans","group":"Equipment","title":"Starscourge Heirloom","desc":"Looted from a chest in <a href='https://eldenring.wiki.fextralife.com/Fort+Gael' target=\"_blank\">Fort Gael</a>. It's outside the watchtower on the upper-section of the fort, under a canopy tent.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3301","x":0.45744226,"y":0.711099444,"cat":"Weapons","group":"Equipment","title":"Falchion","desc":"Dropped by <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/demi-human'>Demi-Human</a> enemies under the bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedsword.png?h=40"},{"id":"1373","x":0.306360044,"y":0.711191007,"cat":"Spirit Ashes","group":"Equipment","title":"Stormhawk Deenh","desc":"Spirit Ash. Found in a chest on the wooden walkway above the southern wing's main room. Accessible from where <a href='https://eldenring.wiki.fextralife.com/The+Stormhawk+King' target=\"_blank\">The Stormhawk King</a> key item is found.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6472","x":0.425616207,"y":0.711252047,"cat":"Consumables","group":"Items","title":"Golden Rune [2]","desc":"Found on a dead body around the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4463","x":0.448105292,"y":0.711404647,"cat":"Sites of Grace","group":"Locations","title":"Artist's Shack (Limgrave)","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2936","x":0.504738779,"y":0.711465687,"cat":"Locations","group":"Locations","title":"Fort Gael","desc":"A ruined fort in a ruined land, Fort Gael looms above the surrounding landscape, vicious roars can be heard within.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-forthaight.png?h=40"},{"id":"806","x":0.460341351,"y":0.711709849,"cat":"Weapons","group":"Equipment","title":"Erdsteel Dagger","desc":"Dagger. Rewarded by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Kenneth+Haight'>Kenneth Haight</a> for clearing out <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Fort+Haight'>Fort Haight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"2943","x":0.507301754,"y":0.711740371,"cat":"Consumables","group":"Items","title":"Rune Arc - Fort Gael","desc":"Consumable. Looted off a corpse next to the locked gate of <a href='https://eldenring.wiki.fextralife.com/Fort+Gael' target=\"_blank\">Fort Gael</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"913","x":0.338134528,"y":0.71177089,"cat":"Shields","group":"Equipment","title":"Marred Leather Shield","desc":"Shield. Found on a corpse on a wooden platform, outside the castle walls.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"971","x":0.345857075,"y":0.71177089,"cat":"Sites of Grace","group":"Locations","title":"Gateside Chamber","desc":"Site of Grace found through an archway accessible from within the castle walls. There is a lever in this chamber that opens up the castle's main gate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"525","x":0.373190871,"y":0.711801412,"cat":"Key Items","group":"Items","title":"Stonesword Key - Stormhill Shack","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stonesword+Key'>Stoneword Key</a> found at <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stormhill+Shack'>Stormhill Shack</a> next to the Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"8297","x":0.344503699,"y":0.711862452,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Stormveil Castle Secret Entrance","desc":"Summoning Pool Effigy found by the cliffside as you exit Gostoc's room towards the Stormveil Castle's secret back entrance. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"972","x":0.347494651,"y":0.711954011,"cat":"Armor","group":"Equipment","title":"Commoner's Simple Garb","desc":"Chest Armor. Found on a corpse on the balcony accessible from the Gateside Chamber Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"3241","x":0.563967063,"y":0.711984533,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4] A","desc":"Found on a body in the swamp next to a Cleanrot Knight","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"5918","x":0.433548895,"y":0.712350776,"cat":"NPCs","group":"Characters","title":"Bloody Finger Hunter Yura (Second Location)","desc":"NPC Questline: Found on the ground level under a broken structure. Talk to Bloody Finger Hunter Yura by resting at a grace after defeating NPC invader Bloody Finger Nerijus.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"7065","x":0.348877375,"y":0.712533898,"cat":"Key Items","group":"Items","title":"Gostoc's Bell Bearing","desc":"Dropped by <a class=\"wiki_link\" target?\"_blank\" href='https://eldenring.wiki.fextralife.com/Gatekeeper+Gostoc'>Gatekeeper Gostoc</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3235","x":0.564699671,"y":0.712625457,"cat":"Crafting Materials","group":"Items","title":"Aeonian Butterfly","desc":"1 Aeonian Butterfly can be found on a body in the middle of the swamp here","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3163","x":0.516488087,"y":0.712869619,"cat":"Weapons","group":"Equipment","title":"Meteoric Ore Blade","desc":"Katana. Found inside a chest in a small room at the back of an underground hall filled with sarcophagi and Prawn Miners enemies. The entrance is found in the northwest section of the <a href='https://eldenring.wiki.fextralife.com/Caelid+Waypoint+Ruins' target=\"_blank\">Caelid Waypoint Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-katana.png?h=40"},{"id":"4528","x":0.539709084,"y":0.712961182,"cat":"Sites of Grace","group":"Locations","title":"Aeonia Swamp Shore","desc":"Site of Grace found on the western bank of the <a href='https://eldenring.wiki.fextralife.com/Swamp+of+Aeonia' target=\"_blank\">Swamp of Aeonia</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4536","x":0.362514525,"y":0.713510546,"cat":"Sites of Grace","group":"Locations","title":"Castleward Tunnel","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2941","x":0.503975792,"y":0.713632627,"cat":"Weapons","group":"Equipment","title":"Katar","desc":"First Weapon. Looted from a treasure chest in <a href='https://eldenring.wiki.fextralife.com/Fort+Gael' target=\"_blank\">Fort Gael</a>. You can find the chest inside a dark room on the elevated platform above the Lion Guardian.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fist.png?h=40"},{"id":"2945","x":0.501625923,"y":0.713754708,"cat":"Consumables","group":"Items","title":"Warming Stone - Fort Gael","desc":"Consumable. Looted off a corpse that's hanging on a narrow beam. Bacony/Upper-section of <a href='https://eldenring.wiki.fextralife.com/Fort+Gael' target=\"_blank\">Fort Gael</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"831","x":0.458357415,"y":0.713846267,"cat":"NPCs","group":"Characters","title":"Kenneth Haight (First Location)","desc":"Kenneth Haight is first encountered at this spot. He is seen dramatically calling out for someone to aid him in his plight.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"1888","x":0.353537595,"y":0.71393783,"cat":"Key Items","group":"Items","title":"Talisman Pouch","desc":"Small, withered bag, knitted by hand. Bestowed upon the ruling lord, or those atempting to become lord, by the elderly Finger Reader. Dropped by <a href='https://eldenring.wiki.fextralife.com/margit+the+Fell+Omen' target=\"_blank\">Margit, the Fell Omen</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"7034","x":0.351462243,"y":0.71393783,"cat":"Consumables","group":"Items","title":"Fire Grease - 3x Stormveil Castle","desc":"Can be found beneath the bridge. You have to drop down onto a ledge on the east side of the bridge to access it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6475","x":0.346406132,"y":0.714120951,"cat":"Consumables","group":"Items","title":"Golden Rune [1] A - Stormveil Castle","desc":"Found on a dead body by the Effigy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2946","x":0.506936388,"y":0.714151469,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Lion's Claw","desc":"Drops from the <a href='https://eldenring.wiki.fextralife.com/Lion+Guardian' target=\"_blank\">Lion Guardian</a> in <a href='https://eldenring.wiki.fextralife.com/Fort+Gael' target=\"_blank\">Fort Gael</a> upon defeating it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"906","x":0.341701269,"y":0.714456672,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] A - Stormveil Castle","desc":"Upgrade Material. Found on a corpse on the outside of the castle walls. Reachable by climbing on broken sections nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1882","x":0.356966324,"y":0.714517713,"cat":"Sites of Grace","group":"Locations","title":"Margit, the Fell Omen","desc":"Margit the Fell Omen Site of Grace, located at the boss arena of Margit, near Stormvel Castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1885","x":0.355155149,"y":0.714517713,"cat":"Bosses","group":"Characters","title":"Margit, the Fell Omen","desc":"A large, apparently elder creature, self-proclaimed as \"The last of all kings\". Drops <a href='https://eldenring.wiki.fextralife.com/Talisman+Pouch' target=\"_blank\">Talisman Pouch</a> and 12000 Runes upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"8157","x":0.362083173,"y":0.714639794,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Castleward Tunnel","desc":"Summoning Pool Effigy found near the Castleward Tunnel site of grace in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1211","x":0.428607557,"y":0.714700834,"cat":"Sites of Grace","group":"Locations","title":"Murkwater Coast","desc":"Site of grace located at the coasts of Murkwater","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3186","x":0.576722222,"y":0.715006037,"cat":"Locations","group":"Locations","title":"Sellia Gateway","desc":"Gateway leading to <a href='https://eldenring.wiki.fextralife.com/Sellia,+Town+of+Sorcery' target=\"_blank\">Sellia, Town of Sorcery</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-stormgate.png?h=40"},{"id":"6872","x":0.578918987,"y":0.71543332,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - 2x Sellia Gateway","desc":"Two <strong>Golden Runes (4)</strong> within <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/sellia+gateway'>Sellia Gateway</a>. First one is on top of the gateway, held by a dead body inside one of the towers. The second one is at ground level, on the path to <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/church+of+the+plague'>Church of the Plague</a>, on a broken pillar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"758","x":0.380820763,"y":0.715524883,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] A","desc":"A Smithing Stone found on top of a corpse that lays on the ground. Found together with 3 other dead bodies and a rounded group of chairs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8151","x":0.339284794,"y":0.715708004,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Stormveil Cliffside","desc":"Summoning Pool Effigy found near the Stormveil Cliffside site of grace in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"911","x":0.340180372,"y":0.716013207,"cat":"Sites of Grace","group":"Locations","title":"Stormveil Cliffside","desc":"Site of Grace found on the cliffs outside the castle walls in the southwest. There is a Summoning Pool nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"14303","x":0.434984953,"y":0.716584546,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [1] - Artist's Shack (Limgrave)","desc":"<p>Upgrade Material. Southwest of the <a class=\"wiki_link\" href='https://eldenring.wiki.fextralife.com/Artist's+Shack+(Limgrave)' target=\"blank\"> Artist's Shack</a> in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"blank\">Limgrave</a>. In a bug that looks like a Scarab.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"2362","x":0.624568544,"y":0.71665413,"cat":"Bosses","group":"Characters","title":"Starscourge Radahn","desc":"One of the Shardbearers. Drops <a href='https://eldenring.wiki.fextralife.com/Remembrance+of+the+Starscourge' target=\"_blank\">Remembrance of the Starscourge</a>, <a href='https://eldenring.wiki.fextralife.com/Radahn's+Great+Rune' target=\"_blank\"> Radahn's Great Rune</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"5415","x":0.631740725,"y":0.716684652,"cat":"NPCs","group":"Characters","title":"Iron Fist Alexander (Fourth Location)","desc":"NPC. Third location on this questline. He can then be summoned for the boss fight against Starscourge Radahn. If he has not been interacted with prior to this, he will show up at the festival anyway and introduce himself. Before moving to his next location, he can be found scavenging at Starscourge Radahn's Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3051","x":0.352379873,"y":0.716928814,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1]","desc":"Held by a corpse sitting against a grave, surrounded by <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Spirit+Jellyfish' target=\"\">Spirit Jellyfishes</a> and <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Skeleton' target=\"\">Skeleton Enemies</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"520","x":0.374015399,"y":0.717111936,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed (F)","desc":"Golden Seeds allow the user to upgrade the number of <a href='https://eldenring.wiki.fextralife.com/Flask+of+Crimson+Tears'>Crimson</a> and <a href='https://eldenring.wiki.fextralife.com/Flask+of+Cerulean+Tears'>Cerulean</a> Flask Uses, but <strong>not</strong> the amount of Wondrous Physik flasks available.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"3161","x":0.520575674,"y":0.717111936,"cat":"Locations","group":"Locations","title":"Caelid Waypoint Ruins","desc":"A set of ruins found in the southwest of <a href='https://eldenring.wiki.fextralife.com/Caelid' target=\"_blank\">Caelid</a>, along the highway.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"2408","x":0.62215708,"y":0.71882107,"cat":"Key Items","group":"Items","title":"Radahn's Great Rune","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Starscourge+Radahn'>Starscourge Radahn</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2407","x":0.626338309,"y":0.719126273,"cat":"Remembrances","group":"Items","title":"Remembrance of the Starscourge","desc":"Dropped <a hef=\"/Starscourge+Radahn\" target=\"_blank\"> Starscourge Radahn</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"3251","x":0.547261907,"y":0.719309394,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Poisonous Mist","desc":"Ash of War. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> in the southwest section of the <a href='https://eldenring.wiki.fextralife.com/Swamp+of+Aeonia' target=\"_blank\">Swamp of Aeonia</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"909","x":0.339260844,"y":0.719675637,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] A - Stormveil Castle","desc":"Upgrade Material. Found on a corpse around the southwestern cliffs. Watch out for the Bladed Talon Eagles roosting in the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"461","x":0.405601002,"y":0.720621763,"cat":"Crafting Materials","group":"Items","title":"Large Glintstone Scrap","desc":"Accessed from <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Limgrave+Tunnels'>Limgrave Tunnels</a>. Underground. It can be found on a body, inside a little hut guarded by dogs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5949","x":0.364053006,"y":0.720652285,"cat":"Spirit Ashes","group":"Equipment","title":"Godrick Soldier Ashes","desc":"Found at the Cemetery at the west of Stormhill that is filled with Spirit Jellyfish, next to a grave. Check both sides of each grave to find it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6474","x":0.386855912,"y":0.720988006,"cat":"Consumables","group":"Items","title":"Golden Rune [2]","desc":"Found in a dead body at the ruins past the Stormgate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6958","x":0.365725242,"y":0.721018528,"cat":"Consumables","group":"Items","title":"Magic Grease - East Limgrave","desc":"Can be found in the graveyard on the small cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3255","x":0.559755544,"y":0.721232168,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] - 3x Southern Aeonia Swamp Bank","desc":"Upgrade Material. 3x found on a body sat on a chair on the southern bank of the <a href='https://eldenring.wiki.fextralife.com/Swamp+of+Aeonia' target=\"_blank\">Swamp of Aeonia</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"1210","x":0.423266857,"y":0.72147633,"cat":"Key Items","group":"Items","title":"Armorer's Cookbook [1]","desc":"Can be found inside a small camp of Soldiers and Wolves.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"705","x":0.394580513,"y":0.721720492,"cat":"Talismans","group":"Equipment","title":"Arrow's Reach Talisman","desc":"Found in a chest inside the Tower above Stormgate that can be accessed going all around it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6753","x":0.391378873,"y":0.722666622,"cat":"Crafting Materials","group":"Items","title":"Lump of Flesh","desc":"Can be found on a dead body by the road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3237","x":0.561221315,"y":0.72269714,"cat":"Crafting Materials","group":"Items","title":"Sacramental Bud - Southern Aeonia Swamp Bank","desc":"Crafting Material. Found on a body sat on a chair in the southern bank of the <a href='https://eldenring.wiki.fextralife.com/Swamp+of+Aeonia' target=\"_blank\">Swamp of Aeonia</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3253","x":0.558697292,"y":0.723185464,"cat":"Consumables","group":"Items","title":"Rune Arc - Southern Aeonia Swamp Bank","desc":"Consumable. Found on a body on a chair on the southern bank of the <a href='https://eldenring.wiki.fextralife.com/Swamp+of+Aeonia' target=\"_blank\">Swamp of Aeonia</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8451","x":0.429223924,"y":0.723551707,"cat":"Armor","group":"Equipment","title":"Leather Set (No Helmet)","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Patches'>Patches</a> if the player decides to defeat him.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"42","x":0.394825033,"y":0.723765351,"cat":"Locations","group":"Locations","title":"Stormgate","desc":"The entrance to the Stormhill heavily guarded.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-stormgate.png?h=40"},{"id":"775","x":0.455307993,"y":0.72385691,"cat":"Sites of Grace","group":"Locations","title":"Mistwood Outskirts","desc":"Site of Grace situated next to the main road North of Mistwood Ruins, in the middle of a group of large stones.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"403","x":0.398458322,"y":0.724040032,"cat":"Sites of Grace","group":"Locations","title":"Gatefront Ruins","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"405","x":0.400684423,"y":0.72501668,"cat":"Weapons","group":"Equipment","title":"Lordsworn's Greatsword","desc":"Greatsword. Found inside a Wagon Chest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"404","x":0.402546775,"y":0.725138761,"cat":"Maps","group":"Locations","title":"Map (Limgrave, West)","desc":"At the foot of a pillar. Unlocks Western Limgrave on your map","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"3162","x":0.519112696,"y":0.725199801,"cat":"Crafting Materials","group":"Items","title":"Poisonbloom - 4x Southwest Caelid","desc":"Crafting Material. 4x found on a corpse sitting at the end of the cliffs.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1229","x":0.424829058,"y":0.725474485,"cat":"Armor","group":"Equipment","title":"Cloth Garb","desc":"Can be found at the chest at the end of the dungeon in <a href='https://eldenring.wiki.fextralife.com/Murkwater+Cave' target=\"_blank\">Murkwater Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bodyarmor.png?h=40"},{"id":"1222","x":0.427026491,"y":0.725535526,"cat":"Bosses","group":"Characters","title":"Patches (Bossfight)","desc":"Found within <a href='https://eldenring.wiki.fextralife.com/Murkwater+Cave' target=\"_blank\"> Murkwater Cave</a>. After defeating him, he sets up a shop in the Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6140","x":0.409657275,"y":0.725688125,"cat":"Weapons","group":"Equipment","title":"Flail","desc":"It can be found in a charriot, defended by a group of soldiers. near the <a href='https://eldenring.wiki.fextralife.com/Gatefront+Ruins' target=\"_blank\">Gatefront Ruins</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-flail.png?h=40"},{"id":"1220","x":0.422904775,"y":0.727031016,"cat":"Sites of Grace","group":"Locations","title":"Murkwater Cave (Site of Grace)","desc":"Site of grace just inside <a href='https://eldenring.wiki.fextralife.com/Murkwater+Cave' target=\"_blank\">Murkwater Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"4514","x":0.564700186,"y":0.72751934,"cat":"Sites of Grace","group":"Locations","title":"Southern Aeonia Swamp Bank","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"8003","x":0.386373617,"y":0.727763502,"cat":"Spells","group":"Equipment","title":"Aspects of the Crucible: Tail","desc":"Incantation. Dropped by the Crucible Knight boss in Stormhill Evergaol.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-yellowspell.png?h=40"},{"id":"6889","x":0.416614034,"y":0.728312867,"cat":"Crafting Materials","group":"Items","title":"Erdleaf Flower","desc":"Can be found nex to the stone monument.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"363","x":0.403431316,"y":0.728434948,"cat":"Key Items","group":"Items","title":"Whetstone Knife","desc":"Key Item. Found in the southeastern area of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Gatefront+Ruins'>Gatefront Ruins</a>. There is a set of stairs that leads to a small room with a treasure chest. This item is found alongside the <a target=\"_blank\" href=\"Ash+of+War:+Storm+Stomp\">Ash of War: Storm Stomp</a> upgrade.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"3256","x":0.555544549,"y":0.728434948,"cat":"Crafting Materials","group":"Items","title":"Crab Eggs - Caelid South","desc":"Found on a body underneath a broken cart next to a burnt out campfire and a small red tent.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1217","x":0.429857476,"y":0.728557029,"cat":"Weapons","group":"Equipment","title":"Reduvia","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Bloody+Finger+Nerijus' target=\"_blank\"> Bloody Finger Nerijus</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"10","x":0.411337729,"y":0.728770673,"cat":"Sites of Grace","group":"Locations","title":"Agheel Lake North","desc":"Site of Grace found next to the main road east of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Gatefront+Ruins'>Gatefront Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"1218","x":0.427049012,"y":0.728862232,"cat":"Locations","group":"Locations","title":"Murkwater Cave","desc":"Found halfway over the Murkwater River.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"2011","x":0.404288527,"y":0.729014835,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Storm Stomp","desc":"Found in the southeastern area of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/gatefront+ruins'>Gatefront Ruins</a>. There is a set of stairs that leads to a small room with a treasure chest. This item is found alongside <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/whetstone+knife'>Whetstone Knife</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"30","x":0.388600632,"y":0.729197956,"cat":"Locations","group":"Locations","title":"Stormhill Evergaol","desc":"Stormhill Evergaol is a round platform that can be easily found at the west of Stormhill.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-evergaol.png?h=40"},{"id":"1155","x":0.528022684,"y":0.729472637,"cat":"Sites of Grace","group":"Locations","title":"Caelid Highway South","desc":"Site of Grace found by the Caelid Highway bend towards the south.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6898","x":0.467542447,"y":0.729472637,"cat":"Crafting Materials","group":"Items","title":"Gold Firefly","desc":"Can be found near waters close to Minor Erdrees.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"402","x":0.402638504,"y":0.729869402,"cat":"Locations","group":"Locations","title":"Gatefront Ruins","desc":"Heavily Guarded Area. A Map fragment, some weapons and hidden cellar offer notable loot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"6901","x":0.431141364,"y":0.729991483,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy","desc":"Can be looted from <a href='https://eldenring.wiki.fextralife.com/Bloody+Finger+Nerijus' target=\"_blank\">Bloody Finger Nerijus</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"1754","x":0.385062915,"y":0.730144083,"cat":"Bosses","group":"Characters","title":"Crucible Knight","desc":"Found within Stormhill Evergaol, this is a solo fight without Spirit Ashes or player summons. Drops the Incantation <a href='https://eldenring.wiki.fextralife.com/Aspects+of+the+Crucible:+Tail' target=\"_blank\">Aspects of the Crucible: Tail</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"8174","x":0.375511935,"y":0.730449285,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Stormfoot Catacombs","desc":"Summoning Pool Effigy found in front of the Boss Doors of the Stormfoot Catacombs in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"8171","x":0.423028383,"y":0.730723969,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Murkwater Cave","desc":"Summoning Pool Effigy found just ahead of the Murkwater Cave site of grace in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"784","x":0.37276514,"y":0.731029171,"cat":"Bosses","group":"Characters","title":"Erdtree Burial Watchdog (Stormfoot Catacombs)","desc":"Optional Boss found at the end of <a href='https://eldenring.wiki.fextralife.com/Stormfoot+Catacombs' target=\"_blank\">Stormfoot Catacombs</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Noble+Sorcerer+Ashes' target=\"_blank\">Noble Sorcerer Ashes</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mainboss.png?h=40"},{"id":"1170","x":0.543996278,"y":0.731181771,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Poison Moth Flight","desc":"Ash of War Upgrade. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> miniboss roaming the highway upon defeat. Only appears at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"732","x":0.466687528,"y":0.731670095,"cat":"Key Items","group":"Items","title":"Nomadic Warrior's Cookbook [4]","desc":"Cookbook item. Obtained in the south of Mistwood. Found on a corpse at the side of the road close to the Siofra River Well.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"6685","x":0.375969592,"y":0.732219459,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [1] - Stormfoot Catacombs","desc":"Spirit Ash Upgrade Material. Found behind the second flamethrower pillar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"8851","x":0.375022484,"y":0.732402581,"cat":"Key Items","group":"Items","title":"Crossed Legs Gesture","desc":"<p>Gesture. Obtained by interacting with a corpse on a large piece of debris, South of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Stormhill+Shack' target=\"\">Stormhill Shack</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1230","x":0.424859578,"y":0.732433103,"cat":"Armor","group":"Equipment","title":"Cloth Trousers","desc":"Can be found at the chest at the end of the dungeon in <a href='https://eldenring.wiki.fextralife.com/Murkwater+Cave' target=\"_blank\">Murkwater Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-leggins.png?h=40"},{"id":"1215","x":0.429857937,"y":0.732463621,"cat":"NPC Invaders","group":"Characters","title":"Bloody Finger Nerijus","desc":"Found while traversing the Murkwater River. Blood Finger Hunter Yura joins to aid you during the fight.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npcinvader.png?h=40"},{"id":"2502","x":0.371300186,"y":0.732585702,"cat":"Spirit Ashes","group":"Equipment","title":"Noble Sorcerer Ashes","desc":"Dropped by the <a href='https://eldenring.wiki.fextralife.com/Erdtree+Burial+Watchdog' target=\"_blank\">Erdtree Burial Watchdog</a> inside the <a href='https://eldenring.wiki.fextralife.com/Stormfoot+Catacombs' target=\"_blank\">Stormfoot Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"8172","x":0.406084722,"y":0.733043508,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Limgrave Tunnels","desc":"Summoning Pool Effigy found next to the Limgrave Tunnels site of grace in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"460","x":0.408009298,"y":0.733165589,"cat":"Sites of Grace","group":"Locations","title":"Limgrave Tunnels","desc":"Limgrave Tunnels Site of Grace, located just below the main elevator.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"7057","x":0.523111074,"y":0.733196107,"cat":"Consumables","group":"Items","title":"Starlight Shards - Southwest Caelid","desc":"Can be found at the southwestern area of Caelid, near the monument that looks like a broken cup.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"809","x":0.477276958,"y":0.733470792,"cat":"Locations","group":"Locations","title":"Siofra River Well","desc":"A cylindrical structure that takes players underground to the southern section of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Siofra+River'>Siofra River</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-well.png?h=40"},{"id":"4512","x":0.57410032,"y":0.733592873,"cat":"Bosses","group":"Characters","title":"Death Rite Bird (Caelid Southeast)","desc":"Only spawns at night. Southeast from the Southern Aeonia Swamp Bank site of grace, before Sellia Gateway. It drops the <a href='https://eldenring.wiki.fextralife.com/Death's+Poker' target=\"_blank\">Death's Poker</a> Greatsword","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"8829","x":0.53311199,"y":0.733592873,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Caelid Highway South","desc":"Summoning Pool Effigy found southeast of the Site of Grace, by the road next to a fungal growth. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6461","x":0.463365222,"y":0.733714954,"cat":"Consumables","group":"Items","title":"Golden Rune [1]","desc":"Found by a statue.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"779","x":0.46851872,"y":0.734111715,"cat":"Maps","group":"Locations","title":"Map (Limgrave, East)","desc":"At the foot of a pillar with ancient writings on it. Unlocks Eastern Limgrave on your map.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"4513","x":0.570987287,"y":0.734142237,"cat":"Weapons","group":"Equipment","title":"Death's Poker","desc":"Greatsword. Dropped by miniboss <a href='https://eldenring.wiki.fextralife.com/Death+Rite+Bird' target=\"_blank\">Death Rite Bird</a> that appears only at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"777","x":0.378197545,"y":0.73444744,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [1] - 5x Stormfoot Catacombs","desc":"Spirit Ash Upgrade Material. The first one is found by a sarcophagus in the room with the boss door. The second one is found in the next room, behind a pillar near the entrance to the narrow corridor. The third is found after climbing the ladder in the hallway where the second flamethrower pillar is. The fourth is found in a room west of where you got the third one. The final one is found to the left of the boss' door's lever.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"2971","x":0.386095975,"y":0.73450848,"cat":"Talismans","group":"Equipment","title":"Flamedrake Talisman","desc":"Talisman. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Beastman+of+Farum+Azula' target=\"_blank\">Beastman of Farum Azula</a> boss inside <a href='https://eldenring.wiki.fextralife.com/Groveside+Cave' target=\"_blank\">Groveside Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"454","x":0.361170108,"y":0.734600039,"cat":"Crafting Materials","group":"Items","title":"Strip of White Flesh","desc":"Found on a dead body, sitting across a Soldier.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1168","x":0.545204361,"y":0.734752642,"cat":"Bosses","group":"Characters","title":"Night's Cavalry (Caelid)","desc":"<a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> Miniboss. Roams the Caelid Highway South. Only appears at night. Drops <a href='https://eldenring.wiki.fextralife.com/Ash+of+War:+Poison+Moth+Flight' target=\"_blank\">Ash of War: Poison Moth Flight</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"1158","x":0.559389963,"y":0.735210444,"cat":"NPCs","group":"Characters","title":"Nomadic Merchant Caelid South","desc":"Nomadic Merchant. General Goods vendor found sitting by a campfire in south Caelid. Sells the <a href='https://eldenring.wiki.fextralife.com/Nomadic+Warrior's+Cookbook+(15)' target=\"_blank\">Nomadic Warrior's Cookbook (15)</a>, among other items.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"3889","x":0.405019057,"y":0.735363047,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [1] - Limgrave Tunnels","desc":"Players can find one at the Limgrave Tunnels. Before taking the second elevator, fall down the edge on the left, and keep falling on the surfaces against the wall. There is a Golden Rune (1) on a platform with a dead body, the next one has a Somber Smithing Stone [1].","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"776","x":0.375540897,"y":0.735698769,"cat":"Locations","group":"Locations","title":"Stormfoot Catacombs","desc":"A deep catacomb littered with fire traps and creatures.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"1156","x":0.555331572,"y":0.735973452,"cat":"Maps","group":"Locations","title":"Map (Caelid)","desc":"Map Fragment. Reveals the <a href='https://eldenring.wiki.fextralife.com/Caelid' target=\"_blank\">Caelid</a> region excluding <a href='https://eldenring.wiki.fextralife.com/Dragonbarrow' target=\"_blank\">Dragonbarrow</a>. Found on a monolith at the <strong>Caelid Highway South</strong> intersection.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"8175","x":0.387716494,"y":0.736156574,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Groveside Cave","desc":"Summoning Pool Effigy found next to the Groveside Cave site of grace in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"459","x":0.408099648,"y":0.736583858,"cat":"Locations","group":"Locations","title":"Limgrave Tunnels","desc":"On the northern area of the Agheel Lake, you can find the rich Limgrave Tunnels","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tunnel.png?h=40"},{"id":"368","x":0.383901507,"y":0.736644898,"cat":"Bosses","group":"Characters","title":"Beastman of Farum Azula (Groveside Cave)","desc":"Optional Boss. Found at the end of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Groveside+Cave'>Groveside Cave</a> mini-dungeon. Drops the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Flamedrake+Talisman'>Flamedrake Talisman</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"4515","x":0.372521346,"y":0.736705939,"cat":"Sites of Grace","group":"Locations","title":"Stormfoot Catacombs","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"367","x":0.420030049,"y":0.736858538,"cat":"NPCs","group":"Characters","title":"Boc the Seamster (First Location)","desc":"Location 1. Roaming around this location, you will hear someone call out. Look for a small group of trees and attack the small yellow tree to dispel the illusion and reveal Boc. Awards <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Mushroom'>Mushroom</a> x10 after speaking to him twice.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"701","x":0.367007079,"y":0.736858538,"cat":"Consumables","group":"Items","title":"Starlight Shards B","desc":"<a href='https://eldenring.wiki.fextralife.com/Starlight+Shards' target=\"_blank\">Starlight Shards</a>: Found at the very west of Stormhill at the edge of the Cliff on a stone monument.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6473","x":0.390679086,"y":0.737529983,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Groveside Cave","desc":"Found in Groveside Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1157","x":0.535398038,"y":0.737682587,"cat":"Bosses","group":"Characters","title":"Decaying Ekzykes","desc":"Optional Boss. Found guarding the Caelid Highway South.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"5948","x":0.379843311,"y":0.737713105,"cat":"Spirit Ashes","group":"Equipment","title":"Wandering Noble Ashes","desc":"Located on a corpse that is resting against a stone coffin in the <a href='https://eldenring.wiki.fextralife.com/Stormfoot+Catacombs' target=\"_blank\"> Stormfoot Catacombs</a> in Limgrave. Proceed through the catacombs as normal until reaching a ladder that is going up, once you've reached the top continue forward past some Jade Goblins until reaching a dead end room that is being guarded by two Jade Goblins, the corpse resting against the stone coffin will hold the ashes","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6899","x":0.46769404,"y":0.737743627,"cat":"Crafting Materials","group":"Items","title":"Thin Beast Bones","desc":"Can be found neraby the wagon, on a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2259","x":0.410986275,"y":0.73826247,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - Limgrave Tunnels","desc":"Golden Rune [4] held by a corpse within the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/limgrave+tunnels'>Limgrave Tunnels</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3888","x":0.4047749,"y":0.738415073,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] - 8x Limgrave Tunnels","desc":"Approximately x8 found in <a href='https://eldenring.wiki.fextralife.com/Limgrave+Tunnels'>Limgrave Tunnels</a> (mostly as yellow glowing stones on wall).","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6897","x":0.472698077,"y":0.738415073,"cat":"Crafting Materials","group":"Items","title":"Tarnished Golden Sunflower","desc":"Can be found x20 Tarnished Golden Sunflower araund the <a href='https://eldenring.wiki.fextralife.com/Minor+Erdtree+(Mistwood)' target=\"_blank\">Minor Erdtree (Mistwood)</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5933","x":0.566774222,"y":0.738659235,"cat":"Flask Upgrades","group":"Items","title":"Windy Crystal Tear","desc":"The item can be found in Caelid in a pit southeast of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Nomadic+Merchant+Caelid+South'>Nomadic Merchant Caelid South</a>. One of the birds watches over it, facing south.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"372","x":0.389124177,"y":0.738720275,"cat":"Sites of Grace","group":"Locations","title":"Groveside Cave","desc":"Site of Grace found inside the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Groveside+Cave'>Groveside Cave</a>, right before the boss fight.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6896","x":0.480389651,"y":0.738811834,"cat":"Crafting Materials","group":"Items","title":"Strip of White Flesh","desc":"Can be found near <a href='https://eldenring.wiki.fextralife.com/Siofra+River+Well' target=\"_blank\">Siofra River Well</a> on a dead body behind the <a href='https://eldenring.wiki.fextralife.com/Giant+Crab' target=\"_blank\">Giant Crab</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"401","x":0.387229156,"y":0.739178077,"cat":"Locations","group":"Locations","title":"Groveside Cave","desc":"Small cave north from Church of Elleh.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"1759","x":0.425713505,"y":0.739422239,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Repeating Thrust","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> that roams the bridge near Agheel Lake North, only appears at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"369","x":0.363061719,"y":0.739452761,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Stamp (Sweep)","desc":"Ash of War Upgrade. Found by defeating an invisible <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab'>Teardrop Scarab</a> roaming around the beach. You will see glowing footprints appearing in a set pattern around the area. Stand in front of its path and attack as it approaches you to reveal the creature.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"8191","x":0.618037993,"y":0.739574842,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Redmane Castle Northern Shores","desc":"Summoning Pool Effigy found next to the Sending Gate that leads to Starscourage Radahn's boss arena in Caelid. Accessible by taking the lift outside the chapel in the north of the castle. If you have already completed the Radahn encounter without activating the Martyr Effigy, you will need to complete the Misbegotten Warrior and Crucible Knight duo encounter before the elevator is accessible again. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"735","x":0.478710564,"y":0.739666401,"cat":"Flask Upgrades","group":"Items","title":"Greenspill Crystal Tear","desc":"Crystal Tear for the Flask of Wondrous Physick. Found on an altar next to the Minor Erdtree in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Mistwood'>Mistwood</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"7851","x":0.619808398,"y":0.739788482,"cat":"Waygates","group":"Locations","title":"Sending Gate (Redmane Castle to Wailing Dunes)","desc":"A Sending Gate found on the shores in the north of Redmane Castle. Transports you to the <strong>Wailing Dunes</strong> in the north where you can fight <a href='https://eldenring.wiki.fextralife.com/Starscourge+Radahn' target=\"_blank\">Starscourge Radahn</a>. This gate can be found by taking the side exit from the chapel and descending the lift onto the shores.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"496","x":0.407611451,"y":0.740002126,"cat":"Bosses","group":"Characters","title":"Stonedigger Troll (Limgrave)","desc":"Optional Boss. Found at the end of Limgrave Tunnels. Drops Roar Medallion","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"825","x":0.421929667,"y":0.740032644,"cat":"Bosses","group":"Characters","title":"Night's Cavalry (Limgrave)","desc":"<a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> roams the bridge near Agheel Lake North, only appears at night. Drops <a href='https://eldenring.wiki.fextralife.com/Ash+of+War:+Repeating+Thrust' target=\"_blank\">Ash of War: Repeating Thrust</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mainboss.png?h=40"},{"id":"464","x":0.476026551,"y":0.740154725,"cat":"Locations","group":"Locations","title":"Minor Erdtree (Mistwood)","desc":"A Minor Erdtree found in the <a href='https://eldenring.wiki.fextralife.com/Mistwood' target=\"_blank\">Mistwood</a> sub-region of <a href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"_blank\">Limgrave</a> in the east.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tree.png?h=40"},{"id":"734","x":0.471477746,"y":0.740185247,"cat":"Flask Upgrades","group":"Items","title":"Spiked Cracked Tear","desc":"Crystal Tear for the Flask of Wondrous Physick. Found on an altar next to the Minor Erdtree in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Mistwood'>Mistwood</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"2106","x":0.536322648,"y":0.740612531,"cat":"Consumables","group":"Items","title":"Dragon Heart (Decaying Ekzykes)","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Decaying+Ekzykes' target=\"_blank\"> Decaying Ekzykes</a> in <strong>South Caelid</strong>. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6659","x":0.375541322,"y":0.74076513,"cat":"Key Items","group":"Items","title":"Prattling Pate (Hello)","desc":"Can be found in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/stormfoot+catacombs'>Stormfoot Catacombs</a> on a corpse behind the first pillar that exudes fire.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"521","x":0.404838167,"y":0.741222936,"cat":"Talismans","group":"Equipment","title":"Roar Medallion","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Stonedigger+Troll' target=\"_blank\"> Stonedigger Troll</a>. Located in Limgrave Tunnels.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6751","x":0.388634367,"y":0.7419249,"cat":"Key Items","group":"Items","title":"Cracked Pot - Groveside Cave","desc":"Crafting Pot. Can be found inside <a href='https://eldenring.wiki.fextralife.com/Groveside+Cave' target=\"_blank\">Groveside Cave</a>. By the bonfire, there is a body that you can loot to find x1 Cracked Pot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"4258","x":0.464032954,"y":0.742138544,"cat":"NPCs","group":"Characters","title":"Blaidd (1st location)","desc":"Blaidd's First Location: When visiting Mistwood, the player can occasionally hear a wolf howl. At this point, they can ask Merchant Kale about the howling. The merchant will teach the player the Finger Snap gesture.<br />Blaidd can be seen resting on the tallest point in the Mistwood Ruins, and will jump down after the player uses the gesture while standing below him. Blaidd will tell the player he is searching for a man who goes by the name Darriwil.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6586","x":0.572358658,"y":0.742687908,"cat":"Crafting Materials","group":"Items","title":"Beast Blood","desc":"Can be found on a dead body guarded by a <a href='https://eldenring.wiki.fextralife.com/Lion+Guardian' target=\"_blank\">Lion Guardian</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"602","x":0.423058274,"y":0.743206751,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Determination","desc":"It drops from a Teardrop Scarab, north of Agheel Lake, near a group of soldiers.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"767","x":0.459239627,"y":0.743237273,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] - Mistwood Ruins","desc":"Upgrade Material. Found in a chest in the center of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Mistwood+Ruins'>Mistwood Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"2451","x":0.425525318,"y":0.743298313,"cat":"Weapons","group":"Equipment","title":"Dagger","desc":"Looted from a <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/soldier'>Foot Soldier</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"755","x":0.470353004,"y":0.744030799,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Ground Slam","desc":"Ash of War Upgrade. Dropped by a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab'>Teardrop Scarab</a> found rolling down the hill west of the Minor Erdtree in Mistwood.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"6957","x":0.441360365,"y":0.74424444,"cat":"Consumables","group":"Items","title":"Gold-Pickled Fowl Foot - Limgrave","desc":"Can be found at the base of the crucifix on a small hill.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3258","x":0.561311695,"y":0.74430548,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - South Caelid","desc":"Flask Upgrade Material. Found under a Phantom Tree by the side of the road in south <a href='https://eldenring.wiki.fextralife.com/Caelid' target=\"_blank\">Caelid</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"6460","x":0.46046583,"y":0.744915885,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - Mistwood Ruins","desc":"Found in Mistwood Ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6666","x":0.525427033,"y":0.744946407,"cat":"Key Items","group":"Items","title":"Larval Tear - 1x Enemy Drop Caelid","desc":"Larval Tear dropped by a Troll disguised as a regular enemy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"1972","x":0.393895122,"y":0.744976925,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - Church of Elleh - x3","desc":"At least 3x Golden Runes (1) along the road north-east of <a target=\"\" href='https://eldenring.wiki.fextralife.com/church+of+elleh'>Church of Elleh</a>. Inside skulls. Perform an attack to loot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6879","x":0.534613533,"y":0.745037966,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - Caelid's South West Sarcophagi","desc":"Found at the sarcophagi located at <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/caelid'>South-West Caelid</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"762","x":0.463727823,"y":0.745160047,"cat":"Locations","group":"Locations","title":"Mistwood Ruins","desc":"An old ruin occupied by a <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Lesser+Runebear'>Lesser Runebear</a>. The site is home to a few prized <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Trina's+Lily'>Trina's Lilies</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"832","x":0.42750649,"y":0.74531265,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1]","desc":"At the side of the bridge, on a body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6423","x":0.616390672,"y":0.745923055,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] C - Redmane Castle","desc":"Upgrade Material. Found on a corpse inside the chapel to the north of the castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"4468","x":0.552613716,"y":0.746167217,"cat":"Spirit Ashes","group":"Equipment","title":"Kindred of Rot Ashes","desc":"Spirit Ashes. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Cemetery+Shade' target=\"_blank\">Cemetery Shade</a> in the <a href='https://eldenring.wiki.fextralife.com/Caelid+Catacombs' target=\"_blank\">Caelid Catacombs</>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"5728","x":0.456478709,"y":0.746411379,"cat":"Talismans","group":"Equipment","title":"Sacrificial Twig - Mistwood Ruins","desc":"Can be found on a ledge of the cemetery that's overlooking the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6806","x":0.461805633,"y":0.746625019,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Mistwood+Ruins' target=\"_blank\">Mistwood Ruins</a> behind a grave near the Sacrificial Twig.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"706","x":0.446491534,"y":0.746960744,"cat":"Bosses","group":"Characters","title":"Mad Pumpkin Head (Waypoint Ruins)","desc":"Field Boss. Found directly below the <a href='https://eldenring.wiki.fextralife.com/Waypoint+Ruins' target=\"_blank\">Waypoint Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"769","x":0.459058413,"y":0.746960744,"cat":"Talismans","group":"Equipment","title":"Axe Talisman","desc":"Talisman. Found in a cellar underneath the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Mistwood+Ruins'>Mistwood Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6875","x":0.535166438,"y":0.747113343,"cat":"Consumables","group":"Items","title":"Golden Rune [5] - Caelid's South West Sarcophagi","desc":"Found at the sarcophagi located at <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/caelid'>South-West Caelid</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1969","x":0.386681723,"y":0.747357505,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] - Church of Elleh","desc":"Found at Church of Elleh on the smithing table.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"3180","x":0.543737181,"y":0.747479586,"cat":"Key Items","group":"Items","title":"Ancient Dragon Apostle's Cookbook [3]","desc":"Cookbook item found at the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>. Looted off a corpse tucked under the dragon's chest.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"8203","x":0.419274432,"y":0.747479586,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Agheel Lake","desc":"Summoning Pool Effigy found next to the Flying Dragon Agheel spawn location in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"4","x":0.390768225,"y":0.74769323,"cat":"NPCs","group":"Characters","title":"Merchant Kale","desc":"General Goods Vendor. Found sitting by the fire in the ruins of the Church of Elleh. Sells the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Telescope'>Telescope</a> and <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Crafting+Kit'>Crafting Kit</a> key items.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"812","x":0.476133142,"y":0.747766478,"cat":"NPCs","group":"Characters","title":"Nomadic Merchant East Limgrave","desc":"Nomadic Merchant. General Goods vendor found sitting by a campfire next to the road between <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Mistwood+Ruins'>Mistwood Ruins</a> and <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Fort+Haight'>Fort Haight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"6442","x":0.554658552,"y":0.747876351,"cat":"Bosses","group":"Characters","title":"Cemetery Shade (Caelid Catacombs)","desc":"Boss found inside the <a href='https://eldenring.wiki.fextralife.com/Caelid+Catacombs' target=\"_blank\">Caelid Catacombs</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Kindred+of+Rot+Ashes' target=\"_blank\">Kindred of Rot Ashes</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"713","x":0.43959021,"y":0.748181554,"cat":"Consumables","group":"Items","title":"Immunizing Cured Meat","desc":"Found in the small group of Poison Flowers in the outskirts of the <a href='https://eldenring.wiki.fextralife.com/Waypoint+Ruins' target=\"_blank\">Waypoint Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"465","x":0.383718691,"y":0.748486756,"cat":"NPCs","group":"Characters","title":"Renna","desc":"Renna appears in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Church+of+Elleh'>Church of Elleh</a> after you get your horse from Melina. Gives the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Spirit+Calling+Bell'>Spirit Calling Bell</a> and <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Lone+Wolf+Ashes'>Lone Wolf Ashes</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"4466","x":0.550939781,"y":0.748547797,"cat":"Sites of Grace","group":"Locations","title":"Caelid Catacombs","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2108","x":0.365145363,"y":0.748639356,"cat":"Consumables","group":"Items","title":"Golden Rune [1] I - 2x","desc":"x2 Golden Runes (1) located along the shore.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2932","x":0.54117341,"y":0.748669878,"cat":"Sites of Grace","group":"Locations","title":"Cathedral of Dragon Communion","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"497","x":0.405932598,"y":0.748700396,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"x3 Trina's Lily under the giant ruined structure. Beware of the Giant Crab guarding them.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8186","x":0.548554568,"y":0.748852999,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Caelid Catacombs","desc":"Summoning Pool Effigy found at the end of the hallway just past the Caelid Catacombs site of grace in Caelid. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"702","x":0.43136032,"y":0.748944559,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [1] A","desc":"Located on the field, on a dead body sitting on a chair.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"6459","x":0.618924151,"y":0.74912768,"cat":"NPCs","group":"Characters","title":"Witch-Hunter Jerren (First Location)","desc":"<p>Witch-Hunter Jerren is first spoken to in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Castle+Redmane' target=\"\">Castle Redmane</a> just north of the Chamber Outside the Plaza <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Site+of+Grace' target=\"\">Site of Grace</a>. He is found here after the defeat of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Starscourge+Radahn' target=\"\">Starscourge Radahn</a>. If he is not found in this location, he is likey already at his second location in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Witchbane+Ruins' target=\"\">Witchbane Ruins</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6424","x":0.621730904,"y":0.74918872,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [5] - Redmane Castle","desc":"Upgrade Material. Found on a corpse by the large monument surrounded by chairs in the north of the castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"8","x":0.413231488,"y":0.749616004,"cat":"Bosses","group":"Characters","title":"Flying Dragon Agheel","desc":"Optional Dragon Boss of <strong>Agheel Lake</strong>. Rewards a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/dragon+heart'>Dragon Heart</a> you can use at the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/church+of+dragon+communion'>Church of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2931","x":0.54318705,"y":0.749890688,"cat":"Locations","group":"Locations","title":"Cathedral of Dragon Communion","desc":"Special Dragon Communion altar can be used to trade <a href='https://eldenring.wiki.fextralife.com/Dragon+Heart' target=\"_blank\">Dragon Hearts</a> for Draconic Incantations.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"1886","x":0.410925235,"y":0.750684215,"cat":"Consumables","group":"Items","title":"Dragon Heart (Flying Dragon Agheel)","desc":"Key Consumable. Dropped by <a href='https://eldenring.wiki.fextralife.com/Flying+Dragon+Agheel' target=\"_blank\"> Flying Dragon Agheel</a>. <strong>Dragon Hearts</strong> are used to acquire <a href='https://eldenring.wiki.fextralife.com/Dragon+Communion+Incantations' target=\"_blank\">Dragon Communion Incantations</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion' target=\"_blank\">Church of Dragon Communion</a> and the <a href='https://eldenring.wiki.fextralife.com/Cathedral+of+Dragon+Communion' target=\"_blank\">Cathedral of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4467","x":0.555513107,"y":0.750958895,"cat":"Spirit Ashes","group":"Equipment","title":"Miranda Sprout Ashes","desc":"Spirit Ashes. Found behind a hidden wall in <a href='https://eldenring.wiki.fextralife.com/Caelid+Catacombs' target=\"_blank\">Caelid Catacombs</a>. You must attack a wall to the right of the staircase to reveal a path to the ashes.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6138","x":0.621822374,"y":0.750989417,"cat":"NPCs","group":"Characters","title":"Blaidd (Ranni's Quest - Second Location)","desc":"NPC, appears awaiting for the festival after you meet him at <a href='https://eldenring.wiki.fextralife.com/Siofra+River' target=\"_blank\">Siofra River</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6452","x":0.401860819,"y":0.751080976,"cat":"Consumables","group":"Items","title":"Golden Rune [1]","desc":"Found by a ruin next to the lake.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"601","x":0.445116781,"y":0.751142016,"cat":"Locations","group":"Locations","title":"Waypoint Ruins","desc":"Waypoint Ruins consists of a group of broken buildings and abandoned campsites, now overrun with poisonous flowers and their crazed caretaker.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"4465","x":0.551641486,"y":0.751172539,"cat":"Locations","group":"Locations","title":"Caelid Catacombs","desc":"Found due East from the Cathedral of Dragon Communion.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"11","x":0.449564547,"y":0.75129462,"cat":"Armor","group":"Equipment","title":"Pumpkin Helm - 1x Waypoint Ruins","desc":"Dropped when defeating <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/mad+pumpkin+head'>Mad Pumpkin Head</a> boss.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"39","x":0.38817551,"y":0.75129462,"cat":"Locations","group":"Locations","title":"Church of Elleh","desc":"Ruins of an Old Church. There is a Merchant and a Smithing Table in the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"6114","x":0.546845453,"y":0.751752421,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [3] - 2x Caelid Catacombs","desc":"Spirit Ash Upgrade Material. A total of <strong>2</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Caelid+Catacombs' target=\"_blank\">Caelid Catacombs</a>: <ol> <li>The first one is found in the corner of the connecting corridor after the scarlot rot-flooded corridor past the Site of Grace.</li> <li>Continue along the dungeon until you reach a room with a small set of stairs on the left. The second glovewort is on the far wall opposite the stairs.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"453","x":0.366295719,"y":0.752057624,"cat":"Crafting Materials","group":"Items","title":"Land Octopus Ovary","desc":"Defeat <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Land+Octopus'>Land Octopus</a> to obtain.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1582","x":0.438339909,"y":0.752149187,"cat":"Weapons","group":"Equipment","title":"Greataxe","desc":"Found inside the treasure chest within the carriage being pulled by two large Trolls and defended by militia and aristocracy.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greataxe.png?h=40"},{"id":"4410","x":0.439592675,"y":0.753705718,"cat":"Locations","group":"Locations","title":"Enemy Caravan (Limgrave)","desc":"Enemy Caravan traveling the road South in Limgrave. Chest within contains <a href='https://eldenring.wiki.fextralife.com/Greataxe' target=\"_blank\">Greataxe</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-wagon.png?h=40"},{"id":"6451","x":0.389622334,"y":0.753766758,"cat":"Consumables","group":"Items","title":"Golden Rune [2]","desc":"Found by the <a href='https://eldenring.wiki.fextralife.com/Church+or+Elleh' target=\"_blank\">Church of Elleh</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"355","x":0.391898215,"y":0.75379728,"cat":"Sites of Grace","group":"Locations","title":"Church of Elleh","desc":"Site of Grace found within the ruins of the Church of Elleh.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6113","x":0.54815781,"y":0.753827799,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [4] - 3x Caelid Catacombs","desc":"Spirit Ash Upgrade Material. A total of <strong>3</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Caelid+Catacombs' target=\"_blank\">Caelid Catacombs</a>: <ol> <li>The first is found on the left side of the scarlet rot-flooded corridor just past the Site of Grace.</li> <li>The second one is found in the room before the boss door, in the corner of the central support.</li> <li>The third one is found in the same room, in the right corner in the back.</li> </ol>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"8155","x":0.4446714,"y":0.753931569,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Waypoint Ruins","desc":"Summoning Pool Effigy found outside the Waypoint Ruins location in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6117","x":0.554475431,"y":0.75394988,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [4] - Caelid Catacombs","desc":"Spirit Ash Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Caelid+Catacombs' target=\"_blank\">Caelid Catacombs</a>. Continue along the dungeon until you reach a room with a small set of stairs on the left. The glovewort can be found further down after turning the corner, just before the next corridor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"6456","x":0.621028855,"y":0.75394988,"cat":"Bosses","group":"Characters","title":"Crucible Knight / Misbegotten Warrior","desc":"Dual Bossfight against <strong>Crucible Knight</strong> and <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/misbegotten+warrior'>Misbegotten Warrior</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"467","x":0.382895772,"y":0.754468726,"cat":"Key Items","group":"Items","title":"Spirit Calling Bell","desc":"Key Item. Given by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Renna'>Renna</a>. Return to the church after getting your horse to find her sitting by the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"771","x":0.488902154,"y":0.754560285,"cat":"Key Items","group":"Items","title":"Nomadic Warrior's Cookbook [6]","desc":"Cookbook item. Can be looted from the chest in the room at the top of the main stairs of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Fort+Haight'>Fort Haight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"6203","x":0.622709895,"y":0.754926528,"cat":"Weapons","group":"Equipment","title":"Ruins Greatsword","desc":"Acquired by defeating the <a href='https://eldenring.wiki.fextralife.com/Misbegotten+Warrior' target=\"_blank\">Misbegotten Warrior</a> and <a href='https://eldenring.wiki.fextralife.com/Crucible+Knight' target=\"_blank\">Crucible Knight</a> duo bosses at <a href='https://eldenring.wiki.fextralife.com/Redmane+Castle' target=\"_blank\">Redmane Castle</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-colossalsword.png?h=40"},{"id":"6121","x":0.619594421,"y":0.755048609,"cat":"NPCs","group":"Characters","title":"Iron Fist Alexander (Third Location)","desc":"He can be found here waiting for the festival to start.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"5947","x":0.38728956,"y":0.755140171,"cat":"Spirit Ashes","group":"Equipment","title":"Lone Wolf Ashes","desc":"Given to players by <a href='https://eldenring.wiki.fextralife.com/Renna' target=\"_blank\">Renna</a> at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Elleh' target=\"_blank\">Church of Elleh</a> in Limgrave. Return to the Church after getting the ability to summon your Spectral Steed from <a href='https://eldenring.wiki.fextralife.com/Melina' target=\"_blank\">Melina</a>. You will find Renna sitting by the ruins of the church.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6116","x":0.552613716,"y":0.75517069,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [3] - Caelid Catacombs","desc":"Spirit Ash Upgrade Material. <strong>One</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Caelid+Catacombs' target=\"_blank\">Caelid Catacombs</a>. Continue along the dungeon until you reach a room with a small set of stairs on the left. The glovewort can be found further down after turning the corner, just before the next corridor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"6115","x":0.550141602,"y":0.755292771,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [5] - 2x Caelid Catacombs","desc":"Spirit Ash Upgrade Material. A total of <strong>2</strong> can be found inside the <a href='https://eldenring.wiki.fextralife.com/Caelid+Catacombs' target=\"_blank\">Caelid Catacombs</a>: <ul> <li>Continue along the dungeon until you reach a room with a small set of stairs on the left. Check under the stairs and hit the walls to reveal an alcove with 2 of the gloveworts.</li> </ul>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"5413","x":0.556550783,"y":0.755384334,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [4] - 1x Southern Caelid","desc":"<p>Upgrade Material. Dropped by a <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"blank\">Teardrop Scarab</a> in the southern edges of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Caelid' target=\"blank\">Caelid</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"10209","x":0.454020078,"y":0.755547109,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Waypoint Ruins Cliffside","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"blank\">Limgrave</a>, <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Waypoint+Ruins' target=\"blank\">Waypoint Ruins</a> east Cliffside.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"709","x":0.44491508,"y":0.755784267,"cat":"Sites of Grace","group":"Locations","title":"Waypoint Ruins Cellar","desc":"Site of grace in the cellar of the Waypoint Ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"2052","x":0.394246131,"y":0.755903176,"cat":"Weapons","group":"Equipment","title":"Golden Halberd","desc":"Drops from <a href='https://eldenring.wiki.fextralife.com/Tree+Sentinel' target=\"_blank\"> Tree Sentinel</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-halberd.png?h=40"},{"id":"707","x":0.4489895,"y":0.755964216,"cat":"NPCs","group":"Characters","title":"Sorceress Sellen (First Location)","desc":"Considered a witch and exiled member of the Raya Lucaria Academy, Sorceress Sellen sells Sorceries.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"958","x":0.492379507,"y":0.757123986,"cat":"NPCs","group":"Characters","title":"Kenneth Haight (Second Location)","desc":"Kenneth Haight will move to this location after you clear our Fort Haight. He can be found up on the battlements where you fought the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Beast+Crest+Heater+Knight'>Beast Crest Heater Knight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"4543","x":0.621334713,"y":0.757215549,"cat":"Sites of Grace","group":"Locations","title":"Redmane Castle Plaza","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"490","x":0.419543782,"y":0.75755127,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Rare Crafting Material. Found on a corpse sitting on a chair at the beach. Guarded by 4 <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Spirit+Jellyfish'>Spirit Jellyfish</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6589","x":0.600065538,"y":0.757642832,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found next to a big tree nearby the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2051","x":0.394405528,"y":0.758253237,"cat":"Bosses","group":"Characters","title":"Tree Sentinel (Limgrave)","desc":"Field Boss roaming the area. Drops <a href='https://eldenring.wiki.fextralife.com/Golden+Halberd' target=\"_blank\"> Golden Halberd</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"1965","x":0.39169769,"y":0.758436359,"cat":"Consumables","group":"Items","title":"Golden Rune [1] E","desc":"Inside a glowing skull in the open field. Hit it with any attack to obtain.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"10103","x":0.41640269,"y":0.758802602,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Dragon-Burnt Ruins","desc":"Summoning Pool Effigy north of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Dragon-Burnt+Ruins' target=\"blank\">Dragon-Burnt Ruins</a>. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6890","x":0.442459437,"y":0.759046764,"cat":"Crafting Materials","group":"Items","title":"Smoldering Butterfly","desc":"Find by looting a dead body at the base of the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"469","x":0.37288524,"y":0.759199364,"cat":"Key Items","group":"Items","title":"Sewing Needle","desc":"Key Quest Item. Dropped by the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Demi-Human+Chief'>Demi-Human Chief</a> boss upon defeat. Return it to <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Boc+the+Seamster'>Boc the Seamster</a> in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Coastal+Cave'>Coastal Cave</a> to further his storyline.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"805","x":0.493822818,"y":0.759474047,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Bloody Slash","desc":"Ash of War Upgrade. Dropped by a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Beast+Crest+Heater+Knight'>Beast Crest Heater Knight</a> fought at the top of the ramparts of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Fort+Haight'>Fort Haight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"6812","x":0.613980243,"y":0.759657169,"cat":"Key Items","group":"Items","title":"Red-Hot Whetblade","desc":"Key Item. Found in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/redmane+castle'>Redmane Castle</a>, at the bottom level of the gate house building east of the main gate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"770","x":0.489757241,"y":0.760145493,"cat":"Locations","group":"Locations","title":"Fort Haight","desc":"A Fort by the coast. Heavily guarded by knights and invested with <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Rat'>Rats</a>. Once cleared, many treasures can be found here.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-forthaight.png?h=40"},{"id":"36","x":0.416491254,"y":0.760389655,"cat":"Locations","group":"Locations","title":"Dragon-Burnt Ruins","desc":"Located in the lake of Limgrave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"3","x":0.39247755,"y":0.760420173,"cat":"NPCs","group":"Characters","title":"White-Faced Varre (First Location)","desc":"<a href='https://eldenring.wiki.fextralife.com/White-Faced+Varre' target=\"blank\">White-Faced Varre</a>, Location 1. Found right next to The First Step <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Sites+of+Grace'>Site of Grace</a>. Provides Lore info. You will encounter this NPC multiple times in different locations.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"8173","x":0.37450654,"y":0.760511736,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Coastal Cave","desc":"Summoning Pool Effigy found next to the Coastal Cave site of grace in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"1752","x":0.420037431,"y":0.760725376,"cat":"Waygates","group":"Locations","title":"Teleporter Chest (Sellia Crystal Tunnel)","desc":"This is a trap chest at an underground cellar in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/dragon-burnt+ruins'>Dragon-Burnt Ruins</a>. It will teleport you to the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Sellia+Crystal+Tunnel'>Sellia Crystal Tunnel</a> in <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Caelid'>Caelid</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"373","x":0.37773733,"y":0.760755898,"cat":"NPCs","group":"Characters","title":"Boc the Seamster (Second Location)","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Boc+the+Seamster'>Boc the Seamster</a> Location 2. After meeting him for the first time, Boc will move into the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Coastal+Cave'>Coastal Cave</a>. You will find him writhing on the ground next to the Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6438","x":0.447373594,"y":0.760755898,"cat":"Consumables","group":"Items","title":"Golden Rune [3]","desc":"Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6439","x":0.449815188,"y":0.761183182,"cat":"Consumables","group":"Items","title":"Golden Rune [2]","desc":"Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6422","x":0.622341502,"y":0.761427344,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] B - Redmane Castle","desc":"Upgrade Material. Found on a corpse on the roof of the eastern-most building south of the plaza. This roof can be reached by starting from the eastern gate house building right next to the main entrance. Head up the stairs and then navigate across the ramparts and some wooden bridges among the rooftops.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"370","x":0.376090095,"y":0.761702024,"cat":"Sites of Grace","group":"Locations","title":"Coastal Cave","desc":"Site of Grace found inside <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Coastal+Cave'>Coastal Cave</a>, near the beginning.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"807","x":0.484874608,"y":0.761793587,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Fort Haight","desc":"Flask Upgrade. Found right in front of the entrance to <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Fort+Haight'>Fort Haight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"6894","x":0.487529222,"y":0.761793587,"cat":"Crafting Materials","group":"Items","title":"Bloodrose","desc":"6 Bloodrose bushes can be farmed at <a href='https://eldenring.wiki.fextralife.com/Fort+Haight' target=\"_blank\">Fort Haight</a>, at the far Southeast corner of Limgrave. 1 at the entrance stairway, 2 behind the castle, and 3 within the fort's courtyard. After collecting them, teleporting back to the nearby grace site is faster than riding back on Torrent, since the fort is a no-riding zone.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5721","x":0.611416569,"y":0.761976708,"cat":"Key Items","group":"Items","title":"Armorer's Cookbook [4]","desc":"Found in <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Redmane+Castle'>Redmane Castle</a>, inside the gate house building east of the main gate, behind a large barrel.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"4256","x":0.480085243,"y":0.762007226,"cat":"Sites of Grace","group":"Locations","title":"Fort Haight West","desc":"Site of Grace just west from Fort Haight","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"468","x":0.371725484,"y":0.762251389,"cat":"Key Items","group":"Items","title":"Tailoring Tools","desc":"Key Item. Dropped by the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Demi-Human+Chief'>Demi-Human Chief</a> boss upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"6895","x":0.490824742,"y":0.762281911,"cat":"Crafting Materials","group":"Items","title":"Bloodrose","desc":"can be found at the hight level of <a href='https://eldenring.wiki.fextralife.com/Fort+Haight' target=\"_blank\">Fort Haight</a> on a dead body","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6421","x":0.615383192,"y":0.762495551,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] A - Redmane Castle","desc":"Upgrade Material. Found on a pile of corpses to the side of the main road, near the main gate.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"774","x":0.492299562,"y":0.762526073,"cat":"Key Items","group":"Items","title":"Dectus Medallion (Left)","desc":"Key Quest Item. Found in a chest that can be reached by climbing the ladder in the tallest tower of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Fort+Haight'>Fort Haight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6588","x":0.580963311,"y":0.762983875,"cat":"Crafting Materials","group":"Items","title":"Mushroom - Caelid (Impassable Greatbridge)","desc":"Can be found on a dead body inside a tent.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2980","x":0.488789772,"y":0.763075437,"cat":"Weapons","group":"Equipment","title":"Partisan - Limgrave","desc":"A Partisan Spear that can be dropped from a <a href='https://eldenring.wiki.fextralife.com/Godrick+Knight' target=\"_blank\">Godrick Knight</a> in <a href='https://eldenring.wiki.fextralife.com/Fort+Haight' target=\"_blank\">Fort Haight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spear.png?h=40"},{"id":"6440","x":0.448227345,"y":0.763136478,"cat":"Consumables","group":"Items","title":"Golden Rune [1]","desc":"x3 Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5856","x":0.62170095,"y":0.763411158,"cat":"Sites of Grace","group":"Locations","title":"Chamber Outside the Plaza","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"38","x":0.37517337,"y":0.76344168,"cat":"Locations","group":"Locations","title":"Coastal Cave","desc":"A dark and humid cavern home to the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Demi-Human+Chief'>Demi-Human Chief</a> boss. Must be completed to access the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion'>Church of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"6057","x":0.401781839,"y":0.76344168,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1]","desc":"Found on a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"458","x":0.399254871,"y":0.763472199,"cat":"Sites of Grace","group":"Locations","title":"Cave of Knowledge","desc":"Site of grace located inside the Cave of Knowledge","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6415","x":0.609370768,"y":0.763502721,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] A - Redmane Castle","desc":"Upgrade material. Found on a corpse behind the lookout tower outside of <a href='https://eldenring.wiki.fextralife.com/Redmane+Castle' target=\"_blank\">Redmane Castle</a>, at ground level.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"457","x":0.391654058,"y":0.763807923,"cat":"Sites of Grace","group":"Locations","title":"The First Step","desc":"Site of Grace found just outside the Stranded Graveyard, named The First Step.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3834","x":0.416060696,"y":0.763899483,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - 1x Dragon-Burnt Ruins","desc":"Consumable. Pillage the remains in the middle of <p><a class=\"wiki_link\" title=\"\"href='https://eldenring.wiki.fextralife.com/Dragon-Burnt+Ruins' target=\"\">Dragon-Burnt Ruins</a></p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"353","x":0.396969198,"y":0.763991045,"cat":"Key Items","group":"Items","title":"Small Golden Effigy","desc":"Multiplayer Item. Found on the Summoning Pool a few steps west of The First Step Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"8154","x":0.395748402,"y":0.764052085,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: First Step","desc":"Summoning Pool Effigy found near the First Step site of grace in Limgrave. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6414","x":0.607357873,"y":0.764296247,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [6] A - Redmane Castle","desc":"Upgrade Material. Found on a corpse on a ledge in the middle level of the lookout tower outside of <a href='https://eldenring.wiki.fextralife.com/Redmane+Castle' target=\"_blank\"> Redmane Castle</a>. To reach this item, head for the cliffs to the south of the castle's main gate and then jump onto the tower's roof. There is a ladder you can descend to reach the middle ledge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"9834","x":0.583612125,"y":0.764357288,"cat":"Waygates","group":"Locations","title":"Impassable Greatbridge Waygate","desc":"Waygate. Found at the Impassable Greatbridge Site of Grace outside Redmane Castle. Teleports you inside <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Redmane+Castle' target=\"blank\">Redmane Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"773","x":0.485728566,"y":0.76466249,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] - Fort Haight","desc":"Upgrade Material. Found by looting a corpse on the battlements of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Fort+Haight'>Fort Haight</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"456","x":0.417291718,"y":0.76475405,"cat":"Key Items","group":"Items","title":"Stonesword Key - Dragon-Burnt Ruins","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stoneword+Key' target=\"\">Stoneword Key</a> Found inside a small room, protected by a Rat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"2961","x":0.582366764,"y":0.765089774,"cat":"Sites of Grace","group":"Locations","title":"Impassable Greatbridge","desc":"A heavily guarded great bridge that leads to the <a href='https://eldenring.wiki.fextralife.com/Redmane+Castle' target=\"blank\">Redmane Castle</a> of Caelid.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6608","x":0.39970776,"y":0.765169125,"cat":"Key Items","group":"Items","title":"Stonesword Key - Fringefolk Hero's Grave","desc":"Held by a corpse within <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/fringefolk+hero's+grave'>Fringefolk Hero's Grave</a>. Look for the body on a platform above the chariot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"351","x":0.394401782,"y":0.765333936,"cat":"Key Items","group":"Items","title":"Finger Severer","desc":"Multiplayer Item. Found on a corpse by the wall just past the Site of Grace in the Stranded Graveyard. Found along with the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Tarnished's+Furled+Finger'>Tarnished's Furled Finger</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"5220","x":0.402302513,"y":0.76576122,"cat":"Locations","group":"Locations","title":"Stranded Graveyard","desc":"Players are transported here after dying for the first time at the beginning of the game.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"6420","x":0.618465704,"y":0.76576122,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [4] B - Redmane Castle","desc":"Upgrade Material. Found on a corpse in the open space above the building in the center of the castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6528","x":0.616330085,"y":0.76576122,"cat":"Locations","group":"Locations","title":"Redmane Castle","desc":"Major Dungeon. A small castle that is heavily guarded at the castle's outskirts by Radahn Knights and Soldiers. Redmane Castle serves as the gathering point for warriors alike who are wanting to participate in the Radahn Festival.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redmanecastle.png?h=40"},{"id":"455","x":0.419359435,"y":0.76582226,"cat":"Weapons","group":"Equipment","title":"Twinblade","desc":"Underground. Can be found once you take the stairs down <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Dragon-Burnt+Ruins'>Dragon-Burnt Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-doubleedgedswords.png?h=40"},{"id":"5205","x":0.579377554,"y":0.765852778,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Cragblade","desc":"Can be found at West of Impassable Greatbridge site, on a scarab in the sword monument","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"9844","x":0.597853865,"y":0.766005382,"cat":"Waygates","group":"Locations","title":"Impassable Greatbridge Redmane Waygate","desc":"Waygate. Found across the Impassable Greatbridge Site of Grace towards Redmane Castle. Teleports you to the waygate inside <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Redmane+Castle' target=\"blank\">Redmane Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"371","x":0.374411949,"y":0.766157981,"cat":"Bosses","group":"Characters","title":"Demi-Human Chief","desc":"Optional Boss. A duo of Demi-Human bosses found deep within the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Coastal+Cave'>Coastal Cave</a>. Required to defeat in order to access the <a target=\"_blank\" href=\"Church+of+Dragon+Communion\">Church of Dragon Communion</a> location. Drops the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Tailoring+Tools'>Tailoring Tools</a> and <a target=\"_blank\" href=\"Sewing+Needle\">Sewing Needle</a> key items upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2113","x":0.418414545,"y":0.766341102,"cat":"Crafting Materials","group":"Items","title":"Great Dragonfly Head","desc":"On a corpse underwater at the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/dragon-burnt+ruins'>Dragon-Burnt Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5551","x":0.41017225,"y":0.766493706,"cat":"Armor","group":"Equipment","title":"Incantation Scarab","desc":"Need to examine the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/homecoming+painting'>Homecoming Painting</a> at <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/artist's+shack'>Artist's Shack</a> first. The Incantation Scarab can be found Southwest of the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/dragon-burnt+ruins'>Dragon Burnt Ruins</a>, there will be a gravestone with a ghost sitting in front of it. Interact with the ghost, and it will drop the Incantation Scarab.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"2504","x":0.396840447,"y":0.766768386,"cat":"Weapons","group":"Equipment","title":"Dragon Communion Seal","desc":"Found in the <a href='https://eldenring.wiki.fextralife.com/Fringefolk+Hero's+Grave' target=\"_blank\">Fringefolk Hero's Grave</a>. Progress down the tunnel with the mechanized chariot until the path splits and you can go either up or down. Go up until you reach the end of the tunnel and inside the small room is an enemy that once killed will give you the weapon.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacredseal.png?h=40"},{"id":"3261","x":0.581573245,"y":0.766920989,"cat":"Talismans","group":"Equipment","title":"Arrow's Sting Talisman","desc":"Found in the chest at the top of the tower next to the Impassable Greatbridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3841","x":0.392691937,"y":0.767165151,"cat":"Bosses","group":"Characters","title":"Ulcerated Tree Spirit (Limgrave)","desc":"<p>Ulcerated Tree Spirit is found underneath the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Stranded+Graveyard' target=\"\">Stranded Graveyard</a> within <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Fringefolk+Hero's+Grave' target=\"\">Fringefolk Hero's Grave</a>. Defeating it drops <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Banished+Knight+Oleg's+Ashes' target=\"\">Banished Knight Oleg's Ashes</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mainboss.png?h=40"},{"id":"9833","x":0.620930093,"y":0.76719567,"cat":"Waygates","group":"Locations","title":"Redmane Castle Waygate","desc":"Waygate. Within <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Redmane+Castle' target=\"\">Redmane Castle</a>. Teleports you to the waygate next to Impassable Greatbridge Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"6869","x":0.61455868,"y":0.76841648,"cat":"Consumables","group":"Items","title":"Golden Rune [6] - Redmane Castle","desc":"Rune Consumable. Found on a corpse inside a guardhouse in the castle's inner grounds.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2505","x":0.398647793,"y":0.768447002,"cat":"Talismans","group":"Equipment","title":"Erdtree's Favor","desc":"Head down until you see the path narrow on both sides and drop just at the edge where it begins to find a secret area. Defeat the imps and proceed past the fire trap to find the item resting at an altar. Two Grafted Scions wait hanging above, so be sure to avoid them when they land and grab it really quickly","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6","x":0.381308636,"y":0.768721682,"cat":"NPCs","group":"Characters","title":"Nomadic Merchant West Limgrave","desc":"General Goods vendor found southeast of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Coastal+Cave'>Coastal Cave</a> entrance along the beach, sitting by a fire under a collapsed stone structure.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"2","x":0.395133328,"y":0.768874285,"cat":"Sites of Grace","group":"Locations","title":"Stranded Graveyard","desc":"Site of Grace found inside the Stranded Graveyard, just before the lift leading outside to The First Step.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3844","x":0.393306812,"y":0.768874285,"cat":"Spirit Ashes","group":"Equipment","title":"Banished Knight Oleg Ashes","desc":"<p>This Spirit is obtained after Defeating the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Ulcerated+Tree+Sprit' target=\"\">Ulcerated Tree Sprit</a> located within <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Fringefolk+Hero's+Grave' target=\"\">Fringefolk Hero's Grave</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"6202","x":0.621976885,"y":0.769057407,"cat":"Weapons","group":"Equipment","title":"Flamberge","desc":"Greatsword found on a corpse on the roof of the building in the southeast of <a href='https://eldenring.wiki.fextralife.com/Redmane+Castle' target=\"_blank\">Redmane Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"522","x":0.415908095,"y":0.769087925,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - 1x Dragon-Burnt Ruins","desc":"Over a big stone, where some bats are nesting. Defeat them to loot the body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"356","x":0.40081471,"y":0.76948469,"cat":"Bosses","group":"Characters","title":"Soldier of Godrick","desc":"Optional Boss. Found within in the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stranded+Graveyard' target=\"_blank\">Stranded Graveyard</a> if you jump down the pit into the Tutorial Area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"3850","x":0.397419903,"y":0.770186654,"cat":"Locations","group":"Locations","title":"Fringefolk Hero's Grave","desc":"Fringefolk Hero's Grave is found in <a href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"_blank\">Limgrave</a> behind a fog wall in <a href='https://eldenring.wiki.fextralife.com/Stranded+Graveyard' target=\"_blank\">Stranded Graveyard</a> that requires 2 <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Keys</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-herosgrave.png?h=40"},{"id":"6419","x":0.623714895,"y":0.770278217,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] B - Redmane Castle","desc":"Upgrade Material. Found on a corpse at the top of southeast tower of the castle, accessible by climbing ladders inside and on the roof of the southeast building it is attached to.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6418","x":0.620631801,"y":0.770339258,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [3] B - Redmane Castle","desc":"Upgrade Material. Found on a corpse on the rooftop of the building in the southeast of <a href='https://eldenring.wiki.fextralife.com/Redmane+Castle' target=\"_blank\">Redmane Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"8954","x":0.615434073,"y":0.770339258,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Redmane Castle South Entrance","desc":"Summoning Pool Effigy found Right at the south entrance of Redmane Castle where a Golden Rune can be obtained. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6454","x":0.463096676,"y":0.770522379,"cat":"Consumables","group":"Items","title":"Golden Rune [4]","desc":"Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5723","x":0.61474225,"y":0.77091914,"cat":"Key Items","group":"Items","title":"Armorer's Cookbook [5]","desc":"Found on a corpse in the southern-most building of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Redmane+Castle'>Redmane Castle</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"6455","x":0.465629827,"y":0.771071744,"cat":"Consumables","group":"Items","title":"Golden Rune [3]","desc":"Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3846","x":0.394124246,"y":0.771163303,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - 1x Fringefolk Hero's Grave","desc":"<p>This item is obtained after Defeating the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Ulcerated+Tree+Sprit' target=\"\">Ulcerated Tree Sprit</a> located within <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Fringefolk+Hero's+Grave' target=\"\">Fringefolk Hero's Grave</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"528","x":0.436058848,"y":0.772109432,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Unsheathe","desc":"Can be obtained from a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab'>Teardrop Scarab</a> located in the water. Beware of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Giant+Crab'>Giant Crab</a> nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"5926","x":0.618529994,"y":0.772231513,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Flaming Strike","desc":"Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\"> Teardrop Scarab</a> in graveyard south of <a href='https://eldenring.wiki.fextralife.com/Redmane+Castle' target=\"_blank\">Redmane Castle</a>. You can get here through the backdoor of the southern-most building. Alternatively, you can scale the cliffs outside the castle's western ramparts, past some bats to reach the graveyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"519","x":0.408251198,"y":0.772475675,"cat":"Talismans","group":"Equipment","title":"Haligdrake Talisman","desc":"Talisman. Drop down from the cliff near the Seaside Ruins site of grace. Explore the lower area and between fallen columns, there is a small entrance. Enter and take the path until you fing a hanging body.There you will find the Haligdrake Talisman - this is the unreachable item seen in the Cave of Knowledge starting tutorial","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6457","x":0.462358874,"y":0.772719837,"cat":"Consumables","group":"Items","title":"Golden Rune [2]","desc":"Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6417","x":0.615353313,"y":0.772811396,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [5] A - Redmane Castle","desc":"Upgrade Material. Found on a corpse inside the southern-most building of the castle.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"6458","x":0.464769948,"y":0.772963999,"cat":"Consumables","group":"Items","title":"Golden Rune [1]","desc":"x4 Found by looting the sarcophagi.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6891","x":0.43489253,"y":0.773208161,"cat":"Crafting Materials","group":"Items","title":"Crab Eggs","desc":"Find by looting a dead body at the edge of the lake, near <a href='https://eldenring.wiki.fextralife.com/Ash+of+War:+Unsheathe'_blank\">Ash of War: Unsheathe</a> location.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6139","x":0.398458001,"y":0.773696485,"cat":"Weapons","group":"Equipment","title":"Erdtree Greatbow","desc":"Dropped from the Chariot inside <a href='https://eldenring.wiki.fextralife.com/Fringefolk+Hero's+Grave' target=\"_blank\">Fringefolk Hero's Grave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bow.png?h=40"},{"id":"452","x":0.394632332,"y":0.774337409,"cat":"Consumables","group":"Items","title":"Gold-Pickled Fowl Foot","desc":"Near the waterfall, beware of the lurking skeletons","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2105","x":0.390451103,"y":0.774490012,"cat":"Consumables","group":"Items","title":"Golden Rune [1] H","desc":"Found along the shore before reaching the bridge, under which the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/gold-pickled+fowl+foot'>Gold-Pickled Fowl Foot</a> is.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"5","x":0.422990891,"y":0.77452053,"cat":"NPCs","group":"Characters","title":"Bloody Finger Hunter Yura (First Location)","desc":"First encounter with this NPC, warns you about the dragon in the nearby ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6892","x":0.457168146,"y":0.775710822,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"Can be found in nearby bushes on the edge cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10202","x":0.394219857,"y":0.775835833,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Behind Fringefolk Hero's Grave","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in Limgrave, on the lower beaches behind Fringefolk Hero's Grave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"2403","x":0.453201089,"y":0.777145273,"cat":"Weapons","group":"Equipment","title":"Warpick","desc":"Looted from one of the many <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/undead+soldier'>Undead Soldiers</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-hammer.png?h=40"},{"id":"551","x":0.450394367,"y":0.777419956,"cat":"Weapons","group":"Equipment","title":"Great Epee","desc":"Head southeast from the Agheel Lake South site of grace, head to the top of a cliff and you'll see a statue of an object that looks like the half piece of a bowl or a circle. Face the other way, and get down, you will find a group of enemies. The Great Epee is inside a chest. on the right side.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-thrusting_sword.png?h=40"},{"id":"499","x":0.41749925,"y":0.777542037,"cat":"Sites of Grace","group":"Locations","title":"Seaside Ruins","desc":"Site of grace located in the wilderness.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"719","x":0.433031006,"y":0.778762847,"cat":"Crafting Materials","group":"Items","title":"Sliver of Meat","desc":"Crafting Material. Found on a corpse where a singing Bat is sitting.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"507","x":0.412098416,"y":0.778945969,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Gravitas","desc":"Looted from a <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Lesser+Alabaster+Lord'>Lesser Alabaster Lord</a> that uses the Gravitas skill as one of its attacks when it fights. You can find the enemy roaming by the beach-side at the stone arch that has a bonfire, near the Seaside Ruins Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"517","x":0.406451804,"y":0.779770014,"cat":"Crafting Materials","group":"Items","title":"Lump of Flesh","desc":"can be looted from a corpse by the beachside near the Seaside Ruins Site of Grace in south of Limgrave. The corpse is being guarded by a Giant Crab.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2402","x":0.455583455,"y":0.780044698,"cat":"Consumables","group":"Items","title":"Golden Rune [1] K","desc":"2 Golden Runes (1) on top of a big stone, accessible by <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)#spiritjumping'>Spirit Jumping</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"535","x":0.452161585,"y":0.78022782,"cat":"Key Items","group":"Items","title":"Royal House Scroll","desc":"Head southeast from the Agheel Lake South site of grace, head to the top of a cliff and you'll see a statue of an object that looks like the half piece of a bowl or a circle. Face the other way, to see a Knight. Keep going to a structure to see a man standing watching over the big structure, alongside a dead body. In that body, you will find the Royal House Scroll.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-scroll.png?h=40"},{"id":"2357","x":0.421163551,"y":0.780807702,"cat":"Consumables","group":"Items","title":"Golden Rune [1] J","desc":"Next to a big arch structure, besides a large rock.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"530","x":0.441671023,"y":0.780899265,"cat":"Sites of Grace","group":"Locations","title":"Agheel Lake South","desc":"Site of Grace located over a rocky terrain, near a herd of Sheep.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"10203","x":0.414748135,"y":0.781001001,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Seaside Ruins","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in Limgrave, just south of the Seaside Ruins Site of Grace. Can be used to jump down to the shore safely to get the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Ash+of+War:+Gravitas' target=\"blank\">Ash of War: Gravitas</a> and <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Haligdrake+Talisman' target=\"blank\">Haligdrake Talisman</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"375","x":0.362237535,"y":0.781479148,"cat":"Spells","group":"Equipment","title":"Dragonmaw","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Incantation'>Incantation</a>. Can be obtained by making a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Dragon+Heart'>Dragon Heart</a> offering at the altar found in the ruins of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion'>Church of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"7451","x":0.445477722,"y":0.782638918,"cat":"Key Items","group":"Items","title":"Larval Tear - 1x Limgrave Bear Drop","desc":"Key item used for Rebirth. Obtained by defeating a regular Noble enemy, that transforms into a Lesser Rune Bear. If you kill the Bear form a larval tear will drop.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6437","x":0.438675419,"y":0.782699959,"cat":"Consumables","group":"Items","title":"Golden Rune [2]","desc":"Found by the statue.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"376","x":0.365928122,"y":0.78273048,"cat":"Sites of Grace","group":"Locations","title":"Church of Dragon Communion","desc":"Site of Grace just outside of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion'>Church of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"534","x":0.45085122,"y":0.783707128,"cat":"Shields","group":"Equipment","title":"Brass Shield","desc":"Found southeast of the map in Limgrave. Head southeast from the Agheel Lake South site of grace, head to the top of a cliff and you'll see a statue of an object that looks like the half piece of a bowl or a circle. Face the other way, to see a Knight. Defeat it to obtain a Brass Shield.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"532","x":0.4539407,"y":0.784042849,"cat":"Consumables","group":"Items","title":"Starlight Shards - Southern Limgrave","desc":"<a href='https://eldenring.wiki.fextralife.com/Starlight+Shards' target=\"_blank\">Starlight Shards</a>: Do a Spiritspring Jumping, and keep jumping until you reach the top.You will find the item over a cup-like monument, on the edge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"374","x":0.366997182,"y":0.784897416,"cat":"Spells","group":"Equipment","title":"Dragonclaw","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Incantation'>Incantation</a>. Can be obtained by making a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Dragon+Heart'>Dragon Heart</a> offering at the altar found in the ruins of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion'>Church of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"27","x":0.35817825,"y":0.785080538,"cat":"Spells","group":"Equipment","title":"Dragonfire","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Incantation'>Incantation</a>. Can be obtained by making a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Dragon+Heart'>Dragon Heart</a> offering at the altar found in the ruins of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Church+of+Dragon+Communion'>Church of Dragon Communion</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"34","x":0.36382371,"y":0.787155915,"cat":"Locations","group":"Locations","title":"Church of Dragon Communion","desc":"The ruins of a church where dragon rituals were performed. The most prominent sight here is the corpse of a large white dragon laying amongst the ruins. There is also an altar where you can obtain powerful <a target=\"_blank\" href=\"Incantations\">Incantations</a> in exchange for <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Dragon+Heart'>Dragon Heart</a> offerings.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"2358","x":0.421191067,"y":0.787277996,"cat":"Crafting Materials","group":"Items","title":"String","desc":"Dropped by killed <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/demi-human'>Demi-Humans</a> during an ambush.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10204","x":0.447828955,"y":0.787613721,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Bridge of Sacrifice","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"\">Limgrave</a>, just north of the Bridge of Sacrifice. Follow the part north to reach this Spiritjump spot.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"5946","x":0.407885167,"y":0.790907467,"cat":"Spirit Ashes","group":"Equipment","title":"Warhawk Ashes","desc":"Rewarded upon finding the location Prophecy Painting depicts. The location is north of the <a href='https://eldenring.wiki.fextralife.com/Church+of+Pilgrimage' target=\"_blank\">Church of Pilgrimage</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"1757","x":0.443283883,"y":0.791215111,"cat":"Weapons","group":"Equipment","title":"Bloodhound's Fang","desc":"Curved Greatsword. Dropped by the boss of <a href='https://eldenring.wiki.fextralife.com/Forlorn+Hound+Evergaol' target=\"_blank\">Forlorn Hound Evergaol</a>, <a href='https://eldenring.wiki.fextralife.com/Bloodhound+Knight+Darriwil' target=\"_blank\">Bloodhound Knight Darriwil</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-curvedgreatsword.png?h=40"},{"id":"6061","x":0.366021608,"y":0.791245629,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2]","desc":"On a high rock near the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"498","x":0.420581431,"y":0.79136771,"cat":"Crafting Materials","group":"Items","title":"Crab Eggs","desc":"Found on a body located on the edge. Beware of the small skeleton army you have to face before.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"377","x":0.360619582,"y":0.791672913,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [1] - Church of Dragon Communion","desc":"Upgrade Material. Obtained by defeating a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab'>Teardrop Scarab</a> in the cliffs behind the church.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"6710","x":0.403949752,"y":0.791703435,"cat":"Crafting Materials","group":"Items","title":"Sliver of Meat","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Church+of+Pilgrimage' target=\"_blank\">Church of Pilgrimage</a> area, down the cliffside on a dead body","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6955","x":0.363990333,"y":0.792405399,"cat":"Consumables","group":"Items","title":"Exalted Flesh - Church of Dragon Communion","desc":"Can be found at the top of the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"1756","x":0.439228914,"y":0.792619042,"cat":"Bosses","group":"Characters","title":"Bloodhound Knight Darriwil","desc":"Boss of <a href='https://eldenring.wiki.fextralife.com/Forlorn+Hound+Evergaol' target=\"_blank\">Forlorn Hound Evergaol</a>. Drops the <a href='https://eldenring.wiki.fextralife.com/Bloodhound's+Fang' target=\"_blank\">Bloodhound's Fang</a> Curved Greatsword","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"766","x":0.442001842,"y":0.792954764,"cat":"Locations","group":"Locations","title":"Forlorn Hound Evergaol","desc":"An Evergaol on Southern Limgrave. This location does not allow use of Spirit Ashes or Summons.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-evergaol.png?h=40"},{"id":"6954","x":0.402475947,"y":0.793443087,"cat":"Consumables","group":"Items","title":"Bewitching Branch - Weeping Peninsula","desc":"Can be found on a corpse, surrounded by bats.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6709","x":0.409992832,"y":0.794389217,"cat":"Crafting Materials","group":"Items","title":"Golden Centipede","desc":"Found on the ground in front of the altar at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Pilgrimage' target=\"_blank\">Church of Pilgrimage</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"511","x":0.411578668,"y":0.794816501,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (Church of Pilgrimage)","desc":"Flask Upgrade Material. Found on the ground in front of the altar at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Pilgrimage' target=\"_blank\">Church of Pilgrimage</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"512","x":0.403888782,"y":0.794938582,"cat":"Shields","group":"Equipment","title":"Gilded Iron Shield","desc":"Shield. Found on a corpse sitting on a grave in the graveyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-smallshield.png?h=40"},{"id":"509","x":0.408615595,"y":0.795396383,"cat":"Locations","group":"Locations","title":"Church of Pilgrimage","desc":"Church ruins found atop cliffs in the northern section of Weeping Peninsula.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"2503","x":0.452048464,"y":0.796250951,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - 3x Bridge of Sacrifice","desc":"There's 1 Golden Rune (1) prior to the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/bridge+of+sacrifice'>Bridge of Sacrifice</a>, on the <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/limgrave'>Limgrave</a> side. There are other two at the bridge, one between the wooden barricades and the other as a drop from the enemies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4260","x":0.440842281,"y":0.796373032,"cat":"NPCs","group":"Characters","title":"Blaidd (2nd Location)","desc":"Blaidd's Second Encounter. Darriwil can be fought at the Forlorn Hound Evergaol, where Blaidd will become available as a summon. Speak to Blaidd again after the fight. <br />Talking to Blaidd once will yield a Somber Smithing stone [2]. Talk to him a second time and he will mention a blacksmith along the Road to the Manor in Liurnia, and instruct the player to say that \"Blaidd sent them\". Doing this will unlock the Carian Filigreed Crest in the blacksmith's shop. <br />If the Evergaol fight was completed before meeting Blaidd, he will still be available to speak to here after the player talks to him in the Mistwood Ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"7908","x":0.443403534,"y":0.796952918,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [2] - 1x Blaidd Quest Reward","desc":"Upgrade Material. Obtained as a reward for completing Forlorn Hound Evergaol with Blaidd, then talking to him outside the Jail.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"510","x":0.410881853,"y":0.799669219,"cat":"Sites of Grace","group":"Locations","title":"Church of Pilgrimage","desc":"Site of Grace found at the <a href='https://eldenring.wiki.fextralife.com/Church+of+Pilgrimage' target=\"_blank\">Church of Pilgrimage</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"487","x":0.457137497,"y":0.800249106,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] - Bridge of Sacrifice","desc":"Upgrade Material. Found on a corpse on the eastern edge of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Bridge+of+Sacrifice'>Bridge of Sacrifice</a>, near the middle section.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"513","x":0.404337662,"y":0.800310146,"cat":"Consumables","group":"Items","title":"Blood Grease","desc":"Consumable Item. Two can be found by a grave with a wooden pole next to it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"485","x":0.45472606,"y":0.800462746,"cat":"Locations","group":"Locations","title":"Bridge of Sacrifice","desc":"A large stone bridge connecting <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Limgrave'>Limgrave</a> to the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Weeping+Peninsula'>Weeping Peninsula</a>. Lots of enemy soldiers and ballistae around.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cityruins.png?h=40"},{"id":"3916","x":0.422166735,"y":0.802568645,"cat":"Flask Upgrades","group":"Items","title":"Faith-knot Crystal Tear","desc":"North of the <a href='https://eldenring.wiki.fextralife.com/Demi-Human+Forest+Ruins' target=\"_blank\">Demi-Human Forest Ruins</a>. Directly east of the <a href='https://eldenring.wiki.fextralife.com/Church+of+Pilgrimage' target=\"_blank\">Church of Pilgrimage</a>, just down the cliff. It's in a bowl under a tree and surrounded by <a href='https://eldenring.wiki.fextralife.com/Poison+Flower' target=\"_blank\">Poison Flowers</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"6956","x":0.433792232,"y":0.802934888,"cat":"Consumables","group":"Items","title":"Glowstone - Limgrave","desc":"Can be found on a corpse. Beware of the two goblins that will spawn near it.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6893","x":0.443318582,"y":0.802995928,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"On the lowest cliff south of the <a href='https://eldenring.wiki.fextralife.com/Forlorn+Hound+Evergaol' target=\"_blank\">Forlorn Hound Evergaol</a>, near a spiritspring","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"5902","x":0.441212709,"y":0.804186216,"cat":"Weapons","group":"Equipment","title":"Large Club","desc":"On the lowest cliff south of the <a href='https://eldenring.wiki.fextralife.com/Forlorn+Hound+Evergaol' target=\"_blank\">Forlorn Hound Evergaol</a>, near a spiritspring","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-hammer.png?h=40"},{"id":"10205","x":0.438109614,"y":0.804186216,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Forlorn Hound Evergaol","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank_\">Torrent</a>. Found in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"\">Limgrave</a>, south <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Forlorn+Hound+Evergaol' target=\"\">Forlorn Hound Evergaol</a>&nbsp;toward the cliffside by the water.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"488","x":0.455976576,"y":0.80467454,"cat":"Key Items","group":"Items","title":"Stonesword Key  - Bridge of Sacrifice (Weeping Peninsula)","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stoneword+Key' target=\"\">Stoneword Key</a> Found on the ground by a wooden barricade at the southern end of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Bridge+of+Sacrifice'>Bridge of Sacrifice</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"6467","x":0.421679159,"y":0.80467454,"cat":"Bosses","group":"Characters","title":"Demi-human queen","desc":"Demi-Human Queen guarding the site. Drops <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/crystal+burst'>Crystal Burst</a> and <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/demi-human+queen's+staff'>Demi-Human Queen's Staff</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6708","x":0.414782206,"y":0.804766103,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily - 3x","desc":"Can be found x3 Trina's Lily next to a small cliffside.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6707","x":0.421678897,"y":0.806566796,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Demi-human+Forest+Ruins' target=\"_blank\">Demi-human Forest Ruins</a> near to <a href='https://eldenring.wiki.fextralife.com/Demi-human' target=\"_blank\">Demi-human</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"728","x":0.461714319,"y":0.806902521,"cat":"Key Items","group":"Items","title":"Stonesword Key - North East Weeping Peninsula","desc":"<a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a>. Found on a corpse sitting in a chair at the northern edge of the plateau, overlooking the sea.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"486","x":0.453417015,"y":0.807390845,"cat":"Sites of Grace","group":"Locations","title":"Bridge of Sacrifice","desc":"Site of Grace found on the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Weeping+Peninsula'>Weeping Peninsula</a> end of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Bridge+of+Sacrifice'>Bridge of Sacrifice</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"501","x":0.436478416,"y":0.807573966,"cat":"Sites of Grace","group":"Locations","title":"Earthbore Cave","desc":"Site of Grace found inside the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Earthbore+Cave' target=\"_blank\">Earthbore Cave</a>, near the entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6692","x":0.462844196,"y":0.808092809,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"Can be found nearby <a href='https://eldenring.wiki.fextralife.com/Impaler's+Catacombs' target=\"_blank\">Impaler's Catacombs</a> on a cliff","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"494","x":0.433305843,"y":0.809130497,"cat":"Locations","group":"Locations","title":"Earthbore Cave","desc":"A small dark cave on the side of the cliffside between <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Limgrave' target=\"_blank\">Limgrave</a> and <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Weeping Peninsula' target=\"_blank\">Weeping Peninsula</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"730","x":0.466139045,"y":0.809710384,"cat":"Armor","group":"Equipment","title":"Imp Head (Cat)","desc":"Helm. Rare drop inside the <a href='https://eldenring.wiki.fextralife.com/Impaler's+Catacombs' target=\"_blank\">Impaler's Catacombs</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"489","x":0.4587839,"y":0.809862984,"cat":"NPCs","group":"Characters","title":"Irina","desc":"NPC found sitting on a rock at the beginning of the main road in eastern Weeping Peninsula. Hands you <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Irina's+Letter'>Irina's Letter</a> and asks that you deliver it to her father at <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Castle+Morne'>Castle Morne</a> in the south.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6701","x":0.443863725,"y":0.810076627,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"Can be found near to a Stone pilar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1810","x":0.422046154,"y":0.810137668,"cat":"Weapons","group":"Equipment","title":"Demi-Human Queen's Staff","desc":"Dropped by the Demi-Human Queen elite enemy in Demi-Human Forest Ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"6653","x":0.461533444,"y":0.810351308,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [2] - Impaler's Catacombs","desc":"Spirit Ash Upgrade Material. Found under the impaler lift, right by the entrance to the next corridor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"504","x":0.428460991,"y":0.81059547,"cat":"Talismans","group":"Equipment","title":"Spelldrake Talisman","desc":"Talisman. Acquired by defeating the <a href='https://eldenring.wiki.fextralife.com/Runebear' target=\"_blank\">Runebear</a> boss inside <a href='https://eldenring.wiki.fextralife.com/Earthbore+Cave' target=\"_blank\">Earthbore Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"3016","x":0.419235999,"y":0.810778591,"cat":"Spells","group":"Equipment","title":"Crystal Burst","desc":"Drops from the Demi-Human Queen mini-boss in the <a href='https://eldenring.wiki.fextralife.com/Demi-Human Forest Ruins' target=\"_blank\"> Demi-Human Forest Ruins</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cyanspell.png?h=40"},{"id":"6953","x":0.438553339,"y":0.811022753,"cat":"Consumables","group":"Items","title":"Pickled Turtle Neck - 3x Earthbore Cave","desc":"Found in the chest just inside <a href='https://eldenring.wiki.fextralife.com/Earthbore+Cave' target=\"_blank\">Earthbore Cave</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6706","x":0.423327913,"y":0.81181628,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Demi-human+Forest+Ruins' target=\"_blank\">Demi-human Forest Ruins</a> nearby a broekn stone wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6705","x":0.431352286,"y":0.812029923,"cat":"Crafting Materials","group":"Items","title":"String - Earthbore Cave","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Earthbore+Cave' target=\"_blank\">Earthbore Cave</a> on some dead bodies","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"495","x":0.463819246,"y":0.812090964,"cat":"Locations","group":"Locations","title":"Impaler's Catacombs","desc":"Mini-dungeon. The entrance can be found by following the cliffside on the eastern edge of <a href='https://eldenring.wiki.fextralife.com/Weeping+Peninsula' target=\"_blank\">Weeping Peninsula</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"6651","x":0.460829427,"y":0.812182523,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [1] - 3x Impaler's Catacombs","desc":"Spirit Ash Upgrade Material. The first is found on top of a sarcophagus in the room to the left of the boss door. A second one can be found in the second section of the sewers with Zombies, after dropping down underneath the Impaler Lift and one more can be found in the third section before climbing up the ladder.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"727","x":0.422594735,"y":0.812243563,"cat":"Locations","group":"Locations","title":"Demi-human Forest Ruins","desc":"Demi-Humans congregate here to worship their queen. Defeating her will reward players with the Demi-Human Queen's Staff, which is excellent for beginner mages.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"1881","x":0.471152226,"y":0.812518247,"cat":"Spirit Ashes","group":"Equipment","title":"Demi-Human Ashes","desc":"Found within <a href='https://eldenring.wiki.fextralife.com/Impaler's+Catacombs' target=\"_blank\"> Impaler's Catacombs</a>. Dropped by <a href='https://eldenring.wiki.fextralife.com/Erdtree+Burial+Watchdog' target=\"_blank\">Erdtree Burial Watchdog</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"718","x":0.443710301,"y":0.812731887,"cat":"Locations","group":"Locations","title":"Forest Lookout Tower","desc":"Easily found not very far from the bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tower.png?h=40"},{"id":"8179","x":0.428796709,"y":0.812731887,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Earthbore Cave","desc":"Summoning Pool Effigy found along the winding tunnel after the Earthbore Cave site of grace in the Weeping Peninsula (after avoiding the crumbling floor trap). Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6703","x":0.43370246,"y":0.81276241,"cat":"Crafting Materials","group":"Items","title":"Glowstone - Earthbore Cave","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Earthbore+Cave' target=\"_blank\">Earthbore Cave</a> on a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"506","x":0.436416786,"y":0.812884491,"cat":"Consumables","group":"Items","title":"Rainbow Stone (B)","desc":"Consumable. Found on a corpse among some sacks and wooden objects.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3013","x":0.445175704,"y":0.813464374,"cat":"Weapons","group":"Equipment","title":"Hand Ballista","desc":"At the top of the Forest Lookout Tower, west of the Bridge of Sacrifice.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ballista.png?h=40"},{"id":"6691","x":0.45664919,"y":0.814227382,"cat":"Crafting Materials","group":"Items","title":"Sanctuary Stone","desc":"You can find one on top of the destroyed bridge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6652","x":0.461256603,"y":0.814624143,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [2] - 3x Impaler's Catacombs","desc":"Spirit Ash Upgrade Material. The first is found in a dead end room with two statues and a sarcophagus. A second one can be found in the first section of the sewers with Zombies after dropping down underneath the impaler lift. A final one can be found in the corridor after pulling the boss door's lever.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"6436","x":0.448444333,"y":0.814868305,"cat":"Consumables","group":"Items","title":"Golden Rune [1]","desc":"Loot the dead bodies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6434","x":0.383462039,"y":0.814898827,"cat":"Consumables","group":"Items","title":"Golden Rune [2]","desc":"Found on a dead body by the sea.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"503","x":0.432359563,"y":0.815173508,"cat":"Bosses","group":"Characters","title":"Runebear","desc":"Optional Miniboss. Found in the lower level of <a href='https://eldenring.wiki.fextralife.com/Earthbore+Cave' target=\"_blank\">Earthbore Cave</a> after leaping down into a hole near the end. Drops the <a href='https://eldenring.wiki.fextralife.com/Spelldrake+Talisman'>Spelldrake Talisman</a>upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6702","x":0.438645,"y":0.815173508,"cat":"Crafting Materials","group":"Items","title":"Rainbow Stone","desc":"Can be found on a dead body nerby to the campfire.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3020","x":0.417589701,"y":0.81541767,"cat":"Shields","group":"Equipment","title":"Shield of the Guilty","desc":"In the cellar area of the <a href='https://eldenring.wiki.fextralife.com/Demi-Human Forest Ruins' target=\"_blank\"> Demi-Human Forest Ruins</a>, before the main building with the Demi-Human Queen mini-boss. You will need to jump over a wall to access the stairs leading into the cellar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-smallshield.png?h=40"},{"id":"729","x":0.466723696,"y":0.815600792,"cat":"Sites of Grace","group":"Locations","title":"Impaler's Catacombs","desc":"Site of Grace found within the <a href='https://eldenring.wiki.fextralife.com/Impaler's+Catacombs' target=\"_blank\">Impaler's Catacombs</a>, near the entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3877","x":0.396077147,"y":0.815936516,"cat":"Weapons","group":"Equipment","title":"Winged Scythe","desc":"Located In the center of <a href='https://eldenring.wiki.fextralife.com/Tombsward+Ruins' target=\"_blank\">Tombsward Ruins</a>, there is a set of stairs leading underground into a dark hall with a door to a small room at the end. The scythe is inside a chest in the small room.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-reaper.png?h=40"},{"id":"1205","x":0.463452579,"y":0.816028075,"cat":"Bosses","group":"Characters","title":"Erdtree Burial Watchdog (Impaler's Catacombs)","desc":"Found within Impaler's Catacombs. Drops <a href='https://eldenring.wiki.fextralife.com/Demi-Human+Ashes' target=\"_blank\"> Demi-Human Ashes</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"6658","x":0.459822084,"y":0.816028075,"cat":"Key Items","group":"Items","title":"Prattling Pate (Please Help)","desc":"Found within <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/impaler's+catacombs'>Impaler's Catacombs</a>, held by a corpse in the water underneath the spikes trap.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"518","x":0.408619287,"y":0.816302759,"cat":"Key Items","group":"Items","title":"Prattling Pate (Thank You)","desc":"Reusable Item. Obtained inside the <a href='https://eldenring.wiki.fextralife.com/Tombsward+Catacombs' target=\"_blank\">Tombsward Catacombs</a>. Found on a corpse at the end of the main path, past the flamethrowing pillar.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"782","x":0.39397197,"y":0.816730042,"cat":"Locations","group":"Locations","title":"Tombsward Ruins","desc":"The ruins of a former burial ground.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"2501","x":0.405137575,"y":0.817004723,"cat":"Spirit Ashes","group":"Equipment","title":"Lhutel the Headless","desc":"Dropped by the <a href='https://eldenring.wiki.fextralife.com/Cemetery+Shade' target=\"_blank\"> Cemetery Shade</a> inside the <a href/(\"/Tombsward+Catacombs>Tombsward Catacombs</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spiritash.png?h=40"},{"id":"8178","x":0.46227145,"y":0.818072934,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Impaler's Catacombs","desc":"Summoning Pool Effigy found in front of the Boss Doors of the Impaler's Catacombs in the Weeping Peninsula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"8177","x":0.408714604,"y":0.818103452,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Tombsward Catacombs","desc":"Summoning Pool Effigy found in front of Boss Doors of the Tombsward Catacombs at the Weeping Peninsula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"6675","x":0.395620122,"y":0.818133974,"cat":"Crafting Materials","group":"Items","title":"Beast Liver","desc":"Can be found on a dead body in the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"10206","x":0.418719199,"y":0.818152566,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Demi-human Forest Ruins","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank\">Torrent</a>. Found in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Weeping+Peninsula' target=\"\">Weeping Peninsula</a>, south <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Demi-human+Forest+Ruins' target=\"blank\">Demi-human Forest Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"1204","x":0.406482667,"y":0.818500217,"cat":"Bosses","group":"Characters","title":"Cemetery Shade","desc":"Found inside <a href='https://eldenring.wiki.fextralife.com/Tombsward+Catacombs' target=\"_blank\"> Tombsward Catacombs</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Lhutel+the+Headless' target=\"_blank\"> Lhutel the Headless</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"829","x":0.385306139,"y":0.819354784,"cat":"Bosses","group":"Characters","title":"Ancient Hero of Zamor","desc":"Optional Boss imprisoned within the <a href='https://eldenring.wiki.fextralife.com/Weeping+Evergaol'>Weeping Evergaol</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6704","x":0.428941353,"y":0.819476865,"cat":"Crafting Materials","group":"Items","title":"Gold-Tinged Excrement","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Earthbore+Cave' target=\"_blank\">Earthbore Cave</a> on some dead bodies","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"516","x":0.412622628,"y":0.819690505,"cat":"Key Items","group":"Items","title":"Nomadic Warrior's Cookbook [9]","desc":"Cookbook item. Found inside the <a href='https://eldenring.wiki.fextralife.com/Tombsward+Catacombs' target=\"_blank\">Tombsward Catacombs</a>, locked behind an imp statue barrier. Requires a <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a> to break the seal.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"515","x":0.405267331,"y":0.820056748,"cat":"Sites of Grace","group":"Locations","title":"Tombsward Catacombs","desc":"Site of Grace found inside the <a href='https://eldenring.wiki.fextralife.com/Tombsward+Catacombs' target=\"_blank\">Tombsward Catacombs</a>, a few steps from the entrance.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"785","x":0.389396975,"y":0.820300911,"cat":"Spells","group":"Equipment","title":"Divine Fortification","desc":"<a href='https://eldenring.wiki.fextralife.com/Incantations' target=\"_blank\">Incantation</a>. Dropped by a <a href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab' target=\"_blank\">Teardrop Scarab</a> found atop a collapsed stone structure overgrown with yellow moss.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"815","x":0.384451244,"y":0.820789234,"cat":"Locations","group":"Locations","title":"Weeping Evergaol","desc":"Evergaol imprisoning the <a href='https://eldenring.wiki.fextralife.com/Ancient+Hero+of+Zamor' target=\"_blank\">Ancient Hero of Zamor</a> boss. Requires a <a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a> to unlock the portal mechanism.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-evergaol.png?h=40"},{"id":"514","x":0.409900288,"y":0.820941837,"cat":"Locations","group":"Locations","title":"Tombsward Catacombs","desc":"A hidden mini-dungeon. The entrance can be found behind a leaning pillar on the side of the mountain.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-catacomb.png?h=40"},{"id":"6656","x":0.403307325,"y":0.821094437,"cat":"Upgrade Materials","group":"Items","title":"Ghost Glovewort [1] - Tombsward Catacombs","desc":"Spirit Ash Upgrade Material. One found in the bottom level of the first room with a second floor, near the back.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"6654","x":0.406605232,"y":0.821430161,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [1] - 2x Tombsward Catacombs","desc":"Spirit Ash Upgrade Material. One found in the room to the right of the boss door. A second one is found near a sarcophagus on the bottom level of the first room with a second floor.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"6690","x":0.450821243,"y":0.821887963,"cat":"Crafting Materials","group":"Items","title":"Strip of White Flesh","desc":"Can be found on a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2455","x":0.379684559,"y":0.822284729,"cat":"Talismans","group":"Equipment","title":"Radagon's Scarseal","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Ancient+Hero+of+Zamor' target=\"_blank\"> Ancient Hero of Zamor</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"6655","x":0.404957158,"y":0.822620449,"cat":"Upgrade Materials","group":"Items","title":"Grave Glovewort [2] - 3x Tombsward Catacombs","desc":"Spirit Ash Upgrade Material. One found in the room to the right of the boss door, behind the central column. A second one is found in the room to the left of the flamethrower pillar. A third one is found in a room on the upper level after riding the flamethrower pillar and before the room with the boss door's lever.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-glovewort.png?h=40"},{"id":"816","x":0.377677254,"y":0.823475016,"cat":"Locations","group":"Locations","title":"Fourth Church of Marika","desc":"An abandoned church on a plateau in the western landmass of the peninsula.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"508","x":0.442278683,"y":0.824085421,"cat":"Sites of Grace","group":"Locations","title":"South of the Lookout Tower","desc":"Site of Grace found directly south of the <a href='https://eldenring.wiki.fextralife.com/Forest+Lookout+Tower' target=\"_blank\">Forest Lookout Tower</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"817","x":0.374870954,"y":0.824176984,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (Fourth Church of Marika)","desc":"Flask Upgrade Material. Found on the ground in front of the altar at the <a href='https://eldenring.wiki.fextralife.com/Fourth+Church+of+Marika' target=\"_blank\">Fourth Church of Marika</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"5725","x":0.428484727,"y":0.824390624,"cat":"Weapons","group":"Equipment","title":"Bloodstained Dagger","desc":"Dropped by Demihuman chief/Demihuman assassin sleeping before the wooden bridge leading to the minor eldtree in the weeping peninsula.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-dagger.png?h=40"},{"id":"724","x":0.462817148,"y":0.82506207,"cat":"Sites of Grace","group":"Locations","title":"Beside the Crater-Pocked Glade","desc":"Site of Grace found near a forested area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"472","x":0.4490814,"y":0.825092592,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2]","desc":"Upgrade Material. Found in a corpse in the middle of the road, near the group of enemies scavenging the broken cart.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"5419","x":0.437975374,"y":0.825428313,"cat":"Sites of Grace","group":"Locations","title":"Ailing Village Outskirts","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6435","x":0.426830841,"y":0.825489353,"cat":"Consumables","group":"Items","title":"Golden Rune [2]","desc":"Found by the side of the road on a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"470","x":0.453293634,"y":0.825611434,"cat":"Weapons","group":"Equipment","title":"Morning Star","desc":"Hammer-type Weapon. Found in a chest inside a broken wagon along the road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-hammer.png?h=40"},{"id":"8828","x":0.413994549,"y":0.825672475,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Minor Erdtree Weeping Peninsula","desc":"Summoning Pool Effigy found the grass just southwest of the Stake of Marika. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"3245","x":0.383352555,"y":0.825977677,"cat":"Talismans","group":"Equipment","title":"Viridian Amber Medallion","desc":"Viridian Amber Medallion Raises maximum stamina. It is dropped by Miranda the Blighted Bloom, found inside the Tombsward Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"818","x":0.375108858,"y":0.826435483,"cat":"Sites of Grace","group":"Locations","title":"Fourth Church of Marika","desc":"Site of Grace found within the <a href='https://eldenring.wiki.fextralife.com/Fourth+Church+of+Marika' target=\"_blank\">Fourth Church of Marika</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3023","x":0.405018276,"y":0.826557564,"cat":"Shields","group":"Equipment","title":"Eclipse Crest Heater Shield","desc":"Ledge of the pillar near Tombsward Site of Grace. Can be reached from the ledge near Minor Erdtree","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"10207","x":0.42448822,"y":0.826565545,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Minor Erdtree Weeping Peninsula","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank\">Torrent</a>. Found in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Weeping+Peninsula' target=\"blank\">Weeping Peninsula</a>, east of the Minor Erdtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"2878","x":0.380026295,"y":0.826801726,"cat":"Weapons","group":"Equipment","title":"Lordsworn's Straight Sword (B)","desc":"Dropped by a head-less, undead Soldier at Fourth Church of Marika.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-straightsword.png?h=40"},{"id":"6689","x":0.444015163,"y":0.827351091,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found in the pond.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6674","x":0.384392238,"y":0.827412131,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily - 5x Tombsward Cave","desc":"Can be found x5 Trina's Lily at <a href='https://eldenring.wiki.fextralife.com/Tombsward+Cave' target=\"_blank\">Tombsward Cave</a> area, In the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"471","x":0.449939807,"y":0.827961496,"cat":"Consumables","group":"Items","title":"Golden Rune [2] (A)","desc":"Consumable. Found on a corpse along the road.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"716","x":0.411211036,"y":0.827961496,"cat":"Flask Upgrades","group":"Items","title":"Crimsonburst Crystal Tear","desc":"Crystal Tear for the Flask of Wondrous Physick. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Erdtree+Avatar' target=\"_blank\">Erdtree Avatar</a> boss upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"3510","x":0.382224017,"y":0.828175135,"cat":"Bosses","group":"Characters","title":"Miranda the Blighted Bloom","desc":"Miranda the Blighted Bloom is a large, poisonous flower within the Tombsward Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"3905","x":0.422710652,"y":0.828297216,"cat":"Consumables","group":"Items","title":"Large Glintstone Scrap - 2x Morne Tunnel","desc":"Two can be looted off a corpse behind the small shack in <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6673","x":0.387566311,"y":0.82851086,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"Can be found x3 Trina's Lily near to <a href='https://eldenring.wiki.fextralife.com/Tombsward+Cave' target=\"_blank\">Tombsward Cave</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6952","x":0.449298889,"y":0.829090743,"cat":"Consumables","group":"Items","title":"Rainbow Stone - 5x Weeping Peninsula","desc":"Can be found at the foot at the cruficix.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3904","x":0.424511327,"y":0.829304387,"cat":"Consumables","group":"Items","title":"Stanching Boluses - 1x Morne Tunnel","desc":"One can be looted off a corpse in <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"715","x":0.408710847,"y":0.829365427,"cat":"Flask Upgrades","group":"Items","title":"Opaline Bubbletear","desc":"Crystal Tear for the Flask of Wondrous Physick. Dropped by the <a href='https://eldenring.wiki.fextralife.com/Erdtree+Avatar' target=\"_blank\">Erdtree Avatar</a> boss upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crystal-tears.png?h=40"},{"id":"2327","x":0.420549547,"y":0.829518027,"cat":"Weapons","group":"Equipment","title":"Rusted Anchor","desc":"Greataxe dropped by <a href='https://eldenring.wiki.fextralife.com/Scaly+Misbegotten' target=\"_blank\">Scaly Misbegotten</a> located in <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greataxe.png?h=40"},{"id":"3201","x":0.384878357,"y":0.829518027,"cat":"Locations","group":"Locations","title":"Tombsward Cave","desc":"Tombsward Cave is an optional dungeon in Elden Ring. You'll come across a poisonous swamp once you reach deeper within the cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cave.png?h=40"},{"id":"6003","x":0.373436372,"y":0.829975832,"cat":"Spells","group":"Equipment","title":"Ambush Shard","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Weeping+Peninsula'>Weeping Peninsula</a>: Found on a corpse in the underground jail of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Witchbane+Ruins'>Witchbane Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bluespell.png?h=40"},{"id":"3901","x":0.423357699,"y":0.830342075,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf - 2x Morne Tunnel","desc":"Two can be looted off a corpse that is being eaten by two Misbegotten enemies in <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3892","x":0.3769743,"y":0.830555716,"cat":"Weapons","group":"Equipment","title":"Spiked Spear","desc":"Chance for it to drop from a <a href='https://eldenring.wiki.fextralife.com/Marionette+Soldier' target=\"_blank\">Marionette Soldier</a> enemy just outside of <a href='https://eldenring.wiki.fextralife.com/Witchbane+Ruins' target=\"_blank\">Witchbane Ruins</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spear.png?h=40"},{"id":"6676","x":0.413805925,"y":0.830555716,"cat":"Crafting Materials","group":"Items","title":"Tarnished Golden Sunflower 10x","desc":"Can be found x10 Tarnished Golden Sunflower araund the Erdtree.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6433","x":0.363471495,"y":0.830586237,"cat":"Consumables","group":"Items","title":"Golden Rune [1]","desc":"Found on a dead body.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"8176","x":0.382072194,"y":0.830647278,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Tombsward Cave","desc":"Summoning Pool Effigy found next to the Tombsward Cave site of grace at the Weeping Peninsula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"2552","x":0.428426081,"y":0.830799877,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf 4x","desc":"4x Arteria Leaf on the west side of <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/ailing+village'>Ailing Village</a>, behind the cabins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3524","x":0.388467307,"y":0.830830399,"cat":"Consumables","group":"Items","title":"Poisonbone Dart","desc":"An offensive consumable that can be found on a corpse inside Tombsward Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"712","x":0.412499075,"y":0.83089144,"cat":"Bosses","group":"Characters","title":"Erdtree Avatar","desc":"Miniboss found guarding the Erdtree. Drops the <a href='https://eldenring.wiki.fextralife.com/Opaline+Bubbletear' target=\"_blank\">Opaline Bubbletear</a> and <a href='https://eldenring.wiki.fextralife.com/Crimsonburst+Crystal+Tear' target=\"_blank\">Crimsonburst Crystal Tear</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"6688","x":0.451644434,"y":0.831135602,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found on a ledge nearby the stone ruin.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"2326","x":0.424951197,"y":0.831196642,"cat":"Bosses","group":"Characters","title":"Scaly Misbegotten","desc":"Optional Boss, found within <a href='https://eldenring.wiki.fextralife.com/Mourne+Tunnel' target=\"_blank\">Mourne Tunnel</a>. Drops <a href='https://eldenring.wiki.fextralife.com/Rusted+Anchor'> Rusted Anchor</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-boss.png?h=40"},{"id":"2551","x":0.436479752,"y":0.831349242,"cat":"Shields","group":"Equipment","title":"Flame Crest Wooden Shield","desc":"You can loot the Flame Crest Wooden Shield from a naked commoner's corpse inside one of the cabins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shield.png?h=40"},{"id":"480","x":0.433366153,"y":0.831440804,"cat":"Locations","group":"Locations","title":"Ailing Village","desc":"A small, abandoned village inhabited only by its <a href='https://eldenring.wiki.fextralife.com/Frenzied+Villager' target=\"_blank\">Frenzied Villagers</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-town.png?h=40"},{"id":"3896","x":0.422322097,"y":0.831837566,"cat":"Crafting Materials","group":"Items","title":"Cracked Crystal - 1x Morne Tunnel","desc":"One can be looted off a Miner enemy on the left side of the small shack in <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"826","x":0.375968557,"y":0.831959647,"cat":"Locations","group":"Locations","title":"Witchbane Ruins","desc":"Ruins found south of the Fourth Church of Marika. Teeming with hostiles.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ruins.png?h=40"},{"id":"6462","x":0.372520784,"y":0.83238693,"cat":"NPCs","group":"Characters","title":"Witch-Hunter Jerren (Second Location)","desc":"<p>Witch-Hunter Jerren appears here while progressing through the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Sorceress+Sellen' target=\"\">Sorceress Sellen</a> questline. He may be first encountered in <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Castle+Redmane' target=\"\">Castle Redmane</a> after the defeat of <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Starscourge+Radahn' target=\"\">Starscourge Radahn</a>.</p>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3530","x":0.382586236,"y":0.832539534,"cat":"Sites of Grace","group":"Locations","title":"Tombsward Cave (Site of Grace)","desc":"Site of Grace can be found once you enter the Tombsward Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3525","x":0.387743667,"y":0.832661615,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy H","desc":"Can be looted off from a corpse once you head straight inside the Tombsward Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"6672","x":0.378318235,"y":0.832753173,"cat":"Crafting Materials","group":"Items","title":"Poisonbloom - 5x","desc":"Can be found 5 Poisonbloom at <a href='https://eldenring.wiki.fextralife.com/Witchbane+Ruins' target=\"_blank\">Witchbane Ruins</a> Around the ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3529","x":0.385485194,"y":0.832783696,"cat":"Key Items","group":"Items","title":"Nomadic Warrior's Cookbook [8]","desc":"Can be found on a corpse within the Tombsward Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-cookbook.png?h=40"},{"id":"2916","x":0.37105583,"y":0.832875254,"cat":"NPCs","group":"Characters","title":"Sorceress Sellen (Second Location)","desc":"Sorceress Sellen alternative location.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"3898","x":0.427258118,"y":0.832936295,"cat":"Consumables","group":"Items","title":"Golden Rune [4] - 1x Morne Tunnel","desc":"One can be looted off a corpse inside the small shack in <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3894","x":0.423211562,"y":0.833119417,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] - 9x Morne Tunnel","desc":"You can find a couple of these stones within <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"473","x":0.447586024,"y":0.833394101,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Mighty Shot","desc":"Ash of War Upgrade. Dropped by a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab'>Teardrop Scarab</a> found along the road as it slopes upwards.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"8300","x":0.368919422,"y":0.833394101,"cat":"Armor","group":"Equipment","title":"Witch's Glintstone Crown","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Sorceress+Sellen'>Sorceress Sellen</a>, by completing her questline and after defeating her.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-helmet.png?h=40"},{"id":"3895","x":0.42531108,"y":0.833516182,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [1] - 3x Morne Tunnel","desc":"You can find a few in <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"3570","x":0.431561427,"y":0.834126587,"cat":"Consumables","group":"Items","title":"Golden Rune [1] - Ailing Village","desc":"Can be found inside the abandoned <a href='https://eldenring.wiki.fextralife.com/Ailing+Village' target=\"_blank\">Ailing Village.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"819","x":0.402057637,"y":0.834248668,"cat":"Sites of Grace","group":"Locations","title":"Tombsward","desc":"Site of Grace found west of the Minor Erdtree, at the base of the plateau.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"726","x":0.462385758,"y":0.834340227,"cat":"Key Items","group":"Items","title":"Memory Stone - Oridys's Rise","desc":"Memory Upgrade Material. Found in a chest at the top floor of <a href='https://eldenring.wiki.fextralife.com/Oridys's+Rise' target=\"_blank\">Oridys's Rise</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-specialtoolitem.png?h=40"},{"id":"483","x":0.437091998,"y":0.834370749,"cat":"Spells","group":"Equipment","title":"The Flame of Frenzy","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Incantations'>Incantation</a>. Found on a corpse by one of the pillars on the left side of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Callu+Baptismal+Church'>Callu Baptismal Church</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"3522","x":0.385201678,"y":0.834462308,"cat":"Consumables","group":"Items","title":"Golden Rune [2] (D)","desc":"Can be looted off of defeated Rats within the Tombsward Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2919","x":0.356848676,"y":0.834614911,"cat":"Consumables","group":"Items","title":"Golden Rune [5] B","desc":"Found at the shore surrounded by <a target=\"blank\" href='https://eldenring.wiki.fextralife.com/skeleton'>Skeleton</a> enemies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3884","x":0.423266205,"y":0.835103235,"cat":"Sites of Grace","group":"Locations","title":"Morne Tunnel","desc":"Located at Underground Level 1 of <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"3897","x":0.42670876,"y":0.835103235,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - 1x Morne Tunnel","desc":"One can be looted off a corpse sitting in between some crates and barrels in <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3899","x":0.419783009,"y":0.835316875,"cat":"Consumables","group":"Items","title":"Soft Cotton - 1x Morne Tunnel","desc":"One can be looted off a corpse in <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6679","x":0.437241114,"y":0.835561037,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf 4x","desc":"Can be found x4 Arteria Leaf at <a href='https://eldenring.wiki.fextralife.com/Callu+Baptismal+Church' target=\"_blank\">Callu Baptismal Church</a>, Near a tree to the east of the building.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"8180","x":0.421594008,"y":0.835561037,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Morne Tunnel","desc":"Summoning Pool Effigy found next to the Morne Tunnel site of grace in the Weeping Peninsula. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"463","x":0.413562667,"y":0.83598832,"cat":"Locations","group":"Locations","title":"Minor Erdtree (Weeping Peninsula)","desc":"","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tree.png?h=40"},{"id":"2318","x":0.4255548,"y":0.836415604,"cat":"Locations","group":"Locations","title":"Morne Tunnel","desc":"Morne Tunnel can be found in Weeping Peninsula. To reach it jump down towards the bottom of the canyon next to Ailing Village in Weeping Peninsula.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tunnel.png?h=40"},{"id":"3523","x":0.387032869,"y":0.836812369,"cat":"Consumables","group":"Items","title":"Golden Rune [3] E","desc":"Can be looted off of defeated Giant Rats within the Tombsward Cave.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"725","x":0.461592164,"y":0.837239653,"cat":"Locations","group":"Locations","title":"Oridys's Rise","desc":"Lookout Tower. Initially sealed by a barrier. Inspecting the statue at the entrance, you are asked to \"seek three wise beasts\". These can be found as Ghostly Tortoises that you need to attack. The first is just a few steps directly to the north, opposite the entrance. There is another one hiding in the bushes left of the steps leading up to the tower. The last one is found in a pond slightly west of the tower and is invisible until struck. Attack near the center of the pond to reveal the Tortoise. Once all three have been defeated, the tower's seal is broken.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-fieldtower.png?h=40"},{"id":"8002","x":0.421550895,"y":0.837544855,"cat":"Consumables","group":"Items","title":"Exalted Flesh - 1x Morne Tunnel","desc":"Consumable Item. Looted from a chest inside a shack within Morne Tunnel.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"482","x":0.434556551,"y":0.837789017,"cat":"Locations","group":"Locations","title":"Callu Baptismal Church","desc":"Church ruins found just south of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Ailing+Village'>Ailing Village</a>. Inhabited by a lot of rats and one giant rat monster.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-church.png?h=40"},{"id":"10208","x":0.45377721,"y":0.83815526,"cat":"Spiritsprings","group":"Locations","title":"Spiritspring: Castle Morne Rampart","desc":"Spiritspring Jump for <a href='https://eldenring.wiki.fextralife.com/Torrent+(Spirit+Steed)' target=\"blank\">Torrent</a>. Found in the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Weeping+Peninsula' target=\"\">Weeping Peninsula</a>, just east of the <a class=\"wiki_link\" title=\"\" href='https://eldenring.wiki.fextralife.com/Castle+Morne' target=\"blank\">Castle Morne</a> Rampart Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-spirit_spring.png?h=40"},{"id":"6951","x":0.467671878,"y":0.838460463,"cat":"Consumables","group":"Items","title":"Starlight Shards - Weeping Peninsula","desc":"Can be found on an altar, by the cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"4144","x":0.384145918,"y":0.838490981,"cat":"Locations","group":"Locations","title":"Walking Mausoleum (Weeping Peninsula)","desc":"Attack the white spots on the legs to get it to come down and access the mausoleum.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-walking-mausoleum.png?h=40"},{"id":"6680","x":0.436418243,"y":0.838857224,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf 4x","desc":"Can be found 4x Arteria Leaf at <a href='https://eldenring.wiki.fextralife.com/Callu+Baptismal+Church' target=\"_blank\">Callu Baptismal Church</a>, on the slope going upwards beside the town.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"474","x":0.449724104,"y":0.839162427,"cat":"Sites of Grace","group":"Locations","title":"Castle Morne Rampart","desc":"Site of Grace found near a campfire.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"6678","x":0.425279958,"y":0.839833872,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Morne+Tunnel' target=\"_blank\">Morne Tunnel</a>, You'll notice there are is a corpse being eaten by two Misbegotten enemies. Loot that body to find x2 Arteria Leaf.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6687","x":0.460676151,"y":0.839864394,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Can be found behind <a href='https://eldenring.wiki.fextralife.com/Oridys's+Rise' target=\"_blank\">Oridys's Rise</a> nearby the pond.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"720","x":0.422173886,"y":0.840078034,"cat":"Spells","group":"Equipment","title":"Lightning Strike","desc":"<a href='https://eldenring.wiki.fextralife.com/Incantations' target=\"_blank\">Incantation</a>. Dropped by a <a href=\"Teardrop+Scarab\" target=\"_blank\">Teardrop Scarab</a> in the lower section of the crevasse. When approaching from either the eastern or western cliffs, look for stone platforms jutting out of the cliffside to safely descend to the area. Beware as the area is constantly being pummeled by lightning and there are several Giant bats guarding the scarab as well.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"6432","x":0.40214023,"y":0.840078034,"cat":"Consumables","group":"Items","title":"Golden Rune [1]","desc":"Found at the top of the ruined structure.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"484","x":0.436874943,"y":0.840291678,"cat":"Flask Upgrades","group":"Items","title":"Sacred Tear (Callu Baptismal Church)","desc":"Flask Upgrade Material. Found on the ground in front of the altar at the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Callu+Baptismal+Church'>Callu Baptismal Church</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-sacred-tear.png?h=40"},{"id":"722","x":0.445484975,"y":0.840383237,"cat":"Bosses","group":"Characters","title":"Night's Cavalry (Weeping Peninsula)","desc":"<a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> Miniboss found patrolling the roads around the Castle Morne Ramparts. Only appears at night. Drops <a href='https://eldenring.wiki.fextralife.com/Ash+of+War:+Barricade+Shield' target=\"_blank\">Ash of War: Barricade Shield</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"1758","x":0.447677584,"y":0.841115723,"cat":"Ashes of War","group":"Equipment","title":"Ash of War: Barricade Shield","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\">Night's Cavalry</a> Miniboss found patrolling the roads around the Castle Morne Ramparts. Only appears at night.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-ashofwar.png?h=40"},{"id":"1977","x":0.445601427,"y":0.841787168,"cat":"Weapons","group":"Equipment","title":"Nightrider Flail","desc":"Dropped by <a href='https://eldenring.wiki.fextralife.com/Night's+Cavalry' target=\"_blank\"> Night's Cavalry</a> that spawns at night near Castle Morne Rampart Site of Grace.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-flail.png?h=40"},{"id":"475","x":0.450423614,"y":0.841817691,"cat":"NPCs","group":"Characters","title":"Nomadic Merchant Castle Morne Rampart","desc":"Nomadic Merchant. General Goods vendor found sitting by a campfire near the Castle Morne Rampart site of grace. Sells <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Stonesword+Key'>Stonesword Key</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"723","x":0.455494433,"y":0.841909249,"cat":"Consumables","group":"Items","title":"Warming Stone","desc":"Consumable Item. 2 can be found on a corpse atop the eastern-most tower of the Castle Morne Ramparts. This area can be reached by using Torrent to jump from the Spiritspring located just east of the Site of Grace nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6056","x":0.453108251,"y":0.842153411,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1]","desc":"In a corpse at the water on the corner.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"721","x":0.453932662,"y":0.8431911,"cat":"Shields","group":"Equipment","title":"Great Turtle Shell","desc":"Small Shield. Found on a corpse atop the eastern-most tower of the Castle Morne Ramparts. This area can be reached by using Torrent to jump from the Spiritspring located just east of the Site of Grace nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-smallshield.png?h=40"},{"id":"824","x":0.371482518,"y":0.843313181,"cat":"NPCs","group":"Characters","title":"Isolated Merchant","desc":"General Goods vendor found sitting in his shack. Sells the <a href='https://eldenring.wiki.fextralife.com/Lantern' target=\"_blank\">Lantern</a> and <a href='https://eldenring.wiki.fextralife.com/Lost+Ashes+of+War'>Lost Ashes of War</a>, among other useful items.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-merchant.png?h=40"},{"id":"6681","x":0.428576014,"y":0.843801505,"cat":"Crafting Materials","group":"Items","title":"Eye of Yelough","desc":"Can be found in <a href='https://eldenring.wiki.fextralife.com/Ailing+Village' target=\"_blank\">Ailing Village</a> and <a href='https://eldenring.wiki.fextralife.com/Callu+Baptismal+Church' target=\"_blank\">Callu Baptismal Church</a> within the <a href='https://eldenring.wiki.fextralife.com/Weeping+Peninsula' target=\"_blank\">Weeping Peninsula</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"822","x":0.368492699,"y":0.844930756,"cat":"Sites of Grace","group":"Locations","title":"Isolated Merchant's Shack (Weeping Peninsula)","desc":"Site of Grace outside the <a href='https://eldenring.wiki.fextralife.com/Isolated+Merchant'>Isolated Merchant</a>'s Shack.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"823","x":0.37090155,"y":0.84551064,"cat":"Locations","group":"Locations","title":"Isolated Merchant's Shack (Weeping Peninsula)","desc":"A wooden hut far to the west of the Weeping Peninsula.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-shack.png?h=40"},{"id":"6682","x":0.428789752,"y":0.84563272,"cat":"Crafting Materials","group":"Items","title":"Yellow Ember","desc":"Can be found near to <a href='https://eldenring.wiki.fextralife.com/Callu+Baptismal+Church' target=\"_blank\">Callu Baptismal Church</a> on a dead body in front of the tent.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"717","x":0.410533207,"y":0.845907404,"cat":"Consumables","group":"Items","title":"Golden Rune [6] (A)","desc":"Consumable item. Dropped by an elite singing Bat enemy found along the cliffs south of the Minor Erdtree. You can hear the bat singing as you approach the cliffs. He is guarded by other Giant Bats.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6677","x":0.412463536,"y":0.846029485,"cat":"Crafting Materials","group":"Items","title":"Sliver of Meat","desc":"Crafting Material. Found on a corpse where a singing Bat is sitting.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6670","x":0.399617117,"y":0.849447754,"cat":"Crafting Materials","group":"Items","title":"Gold Firefly","desc":"Can be found some at <a href='https://eldenring.wiki.fextralife.com/Tower+of+Return' target=\"_blank\">Tower of Return</a> area in the water pond.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6669","x":0.395436595,"y":0.854392035,"cat":"Crafting Materials","group":"Items","title":"Great Dragonfly Head","desc":"A Great Dragonfly Head can be found on the ground by one of the effigies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"4470","x":0.433608533,"y":0.855399201,"cat":"Bosses","group":"Characters","title":"Deathbird (Weeping Peninsula)","desc":"Spawns only at night, drops the <a href='https://eldenring.wiki.fextralife.com/Sacrificial+Axe' target=\"_blank\">Sacrificial Axe</a>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"},{"id":"4474","x":0.431657659,"y":0.856650534,"cat":"Weapons","group":"Equipment","title":"Sacrificial Axe","desc":"Axe. Dropped from miniboss that only spawns at night: <a href='https://eldenring.wiki.fextralife.com/Deathbird' target=\"_blank\">Deathbird</a> (Weeping Peninsula)","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-axe.png?h=40"},{"id":"2559","x":0.441451855,"y":0.857169376,"cat":"Maps","group":"Locations","title":"Map (Weeping Peninsula)","desc":"Map for all of <a href='https://eldenring.wiki.fextralife.com/Weeping+Peninsula' target=\"_blank\">Weeping Peninsula</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-mapshard.png?h=40"},{"id":"821","x":0.391256832,"y":0.857505101,"cat":"Waygates","group":"Locations","title":"Teleporter Chest to Leyndell","desc":"Teleporter Chest. Found atop the <a href='https://eldenring.wiki.fextralife.com/Tower+of+Return' target=\"_blank\">Tower of Return</a>. Transports you to <a href='https://eldenring.wiki.fextralife.com/Leyndell,+Royal+Capital' target=\"_blank\">Leyndell, Royal Capital</a> upon opening.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-waygate.png?h=40"},{"id":"5961","x":0.438553679,"y":0.85881747,"cat":"Flask Upgrades","group":"Items","title":"Golden Seed - Weeping Peninsula","desc":"Flask Upgrade Material. Found underneath a Phantom Tree up on a ridge southwest of the <strong>Weeping Peninsula Map Fragment</strong>","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-golden-seed.png?h=40"},{"id":"820","x":0.390494454,"y":0.859733077,"cat":"Locations","group":"Locations","title":"Tower of Return","desc":"Dilapidated tower found near the edge of the landmass. Beware the mounted knight and foot soldiers nearby. There is a Transporter Chest at the very top.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-tower.png?h=40"},{"id":"492","x":0.453573275,"y":0.86003828,"cat":"Spells","group":"Equipment","title":"Poison Mist","desc":"<a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Incantations'>Incantation</a>. Dropped by a <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Teardrop+Scarab'>Teardrop Scarab</a> in the forested area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-redspell.png?h=40"},{"id":"6671","x":0.392690058,"y":0.860282442,"cat":"Crafting Materials","group":"Items","title":"Mushroom","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Tower+of+Return' target=\"_blank\">Tower of Return</a> area on a dead body near to the ledge cliff.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6686","x":0.449936862,"y":0.869957364,"cat":"Crafting Materials","group":"Items","title":"Poisonbloom","desc":"Can be found x8 Poisonblom around the poison swampland.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6683","x":0.440596948,"y":0.870140486,"cat":"Crafting Materials","group":"Items","title":"Sanctuary Stone - 3x","desc":"Can fe found inside the Ruins.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"6431","x":0.421555067,"y":0.870415166,"cat":"Consumables","group":"Items","title":"Golden Rune [1]","desc":"Found by the statue.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6430","x":0.449941405,"y":0.871208692,"cat":"Consumables","group":"Items","title":"Golden Rune [4]","desc":"Climb over to the top.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2918","x":0.436419001,"y":0.876305577,"cat":"Weapons","group":"Equipment","title":"Golem Greatbow","desc":"Chance to drop by Golem Archer.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bow.png?h=40"},{"id":"493","x":0.427813398,"y":0.878197832,"cat":"Sites of Grace","group":"Locations","title":"Castle Morne Lift","desc":"Site of Grace found at the entrance of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Castle+Morne'>Castle Morne</a>, before ascending the lift.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"476","x":0.432451452,"y":0.879021877,"cat":"Locations","group":"Locations","title":"Castle Morne","desc":"Optional Dungeon. A large castle on the southern tip of the Weeping Peninsula. The <a href='https://eldenring.wiki.fextralife.com/Leonine+Misbegotten' target=\"_blank\">Leonine Misbegotten</a> boss can be found here.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-castlemourne.png?h=40"},{"id":"3822","x":0.424423938,"y":0.879632282,"cat":"Consumables","group":"Items","title":"Rune Arc - 1x Castle Morne","desc":"Can be looted off a defeated Giant Rat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"2917","x":0.418413373,"y":0.88027321,"cat":"Weapons","group":"Equipment","title":"Misbegotten Shortbow","desc":"There are flying enemies at the top of the castle. Thet may drop this weapon when killed.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-bow.png?h=40"},{"id":"753","x":0.421893346,"y":0.880700493,"cat":"Weapons","group":"Equipment","title":"Claymore","desc":"Greatsword. From the main courtyard entrance, hug the right wall past the burning corpses and harpies to reach the entrance to the building in the north. The sword is found in a chest to the left as you enter.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"8156","x":0.427875504,"y":0.881616101,"cat":"Summoning Pools","group":"Locations","title":"Effigy of the Martyr: Castle Morne","desc":"Summoning Pool Effigy found at the top of the lift going into Castle Morne. Activate this effigy to send your summon sign to this summoning pool.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-summoning-pool.png?h=40"},{"id":"760","x":0.42522002,"y":0.88170766,"cat":"Weapons","group":"Equipment","title":"Steel-Wire Torch","desc":"Torch. Found on a corpse at the end of a narrow path at the top level of the castle. Guarded by two harpies.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-staff.png?h=40"},{"id":"5501","x":0.421954387,"y":0.882104425,"cat":"Weapons","group":"Equipment","title":"Longhaft Axe","desc":"Rare drop from enemies wielding it at Castle Mourne in Weeping Peninsula. There is an easy to kill one from Beside the Rampant Gaol site of grace, cross the bridge and will be on the left sleeping.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greataxe.png?h=40"},{"id":"757","x":0.419995111,"y":0.882409627,"cat":"Key Items","group":"Items","title":"Furlcalling Finger Remedy - 1x Castle Morne","desc":"Multiplayer Item. Found on a corpse to the right of the gallows on the top level on the castle. This area is accessed by hugging the right wall from the main courtyard area, past the burning corpses and harpies and then following the linear path to reach the roof.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-multiplayeritem.png?h=40"},{"id":"3837","x":0.423785582,"y":0.88292847,"cat":"Weapons","group":"Equipment","title":"Iron Cleaver - Castle Morne","desc":"Dropped by one of the Misbegotten creatures attacking a soldier before reaching the top of Castle Morne.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-axe.png?h=40"},{"id":"3831","x":0.430530739,"y":0.883203154,"cat":"Talismans","group":"Equipment","title":"Sacrificial Twig 1x - Castle Morne","desc":"Give the letter to Edgar and he'll give you x1 Sacrificial Twig.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"477","x":0.426562499,"y":0.883294713,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] A - Castle Morne","desc":"Upgrade Material. From the main courtyard entrance of Castle Morne, head up the steps on the left side to find the item on a corpse. Beware the skeletal dogs in the area.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"524","x":0.445511593,"y":0.883447316,"cat":"Crafting Materials","group":"Items","title":"Arteria Leaf","desc":"Near the area of the <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Flying+Dragon+Agheel'>Flying Dragon Agheel</a>. It is surrounded by <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Poison+Pod'>Poison Pods</a>, against a tomb.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"3825","x":0.417345947,"y":0.883874599,"cat":"Crafting Materials","group":"Items","title":"Sanctuary Stone - 1x Castle Morne","desc":"Can be found at Castle Morne, dropped when defeating a Lesser Pumpkin Head.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"1127","x":0.428913216,"y":0.884485005,"cat":"NPCs","group":"Characters","title":"Edgar (First Location)","desc":"Edgar can be found sitting on a bench up on the ramparts of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Castle+Morne'>Castle Morne</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-npc.png?h=40"},{"id":"6429","x":0.426835012,"y":0.884576563,"cat":"Consumables","group":"Items","title":"Golden Rune [2]","desc":"Looted off a corpse by the ledge of the wooden fence.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"737","x":0.418322122,"y":0.884729167,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] B - Castle Morne","desc":"Upgrade Material. Found on a corpse being chopped up by a Misbegotten.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"761","x":0.425675255,"y":0.886102576,"cat":"Consumables","group":"Items","title":"Fire Grease - 2x Castle Morne","desc":"Consumable. 2 can be found on a corpse near the the burning pile of corpses in the courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"741","x":0.414110943,"y":0.886499341,"cat":"Talismans","group":"Equipment","title":"Twinblade Talisman","desc":"Talisman. Found in the tower section of the walls of Castle Morne. Climb up the ladder and go around the tower to find a chest containing the talisman.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-talisman.png?h=40"},{"id":"736","x":0.419693351,"y":0.886682463,"cat":"Consumables","group":"Items","title":"Golden Rune [2] - 1x Castle Morne","desc":"Consumable. Found on a corpse partially hanging on a ledge at the top level of the castle. Beware the harpies nearby.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"3809","x":0.417010081,"y":0.887414949,"cat":"Crafting Materials","group":"Items","title":"Old Fang","desc":"Dropped at Castle Morne by one of the Misbegotten enemies, past the caged spirit.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"491","x":0.437912428,"y":0.888055872,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [2]","desc":"Upgrade Material. Found on a corpse, fallen with its chair at the beach. Guarded by 4 <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Spirit+Jellyfish'>Spirit Jellyfish</a>.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"6684","x":0.429704528,"y":0.888483156,"cat":"Crafting Materials","group":"Items","title":"Trina's Lily","desc":"Can be found at <a href='https://eldenring.wiki.fextralife.com/Castle+Morne' target=\"_blank\">Castle Morne</a> area nearby the cliff on the right","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-crafting.png?h=40"},{"id":"479","x":0.420641635,"y":0.888727318,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [1] - 3x Castle Morne","desc":"Upgrade Material. Found on a corpse in the left side at the back of <a target=\"_blank\" href='https://eldenring.wiki.fextralife.com/Castle+Morne'>Castle Morne</a>'s courtyard.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"740","x":0.418078,"y":0.890009168,"cat":"Consumables","group":"Items","title":"Pickled Turtle Neck - 1x Castle Morne","desc":"Consumable Item. Found on a corpse in a small room with a caged ghost. Beware of the Skeletal Slime that drops from the ceiling when you collect this.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"7008","x":0.419970927,"y":0.891229979,"cat":"Upgrade Materials","group":"Items","title":"Smithing Stone [2] C - Castle Morne","desc":"Upgrade Material. Inside a building known as the Rampart Gaol at the back of the castle. This is the same building where the <a href='https://eldenring.wiki.fextralife.com/Whip' target=\"_blank\">Whip</a> can be found and is first accessed by walking atop the western walls at the back of the castle from the \"Behind the Castle\" Site of Grace. There is a building to the left with a blue roof. Jump onto this roof and then down to the cliffs below. Follow the cliffs southeast until you return onto a section of the castle with a square opening. Descend into the opening by using the wooden beams below. The stone can be found on a corpse on one of these wooden beams.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-upgradematerial.png?h=40"},{"id":"738","x":0.422808985,"y":0.891596222,"cat":"Sites of Grace","group":"Locations","title":"Behind the Castle","desc":"Site of Grace found by taking the ladder at the back of the main courtyard to the top level. Follow the path ahead, past the harpies and then drop down the broken section of the wall on the right.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"739","x":0.41819985,"y":0.891962465,"cat":"Key Items","group":"Items","title":"Stonesword Key - Castle Morne","desc":"<a href='https://eldenring.wiki.fextralife.com/Stonesword+Key' target=\"_blank\">Stonesword Key</a>. Found on a corpse partially hanging from a wooden platform. The platform can be found by walking down west from the nearby Site of Grace and back onto a section of the castle. Look to the left edge.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-key.png?h=40"},{"id":"742","x":0.421282987,"y":0.893549518,"cat":"Sites of Grace","group":"Locations","title":"Beside the Rampart Gaol","desc":"Site of Grace found at the back of the castle, at the lower level.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"743","x":0.417885052,"y":0.895167093,"cat":"Weapons","group":"Equipment","title":"Whip","desc":"Whip. Found on a corpse inside the building known as the Rampart Gaol. This building is first accessed by walking atop the western wall of the castle. Look to the left for a building with a blue roof. Jump onto this roof and then jump down to the cliffs below. Follow the cliffs southeast until you return to a section of the castle with a big square opening. Descend into the opening by landing on the wooden beams. There is a corpse with a Smithing Stone [2] on one of the beams and there are several Rats and a Harpy at the ground level. The corpse with the whip is sitting against a wall.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-whip.png?h=40"},{"id":"3833","x":0.416645269,"y":0.897614827,"cat":"Consumables","group":"Items","title":"Throwing Dagger - 8x Castle Morne","desc":"Held by a corpse across the wooden bridge that's in front of Raumpart Gaol at Castle Morne.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-consumable.png?h=40"},{"id":"6055","x":0.413541974,"y":0.89874895,"cat":"Upgrade Materials","group":"Items","title":"Somber Smithing Stone [1]","desc":"Found at the edge of the sea.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-somber_smithing_stone.png?h=40"},{"id":"747","x":0.414812675,"y":0.903377039,"cat":"Weapons","group":"Equipment","title":"Grafted Blade Greatsword","desc":"Greatsword. Dropped by <a href='https://eldenring.wiki.fextralife.com/Leonine+Misbegoten' target=\"_blank\">Leonine Misbegotten</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-greatsword.png?h=40"},{"id":"749","x":0.414446528,"y":0.905330336,"cat":"Sites of Grace","group":"Locations","title":"Morne Moangrave","desc":"Site of Grace accessible after defeating the <a href='https://eldenring.wiki.fextralife.com/Leonine+Misbegotten' target=\"_blank\">Leonine Misbegotten</a> boss.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-grace.png?h=40"},{"id":"746","x":0.41779473,"y":0.906093344,"cat":"Bosses","group":"Characters","title":"Leonine Misbegotten","desc":"Optional Greater Enemy Boss. Can be found by heading southeast from the \"Beside the Rampart Gaol\" Site of Grace, through the wooden bridge and down a ladder onto the shores below. Drops the <a href='https://eldenring.wiki.fextralife.com/Grafted Blade Greatsword' target=\"_blank\">Grafted Blade Greatsword</a> upon defeat.","link":null,"icon":"https://static0.fextralifeimages.com/wordpress/wp-content/uploads/mapimages/Elden-Ring-miniboss.png?h=40"}]};